-- DROP PROCEDURE crmdm.prc_ads_acct_depo(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_acct_depo(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 存款账户日均余额表
  -- 存储过程编号：PRC_ADS_ACCT_DEPO_AVG
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：DWD_ACCT_DEPO(存款账户信息表)；DWS_CUST_ASSE_LIAB_CUMU(客户资产负债基数表)
  -- 目标表：ADS_ACCT_DEPO_AVG
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '存款账户日均余额表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_ACCT_DEPO_AVG';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_ACCT_DEPO';
  

  --***************************************
  -- 2.1 -- 第1段处理开始：存款销量
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：存款销量
  INSERT INTO ADS_ACCT_DEPO (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CUST_TYP,
      ACCT_ID,
      CARD_NO,
      PRDKT_ID,
      PRDKT_NAME,
      PRDKT_CATE_BIG,
      ACCT_TYP,
      CCY_CD,
      BAL,
      RMB_BAL,
      OPEN_ACCT_ORG,
      OPEN_DATE,
      RATE_INTRI,
      INTRI_BGN_DATE,
      EXPR_DATE,
      ACCT_CLOZ_DATE,
      ACCT_STATE,
      VCHR_TYP,
      CUNQ,
      FIX_CURNT_FLG,
      DEPO_BAL,
      CUNKZLEI,
      KAIHUQUD,
      OPEN_CARD_ORG,
      BAL_MTH_AVG_DAY,
      BAL_QRT_AVG_DAY,
      BAL_YR_AVG_DAY
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS CUST_ID              , -- 客户编号
         T1.CUST_NAME            AS CUST_NAME            , -- 客户名称
         T1.CUST_TYP             AS CUST_TYP             , -- 客户类型
         T1.ACCT_ID              AS ACCT_ID              , -- 账户
         T1.CARD_NO              AS CARD_NO              , -- 卡/折号
         T1.PRDKT_ID             AS PRDKT_ID             , -- 产品编号
         T1.PRDKT_NAME           AS PRDKT_NAME           , -- 产品名称
         T1.PRDKT_CATE_BIG       AS PRDKT_CATE_BIG       , -- 产品大类
         T1.ACCT_TYP             AS ACCT_TYP             , -- 账户类型
         T1.CCY_CD               AS CCY_CD               , -- 币种
         T1.BAL                  AS BAL                  , -- 余额
         T1.RMB_BAL              AS RMB_BAL              , -- 折人民币余额
         T1.OPEN_ACCT_ORG        AS OPEN_ACCT_ORG        , -- 归属机构
         T1.OPEN_DATE            AS OPEN_DATE            , -- 开户日期
         T1.RATE_INTRI           AS RATE_INTRI           , -- 利率
         T1.INTRI_BGN_DATE       AS INTRI_BGN_DATE       , -- 起息日期
         T1.EXPR_DATE            AS EXPR_DATE            , -- 到期日期
         T1.ACCT_CLOZ_DATE       AS ACCT_CLOZ_DATE       , -- 销户日期
         T1.ACCT_STATE           AS ACCT_STATE           , -- 账户状态
         T1.VCHR_TYP             AS VCHR_TYP             , -- 凭证类型
         T1.CUNQ                 AS CUNQ                 , -- 存期
         T1.FIX_CURNT_FLG        AS FIX_CURNT_FLG        , -- 定活标志
         T1.DEPO_BAL             AS DEPO_BAL             , -- 当日存款金额
         T1.CUNKZLEI             AS CUNKZLEI             , -- 存款种类
         T1.KAIHUQUD             AS KAIHUQUD             , -- 开户渠道
         T1.OPEN_CARD_ORG        AS OPEN_CARD_ORG        , -- 开卡机构
         CASE
             WHEN NVL(T2.MTH_DAYS, 0) = 0 THEN 0
             ELSE NVL(T2.MTH_BAL, 0) / T2.MTH_DAYS
         END AS BAL_MTH_AVG_DAY, -- 余额月日均
         CASE
             WHEN NVL(T2.QRT_DAYS, 0) = 0 THEN 0
             ELSE NVL(T2.QRT_BAL, 0) / T2.MTH_DAYS
         END AS BAL_QRT_AVG_DAY, -- 余额季日均
         CASE
             WHEN NVL(T2.YAR_DAYS, 0) = 0 THEN 0
             ELSE NVL(T2.YAR_BAL, 0) / T2.MTH_DAYS
         END AS BAL_YR_AVG_DAY -- 余额年日均
    FROM DWD_ACCT_DEPO T1 -- 存款账户信息表
    LEFT JOIN DWS_CUST_ASSE_LIAB_CUMU T2 -- 客户资产负债基数表
      ON T1.ACCT_ID = T2.ACCT_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T2.PRDKT_TYP = '1' AND T2.DATA_DATE='20260630';

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：存款销量';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_label_valid_cust(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_label_valid_cust(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_有效客户
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AE01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：
  -- 目标表：ADS_CUST_LABEL_AE01；TMP_ADS_CUST_LABEL_AE01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_有效客户';
  V_PRC_NAME             VARCHAR(60)  := 'PRC_ADS_CRM_R_CUST_LABEL_VALID_CUST';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_LAST_MONTH_START    VARCHAR(8);
  V_LAST_MONTH_END      VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;
 
  ------------------------------------------------------------------
  -- 1. 客户贷款逾期数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_VALID_CUST';
   INSERT INTO ADS_CUST_LABLE_VALID_CUST(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      CUST_ID   --客户号
   )
   SELECT A.PERSN_LEGAL_BK_CODE,  --法人行号
   		 A.CUST_ID
   FROM DWD_ACCT_DEPO A 
   INNER JOIN DWD_CUST_INDV_INFO B ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE
   WHERE A.ACCT_STATE <>'C' AND B.AGE<120
   GROUP BY A.PERSN_LEGAL_BK_CODE,A.CUST_ID;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签是否有效客户数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：对私客户标签表
  -- 处理周期: 日
  -- 过程描述: 生成对私客户的12个标签字段
  -- 来源表: DWD_CUST_INDV_INFO, DWD_TX_ASET, crmdm.mbk_cust_log_fee, crmdm.mbk_cust_info, crmdm.uepp_pay_order_info
  -- 目标表: ADS_CRM_R_CUST_LABLE
  -- 适配数据库: Kingbase Oracle 兼容模式

  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '对私客户标签表';
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE';
  V_LOG_MSG              VARCHAR(4000);
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;

BEGIN
  ------------------------------------------------------------------
  -- 1. 参数检查
  ------------------------------------------------------------------
  
  V_NO_ID := 'TMP1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CRM_R_CUST_LABLE';
  	INSERT INTO ADS_CRM_R_CUST_LABLE(
  		PERSN_LEGAL_BK_CODE , --法人行号
		CUST_ID , --核心客户号
		CUST_NAME , --客户名称
		CERT_TYP , --证件类型
		CERT_ID , --证件号码
		GEND , --性别
		AGE , --年龄
		NATION , --民族
		MARI_SITU , --婚姻状况
		PHONE_NO , --手机号码
		MAX_DEG_EDU , --最高学历
		OCCU_CLS , --职业分类
		HOST_CUST_MNGR_POST_ID , --主办客户经理职位编号
		HOST_CUST_MNGR_NAME , --主办客户经理名称
		HOST_CUST_MNGR_EMP_ID , --主办客户经理工号
		ORG_LEAD , --主办机构(归属机构)
		ORG_LEAD_PATH , --主办机构路径
		COSPSR_CUST_MNGR_POST_ID , --信贷客户经理职位编号
		COSPSR_CUST_MNGR_NAME , --信贷客户经理名称
		COSPSR_CUST_MNGR_EMP_ID , --信贷客户经理工号
		COSPSR_ORG , --信贷机构
		COSPSR_ORG_PATH , --信贷机构路径
		IS_NOT_INDIV_BIZ_ACCT , --是否一码付商户
		IS_NOT_MINOR_ENTER_MAIN , --是否小微企业主
		NEAR_YR_HF_AVG_MTH_INCOM , --近半年月均收入
		INDIV_ESTIM_YR_INCOM , --个人年收入
		FUND_ACUM_DEPO_NUM_BASE , --公积金缴存基数
		SOCIAL_WELF_PAY_NUM_BASE , --社保缴存基数
		IS_NOT_PURE_NEW_CUST , --纯新户开户标志
		IS_NOT_BK_SELF_EMP , --是否本行员工
		IS_NOT_SLEEP_ACCT , --是否睡眠户
		CUST_HRAKY , --客户层级
		CUST_LVL , --客户等级
		LIFE_CYC , --生命周期
		AUM , --AUM余额
		AUM_MTH_AVG , --AUM月日均
		AUM_QRT_AVG , --AUM季日均
		AUM_YR_AVG , --AUM年日均
		IS_NOT_DEPO , --是否持有存款产品
		DEPO_BAL , --存款余额
		DEPO_MTH_AVG , --存款月日均
		DEPO_QRT_AVG , --存款季日均
		DEPO_YR_AVG , --存款年日均
		DEPO_CURNT_DEPO_BAL , --活期存款余额
		DEPO_CURNT_DEPO_BAL_MTH_CURNT_AVG_DAY , --活期存款日均余额
		IS_NOT_HIST_FIXD_DEPO_FLAG , --是否历史持有定期存款产品
		IS_NOT_FIXD_DEPO , --是否持有定期存款产品
		FIX_DEPO_BAL , --定期存款余额
		FIX_DEPO_MTH_AVG , --定期存款月日均
		FIX_DEPO_QRT_AVG , --定期存款季日均
		FIX_DEPO_YR_AVG , --定期存款年日均
		IS_NOT_HIST_LUMPSUM_FIXD_FLAG , --是否历史持有整存整取定期存款
		IS_NOT_LUMPSUM_FIXD , --是否持有整存整取定期存款
		LUMPSUM_FIXD_DEPO_BAL , --整存整取定期存款余额
		IS_NOT_HIST_LEHUI_FLAG , --是否历史持有乐惠存产品
		IS_NOT_LEHUI , --是否持有乐惠存产品
		LEHUI_BAL , --乐惠存产品余额
		LEHUI_MTH_AVG_DAY , --乐惠存产品月日均余额
		RCNT_FIXD_DEPO_MATURE_DAYS , --最近一笔定期存款到期天数
		RCNT_FIXD_DEPO_MATURE_AMT , --最近一笔定期存款到期金额
		IS_NOT_HIST_LARGEDP_FLAG , --是否历史持有大额存单
		IS_NOT_LARGEDP , --是否持有大额存单
		LARGEDP_BAL , --大额存单余额
		LARGEDP_MTH_AVG_DAY , --大额存单月日均余额
		IS_NOT_FIN_CTRAKT , --是否理财签约
		IS_NOT_HIST_FIN_FLAG , --是否历史持有理财产品
		IS_NOT_FIN , --是否持有理财产品
		RCNT_FIN_MATURE_DAYS , --最近一笔理财到期天数
		RCNT_FIN_MATURE_AMT , --最近一笔理财到期金额
		FIN_AMT , --理财余额
		FIN_MTH_AVG , --理财月日均
		FIN_QRT_AVG , --理财季日均
		FIN_YR_AVG , --理财年日均
		IS_NOT_HIST_OPEN_FIN_FLAG , --是否历史持有开放式理财产品
		IS_NOT_OPEN_FIN , --是否持有开放式理财产品
		OPEN_FIN_BAL , --开放式理财产品余额
		OPEN_FIN_MTH_AVG_DAY , --开放式理财产品月日均余额
		IS_NOT_HIST_CLOSE_FIN_FLAG , --是否历史持有封闭式理财产品
		IS_NOT_CLOSE_FIN , --是否持有封闭式理财产品
		CLOSE_FIN_BAL , --封闭式理财产品余额
		CLOSE_FIN_MTH_AVG_DAY , --封闭式理财产品月日均余额
		IS_NOT_HIST_AGT_FIN_FLAG , --是否历史持有代销理财产品
		IS_NOT_AGT_FIN , --是否持有代销理财产品
		AGT_FIN_BAL , --代销理财产品余额
		AGT_FIN_MTH_AVG_DAY , --代销理财产品月日均余额
		IS_NOT_LOAN_CUST , --是否贷款客户
		IS_NOT_HIST_LOAN_FLAG , --是否历史贷款客户
		LOAN_BAL , --贷款余额
		IS_NOT_PAYROL_BK , --是否代发户
		IS_NOT_SALRY_PAYROL_BK , --是否代发工资客户
		BK_SALRY_AMT_MTH_LAST , --上月代发工资金额
		RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE , --最近一次代发工资日期
		PAYROL_BK_SALRY_AMT , --最近一次代发工资金额
		PAYROL_SALRY_TTL , --代发工资累计金额
		CONTI_PAYROL_BK_MTHS , --连续稳定代发工资月数
		DCARD_TYPE , --借记卡类型
		IS_NOT_BK_SELF_SSCARD , --是否我行社保卡
		IS_NOT_BK_SELF_CGZJ , --是否我行川工之家客户
		CGZJ_ACCT_WELF_BAL , --川工之家账户福利资金余额
		IS_NOT_SELF_REG_MBANK , --是否自助注册手机银行
		IS_NOT_KTER_CTRAKT_MBANK , --是否柜面签约手机银行
		NEAR_MTH_TX_CNT , --近1月累计交易笔数
		NEAR_MTH_TX_AMT , --近1月累计交易金额
		NEAR_MTH_MBANK_TX_CNT , --近1月手机银行累计交易笔数
		NEAR_MTH_MBANK_TX_AMT , --近1月手机银行累计交易金额
		NEAR_MTH_MBANK_TX_AMT_BK_OUTER , --近1月手机银行行外入账金额
		IS_NOT_SFZF , --是否签约三方支付
		NEAR_MTH_THIRD_PAY_OUT_CNT , --近1月第三方支付累计转出笔数
		NEAR_MTH_THIRD_PAY_OUT_AMT , --近1月第三方支付累计转出金额
