		NVL(D.IS_NOT_HIST_LARGEDP_FLAG,0) , --是否历史持有大额存单
		NVL(D.IS_NOT_LARGEDP,0) , --是否持有大额存单
		NVL(D.LARGEDP_BAL,0) , --大额存单余额
		NVL(D.LARGEDP_MTH_AVG_DAY,0) , --大额存单月日均余额
		NVL(E.IS_NOT_FIN_CTRAKT,0) , --是否理财签约
		NVL(D.IS_NOT_HIST_FIN_FLAG,0) , --是否历史持有理财产品
		NVL(D.IS_NOT_FIN,0) , --是否持有理财产品
		D.RCNT_FIN_MATURE_DAYS , --最近一笔理财到期天数
