		NVL(D.AGT_FIN_MTH_AVG_DAY,0) , --代销理财产品月日均余额
		NVL(D.IS_NOT_LOAN_CUST,0) , --是否贷款客户
		NVL(D.IS_NOT_HIST_LOAN_FLAG,0) , --是否历史贷款客户
