		B.RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE , --最近一次代发工资日期
		NVL(B.PAYROL_BK_SALRY_AMT,0) , --最近一次代发工资金额
		NVL(B.PAYROL_SALRY_TTL,0) , --代发工资累计金额
		NVL(B.CONTI_PAYROL_BK_MTHS,0) , --连续稳定代发工资月数
		B.DCARD_TYPE , --借记卡类型
		NVL(B.IS_NOT_BK_SELF_SSCARD,0) , --是否我行社保卡
