		NVL(B.CGZJ_ACCT_WELF_BAL,0) , --川工之家账户福利资金余额
		NVL(B.IS_NOT_SELF_REG_MBANK,0) , --是否自助注册手机银行
		NVL(B.IS_NOT_KTER_CTRAKT_MBANK,0) , --是否柜面签约手机银行
		NVL(B.NEAR_MTH_TX_CNT,0) , --近1月累计交易笔数
		NVL(B.NEAR_MTH_TX_AMT,0) , --近1月累计交易金额
		NVL(B.NEAR_MTH_MBANK_TX_CNT,0) , --近1月手机银行累计交易笔数
		NVL(B.NEAR_MTH_MBANK_TX_AMT,0) , --近1月手机银行累计交易金额
		NVL(B.NEAR_MTH_MBANK_TX_AMT_BK_OUTER,0) , --近1月手机银行行外入账金额
		NVL(B.IS_NOT_SFZF,0) , --是否签约三方支付
		NVL(B.NEAR_MTH_THIRD_PAY_OUT_CNT,0) , --近1月第三方支付累计转出笔数
		NVL(B.NEAR_MTH_THIRD_PAY_OUT_AMT,0) , --近1月第三方支付累计转出金额
