		NVL(D.INSUR_MTH_AVG,0) , --保险月日均
		NVL(D.INSUR_QRT_AVG,0) , --保险季日均
		NVL(D.INSUR_YR_AVG,0) , --保险年日均
		C.NEAR_3_MTH_MIN_BENEFIT_LVL , --近三个月最低权益等级
		C.NEAR_6_MTH_MIN_BENEFIT_LVL , --近六个月最低权益等级
		C.NEAR_9_MTH_MIN_BENEFIT_LVL , --近九个月最低权益等级
		C.NEAR_12_MTH_MIN_BENEFIT_LVL , --近十二个月最低权益等级
		NVL(C.IS_NOT_YR_FRST_LVL_UPG_CUST,0) , --是否当年首次等级升级客户
		C.FRST_UPG_CUST_UPG_LVL , --首次升级客户升级等级
		NVL(C.IS_NOT_YR_LVL_DWN_CUST,0) , --是否当年等级降级客户
		C.DWN_CUST_LVL_BF_AF , --降级客户降级前后等级
		NVL(C.IS_NOT_HIGH_WORTH_CRIT_CUST,0) , --是否为高净值临界客户
		NVL(C.IS_NOT_MBANK_BIND_CARD,0) , --是否登录手机银行并完成绑卡客户
		NVL(C.REG_LOGIN_BK_PHONE_CUST_DAYS,0) , --注册并登录手机银行客户的天数
		NVL(C.MTH_LOGIN_MBANK_CNT,0) , --当月登录手机银行次数
		NVL(C.IS_NOT_3RD_PAY_BIND_CARD_DONE,0) , --是否完成三方支付绑卡
		NVL(B.YR_CAMPUS_PAY_CNT,0) , --当年校园缴费笔数
		NVL(C.YR_HOT_ACTV_CNT,0) , --当年参与热门活动次数
		NVL(B.MTH_UTIL_PAY_TRAN_AMT,0) , --当月完成水电气缴费交易金额
		NVL(B.MTH_UTIL_PAY_TRAN_CNT,0) , --当月完成水电气缴费交易笔数
		C.TRAN_CHAN_PREF , --交易渠道偏好
		NVL(C.IS_NOT_WECHAT_TRAN_MTH_ACTIVE,0) , --是否为微信绑卡交易月活跃客户
		C.PRDKT_PREF , --储蓄产品偏好
		NVL(C.VERIFIED_BADGE,0) , --企微客户认证标志
		C.DEPO_TERM_PREF , --储蓄产品期限偏好
		NVL(C.IS_NOT_WB_LOAN,0) , --是否微粒贷客户
		NVL(C.IS_NOT_MT_LOAN,0) , --是否美团贷款客户
		C.ORG_PATH , --机构路径
		C.CONTR_AMT , --总合同额度
		B.DCARD_LVL , --借记卡等级
		C.FIN_RISK , --理财风评结果
		C.INSUR_RISK  --保险风评结果
 	FROM ADS_CRM_R_CUST_LABLE_01 A 
 	LEFT JOIN ADS_CRM_R_CUST_LABLE_02 B ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE
 	LEFT JOIN ADS_CRM_R_CUST_LABLE_03 C ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE
 	LEFT JOIN ADS_CUST_LABLE_PRDKT_HOLD D ON A.CUST_ID=D.CUST_ID AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE
 	LEFT JOIN TMP_ADS_CUST_LABLE_01 E ON A.CUST_ID=E.CUST_ID AND A.PERSN_LEGAL_BK_CODE=E.PERSN_LEGAL_BK_CODE
 	;
 	COMMIT ;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：多表LEFT JOIN汇聚写入对私客户标签表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE,
      V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
  );

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
        V_BGN_DATE, V_END_DATE, V_DURA_DATE,
        V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
    );

    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户标签整合01
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_01
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CRM_R_CUST_LABLE_01
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户标签整合01';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_01';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NEAR_1MTH  VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  ------------------------------------------------------------------
  -- 1. 客户标签整合
  ------------------------------------------------------------------
  
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABLE_01';
  INSERT INTO TMP_ADS_CUST_LABLE_01(
  		PERSN_LEGAL_BK_CODE , --法人行号
		CUST_ID , --核心客户号
  		IS_NOT_FIN_CTRAKT -- 是否签约理财
  )
  SELECT '9999',t0.ECIF_CUST_NO,'1' 
   FROM ECIF_T01_P_CUST_INFO T0                  -- 客户信息
   INNER JOIN ECIF_T02_A_CUST_SIGN_REL T1         -- 参与人与业务签约的关系
      ON T0.PARTY_ID = T1.PARTY_ID
   WHERE T1.SIGN_TYPE='212' -- 签约理财
   	AND T1.SIGN_STATE<>'2'
   	GROUP BY t0.ECIF_CUST_NO;
   	COMMIT;
  
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CRM_R_CUST_LABLE_01';
   INSERT INTO ADS_CRM_R_CUST_LABLE_01 (
   		PERSN_LEGAL_BK_CODE , --法人行号
		CUST_ID , --核心客户号
		CUST_NAME , --客户名称
		CERT_TYP , --证件类型
		CERT_ID , --证件号码
		GEND , --性别
		AGE , --年龄
		NATION , --民族
		MARI_SITU , --婚姻状况
		PHONE_NO , --手机号码
		MAX_DEG_EDU , --最高学历
		OCCU_CLS , --职业分类
		HOST_CUST_MNGR_POST_ID , --主办客户经理职位编号
		HOST_CUST_MNGR_NAME , --主办客户经理名称
		HOST_CUST_MNGR_EMP_ID , --主办客户经理工号
		ORG_LEAD , --主办机构(归属机构)
		ORG_LEAD_PATH , --主办机构路径
		COSPSR_CUST_MNGR_POST_ID , --信贷客户经理职位编号
		COSPSR_CUST_MNGR_NAME , --信贷客户经理名称
		COSPSR_CUST_MNGR_EMP_ID , --信贷客户经理工号
		COSPSR_ORG , --信贷机构
		COSPSR_ORG_PATH , --信贷机构路径
		IS_NOT_INDIV_BIZ_ACCT , --是否一码付商户
		IS_NOT_MINOR_ENTER_MAIN , --是否小微企业主
		-- NEAR_YR_HF_AVG_MTH_INCOM , --近半年月均收入
		-- INDIV_ESTIM_YR_INCOM , --个人年收入
		FUND_ACUM_DEPO_NUM_BASE , --公积金缴存基数
		SOCIAL_WELF_PAY_NUM_BASE , --社保缴存基数
		IS_NOT_PURE_NEW_CUST , --纯新户开户标志
		IS_NOT_BK_SELF_EMP , --是否本行员工
		IS_NOT_SLEEP_ACCT , --是否睡眠户
		CUST_HRAKY , --客户层级
		CUST_LVL , --客户等级
		LIFE_CYC  --生命周期
   )
   SELECT 
   		A.PERSN_LEGAL_BK_CODE , --法人行号
		A.AA01 AS CUST_ID , --核心客户号
		A.AA02 AS CUST_NAME , --客户名称
		A.AA11 AS CERT_TYP , --证件类型
		A.AA03 AS CERT_ID , --证件号码
		A.AA04 AS GEND , --性别
		A.AA05 AS AGE , --年龄
		A.AA06 AS NATION , --民族
		A.AA07 AS MARI_SITU , --婚姻状况
		A.AA08 AS PHONE_NO , --手机号码
		A.AA10 AS MAX_DEG_EDU , --最高学历
		A.AA09 AS OCCU_CLS , --职业分类
		B.HOST_CUST_MNGR_POST_ID , --主办客户经理职位编号
		B.HOST_CUST_MNGR_NAME , --主办客户经理名称
		B.HOST_CUST_MNGR_EMP_ID , --主办客户经理工号
		CASE WHEN B.ORG_LEAD IS NULL THEN i.org_id END ORG_LEAD , --主办机构(归属机构)
		CASE WHEN B.ORG_LEAD_PATH IS NULL THEN K.ORG_PATH END ORG_LEAD_PATH , --主办机构路径
		B.COSPSR_CUST_MNGR_POST_ID , --信贷客户经理职位编号
		B.COSPSR_CUST_MNGR_NAME , --信贷客户经理名称
		B.COSPSR_CUST_MNGR_EMP_ID , --信贷客户经理工号
		B.COSPSR_ORG , --信贷机构
		B.COSPSR_ORG_PATH , --信贷机构路径
		'' AS IS_NOT_INDIV_BIZ_ACCT , --是否一码付商户
		C.AB01 AS IS_NOT_MINOR_ENTER_MAIN , --是否小微企业主
		-- NEAR_YR_HF_AVG_MTH_INCOM , --近半年月均收入
		-- INDIV_ESTIM_YR_INCOM , --个人年收入
	    D.AC01 AS FUND_ACUM_DEPO_NUM_BASE , --公积金缴存基数
		E.AD01 AS SOCIAL_WELF_PAY_NUM_BASE , --社保缴存基数
		F.AF01 AS IS_NOT_PURE_NEW_CUST , --纯新户开户标志
		G.AG01 AS IS_NOT_BK_SELF_EMP , --是否本行员工
		CASE WHEN H.CUST_ID IS NOT NULL THEN 1 ELSE 0 END AS IS_NOT_SLEEP_ACCT , --是否睡眠户
		I.CUST_HRAKY AS CUST_HRAKY , --客户层级
		I.CUST_LVL AS CUST_LVL , --客户等级
		J.LIFE_CYCLE_STAGE AS LIFE_CYC  --生命周期
   FROM ADS_CUST_LABEL_AA01 A 
   LEFT JOIN DWS_CUST_MNGR_INFO B ON A.AA01=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AB01 C ON A.AA01=C.AA01 AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AC01 D ON A.AA01=D.AA01 AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AD01 E ON A.AA01=E.AA01 AND A.PERSN_LEGAL_BK_CODE=E.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AF01 F ON A.AA01=F.AA01 AND A.PERSN_LEGAL_BK_CODE=F.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AG01 G ON A.AA01=G.AA01 AND A.PERSN_LEGAL_BK_CODE=G.PERSN_LEGAL_BK_CODE
   LEFT JOIN DWS_CUST_DORMANT_ACCOUT H ON A.AA01=H.CUST_ID AND A.PERSN_LEGAL_BK_CODE=H.PERSN_LEGAL_BK_CODE
   LEFT JOIN DWS_CUST_LVL_INFO I ON A.AA01=I.CUST_ID AND A.PERSN_LEGAL_BK_CODE=I.PERSN_LEGAL_BK_CODE
   LEFT JOIN DWS_CUST_LIFE_CYCLE_STAGE J ON A.AA01=J.CUST_ID AND A.PERSN_LEGAL_BK_CODE=J.PERSN_LEGAL_BK_CODE AND J.DATA_DT=V_SYSDAT
   LEFT JOIN DWD_SYS_ORG K ON I.ORG_ID=K.ORG_ID
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签整合01数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_02(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_02(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户标签整合02
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_02
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CRM_R_CUST_LABLE_02
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户标签整合02';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_02';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NEAR_1MTH  VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  ------------------------------------------------------------------
  -- 1. 客户标签整合
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CRM_R_CUST_LABLE_02';
   INSERT INTO ADS_CRM_R_CUST_LABLE_02 (
   		PERSN_LEGAL_BK_CODE , --法人行号
		CUST_ID , --核心客户号
		NEAR_YR_HF_AVG_MTH_INCOM , --近半年月均收入
		INDIV_ESTIM_YR_INCOM , --个人年收入
		IS_NOT_PAYROL_BK , --是否代发户
		IS_NOT_SALRY_PAYROL_BK , --是否代发工资客户
		BK_SALRY_AMT_MTH_LAST , --上月代发工资金额
		RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE , --最近一次代发工资日期
		PAYROL_BK_SALRY_AMT , --最近一次代发工资金额
		PAYROL_SALRY_TTL , --代发工资累计金额
		CONTI_PAYROL_BK_MTHS , --连续稳定代发工资月数
		DCARD_TYPE , --借记卡类型
		DCARD_LVL , --借记卡等级
		IS_NOT_BK_SELF_SSCARD , --是否我行社保卡
		IS_NOT_BK_SELF_CGZJ , --是否我行川工之家客户
		CGZJ_ACCT_WELF_BAL , --川工之家账户福利资金余额
		IS_NOT_SELF_REG_MBANK , --是否自助注册手机银行
		IS_NOT_KTER_CTRAKT_MBANK , --是否柜面签约手机银行
		NEAR_MTH_TX_CNT , --近1月累计交易笔数
		NEAR_MTH_TX_AMT , --近1月累计交易金额
		NEAR_MTH_MBANK_TX_CNT , --近1月手机银行累计交易笔数
		NEAR_MTH_MBANK_TX_AMT , --近1月手机银行累计交易金额
		NEAR_MTH_MBANK_TX_AMT_BK_OUTER , --近1月手机银行行外入账金额
		IS_NOT_SFZF , --是否签约三方支付
		NEAR_MTH_THIRD_PAY_OUT_CNT , --近1月第三方支付累计转出笔数
		NEAR_MTH_THIRD_PAY_OUT_AMT , --近1月第三方支付累计转出金额
		IS_NOT_BILL_RSV_MINOR_MKNT , --是否收单商户小微商户
		IS_NOT_BILL_RSV_INDIV_MKNT , --是否收单商户个体商户
		BILL_RSV_MKNT_CNT_MTH_LAST , --收单商户上月交易笔数
		BILL_RSV_MKNT_AMT_MTH_LAST , --收单商户上月交易金额
		IS_NOT_BILL_RSV_VAL_MKNT , --是否收单价值商户
		IS_NOT_BK_SELF_FUND_PASS_BY_ACCT , --是否我行资金过路户
		IS_NOT_RGLAR_TRANS_BK_OTHER_SAMENAME , --是否向他行同名户规律转出
		MBANK_CONTI_LOGIN_DAYS , --连续登录手机银行天数
		IS_NOT_BK_PHONE_ACTV_CUST , --是否手机银行活跃客户
		IS_NOT_BK_SELF_LOAN_DUE_OVER_CUST , --行内贷款是否逾期
		NEAR_24MTH_OVERDUE_FLAG , --行内近24月内是否存在贷款逾期
		CRDT_DUE_OVER_CNT , --征信逾期次数
		EXIST_BADLOAN_REC,  --征信是否存在不良贷款记录
		YR_CAMPUS_PAY_CNT , --当年校园缴费笔数
		MTH_UTIL_PAY_TRAN_AMT , --当月完成水电气缴费交易金额
		MTH_UTIL_PAY_TRAN_CNT   --当月完成水电气缴费交易笔数
   )
   SELECT 
   		A.PERSN_LEGAL_BK_CODE , --法人行号
		A.CUST_ID , --核心客户号
		B.NEAR_YR_HF_AVG_MTH_INCOM , --近半年月均收入
	 	B.INDIV_ESTIM_YR_INCOM , --个人年收入
		Q.AE01 AS IS_NOT_PAYROL_BK , --是否代发户
		B.IS_NOT_SALRY_PAYROL_BK , --是否代发工资客户
		B.BK_SALRY_AMT_MTH_LAST , --上月代发工资金额
		C.RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE , --最近一次代发工资日期
		C.PAYROL_BK_SALRY_AMT , --最近一次代发工资金额
		B.PAYROL_SALRY_TTL , --代发工资累计金额
		D.CONTI_PAYROL_BK_MTHS , --连续稳定代发工资月数
		E.DCARD_TYPE , --借记卡类型
		E.DCARD_LVL , --借记卡等级
		E.IS_NOT_BK_SELF_SSCARD , --是否我行社保卡
		E.IS_NOT_BK_SELF_CGZJ , --是否我行川工之家客户
		E.CGZJ_ACCT_WELF_BAL , --川工之家账户福利资金余额
		F.QD01 IS_NOT_SELF_REG_MBANK , --是否自助注册手机银行
		G.QD02 IS_NOT_KTER_CTRAKT_MBANK , --是否柜面签约手机银行
		K.NEAR_MTH_TX_CNT , --近1月累计交易笔数
		K.NEAR_MTH_TX_AMT , --近1月累计交易金额
		H.QD03 AS NEAR_MTH_MBANK_TX_CNT , --近1月手机银行累计交易笔数
		H.QD04 AS NEAR_MTH_MBANK_TX_AMT , --近1月手机银行累计交易金额
		I.QD05 AS NEAR_MTH_MBANK_TX_AMT_BK_OUTER , --近1月手机银行行外入账金额
		J.QD09 AS IS_NOT_SFZF , --是否完成三方支付绑卡
		K.NEAR_MTH_THIRD_PAY_OUT_CNT , --近1月第三方支付累计转出笔数
		K.NEAR_MTH_THIRD_PAY_OUT_AMT , --近1月第三方支付累计转出金额
		L.IS_NOT_BILL_RSV_MINOR_MKNT , --是否收单商户小微商户
		L.IS_NOT_BILL_RSV_INDIV_MKNT , --是否收单商户个体商户
		K.BILL_RSV_MKNT_CNT_MTH_LAST , --收单商户上月交易笔数
		K.BILL_RSV_MKNT_AMT_MTH_LAST , --收单商户上月交易金额
		L.IS_NOT_BILL_RSV_VAL_MKNT , --是否收单价值商户
		M.IS_NOT_BK_SELF_FUND_PASS_BY_ACCT , --是否我行资金过路户
		K.IS_NOT_RGLAR_TRANS_BK_OTHER_SAMENAME , --是否向他行同名户规律转出
		N.QD12 AS MBANK_CONTI_LOGIN_DAYS , --连续登录手机银行天数
		O.QD13 AS IS_NOT_BK_PHONE_ACTV_CUST , --是否手机银行活跃客户
		P.IS_NOT_BK_SELF_LOAN_DUE_OVER_CUST , --行内贷款是否逾期
		P.NEAR_24MTH_OVERDUE_FLAG , --行内近24月内是否存在贷款逾期
		P.CRDT_DUE_OVER_CNT , --征信逾期次数
		P.EXIST_BADLOAN_REC,   --征信是否存在不良贷款记录
		K.YR_CAMPUS_PAY_CNT , --当年校园缴费笔数
		K.MTH_UTIL_PAY_TRAN_AMT , --当月完成水电气缴费交易金额
		K.MTH_UTIL_PAY_TRAN_CNT  --当月完成水电气缴费交易笔数
   FROM DWS_CUST_LVL_INFO A 
   LEFT JOIN ADS_CUST_LABLE_PAYROL_INFO01 B ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABLE_PAYROL_INFO02 C ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABLE_PAYROL_INFO03 D ON A.CUST_ID=D.CUST_ID AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABLE_CARD_INFO E ON A.CUST_ID=E.CUST_ID AND A.PERSN_LEGAL_BK_CODE=E.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD01 F ON A.CUST_ID=F.AA01 AND A.PERSN_LEGAL_BK_CODE=F.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD02 G ON A.CUST_ID=G.AA01 AND A.PERSN_LEGAL_BK_CODE=G.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD03 H ON A.CUST_ID=H.AA01 AND A.PERSN_LEGAL_BK_CODE=H.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD05 I ON A.CUST_ID=I.AA01 AND A.PERSN_LEGAL_BK_CODE=I.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD09 J ON A.CUST_ID=J.AA01 AND A.PERSN_LEGAL_BK_CODE=J.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CRM_R_CUST_LABLE_TX_INFO K ON A.CUST_ID=K.CUST_ID AND A.PERSN_LEGAL_BK_CODE=K.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABLE_BILL_INFO L ON A.CUST_ID=L.CUST_ID AND A.PERSN_LEGAL_BK_CODE=L.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABLE_PASS_INFO M ON A.CUST_ID=M.CUST_ID AND A.PERSN_LEGAL_BK_CODE=M.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD12 N ON A.CUST_ID=N.AA01 AND A.PERSN_LEGAL_BK_CODE=N.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD13 O ON A.CUST_ID=N.AA01 AND A.PERSN_LEGAL_BK_CODE=O.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABLE_OVERDUE_INFO P ON A.CUST_ID=P.CUST_ID AND A.PERSN_LEGAL_BK_CODE=P.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AE01 Q ON A.CUST_ID=Q.AA01 AND A.PERSN_LEGAL_BK_CODE=Q.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签整合01数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_03(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_03(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户标签整合03
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_03
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CRM_R_CUST_LABLE_03
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户标签整合03';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_03';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NEAR_1MTH  VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  ------------------------------------------------------------------
  -- 1. 客户标签整合
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CRM_R_CUST_LABLE_03';
   INSERT INTO ADS_CRM_R_CUST_LABLE_03 (
   		PERSN_LEGAL_BK_CODE , --法人行号
		CUST_ID , --核心客户号
		NEAR_3_MTH_MIN_BENEFIT_LVL , --近三个月最低权益等级
		NEAR_6_MTH_MIN_BENEFIT_LVL , --近六个月最低权益等级
		NEAR_9_MTH_MIN_BENEFIT_LVL , --近九个月最低权益等级
		NEAR_12_MTH_MIN_BENEFIT_LVL , --近十二个月最低权益等级
		IS_NOT_YR_FRST_LVL_UPG_CUST , --是否当年首次等级升级客户
		FRST_UPG_CUST_UPG_LVL , --首次升级客户升级等级
		IS_NOT_YR_LVL_DWN_CUST , --是否当年等级降级客户
		DWN_CUST_LVL_BF_AF , --降级客户降级前后等级
		IS_NOT_HIGH_WORTH_CRIT_CUST , --是否为高净值临界客户
		IS_NOT_MBANK_BIND_CARD , --是否登录手机银行并完成绑卡客户
		REG_LOGIN_BK_PHONE_CUST_DAYS , --注册并登录手机银行客户的天数
		MTH_LOGIN_MBANK_CNT , --当月登录手机银行次数
		IS_NOT_3RD_PAY_BIND_CARD_DONE , --是否完成三方支付绑卡
		YR_HOT_ACTV_CNT , --当年参与热门活动次数
		TRAN_CHAN_PREF , --交易渠道偏好
		IS_NOT_WECHAT_TRAN_MTH_ACTIVE , --是否为微信绑卡交易月活跃客户
		PRDKT_PREF , --储蓄产品偏好
		VERIFIED_BADGE , --企微客户认证标志
		DEPO_TERM_PREF , --储蓄产品期限偏好
		IS_NOT_WB_LOAN , --是否微粒贷客户
		IS_NOT_MT_LOAN , --是否美团贷款客户
		ORG_PATH , --机构路径
		CONTR_AMT , --总合同额度
		FIN_RISK , --理财风评结果
		INSUR_RISK  --保险风评结果
   )
   SELECT 
   		A.PERSN_LEGAL_BK_CODE , --法人行号
		A.CUST_ID , --核心客户号
		B.NEAR_3_MTH_MIN_BENEFIT_LVL , --近三个月最低权益等级
		B.NEAR_6_MTH_MIN_BENEFIT_LVL , --近六个月最低权益等级
		B.NEAR_9_MTH_MIN_BENEFIT_LVL , --近九个月最低权益等级
		B.NEAR_12_MTH_MIN_BENEFIT_LVL , --近十二个月最低权益等级
		B.IS_NOT_YR_FRST_LVL_UPG_CUST , --是否当年首次等级升级客户
		B.FRST_UPG_CUST_UPG_LVL , --首次升级客户升级等级
		B.IS_NOT_YR_LVL_DWN_CUST , --是否当年等级降级客户
		B.DWN_CUST_LVL_BF_AF , --降级客户降级前后等级
		B.IS_NOT_HIGH_WORTH_CRIT_CUST , --是否为高净值临界客户
		C.QD06 AS IS_NOT_MBANK_BIND_CARD , --是否登录手机银行并完成绑卡客户
		D.QD07 AS REG_LOGIN_BK_PHONE_CUST_DAYS , --注册并登录手机银行客户的天数
		E.QD08 AS MTH_LOGIN_MBANK_CNT , --当月登录手机银行次数
		F.QD09 AS IS_NOT_3RD_PAY_BIND_CARD_DONE , --是否完成三方支付绑卡
		G.QD10 AS YR_HOT_ACTV_CNT , --当年参与热门活动次数
		H.QD11 AS TRAN_CHAN_PREF , --交易渠道偏好
		I.QD14 AS IS_NOT_WECHAT_TRAN_MTH_ACTIVE , --是否为微信绑卡交易月活跃客户
		J.AH01 AS PRDKT_PREF , --储蓄产品偏好
		'' VERIFIED_BADGE , --企微客户认证标志
		K.AI01 AS DEPO_TERM_PREF , --储蓄产品期限偏好
		L.IS_NOT_WB_LOAN , --是否微粒贷客户
		L.IS_NOT_MT_LOAN , --是否美团贷款客户
		'' AS ORG_PATH , --机构路径
		O.CONTR_AMT , --总合同额度
		M.RISK_LVL AS FIN_RISK , --理财风评结果
		M.RISK_LVL AS INSUR_RISK  --保险风评结果
   FROM DWS_CUST_LVL_INFO A 
   LEFT JOIN ADS_CUST_LABLE_LVL_INFO B ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD06 C ON A.CUST_ID=C.AA01 AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD07 D ON A.CUST_ID=D.AA01 AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD08 E ON A.CUST_ID=E.AA01 AND A.PERSN_LEGAL_BK_CODE=E.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD09 F ON A.CUST_ID=F.AA01 AND A.PERSN_LEGAL_BK_CODE=F.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD10 G ON A.CUST_ID=G.AA01 AND A.PERSN_LEGAL_BK_CODE=G.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD11 H ON A.CUST_ID=H.AA01 AND A.PERSN_LEGAL_BK_CODE=H.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_QD14 I ON A.CUST_ID=I.AA01 AND A.PERSN_LEGAL_BK_CODE=I.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AH01 J ON A.CUST_ID=J.AA01 AND A.PERSN_LEGAL_BK_CODE=J.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABEL_AI01 k ON A.CUST_ID=k.AA01 AND A.PERSN_LEGAL_BK_CODE=k.PERSN_LEGAL_BK_CODE
   LEFT JOIN ADS_CUST_LABLE_WD_INFO L ON A.CUST_ID=L.CUST_ID AND A.PERSN_LEGAL_BK_CODE=L.PERSN_LEGAL_BK_CODE
   LEFT JOIN DWD_CUST_INDIV_RISK_INVST M ON A.CUST_ID=M.CUST_ID AND A.PERSN_LEGAL_BK_CODE=M.PERSN_LEGAL_BK_CODE AND M.INVEST_TYP='1'
   LEFT JOIN DWD_CUST_INDIV_RISK_INVST N ON A.CUST_ID=N.CUST_ID AND A.PERSN_LEGAL_BK_CODE=N.PERSN_LEGAL_BK_CODE AND N.INVEST_TYP='2'
   LEFT JOIN (
   		SELECT S.CUST_ID,S.PERSN_LEGAL_BK_CODE ,SUM(S.CRDT_TTL_LMT) CONTR_AMT
			FROM dwd_cust_indiv_crdt S 
			WHERE CRDT_STATUS IN ('EFFECTIVE','FREEZE')
			GROUP BY S.CUST_ID,S.PERSN_LEGAL_BK_CODE
   ) O ON A.CUST_ID=O.CUST_ID AND A.PERSN_LEGAL_BK_CODE=O.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签整合01数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_bill_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_bill_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-收单商户相关数据
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_BILL_INFO
  -- 处理周期: 每日
  -- 来源表: ADS_CUST_LABLE_PRDKT_HOLD UEPP_PAY_ORDER_INFO
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-收单商户相关数据';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_BILL_INFO';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NEAR_1MTH  VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_NEAR_1MTH := sys_fun_deal_date(V_SYSDAT,20);
  ------------------------------------------------------------------
  -- 1. 收单客户数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_BILL_INFO';
   WITH BILL_TX AS
   (SELECT CASE WHEN SUBSTR(UPO.ISSCODE, 1, 2) IN ('12', '15', '18')
              THEN SUBSTR(UPO.ISSCODE, 1, 2) || '00'
              ELSE '9999'
         END   AS PERSN_LEGAL_BK_CODE,
         UPM.CUST_NO  AS CUST_ID,
         COUNT(*)     AS MKT_CNT,
         SUM(ORDER_AMT) AS MKT_AMT
    FROM CRMDM.UEPP_PAY_ORDER_INFO UPO
    INNER JOIN UEPP_PAY_MCT_SETTLE_ACCOUNT UPM
      ON UPM.MCT_ID = UPO.MCT_ID
   	WHERE UPO.STATUS   = '02'                            -- 交易成功
     AND UPO.PAY_TIME >= to_char(to_date(V_NEAR_1MTH,'YYYY-MM-DD'),'YYYY-MM-DD')
   	GROUP BY CASE WHEN SUBSTR(UPO.ISSCODE, 1, 2) IN ('12', '15', '18')
                 THEN SUBSTR(UPO.ISSCODE, 1, 2) || '00'
                 ELSE '9999' END, CUST_NO
    ),
    BILL_INFO AS (
    	SELECT '9999' PERSN_LEGAL_BK_CODE, B.CUST_NO AS CUST_ID,MAX(CASE WHEN A.MCT_TYPE='personage' THEN '1' ELSE 0 END) GTGSH,
    			MAX(CASE WHEN A.MCT_TYPE='smallBusinesses' THEN '1' ELSE 0 END) XWSH
    	FROM UEPP_PAY_MCT_INFO A ,UEPP_PAY_MCT_SETTLE_ACCOUNT B 
    	WHERE A.MCT_ID=B.MCT_ID AND A.STATUS IN ('0','2')  AND B.STATUS IN ('0','2')
    	GROUP BY B.CUST_NO
    )
   INSERT INTO ADS_CUST_LABLE_BILL_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      IS_NOT_BILL_RSV_MINOR_MKNT, -- 是否收单商户小微商户
	  IS_NOT_BILL_RSV_INDIV_MKNT,  -- 是否收单商户个体商户
	  IS_NOT_BILL_RSV_VAL_MKNT   -- 是否收单价值商户
   )
   SELECT 
	  A.PERSN_LEGAL_BK_CODE, --法人行号
      V_SYSDAT DATA_DATE, --数据日期
      A.CUST_ID,   --客户号
      A.XWSH IS_NOT_BILL_RSV_MINOR_MKNT, -- 是否收单商户小微商户
	  A.GTGSH IS_NOT_BILL_RSV_INDIV_MKNT,  -- 是否收单商户个体商户
	  CASE WHEN (A.GTGSH='1' AND ((C.AUM_MTH_AVG>=50000 OR C.DEPO_CURNT_DEPO_BAL_MTH_CURNT_AVG_DAY>=25000) 
	  	AND (B.MKT_CNT>=10 AND B.MKT_AMT>=100))) THEN 1 
	  	WHEN (A.GTGSH='2' AND ((C.AUM_MTH_AVG>=20000 OR C.DEPO_CURNT_DEPO_BAL_MTH_CURNT_AVG_DAY>=10000) 
	  	AND (B.MKT_CNT>=10 AND B.MKT_AMT>=100))) THEN 1 
	  	ELSE 0 END IS_NOT_BILL_RSV_VAL_MKNT   -- 是否收单价值商户
   FROM BILL_INFO a
   	LEFT JOIN BILL_TX b ON a.CUST_ID=b.CUST_ID AND a.PERSN_LEGAL_BK_CODE=b.PERSN_LEGAL_BK_CODE
   	LEFT JOIN ADS_CUST_LABLE_PRDKT_HOLD C ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE
   	WHERE A.CUST_ID IS NOT NULL;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签收单客户数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_card_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_card_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户卡相关数据
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_CARD_INFO
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户卡相关数据';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_CARD_INFO';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_MONTH_END3  VARCHAR(8);
  V_MONTH_END6  VARCHAR(8);
  V_MONTH_END9  VARCHAR(8);
  V_MONTH_END12  VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  V_LAST_MONTH24 VARCHAR(10);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  ------------------------------------------------------------------
  -- 1. 客户借记卡数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_CARD_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABLE_CARD_INFO';
   INSERT INTO TMP_ADS_CUST_LABLE_CARD_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      DCARD_LVL, -- 借记卡等级
	  DCARD_TYPE,  -- 借记卡类型
	  IS_NOT_BK_SELF_SSCARD  , -- 是否我行社保卡
	  IS_NOT_BK_SELF_CGZJ, --是否我行川工之家客户
	  CGZJ_ACCT_WELF_BAL   -- 川工之家账户福利资金余额
   )
   SELECT CASE WHEN A.FAKAJIGO LIKE '12%' THEN '1200'
   			   WHEN A.FAKAJIGO LIKE '15%' THEN '1500'
   			   WHEN A.FAKAJIGO LIKE '18%' THEN '1800'
   			   ELSE '9999' END PERSN_LEGAL_BK_CODE,  --法人行号
   		V_SYSDAT,       --数据日期
   		A.KEHUHAOO,       --客户号
   		max(CASE
             WHEN VIPPTKBZ IN ('0','1') THEN '02'
             WHEN VIPPTKBZ = '2' THEN '03'
             WHEN VIPPTKBZ = '6' THEN '04'
             WHEN VIPPTKBZ = '8' THEN '05'
             ELSE '99' END) AS DCARD_LVL, -- 借记卡等级
	    max(CASE
             WHEN VIPPTKBZ IN ('0','1') THEN '02'
             WHEN VIPPTKBZ = '2' THEN '03'
             WHEN VIPPTKBZ = '6' THEN '04'
             WHEN VIPPTKBZ = '8' THEN '05'
             ELSE '99' END) AS DCARD_TYPE,  -- 借记卡类型
	         max(A.SBKBIAOZ) AS IS_NOT_BK_SELF_SSCARD  , -- 是否我行社保卡
	    '0' IS_NOT_BK_SELF_CGZJ, --是否我行川工之家客户
	     0 CGZJ_ACCT_WELF_BAL   -- 川工之家账户福利资金余额
   FROM CBS_KCDA_PZJCXX a 
	WHERE a.PZSYZTAI IN ('0','1','3','4','5','6','D','E','F','K','N','M','j','m','n','h','y')
   GROUP BY CASE WHEN A.FAKAJIGO LIKE '12%' THEN '1200'
   			   WHEN A.FAKAJIGO LIKE '15%' THEN '1500'
   			   WHEN A.FAKAJIGO LIKE '18%' THEN '1800'
   			   ELSE '9999' END,A.KEHUHAOO;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签客户借记卡数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2. 川工之家客户数据
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_CUST_LABLE_CARD_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      DCARD_LVL, -- 借记卡等级
	  DCARD_TYPE,  -- 借记卡类型
	  IS_NOT_BK_SELF_SSCARD  , -- 是否我行社保卡
	  IS_NOT_BK_SELF_CGZJ, --是否我行川工之家客户
	  CGZJ_ACCT_WELF_BAL   -- 川工之家账户福利资金余额
   )
   SELECT B.PERSN_LEGAL_BK_CODE,  --法人行号
   		V_SYSDAT,       --数据日期
   		B.CUST_ID,       --客户号
   		NULL AS DCARD_LVL, -- 借记卡等级
   		NULL AS DCARD_TYPE, -- 借记卡类型
	    '0' AS IS_NOT_BK_SELF_SSCARD  , -- 是否我行社保卡
	    '1' IS_NOT_BK_SELF_CGZJ, --是否我行川工之家客户
	     SUM(NVL(B.RMB_BAL,0)) CGZJ_ACCT_WELF_BAL   -- 川工之家账户福利资金余额
   FROM  DWD_ACCT_DEPO  B ,CBS_KDPA_KEHUZH C 
   WHERE B.CARD_NO =C.KEHUZHAO AND C.ZHHUFENL ='3' AND C.ZHHUZTAI !='C'
   GROUP BY B.PERSN_LEGAL_BK_CODE,B.CUST_ID;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步客户标签川工之家客户数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   ------------------------------------------------------------------
  -- 3. 汇总到结果表
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_CUST_LABLE_CARD_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      DCARD_LVL, -- 借记卡等级
	  DCARD_TYPE,  -- 借记卡类型
	  IS_NOT_BK_SELF_SSCARD  , -- 是否我行社保卡
	  IS_NOT_BK_SELF_CGZJ, --是否我行川工之家客户
	  CGZJ_ACCT_WELF_BAL   -- 川工之家账户福利资金余额
   )
   SELECT 
	  PERSN_LEGAL_BK_CODE, --法人行号
      V_SYSDAT, --数据日期
      CUST_ID,   --客户号
      max(DCARD_LVL), -- 借记卡等级
	  max(DCARD_TYPE),  -- 借记卡类型
	  max(IS_NOT_BK_SELF_SSCARD)  , -- 是否我行社保卡
	  max(IS_NOT_BK_SELF_CGZJ), --是否我行川工之家客户
	  max(CGZJ_ACCT_WELF_BAL)   -- 川工之家账户福利资金余额
   FROM  TMP_ADS_CUST_LABLE_CARD_INFO
   GROUP BY PERSN_LEGAL_BK_CODE,CUST_ID;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3步客户标签川工之家客户数据汇总到结果表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_overdue_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_overdue_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户贷款相关数据
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_OVERDUE_INFO
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户贷款相关数据';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_OVERDUE_INFO';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_MONTH_END3  VARCHAR(8);
  V_MONTH_END6  VARCHAR(8);
  V_MONTH_END9  VARCHAR(8);
  V_MONTH_END12  VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  V_LAST_MONTH24 VARCHAR(10);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_MONTH24 := to_char(to_date(crmdm.sys_fun_deal_date(V_SYSDAT,28),'YYYYMMDD'),'YYYY/MM/DD');
  ------------------------------------------------------------------
  -- 1. 客户贷款逾期数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_OVERDUE_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABLE_OVERDUE_INFO';
   INSERT INTO TMP_ADS_CUST_LABLE_OVERDUE_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      IS_NOT_BK_SELF_LOAN_DUE_OVER_CUST, -- 行内贷款是否逾期
	  NEAR_24MTH_OVERDUE_FLAG,  -- 行内近24月内是否存在贷款逾期
	  CRDT_DUE_OVER_CNT,  -- 最近一次征信报告逾期次数
	  EXIST_BADLOAN_REC  -- 最近一次征信是否存在不良贷款记录
   )
   SELECT A.PERSN_LEGAL_BK_CODE,  --法人行号
   		V_SYSDAT,       --数据日期
   		A.CUST_ID,       --数据日期
   		'1',             -- 行内贷款是否逾期
   		'0',             -- 行内近24月内是否存在贷款逾期
   		'0',             -- 最近一次征信报告逾期次数
   		'0'              -- 最近一次征信是否存在不良贷款记录
   FROM DWD_ACCT_LOAN A 
   WHERE A.OVER_DAYS>0
   GROUP BY A.PERSN_LEGAL_BK_CODE,A.CUST_ID;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签客户贷款逾期数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2. 客户24月内是否存在贷款逾期  口径：以客户维度进行统计,遍历客户近24个月所有贷款的还款计划表,若本金罚息>0 or 利息罚息>0,则“是”,否则“否”
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_CUST_LABLE_OVERDUE_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      IS_NOT_BK_SELF_LOAN_DUE_OVER_CUST, -- 行内贷款是否逾期
	  NEAR_24MTH_OVERDUE_FLAG,  -- 行内近24月内是否存在贷款逾期
	  CRDT_DUE_OVER_CNT,  -- 最近一次征信报告逾期次数
	  EXIST_BADLOAN_REC  -- 最近一次征信是否存在不良贷款记录
   )
   SELECT B.PERSN_LEGAL_BK_CODE,  --法人行号
   		V_SYSDAT,       --数据日期
   		B.CUST_ID,       --数据日期
   		'0',             -- 行内贷款是否逾期
   		'1',             -- 行内近24月内是否存在贷款逾期
   		'0',             -- 最近一次征信报告逾期次数
   		'0'              -- 最近一次征信是否存在不良贷款记录
   FROM CMS_ACCT_PAYMENT_SCHEDULE A,DWD_ACCT_LOAN B 
   WHERE  A.OBJECTNO = B.ACCT_ID AND A.OBJECTTYPE='jbo.acct.ACCT_LOAN'
   	AND A.PAYDATE>=V_LAST_MONTH24
   	AND (A.PAYPRINCIPALPENALTYAMT>0 OR A.PAYINTERESTPENALTYAMT>0)  
   	GROUP BY B.PERSN_LEGAL_BK_CODE,B.CUST_ID;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步客户标签客户24月内是否存在贷款逾期数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  
  ------------------------------------------------------------------
  -- 3. 最近一次征信报告逾期次数 
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

   INSERT INTO TMP_ADS_CUST_LABLE_OVERDUE_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      IS_NOT_BK_SELF_LOAN_DUE_OVER_CUST, -- 行内贷款是否逾期
	  NEAR_24MTH_OVERDUE_FLAG,  -- 行内近24月内是否存在贷款逾期
	  CRDT_DUE_OVER_CNT,  -- 最近一次征信报告逾期次数
	  EXIST_BADLOAN_REC  -- 最近一次征信是否存在不良贷款记录
   )
   SELECT A.PERSN_LEGAL_BK_CODE,  --法人行号
   		V_SYSDAT,       --数据日期
   		A.CUST_ID,       --数据日期
   		'0',             -- 行内贷款是否逾期
   		'0',             -- 行内近24月内是否存在贷款逾期
   		NVL(B.MAXDURATION,0),             -- 最近一次征信报告逾期次数
   		CASE WHEN B.YQJE>0 THEN '1' ELSE '0' END               -- 最近一次征信是否存在不良贷款记录
   FROM (
		SELECT A.REPORTNO,B.CUST_ID,B.PERSN_LEGAL_BK_CODE ,ROW_NUMBER() OVER(PARTITION BY CERT_ID ORDER BY A.QUERYTIME DESC ) RN 
			FROM EDZX_CRQ_REPORTBASEINFO A ,DWD_CUST_INDV_INFO B 
			WHERE A.CERTID=B.CERT_ID
		) A 
	LEFT JOIN (SELECT REPORTNO, MAX(MAXDURATION) MAXDURATION,MAX(HIGHESTOVERDUEAMOUNTPERMON) YQJE 
		FROM EDZX_ICR_PCO_OVERDUE A 
		GROUP BY REPORTNO) B ON A.REPORTNO=B.REPORTNO
	WHERE A.RN=1;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步客户标签客户最近一次征信报告逾期次数数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4. 汇总到结果表 
  ------------------------------------------------------------------
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

   INSERT INTO ADS_CUST_LABLE_OVERDUE_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      IS_NOT_BK_SELF_LOAN_DUE_OVER_CUST, -- 行内贷款是否逾期
	  NEAR_24MTH_OVERDUE_FLAG,  -- 行内近24月内是否存在贷款逾期
	  CRDT_DUE_OVER_CNT,  -- 最近一次征信报告逾期次数
	  EXIST_BADLOAN_REC  -- 最近一次征信是否存在不良贷款记录
   )
   SELECT 
	  PERSN_LEGAL_BK_CODE, --法人行号
      V_SYSDAT, --数据日期
      CUST_ID,   --客户号
      max(IS_NOT_BK_SELF_LOAN_DUE_OVER_CUST), -- 行内贷款是否逾期
	  max(NEAR_24MTH_OVERDUE_FLAG),  -- 行内近24月内是否存在贷款逾期
	  max(CRDT_DUE_OVER_CNT),  -- 最近一次征信报告逾期次数
	  max(EXIST_BADLOAN_REC)  -- 最近一次征信是否存在不良贷款记录
   FROM TMP_ADS_CUST_LABLE_OVERDUE_INFO
   GROUP BY PERSN_LEGAL_BK_CODE,CUST_ID;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4步客户标签汇总到结果表数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_pass_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_pass_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-资金过路户
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_PASS_INFO
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-资金过路户';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_PASS_INFO';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NEAR_MONTH1 VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_NEAR_MONTH1 := sys_fun_deal_date(V_SYSDAT ,20);
  ------------------------------------------------------------------
  -- 1. 转出资金及AUM月日均
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABLE_PASS_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_PASS_INFO';
  INSERT INTO TMP_ADS_CUST_LABLE_PASS_INFO(
  	  PERSN_LEGAL_BK_CODE,                 --法人行号
      DATA_DATE,                           --数据日期
      CUST_ID,                             --客户号
      AUM_MTH_AVG,                         -- AUM月日均
	  TX_OUT_AMT                          -- 转出金额
  )
  SELECT 
  	A.PERSN_LEGAL_BK_CODE,        --法人行号
  	V_SYSDAT,                     --数据日期
  	A.CUST_ID,                    --客户号
  	A.INDX_VALUE AS AUM_MTH_AVG,  -- AUM月日均
  	0 TX_OUT_AMT                  -- 转出金额
  FROM DWS_CUST_INDX_DATA A 
  WHERE A.INDX_TYP='AUM_MTH_AVG' AND DATA_DATE=V_SYSDAT;
  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签资金过路户数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   ------------------------------------------------------------------
  -- 2. 转出资金
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  INSERT INTO TMP_ADS_CUST_LABLE_PASS_INFO(
  	  PERSN_LEGAL_BK_CODE,                 --法人行号
      DATA_DATE,                           --数据日期
      CUST_ID,                             --客户号
      AUM_MTH_AVG,                         -- AUM月日均
	  TX_OUT_AMT                          -- 转出金额
  )
  SELECT 
  	  XX.PERSN_LEGAL_BK_CODE, --法人行号
  	  V_SYSDAT,              --数据日期
  	  XX.CUST_ID,            -- 客户号
  	  0 AUM_MTH_AVG,         -- AUM月日均
  	  SUM(MX.AMT) TX_OUT_AMT  -- 转出金额
      FROM DWD_TX_ASET MX
      LEFT JOIN DWD_ACCT_DEPO XX
        ON MX.ACCT_ID = XX.ACCT_ID
     WHERE MX.TX_DATE >= V_NEAR_MONTH1 --近一个月
       AND MX.TX_DATE <= V_SYSDAT
       AND MX.LOAN_FLG = '0' --转出
       AND MX.XIANZZBZ = '1' --1 代表转账 
       AND MX.TX_CHNL <> '990' --交易渠道不等‘990’
        AND MX.CHONGZBZ = '0' --要原始数据
     GROUP BY XX.PERSN_LEGAL_BK_CODE,XX.CUST_ID;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签客户近半年月均收入数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   ------------------------------------------------------------------
  -- 3. 计算是否我行资金过路户
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  INSERT INTO ADS_CUST_LABLE_PASS_INFO(
  	  PERSN_LEGAL_BK_CODE,                 --法人行号
      DATA_DATE,                           --数据日期
      CUST_ID,                             --客户号
      IS_NOT_BK_SELF_FUND_PASS_BY_ACCT     -- AUM月日均
  )
  SELECT 
  	  PERSN_LEGAL_BK_CODE,                 --法人行号
      V_SYSDAT,                           --数据日期
      CUST_ID,                             --客户号
      CASE WHEN sum(NVL(A.AUM_MTH_AVG,0))*100/decode(sum(NVL(A.TX_OUT_AMT,0)),0,1,sum(NVL(A.TX_OUT_AMT,0))) <10 
      		THEN '1' ELSE '0' END IS_NOT_BK_SELF_FUND_PASS_BY_ACCT     -- AUM月日均
  FROM TMP_ADS_CUST_LABLE_PASS_INFO A
  GROUP BY PERSN_LEGAL_BK_CODE,CUST_ID;
  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签客户近半年月均收入数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_payrol_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_payrol_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户代发相关数据
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_PAYROL_INFO
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户代发相关数据';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_PAYROL_INFO';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_MONTH_END6  VARCHAR(8);
  V_MONTH_END12  VARCHAR(8);
  V_MONTH_BEGIN	VARCHAR(8);
  V_MONTH_END	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_MONTH_END6 := sys_fun_deal_date(V_SYSDAT,21);
  V_MONTH_END12 := sys_fun_deal_date(V_SYSDAT,29);
  V_MONTH_BEGIN := sys_fun_deal_date(V_SYSDAT,15);
  V_MONTH_END := sys_fun_deal_date(V_SYSDAT,2);
  ------------------------------------------------------------------
  -- 1. 近半年月均收入数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_PAYROL_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABLE_PAYROL_INFO';
   INSERT INTO TMP_ADS_CUST_LABLE_CARD_INFO(
   	  PERSN_LEGAL_BK_CODE,                 --法人行号
      DATA_DATE,                           --数据日期
      CUST_ID,                             --客户号
      NEAR_YR_HF_AVG_MTH_INCOM,            -- 近半年月均收入
	  INDIV_ESTIM_YR_INCOM,                -- 个人年收入
	  IS_NOT_SALRY_PAYROL_BK,              -- 是否代发工资客户
	  BK_SALRY_AMT_MTH_LAST,               -- 上月代发工资金额
	  RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE,  -- 最近一次代发工资日期
	  PAYROL_BK_SALRY_AMT,                 -- 最近一次代发工资金额
	  PAYROL_SALRY_TTL                    -- 代发工资累计金额_6
   )
   SELECT CASE WHEN B.JIYIJGHO LIKE '12%' THEN '1200'
   			   WHEN B.JIYIJGHO LIKE '15%' THEN '1500'
   			   WHEN B.JIYIJGHO LIKE '18%' THEN '1800'
   			   ELSE '9999' END PERSN_LEGAL_BK_CODE,      --法人行号
   		V_SYSDAT,                                        --数据日期
   		C.KEHUHAOO,                                      --客户号
   		SUM(CASE WHEN A.CHLIRIQI > = V_MONTH_END6 THEN  B.ZHUANZJE ELSE 0 END) / 6  NEAR_YR_HF_AVG_MTH_INCOM,   -- 近半年月均收入
   		SUM(B.ZHUANZJE),                                 -- 个人年收入
   		MAX(CASE WHEN  A.CHLIRIQI > = V_MONTH_BEGIN THEN 1 ELSE 0 end),  -- 是否代发工资客户
   		SUM(CASE WHEN A.CHLIRIQI > = V_MONTH_END6 AND A.CHLIRIQI <= V_MONTH_END THEN  B.ZHUANZJE ELSE 0 END) BK_SALRY_AMT_MTH_LAST,   -- 上月代发工资金额
   		'' RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE,  -- 最近一次代发工资日期
	    0 PAYROL_BK_SALRY_AMT,                 -- 最近一次代发工资金额
	    SUM(CASE WHEN A.CHLIRIQI > = V_MONTH_END6 THEN  B.ZHUANZJE ELSE 0 END) PAYROL_SALRY_TTL  -- 代发工资累计金额_6
      FROM CBS_KIBB_PLDLYW A, CBS_KIBB_PLDLMX B, CBS_KDPA_KEHUZH C
     WHERE A.WEITUOHO = B.WEITUOHO
       AND B.KEHUZHAO = C.KEHUZHAO
       AND A.JIAOYIMA = '1600'
       AND A.XITONGBS IN ('1001', '2002', '3001')
       AND A.CHLIRIQI > = V_MONTH_END12
     GROUP BY CASE WHEN B.JIYIJGHO LIKE '12%' THEN '1200'
   			   WHEN B.JIYIJGHO LIKE '15%' THEN '1500'
   			   WHEN B.JIYIJGHO LIKE '18%' THEN '1800'
   			   ELSE '9999' END,C.KEHUHAOO;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签客户近半年月均收入数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

