-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_payrol_info02(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_payrol_info02(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户代发相关数据02
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_PAYROL_INFO02
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户代发相关数据02';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_PAYROL_INFO02';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_MONTH_END6  VARCHAR(8);
  V_MONTH_END12  VARCHAR(8);
  V_MONTH_BEGIN	VARCHAR(8);
  V_MONTH_END	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_MONTH_END6 := sys_fun_deal_date(V_SYSDAT,21);
  V_MONTH_END12 := sys_fun_deal_date(V_SYSDAT,29);
  V_MONTH_BEGIN := sys_fun_deal_date(V_SYSDAT,15);
  V_MONTH_END := sys_fun_deal_date(V_SYSDAT,2);
  ------------------------------------------------------------------
  -- 1. 近半年月均收入数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_PAYROL_INFO02';
    INSERT INTO ADS_CUST_LABLE_PAYROL_INFO02(
   	  PERSN_LEGAL_BK_CODE,                 --法人行号
      DATA_DATE,                           --数据日期
      CUST_ID,                             --客户号
	  RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE,  -- 最近一次代发工资日期
	  PAYROL_BK_SALRY_AMT                 -- 最近一次代发工资金额
   )
   SELECT 
   	  CASE WHEN JIYIJGHO LIKE '12%' THEN '1200'
   			   WHEN JIYIJGHO LIKE '15%' THEN '1500'
   			   WHEN JIYIJGHO LIKE '18%' THEN '1800'
   			   ELSE '9999' END PERSN_LEGAL_BK_CODE,                 --法人行号
      V_SYSDAT,                           --数据日期
      KEHUHAOO AS CUST_ID,                             --客户号
	  JIAOYIRQ AS RCNT_TIME_ONE_PAYROL_BK_SALRY_DATE,  -- 最近一次代发工资日期
	  ZHUANZJE AS PAYROL_BK_SALRY_AMT                -- 最近一次代发工资金额
      FROM (SELECT C.KEHUHAOO,
                   A.JIAOYIRQ,
                   B.ZHUANZJE,
                   B.JIYIJGHO,
                   ROW_NUMBER() OVER(PARTITION BY C.KEHUHAOO ORDER BY A.JIAOYIRQ DESC) ROW_NUMBER
              FROM CBS_KIBB_PLDLYW A, CBS_KIBB_PLDLMX B, CBS_KDPA_KEHUZH C
             WHERE A.WEITUOHO = B.WEITUOHO
               AND B.KEHUZHAO = C.KEHUZHAO
               AND A.CHLIRIQI > = V_MONTH_END12
               AND A.JIAOYIMA = '1600'
               AND A.XITONGBS IN ('1001', '2002', '3001')) K
     WHERE K.ROW_NUMBER = 1
     AND k.KEHUHAOO IS NOT null;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签客户近一次代发数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_payrol_info03(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_payrol_info03(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-客户代发相关数据03
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_PAYROL_INFO03
  -- 处理周期: 每日
  -- 来源表: 
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO03
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-客户代发相关数据03';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_PAYROL_INFO03';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_COUNT      NUMBER;
  V_MINDATE    VARCHAR2(8);
  V_NEXTDATE   VARCHAR2(8);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
BEGIN
  
  ------------------------------------------------------------------
  -- 1. 近半年月均收入数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
   EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_PAYROL_INFO03';
  --条件为变量的SQL处理
  SELECT COUNT(1) INTO V_COUNT FROM TMP2_ADS_CUST_LABLE_PAYROL_INFO03;
  --初始化数据
  --循环所有代发日期
  IF (V_COUNT = 0) THEN
    SELECT MIN(A.JIAOYIRQ)
      INTO V_MINDATE
      FROM CBS_KIBB_PLDLYW A
     WHERE A.JIAOYIMA = '1600'
       AND A.XITONGBS IN ('1001', '2002', '3001');
    V_NEXTDATE := TO_CHAR(ADD_MONTHS(TO_DATE(V_MINDATE, 'YYYYMMDD'), -1),
                          'YYYYMMDD');
    --V_MINDATE 20200904 CYC 获取代发工资最小月份-1 ,方便后边后边根据最大未代发计算连续代发
    WHILE (V_NEXTDATE <= V_SYSDAT) LOOP
      INSERT INTO TMP2_ADS_CUST_LABLE_PAYROL_INFO03 VALUES (V_NEXTDATE);
      COMMIT;
      V_NEXTDATE := TO_CHAR(TO_DATE(V_NEXTDATE, 'YYYYMMDD') + 1, 'YYYYMMDD');
    END LOOP;
    --保存所有代发月份
    EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP3_ADS_CUST_LABLE_PAYROL_INFO03';
    INSERT INTO TMP3_ADS_CUST_LABLE_PAYROL_INFO03
      SELECT SUBSTR(A.D_DATE, 1, 6)
        FROM TMP2_ADS_CUST_LABLE_PAYROL_INFO03 A
       GROUP BY SUBSTR(A.D_DATE, 1, 6);
    COMMIT;
    --初始化所有代发客户月份
    EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_CUST_LABLE_PAYROL_INFO03';
    INSERT INTO TMP1_ADS_CUST_LABLE_PAYROL_INFO03
      SELECT CASE WHEN B.JIYIJGHO LIKE '12%' THEN '1200'
   			   WHEN B.JIYIJGHO LIKE '15%' THEN '1500'
   			   WHEN B.JIYIJGHO LIKE '18%' THEN '1800'
   			   ELSE '9999' END PERSN_LEGAL_BK_CODE,      --法人行号
   			    C.KEHUHAOO,                              -- 客户号
   			    SUBSTR(A.JIAOYIRQ, 1, 6) NY              -- 年月
        FROM CBS_KIBB_PLDLYW A, CBS_KIBB_PLDLMX B, CBS_KDPA_KEHUZH C
       WHERE A.WEITUOHO = B.WEITUOHO
         AND B.KEHUZHAO = C.KEHUZHAO
         AND A.JIAOYIMA = '1600'
         AND A.XITONGBS IN ('1001', '2002', '3001')
       GROUP BY CASE WHEN B.JIYIJGHO LIKE '12%' THEN '1200'
   			   WHEN B.JIYIJGHO LIKE '15%' THEN '1500'
   			   WHEN B.JIYIJGHO LIKE '18%' THEN '1800'
   			   ELSE '9999' END,C.KEHUHAOO, SUBSTR(A.JIAOYIRQ, 1, 6);
    COMMIT;
     OUTCDE := 0;
	  V_END_DATE := SYSDATE;
	  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
	  V_LOG_MSG := '第1步初始化数据完成';
	  V_LOG_FLG := OUTCDE;
	  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
    
    ELSE
    DELETE FROM TMP3_ADS_CUST_LABLE_PAYROL_INFO03 A
     WHERE A.D_DATE = SUBSTR(V_SYSDAT, 1, 6);
    COMMIT;
    INSERT INTO TMP3_ADS_CUST_LABLE_PAYROL_INFO03 VALUES (SUBSTR(V_SYSDAT, 1, 6));
    COMMIT;
    DELETE FROM TMP1_ADS_CUST_LABLE_PAYROL_INFO03
     WHERE NY = SUBSTR(V_SYSDAT, 1, 6);
    COMMIT;
    INSERT INTO TMP1_ADS_CUST_LABLE_PAYROL_INFO03
      SELECT 
      		CASE WHEN B.JIYIJGHO LIKE '12%' THEN '1200'
   			   WHEN B.JIYIJGHO LIKE '15%' THEN '1500'
   			   WHEN B.JIYIJGHO LIKE '18%' THEN '1800'
   			   ELSE '9999' END PERSN_LEGAL_BK_CODE,      --法人行号
      		C.KEHUHAOO,                                  -- 客户号
      		SUBSTR(A.JIAOYIRQ, 1, 6) NY                  -- 年月
        FROM CBS_KIBB_PLDLYW A, CBS_KIBB_PLDLMX B, CBS_KDPA_KEHUZH C
       WHERE A.WEITUOHO = B.WEITUOHO
         AND B.KEHUZHAO = C.KEHUZHAO
         AND A.JIAOYIMA = '1600'
         AND A.XITONGBS IN ('1001', '2002', '3001')
         AND A.JIAOYIRQ >= SUBSTR(V_SYSDAT, 1, 6) || '01'
         AND A.JIAOYIRQ <= V_SYSDAT
       GROUP BY CASE WHEN B.JIYIJGHO LIKE '12%' THEN '1200'
   			   WHEN B.JIYIJGHO LIKE '15%' THEN '1500'
   			   WHEN B.JIYIJGHO LIKE '18%' THEN '1800'
   			   ELSE '9999' END,C.KEHUHAOO, SUBSTR(A.JIAOYIRQ, 1, 6);
    COMMIT;

     OUTCDE := 0;
	  V_END_DATE := SYSDATE;
	  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
	  V_LOG_MSG := '第1步当月数据完成';
	  V_LOG_FLG := OUTCDE;
	  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
  END IF;

  ------------------------------------------------------------------
  -- 2. 求最大未发代发月份
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
    --求最大未发代发月份
   EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP4_ADS_CUST_LABLE_PAYROL_INFO03';
    INSERT INTO TMP4_ADS_CUST_LABLE_PAYROL_INFO03
      SELECT PERSN_LEGAL_BK_CODE,CUST_ID, MAX(D_DATE) D_DATE
        FROM (SELECT B.PERSN_LEGAL_BK_CODE ,D_DATE, B.CUST_ID
                FROM  TMP3_ADS_CUST_LABLE_PAYROL_INFO03 A
                inner JOIN (SELECT PERSN_LEGAL_BK_CODE, CUST_ID
                            FROM TMP1_ADS_CUST_LABLE_PAYROL_INFO03 M GROUP BY PERSN_LEGAL_BK_CODE, CUST_ID) B
                  ON 1 = 1
                LEFT JOIN TMP1_ADS_CUST_LABLE_PAYROL_INFO03 C
                  ON B.CUST_ID || A.D_DATE = C.CUST_ID || C.NY AND B.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE
               WHERE C.NY IS NULL)
       GROUP BY PERSN_LEGAL_BK_CODE,CUST_ID;
       
     OUTCDE := 0;
	  V_END_DATE := SYSDATE;
	  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
	  V_LOG_MSG := '第2步最大未发代发月份完成';
	  V_LOG_FLG := OUTCDE;
	  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
	  
  ------------------------------------------------------------------
  -- 3. 连续代发月数
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
   EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_PAYROL_INFO03';
   
    INSERT INTO ADS_CUST_LABLE_PAYROL_INFO03(
	  PERSN_LEGAL_BK_CODE,                 --法人行号
      DATA_DATE,                           --数据日期
      CUST_ID,                             --客户号
      CONTI_PAYROL_BK_MTHS                -- 连续代发月数
    )
      SELECT
      	B.PERSN_LEGAL_BK_CODE,
      	V_SYSDAT,
      	B.CUST_ID,
             MONTHS_BETWEEN(TO_DATE(SUBSTR(V_SYSDAT, 1, 6) || '01',
                                    'YYYYMMDD'),
                            TO_DATE(B.D_DATE || '01', 'YYYYMMDD')) LXDFYS 
        FROM TMP4_ADS_CUST_LABLE_PAYROL_INFO03 B;
    COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步客户标签连续代发月数数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_prdkt_hold(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_prdkt_hold(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-产品相关数据
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_PRDKT_HOLD
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_ASSE_LIAB
  -- 目标表: ADS_CUST_LABLE_PRDKT_HOLD
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-产品相关数据';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_PRDKT_HOLD';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
BEGIN

  ------------------------------------------------------------------
  -- 1. 各产品余额
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

   EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_PRDKT_HOLD';
   EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_CUST_LABLE_PRDKT_HOLD';
   
   INSERT INTO TMP1_ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                 ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                  
		AUM                                   ,  --AUM余额                                                            
		IS_NOT_DEPO                           ,  --是否持有存款产品                          
		DEPO_BAL                              ,  --存款余额                                                            
		DEPO_CURNT_DEPO_BAL                   ,  --活期存款余额                              
		IS_NOT_FIXD_DEPO                      ,  --是否持有定期存款产品                      
		FIX_DEPO_BAL                          ,  --定期存款余额                              
		IS_NOT_LUMPSUM_FIXD                   ,  --是否持有整存整取定期存款                  
		LUMPSUM_FIXD_DEPO_BAL                 ,  --整存整取定期存款余额                      
		IS_NOT_LEHUI                          ,  --是否持有乐惠存产品                        
		LEHUI_BAL                             ,  --乐惠存产品余额                            
		IS_NOT_LARGEDP                        ,  --是否持有大额存单                          
		LARGEDP_BAL                           ,  --大额存单余额                              
		IS_NOT_FIN                            ,  --是否持有理财产品                          
		FIN_AMT                               ,  --理财余额                                                               
		IS_NOT_OPEN_FIN                       ,  --是否持有开放式理财产品                    
		OPEN_FIN_BAL                          ,  --开放式理财产品余额                        
		IS_NOT_CLOSE_FIN                      ,  --是否持有封闭式理财产品                    
		CLOSE_FIN_BAL                         ,  --封闭式理财产品余额                        
		IS_NOT_AGT_FIN                        ,  --是否持有代销理财产品                      
		AGT_FIN_BAL                           ,  --代销理财产品余额                          
		IS_NOT_INSUR                          ,  --是否持有保险产品                          
		INSUR_FRST_PREM_AMT                   ,  --保险产品首期保费                          
		IS_NOT_LOAN_CUST                      ,  --是否贷款客户                              
		LOAN_BAL                              ,  --贷款余额     
		INSUR_BAL								 -- 保险余额                             
   )
   SELECT                   
   		A.PERSN_LEGAL_BK_CODE                         ,  --法人行号                   
   		V_SYSDAT                                      ,  --数据日期                   
   		A.CUST_ID                                     ,  --客户编号                   
   		A.AUM_BAL       							  ,  --AUM余额                  
   		CASE WHEN A.DEPO_BAL>0 THEN 1 ELSE 0 end      ,  --是否持有存款产品           
   		A.DEPO_BAL                                    ,  --存款余额                   
   		A.DEPO_CURNT_DEPO_BAL                         ,  --活期存款余额               
   		CASE WHEN A.FIXD_DEPO_BAL>0 THEN 1 ELSE 0 end  ,  --是否持有定期存款产品       
   		A.FIXD_DEPO_BAL                                ,  --定期存款余额               
   		CASE WHEN B.BAL>0 THEN 1 ELSE 0 end           ,  --是否持有整存整取定期存款   
   		B.BAL                                          ,  --整存整取定期存款余额       
   		CASE WHEN A.LEHUI_BAL>0 THEN 1 ELSE 0 end      ,  --是否持有乐惠存产品         
   		A.LEHUI_BAL                                    ,  --乐惠存产品余额             
   		CASE WHEN A.LARGEDP_BAL>0 THEN 1 ELSE 0 end    ,  --是否持有大额存单           
   		A.LARGEDP_BAL                                  ,  --大额存单余额                     
   		CASE WHEN A.FIN_BAL>0 THEN 1 ELSE 0 end        ,  --是否持有理财产品           
   		A.FIN_BAL                                      ,  --理财余额                   
   		CASE WHEN (A.OPEN_AGEN_FIN_BAL+A.OPEN_SELF_FIN_BAL)>0 THEN 1 ELSE 0 end ,  --是否持有开放式理财产品     
   		A.OPEN_AGEN_FIN_BAL+A.OPEN_SELF_FIN_BAL        ,  --开放式理财产品余额         
   		CASE WHEN (A.CLOSE_AGEN_FIN_BAL+A.OPEN_SELF_FIN_BAL)>0 THEN 1 ELSE 0 END ,  --是否持有封闭式理财产品     
   		A.CLOSE_AGEN_FIN_BAL+A.OPEN_SELF_FIN_BAL       ,  --封闭式理财产品余额         
   		CASE WHEN (A.OPEN_AGEN_FIN_BAL+A.CLOSE_AGEN_FIN_BAL)>0 THEN 1 ELSE 0 end ,  --是否持有代销理财产品       
   		A.OPEN_AGEN_FIN_BAL+A.CLOSE_AGEN_FIN_BAL       ,  --代销理财产品余额           
   		CASE WHEN A.INSUR_BAL>0 THEN 1 ELSE 0 end      ,  --是否持有保险产品           
   		C.NEW_INSUR_AMT                                ,  --保险产品首期保费           
   		CASE WHEN A.LOAN_BAL>0 THEN 1 ELSE 0 end       ,  --是否贷款客户               
   		A.LOAN_BAL                                     ,  --贷款余额        
   		A.INSUR_BAL                                       --保险月
   FROM DWS_CUST_ASSE_LIAB a 
   LEFT JOIN (SELECT D.PERSN_LEGAL_BK_CODE,D.CUST_ID,SUM(D.BAL) BAL 
   		FROM DWD_ACCT_DEPO D 
   		WHERE D.ACCT_TYP='01' AND D.BAL>0
   		GROUP BY D.PERSN_LEGAL_BK_CODE,D.CUST_ID) B ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE
    LEFT JOIN (SELECT CUST_ID,PERSN_LEGAL_BK_CODE,SUM(NEW_INSUR_AMT) NEW_INSUR_AMT
    		FROM DWD_ACCT_INSUR GROUP BY CUST_ID,PERSN_LEGAL_BK_CODE) C ON  A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE
   WHERE a.bal_type ='1';
   COMMIT ;
    
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
	  
	  ------------------------------------------------------------------
  -- 2. 各产品日均余额
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

   INSERT INTO TMP1_ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                   ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                  
		AUM_MTH_AVG                           ,  --AUM月日均   
		AUM_QRT_AVG                           ,  --AUM季日均                                 
		AUM_YR_AVG                            ,  --AUM年日均                                                                                            
		DEPO_MTH_AVG                          ,  --存款月日均   
		DEPO_QRT_AVG                          ,  --存款季日均                                
		DEPO_YR_AVG                           ,  --存款年日均      
		DEPO_CURNT_DEPO_BAL_MTH_CURNT_AVG_DAY , -- 活期存款月日均                       
		FIX_DEPO_MTH_AVG                      ,  --定期存款月日均        
		FIX_DEPO_QRT_AVG                      ,  --定期存款季日均                            
		FIX_DEPO_YR_AVG                       ,  --定期存款年日均                    
		LEHUI_MTH_AVG_DAY                     ,  --乐惠存产品月日均余额                      
		LARGEDP_MTH_AVG_DAY                   ,  --大额存单月日均余额                        
		FIN_MTH_AVG                           ,  --理财月日均                                
		FIN_QRT_AVG                           ,  --理财季日均                                
		FIN_YR_AVG                            ,  --理财年日均                                
		OPEN_FIN_MTH_AVG_DAY                  ,  --开放式理财产品月日均余额                  
		CLOSE_FIN_MTH_AVG_DAY                 ,  --封闭式理财产品月日均余额                  
		AGT_FIN_MTH_AVG_DAY                   ,   --代销理财产品月日均余额    
		INSUR_MTH_AVG                         ,   --保险月日均余额    
		INSUR_QRT_AVG                         ,   --保险季日均余额    
		INSUR_YR_AVG                              --保险年日均余额    
                                
   )
   SELECT                   
   		A.PERSN_LEGAL_BK_CODE                    ,  --法人行号                   
   		V_SYSDAT                                 ,  --数据日期                   
   		A.CUST_ID                                ,  --客户编号                     
   		A.AUM_BAL 								 , --AUM月日均                    
   		0 										 , --AUM季日均                    
   		0 										 , --AUM年日均                    
   		A.DEPO_BAL 								 ,  --存款月日均                   
   		0 										 , --存款季日均                   
   		0 										 , --存款年日均   
   		A.DEPO_CURNT_DEPO_BAL                    , -- 活期存款月日均                
   		A.FIXD_DEPO_BAL 						 ,  --定期存款月日均               
   		0 										 , --定期存款季日均               
   		0 										 ,--定期存款年日均               
   		A.LEHUI_BAL   							 ,--乐惠存产品月日均余额         
   		A.LARGEDP_BAL   						 ,--大额存单月日均余额           
   		A.FIN_BAL   							 ,--理财月日均                   
   		0   									 ,--理财季日均                   
   		0   									 , --理财年日均                   
   		A.OPEN_AGEN_FIN_BAL+A.OPEN_SELF_FIN_BAL    ,  --开放式理财产品月日均余额     
   		A.CLOSE_AGEN_FIN_BAL+A.CLOSE_SELF_FIN_BAL ,  --封闭式理财产品月日均余额     
   		A.OPEN_AGEN_FIN_BAL+A.CLOSE_AGEN_FIN_BAL  ,    --代销理财产品月日均余额    
   		A.INSUR_BAL INSUR_MTH_AVG                  ,   --保险月日均余额    
		0 INSUR_QRT_AVG                            ,  --保险季日均余额    
		0 INSUR_YR_AVG                              --保险年日均余额              
   FROM DWS_CUST_ASSE_LIAB a 
   WHERE a.bal_type ='2'
   UNION ALL 
   SELECT                   
   		A.PERSN_LEGAL_BK_CODE                    ,  --法人行号                   
   		V_SYSDAT                                 ,  --数据日期                   
   		A.CUST_ID                                ,  --客户编号                     
   		0       								 , --AUM月日均                    
   		A.AUM_BAL    							 , --AUM季日均                       
   		0 										 , --AUM年日均                    
   		0       								 ,  --存款月日均                   
   		A.DEPO_BAL 								 , --存款季日均                   
   		0 										 , --存款年日均       
   		0                                        , -- 活期存款月日均             
   		0               						 ,  --定期存款月日均               
   		A.FIXD_DEPO_BAL 						 , --定期存款季日均               
   		0 										 ,--定期存款年日均               
   		0           							 ,--乐惠存产品月日均余额         
   		0               						 ,--大额存单月日均余额           
   		0           							 ,--理财月日均                   
   		A.FIN_BAL 								 ,--理财季日均                   
   		0   									 , --理财年日均                   
   		0                                        ,  --开放式理财产品月日均余额     
   		0                                        ,  --封闭式理财产品月日均余额     
   		0                                        ,  --代销理财产品月日均余额     
   		0 INSUR_MTH_AVG                          ,   --保险月日均余额    
		A.INSUR_BAL INSUR_QRT_AVG                ,  --保险季日均余额    
		0 INSUR_YR_AVG                              --保险年日均余额               
   FROM DWS_CUST_ASSE_LIAB a 
   WHERE a.bal_type ='3'
   UNION ALL 
   SELECT                   
   		A.PERSN_LEGAL_BK_CODE                    ,  --法人行号                   
   		V_SYSDAT                                 ,  --数据日期                   
   		A.CUST_ID                                ,  --客户编号                     
   		0       								 , --AUM月日均                    
   		0           							 , --AUM季日均                    
   		A.AUM_BAL   							 , --AUM年日均                    
   		0       								 ,  --存款月日均                   
   		0 		        						 , --存款季日均                   
   		A.DEPO_BAL 		     					 , --存款年日均   
   		0                                        , -- 活期存款月日均                     
   		0               						 ,  --定期存款月日均               
   		0               						 , --定期存款季日均               
   		A.FIXD_DEPO_BAL							 ,--定期存款年日均               
   		0           							 ,--乐惠存产品月日均余额         
   		0               						 ,--大额存单月日均余额           
   		0           							 ,--理财月日均                   
   		0            							 ,--理财季日均                   
   		A.FIN_BAL								 , --理财年日均                   
   		0                                        ,  --开放式理财产品月日均余额     
   		0                                        ,  --封闭式理财产品月日均余额     
   		0                                        ,   --代销理财产品月日均余额     
   		0 INSUR_MTH_AVG                          ,   --保险月日均余额    
		0 INSUR_QRT_AVG                          ,  --保险季日均余额    
		A.INSUR_BAL INSUR_YR_AVG                    --保险年日均余额             
   FROM DWS_CUST_ASSE_LIAB a 
   WHERE a.bal_type ='4';
   COMMIT ;
    
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步客户标签数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
    
  ------------------------------------------------------------------
  -- 3. 存款产品历史持有
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
	
   INSERT INTO TMP1_ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                   ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                                   
		IS_NOT_HIST_FIXD_DEPO_FLAG            ,  --是否历史持有定期存款产品                                       
		IS_NOT_HIST_LUMPSUM_FIXD_FLAG         ,  --是否历史持有整存整取定期存款                                       
		IS_NOT_HIST_LEHUI_FLAG                ,  --是否历史持有乐惠存产品                 
		IS_NOT_HIST_LARGEDP_FLAG                --是否历史持有大额存单                             
   )
   SELECT                   
   		A.PERSN_LEGAL_BK_CODE                         ,  --法人行号                   
   		V_SYSDAT                                      ,  --数据日期                   
   		A.CUST_ID                                     ,  --客户编号                   
   		CASE WHEN a.PRDKT_CATE_BIG !='01' AND a.bal=0 THEN '1' ELSE 0 END  IS_NOT_HIST_FIXD_DEPO_FLAG ,  --是否历史持有定期存款产品     
   		CASE WHEN a.ACCT_TYP='01' AND a.bal=0 THEN '1' ELSE 0 END  IS_NOT_HIST_LUMPSUM_FIXD_FLAG      ,  --是否历史持有整存整取定期存款  
   		CASE WHEN a.PRDKT_CATE_BIG='03' AND a.bal=0 THEN '1' ELSE 0 END  IS_NOT_HIST_LEHUI_FLAG      ,  --是否历史持有乐惠存产品  
   		CASE WHEN a.PRDKT_CATE_BIG='05' AND a.bal=0 THEN '1' ELSE 0 END  IS_NOT_HIST_LARGEDP_FLAG        --是否历史持有大额存单            
   FROM DWD_ACCT_DEPO a;
   COMMIT ;
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3步客户标签存款产品历史持有数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
	  
  ------------------------------------------------------------------
  -- 4. 理财产品历史持有
  ------------------------------------------------------------------
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;
	
   INSERT INTO TMP1_ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                   ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                                   
		IS_NOT_HIST_AGT_FIN_FLAG              ,  --是否历史持有代销理财产品                                       
		IS_NOT_HIST_CLOSE_FIN_FLAG            ,  --是否历史持有封闭式理财产品                                       
		IS_NOT_HIST_FIN_FLAG                  ,  --是否历史持有理财产品                 
		IS_NOT_HIST_OPEN_FIN_FLAG                 --是否历史持有开放式理财产品                             
   )
   SELECT                   
   		A.PERSN_LEGAL_BK_CODE                         ,  --法人行号                   
   		V_SYSDAT                                      ,  --数据日期                   
   		A.CUST_ID                                     ,  --客户编号                   
   		CASE WHEN a.PRDKT_CATE_BIG IN('1','2') AND a.FIN_AMT=0 THEN '1' ELSE 0 END  IS_NOT_HIST_AGT_FIN_FLAG ,  --是否历史持有代销理财产品     
   		CASE WHEN a.PRDKT_CATE_BIG IN('2','4') AND a.FIN_AMT=0 THEN '1' ELSE 0 END  IS_NOT_HIST_CLOSE_FIN_FLAG      ,  --是否历史持有封闭式理财产品  
   		CASE WHEN a.FIN_AMT=0 THEN '1' ELSE 0 END  IS_NOT_HIST_FIN_FLAG      ,  --是否历史持有理财产品  
   		CASE WHEN a.PRDKT_CATE_BIG IN('1','3') AND a.FIN_AMT=0 THEN '1' ELSE 0 END  IS_NOT_HIST_OPEN_FIN_FLAG        --是否历史持有开放式理财产品            
   FROM DWD_ACCT_FIN a;
   COMMIT ;
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4步客户标签理财产品历史持有数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
   
   ------------------------------------------------------------------
  -- 5. 贷款产品历史持有
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
	
   INSERT INTO TMP1_ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                   ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                                   
		IS_NOT_HIST_LOAN_FLAG                    --是否历史贷款客户                                                                 
   )
   SELECT                   
   		A.PERSN_LEGAL_BK_CODE                         ,  --法人行号                   
   		V_SYSDAT                                      ,  --数据日期                   
   		A.CUST_ID                                     ,  --客户编号                   
   		CASE WHEN a.BAL = 0 THEN '1' ELSE 0 END  IS_NOT_HIST_AGT_FIN_FLAG   --是否历史贷款客户     
   FROM DWD_ACCT_LOAN a;
   COMMIT ;
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步客户标签贷款产品历史持有数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
   ------------------------------------------------------------------
  -- 6. 理财产品最近到期
  ------------------------------------------------------------------
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;
	
   INSERT INTO TMP1_ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                   ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                                   
		RCNT_FIXD_DEPO_MATURE_DAYS            ,  --最近一笔定期存款到期天数                                       
		RCNT_FIXD_DEPO_MATURE_AMT               --最近一笔定期存款到期金额                                                                  
   )
   WITH FIXD_DEPO AS
     (SELECT A.PERSN_LEGAL_BK_CODE,  A.CUST_ID, MIN(A.EXPR_DATE) DOQIRIQI  --最近一笔乐惠存产品到期日期 
        FROM DWD_ACCT_DEPO    A
       WHERE A.PRDKT_CATE_BIG!='01'
         AND A.BAL>0
         AND A.EXPR_DATE >=V_SYSDAT
       GROUP BY A.PERSN_LEGAL_BK_CODE,  A.CUST_ID)
      SELECT 
      	A.PERSN_LEGAL_BK_CODE ,   --法人行号    
      	V_SYSDAT ,                --数据日期       
      	A.CUST_ID,                --客户编号
       MIN(TO_NUMBER(TO_DATE(B.DOQIRIQI, 'YYYY-MM-DD') -
                         TO_DATE(V_SYSDAT, 'YYYY-MM-DD'))) DOQITS,  --最近一笔定期存款到期天数  
       SUM(NVL(A.BAL,0)) BAL      --最近一笔定期存款到期金额   
      FROM DWD_ACCT_DEPO  A 
      INNER JOIN FIXD_DEPO B ON A.CUST_ID =B.CUST_ID AND A.PERSN_LEGAL_BK_CODE =B.PERSN_LEGAL_BK_CODE AND A.EXPR_DATE =B.DOQIRIQI
    GROUP BY  A.CUST_ID ,A.PERSN_LEGAL_BK_CODE;
    
   COMMIT ;
    
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6步客户标签存款产品最近到期数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
	  
  ------------------------------------------------------------------
  -- 7. 理财产品最近到期
  ------------------------------------------------------------------
  V_NO_ID := '7';
  V_BGN_DATE := SYSDATE;
	
   INSERT INTO TMP1_ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                   ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                                   
		RCNT_FIN_MATURE_DAYS                  ,  --最近一笔定期存款到期天数                                       
		RCNT_FIN_MATURE_AMT                      --最近一笔定期存款到期金额                                                                  
   )
   WITH FIN_DEPO AS
     (SELECT A.PERSN_LEGAL_BK_CODE,  A.CUST_ID, MIN(A.EXPR_DATE) DOQIRIQI  --最近一笔乐惠存产品到期日期 
        FROM DWD_ACCT_FIN    A
       WHERE A.FIN_AMT>0
         AND A.EXPR_DATE >=V_SYSDAT
       GROUP BY A.PERSN_LEGAL_BK_CODE,  A.CUST_ID)
      SELECT 
      	A.PERSN_LEGAL_BK_CODE ,   --法人行号    
      	V_SYSDAT ,                --数据日期       
      	A.CUST_ID,                --客户编号
       MIN(TO_NUMBER(TO_DATE(B.DOQIRIQI, 'YYYY-MM-DD') -
                         TO_DATE(V_SYSDAT, 'YYYY-MM-DD'))) DOQITS,  --最近一笔定期存款到期天数  
       SUM(NVL(A.FIN_AMT,0)) BAL      --最近一笔定期存款到期金额   
      FROM DWD_ACCT_FIN  A 
      INNER JOIN FIN_DEPO B ON A.CUST_ID =B.CUST_ID AND A.PERSN_LEGAL_BK_CODE =B.PERSN_LEGAL_BK_CODE AND A.EXPR_DATE =B.DOQIRIQI
    GROUP BY  A.CUST_ID ,A.PERSN_LEGAL_BK_CODE;
    
   COMMIT ;
    
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第7步客户标签理财产品最近到期数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
	  
	 
	  ------------------------------------------------------------------
  -- 8. 汇总插入到结果表
  ------------------------------------------------------------------
  V_NO_ID := '8';
  V_BGN_DATE := SYSDATE;
	
   INSERT INTO ADS_CUST_LABLE_PRDKT_HOLD(
   		PERSN_LEGAL_BK_CODE                   ,  --法人行号                                  
		DATA_DATE                             ,  --数据日期                                  
		CUST_ID                               ,  --客户编号                                  
		AUM                                   ,  --AUM余额                                   
		AUM_MTH_AVG                           ,  --AUM月日均                                 
		AUM_QRT_AVG                           ,  --AUM季日均                                 
		AUM_YR_AVG                            ,  --AUM年日均                                 
		IS_NOT_DEPO                           ,  --是否持有存款产品                          
		DEPO_BAL                              ,  --存款余额                                  
		DEPO_MTH_AVG                          ,  --存款月日均                                
		DEPO_QRT_AVG                          ,  --存款季日均                                
		DEPO_YR_AVG                           ,  --存款年日均                                
		DEPO_CURNT_DEPO_BAL                   ,  --活期存款余额                              
		DEPO_CURNT_DEPO_BAL_MTH_CURNT_AVG_DAY ,  --活期存款日均余额                          
		IS_NOT_HIST_FIXD_DEPO_FLAG            ,  --是否历史持有定期存款产品                  
		IS_NOT_FIXD_DEPO                      ,  --是否持有定期存款产品                      
		FIX_DEPO_BAL                          ,  --定期存款余额                              
		FIX_DEPO_MTH_AVG                      ,  --定期存款月日均                            
		FIX_DEPO_QRT_AVG                      ,  --定期存款季日均                            
		FIX_DEPO_YR_AVG                       ,  --定期存款年日均                            
		IS_NOT_HIST_LUMPSUM_FIXD_FLAG         ,  --是否历史持有整存整取定期存款              
		IS_NOT_LUMPSUM_FIXD                   ,  --是否持有整存整取定期存款                  
		LUMPSUM_FIXD_DEPO_BAL                 ,  --整存整取定期存款余额                      
		IS_NOT_HIST_LEHUI_FLAG                ,  --是否历史持有乐惠存产品                    
		IS_NOT_LEHUI                          ,  --是否持有乐惠存产品                        
		LEHUI_BAL                             ,  --乐惠存产品余额                            
		LEHUI_MTH_AVG_DAY                     ,  --乐惠存产品月日均余额                      
		RCNT_FIXD_DEPO_MATURE_DAYS            ,  --最近一笔定期存款到期天数                  
		RCNT_FIXD_DEPO_MATURE_AMT             ,  --最近一笔定期存款到期金额                  
		IS_NOT_HIST_LARGEDP_FLAG              ,  --是否历史持有大额存单                      
		IS_NOT_LARGEDP                        ,  --是否持有大额存单                          
		LARGEDP_BAL                           ,  --大额存单余额                              
		LARGEDP_MTH_AVG_DAY                   ,  --大额存单月日均余额                        
		IS_NOT_HIST_FIN_FLAG                  ,  --是否历史持有理财产品                      
		IS_NOT_FIN                            ,  --是否持有理财产品                          
		RCNT_FIN_MATURE_DAYS                  ,  --最近一笔理财到期天数                      
		RCNT_FIN_MATURE_AMT                   ,  --最近一笔理财到期金额                      
		FIN_AMT                               ,  --理财余额                                  
		FIN_MTH_AVG                           ,  --理财月日均                                
		FIN_QRT_AVG                           ,  --理财季日均                                
		FIN_YR_AVG                            ,  --理财年日均                                
		IS_NOT_HIST_OPEN_FIN_FLAG             ,  --是否历史持有开放式理财产品                
		IS_NOT_OPEN_FIN                       ,  --是否持有开放式理财产品                    
		OPEN_FIN_BAL                          ,  --开放式理财产品余额                        
		OPEN_FIN_MTH_AVG_DAY                  ,  --开放式理财产品月日均余额                  
		IS_NOT_HIST_CLOSE_FIN_FLAG            ,  --是否历史持有封闭式理财产品                
		IS_NOT_CLOSE_FIN                      ,  --是否持有封闭式理财产品                    
		CLOSE_FIN_BAL                         ,  --封闭式理财产品余额                        
		CLOSE_FIN_MTH_AVG_DAY                 ,  --封闭式理财产品月日均余额                  
		IS_NOT_HIST_AGT_FIN_FLAG              ,  --是否历史持有代销理财产品                  
		IS_NOT_AGT_FIN                        ,  --是否持有代销理财产品                      
		AGT_FIN_BAL                           ,  --代销理财产品余额                          
		AGT_FIN_MTH_AVG_DAY                   ,  --代销理财产品月日均余额                    
		IS_NOT_INSUR                          ,  --是否持有保险产品                          
		INSUR_FRST_PREM_AMT                   ,  --保险产品首期保费                          
		IS_NOT_LOAN_CUST                      ,  --是否贷款客户                              
		IS_NOT_HIST_LOAN_FLAG                 ,  --是否历史贷款客户                          
		LOAN_BAL                              ,   --贷款余额      
		INSUR_MTH_AVG                         ,   --保险月日均余额    
		INSUR_QRT_AVG                         ,   --保险季日均余额    
		INSUR_YR_AVG                              --保险年日均余额                                                                                      
   )
   SELECT 
   		PERSN_LEGAL_BK_CODE,                    --法人行号                         
		DATA_DATE,                              --数据日期                         
		CUST_ID,                                --客户编号                         
		SUM(NVL(AUM,0)),                                    --AUM余额                          
		SUM(NVL(AUM_MTH_AVG,0)),                            --AUM月日均                        
		SUM(NVL(AUM_QRT_AVG,0)),                            --AUM季日均                        
		SUM(NVL(AUM_YR_AVG,0)),                             --AUM年日均                        
		SUM(NVL(IS_NOT_DEPO,0)),                            --是否持有存款产品                 
		SUM(NVL(DEPO_BAL,0)),                               --存款余额                         
		SUM(NVL(DEPO_MTH_AVG,0)),                           --存款月日均                       
		SUM(NVL(DEPO_QRT_AVG,0)),                           --存款季日均                       
		SUM(NVL(DEPO_YR_AVG,0)),                            --存款年日均                       
		SUM(NVL(DEPO_CURNT_DEPO_BAL,0)),                    --活期存款余额                     
		SUM(NVL(DEPO_CURNT_DEPO_BAL_MTH_CURNT_AVG_DAY,0)),  --活期存款日均余额                 
		SUM(NVL(IS_NOT_HIST_FIXD_DEPO_FLAG,0)),             --是否历史持有定期存款产品         
		SUM(NVL(IS_NOT_FIXD_DEPO,0)),                       --是否持有定期存款产品             
		SUM(NVL(FIX_DEPO_BAL,0)),                           --定期存款余额                     
		SUM(NVL(FIX_DEPO_MTH_AVG,0)),                       --定期存款月日均                   
		SUM(NVL(FIX_DEPO_QRT_AVG,0)),                       --定期存款季日均                   
		SUM(NVL(FIX_DEPO_YR_AVG,0)),                        --定期存款年日均                   
		SUM(NVL(IS_NOT_HIST_LUMPSUM_FIXD_FLAG,0)),          --是否历史持有整存整取定期存款     
		SUM(NVL(IS_NOT_LUMPSUM_FIXD,0)),                    --是否持有整存整取定期存款         
		SUM(NVL(LUMPSUM_FIXD_DEPO_BAL,0)),                  --整存整取定期存款余额             
		SUM(NVL(IS_NOT_HIST_LEHUI_FLAG,0)),                 --是否历史持有乐惠存产品           
		SUM(NVL(IS_NOT_LEHUI,0)),                           --是否持有乐惠存产品               
		SUM(NVL(LEHUI_BAL,0)),                              --乐惠存产品余额                   
		SUM(NVL(LEHUI_MTH_AVG_DAY,0)),                      --乐惠存产品月日均余额             
		SUM(NVL(RCNT_FIXD_DEPO_MATURE_DAYS,0)),             --最近一笔定期存款到期天数         
		SUM(NVL(RCNT_FIXD_DEPO_MATURE_AMT,0)),              --最近一笔定期存款到期金额         
		SUM(NVL(IS_NOT_HIST_LARGEDP_FLAG,0)),               --是否历史持有大额存单             
		SUM(NVL(IS_NOT_LARGEDP,0)),                         --是否持有大额存单                 
		SUM(NVL(LARGEDP_BAL,0)),                            --大额存单余额                     
		SUM(NVL(LARGEDP_MTH_AVG_DAY,0)),                    --大额存单月日均余额               
		SUM(NVL(IS_NOT_HIST_FIN_FLAG,0)),                   --是否历史持有理财产品             
		SUM(NVL(IS_NOT_FIN,0)),                             --是否持有理财产品                 
		SUM(NVL(RCNT_FIN_MATURE_DAYS,0)),                   --最近一笔理财到期天数             
		SUM(NVL(RCNT_FIN_MATURE_AMT,0)),                    --最近一笔理财到期金额             
		SUM(NVL(FIN_AMT,0)),                                --理财余额                         
		SUM(NVL(FIN_MTH_AVG,0)),                            --理财月日均                       
		SUM(NVL(FIN_QRT_AVG,0)),                            --理财季日均                       
		SUM(NVL(FIN_YR_AVG,0)),                             --理财年日均                       
		SUM(NVL(IS_NOT_HIST_OPEN_FIN_FLAG,0)),              --是否历史持有开放式理财产品       
		SUM(NVL(IS_NOT_OPEN_FIN,0)),                        --是否持有开放式理财产品           
		SUM(NVL(OPEN_FIN_BAL,0)),                           --开放式理财产品余额               
		SUM(NVL(OPEN_FIN_MTH_AVG_DAY,0)),                   --开放式理财产品月日均余额         
		SUM(NVL(IS_NOT_HIST_CLOSE_FIN_FLAG,0)),             --是否历史持有封闭式理财产品       
		SUM(NVL(IS_NOT_CLOSE_FIN,0)),                       --是否持有封闭式理财产品           
		SUM(NVL(CLOSE_FIN_BAL,0)),                          --封闭式理财产品余额               
		SUM(NVL(CLOSE_FIN_MTH_AVG_DAY,0)),                  --封闭式理财产品月日均余额         
		SUM(NVL(IS_NOT_HIST_AGT_FIN_FLAG,0)),               --是否历史持有代销理财产品         
		SUM(NVL(IS_NOT_AGT_FIN,0)),                         --是否持有代销理财产品             
		SUM(NVL(AGT_FIN_BAL,0)),                            --代销理财产品余额                 
		SUM(NVL(AGT_FIN_MTH_AVG_DAY,0)),                    --代销理财产品月日均余额           
		SUM(NVL(IS_NOT_INSUR,0)),                           --是否持有保险产品                 
		SUM(NVL(INSUR_FRST_PREM_AMT,0)),                    --保险产品首期保费                 
		SUM(NVL(IS_NOT_LOAN_CUST,0)),                       --是否贷款客户                     
		SUM(NVL(IS_NOT_HIST_LOAN_FLAG,0)),                  --是否历史贷款客户                 
		SUM(NVL(LOAN_BAL,0)),                               --贷款余额    
		SUM(NVL(INSUR_MTH_AVG,0)),                          --保险月日均余额    
		SUM(NVL(INSUR_QRT_AVG,0)),                          --保险季日均余额    
		SUM(NVL(INSUR_YR_AVG,0))                              --保险年日均余额                           

   FROM 
	TMP1_ADS_CUST_LABLE_PRDKT_HOLD
	GROUP BY PERSN_LEGAL_BK_CODE,DATA_DATE,CUST_ID;
    
   COMMIT ;
    
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第7步客户标签理财产品最近到期数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_tx_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_tx_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：对私客户标签表
  -- 处理周期: 日
  -- 过程描述: 生成对私客户的12个标签字段
  -- 来源表: DWD_CUST_INDV_INFO, DWD_TX_ASET, crmdm.mbk_cust_log_fee, crmdm.mbk_cust_info, crmdm.uepp_pay_order_info
  -- 目标表: ADS_CRM_R_CUST_LABLE
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v1.4.0
  -- 变更记录:
  --   v1.4.0 2026-08-14 日期参数补充：新增sys_fun_deal_date code=30(6月前的前一天,近6月窗口滚动清理边界)
  --   v1.3.2 2026-08-04 F-01:修复TMP_02/TMP_03 SELECT列顺序与INSERT不一致导致PERSN_LEGAL_BK_CODE与CUST_ID交叉写入；
  --                        F-02:补充TMP_02/TMP_03近1月窗口上界TX_DATE<=V_SYSDAT；
  --                        F-03:删除V_END_DATE无效初始化；
  --                        F-04:确认DWD_TX_ASET.AMT字段存在(NUMBER(18,4)发生额),引用正确
  --   v1.3.1 2026-07-29 补充材料开发：BILL_RSV_MKNT_CNT_MTH_LAST+AMT_MTH_LAST(收单商户上月交易),源表uepp_pay_order_info
  --   v1.3.0 2026-07-29 架构重构：拆分6个独立临时表,每段独立INSERT,最终多表LEFT JOIN汇聚到目标表
  --   v1.2.1 2026-07-29 双键关联：所有源表关联统一使用CUST_ID+PERSN_LEGAL_BK_CODE作为计算单位
  --   v1.2.0 2026-07-29 补充材料开发：YR_CAMPUS_PAY_CNT(校园缴费)+MTH_UTIL_PAY_*(水电气缴费),源表mbk_cust_log_fee
  --   v1.1.0 2026-07-29 合规修复：日期参数改用sys_fun_deal_date(code=20/21),移除DATA_DATE,目标表改为全量快照
  --   v1.0.0 2026-07-28 初始版本：实现8个Y标记可直接开发字段
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '对私客户标签表';
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_TX_INFO';
  V_LOG_MSG              VARCHAR(4000);
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  V_ONE_MONTH_AGO        VARCHAR2(8);      -- code=20 1月前
  V_SIX_MONTH_AGO        VARCHAR2(8);      -- code=21 6月前
  V_SIX_MONTH_AGO_AGO    VARCHAR2(8);      -- code=30 6月前的前一天
  V_CURR_YEAR_BEGIN      VARCHAR2(8);      -- code=13 本年1月1日
  V_CURR_MONTH_BEGIN     VARCHAR2(8);      -- code=9  本月1日
  V_PREV_MONTH_BEGIN     VARCHAR2(8);      -- code=15 上月1日
  V_PREV_MONTH_END       VARCHAR2(8);      -- code=2  上月末

  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 1. 参数检查
  ------------------------------------------------------------------
  IF V_SYSDAT IS NULL
     OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')
  THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_ONE_MONTH_AGO        := sys_fun_deal_date(V_SYSDAT, 20);  -- 20:1月前
  V_SIX_MONTH_AGO        := sys_fun_deal_date(V_SYSDAT, 21);  -- 21:6月前
  V_SIX_MONTH_AGO_AGO    := sys_fun_deal_date(V_SYSDAT, 30);  -- 30:6月前的前一天
  V_CURR_YEAR_BEGIN      := sys_fun_deal_date(V_SYSDAT, 13);  -- 13:本年1月1日
  V_CURR_MONTH_BEGIN     := sys_fun_deal_date(V_SYSDAT, 9);   -- 9:本月1日
  V_PREV_MONTH_BEGIN     := sys_fun_deal_date(V_SYSDAT, 15);  -- 15:上月1日
  V_PREV_MONTH_END       := sys_fun_deal_date(V_SYSDAT, 2);   -- 2:上月末

  ------------------------------------------------------------------
  -- 2. TMP1：清理目标表和所有临时表(全量快照模式)
  ------------------------------------------------------------------
  V_NO_ID := 'TMP1';
  V_BGN_DATE := SYSDATE;

  TRUNC_TMP('ADS_CRM_R_CUST_LABLE');
  TRUNC_TMP('TMP_ADS_CRM_CUST_LABLE_01');
  TRUNC_TMP('TMP_ADS_CRM_CUST_LABLE_02');
  TRUNC_TMP('TMP_ADS_CRM_CUST_LABLE_03');
  TRUNC_TMP('TMP_ADS_CRM_CUST_LABLE_04');
  TRUNC_TMP('TMP_ADS_CRM_CUST_LABLE_05');
  TRUNC_TMP('TMP_ADS_CRM_CUST_LABLE_06');
  TRUNC_TMP('TMP_ADS_CRM_CUST_LABLE_07');
  COMMIT;

  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理目标表和7个临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE,
      V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 3. TMP2：各段独立建临时表
  ------------------------------------------------------------------
  V_NO_ID := 'TMP2';
  V_BGN_DATE := SYSDATE;

  -- 3.1 基础客户列表
  INSERT INTO TMP_ADS_CRM_CUST_LABLE_01 (
      PERSN_LEGAL_BK_CODE,
      CUST_ID
  )
  SELECT PERSN_LEGAL_BK_CODE,
         CUST_ID
    FROM DWD_CUST_INDV_INFO;

  -- 3.2 近1月交易汇总(主动动账：JIOYCFFS='0')
  INSERT INTO TMP_ADS_CRM_CUST_LABLE_02 (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      NEAR_MTH_TX_CNT,
      NEAR_MTH_TX_AMT
  )
  SELECT PERSN_LEGAL_BK_CODE,
         CUST_ID,
         COUNT(*)    AS TX_CNT,
         SUM(AMT)    AS TX_AMT
    FROM DWD_TX_ASET
   WHERE TX_DATE >= V_ONE_MONTH_AGO
     AND TX_DATE <= V_SYSDAT
     AND JIOYCFFS = '0'
     AND CHONGZBZ = '0' --要未冲正的数据
   GROUP BY PERSN_LEGAL_BK_CODE, CUST_ID;

  -- 3.3 近1月第三方支付交易(网联渠道)
  INSERT INTO TMP_ADS_CRM_CUST_LABLE_03 (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      NEAR_MTH_THIRD_PAY_OUT_CNT,
      NEAR_MTH_THIRD_PAY_OUT_AMT
  )
WITH txt AS (
    SELECT PYER_ACCT_NO AS card_no, SYS_DATE, TRX_AMT_D
    FROM ECPP_E_TXN_COLLECTION
    WHERE TRX_STATUS IN ('00','03')
      AND REPLACE(SYS_DATE,'_','') BETWEEN V_ONE_MONTH_AGO AND V_SYSDAT
    UNION ALL
    SELECT PYER_ACCT_NO_DE, SYS_DATE, TRX_AMT_D
    FROM ECPP_E_TXN_PAYMENT
    WHERE REPLACE(SYS_DATE,'_','') BETWEEN V_ONE_MONTH_AGO AND V_SYSDAT
)
SELECT B.PERSN_LEGAL_BK_CODE, B.CUST_ID,
       COUNT(1) AS txn_cnt,
       SUM(A.TRX_AMT_D) AS total_amt
FROM txt A
INNER JOIN (SELECT DISTINCT CUST_ID, CARD_NO, PERSN_LEGAL_BK_CODE FROM DWD_ACCT_DEPO) B
   ON A.card_no = B.CARD_NO
GROUP BY B.PERSN_LEGAL_BK_CODE, B.CUST_ID;

  -- 3.4 是否向他行同名户规律转出
  -- 口径：近半年每月至少向他行同名账户转账一笔

 --将每天数据导入中间表
 DELETE FROM TMP_ADS_CRM_CUST_LABLE_04_01 WHERE TX_DATE = V_SIX_MONTH_AGO_AGO; --删除6个月前的前一天数据
 
 INSERT INTO TMP_ADS_CRM_CUST_LABLE_04_01  (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      TX_DATE
)
   SELECT a.CUST_ID,
                a.PERSN_LEGAL_BK_CODE,
                a.TX_DATE
           FROM DWD_TX_ASET a
          WHERE a.TX_DATE = V_SYSDAT 
            AND a.LOAN_FLG = '0' --0借 1贷
            --交易对手行号不为本行机构号
            AND A.CHONGZBZ = '0'
            AND A.XIANZZBZ = '1'		--现转标志(0-现金,1-转账)
            AND INSTR(a.OPNT_ACCT_NAME_FST, A.CUST_NAME) > 0
            AND a.OPNT_BK_KEEP NOT IN (SELECT ORG_ID FROM DWD_SYS_ORG) --
          GROUP BY a.CUST_ID, a.PERSN_LEGAL_BK_CODE, a.TX_DATE;

--从中间表取近半年每月至少向他行同名账户转账一笔
   INSERT INTO TMP_ADS_CRM_CUST_LABLE_04 (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      IS_NOT_RGLAR_TRANS_BK_OTHER_SAMENAME
  )
  SELECT CUST_ID,
         PERSN_LEGAL_BK_CODE,
         CASE WHEN COUNT(DISTINCT SUBSTR(a.TX_DATE, 1, 6)) >= 6 THEN '1' ELSE '0' END AS RGLAR_FLAG
    FROM TMP_ADS_CRM_CUST_LABLE_04_01 m where TX_DATE >= V_SIX_MONTH_AGO
   GROUP BY CUST_ID, PERSN_LEGAL_BK_CODE;  
   
   

  -- 3.5 当年校园缴费笔数(tran_type='1', tran_status='1',cust_status = '1')
  INSERT INTO TMP_ADS_CRM_CUST_LABLE_05 (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      YR_CAMPUS_PAY_CNT
  )
  SELECT i.cust_core_no          AS CUST_ID,
         CASE WHEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2) IN ('12','15','18')
              THEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2)||'00'
              ELSE '9999' END    AS PERSN_LEGAL_BK_CODE,
         COUNT(*)        AS CAMPUS_CNT
    FROM crmdm.mbk_cust_log_fee f
    JOIN crmdm.mbk_cust_info    i
      ON i.cust_no = f.cust_no
   WHERE f.tran_type   = '1'
     AND f.tran_status = '1'
     AND I.cust_status = '1'
     AND f.tran_date  >= V_CURR_YEAR_BEGIN
   GROUP BY i.cust_core_no, 
   CASE WHEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2) IN ('12','15','18')
              THEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2)||'00'
              ELSE '9999' END;

  -- 3.6 当月水电气缴费交易金额+笔数(tran_type='0', tran_status='1',cust_status = '1')
  INSERT INTO TMP_ADS_CRM_CUST_LABLE_06 (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      MTH_UTIL_PAY_TRAN_AMT,
      MTH_UTIL_PAY_TRAN_CNT
  )
  SELECT i.cust_core_no             AS CUST_ID,
         CASE WHEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2) IN ('12','15','18')
              THEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2)||'00'
              ELSE '9999' END                AS PERSN_LEGAL_BK_CODE,
         SUM(TO_NUMBER(f.tran_amt)) AS UTIL_TRAN_AMT,
         COUNT(*)                   AS UTIL_TRAN_CNT
    FROM crmdm.mbk_cust_log_fee f
    JOIN crmdm.mbk_cust_info    i
      ON i.cust_no = f.cust_no
   WHERE f.tran_type   = '0'
     AND f.tran_status = '1'
     AND I.cust_status = '1'
     AND f.tran_date  >= V_CURR_MONTH_BEGIN
   GROUP BY i.cust_core_no, 
   CASE WHEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2) IN ('12','15','18')
              THEN SUBSTR(NVL(F.DEPT_ID,I.CUST_ORG_NO),1,2)||'00'
              ELSE '9999' END;

  -- 3.7 收单商户上月交易(uepp_pay_order_info: status='02',pay_time在上月范围内)
  -- isscode映射法人行号：前2位=12/15/18 → isscode||'00',其余 → '9999'
  INSERT INTO TMP_ADS_CRM_CUST_LABLE_07 (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      BILL_RSV_MKNT_CNT_MTH_LAST,
      BILL_RSV_MKNT_AMT_MTH_LAST
  )
  SELECT CASE WHEN SUBSTR(isscode, 1, 2) IN ('12', '15', '18')
              THEN SUBSTR(isscode, 1, 2) || '00'
              ELSE '9999'
         END          AS PERSN_LEGAL_BK_CODE,
         cust_no  AS CUST_ID,
         COUNT(*)     AS MKT_CNT,
         SUM(order_amt) AS MKT_AMT
    FROM crmdm.uepp_pay_order_info upo
    inner join crmdm.uepp_pay_mct_settle_account upm
      on upm.mct_id = upo.mct_id
   WHERE upo.status   = '02'                            -- 交易成功
     AND replace(SUBSTR(pay_time, 1, 10),'-','') >= V_PREV_MONTH_BEGIN
     AND replace(SUBSTR(pay_time, 1, 10),'-','') <= V_PREV_MONTH_END
   GROUP BY CASE WHEN SUBSTR(isscode, 1, 2) IN ('12', '15', '18')
                 THEN SUBSTR(isscode, 1, 2) || '00'
                 ELSE '9999'
            END,
            cust_no;

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP2 完成：7个临时表独立写入';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE,
      V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 4. 目标表写入：多表LEFT JOIN汇聚
  --    12个字段全部实现
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CRM_R_CUST_LABLE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      NEAR_MTH_TX_CNT,
      NEAR_MTH_TX_AMT,
      NEAR_MTH_THIRD_PAY_OUT_CNT,
      NEAR_MTH_THIRD_PAY_OUT_AMT,
      IS_NOT_RGLAR_TRANS_BK_OTHER_SAMENAME,
      BILL_RSV_MKNT_CNT_MTH_LAST,
      BILL_RSV_MKNT_AMT_MTH_LAST,
      YR_CAMPUS_PAY_CNT,
      MTH_UTIL_PAY_TRAN_AMT,
      MTH_UTIL_PAY_TRAN_CNT,
      KYC_COMPL_RATE
  )
  SELECT a.PERSN_LEGAL_BK_CODE,
         a.CUST_ID,
         NVL(b.NEAR_MTH_TX_CNT, 0),
         NVL(b.NEAR_MTH_TX_AMT, 0),
         NVL(c.NEAR_MTH_THIRD_PAY_OUT_CNT, 0),
         NVL(c.NEAR_MTH_THIRD_PAY_OUT_AMT, 0),
         NVL(d.IS_NOT_RGLAR_TRANS_BK_OTHER_SAMENAME, '0'),
         NVL(g.BILL_RSV_MKNT_CNT_MTH_LAST, 0),
         NVL(g.BILL_RSV_MKNT_AMT_MTH_LAST, 0),
         NVL(e.YR_CAMPUS_PAY_CNT, 0),
         NVL(f.MTH_UTIL_PAY_TRAN_AMT, 0),
         NVL(f.MTH_UTIL_PAY_TRAN_CNT, 0),
         NVL(h.KYC_COMPL_RATE, 0)
    FROM TMP_ADS_CRM_CUST_LABLE_01 a
    LEFT JOIN TMP_ADS_CRM_CUST_LABLE_02 b
           ON b.CUST_ID            = a.CUST_ID
          AND b.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
    LEFT JOIN TMP_ADS_CRM_CUST_LABLE_03 c
           ON c.CUST_ID            = a.CUST_ID
          AND c.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
    LEFT JOIN TMP_ADS_CRM_CUST_LABLE_04 d
           ON d.CUST_ID            = a.CUST_ID
          AND d.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
    LEFT JOIN TMP_ADS_CRM_CUST_LABLE_05 e
           ON e.CUST_ID            = a.CUST_ID
          AND e.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
    LEFT JOIN TMP_ADS_CRM_CUST_LABLE_06 f
           ON f.CUST_ID            = a.CUST_ID
          AND f.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
    LEFT JOIN TMP_ADS_CRM_CUST_LABLE_07 g
           ON g.CUST_ID            = a.CUST_ID
          AND g.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
    LEFT JOIN ADS_NEW_CUST_KYC h
           on h.CUST_ID            = a.CUST_ID
          AND h.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE;
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：多表LEFT JOIN汇聚写入对私客户标签表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE,
      V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
  );

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
        V_BGN_DATE, V_END_DATE, V_DURA_DATE,
        V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
    );

    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_ads_crm_r_cust_lable_wd_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_crm_r_cust_lable_wd_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户标签-微贷相关数据
  -- 作业编号: PRC_ADS_CRM_R_CUST_LABLE_BILL_INFO
  -- 处理周期: 每日
  -- 来源表: ADS_CUST_LABLE_PRDKT_HOLD UEPP_PAY_ORDER_INFO
  -- 目标表: ADS_CUST_LABLE_OVERDUE_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户标签-微贷相关数据';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CRM_R_CUST_LABLE_WD_INFO';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NEAR_1MTH  VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_NEAR_1MTH := sys_fun_deal_date(V_SYSDAT,20);
  ------------------------------------------------------------------
  -- 1. 网贷客户数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABLE_WD_INFO';
   
   WITH MT AS
   (SELECT B.MFCUSTOMERID AS CUST_ID,'1' BZ1,'0' BZ2
   	FROM CMS_NL_IND_INFO A,CMS_CUSTOMER_INFO B
   	WHERE A.CUSTOMERID=B.CUSTOMERID
   	GROUP BY B.MFCUSTOMERID 
	),
	WD AS (
		SELECT B.MFCUSTOMERID AS CUST_ID,'0' BZ1,'1' BZ2
   		FROM CMS_WD_CUSTOMER_INFO A,CMS_CUSTOMER_INFO B
   		WHERE A.CUSTOMERID=B.CUSTOMERID
   		GROUP BY B.MFCUSTOMERID 
	),
	MG_ALL AS (
		SELECT CUST_ID,max(BZ1) BZ1,MAX(BZ2) BZ2
		FROM (
			SELECT CUST_ID,BZ1,BZ2 FROM MT
			UNION ALL
			SELECT CUST_ID,BZ1,BZ2 FROM WD
		)
		GROUP BY CUST_ID 
	)
   INSERT INTO ADS_CUST_LABLE_WD_INFO(
   	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      IS_NOT_WB_LOAN, -- 是否微粒贷客户
	  IS_NOT_MT_LOAN  -- 是否美团贷款客户
   )
   SELECT 
	  '9999' PERSN_LEGAL_BK_CODE, --法人行号
      V_SYSDAT DATA_DATE, --数据日期
      CUST_ID,   --客户号
      BZ2 IS_NOT_WB_LOAN, -- 是否微粒贷客户
	  BZ1 IS_NOT_MT_LOAN  -- 是否美团贷款客户
   FROM MG_ALL
   WHERE CUST_ID IS NOT NULL 
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户标签微贷客户数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_capital_rmnd(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_capital_rmnd(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 大额动账提醒表
  -- 存储过程编号：PRC_ADS_CUST_CAPITAL_RMND
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：CRM_SYS_POST(职位表)；DWD_CUST_MAN(信贷管户关系表)；DWD_TX_ASET(资产交易信息表)；DWS_CUST_LVL_INFO(客户等级信息表)
  -- 目标表：ADS_CUST_CAPITAL_RMND
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '大额动账提醒表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_CAPITAL_RMND';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_DEAD_LINE_DAYS      NUMBER;
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  SELECT TO_NUMBER(PARAM_VAL)
    INTO V_DEAD_LINE_DAYS
    FROM CRM.SYS_PARAM_CONFIG
   WHERE PARAM_ID = 'minCapitalBal';


  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  DELETE FROM ADS_CUST_CAPITAL_RMND WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：大额动账提醒表
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：大额动账提醒表
  INSERT INTO ADS_CUST_CAPITAL_RMND (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      RMND_ID,
      MNGR_POST_ID,
      MNGR_NAME,
      CUST_ID,
      CUST_TYP,
      CUST_NAME,
      ACCT_NO,
      HAPN_BAL,
      ORG_ID,
      PHONE_NO,
      HDLE_STATE,
      DC_FLAG,
      RMND_TIME,
      TX_CHNL,
      OPNT_BK_KEEP,
      OPNT_NAME,
      HDLE_TIME,
      REMARK,
      RMND_INF,
      CUST_HRAKY
  )
  SELECT
         V_SYSDAT                       AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         SEQ_ADS_CUST_CAPITAL_RMND.NEXTVAL  AS RMND_ID              , -- 提醒ID
         T2.MNGR_POST_ID                AS MNGR_POST_ID         , -- 客户经理编号
         T3.USR_NAME                    AS MNGR_NAME            , -- 客户经理名称
         T1.CUST_ID                     AS CUST_ID              , -- 客户编号
         '1'                            AS CUST_TYP             , -- 客户类型
         T1.CUST_NAME                   AS CUST_NAME            , -- 客户名称
         T1.ACCT_ID                     AS ACCT_NO              , -- 账号
         T1.AMT                         AS HAPN_BAL             , -- 发生金额
         T4.ORG_ID                      AS ORG_ID               , -- 机构ID
         ''                             AS PHONE_NO             , -- 手机号
         '0'                            AS HDLE_STATE           , -- 处理状态(0未浏览,1已浏览)
         T1.LOAN_FLG                    AS DC_FLAG              , -- 借贷标志
         CASE WHEN LENGTH(T1.TX_TIME) = 9 THEN SUBSTR(T1.TX_TIME,1,2)||':'||SUBSTR(T1.TX_TIME,3,2)|| ':'||SUBSTR(T1.TX_TIME,5,2)
          ELSE '0'||SUBSTR(T1.TX_TIME,1,1)||':'||SUBSTR(T1.TX_TIME,2,2)|| ':'||SUBSTR(T1.TX_TIME,4,2) END AS RMND_TIME            , -- 发生时间
         T1.TX_CHNL                     AS TX_CHNL              , -- 交易渠道
         T1.OPNT_BK_KEEP                AS OPNT_BK_KEEP         , -- 对手行
         T1.OPNT_ACCT_NAME_FST          AS OPNT_NAME            , -- 对手姓名
         ''                             AS HDLE_TIME            , -- 处理时间
         ''                             AS REMARK               , -- 备注
         ''                             AS RMND_INF             , -- 提醒内容
         T4.CUST_HRAKY                  AS CUST_HRAKY            -- 客户层级
    FROM DWD_TX_ASET T1 -- 资产交易信息表
    LEFT JOIN DWD_CUST_MAN T2 -- 信贷管户关系表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T2.MNG_TYP = '1'
    LEFT JOIN CRM_SYS_POST T3 -- 职位表
      ON T2.MNGR_POST_ID = T3.POST_ID
    LEFT JOIN DWS_CUST_LVL_INFO T4 -- 客户等级信息表
      ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
   WHERE T1.DATA_DATE = V_SYSDAT AND T1.AMT >= V_DEAD_LINE_DAYS;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：大额动账提醒表';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_care_rmnd(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_care_rmnd(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户关怀提醒表
  -- 存储过程编号：PRC_ADS_CUST_CARE_RMND
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：CRM_SYS_POST(职位表)；DWD_CUST_INDV_INFO(客户基本信息表)；DWD_CUST_MAN(信贷管户关系表)；DWS_CUST_LVL_INFO(客户等级信息表)
  -- 目标表：ADS_CUST_CARE_RMND
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户关怀提醒表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_CARE_RMND';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_DEAD_LINE_DAYS      NUMBER;
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  SELECT TO_NUMBER(PARAM_VAL)
    INTO V_DEAD_LINE_DAYS
    FROM CRM.SYS_PARAM_CONFIG
   WHERE PARAM_ID = 'careRmndDays';


  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  DELETE FROM ADS_CUST_CARE_RMND WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：客户关怀提醒
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：客户关怀提醒
  INSERT INTO ADS_CUST_CARE_RMND (
      PERSN_LEGAL_BK_CODE,
      DATA_DATE,
      CARE_ID,
      CARE_TYP,
      MNGR_POST_ID,
      MNGR_NAME,
      CUST_ID,
      CUST_NAME,
      PHONE_NO,
      CUST_TYP,
      ORG_ID,
      HDLE_STATE,
      CATE_TIME,
      HDLE_TIME,
      CTKTR_NAME,
      CTKTR_REL,
      MSG_CONTENT,
      ACCT_NO,
      CUST_HRAKY,
      ORG_NAME
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         V_SYADAT                    AS DATA_DATE            , -- 数据日期
         SEQ_ADS_CUST_CARE_RMND.NEXTVAL  AS CARE_ID              , -- 关怀ID
         '01'                        AS CARE_TYP             , -- 关怀类型
         T2.MNGR_POST_ID             AS MNGR_POST_ID         , -- 客户经理编号
         T3.USR_NAME                 AS MNGR_NAME            , -- 客户经理名称
         T1.CUST_ID                  AS CUST_ID              , -- 客户ID
         T1.CUST_NAME                AS CUST_NAME            , -- 客户名称
         T1.PHONE_NO                 AS PHONE_NO             , -- 手机号
         T1.CUST_TYP                 AS CUST_TYP             , -- 客户类型
         T4.ORG_ID                   AS ORG_ID               , -- 所属机构
         '0'                         AS HDLE_STATE           , -- 处理状态
         CASE
          WHEN LENGTH(T1.CERT_ID) = 18 THEN SUBSTR(T1.CERT_ID, 7, 8)
             WHEN LENGTH(T1.CERT_ID) = 15 THEN '19' || SUBSTR(T1.CERT_ID, 7, 6)
          ELSE 0
         END AS CATE_TIME, -- 生日日期
         ''                          AS HDLE_TIME            , -- 处理时间
         ''                          AS CTKTR_NAME           , -- 联系人姓名
         ''                          AS CTKTR_REL            , -- 联系人关系
         ''                          AS MSG_CONTENT          , -- 消息内容
         ''                          AS ACCT_NO              , -- 客户账户
         T4.CUST_HRAKY               AS CUST_HRAKY           , -- 客户层级
         ''                          AS ORG_NAME              -- 机构名称
    FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
    LEFT JOIN DWD_CUST_MAN T2 -- 信贷管户关系表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T2.MNG_TYP = '1'
    LEFT JOIN CRM_SYS_POST T3 -- 职位表
      ON T2.MNGR_POST_ID = T3.POST_ID
    LEFT JOIN DWS_CUST_LVL_INFO T4 -- 客户等级信息表
      ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
   WHERE T1.CERT_TYP = '01' AND CASE
     WHEN LENGTH(T1.CERT_ID) = 18 THEN
     TO_DATE(V_SYSDAT, 'YYYYMMDD') - TO_DATE(SUBSTR(T1.CERT_ID, 7, 8),'YYYYMMDD')
     WHEN LENGTH(T1.CERT_ID) = 15 THEN
     TO_DATE(V_SYSDAT, 'YYYYMMDD') - TO_DATE('19' || SUBSTR(T1.CERT_ID, 7, 6),'YYYYMMDD')
     ELSE 0
     END >=  V_DEAD_LINE_DAYS;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：客户关怀提醒';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_deadline_info_depo_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_deadline_info_depo_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 定期到期明细数据处理
  -- 作业编号: PRC_ADS_CUST_DEADLINE_INFO_DEPO_DTL
  -- 处理周期: 每日
  -- 来源表: DWD_ACCT_DEPO
  -- 目标表: ADS_CUST_DEADLINE_INFO_DEPO_DTL
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '定期到期明细数据处理';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CUST_DEADLINE_INFO_DEPO_DTL';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NC			VARCHAR(8);
  V_NM			VARCHAR(8);
  V_NUM			INTEGER := 0;
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_NC := sys_fun_deal_date(V_SYSDAT, 13);
  V_NM := substring(V_SYSDAT,1,4)||'1231'; 
  ------------------------------------------------------------------
  -- 1. 年初把当年到期的数据加工到目标表
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  -- 第一次初始化
  SELECT count(1) INTO V_NUM FROM  ADS_CUST_DEADLINE_INFO_DEPO_DTL;
  IF V_NUM = 0 THEN 
  	DELETE FROM ADS_CUST_DEADLINE_INFO_DEPO_DTL WHERE DATA_DATE = V_SYSDAT;
   		COMMIT;
		INSERT INTO ADS_CUST_DEADLINE_INFO_DEPO_DTL(
	   	  PERSN_LEGAL_BK_CODE,  -- 法人行号       
		  DATA_DATE,            -- 数据日期
		  CUST_ID,              -- 客户编号
		  PRDKT_ID,             -- 产品编号
		  PRDKT_NAME,           -- 产品名称
		  EXPR_DATE,            -- 到期日期
		  BAL,                  -- 到期金额
		  RATE_INTRI            -- 利率
	   )
	   SELECT 
	   	  A.PERSN_LEGAL_BK_CODE,-- 法人行号
	   	  V_SYSDAT,             -- 数据日期
	   	  A.CUST_ID,            -- 客户编号
	   	  A.PRDKT_ID,           -- 产品编号
	   	  A.PRDKT_NAME,         -- 产品名称
	   	  A.EXPR_DATE,          -- 到期日期
	   	  A.RMB_BAL,            -- 到期金额
	   	  A.RATE_INTRI          -- 利率
	   FROM DWD_ACCT_DEPO A 
	   WHERE A.EXPR_DATE >= V_SYSDAT
	   	AND A.EXPR_DATE <= V_NM 
	   	AND A.RMB_BAL>0;
	   COMMIT;
  ELSE 
  	-- 正常跑批
  IF V_SYSDAT = V_NC THEN
	  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_DEADLINE_INFO_DEPO_DTL';
	   INSERT INTO ADS_CUST_DEADLINE_INFO_DEPO_DTL(
	   	  PERSN_LEGAL_BK_CODE,  -- 法人行号       
		  DATA_DATE,            -- 数据日期
		  CUST_ID,              -- 客户编号
		  PRDKT_ID,             -- 产品编号
		  PRDKT_NAME,           -- 产品名称
		  EXPR_DATE,            -- 到期日期
		  BAL,                  -- 到期金额
		  RATE_INTRI            -- 利率
	   )
	   SELECT 
	   	  A.PERSN_LEGAL_BK_CODE,-- 法人行号
	   	  V_SYSDAT,             -- 数据日期
	   	  A.CUST_ID,            -- 客户编号
	   	  A.PRDKT_ID,           -- 产品编号
	   	  A.PRDKT_NAME,         -- 产品名称
	   	  A.EXPR_DATE,          -- 到期日期
	   	  A.RMB_BAL,            -- 到期金额
	   	  A.RATE_INTRI          -- 利率
	   FROM DWD_ACCT_DEPO A 
	   WHERE A.EXPR_DATE >= V_NC 
	   	AND A.EXPR_DATE <= V_NM 
	   	AND A.RMB_BAL > 0;
	   COMMIT;
   ELSE 
   		DELETE FROM ADS_CUST_DEADLINE_INFO_DEPO_DTL WHERE DATA_DATE = V_SYSDAT;
   		COMMIT;
		INSERT INTO ADS_CUST_DEADLINE_INFO_DEPO_DTL(
	   	  PERSN_LEGAL_BK_CODE,  -- 法人行号       
		  DATA_DATE,            -- 数据日期
		  CUST_ID,              -- 客户编号
		  PRDKT_ID,             -- 产品编号
		  PRDKT_NAME,           -- 产品名称
		  EXPR_DATE,            -- 到期日期
		  BAL,                  -- 到期金额
		  RATE_INTRI            -- 利率
	   )
	   SELECT 
	   	  A.PERSN_LEGAL_BK_CODE,-- 法人行号
	   	  V_SYSDAT,             -- 数据日期
	   	  A.CUST_ID,            -- 客户编号
	   	  A.PRDKT_ID,           -- 产品编号
	   	  A.PRDKT_NAME,         -- 产品名称
	   	  A.EXPR_DATE,          -- 到期日期
	   	  A.RMB_BAL,            -- 到期金额
	   	  A.RATE_INTRI          -- 利率
	   FROM DWD_ACCT_DEPO A 
	   WHERE A.INTRI_BGN_DATE = V_SYSDAT
	   	AND A.EXPR_DATE <= V_NM 
	   	AND A.RMB_BAL>0;
	   COMMIT;
   END IF;	
  
  END IF;
  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户当年到期存款明细数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_deadline_info_fin_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_deadline_info_fin_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 理财到期明细数据处理
  -- 作业编号: PRC_ADS_CUST_DEADLINE_INFO_FIN_DTL
  -- 处理周期: 每日
  -- 来源表: DWD_ACCT_FIN
  -- 目标表: ADS_CUST_DEADLINE_INFO_FIN_DTL
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '定期到期明细数据处理';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_CUST_DEADLINE_INFO_FIN_DTL';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_NC			VARCHAR(8);
  V_NM			VARCHAR(8);
  V_NUM			INTEGER := 0;
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_NC := sys_fun_deal_date(V_SYSDAT, 13);
  V_NM := substring(V_SYSDAT,1,4)||'1231'; 
  ------------------------------------------------------------------
  -- 1. 年初把当年到期的数据加工到目标表
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  -- 第一次初始化
  SELECT count(1) INTO V_NUM FROM  ADS_CUST_DEADLINE_INFO_FIN_DTL;
  IF V_NUM = 0 THEN 
  	DELETE FROM ADS_CUST_DEADLINE_INFO_FIN_DTL WHERE DATA_DATE = V_SYSDAT;
   		COMMIT;
		INSERT INTO ADS_CUST_DEADLINE_INFO_FIN_DTL(
	   	  PERSN_LEGAL_BK_CODE,  -- 法人行号       
		  DATA_DATE,            -- 数据日期
		  CUST_ID,              -- 客户编号
		  PRDKT_ID,             -- 产品编号
		  PRDKT_NAME,           -- 产品名称
		  EXPR_DATE,            -- 到期日期
		  BAL,                  -- 到期金额
		  RATE_INTRI            -- 利率
	   )
	   SELECT 
	   	  A.PERSN_LEGAL_BK_CODE,-- 法人行号
	   	  V_SYSDAT,             -- 数据日期
	   	  A.CUST_ID,            -- 客户编号
	   	  A.PRDKT_ID,           -- 产品编号
	   	  A.PRDKT_NAME,         -- 产品名称
	   	  A.EXPR_DATE,          -- 到期日期
	   	  A.FIN_AMT,            -- 到期金额
	   	  A.RATE_INTRI          -- 利率
	   FROM DWD_ACCT_FIN A 
	   WHERE A.EXPR_DATE >= V_SYSDAT
	   	AND A.EXPR_DATE <= V_NM 
	   	AND A.FIN_AMT>0;
	   COMMIT;
  ELSE 
  	-- 正常跑批
  IF V_SYSDAT = V_NC THEN
	  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_DEADLINE_INFO_FIN_DTL';
	   INSERT INTO ADS_CUST_DEADLINE_INFO_FIN_DTL(
	   	  PERSN_LEGAL_BK_CODE,  -- 法人行号       
		  DATA_DATE,            -- 数据日期
		  CUST_ID,              -- 客户编号
		  PRDKT_ID,             -- 产品编号
		  PRDKT_NAME,           -- 产品名称
		  EXPR_DATE,            -- 到期日期
		  BAL,                  -- 到期金额
		  RATE_INTRI            -- 利率
	   )
	   SELECT 
	   	  A.PERSN_LEGAL_BK_CODE,-- 法人行号
	   	  V_SYSDAT,             -- 数据日期
	   	  A.CUST_ID,            -- 客户编号
	   	  A.PRDKT_ID,           -- 产品编号
	   	  A.PRDKT_NAME,         -- 产品名称
	   	  A.EXPR_DATE,          -- 到期日期
	   	  A.FIN_AMT,            -- 到期金额
	   	  A.RATE_INTRI          -- 利率
	   FROM DWD_ACCT_FIN A 
	   WHERE A.EXPR_DATE >= V_NC 
	   	AND A.EXPR_DATE <= V_NM 
	   	AND A.RMB_BAL > 0;
	   COMMIT;
   ELSE 
   		DELETE FROM ADS_CUST_DEADLINE_INFO_FIN_DTL WHERE DATA_DATE = V_SYSDAT;
   		COMMIT;
		INSERT INTO ADS_CUST_DEADLINE_INFO_FIN_DTL(
	   	  PERSN_LEGAL_BK_CODE,  -- 法人行号       
		  DATA_DATE,            -- 数据日期
		  CUST_ID,              -- 客户编号
		  PRDKT_ID,             -- 产品编号
		  PRDKT_NAME,           -- 产品名称
		  EXPR_DATE,            -- 到期日期
		  BAL,                  -- 到期金额
		  RATE_INTRI            -- 利率
	   )
	   SELECT 
	   	  A.PERSN_LEGAL_BK_CODE,-- 法人行号
	   	  V_SYSDAT,             -- 数据日期
	   	  A.CUST_ID,            -- 客户编号
	   	  A.PRDKT_ID,           -- 产品编号
	   	  A.PRDKT_NAME,         -- 产品名称
	   	  A.EXPR_DATE,          -- 到期日期
	   	  A.FIN_AMT,            -- 到期金额
	   	  A.RATE_INTRI          -- 利率
	   FROM DWD_ACCT_FIN A 
	   WHERE A.INTRI_BGN_DATE = V_SYSDAT
	   	AND A.EXPR_DATE <= V_NM 
	   	AND A.RMB_BAL>0;
	   COMMIT;
   END IF;	
  
  END IF;
  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户当年到期存款明细数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_deadline_rmnd(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_deadline_rmnd(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 到期预警提醒表
  -- 存储过程编号：PRC_ADS_CUST_DEADLINE_RMND
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：CRM_SYS_POST(职位表)；DWD_ACCT_DEPO(存款账户信息表)；DWD_ACCT_FIN(理财账户)；DWD_CUST_CTRAKT_INFO(客户合同信息)；DWD_CUST_INDIV_RISK_INVST(客户风险评估)；DWD_CUST_MAN(信贷管户关系表)；DWD_SYS_ORG(机构表)；DWS_CUST_LVL_INFO(客户等级信息表)
  -- 目标表：ADS_CUST_DEADLINE_RMND
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '到期预警提醒表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_DEADLINE_RMND';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_DEAD_LINE_DAYS      NUMBER;
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  SELECT TO_NUMBER(PARAM_VAL)
    INTO V_DEAD_LINE_DAYS
    FROM CRM.SYS_PARAM_CONFIG
   WHERE PARAM_ID = 'deadLineDays';


  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  DELETE FROM ADS_CUST_DEADLINE_RMND WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：定期存款到期
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：定期存款到期
  INSERT INTO ADS_CUST_DEADLINE_RMND (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      RMND_ID,
      RMND_TYP,
      RMND_NAME,
      MNGR_POST_ID,
      MNGR_NAME,
      CUST_ID,
      CUST_TYP,
      CUST_NAME,
      PRDKT_NAME,
      EXPR_AMT,
      EXPR_DATE,
      ORG_ID,
      HDLE_STATE,
      RMND_DATE,
      HDLE_TIME,
      DEL_FLG,
      PHONE_NO,
      RMND_INF,
      CUST_HRAKY,
      ACCT_NO,
      ORG_NAME
  )
  SELECT
         V_SYSDAT                        AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         SEQ_ADS_CUST_DEADLINE_RMND.NEXTVAL  AS RMND_ID              , -- 到期提醒ID
         '01'                            AS RMND_TYP             , -- 提醒类型
         '定期存款到期'                        AS RMND_NAME            , -- 提醒名称
         T2.MNGR_POST_ID                 AS MNGR_POST_ID         , -- 客户经理编号
         T3.USR_NAME                     AS MNGR_NAME            , -- 客户经理名称
         T1.CUST_ID                      AS CUST_ID              , -- 客户ID
         T1.CUST_TYP                     AS CUST_TYP             , -- 客户类型
         T1.CUST_NAME                    AS CUST_NAME            , -- 客户名称
         T1.PRDKT_NAME                   AS PRDKT_NAME           , -- 产品名称
         T1.RMB_BAL                      AS EXPR_AMT             , -- 到期金额
         T1.EXPR_DATE                    AS EXPR_DATE            , -- 到期日期
         T4.ORG_ID                       AS ORG_ID               , -- 机构
         '0'                             AS HDLE_STATE           , -- 处理状态
         V_SYSDAT                        AS RMND_DATE            , -- 提醒日期
         ''                              AS HDLE_TIME            , -- 处理时间
         '0'                             AS DEL_FLG              , -- 删除标志
         ''                              AS PHONE_NO             , -- 手机号
         ''                              AS RMND_INF             , -- 提醒内容
         T4.CUST_HRAKY                   AS CUST_HRAKY           , -- 客户层级
         T1.ACCT_ID                      AS ACCT_NO              , -- 客户账户
         T5.ORG_NAME                     AS ORG_NAME              -- 机构名称
    FROM DWD_ACCT_DEPO T1 -- 存款账户信息表
    INNER JOIN DWD_CUST_MAN T2 -- 信贷管户关系表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T2.MNG_TYP = '1'
    INNER JOIN CRM_SYS_POST T3 -- 职位表
      ON T2.MNGR_POST_ID = T3.POST_ID
    INNER JOIN DWS_CUST_LVL_INFO T4 -- 客户等级信息表
      ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
    INNER JOIN DWD_SYS_ORG T5 -- 机构表
      ON T4.ORG_ID = T5.ORG_ID
   WHERE T1.PRDKT_CATE_BIG = '02' AND TO_DATE(V_SYSDAT, 'YYYYMMDD') - TO_DATE(T1.EXPR_DATE,'YYYYMMDD') = V_DEAD_LINE_DAYS;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：定期存款到期';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：理财到期
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：理财到期
  INSERT INTO ADS_CUST_DEADLINE_RMND (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      RMND_ID,
      RMND_TYP,
      RMND_NAME,
      MNGR_POST_ID,
      MNGR_NAME,
      CUST_ID,
      CUST_TYP,
      CUST_NAME,
      PRDKT_NAME,
      EXPR_AMT,
      EXPR_DATE,
      ORG_ID,
      HDLE_STATE,
      RMND_DATE,
      HDLE_TIME,
      DEL_FLG,
      PHONE_NO,
      RMND_INF,
      CUST_HRAKY,
      ACCT_NO,
      ORG_NAME
  )
  SELECT
         V_SYSDAT                        AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         SEQ_ADS_CUST_DEADLINE_RMND.NEXTVAL  AS RMND_ID              , -- 到期提醒ID
         '02'                            AS RMND_TYP             , -- 提醒类型
         '理财到期'                          AS RMND_NAME            , -- 提醒名称
         T2.MNGR_POST_ID                 AS MNGR_POST_ID         , -- 客户经理编号
         T3.USR_NAME                     AS MNGR_NAME            , -- 客户经理名称
         T1.CUST_ID                      AS CUST_ID              , -- 客户ID
         T1.CUST_TYP                     AS CUST_TYP             , -- 客户类型
         T4.CUST_NAME                    AS CUST_NAME            , -- 客户名称
         T1.PRDKT_NAME                   AS PRDKT_NAME           , -- 产品名称
         T1.FIN_AMT                      AS EXPR_AMT             , -- 到期金额
         T1.EXPR_DATE                    AS EXPR_DATE            , -- 到期日期
         T4.ORG_ID                       AS ORG_ID               , -- 机构
         ''                              AS HDLE_STATE           , -- 处理状态
         V_SYSDAT                        AS RMND_DATE            , -- 提醒日期
         ''                              AS HDLE_TIME            , -- 处理时间
         '0'                             AS DEL_FLG              , -- 删除标志
         ''                              AS PHONE_NO             , -- 手机号
         ''                              AS RMND_INF             , -- 提醒内容
         T4.CUST_HRAKY                   AS CUST_HRAKY           , -- 客户层级
         T1.ACCT_ID                      AS ACCT_NO              , -- 客户账户
         T5.ORG_NAME                     AS ORG_NAME              -- 机构名称
    FROM DWD_ACCT_FIN T1 -- 理财账户
    INNER JOIN DWD_CUST_MAN T2 -- 信贷管户关系表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T2.MNG_TYP = '1'
    INNER JOIN CRM_SYS_POST T3 -- 职位表
      ON T2.MNGR_POST_ID = T3.POST_ID
    INNER JOIN DWS_CUST_LVL_INFO T4 -- 客户等级信息表
      ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
    INNER JOIN DWD_SYS_ORG T5 -- 机构表
      ON T4.ORG_ID = T5.ORG_ID
   WHERE TO_DATE(V_SYSDAT, 'YYYYMMDD') - TO_DATE(T1.EXPR_DATE,'YYYYMMDD') = V_DEAD_LINE_DAYS;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：理财到期';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：贷款授信到期
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：贷款授信到期
  INSERT INTO ADS_CUST_DEADLINE_RMND (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      RMND_ID,
      RMND_TYP,
      RMND_NAME,
      MNGR_POST_ID,
      MNGR_NAME,
      CUST_ID,
      CUST_TYP,
      CUST_NAME,
      PRDKT_NAME,
      EXPR_AMT,
      EXPR_DATE,
      ORG_ID,
      HDLE_STATE,
      RMND_DATE,
      HDLE_TIME,
      DEL_FLG,
      PHONE_NO,
      RMND_INF,
      CUST_HRAKY,
      ACCT_NO,
      ORG_NAME
  )
  SELECT
         V_SYSDAT                        AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         SEQ_ADS_CUST_DEADLINE_RMND.NEXTVAL  AS RMND_ID              , -- 到期提醒ID
         '03'                            AS RMND_TYP             , -- 提醒类型
         '贷款授信到期'                        AS RMND_NAME            , -- 提醒名称
         T2.MNGR_POST_ID                 AS MNGR_POST_ID         , -- 客户经理编号
         T3.USR_NAME                     AS MNGR_NAME            , -- 客户经理名称
         T1.CUST_ID                      AS CUST_ID              , -- 客户ID
         '1'                             AS CUST_TYP             , -- 客户类型
         T4.CUST_NAME                    AS CUST_NAME            , -- 客户名称
         T1.PRDKT_NAME                   AS PRDKT_NAME           , -- 产品名称
         T1.CONTR_AMT                    AS EXPR_AMT             , -- 到期金额
         T1.END_DATE                     AS EXPR_DATE            , -- 到期日期
         T4.ORG_ID                       AS ORG_ID               , -- 机构
         ''                              AS HDLE_STATE           , -- 处理状态
         V_SYSDAT                        AS RMND_DATE            , -- 提醒日期
         ''                              AS HDLE_TIME            , -- 处理时间
         '0'                             AS DEL_FLG              , -- 删除标志
         ''                              AS PHONE_NO             , -- 手机号
         ''                              AS RMND_INF             , -- 提醒内容
         T4.CUST_HRAKY                   AS CUST_HRAKY           , -- 客户层级
         T1.LOAN_ACCT                    AS ACCT_NO              , -- 客户账户
         T5.ORG_NAME                     AS ORG_NAME              -- 机构名称
    FROM DWD_CUST_CTRAKT_INFO T1 -- 客户合同信息
    INNER JOIN DWD_CUST_MAN T2 -- 信贷管户关系表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T2.MNG_TYP = '2'
    INNER JOIN CRM_SYS_POST T3 -- 职位表
      ON T2.MNGR_POST_ID = T3.POST_ID
    INNER JOIN DWS_CUST_LVL_INFO T4 -- 客户等级信息表
      ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
    INNER JOIN DWD_SYS_ORG T5 -- 机构表
      ON T4.ORG_ID = T5.ORG_ID
   WHERE TO_DATE(V_SYSDAT, 'YYYYMMDD') - TO_DATE(T1.END_DATE,'YYYYMMDD') = V_DEAD_LINE_DAYS;

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：贷款授信到期';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：风险评估到期
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 第4段业务逻辑：风险评估到期
  INSERT INTO ADS_CUST_DEADLINE_RMND (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      RMND_ID,
      RMND_TYP,
      RMND_NAME,
      MNGR_POST_ID,
      MNGR_NAME,
      CUST_ID,
      CUST_TYP,
      CUST_NAME,
      PRDKT_NAME,
      EXPR_AMT,
      EXPR_DATE,
      ORG_ID,
      HDLE_STATE,
      RMND_DATE,
      HDLE_TIME,
      DEL_FLG,
      PHONE_NO,
      RMND_INF,
      CUST_HRAKY,
      ACCT_NO,
      ORG_NAME
  )
  SELECT
         V_SYSDAT                        AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         SEQ_ADS_CUST_DEADLINE_RMND.NEXTVAL  AS RMND_ID              , -- 到期提醒ID
         CASE 
           WHEN INVEST_TYP = '3' THEN '04'
           WHEN INVEST_TYP = '4' THEN '05'
         END AS RMND_TYP, -- 提醒类型
         CASE 
           WHEN INVEST_TYP = '3' THEN '理财风险评估到期'
           WHEN INVEST_TYP = '4' THEN '保险风险评估到期'
         END AS RMND_NAME, -- 提醒名称
         T2.MNGR_POST_ID                 AS MNGR_POST_ID         , -- 客户经理编号
         T3.USR_NAME                     AS MNGR_NAME            , -- 客户经理名称
         T1.CUST_ID                      AS CUST_ID              , -- 客户ID
         '1'                             AS CUST_TYP             , -- 客户类型
         T4.CUST_NAME                    AS CUST_NAME            , -- 客户名称
         ''                              AS PRDKT_NAME           , -- 产品名称
         ''                              AS EXPR_AMT             , -- 到期金额
         T1.EXPR_DATE                    AS EXPR_DATE            , -- 到期日期
         T4.ORG_ID                       AS ORG_ID               , -- 机构
         ''                              AS HDLE_STATE           , -- 处理状态
         V_SYSDAT                        AS RMND_DATE            , -- 提醒日期
         ''                              AS HDLE_TIME            , -- 处理时间
         '0'                             AS DEL_FLG              , -- 删除标志
         ''                              AS PHONE_NO             , -- 手机号
         ''                              AS RMND_INF             , -- 提醒内容
         T4.CUST_HRAKY                   AS CUST_HRAKY           , -- 客户层级
         ''                              AS ACCT_NO              , -- 客户账户
         T5.ORG_NAME                     AS ORG_NAME              -- 机构名称
    FROM DWD_CUST_INDIV_RISK_INVST T1 -- 客户风险评估
    INNER JOIN DWD_CUST_MAN T2 -- 信贷管户关系表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T2.MNG_TYP = '1'
    INNER JOIN CRM_SYS_POST T3 -- 职位表
      ON T2.MNGR_POST_ID = T3.POST_ID
    INNER JOIN DWS_CUST_LVL_INFO T4 -- 客户等级信息表
      ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
    INNER JOIN DWD_SYS_ORG T5 -- 机构表
      ON T4.ORG_ID = T5.ORG_ID
   WHERE TO_DATE(V_SYSDAT, 'YYYYMMDD') - TO_DATE(T1.EXPR_DATE,'YYYYMMDD') = V_DEAD_LINE_DAYS;

  -- 提交第4段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：风险评估到期';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_deadline_rmnd_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_deadline_rmnd_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 到期承接明细表处理
  -- 存储过程编号: PRC_ADS_CUST_DEADLINE_RMND_DTL
  -- 处理周期: 日
  -- 过程描述: 分段生成到期承接明细,物理中间表仅做 TRUNCATE/INSERT,便于排查
  -- 来源表: DWD_CUST_INDV_INFO(客户基本信息), DWD_ACCT_DEPO(存款账户),
  --         DWD_ACCT_FIN(理财账户), DWD_ACCT_INSUR(保险账户),
  --         DWS_CUST_ASSE_LIAB(客户资产负债表),
  --         ADS_MKT_REC_INFO(营销记录表)
  -- 目标表: ADS_CUST_DEADLINE_RMND_DTL(到期承接明细表)
  -- author :
  -- date   : 2026-07-15
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.7.0
  -- 关联需求: REQ-CUST-001, REQ-CUST-002
  -- 变更记录:
  --   v3.1.1: DUE_WIN生成优化：两条INSERT合并为一条(统一窗口子查询w × 按类型金额子查询a),
  --           三个日期字段统一来自w,金额按类型独立来自a,逻辑更清晰
  --   v3.1.0: 1.F-01修复：30天到期窗口仅按STATIS_TYP=0统一计算(口径40),STATIS_TYP=1/2
  --             JOIN复用统一窗口日期(FIRST_EXPR_DT/LAST_EXPR_DT/TAKE_END_DT_30D),
  --             金额按类型独立汇总；消除存款/理财页签窗口被缩短导致承接金额遗漏
  --           2.F-02修复：理财购买源过滤条件由文字'开放式理财'改为数字代码NOT IN('1','3'),
  --             与到期源过滤条件统一(口径3)
  --   v3.0.0: 两期计算完全分离架构(单过程、单块分段落、禁止嵌套过程)：
  --           段9为单个BEGIN...END块,块内以注释段落分隔本期计算段(C1/C2)/上期计算段(P1/P2)/
  --           数据验证段(V1)；独立存储TMP_CDR_DTL_CURR_STAGE/TMP_CDR_DTL_PREV_STAGE/
  --           FREEZE_LOG/VALIDATE_RESULT；严格边界检查(RAISE -2001x)；日志内联并C/P/V前缀隔离
  --   v2.8.1: 注释规范化：补齐输入输出参数、变量、各处理段(数据来源/业务含义/处理逻辑)注释
  --   v2.9.0: 1.上期基础数据冻结(口径34)：段1不再删除上期行,仅删除本期快照
  --           2.上期仅定点更新7字段(口径35)：TAKE_RATE/FIX_DEPO_TAKE_RATE/UNDTAKE_STATE/
  --             CNTCT_STATE/FIXED_FIN_MATURE_TRAN_INSUR_AMT/FIN_MATURE_TRAN_FIXED_AMT/
  --             FIXED_MATURE_TRAN_FIN_AMT,随30天承接窗口滚动更新
  --           3.DATA_DATE双语义(口径37)：本期行=跑批日期V_SYSDAT,上期行=期末日期
  --           4.承接窗口购买增加BUY_DT<=V_SYSDAT截止(口径39),与EXPR_AMT截止口径对齐
  --   v2.8.0: 1.DWS关联统一补 BAL_TYPE='1' 并移除关联键 ORG_ID(口径15/22/23)
  --           2.CROSS_CONV增加STATIS_TYP维度；TAKE_AMT/AUM_BAL按客户+法人行粒度(口径11/23)
  --           3.接触状态改为30天承接窗口判定(口径30)
  --   v2.7.0: 1.EXPR_AMT截止日期V_PREV_DAY→V_SYSDAT(自然日=跑批日期)
  --           2.CROSS_CONV增加STAT_PERD维度(修复跨类型转化金额月/季/年混淆)
  --   v2.6.0: 1.存款/理财账户JOIN DWS补ORG_ID三键关联(账户表),资产表法人行优先关联
  --           2.合并DWS_CUST_ASSE_LIAB当前AUM查询到CUST_BASE(减少1次大表扫描)
  --           3.跨类型转化金额改为预聚合临时表TMP_CDR_DTL_CROSS_CONV(消除N×2关联子查询)
  --           4.简化DELETE历史清理逻辑(去掉冗余周期末日校验,仅保留三年边界)
  --           5.TMP_CDR_DTL_CUST_BASE列名ORG_ID修正为PERSN_LEGAL_BK_CODE
  --   v2.5.0: 所有基于跑批日的业务日期均使用 SYS_FUN_DEAL_DATE 具名参数；目标表日期统一输出 YYYYMMDD。
  --   v2.2.0: 1.计算粒度调整：因法人行有多个,一个客户在不同归属机构/法人行算多个客户,需分开计算
  --           2.客户号+归属机构(经办机构)/法人机构才能算作一个计算单位
  --           3.到期产品源、到期窗口、购买产品源、承接金额、AUM中间表均按客户+机构维度分组
  --           4.法人行号和归属机构从账户表获取(DWD_ACCT_DEPO.OPEN_ACCT_ORG, DWD_ACCT_FIN.OPRT_ORG)
  --   v2.1.0: 1.资产承接率统计周期从14天改为30天
  --           2.到期窗口计算逻辑调整为取下一笔到期日减1(如果30天内有下一笔到期),否则取最后一笔到期日+30
  --           3.理财到期转定期金额和定期到期转理财金额计算逻辑优化(跨STATIS_TYP统计)
  --           4.客户承接率长期化产品已剔除保险：TAKE_AMT_30D 仅统计 DEPO/FIN
  --           5.定期存款承接率已过滤通知存款：PRDKT_CATE_BIG <> '04'
  --           6.DATA_DATE语义变更：统一使用周期结束日期(M-月末,Q-季末,Y-年末),不再使用快照日期
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '到期承接明细表处理';                    -- 过程描述(日志用)
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_DEADLINE_RMND_DTL';       -- 过程名称(日志用)
  -- V_SYSDAT 为跑批日期：用于源表 DATA_DATE 快照等值关联,不表示需求语义中的上一日。
  V_PREV_DAY             VARCHAR2(8);  -- 上一日：跑批日期的上一日,取 SYS_FUN_DEAL_DATE(V_SYSDAT, 1)。
  V_CURR_MONTH_BEGIN     VARCHAR2(8);  -- 当月初：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 9)。
  V_CURR_MONTH_END       VARCHAR2(8);  -- 当月末：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 10)。
  V_CURR_QUARTER_BEGIN   VARCHAR2(8);  -- 当季初：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 11)。
  V_CURR_QUARTER_END     VARCHAR2(8);  -- 当季末：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 12)。
  V_CURR_YEAR_BEGIN      VARCHAR2(8);  -- 当年初：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 13)。
  V_CURR_YEAR_END        VARCHAR2(8);  -- 当年末：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 14)。
  V_PREV_MONTH_BEGIN     VARCHAR2(8);  -- 上月初：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 15)。
  V_PREV_QUARTER_BEGIN   VARCHAR2(8);  -- 上季初：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 16)。
  V_PREV_YEAR_BEGIN      VARCHAR2(8);  -- 上年初：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 17)。
  V_SQL                  VARCHAR(32767);  -- V_SQL：预留动态SQL变量(当前未使用)
  V_LOG_MSG              VARCHAR(4000);   -- V_LOG_MSG：日志消息文本
  V_START_DT             DATE;            -- V_START_DT：过程开始时间(耗时统计用)
  V_LOG_FLG              INTEGER;         -- V_LOG_FLG：日志标志(0=成功,-1=异常)
  V_LOG_BUTTON           INTEGER := 1;    -- V_LOG_BUTTON：日志记录开关(1=记录)
  V_NO_ID                VARCHAR(10);     -- V_NO_ID：当前处理步骤编号(日志定位用)
  V_BGN_DATE             DATE;            -- V_BGN_DATE：当前步骤开始时间
  V_END_DATE             DATE;            -- V_END_DATE：当前步骤结束时间
  V_DURA_DATE            INTEGER;         -- V_DURA_DATE：当前步骤耗时(秒)
  P_INTERVAL_START_DATE  VARCHAR(8);   -- 30天承接窗口开始日：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 18)。
  P_INTERVAL_END_DATE    VARCHAR(8);   -- 30天承接窗口结束日：上一日,即 V_PREV_DAY。
  V_PREV_MONTH_END       VARCHAR2(8);  -- 上月末：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 2)。
  V_PREV_QUARTER_END     VARCHAR2(8);  -- 上季末：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 3)。
  V_PREV_YEAR_END        VARCHAR2(8);  -- 上年末：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 4)。
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);  -- 三年历史清理边界：取 SYS_FUN_DEAL_DATE(V_SYSDAT, 19)。

BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 1. 校验跑批日期并初始化全部相对业务日期具名参数(sys_fun_deal_date,编号定义见
  --    governance/stored_procedure_date_parameter_rules.md)
  IF V_SYSDAT IS NULL OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$') THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_START_DT := SYSDATE;
  V_PREV_DAY := sys_fun_deal_date(V_SYSDAT, 1);
  V_CURR_MONTH_BEGIN := sys_fun_deal_date(V_SYSDAT, 9);
  V_CURR_MONTH_END := sys_fun_deal_date(V_SYSDAT, 10);
  V_CURR_QUARTER_BEGIN := sys_fun_deal_date(V_SYSDAT, 11);
  V_CURR_QUARTER_END := sys_fun_deal_date(V_SYSDAT, 12);
  V_CURR_YEAR_BEGIN := sys_fun_deal_date(V_SYSDAT, 13);
  V_CURR_YEAR_END := sys_fun_deal_date(V_SYSDAT, 14);
  V_PREV_MONTH_BEGIN := sys_fun_deal_date(V_SYSDAT, 15);
  V_PREV_QUARTER_BEGIN := sys_fun_deal_date(V_SYSDAT, 16);
  V_PREV_YEAR_BEGIN := sys_fun_deal_date(V_SYSDAT, 17);
  P_INTERVAL_START_DATE := sys_fun_deal_date(V_SYSDAT, 18);
  P_INTERVAL_END_DATE   := V_PREV_DAY;
  V_PREV_MONTH_END := sys_fun_deal_date(V_SYSDAT, 2);
  V_PREV_QUARTER_END := sys_fun_deal_date(V_SYSDAT, 3);
  V_PREV_YEAR_END := sys_fun_deal_date(V_SYSDAT, 4);
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);

  --***************************************
  -- 2.0 -- 第1段处理开始：清理目标表和中间表
  -- 业务含义：幂等重跑准备——仅删除本期快照行(DATA_DATE=V_SYSDAT)及旧语义当期结束日行,
  --           严格保留上期(上月/上季/上年)基础数据行(口径34),并清空全部物理中间表
  -- 数据来源：ADS_CUST_DEADLINE_RMND_DTL + 12张TMP_CDR_DTL_*中间表/隔离存储
  -- 处理逻辑：DELETE(本期快照+旧语义当期结束日) + TRUNCATE_TMP × 12
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  DELETE FROM ADS_CUST_DEADLINE_RMND_DTL
   -- v2.9.0(口径28/34/37): 每日替换——删除当期周期区间内的本期快照行
   --                        (当月初/季初/年初~V_SYSDAT),上期行不删除
   WHERE (STAT_PERD = 'M' AND DATA_DATE >= V_CURR_MONTH_BEGIN AND DATA_DATE <= V_SYSDAT)
      OR (STAT_PERD = 'Q' AND DATA_DATE >= V_CURR_QUARTER_BEGIN AND DATA_DATE <= V_SYSDAT)
      OR (STAT_PERD = 'Y' AND DATA_DATE >= V_CURR_YEAR_BEGIN AND DATA_DATE <= V_SYSDAT)
      -- 过渡期清理：旧语义生成的当期结束日行(仅首日存在,后续幂等无影响)
      OR (STAT_PERD = 'M' AND DATA_DATE = V_CURR_MONTH_END)
      OR (STAT_PERD = 'Q' AND DATA_DATE = V_CURR_QUARTER_END)
      OR (STAT_PERD = 'Y' AND DATA_DATE = V_CURR_YEAR_END);
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_PERIOD';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_MATURE_SRC';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_DUE_WIN';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_PURCHASE_SRC';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_TAKE_AMT';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_CUST_BASE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_AUM_BAL';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_CROSS_CONV';
  -- v3.0.0: 两期隔离存储与验证日志
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_CURR_STAGE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_PREV_STAGE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_DTL_FREEZE_LOG';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_VALIDATE_RESULT';

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：清理目标表和中间表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.1 -- 第2段处理开始：生成统计周期中间表
  -- 业务含义：生成当前+上一周期的 M/Q/Y 六条统计周期区间,供到期窗口归属判断
  -- 数据来源：sys_fun_deal_date 具名参数(9~17 对应当期/上期初末)
  -- 处理逻辑：UNION ALL 六行(M/Q/Y 当期+上期),BGN_DT/END_DT 均为 DATE 类型
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_CDR_DTL_PERIOD (
      STAT_PERD, -- 统计周期：M-月,Q-季,Y-年
      BGN_DT,    -- 统计周期开始日期
      END_DT     -- 统计周期结束日期
  )
  SELECT 'M' AS STAT_PERD,
         TO_DATE(V_CURR_MONTH_BEGIN, 'yyyymmdd') AS BGN_DT,
         TO_DATE(V_CURR_MONTH_END, 'yyyymmdd') AS END_DT
    FROM dual
  UNION ALL
  SELECT 'Q' AS STAT_PERD,
         TO_DATE(V_CURR_QUARTER_BEGIN, 'yyyymmdd') AS BGN_DT,
         TO_DATE(V_CURR_QUARTER_END, 'yyyymmdd') AS END_DT
    FROM dual
  UNION ALL
  SELECT 'Y' AS STAT_PERD,
         TO_DATE(V_CURR_YEAR_BEGIN, 'yyyymmdd') AS BGN_DT,
         TO_DATE(V_CURR_YEAR_END, 'yyyymmdd') AS END_DT
    FROM dual
  UNION ALL
  SELECT 'M' AS STAT_PERD,
         TO_DATE(V_PREV_MONTH_BEGIN, 'yyyymmdd') AS BGN_DT,
         TO_DATE(V_PREV_MONTH_END, 'yyyymmdd') AS END_DT
    FROM dual
  UNION ALL
  SELECT 'Q' AS STAT_PERD,
         TO_DATE(V_PREV_QUARTER_BEGIN, 'yyyymmdd') AS BGN_DT,
         TO_DATE(V_PREV_QUARTER_END, 'yyyymmdd') AS END_DT
    FROM dual
  UNION ALL
  SELECT 'Y' AS STAT_PERD,
         TO_DATE(V_PREV_YEAR_BEGIN, 'yyyymmdd') AS BGN_DT,
         TO_DATE(V_PREV_YEAR_END, 'yyyymmdd') AS END_DT
    FROM dual;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：生成统计周期中间表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第3段处理开始：生成到期产品源中间表
  -- 业务含义：提取当期有明确到期日的定期存款与理财到期产品(含产品级金额/到期日)
  -- 数据来源：DWD_ACCT_DEPO(FIX_CURNT_FLG='1'且非通知存款)、DWD_ACCT_FIN(剔除开放理财1/3)
  --          + DWS_CUST_ASSE_LIAB(CA：客户号+法人行号关联,BAL_TYPE='1',口径15)
  -- 处理逻辑：两段UNION后复制生成承接类型0(同客户存款+理财合并到期)
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_CDR_DTL_MATURE_SRC (
      CUST_ID,             -- 客户编号
      STATIS_TYP,          -- 承接类型：0-全部,1-存款,2-理财
      ACCT_ID,             -- 账户
      PRDKT_ID,            -- 产品编号
      PRDKT_NAME,          -- 产品名称
      EXPR_AMT,            -- 到期金额
      EXPR_DT,             -- 到期日期
      PERSN_LEGAL_BK_CODE, -- 法人行号
      ORG_ID               -- 归属机构
  )
  SELECT d.CUST_ID                                            AS CUST_ID,             -- 客户编号
         '1'                                                  AS STATIS_TYP,          -- 承接类型：1-存款
         d.ACCT_ID                                            AS ACCT_ID,             -- 账户
         d.PRDKT_ID                                           AS PRDKT_ID,            -- 产品编号
         d.PRDKT_NAME                                         AS PRDKT_NAME,          -- 产品名称
         sum(NVL(d.BAL, 0))                                        AS EXPR_AMT,            -- 到期金额
         TO_DATE(REPLACE(SUBSTR(d.EXPR_DATE, 1, 10), '-', ''), 'yyyymmdd') AS EXPR_DT,
         CA.PERSN_LEGAL_BK_CODE                                AS PERSN_LEGAL_BK_CODE, -- 法人行号
         CA.ORG_ID                                             AS ORG_ID               -- 归属机构
    FROM DWD_ACCT_DEPO d                                      -- 存款账户
  INNER JOIN DWS_CUST_ASSE_LIAB CA
  ON CA.CUST_ID = D.CUST_ID
  AND CA.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE
   WHERE d.FIX_CURNT_FLG = '1'                                -- 0-活期,1-定期
     AND NVL(d.PRDKT_CATE_BIG, '') <> '04'                    -- 剔除通知存款
     AND d.EXPR_DATE IS NOT NULL
     AND CA.DATA_DATE = V_SYSDAT
     AND CA.BAL_TYPE = '1'                                     -- 统一取余额类型(口径15)
     group by d.CUST_ID,
     d.ACCT_ID,
     d.PRDKT_ID,
     d.PRDKT_NAME,
     TO_DATE(REPLACE(SUBSTR(d.EXPR_DATE, 1, 10), '-', ''), 'yyyymmdd'),
     CA.PERSN_LEGAL_BK_CODE,
     CA.ORG_ID
  UNION ALL
  SELECT f.CUST_ID                                            AS CUST_ID,             -- 客户编号
         '2'                                                  AS STATIS_TYP,          -- 承接类型：2-理财
         f.ACCT_ID                                            AS ACCT_ID,             -- 账户
         f.PRDKT_ID                                           AS PRDKT_ID,            -- 产品编号
         f.PRDKT_NAME                                         AS PRDKT_NAME,          -- 产品名称
         SUM(NVL(f.FIN_AMT, 0))                                    AS EXPR_AMT,            -- 到期金额
         TO_DATE(REPLACE(SUBSTR(f.EXPR_DATE, 1, 10), '-', ''), 'yyyymmdd') AS EXPR_DT,
         CA.PERSN_LEGAL_BK_CODE                                AS PERSN_LEGAL_BK_CODE, -- 法人行号
         CA.ORG_ID                                             AS ORG_ID               -- 归属机构
    FROM DWD_ACCT_FIN f                                       -- 理财账户
    INNER JOIN DWS_CUST_ASSE_LIAB CA
  ON CA.CUST_ID = F.CUST_ID
  AND CA.PERSN_LEGAL_BK_CODE = F.PERSN_LEGAL_BK_CODE
   WHERE TRIM(f.EXPR_DATE) IS NOT NULL                        -- 有明确到期日的理财纳入到期范围；开放式理财分类代码待业务确认
     AND NVL(f.PRDKT_CATE_BIG, '') NOT IN ('1','3')            --理财产品大类 1代销-开放 2代销-封闭  3自营-开放 4自营-封闭
     AND CA.DATA_DATE = V_SYSDAT 
     AND CA.BAL_TYPE = '1'                                     -- 统一取余额类型(口径15)
  group by f.CUST_ID,
  f.ACCT_ID,
  f.PRDKT_ID,
  f.PRDKT_NAME,
  TO_DATE(REPLACE(SUBSTR(f.EXPR_DATE, 1, 10), '-', ''), 'yyyymmdd'),
  CA.PERSN_LEGAL_BK_CODE,
  CA.ORG_ID;
  -- 承接类型0：同客户存款和理财到期产品汇总(按客户+机构维度)。
  INSERT INTO TMP_CDR_DTL_MATURE_SRC (
      CUST_ID, STATIS_TYP, ACCT_ID, PRDKT_ID, PRDKT_NAME, EXPR_AMT, EXPR_DT, PERSN_LEGAL_BK_CODE, ORG_ID
  )
  SELECT CUST_ID, '0', ACCT_ID, PRDKT_ID, PRDKT_NAME, EXPR_AMT, EXPR_DT, PERSN_LEGAL_BK_CODE, ORG_ID
    FROM TMP_CDR_DTL_MATURE_SRC
   WHERE STATIS_TYP IN ('1', '2');

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：生成到期产品源中间表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第4段处理开始：生成到期窗口中间表
  -- 业务含义：三个日期字段(FIRST_EXPR_DT/LAST_EXPR_DT/TAKE_END_DT_30D)均按STATIS_TYP=0
  --           (全部产品)统一计算(口径40),金额(EXPR_AMT/MATURE_TTL_AMT)按类型独立汇总
  -- 数据来源：TMP_CDR_DTL_MATURE_SRC × TMP_CDR_DTL_PERIOD
  -- 处理逻辑：单条INSERT,统一窗口子查询w × 按类型金额子查询a,一次JOIN完成
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 统一窗口(口径40)：w子查询提供三个日期字段(仅STATIS_TYP=0计算),a子查询提供按类型金额
  INSERT INTO TMP_CDR_DTL_DUE_WIN (
      STAT_PERD,            -- 统计周期：M-月,Q-季,Y-年
      BGN_DT,               -- 统计周期开始日期
      END_DT,               -- 统计周期结束日期
      CUST_ID,              -- 客户编号
      STATIS_TYP,           -- 承接类型：0-全部,1-存款,2-理财
      FIRST_EXPR_DT,        -- 本期第一笔到期日期(统一,来自STATIS_TYP=0)
      LAST_EXPR_DT,         -- 本期最后一笔到期日期(统一,来自STATIS_TYP=0)
      EXPR_AMT,             -- 已到期金额(按类型独立)
      MATURE_TTL_AMT,       -- 总到期金额(按类型独立)
      TAKE_END_DT_30D,      -- 30天承接窗口结束日期(统一,来自STATIS_TYP=0)
      PERSN_LEGAL_BK_CODE,  -- 法人行号
      ORG_ID                -- 归属机构
  )
  SELECT w.STAT_PERD,
         w.BGN_DT,
         w.END_DT,
         a.CUST_ID,
         a.STATIS_TYP,                                          -- 0-全部/1-存款/2-理财
         w.FIRST_EXPR_DT,                                       -- 统一窗口(全部产品最早到期日)
         w.LAST_EXPR_DT,                                        -- 统一窗口(全部产品最晚到期日)
         a.EXPR_AMT,                                            -- 金额按类型独立
         a.MATURE_TTL_AMT,                                      -- 金额按类型独立
         w.TAKE_END_DT_30D,                                     -- 统一窗口
         a.PERSN_LEGAL_BK_CODE,
         a.ORG_ID
    FROM (
          -- 统一窗口子查询w：仅STATIS_TYP=0(全部产品)计算FIRST/LAST_EXPR_DT + TAKE_END_DT_30D
          SELECT g.STAT_PERD, g.BGN_DT, g.END_DT, g.CUST_ID,
                 g.PERSN_LEGAL_BK_CODE, g.ORG_ID,
                 g.FIRST_EXPR_DT, g.LAST_EXPR_DT,
                 NVL(
                     -- 窗口结束点优先级(口径16)：初始=最后一笔到期日+30天；
                     -- 若下一期到期日落在该+30范围内,取下一期到期日前一日为最终结束点
                     (SELECT MIN(n.EXPR_DT) - 1
                       FROM TMP_CDR_DTL_MATURE_SRC n
                       WHERE n.CUST_ID = g.CUST_ID
                         AND n.STATIS_TYP = '0'                                      -- 统一窗口：查全部产品
                         AND n.PERSN_LEGAL_BK_CODE = g.PERSN_LEGAL_BK_CODE
                         AND n.ORG_ID = g.ORG_ID
                         AND n.EXPR_DT > g.LAST_EXPR_DT
                         AND n.EXPR_DT <= g.LAST_EXPR_DT + 30),
                     g.LAST_EXPR_DT + 30
                 ) AS TAKE_END_DT_30D
            FROM (
                  SELECT p.STAT_PERD, p.BGN_DT, p.END_DT, m.CUST_ID,
                         m.PERSN_LEGAL_BK_CODE, m.ORG_ID,
                         MIN(m.EXPR_DT) AS FIRST_EXPR_DT,
                         MAX(m.EXPR_DT) AS LAST_EXPR_DT
                    FROM TMP_CDR_DTL_MATURE_SRC m
                    JOIN TMP_CDR_DTL_PERIOD p
                      ON m.EXPR_DT BETWEEN p.BGN_DT AND p.END_DT
                   WHERE m.STATIS_TYP = '0'                                          -- 仅STATIS_TYP=0计算统一窗口
                   GROUP BY p.STAT_PERD, p.BGN_DT, p.END_DT, m.CUST_ID, m.PERSN_LEGAL_BK_CODE, m.ORG_ID
                 ) g
         ) w
    JOIN (
          -- 按类型金额子查询a：STATIS_TYP=0(全部)+1(存款)+2(理财)各自汇总金额
          SELECT p.STAT_PERD, p.BGN_DT, p.END_DT, m.CUST_ID, m.STATIS_TYP,
                 m.PERSN_LEGAL_BK_CODE, m.ORG_ID,
                 -- 已到期金额截止日=跑批日V_SYSDAT(口径12/T-1)
                 SUM(CASE WHEN m.EXPR_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                          THEN NVL(m.EXPR_AMT, 0) ELSE 0 END) AS EXPR_AMT,
                 SUM(NVL(m.EXPR_AMT, 0)) AS MATURE_TTL_AMT
            FROM TMP_CDR_DTL_MATURE_SRC m
            JOIN TMP_CDR_DTL_PERIOD p
              ON m.EXPR_DT BETWEEN p.BGN_DT AND p.END_DT
           WHERE m.STATIS_TYP IN ('0', '1', '2')                     -- 0=全部产品,1=存款,2=理财
           GROUP BY p.STAT_PERD, p.BGN_DT, p.END_DT, m.CUST_ID, m.STATIS_TYP, m.PERSN_LEGAL_BK_CODE, m.ORG_ID
         ) a
      ON a.STAT_PERD = w.STAT_PERD
     AND a.BGN_DT = w.BGN_DT
     AND a.END_DT = w.END_DT
     AND a.CUST_ID = w.CUST_ID
     AND a.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
     AND a.ORG_ID = w.ORG_ID;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：生成30天到期承接窗口';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第5段处理开始：生成购买产品源中间表
  -- 业务含义：提取客户在承接窗口内的购买记录(存款/理财/保险),用于承接与转化率计算
  -- 数据来源：DWD_ACCT_DEPO(定期非通知)、DWD_ACCT_FIN(非开放理财)、DWD_ACCT_INSUR
  -- 处理逻辑：购买日期统一为购买发生日期(口径19)：DEPO=INTRI_BGN_DATE；FIN=ESTAB/INTRI/ISSU顺序；INSUR=TX/BGN_INSUR顺序
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_CDR_DTL_PURCHASE_SRC (
      CUST_ID,             -- 客户编号
      PRDKT_TYP,          -- 购买产品类型：DEPO-存款,FIN-理财,INSUR-保险
      BUY_AMT,            -- 购买金额
      BUY_DT,             -- 购买日期
      PERSN_LEGAL_BK_CODE, -- 法人行号
      ORG_ID               -- 归属机构
  )
  SELECT d.CUST_ID                                            AS CUST_ID,             -- 客户编号
         'DEPO'                                               AS PRDKT_TYP,          -- 购买产品类型：存款
         NVL(d.BAL, 0)                                        AS BUY_AMT,            -- 购买金额
         TO_DATE(REPLACE(SUBSTR(d.INTRI_BGN_DATE, 1, 10), '-', ''), 'yyyymmdd') AS BUY_DT,
         d.PERSN_LEGAL_BK_CODE                                AS PERSN_LEGAL_BK_CODE, -- 法人行号
         d.OPEN_ACCT_ORG                                      AS ORG_ID               -- 归属机构
    FROM DWD_ACCT_DEPO d                                      -- 存款账户
   WHERE d.FIX_CURNT_FLG = '1'
     AND NVL(d.PRDKT_CATE_BIG, '#') <> '04'
     AND d.INTRI_BGN_DATE IS NOT NULL
  UNION ALL
  SELECT f.CUST_ID                                            AS CUST_ID,             -- 客户编号
         'FIN'                                                AS PRDKT_TYP,          -- 购买产品类型：理财
         NVL(f.FIN_AMT, 0)                                    AS BUY_AMT,            -- 购买金额
         TO_DATE(REPLACE(SUBSTR(COALESCE(f.ESTAB_DATE, f.INTRI_BGN_DATE, f.ISSU_DATE), 1, 10), '-', ''), 'yyyymmdd') AS BUY_DT,
         f.PERSN_LEGAL_BK_CODE                                AS PERSN_LEGAL_BK_CODE, -- 法人行号
         f.OPRT_ORG                                           AS ORG_ID               -- 归属机构
    FROM DWD_ACCT_FIN f                                       -- 理财账户
   WHERE NVL(f.PRDKT_CATE_BIG, '#') NOT IN ('1','3')          -- 剔除开放式理财(口径3: PRDKT_CATE_BIG=1或3为开放式),与到期源过滤一致
     AND COALESCE(f.ESTAB_DATE, f.INTRI_BGN_DATE, f.ISSU_DATE) IS NOT NULL
  UNION ALL
  SELECT i.CUST_ID                                            AS CUST_ID,             -- 客户编号
         'INSUR'                                              AS PRDKT_TYP,          -- 购买产品类型：保险
         NVL(i.INSUR_AMT, 0)                                  AS BUY_AMT,            -- 购买金额
         TO_DATE(REPLACE(SUBSTR(COALESCE(i.TX_DATE, i.BGN_INSUR_DATE), 1, 10), '-', ''), 'yyyymmdd') AS BUY_DT,
         i.PERSN_LEGAL_BK_CODE                                AS PERSN_LEGAL_BK_CODE, -- 法人行号
         i.MKT_ORG                                             AS ORG_ID               -- 归属机构
    FROM DWD_ACCT_INSUR i                                     -- 保险账户
   WHERE COALESCE(i.TX_DATE, i.BGN_INSUR_DATE) IS NOT NULL;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段业务逻辑处理完成：生成购买产品源中间表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5 -- 第6段处理开始：生成承接金额中间表
  -- 业务含义：按客户+承接类型汇总30天窗口内各类购买金额与首次购买日期
  -- 数据来源：TMP_CDR_DTL_DUE_WIN × TMP_CDR_DTL_PURCHASE_SRC(客户号+法人行号关联,计算单位=客户+法人行)
  -- 处理逻辑：TAKE_AMT_30D 仅统计DEPO/FIN(长期化)；购买计入到期产品所属原统计周期(口径26)
  --***************************************
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  -- DEFECT-006 修复(2026-08-01): 承接金额不再按 STAT_PERD 聚合写入 TAKE_AMT 中间表,
  -- 改为在第9段最终写入明细时按统计周期实例(BGN_DT/END_DT)内联计算,
  -- 避免上季/上月与当季/当月周期合并导致的购买金额错配。
  -- TMP_CDR_DTL_TAKE_AMT 表结构保留(第1段仍 TRUNCATE), 不再生成数据。

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6段业务逻辑处理完成：生成30天承接金额';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5.1 -- 第6.1段处理开始：生成跨类型转化金额中间表(优化:预聚合替代关联子查询)
  -- 业务含义：理财到期转定期金额(STATIS_TYP=2)、定期到期转理财金额(STATIS_TYP=1),按类型预聚合
  -- 数据来源：TMP_CDR_DTL_TAKE_AMT
  -- 处理逻辑：按 STAT_PERD+CUST_ID+STATIS_TYP+PERSN_LEGAL_BK_CODE 分组(口径11),避免明细层跨类型混计
  --***************************************
  V_NO_ID := '6.1';
  V_BGN_DATE := SYSDATE;

  -- DEFECT-006 修复(2026-08-01): 跨类型转化金额同样改为第9段内联计算(按周期实例),
  -- TMP_CDR_DTL_CROSS_CONV 表结构保留, 不再生成数据。

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6.1段业务逻辑处理完成：生成跨类型转化金额中间表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.6 -- 第7段处理开始：生成客户基础及余额中间表
  -- 业务含义：客户名称/等级/管户经理及当前余额(AUM/活期/定期/理财),供明细展示与留存率计算
  -- 数据来源：DWD_CUST_INDV_INFO、DWS_CUST_LVL_INFO(DATA_DATE=V_SYSDAT)、DWD_CUST_MAN(MNG_TYP='1')
  --          + DWS_CUST_ASSE_LIAB(当前余额,DATA_DATE=V_SYSDAT且BAL_TYPE='1',按客户+法人行聚合)
  -- 处理逻辑：LEFT JOIN补属性,余额统一按客户号+法人行号口径
  --***************************************
  V_NO_ID := '7';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_CDR_DTL_CUST_BASE (
      CUST_ID,             -- 客户编号
      CUST_NAME,           -- 客户名称
      CUST_LVL,            -- 客户等级
      POST_ID,             -- 管户经理
      PERSN_LEGAL_BK_CODE, -- 法人行号
      DEPO_CURNT_DEPO_BAL, -- 活期余额
      FIXD_DEPO_BAL,       -- 定期余额
      FIN_AMT,             -- 理财余额
      AUM_BAL              -- 当前AUM余额
  )
  SELECT c.CUST_ID                                           AS CUST_ID,             -- 客户编号
         c.CUST_NAME                                         AS CUST_NAME,           -- 客户名称
         CL.CUST_LVL                                         AS CUST_LVL,            -- 客户等级
         CM.MNGR_POST_ID                                     AS POST_ID,             -- 管户经理
         C.PERSN_LEGAL_BK_CODE                               AS PERSN_LEGAL_BK_CODE, -- 归属机构
         NVL(b.DEPO_CURNT_DEPO_BAL, 0)                       AS DEPO_CURNT_DEPO_BAL, -- 活期余额
         NVL(b.FIXD_DEPO_BAL, 0)                             AS FIXD_DEPO_BAL,       -- 定期余额
         NVL(b.FIN_AMT, 0)                                   AS FIN_AMT,              -- 理财余额
         NVL(b.AUM_BAL, 0)                                   AS AUM_BAL               -- 当前AUM余额
    FROM DWD_CUST_INDV_INFO c                                -- 客户基本信息
    LEFT JOIN DWS_CUST_LVL_INFO CL
           on CL.CUST_ID = C.CUST_ID
          and CL.PERSN_LEGAL_BK_CODE = C.PERSN_LEGAL_BK_CODE
          AND CL.DATA_DATE = V_SYSDAT
    LEFT JOIN DWD_CUST_MAN CM
           on CM.CUST_ID = C.cust_id
          and CM.PERSN_LEGAL_BK_CODE = C.PERSN_LEGAL_BK_CODE
          and CM.mng_typ = '1'
    LEFT JOIN (
          SELECT a.CUST_ID                                    AS CUST_ID,             -- 客户编号
                 A.PERSN_LEGAL_BK_CODE                        AS PERSN_LEGAL_BK_CODE, --法人行号
                 SUM(NVL(a.DEPO_CURNT_DEPO_BAL, 0))           AS DEPO_CURNT_DEPO_BAL, -- 活期余额
                 SUM(NVL(a.DEPO_BAL, 0))                      AS FIXD_DEPO_BAL,       -- 定期余额
                 SUM(NVL(a.FIN_BAL, 0))                       AS FIN_AMT,              -- 理财余额
                 SUM(NVL(a.AUM_BAL, 0))                       AS AUM_BAL               -- 当前AUM余额
            FROM DWS_CUST_ASSE_LIAB a                         -- 客户资产负债表
           WHERE a.DATA_DATE = V_SYSDAT                       -- 数据日期
             AND a.BAL_TYPE = '1'                             -- 余额类型
           GROUP BY a.CUST_ID,A.PERSN_LEGAL_BK_CODE
         ) b
      ON b.CUST_ID = c.CUST_ID
     and B.PERSN_LEGAL_BK_CODE = C.PERSN_LEGAL_BK_CODE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第7段业务逻辑处理完成：生成客户基础及余额中间表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.7 -- 第8段处理开始：生成AUM中间表
  -- 业务含义：生成"本期第一笔到期日前一日"的AUM基准(PREV),作为资产留存率分母
  -- 数据来源：TMP_CDR_DTL_DUE_WIN × DWS_CUST_ASSE_LIAB(DATA_DATE=FIRST_EXPR_DT-1,BAL_TYPE='1',客户+法人行关联)
  -- 处理逻辑：LEFT JOIN缺失快照按0处理(口径24)
  --***************************************
  V_NO_ID := '8';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_CDR_DTL_AUM_BAL (
      STAT_PERD,            -- 统计周期：M-月,Q-季,Y-年
      CUST_ID,              -- 客户编号
      STATIS_TYP,           -- 承接类型：0-全部,1-存款,2-理财
      AUM_TYP,              -- AUM类型：PREV-第一笔到期前一日,CURR-当前日
      DATA_DATE,            -- AUM数据日期
      AUM_BAL,              -- AUM余额
      PERSN_LEGAL_BK_CODE   -- 法人行号(计算单位=客户+法人行,口径23)
  )
  SELECT w.STAT_PERD                                         AS STAT_PERD,  -- 统计周期：M-月,Q-季,Y-年
         w.CUST_ID                                           AS CUST_ID,    -- 客户编号
         w.STATIS_TYP                                        AS STATIS_TYP, -- 承接类型：0-全部,1-存款,2-理财
         'PREV'                                              AS AUM_TYP,    -- AUM类型：第一笔到期前一日
         TO_CHAR(w.FIRST_EXPR_DT - 1, 'yyyymmdd')            AS DATA_DATE,  -- AUM数据日期
         SUM(NVL(h.AUM_BAL, 0))                              AS AUM_BAL,    -- AUM余额
         w.PERSN_LEGAL_BK_CODE                               AS PERSN_LEGAL_BK_CODE
    FROM TMP_CDR_DTL_DUE_WIN w
    LEFT JOIN DWS_CUST_ASSE_LIAB h                           -- 客户资产负债表
      ON h.CUST_ID = w.CUST_ID
      and H.PERSN_LEGAL_BK_CODE = W.PERSN_LEGAL_BK_CODE
     AND h.DATA_DATE = TO_CHAR(w.FIRST_EXPR_DT - 1, 'yyyymmdd')
     AND h.BAL_TYPE = '1'                                    -- 余额类型
   GROUP BY w.STAT_PERD, w.CUST_ID, w.STATIS_TYP, TO_CHAR(w.FIRST_EXPR_DT - 1, 'yyyymmdd'), w.PERSN_LEGAL_BK_CODE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第8段业务逻辑处理完成：生成当前和历史AUM中间表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.8 -- 第9段处理开始：两期分离计算与验证(v3.0.0,单个BEGIN...END分段落)
  -- 业务含义：本期/上期/验证逻辑位于同一个匿名块内,以注释段落分隔,界限清晰
  -- 数据来源：DUE_WIN×TAKE_AMT×CUST_BASE×AUM_BAL×CROSS_CONV(关联键均不含ORG_ID,口径23)
  -- 处理逻辑：9.0冻结快照 / 9.1本期计算段(C1/C2) / 9.2上期计算段(P1/P2) / 9.3验证段(V1,FAIL即中止)
  --***************************************
  V_NO_ID := '9';
  V_BGN_DATE := SYSDATE;

  DECLARE
    V_FAIL_CNT INTEGER := 0;   -- 验证段失败计数(块级局部变量)
  BEGIN
  -- 9.0 上期冻结快照(供验证模块比对18基础字段是否被修改)
  INSERT INTO TMP_CDR_DTL_FREEZE_LOG (
      BATCH_DATE, PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
      DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
      EXPR_AMT, MATURE_TTL_AMT, TAKE_RATE, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
      FIX_DEPO_TAKE_RATE, CNTCT_STATE, UNDTAKE_STATE, FIXED_FIN_MATURE_TRAN_INSUR_AMT,
      FIN_MATURE_TRAN_FIXED_AMT, FIXED_MATURE_TRAN_FIN_AMT, FRST_MATURE_PK_BF_DAY_AUM_BAL,
      LAST_END_DATE, POST_ID, ORG_ID
  )
  SELECT V_SYSDAT, PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
         DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
         EXPR_AMT, MATURE_TTL_AMT, TAKE_RATE, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
         FIX_DEPO_TAKE_RATE, CNTCT_STATE, UNDTAKE_STATE, FIXED_FIN_MATURE_TRAN_INSUR_AMT,
         FIN_MATURE_TRAN_FIXED_AMT, FIXED_MATURE_TRAN_FIN_AMT, FRST_MATURE_PK_BF_DAY_AUM_BAL,
         LAST_END_DATE, POST_ID, ORG_ID
    FROM ADS_CUST_DEADLINE_RMND_DTL
   WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END);
  COMMIT;
      V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '上期冻结快照完成：TMP_CDR_DTL_FREEZE_LOG';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        '9',
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- ========== 【本期计算段】开始(边界：END_DT=当期结束日,DATA_DATE=V_SYSDAT)==========
    V_NO_ID := 'C1';
    V_BGN_DATE := SYSDATE;

    INSERT INTO TMP_CDR_DTL_CURR_STAGE (
        PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
        DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
        EXPR_AMT, MATURE_TTL_AMT, TAKE_RATE, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
        FIX_DEPO_TAKE_RATE, CNTCT_STATE, UNDTAKE_STATE, FIXED_FIN_MATURE_TRAN_INSUR_AMT,
        FIN_MATURE_TRAN_FIXED_AMT, FIXED_MATURE_TRAN_FIN_AMT, FRST_MATURE_PK_BF_DAY_AUM_BAL,
        LAST_END_DATE, POST_ID, ORG_ID
    )
    SELECT
        w.PERSN_LEGAL_BK_CODE,
        V_SYSDAT                                                   AS DATA_DATE,   -- 本期行: DATA_DATE=跑批日期(口径37)
        w.CUST_ID,
        cb.CUST_NAME,
        cb.CUST_LVL,
        cb.DEPO_CURNT_DEPO_BAL,
        cb.FIXD_DEPO_BAL,
        cb.FIN_AMT,
        w.STAT_PERD,
        w.STATIS_TYP,
        NVL(w.EXPR_AMT, 0),
        NVL(w.MATURE_TTL_AMT, 0),
        CASE WHEN NVL(w.EXPR_AMT, 0) = 0 THEN 0
             ELSE ROUND(NVL(t.TAKE_AMT_30D, 0) / w.EXPR_AMT * 100, 2)
        END,
        CASE WHEN w.STATIS_TYP = '1' THEN NVL(w.EXPR_AMT, 0) ELSE 0 END,
        CASE WHEN w.STATIS_TYP = '1' THEN NVL(w.MATURE_TTL_AMT, 0) ELSE 0 END,
        CASE WHEN w.STATIS_TYP = '1' AND NVL(w.EXPR_AMT, 0) <> 0
             THEN ROUND(NVL(t.BUY_DEPO_AMT_30D, 0) / w.EXPR_AMT * 100, 2)
             ELSE 0
        END,
        CASE WHEN EXISTS (
                   SELECT 1
                     FROM ADS_MKT_REC_INFO m
                    WHERE m.CUST_ID = w.CUST_ID
                      AND m.MKT_TIME IS NOT NULL
                      AND TO_DATE(REPLACE(SUBSTR(m.MKT_TIME, 1, 10), '-', ''), 'yyyymmdd')
                          BETWEEN w.FIRST_EXPR_DT AND w.TAKE_END_DT_30D
                      AND TO_DATE(REPLACE(SUBSTR(m.MKT_TIME, 1, 10), '-', ''), 'yyyymmdd')
                          <= TO_DATE(V_SYSDAT, 'yyyymmdd')
             ) THEN '1' ELSE '0'
        END,
        CASE WHEN NVL(w.EXPR_AMT, 0) > 0
                  AND NVL(t.TAKE_AMT_30D, 0) / w.EXPR_AMT >= 0.8
             THEN '1' ELSE '0'
        END,
        NVL(t.BUY_INSUR_AMT_30D, 0),
        NVL(cv.FIN_MATURE_TRAN_FIXED_AMT, 0),
        NVL(cv.FIXED_MATURE_TRAN_FIN_AMT, 0),
        NVL(ap.AUM_BAL, 0),
        TO_CHAR(w.LAST_EXPR_DT, 'yyyymmdd'),
        cb.POST_ID,
        w.ORG_ID
      FROM TMP_CDR_DTL_DUE_WIN w
      LEFT JOIN (
            SELECT w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE,
                   SUM(CASE WHEN p.PRDKT_TYP IN ('DEPO', 'FIN')
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS TAKE_AMT_30D,
                   SUM(CASE WHEN p.PRDKT_TYP = 'DEPO'
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_DEPO_AMT_30D,
                   SUM(CASE WHEN p.PRDKT_TYP = 'FIN'
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_FIN_AMT_30D,
                   SUM(CASE WHEN p.PRDKT_TYP = 'INSUR'
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_INSUR_AMT_30D
              FROM TMP_CDR_DTL_DUE_WIN w2
              LEFT JOIN TMP_CDR_DTL_PURCHASE_SRC p
                ON p.CUST_ID = w2.CUST_ID
               AND p.PERSN_LEGAL_BK_CODE = w2.PERSN_LEGAL_BK_CODE
               AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
               AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
             GROUP BY w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE
           ) t
        ON t.STAT_PERD = w.STAT_PERD
       AND t.BGN_DT = w.BGN_DT
       AND t.END_DT = w.END_DT
       AND t.CUST_ID = w.CUST_ID
       AND t.STATIS_TYP = w.STATIS_TYP
       AND t.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
      LEFT JOIN TMP_CDR_DTL_CUST_BASE cb
        ON cb.CUST_ID = w.CUST_ID
       AND cb.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
      LEFT JOIN TMP_CDR_DTL_AUM_BAL ap
        ON ap.STAT_PERD = w.STAT_PERD
       AND ap.CUST_ID = w.CUST_ID
       AND ap.STATIS_TYP = w.STATIS_TYP
       AND ap.AUM_TYP = 'PREV'
       AND ap.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
       AND ap.DATA_DATE = TO_CHAR(w.FIRST_EXPR_DT - 1, 'yyyymmdd')
      LEFT JOIN (
            SELECT ta.STAT_PERD, ta.BGN_DT, ta.END_DT, ta.CUST_ID, ta.STATIS_TYP, ta.PERSN_LEGAL_BK_CODE,
                   SUM(CASE WHEN ta.STATIS_TYP = '2' THEN ta.BUY_DEPO_AMT_30D ELSE 0 END) AS FIN_MATURE_TRAN_FIXED_AMT,
                   SUM(CASE WHEN ta.STATIS_TYP = '1' THEN ta.BUY_FIN_AMT_30D ELSE 0 END) AS FIXED_MATURE_TRAN_FIN_AMT
              FROM (
                    SELECT w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE,
                           SUM(CASE WHEN p.PRDKT_TYP = 'DEPO'
                                     AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                                     AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                                    THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_DEPO_AMT_30D,
                           SUM(CASE WHEN p.PRDKT_TYP = 'FIN'
                                     AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                                     AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                                    THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_FIN_AMT_30D
                      FROM TMP_CDR_DTL_DUE_WIN w2
                      LEFT JOIN TMP_CDR_DTL_PURCHASE_SRC p
                        ON p.CUST_ID = w2.CUST_ID
                       AND p.PERSN_LEGAL_BK_CODE = w2.PERSN_LEGAL_BK_CODE
                       AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                       AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                     GROUP BY w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE
                   ) ta
             GROUP BY ta.STAT_PERD, ta.BGN_DT, ta.END_DT, ta.CUST_ID, ta.STATIS_TYP, ta.PERSN_LEGAL_BK_CODE
           ) cv
        ON cv.STAT_PERD = w.STAT_PERD
       AND cv.BGN_DT = w.BGN_DT
       AND cv.END_DT = w.END_DT
       AND cv.CUST_ID = w.CUST_ID
       AND cv.STATIS_TYP = w.STATIS_TYP
       AND cv.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
     -- 边界检查：仅本期周期实例(END_DT=当期结束日),杜绝读取上期/历史实例
     WHERE (w.STAT_PERD = 'M' AND w.END_DT = TO_DATE(V_CURR_MONTH_END, 'yyyymmdd'))
        OR (w.STAT_PERD = 'Q' AND w.END_DT = TO_DATE(V_CURR_QUARTER_END, 'yyyymmdd'))
        OR (w.STAT_PERD = 'Y' AND w.END_DT = TO_DATE(V_CURR_YEAR_END, 'yyyymmdd'));

    -- 边界检查：本期结果 DATA_DATE 必须全部等于跑批日期(防止跨期引用)
    IF EXISTS (SELECT 1 FROM TMP_CDR_DTL_CURR_STAGE WHERE DATA_DATE <> V_SYSDAT) THEN
      RAISE_APPLICATION_ERROR(-20011, '本期边界检查失败：CURR_STAGE存在DATA_DATE<>V_SYSDAT行（跨期引用）');
    END IF;
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '本期计算段完成：CURR_STAGE生成并边界检查通过';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'C1',
        V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
    );

    V_NO_ID := 'C2';
    V_BGN_DATE := SYSDATE;
    INSERT INTO ADS_CUST_DEADLINE_RMND_DTL (
        PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
        DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
        EXPR_AMT, MATURE_TTL_AMT, TAKE_RATE, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
        FIX_DEPO_TAKE_RATE, CNTCT_STATE, UNDTAKE_STATE, FIXED_FIN_MATURE_TRAN_INSUR_AMT,
        FIN_MATURE_TRAN_FIXED_AMT, FIXED_MATURE_TRAN_FIN_AMT, FRST_MATURE_PK_BF_DAY_AUM_BAL,
        LAST_END_DATE, POST_ID, ORG_ID
    )
    SELECT
        PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
        DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
        EXPR_AMT, MATURE_TTL_AMT, TAKE_RATE, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
        FIX_DEPO_TAKE_RATE, CNTCT_STATE, UNDTAKE_STATE, FIXED_FIN_MATURE_TRAN_INSUR_AMT,
        FIN_MATURE_TRAN_FIXED_AMT, FIXED_MATURE_TRAN_FIN_AMT, FRST_MATURE_PK_BF_DAY_AUM_BAL,
        LAST_END_DATE, POST_ID, ORG_ID
      FROM TMP_CDR_DTL_CURR_STAGE;
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '本期计算段完成：写入ADS_CUST_DEADLINE_RMND_DTL';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'C2',
        V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
    );
    -- ========== 【本期计算段】结束 ==========
    -- ========== 【上期计算段】开始(边界：END_DT=上期结束日,DATA_DATE=上期期末日期)==========
    V_NO_ID := 'P1';
    V_BGN_DATE := SYSDATE;

    INSERT INTO TMP_CDR_DTL_PREV_STAGE (
        PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
        DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
        EXPR_AMT, MATURE_TTL_AMT, TAKE_RATE, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
        FIX_DEPO_TAKE_RATE, CNTCT_STATE, UNDTAKE_STATE, FIXED_FIN_MATURE_TRAN_INSUR_AMT,
        FIN_MATURE_TRAN_FIXED_AMT, FIXED_MATURE_TRAN_FIN_AMT, FRST_MATURE_PK_BF_DAY_AUM_BAL,
        LAST_END_DATE, POST_ID, ORG_ID
    )
    SELECT
        w.PERSN_LEGAL_BK_CODE,
        TO_CHAR(w.END_DT, 'yyyymmdd')                               AS DATA_DATE,   -- 上期行: DATA_DATE=期末日期(口径37)
        w.CUST_ID,
        cb.CUST_NAME,
        cb.CUST_LVL,
        cb.DEPO_CURNT_DEPO_BAL,
        cb.FIXD_DEPO_BAL,
        cb.FIN_AMT,
        w.STAT_PERD,
        w.STATIS_TYP,
        NVL(w.EXPR_AMT, 0),
        NVL(w.MATURE_TTL_AMT, 0),
        CASE WHEN NVL(w.EXPR_AMT, 0) = 0 THEN 0
             ELSE ROUND(NVL(t.TAKE_AMT_30D, 0) / w.EXPR_AMT * 100, 2)
        END,
        CASE WHEN w.STATIS_TYP = '1' THEN NVL(w.EXPR_AMT, 0) ELSE 0 END,
        CASE WHEN w.STATIS_TYP = '1' THEN NVL(w.MATURE_TTL_AMT, 0) ELSE 0 END,
        CASE WHEN w.STATIS_TYP = '1' AND NVL(w.EXPR_AMT, 0) <> 0
             THEN ROUND(NVL(t.BUY_DEPO_AMT_30D, 0) / w.EXPR_AMT * 100, 2)
             ELSE 0
        END,
        CASE WHEN EXISTS (
                   SELECT 1
                     FROM ADS_MKT_REC_INFO m
                    WHERE m.CUST_ID = w.CUST_ID
                      AND m.MKT_TIME IS NOT NULL
                      AND TO_DATE(REPLACE(SUBSTR(m.MKT_TIME, 1, 10), '-', ''), 'yyyymmdd')
                          BETWEEN w.FIRST_EXPR_DT AND w.TAKE_END_DT_30D
                      AND TO_DATE(REPLACE(SUBSTR(m.MKT_TIME, 1, 10), '-', ''), 'yyyymmdd')
                          <= TO_DATE(V_SYSDAT, 'yyyymmdd')
             ) THEN '1' ELSE '0'
        END,
        CASE WHEN NVL(w.EXPR_AMT, 0) > 0
                  AND NVL(t.TAKE_AMT_30D, 0) / w.EXPR_AMT >= 0.8
             THEN '1' ELSE '0'
        END,
        NVL(t.BUY_INSUR_AMT_30D, 0),
        NVL(cv.FIN_MATURE_TRAN_FIXED_AMT, 0),
        NVL(cv.FIXED_MATURE_TRAN_FIN_AMT, 0),
        NVL(ap.AUM_BAL, 0),
        TO_CHAR(w.LAST_EXPR_DT, 'yyyymmdd'),
        cb.POST_ID,
        w.ORG_ID
      FROM TMP_CDR_DTL_DUE_WIN w
      LEFT JOIN (
            SELECT w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE,
                   SUM(CASE WHEN p.PRDKT_TYP IN ('DEPO', 'FIN')
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS TAKE_AMT_30D,
                   SUM(CASE WHEN p.PRDKT_TYP = 'DEPO'
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_DEPO_AMT_30D,
                   SUM(CASE WHEN p.PRDKT_TYP = 'FIN'
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_FIN_AMT_30D,
                   SUM(CASE WHEN p.PRDKT_TYP = 'INSUR'
                             AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                             AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                            THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_INSUR_AMT_30D
              FROM TMP_CDR_DTL_DUE_WIN w2
              LEFT JOIN TMP_CDR_DTL_PURCHASE_SRC p
                ON p.CUST_ID = w2.CUST_ID
               AND p.PERSN_LEGAL_BK_CODE = w2.PERSN_LEGAL_BK_CODE
               AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
               AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
             GROUP BY w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE
           ) t
        ON t.STAT_PERD = w.STAT_PERD
       AND t.BGN_DT = w.BGN_DT
       AND t.END_DT = w.END_DT
       AND t.CUST_ID = w.CUST_ID
       AND t.STATIS_TYP = w.STATIS_TYP
       AND t.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
      LEFT JOIN TMP_CDR_DTL_CUST_BASE cb
        ON cb.CUST_ID = w.CUST_ID
       AND cb.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
      LEFT JOIN TMP_CDR_DTL_AUM_BAL ap
        ON ap.STAT_PERD = w.STAT_PERD
       AND ap.CUST_ID = w.CUST_ID
       AND ap.STATIS_TYP = w.STATIS_TYP
       AND ap.AUM_TYP = 'PREV'
       AND ap.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
       AND ap.DATA_DATE = TO_CHAR(w.FIRST_EXPR_DT - 1, 'yyyymmdd')
      LEFT JOIN (
            SELECT ta.STAT_PERD, ta.BGN_DT, ta.END_DT, ta.CUST_ID, ta.STATIS_TYP, ta.PERSN_LEGAL_BK_CODE,
                   SUM(CASE WHEN ta.STATIS_TYP = '2' THEN ta.BUY_DEPO_AMT_30D ELSE 0 END) AS FIN_MATURE_TRAN_FIXED_AMT,
                   SUM(CASE WHEN ta.STATIS_TYP = '1' THEN ta.BUY_FIN_AMT_30D ELSE 0 END) AS FIXED_MATURE_TRAN_FIN_AMT
              FROM (
                    SELECT w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE,
                           SUM(CASE WHEN p.PRDKT_TYP = 'DEPO'
                                     AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                                     AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                                    THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_DEPO_AMT_30D,
                           SUM(CASE WHEN p.PRDKT_TYP = 'FIN'
                                     AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                                     AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                                    THEN NVL(p.BUY_AMT, 0) ELSE 0 END) AS BUY_FIN_AMT_30D
                      FROM TMP_CDR_DTL_DUE_WIN w2
                      LEFT JOIN TMP_CDR_DTL_PURCHASE_SRC p
                        ON p.CUST_ID = w2.CUST_ID
                       AND p.PERSN_LEGAL_BK_CODE = w2.PERSN_LEGAL_BK_CODE
                       AND p.BUY_DT BETWEEN w2.FIRST_EXPR_DT AND w2.TAKE_END_DT_30D
                       AND p.BUY_DT <= TO_DATE(V_SYSDAT, 'yyyymmdd')
                     GROUP BY w2.STAT_PERD, w2.BGN_DT, w2.END_DT, w2.CUST_ID, w2.STATIS_TYP, w2.PERSN_LEGAL_BK_CODE
                   ) ta
             GROUP BY ta.STAT_PERD, ta.BGN_DT, ta.END_DT, ta.CUST_ID, ta.STATIS_TYP, ta.PERSN_LEGAL_BK_CODE
           ) cv
        ON cv.STAT_PERD = w.STAT_PERD
       AND cv.BGN_DT = w.BGN_DT
       AND cv.END_DT = w.END_DT
       AND cv.CUST_ID = w.CUST_ID
       AND cv.STATIS_TYP = w.STATIS_TYP
       AND cv.PERSN_LEGAL_BK_CODE = w.PERSN_LEGAL_BK_CODE
     -- 边界检查：仅上期周期实例(END_DT=上期结束日),数据来源=上一周期实例(口径38)
     WHERE (w.STAT_PERD = 'M' AND w.END_DT = TO_DATE(V_PREV_MONTH_END, 'yyyymmdd'))
        OR (w.STAT_PERD = 'Q' AND w.END_DT = TO_DATE(V_PREV_QUARTER_END, 'yyyymmdd'))
        OR (w.STAT_PERD = 'Y' AND w.END_DT = TO_DATE(V_PREV_YEAR_END, 'yyyymmdd'));

    -- 边界检查：上期结果 DATA_DATE 必须与上期期末日期一一对应(防止跨期引用)
    IF EXISTS (SELECT 1 FROM TMP_CDR_DTL_PREV_STAGE
                WHERE (STAT_PERD = 'M' AND DATA_DATE <> V_PREV_MONTH_END)
                   OR (STAT_PERD = 'Q' AND DATA_DATE <> V_PREV_QUARTER_END)
                   OR (STAT_PERD = 'Y' AND DATA_DATE <> V_PREV_YEAR_END)) THEN
      RAISE_APPLICATION_ERROR(-20012, '上期边界检查失败：PREV_STAGE存在DATA_DATE与上期期末不一致行（跨期引用）');
    END IF;
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '上期计算段完成：PREV_STAGE生成并边界检查通过';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'P1',
        V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
    );

    V_NO_ID := 'P2';
    V_BGN_DATE := SYSDATE;
    -- 定点更新：上期行仅更新7字段(口径35),缺失上期行整行补插
    MERGE INTO ADS_CUST_DEADLINE_RMND_DTL dst
    USING TMP_CDR_DTL_PREV_STAGE src
    ON (dst.STAT_PERD = src.STAT_PERD
        AND dst.DATA_DATE = src.DATA_DATE
        AND dst.CUST_ID = src.CUST_ID
        AND dst.STATIS_TYP = src.STATIS_TYP
        AND dst.PERSN_LEGAL_BK_CODE = src.PERSN_LEGAL_BK_CODE)
    WHEN MATCHED THEN UPDATE SET
        dst.TAKE_RATE = src.TAKE_RATE,
        dst.FIX_DEPO_TAKE_RATE = src.FIX_DEPO_TAKE_RATE,
        dst.UNDTAKE_STATE = src.UNDTAKE_STATE,
        dst.CNTCT_STATE = src.CNTCT_STATE,
        dst.FIXED_FIN_MATURE_TRAN_INSUR_AMT = src.FIXED_FIN_MATURE_TRAN_INSUR_AMT,
        dst.FIN_MATURE_TRAN_FIXED_AMT = src.FIN_MATURE_TRAN_FIXED_AMT,
        dst.FIXED_MATURE_TRAN_FIN_AMT = src.FIXED_MATURE_TRAN_FIN_AMT
    WHEN NOT MATCHED THEN INSERT (
        PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
        DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
        EXPR_AMT, MATURE_TTL_AMT, TAKE_RATE, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
        FIX_DEPO_TAKE_RATE, CNTCT_STATE, UNDTAKE_STATE, FIXED_FIN_MATURE_TRAN_INSUR_AMT,
        FIN_MATURE_TRAN_FIXED_AMT, FIXED_MATURE_TRAN_FIN_AMT, FRST_MATURE_PK_BF_DAY_AUM_BAL,
        LAST_END_DATE, POST_ID, ORG_ID
    ) VALUES (
        src.PERSN_LEGAL_BK_CODE, src.DATA_DATE, src.CUST_ID, src.CUST_NAME, src.CUST_LVL,
        src.DEPO_CURNT_DEPO_BAL, src.FIXD_DEPO_BAL, src.FIN_AMT, src.STAT_PERD, src.STATIS_TYP,
        src.EXPR_AMT, src.MATURE_TTL_AMT, src.TAKE_RATE, src.FIX_DEPO_MATURE_AMT, src.FIX_DEPO_MATURE_TTL_AMT,
        src.FIX_DEPO_TAKE_RATE, src.CNTCT_STATE, src.UNDTAKE_STATE, src.FIXED_FIN_MATURE_TRAN_INSUR_AMT,
        src.FIN_MATURE_TRAN_FIXED_AMT, src.FIXED_MATURE_TRAN_FIN_AMT, src.FRST_MATURE_PK_BF_DAY_AUM_BAL,
        src.LAST_END_DATE, src.POST_ID, src.ORG_ID
    );
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '上期计算段完成：仅更新7字段/补插缺失上期行';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'P2',
        V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
    );
    -- ========== 【上期计算段】结束 ==========
    -- ========== 【数据验证段】开始(冻结/一致性/互斥/值域/行数,FAIL即中止)==========
    V_NO_ID := 'V1';
    V_BGN_DATE := SYSDATE;

    -- V1: 上期18基础字段冻结校验(FREEZE_LOG快照 vs 目标表当前上期行)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'FREEZE_BASE_18',
           CASE WHEN NOT EXISTS (
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
                           DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
                           EXPR_AMT, MATURE_TTL_AMT, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
                           FRST_MATURE_PK_BF_DAY_AUM_BAL, LAST_END_DATE, POST_ID, ORG_ID
                      FROM TMP_CDR_DTL_FREEZE_LOG
                    MINUS
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
                           DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
                           EXPR_AMT, MATURE_TTL_AMT, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
                           FRST_MATURE_PK_BF_DAY_AUM_BAL, LAST_END_DATE, POST_ID, ORG_ID
                      FROM ADS_CUST_DEADLINE_RMND_DTL
                     WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
                AND NOT EXISTS (
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
                           DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
                           EXPR_AMT, MATURE_TTL_AMT, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
                           FRST_MATURE_PK_BF_DAY_AUM_BAL, LAST_END_DATE, POST_ID, ORG_ID
                      FROM ADS_CUST_DEADLINE_RMND_DTL
                     WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END)
                    MINUS
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
                           DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, STAT_PERD, STATIS_TYP,
                           EXPR_AMT, MATURE_TTL_AMT, FIX_DEPO_MATURE_AMT, FIX_DEPO_MATURE_TTL_AMT,
                           FRST_MATURE_PK_BF_DAY_AUM_BAL, LAST_END_DATE, POST_ID, ORG_ID
                      FROM TMP_CDR_DTL_FREEZE_LOG)
           THEN 'PASS' ELSE 'FAIL' END,
           '上期18基础字段冻结校验（口径34）', SYSDATE FROM dual;

    -- V2: 上期7更新字段一致性(目标表上期行 vs PREV_STAGE)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'PREV_7FIELDS_CONSISTENT',
           CASE WHEN NOT EXISTS (
                    SELECT STAT_PERD, DATA_DATE, CUST_ID, STATIS_TYP, PERSN_LEGAL_BK_CODE,
                           TAKE_RATE, FIX_DEPO_TAKE_RATE, UNDTAKE_STATE, CNTCT_STATE,
                           FIXED_FIN_MATURE_TRAN_INSUR_AMT, FIN_MATURE_TRAN_FIXED_AMT,
                           FIXED_MATURE_TRAN_FIN_AMT
                      FROM TMP_CDR_DTL_PREV_STAGE
                    MINUS
                    SELECT STAT_PERD, DATA_DATE, CUST_ID, STATIS_TYP, PERSN_LEGAL_BK_CODE,
                           TAKE_RATE, FIX_DEPO_TAKE_RATE, UNDTAKE_STATE, CNTCT_STATE,
                           FIXED_FIN_MATURE_TRAN_INSUR_AMT, FIN_MATURE_TRAN_FIXED_AMT,
                           FIXED_MATURE_TRAN_FIN_AMT
                      FROM ADS_CUST_DEADLINE_RMND_DTL
                     WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
           THEN 'PASS' ELSE 'FAIL' END,
           '上期7更新字段一致性校验（口径35）', SYSDATE FROM dual;

    -- V3: 本期结果不得包含上期日期(DATA_DATE互斥,防止跨期引用)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'C', 'CURR_NO_PREV_DATE',
           CASE WHEN EXISTS (SELECT 1 FROM TMP_CDR_DTL_CURR_STAGE
                              WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
                THEN 'FAIL' ELSE 'PASS' END,
           '本期结果与上期日期互斥校验', SYSDATE FROM dual;

    -- V4: 率值域与状态值域(两期独立校验)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'C', 'RATE_DOMAIN_CURR',
           CASE WHEN EXISTS (SELECT 1 FROM TMP_CDR_DTL_CURR_STAGE
                              WHERE TAKE_RATE IS NULL OR TAKE_RATE < 0
                                 OR FIX_DEPO_TAKE_RATE IS NULL OR FIX_DEPO_TAKE_RATE < 0
                                 OR CNTCT_STATE NOT IN ('0', '1')
                                 OR UNDTAKE_STATE NOT IN ('0', '1'))
                THEN 'FAIL' ELSE 'PASS' END,
           '本期率值/状态值域校验', SYSDATE FROM dual;
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'RATE_DOMAIN_PREV',
           CASE WHEN EXISTS (SELECT 1 FROM TMP_CDR_DTL_PREV_STAGE
                              WHERE TAKE_RATE IS NULL OR TAKE_RATE < 0
                                 OR FIX_DEPO_TAKE_RATE IS NULL OR FIX_DEPO_TAKE_RATE < 0
                                 OR CNTCT_STATE NOT IN ('0', '1')
                                 OR UNDTAKE_STATE NOT IN ('0', '1'))
                THEN 'FAIL' ELSE 'PASS' END,
           '上期率值/状态值域校验', SYSDATE FROM dual;

    -- V5: stage与目标表行数一致性(两期独立校验)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'C', 'ROWCOUNT_CONSISTENT_CURR',
           CASE WHEN (SELECT COUNT(*) FROM TMP_CDR_DTL_CURR_STAGE)
                  = (SELECT COUNT(*) FROM ADS_CUST_DEADLINE_RMND_DTL WHERE DATA_DATE = V_SYSDAT)
                THEN 'PASS' ELSE 'FAIL' END,
           '本期stage与目标表行数一致性', SYSDATE FROM dual;
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'ROWCOUNT_CONSISTENT_PREV',
           CASE WHEN (SELECT COUNT(*) FROM TMP_CDR_DTL_PREV_STAGE)
                  = (SELECT COUNT(*) FROM ADS_CUST_DEADLINE_RMND_DTL
                      WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
                THEN 'PASS' ELSE 'FAIL' END,
           '上期stage与目标表行数一致性', SYSDATE FROM dual;

    COMMIT;

    -- 任一FAIL即中止批次(防止污染数据后继续)
    SELECT COUNT(*) INTO V_FAIL_CNT
      FROM TMP_CDR_VALIDATE_RESULT
     WHERE BATCH_DATE = V_SYSDAT AND RESULT = 'FAIL';
    IF V_FAIL_CNT > 0 THEN
      RAISE_APPLICATION_ERROR(-20013, '数据验证失败：' || V_FAIL_CNT || ' 项校验未通过');
    END IF;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '数据验证段完成：两期计算结果准确性与独立性校验通过';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'V1',
        V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
    );
    -- ========== 【数据验证段】结束 ==========
  END;


  -- 当前周期只保留最新跑批快照；上期行冻结保留(口径34)；历史只保留最多三年。
  DELETE FROM ADS_CUST_DEADLINE_RMND_DTL d
   WHERE d.DATA_DATE <> V_SYSDAT
     AND d.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第9段业务逻辑处理完成：写入到期承接明细表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- 业务含义：任一环节异常时统一置返回码-1、回滚当前事务并记录错误日志后重抛
  -- 处理逻辑：EXCEPTION WHEN OTHERS → OUTCDE=-1 → ROLLBACK → SYS_PRC_STEP_LOGS(SQLERRM) → RAISE
  --***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END







;

-- DROP PROCEDURE crmdm.prc_ads_cust_deadline_rmnd_statis(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_deadline_rmnd_statis(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 到期承接统计表处理
  -- 存储过程编号: PRC_ADS_CUST_DEADLINE_RMND_STATIS
  -- 处理周期: 日
  -- 过程描述: 按机构向上汇总和客户经理维度生成到期承接统计
  -- 来源表: ADS_CUST_DEADLINE_RMND_DTL, DWS_CUST_ASSE_LIAB, DWD_SYS_ORG
  -- 目标表: ADS_CUST_DEADLINE_RMND_STATIS
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.5.0
  -- 关联需求: REQ-CUST-002
  -- 变更记录:
  --   v2.8.1: 1.注释规范化：补齐输入输出参数、变量、各处理段及列定义注释
  --           2.第4段改为按承接类型(STATIS_TYP 0-全部/1-定期存款/2-理财)分段独立计算并UNION ALL写入
  --   v2.6.0: 1.统计表方案B(口径36)：上期统计行冻结维度与基础列,仅更新6个率值列
  --           2.DATA_DATE双语义(口径37)：本期行=跑批日期V_SYSDAT,上期行=期末日期
  --           3.段1不再删除上期统计行,仅删除本期快照(口径34)
  --           4.第4段改为单个BEGIN...END块分段落(禁止嵌套过程)：本期计算段(C1/C2)/
  --             上期计算段(P1/P2)/数据验证段(V1),MERGE仅更新率值列；独立隔离存储与边界检查
  --   v2.8.0: 1.统计表回退15列(定期存款页签三指标由STATIS_TYP=1行复用,口径2/25)
  --           2.当前AUM关联移除ORG_ID(计算单位=客户+法人行,口径23)
  --           3.存款转理财限定STATIS_TYP=1、理财转存款限定STATIS_TYP=2、保险转化率按全部口径展示(口径17/18)
  --   v2.5.0: 1.资产承接率消除舍入误差(去内层ROUND)
  --           2.新增定期存款页签三指标:FIX_DEPO_EXPR_AMT/FIX_DEPO_TTL_EXPR_AMT/FIX_DEPO_UNDTAKE_RATE
  --           3.STAT_BASE/SRC增加FIX_DEPO_MATURE_AMT/FIX_DEPO_MATURE_TTL_AMT/FIX_DEPO_TAKE_RATE三列
  --   v2.4.0: 1.简化DELETE历史清理逻辑(去掉冗余周期末日校验,仅保留三年边界)
  --   v2.3.0: 跑批日期口径统一：V_SYSDAT为当前跑批数据日；上月末、上季末、上年末分别使用sys_fun_deal_date参数2、3、4。统计过程资产汇总及关联补齐客户号、法人行、归属机构三键
  --   v2.2.0: 1.客户数统计改为按客户+机构维度去重：COUNT(DISTINCT CUST_ID || '_' || ORG_ID)
  --           2.承接状态统计同步改为按客户+机构维度去重
  --   v2.1.0: 1.理财转存款转化率和存款转理财转化率指标已实现
  --           2.统计维度0-全部、1-存款、2-理财已实现
  --           3.客户承接率长期化产品剔除保险(待实现,已做注释)
  --           4.定期存款承接率需确认通知存款过滤(待实现,已做注释)
  --           5.DATA_DATE语义变更：统一使用周期结束日期(M-月末,Q-季末,Y-年末),清理逻辑同步更新
  ------------------------------------------------------------------
  V_PRC_DESC VARCHAR(100) := '到期承接统计表处理';                  -- 过程描述(日志用)
  V_PRC_NAME VARCHAR(64) := 'PRC_ADS_CUST_DEADLINE_RMND_STATIS';     -- 过程名称(日志用)
  V_LOG_MSG VARCHAR(4000);                                           -- 日志消息文本
  V_LOG_FLG INTEGER;                                                 -- 日志标志(0=成功,-1=异常)
  V_LOG_BUTTON INTEGER := 1;                                         -- 日志记录开关(1=记录)
  V_NO_ID VARCHAR(10);                                               -- 当前处理步骤编号
  V_BGN_DATE DATE;                                                   -- 当前步骤开始时间
  V_END_DATE DATE;                                                   -- 当前步骤结束时间
  V_DURA_DATE INTEGER;                                               -- 当前步骤耗时(秒)
  V_PREV_MONTH_END VARCHAR2(8);                                      -- 上月末：sys_fun_deal_date(V_SYSDAT,2)
  V_PREV_QUARTER_END VARCHAR2(8);                                    -- 上季末：sys_fun_deal_date(V_SYSDAT,3)
  V_PREV_YEAR_END VARCHAR2(8);                                       -- 上年末：sys_fun_deal_date(V_SYSDAT,4)
  V_CURR_MONTH_BEGIN VARCHAR2(8);                                    -- 当月初：sys_fun_deal_date(V_SYSDAT,9)
  V_CURR_QUARTER_BEGIN VARCHAR2(8);                                  -- 当季初：sys_fun_deal_date(V_SYSDAT,11)
  V_CURR_YEAR_BEGIN VARCHAR2(8);                                     -- 当年初：sys_fun_deal_date(V_SYSDAT,13)
  V_CURR_MONTH_END VARCHAR2(8);                                      -- 当月末：sys_fun_deal_date(V_SYSDAT,10)
  V_CURR_QUARTER_END VARCHAR2(8);                                    -- 当季末：sys_fun_deal_date(V_SYSDAT,12)
  V_CURR_YEAR_END VARCHAR2(8);                                       -- 当年末：sys_fun_deal_date(V_SYSDAT,14)
  V_HISTORY_CUTOFF_DATE VARCHAR2(8);                                 -- 三年历史清理边界：sys_fun_deal_date(V_SYSDAT,19)

BEGIN
  IF V_SYSDAT IS NULL OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$') THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_PREV_MONTH_END := sys_fun_deal_date(V_SYSDAT, 2);
  V_PREV_QUARTER_END := sys_fun_deal_date(V_SYSDAT, 3);
  V_PREV_YEAR_END := sys_fun_deal_date(V_SYSDAT, 4);
  V_CURR_MONTH_BEGIN := sys_fun_deal_date(V_SYSDAT, 9);
  V_CURR_QUARTER_BEGIN := sys_fun_deal_date(V_SYSDAT, 11);
  V_CURR_YEAR_BEGIN := sys_fun_deal_date(V_SYSDAT, 13);
  V_CURR_MONTH_END := sys_fun_deal_date(V_SYSDAT, 10);
  V_CURR_QUARTER_END := sys_fun_deal_date(V_SYSDAT, 12);
  V_CURR_YEAR_END := sys_fun_deal_date(V_SYSDAT, 14);
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);

  --***************************************
  -- 2.0 -- 第1段处理开始：清理当前快照和中间表
  -- 业务含义：幂等重跑准备——仅删除本期统计快照行(DATA_DATE=V_SYSDAT)及旧语义当期结束日行,
  --           严格保留上期统计行(口径34/36),并清空两张统计中间表
  -- 数据来源：ADS_CUST_DEADLINE_RMND_STATIS + TMP_CDR_STAT_BASE/TMP_CDR_STAT_SRC
  -- 处理逻辑：DELETE(本期快照+旧语义当期结束日) + TRUNCATE_TMP × 2
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  DELETE FROM ADS_CUST_DEADLINE_RMND_STATIS
   -- v2.6.0(口径28/34/37): 每日替换——删除当期周期区间内的本期统计快照行
   --                        (当月初/季初/年初~V_SYSDAT),上期统计行不删除
   WHERE (STATIS_CYCLE = 'M' AND DATA_DATE >= V_CURR_MONTH_BEGIN AND DATA_DATE <= V_SYSDAT)
      OR (STATIS_CYCLE = 'Q' AND DATA_DATE >= V_CURR_QUARTER_BEGIN AND DATA_DATE <= V_SYSDAT)
      OR (STATIS_CYCLE = 'Y' AND DATA_DATE >= V_CURR_YEAR_BEGIN AND DATA_DATE <= V_SYSDAT)
      -- 过渡期清理：旧语义生成的当期结束日行(仅首日存在,后续幂等无影响)
      OR (STATIS_CYCLE = 'M' AND DATA_DATE = V_CURR_MONTH_END)
      OR (STATIS_CYCLE = 'Q' AND DATA_DATE = V_CURR_QUARTER_END)
      OR (STATIS_CYCLE = 'Y' AND DATA_DATE = V_CURR_YEAR_END);
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_STAT_BASE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_STAT_SRC';
  -- v3.0.0: 两期隔离存储与验证日志
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_STAT_CURR_STAGE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_STAT_PREV_STAGE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_STAT_FREEZE_LOG';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_CDR_VALIDATE_RESULT';
  COMMIT;

  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：清理当前快照和中间表';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.1 -- 第2段处理开始：生成统计基础明细中间表
  -- 业务含义：将明细表当期/上期记录与当前AUM合并为统计基础行
  -- 数据来源：ADS_CUST_DEADLINE_RMND_DTL + DWS_CUST_ASSE_LIAB(当前AUM,DATA_DATE=V_SYSDAT且BAL_TYPE='1',客户+法人行聚合)
  -- 处理逻辑：仅取本期(DATA_DATE=V_SYSDAT)与上期(DATA_DATE=期末日期)行(支持较上月对比)；
  --           当前AUM关联键不含ORG_ID(口径23)
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_CDR_STAT_BASE (
      PERSN_LEGAL_BK_CODE,          -- 法人行号
      DATA_DATE,                    -- 数据日期(周期结束日)
      STAT_PERD,                    -- 统计周期(M/Q/Y)
      STATIS_TYP,                   -- 承接类型(0-全部/1-定期存款/2-理财)
      CUST_ID,                      -- 客户编号
      ORG_ID,                       -- 归属机构(DWS取值,与法人行1:1)
      POST_ID,                      -- 管户经理岗位ID
      EXPR_AMT,                     -- 已到期金额
      MATURE_TTL_AMT,               -- 总到期金额
      TAKE_RATE_30D,                -- 30天客户承接金额占比(来自明细TAKE_RATE)
      CUST_TAKE_FLG,                -- 承接状态(TAKE_AMT/EXPR_AMT>=80%为1)
      FIXED_MATURE_TRAN_FIN_AMT,    -- 定期到期转理财金额
      FIXED_FIN_MATURE_TRAN_INSUR_AMT, -- 到期转保险金额
      FIN_MATURE_TRAN_FIXED_AMT,    -- 理财到期转定期金额
      FRST_MATURE_PK_BF_DAY_AUM_BAL,-- 本期第一笔到期前一日AUM(留存率分母)
      CURR_AUM_BAL                  -- 当前AUM(当前时点DWS,客户+法人行聚合)
  )
  SELECT d.PERSN_LEGAL_BK_CODE,
         d.DATA_DATE,
         d.STAT_PERD,
         d.STATIS_TYP,
         d.CUST_ID,
         d.ORG_ID,
         d.POST_ID,
         NVL(d.EXPR_AMT, 0),
         NVL(d.MATURE_TTL_AMT, 0),
         NVL(d.TAKE_RATE, 0),
         d.UNDTAKE_STATE,
         NVL(d.FIXED_MATURE_TRAN_FIN_AMT, 0),
         NVL(d.FIXED_FIN_MATURE_TRAN_INSUR_AMT, 0),
         NVL(d.FIN_MATURE_TRAN_FIXED_AMT, 0),
         NVL(d.FRST_MATURE_PK_BF_DAY_AUM_BAL, 0),
         NVL(a.CURR_AUM_BAL, 0)
    FROM ADS_CUST_DEADLINE_RMND_DTL d
    LEFT JOIN (
        SELECT x.CUST_ID, x.PERSN_LEGAL_BK_CODE, SUM(NVL(x.AUM_BAL, 0)) AS CURR_AUM_BAL
          FROM DWS_CUST_ASSE_LIAB x
         WHERE x.DATA_DATE = V_SYSDAT
           AND x.BAL_TYPE = '1'
         GROUP BY x.CUST_ID, x.PERSN_LEGAL_BK_CODE
    ) a
      ON a.CUST_ID = d.CUST_ID
      AND A.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE
   -- v2.6.0(口径37): 本期行DATA_DATE=V_SYSDAT；上期行DATA_DATE=上期期末日期
   WHERE (d.STAT_PERD = 'M' AND d.DATA_DATE IN (V_SYSDAT, V_PREV_MONTH_END))
      OR (d.STAT_PERD = 'Q' AND d.DATA_DATE IN (V_SYSDAT, V_PREV_QUARTER_END))
      OR (d.STAT_PERD = 'Y' AND d.DATA_DATE IN (V_SYSDAT, V_PREV_YEAR_END));
  COMMIT;

  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：生成统计基础明细中间表';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.2 -- 第3段处理开始：展开机构和客户经理统计对象
  -- 业务含义：将统计基础行展开为"机构(向上含自身及所有上级) + 管户经理"两类统计对象
  -- 数据来源：TMP_CDR_STAT_BASE × DWD_SYS_ORG(ORG_ID/SUP_ORG_ID层级)
  -- 处理逻辑：CONNECT_BY 自底向上展开机构祖先链；管户经理分支仅取POST_ID非空行；UNION ALL合并
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_CDR_STAT_SRC (
      PERSN_LEGAL_BK_CODE,          -- 法人行号
      STATIS_OBJ,                   -- 统计对象(机构ID/管户经理岗位ID)
      DATA_DATE,                    -- 数据日期(周期结束日)
      STAT_PERD,                    -- 统计周期(M/Q/Y)
      STATIS_TYP,                   -- 承接类型(0-全部/1-定期存款/2-理财)
      CUST_ID,                      -- 客户编号
      ORG_ID,                       -- 归属机构
      POST_ID,                      -- 管户经理岗位ID
      EXPR_AMT,                     -- 已到期金额
      MATURE_TTL_AMT,               -- 总到期金额
      TAKE_RATE_30D,                -- 30天客户承接金额占比
      CUST_TAKE_FLG,                -- 承接状态
      FIXED_MATURE_TRAN_FIN_AMT,    -- 定期到期转理财金额
      FIXED_FIN_MATURE_TRAN_INSUR_AMT, -- 到期转保险金额
      FIN_MATURE_TRAN_FIXED_AMT,    -- 理财到期转定期金额
      FRST_MATURE_PK_BF_DAY_AUM_BAL,-- 本期第一笔到期前一日AUM
      CURR_AUM_BAL                  -- 当前AUM
  )
  SELECT b.PERSN_LEGAL_BK_CODE,
         o.ANCESTOR_ORG_ID,
         b.DATA_DATE, b.STAT_PERD, b.STATIS_TYP, b.CUST_ID, b.ORG_ID, b.POST_ID,
         b.EXPR_AMT, b.MATURE_TTL_AMT, b.TAKE_RATE_30D, b.CUST_TAKE_FLG,
         b.FIXED_MATURE_TRAN_FIN_AMT, b.FIXED_FIN_MATURE_TRAN_INSUR_AMT, b.FIN_MATURE_TRAN_FIXED_AMT,
         b.FRST_MATURE_PK_BF_DAY_AUM_BAL, b.CURR_AUM_BAL
    FROM TMP_CDR_STAT_BASE b
    JOIN (
        SELECT DISTINCT CONNECT_BY_ROOT o.ORG_ID AS LEAF_ORG_ID,
                        o.ORG_ID AS ANCESTOR_ORG_ID
          FROM DWD_SYS_ORG o
         START WITH o.ORG_ID IN (
             SELECT DISTINCT z.ORG_ID
               FROM TMP_CDR_STAT_BASE z
              WHERE z.ORG_ID IS NOT NULL
         )
       CONNECT BY NOCYCLE PRIOR o.SUP_ORG_ID = o.ORG_ID
    ) o
      ON o.LEAF_ORG_ID = b.ORG_ID
  UNION ALL
  SELECT b.PERSN_LEGAL_BK_CODE,
         b.POST_ID,
         b.DATA_DATE, b.STAT_PERD, b.STATIS_TYP, b.CUST_ID, b.ORG_ID, b.POST_ID,
         b.EXPR_AMT, b.MATURE_TTL_AMT, b.TAKE_RATE_30D, b.CUST_TAKE_FLG,
         b.FIXED_MATURE_TRAN_FIN_AMT, b.FIXED_FIN_MATURE_TRAN_INSUR_AMT, b.FIN_MATURE_TRAN_FIXED_AMT,
         b.FRST_MATURE_PK_BF_DAY_AUM_BAL, b.CURR_AUM_BAL
    FROM TMP_CDR_STAT_BASE b
   WHERE b.POST_ID IS NOT NULL;
  COMMIT;

  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：展开机构和客户经理统计对象';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.3 -- 第4段处理开始：两期分离计算与验证(v3.0.0,单个BEGIN...END分段落)
  -- 业务含义：本期/上期/验证统计逻辑位于同一个匿名块内,以注释段落分隔；方案B(口径36)
  -- 数据来源：TMP_CDR_STAT_SRC(已按机构/管户经理展开,含三种承接类型行)
  -- 处理逻辑：4.0上期冻结快照 / 4.1本期计算段(C1/C2) / 4.2上期计算段(P1/P2) / 4.3验证段(V1,FAIL即中止)
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  DECLARE
    V_FAIL_CNT INTEGER := 0;   -- 验证段失败计数(块级局部变量)
  BEGIN
  -- 4.0 上期统计冻结快照(供验证段比对9基础列是否被修改)
  INSERT INTO TMP_CDR_STAT_FREEZE_LOG (
      BATCH_DATE, PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
      EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT,
      CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
      DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
  )
  SELECT V_SYSDAT, PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
         EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT,
         CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
         DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
    FROM ADS_CUST_DEADLINE_RMND_STATIS
   WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END);
  COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '上期统计冻结快照完成：TMP_CDR_STAT_FREEZE_LOG';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, '4', V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

    -- ========== 【本期计算段】开始(边界：DATA_DATE=V_SYSDAT)==========
    V_NO_ID := 'C1';
    V_BGN_DATE := SYSDATE;

    INSERT INTO TMP_CDR_STAT_CURR_STAGE (
        PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
        EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT,
        CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
        DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
    )
    SELECT * FROM (
      -- 承接类型 0-全部
      SELECT s.PERSN_LEGAL_BK_CODE,
             s.DATA_DATE,
             s.STATIS_OBJ,
             s.STAT_PERD,
             '0' AS STATIS_TYP,
             COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS EXPR_CUST_CNT,
             COUNT(DISTINCT CASE WHEN s.MATURE_TTL_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS TTL_EXPR_CUST_CNT,
             SUM(s.EXPR_AMT) AS EXPR_AMT,
             SUM(s.MATURE_TTL_AMT) AS TTL_EXPR_AMT,
             CASE WHEN COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) = 0 THEN 0
                  ELSE ROUND(COUNT(DISTINCT CASE WHEN s.CUST_TAKE_FLG = '1' THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END)
                             / COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) * 100, 2)
             END AS CUST_UNDTAKE_RATE,
             CASE WHEN SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) = 0 THEN 0
                  ELSE ROUND(SUM(s.CURR_AUM_BAL) / SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) * 100, 2)
             END AS ASSET_KEEP_RATE,
             CASE WHEN SUM(s.EXPR_AMT) = 0 THEN 0
                  ELSE ROUND(SUM(s.EXPR_AMT * s.TAKE_RATE_30D / 100) / SUM(s.EXPR_AMT) * 100, 2)
             END AS ASSET_UNDTAKE_RATE,
             NVL(ROUND((SELECT NVL(SUM(x.FIXED_MATURE_TRAN_FIN_AMT), 0) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '1')
                       / NULLIF((SELECT SUM(x.EXPR_AMT) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '1'), 0) * 100, 2), 0) AS DEPO_TO_FIN_CONVRS_RATE,
             NVL(ROUND(SUM(s.FIXED_FIN_MATURE_TRAN_INSUR_AMT) / NULLIF(SUM(s.EXPR_AMT), 0) * 100, 2), 0) AS INSUR_CONVRS_RATE,
             NVL(ROUND((SELECT NVL(SUM(x.FIN_MATURE_TRAN_FIXED_AMT), 0) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '2')
                       / NULLIF((SELECT SUM(x.EXPR_AMT) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '2'), 0) * 100, 2), 0) AS FIN_TO_DEPO_CONVRS_RATE
        FROM TMP_CDR_STAT_SRC s
       WHERE s.STATIS_TYP = '0'
       GROUP BY s.PERSN_LEGAL_BK_CODE, s.DATA_DATE, s.STATIS_OBJ, s.STAT_PERD
      UNION ALL
      -- 承接类型 1-定期存款
      SELECT s.PERSN_LEGAL_BK_CODE,
             s.DATA_DATE,
             s.STATIS_OBJ,
             s.STAT_PERD,
             '1' AS STATIS_TYP,
             COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS EXPR_CUST_CNT,
             COUNT(DISTINCT CASE WHEN s.MATURE_TTL_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS TTL_EXPR_CUST_CNT,
             SUM(s.EXPR_AMT) AS EXPR_AMT,
             SUM(s.MATURE_TTL_AMT) AS TTL_EXPR_AMT,
             CASE WHEN COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) = 0 THEN 0
                  ELSE ROUND(COUNT(DISTINCT CASE WHEN s.CUST_TAKE_FLG = '1' THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END)
                             / COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) * 100, 2)
             END AS CUST_UNDTAKE_RATE,
             CASE WHEN SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) = 0 THEN 0
                  ELSE ROUND(SUM(s.CURR_AUM_BAL) / SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) * 100, 2)
             END AS ASSET_KEEP_RATE,
             CASE WHEN SUM(s.EXPR_AMT) = 0 THEN 0
                  ELSE ROUND(SUM(s.EXPR_AMT * s.TAKE_RATE_30D / 100) / SUM(s.EXPR_AMT) * 100, 2)
             END AS ASSET_UNDTAKE_RATE,
             NVL(ROUND(SUM(s.FIXED_MATURE_TRAN_FIN_AMT) / NULLIF(SUM(s.EXPR_AMT), 0) * 100, 2), 0) AS DEPO_TO_FIN_CONVRS_RATE,
             0 AS INSUR_CONVRS_RATE,
             0 AS FIN_TO_DEPO_CONVRS_RATE
        FROM TMP_CDR_STAT_SRC s
       WHERE s.STATIS_TYP = '1'
       GROUP BY s.PERSN_LEGAL_BK_CODE, s.DATA_DATE, s.STATIS_OBJ, s.STAT_PERD
      UNION ALL
      -- 承接类型 2-理财
      SELECT s.PERSN_LEGAL_BK_CODE,
             s.DATA_DATE,
             s.STATIS_OBJ,
             s.STAT_PERD,
             '2' AS STATIS_TYP,
             COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS EXPR_CUST_CNT,
             COUNT(DISTINCT CASE WHEN s.MATURE_TTL_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS TTL_EXPR_CUST_CNT,
             SUM(s.EXPR_AMT) AS EXPR_AMT,
             SUM(s.MATURE_TTL_AMT) AS TTL_EXPR_AMT,
             CASE WHEN COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) = 0 THEN 0
                  ELSE ROUND(COUNT(DISTINCT CASE WHEN s.CUST_TAKE_FLG = '1' THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END)
                             / COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) * 100, 2)
             END AS CUST_UNDTAKE_RATE,
             CASE WHEN SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) = 0 THEN 0
                  ELSE ROUND(SUM(s.CURR_AUM_BAL) / SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) * 100, 2)
             END AS ASSET_KEEP_RATE,
             CASE WHEN SUM(s.EXPR_AMT) = 0 THEN 0
                  ELSE ROUND(SUM(s.EXPR_AMT * s.TAKE_RATE_30D / 100) / SUM(s.EXPR_AMT) * 100, 2)
             END AS ASSET_UNDTAKE_RATE,
             0 AS DEPO_TO_FIN_CONVRS_RATE,
             0 AS INSUR_CONVRS_RATE,
             NVL(ROUND(SUM(s.FIN_MATURE_TRAN_FIXED_AMT) / NULLIF(SUM(s.EXPR_AMT), 0) * 100, 2), 0) AS FIN_TO_DEPO_CONVRS_RATE
        FROM TMP_CDR_STAT_SRC s
       WHERE s.STATIS_TYP = '2'
       GROUP BY s.PERSN_LEGAL_BK_CODE, s.DATA_DATE, s.STATIS_OBJ, s.STAT_PERD
    ) WHERE DATA_DATE = V_SYSDAT;   -- 边界检查：仅本期统计源行

    -- 边界检查：本期统计结果 DATA_DATE 必须全部等于跑批日期
    IF EXISTS (SELECT 1 FROM TMP_CDR_STAT_CURR_STAGE WHERE DATA_DATE <> V_SYSDAT) THEN
      RAISE_APPLICATION_ERROR(-20021, '本期统计边界检查失败：CURR_STAGE存在DATA_DATE<>V_SYSDAT行（跨期引用）');
    END IF;
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '本期统计计算段完成：STAT_CURR_STAGE生成并边界检查通过';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'C1', V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

    V_NO_ID := 'C2';
    V_BGN_DATE := SYSDATE;
    INSERT INTO ADS_CUST_DEADLINE_RMND_STATIS (
        PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
        EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT,
        CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
        DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
    )
    SELECT
        PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
        EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT,
        CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
        DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
      FROM TMP_CDR_STAT_CURR_STAGE;
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '本期统计计算段完成：写入ADS_CUST_DEADLINE_RMND_STATIS';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'C2', V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    -- ========== 【本期计算段】结束 ==========
    -- ========== 【上期计算段】开始(边界：DATA_DATE=上期期末日期)==========
    V_NO_ID := 'P1';
    V_BGN_DATE := SYSDATE;

    INSERT INTO TMP_CDR_STAT_PREV_STAGE (
        PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
        EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT,
        CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
        DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
    )
    SELECT * FROM (
      -- 承接类型 0-全部
      SELECT s.PERSN_LEGAL_BK_CODE,
             s.DATA_DATE,
             s.STATIS_OBJ,
             s.STAT_PERD,
             '0' AS STATIS_TYP,
             COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS EXPR_CUST_CNT,
             COUNT(DISTINCT CASE WHEN s.MATURE_TTL_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS TTL_EXPR_CUST_CNT,
             SUM(s.EXPR_AMT) AS EXPR_AMT,
             SUM(s.MATURE_TTL_AMT) AS TTL_EXPR_AMT,
             CASE WHEN COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) = 0 THEN 0
                  ELSE ROUND(COUNT(DISTINCT CASE WHEN s.CUST_TAKE_FLG = '1' THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END)
                             / COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) * 100, 2)
             END AS CUST_UNDTAKE_RATE,
             CASE WHEN SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) = 0 THEN 0
                  ELSE ROUND(SUM(s.CURR_AUM_BAL) / SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) * 100, 2)
             END AS ASSET_KEEP_RATE,
             CASE WHEN SUM(s.EXPR_AMT) = 0 THEN 0
                  ELSE ROUND(SUM(s.EXPR_AMT * s.TAKE_RATE_30D / 100) / SUM(s.EXPR_AMT) * 100, 2)
             END AS ASSET_UNDTAKE_RATE,
             NVL(ROUND((SELECT NVL(SUM(x.FIXED_MATURE_TRAN_FIN_AMT), 0) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '1')
                       / NULLIF((SELECT SUM(x.EXPR_AMT) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '1'), 0) * 100, 2), 0) AS DEPO_TO_FIN_CONVRS_RATE,
             NVL(ROUND(SUM(s.FIXED_FIN_MATURE_TRAN_INSUR_AMT) / NULLIF(SUM(s.EXPR_AMT), 0) * 100, 2), 0) AS INSUR_CONVRS_RATE,
             NVL(ROUND((SELECT NVL(SUM(x.FIN_MATURE_TRAN_FIXED_AMT), 0) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '2')
                       / NULLIF((SELECT SUM(x.EXPR_AMT) FROM TMP_CDR_STAT_SRC x
                         WHERE x.PERSN_LEGAL_BK_CODE = s.PERSN_LEGAL_BK_CODE
                           AND x.DATA_DATE = s.DATA_DATE
                           AND x.STATIS_OBJ = s.STATIS_OBJ
                           AND x.STAT_PERD = s.STAT_PERD
                           AND x.STATIS_TYP = '2'), 0) * 100, 2), 0) AS FIN_TO_DEPO_CONVRS_RATE
        FROM TMP_CDR_STAT_SRC s
       WHERE s.STATIS_TYP = '0'
       GROUP BY s.PERSN_LEGAL_BK_CODE, s.DATA_DATE, s.STATIS_OBJ, s.STAT_PERD
      UNION ALL
      -- 承接类型 1-定期存款
      SELECT s.PERSN_LEGAL_BK_CODE,
             s.DATA_DATE,
             s.STATIS_OBJ,
             s.STAT_PERD,
             '1' AS STATIS_TYP,
             COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS EXPR_CUST_CNT,
             COUNT(DISTINCT CASE WHEN s.MATURE_TTL_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS TTL_EXPR_CUST_CNT,
             SUM(s.EXPR_AMT) AS EXPR_AMT,
             SUM(s.MATURE_TTL_AMT) AS TTL_EXPR_AMT,
             CASE WHEN COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) = 0 THEN 0
                  ELSE ROUND(COUNT(DISTINCT CASE WHEN s.CUST_TAKE_FLG = '1' THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END)
                             / COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) * 100, 2)
             END AS CUST_UNDTAKE_RATE,
             CASE WHEN SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) = 0 THEN 0
                  ELSE ROUND(SUM(s.CURR_AUM_BAL) / SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) * 100, 2)
             END AS ASSET_KEEP_RATE,
             CASE WHEN SUM(s.EXPR_AMT) = 0 THEN 0
                  ELSE ROUND(SUM(s.EXPR_AMT * s.TAKE_RATE_30D / 100) / SUM(s.EXPR_AMT) * 100, 2)
             END AS ASSET_UNDTAKE_RATE,
             NVL(ROUND(SUM(s.FIXED_MATURE_TRAN_FIN_AMT) / NULLIF(SUM(s.EXPR_AMT), 0) * 100, 2), 0) AS DEPO_TO_FIN_CONVRS_RATE,
             0 AS INSUR_CONVRS_RATE,
             0 AS FIN_TO_DEPO_CONVRS_RATE
        FROM TMP_CDR_STAT_SRC s
       WHERE s.STATIS_TYP = '1'
       GROUP BY s.PERSN_LEGAL_BK_CODE, s.DATA_DATE, s.STATIS_OBJ, s.STAT_PERD
      UNION ALL
      -- 承接类型 2-理财
      SELECT s.PERSN_LEGAL_BK_CODE,
             s.DATA_DATE,
             s.STATIS_OBJ,
             s.STAT_PERD,
             '2' AS STATIS_TYP,
             COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS EXPR_CUST_CNT,
             COUNT(DISTINCT CASE WHEN s.MATURE_TTL_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) AS TTL_EXPR_CUST_CNT,
             SUM(s.EXPR_AMT) AS EXPR_AMT,
             SUM(s.MATURE_TTL_AMT) AS TTL_EXPR_AMT,
             CASE WHEN COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) = 0 THEN 0
                  ELSE ROUND(COUNT(DISTINCT CASE WHEN s.CUST_TAKE_FLG = '1' THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END)
                             / COUNT(DISTINCT CASE WHEN s.EXPR_AMT > 0 THEN s.CUST_ID || CHR(1) || s.PERSN_LEGAL_BK_CODE || CHR(1) || s.ORG_ID END) * 100, 2)
             END AS CUST_UNDTAKE_RATE,
             CASE WHEN SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) = 0 THEN 0
                  ELSE ROUND(SUM(s.CURR_AUM_BAL) / SUM(s.FRST_MATURE_PK_BF_DAY_AUM_BAL) * 100, 2)
             END AS ASSET_KEEP_RATE,
             CASE WHEN SUM(s.EXPR_AMT) = 0 THEN 0
                  ELSE ROUND(SUM(s.EXPR_AMT * s.TAKE_RATE_30D / 100) / SUM(s.EXPR_AMT) * 100, 2)
             END AS ASSET_UNDTAKE_RATE,
             0 AS DEPO_TO_FIN_CONVRS_RATE,
             0 AS INSUR_CONVRS_RATE,
             NVL(ROUND(SUM(s.FIN_MATURE_TRAN_FIXED_AMT) / NULLIF(SUM(s.EXPR_AMT), 0) * 100, 2), 0) AS FIN_TO_DEPO_CONVRS_RATE
        FROM TMP_CDR_STAT_SRC s
       WHERE s.STATIS_TYP = '2'
       GROUP BY s.PERSN_LEGAL_BK_CODE, s.DATA_DATE, s.STATIS_OBJ, s.STAT_PERD
    ) WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END);  -- 边界检查：仅上期周期实例(口径38)

    -- 边界检查：上期统计结果 DATA_DATE 必须与上期期末日期一一对应
    IF EXISTS (SELECT 1 FROM TMP_CDR_STAT_PREV_STAGE
                WHERE (STATIS_CYCLE = 'M' AND DATA_DATE <> V_PREV_MONTH_END)
                   OR (STATIS_CYCLE = 'Q' AND DATA_DATE <> V_PREV_QUARTER_END)
                   OR (STATIS_CYCLE = 'Y' AND DATA_DATE <> V_PREV_YEAR_END)) THEN
      RAISE_APPLICATION_ERROR(-20022, '上期统计边界检查失败：PREV_STAGE存在DATA_DATE与上期期末不一致行（跨期引用）');
    END IF;
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '上期统计计算段完成：STAT_PREV_STAGE生成并边界检查通过';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'P1', V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

    V_NO_ID := 'P2';
    V_BGN_DATE := SYSDATE;
    -- 方案B(口径36)：上期行仅更新6个率值列,缺失上期行整行补插
    MERGE INTO ADS_CUST_DEADLINE_RMND_STATIS dst
    USING TMP_CDR_STAT_PREV_STAGE src
    ON (dst.PERSN_LEGAL_BK_CODE = src.PERSN_LEGAL_BK_CODE
        AND dst.DATA_DATE = src.DATA_DATE
        AND dst.STATIS_OBJ = src.STATIS_OBJ
        AND dst.STATIS_CYCLE = src.STATIS_CYCLE
        AND dst.STATIS_TYP = src.STATIS_TYP)
    WHEN MATCHED THEN UPDATE SET
        dst.CUST_UNDTAKE_RATE     = src.CUST_UNDTAKE_RATE,
        dst.ASSET_KEEP_RATE       = src.ASSET_KEEP_RATE,
        dst.ASSET_UNDTAKE_RATE    = src.ASSET_UNDTAKE_RATE,
        dst.DEPO_TO_FIN_CONVRS_RATE = src.DEPO_TO_FIN_CONVRS_RATE,
        dst.INSUR_CONVRS_RATE     = src.INSUR_CONVRS_RATE,
        dst.FIN_TO_DEPO_CONVRS_RATE = src.FIN_TO_DEPO_CONVRS_RATE
    WHEN NOT MATCHED THEN INSERT (
        PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
        EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT,
        CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
        DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
    ) VALUES (
        src.PERSN_LEGAL_BK_CODE, src.DATA_DATE, src.STATIS_OBJ, src.STATIS_CYCLE, src.STATIS_TYP,
        src.EXPR_CUST_CNT, src.TTL_EXPR_CUST_CNT, src.EXPR_AMT, src.TTL_EXPR_AMT,
        src.CUST_UNDTAKE_RATE, src.ASSET_KEEP_RATE, src.ASSET_UNDTAKE_RATE,
        src.DEPO_TO_FIN_CONVRS_RATE, src.INSUR_CONVRS_RATE, src.FIN_TO_DEPO_CONVRS_RATE
    );
    COMMIT;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '上期统计计算段完成：仅更新6个率值列/补插缺失上期行';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'P2', V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    -- ========== 【上期计算段】结束 ==========
    -- ========== 【数据验证段】开始(冻结/一致性/互斥/值域/行数,FAIL即中止)==========
    V_NO_ID := 'V1';
    V_BGN_DATE := SYSDATE;

    -- V1: 上期9基础列冻结校验(STAT_FREEZE_LOG vs 目标表当前上期行)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'FREEZE_BASE_9',
           CASE WHEN NOT EXISTS (
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
                           EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT
                      FROM TMP_CDR_STAT_FREEZE_LOG
                    MINUS
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
                           EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT
                      FROM ADS_CUST_DEADLINE_RMND_STATIS
                     WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
                AND NOT EXISTS (
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
                           EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT
                      FROM ADS_CUST_DEADLINE_RMND_STATIS
                     WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END)
                    MINUS
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
                           EXPR_CUST_CNT, TTL_EXPR_CUST_CNT, EXPR_AMT, TTL_EXPR_AMT
                      FROM TMP_CDR_STAT_FREEZE_LOG)
           THEN 'PASS' ELSE 'FAIL' END,
           '上期9基础列冻结校验（方案B/口径36）', SYSDATE FROM dual;

    -- V2: 上期6率值列一致性(目标表上期行 vs PREV_STAGE)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'PREV_6RATES_CONSISTENT',
           CASE WHEN NOT EXISTS (
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
                           CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
                           DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
                      FROM TMP_CDR_STAT_PREV_STAGE
                    MINUS
                    SELECT PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE, STATIS_TYP,
                           CUST_UNDTAKE_RATE, ASSET_KEEP_RATE, ASSET_UNDTAKE_RATE,
                           DEPO_TO_FIN_CONVRS_RATE, INSUR_CONVRS_RATE, FIN_TO_DEPO_CONVRS_RATE
                      FROM ADS_CUST_DEADLINE_RMND_STATIS
                     WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
           THEN 'PASS' ELSE 'FAIL' END,
           '上期6率值列一致性校验', SYSDATE FROM dual;

    -- V3: 本期结果不得包含上期日期(DATA_DATE互斥)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'C', 'CURR_NO_PREV_DATE',
           CASE WHEN EXISTS (SELECT 1 FROM TMP_CDR_STAT_CURR_STAGE
                              WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
                THEN 'FAIL' ELSE 'PASS' END,
           '本期统计结果与上期日期互斥校验', SYSDATE FROM dual;

    -- V4: 率值域(两期独立校验,率值>=0且非空)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'C', 'RATE_DOMAIN_CURR',
           CASE WHEN EXISTS (SELECT 1 FROM TMP_CDR_STAT_CURR_STAGE
                              WHERE CUST_UNDTAKE_RATE IS NULL OR CUST_UNDTAKE_RATE < 0
                                 OR ASSET_KEEP_RATE IS NULL OR ASSET_KEEP_RATE < 0
                                 OR ASSET_UNDTAKE_RATE IS NULL OR ASSET_UNDTAKE_RATE < 0)
                THEN 'FAIL' ELSE 'PASS' END,
           '本期统计率值域校验', SYSDATE FROM dual;
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'RATE_DOMAIN_PREV',
           CASE WHEN EXISTS (SELECT 1 FROM TMP_CDR_STAT_PREV_STAGE
                              WHERE CUST_UNDTAKE_RATE IS NULL OR CUST_UNDTAKE_RATE < 0
                                 OR ASSET_KEEP_RATE IS NULL OR ASSET_KEEP_RATE < 0
                                 OR ASSET_UNDTAKE_RATE IS NULL OR ASSET_UNDTAKE_RATE < 0)
                THEN 'FAIL' ELSE 'PASS' END,
           '上期统计率值域校验', SYSDATE FROM dual;

    -- V5: stage与目标表行数一致性(两期独立校验)
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'C', 'ROWCOUNT_CONSISTENT_CURR',
           CASE WHEN (SELECT COUNT(*) FROM TMP_CDR_STAT_CURR_STAGE)
                  = (SELECT COUNT(*) FROM ADS_CUST_DEADLINE_RMND_STATIS WHERE DATA_DATE = V_SYSDAT)
                THEN 'PASS' ELSE 'FAIL' END,
           '本期统计stage与目标表行数一致性', SYSDATE FROM dual;
    INSERT INTO TMP_CDR_VALIDATE_RESULT (BATCH_DATE, PERIOD_TYP, VALIDATE_ITEM, RESULT, DETAIL, CHECK_TIME)
    SELECT V_SYSDAT, 'P', 'ROWCOUNT_CONSISTENT_PREV',
           CASE WHEN (SELECT COUNT(*) FROM TMP_CDR_STAT_PREV_STAGE)
                  = (SELECT COUNT(*) FROM ADS_CUST_DEADLINE_RMND_STATIS
                      WHERE DATA_DATE IN (V_PREV_MONTH_END, V_PREV_QUARTER_END, V_PREV_YEAR_END))
                THEN 'PASS' ELSE 'FAIL' END,
           '上期统计stage与目标表行数一致性', SYSDATE FROM dual;

    COMMIT;

    -- 任一FAIL即中止批次(防止污染数据后继续)
    SELECT COUNT(*) INTO V_FAIL_CNT
      FROM TMP_CDR_VALIDATE_RESULT
     WHERE BATCH_DATE = V_SYSDAT AND RESULT = 'FAIL';
    IF V_FAIL_CNT > 0 THEN
      RAISE_APPLICATION_ERROR(-20023, '统计数据验证失败：' || V_FAIL_CNT || ' 项校验未通过');
    END IF;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
    OUTCDE := 0;
    V_LOG_MSG := '统计数据验证段完成：两期结果准确性与独立性校验通过';
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, 'V1', V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    -- ========== 【数据验证段】结束 ==========
  END;
  DELETE FROM ADS_CUST_DEADLINE_RMND_STATIS t
   WHERE t.DATA_DATE NOT IN (
          V_SYSDAT,
          V_PREV_MONTH_END,
          V_PREV_QUARTER_END,
          V_PREV_YEAR_END
        )
     AND t.DATA_DATE < V_HISTORY_CUTOFF_DATE;
  COMMIT;

  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：写入到期承接统计表并清理历史';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  -- 异常处理区：任一环节异常时统一置返回码-1、回滚当前事务并记录错误日志后重抛
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE WHEN V_BGN_DATE IS NULL THEN NULL ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60) END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    RAISE;
END



;

-- DROP PROCEDURE crmdm.prc_ads_cust_indv_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_indv_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 零售客户信息表
  -- 存储过程编号：PRC_ADS_CUST_INDV_INFO
  -- 处理周期：日
  -- 过程描述：根据 DWS 数据模型映射生成
  -- 来源表：DWD_CUST_INDV_INFO(客户基本信息表)；DWD_SYS_ORG(机构表)；DWS_CUST_LVL_INFO(客户等级信息表)
  -- 目标表：ADS_CUST_INDV_INFO
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '零售客户信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_INDV_INFO';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_INDV_INFO';

  --***************************************
  -- 2.1 -- 第1段处理开始：存款日均余额
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：存款日均余额
  INSERT INTO ADS_CUST_INDV_INFO (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      PARTY_ID,
      CERT_TYP,
      CERT_ID,
      CERT_PRD_VLID,
      CERT_PRD_VLID_END,
      CERT_ISSUING,
      CERT_ISSUING_AUTHORITY,
      CUST_TYP,
      OPEN_DATE,
      OPEN_ORG,
      NATIONALITY,
      NATION,
      MARI_SITU,
      MAX_DEG_EDU,
      NOW_ENTER,
      OCCU_CLS,
      GEND,
      AGE,
      PHONE_NO,
      CONTACT_ADDRESS,
      CONTACT_ADDRESS_DETAIL,
      ID_ADDRESS,
      ID_ADDRESS_DETAIL,
      HOME_ADDRESS,
      HOME_ADDRESS_DETAIL,
      RESIDENCE_ADDRESS,
      RESIDENCE_ADDRESS_DETAIL,
      OFFICE_ADDRESS,
      OFFICE_ADDRESS_DETAIL,
      ORG_LEAD,
      ORG_LEAD_PATH
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE       AS PERSN_LEGAL_BK_CODE       , -- 法人行号
         T1.CUST_ID                   AS CUST_ID                   , -- 客户编号
         T1.CUST_NAME                 AS CUST_NAME                 , -- 客户名称
         T1.PARTY_ID                  AS PARTY_ID                  , -- 参与人ID
         T1.CERT_TYP                  AS CERT_TYP                  , -- 证件类型
         T1.CERT_ID                   AS CERT_ID                   , -- 证件号码
         T1.CERT_PRD_VLID             AS CERT_PRD_VLID             , -- 证件有效期起
         T1.CERT_PRD_VLID_END         AS CERT_PRD_VLID_END         , -- 证件有效期止
         T1.CERT_ISSUING              AS CERT_ISSUING              , -- 签发机关
         T1.CERT_ISSUING_AUTHORITY    AS CERT_ISSUING_AUTHORITY    , -- 签发机关所在地
         T1.CUST_TYP                  AS CUST_TYP                  , -- 客户类型
         T1.OPEN_DATE                 AS OPEN_DATE                 , -- 开户日期
         T1.OPEN_ORG                  AS OPEN_ORG                  , -- 开户机构
         T1.NATIONALITY               AS NATIONALITY               , -- 国籍
         T1.NATION                    AS NATION                    , -- 民族
         T1.MARI_SITU                 AS MARI_SITU                 , -- 婚姻状况
         T1.MAX_DEG_EDU               AS MAX_DEG_EDU               , -- 最高学历
         T1.NOW_ENTER                 AS NOW_ENTER                 , -- 现工作单位
         T1.OCCU_CLS                  AS OCCU_CLS                  , -- 职业分类
         T1.GEND                      AS GEND                      , -- 性别
         T1.AGE                       AS AGE                       , -- 年龄
         T1.PHONE_NO                  AS PHONE_NO                  , -- 手机号码
         T1.CONTACT_ADDRESS           AS CONTACT_ADDRESS           , -- 联系地址
         T1.CONTACT_ADDRESS_DETAIL    AS CONTACT_ADDRESS_DETAIL    , -- 联系地址详细地址
         T1.ID_ADDRESS                AS ID_ADDRESS                , -- 证件地址
         T1.ID_ADDRESS_DETAIL         AS ID_ADDRESS_DETAIL         , -- 证件地址详细地址
         T1.HOME_ADDRESS              AS HOME_ADDRESS              , -- 家庭地址
         T1.HOME_ADDRESS_DETAIL       AS HOME_ADDRESS_DETAIL       , -- 家庭地址详细地址
         T1.RESIDENCE_ADDRESS         AS RESIDENCE_ADDRESS         , -- 住宅地址
         T1.RESIDENCE_ADDRESS_DETAIL  AS RESIDENCE_ADDRESS_DETAIL  , -- 住宅地址详细地址
         T1.OFFICE_ADDRESS            AS OFFICE_ADDRESS            , -- 办公地址
         T1.OFFICE_ADDRESS_DETAIL     AS OFFICE_ADDRESS_DETAIL     , -- 办公地址详细地址
         T2.ORG_ID                    AS ORG_LEAD                  , -- 主办机构(归属机构)
         T3.ORG_PATH                  AS ORG_LEAD_PATH              -- 主办机构路径
    FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
    INNER JOIN DWS_CUST_LVL_INFO T2 -- 客户等级信息表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE
    INNER JOIN DWD_SYS_ORG T3 -- 机构表
      ON T2.ORG_ID = T3.ORG_ID;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：存款日均余额';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_indx_trnd_anlyz(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_indx_trnd_anlyz(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户指标趋势分析表应用
  -- 存储过程编号：PRC_ADS_CUST_INDX_TRND_ANLYZ
  -- 处理周期：日
  -- 过程描述：根据 ADS 应用层数据模型生成客户指标趋势分析数据
  -- 来源表：DWS_CUST_ASSE_LIAB、DWS_CUST_LVL_INFO、TMP_ADS_CUST_INDX_TRND_ANLYZ、TMP2_ADS_CUST_INDX_TRND_ANLYZ
  -- 目标表：ADS_CUST_INDX_TRND_ANLYZ
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户指标趋势分析表应用';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_INDX_TRND_ANLYZ';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);  -- 近30天区间起始日期,格式 YYYYMMDD
  P_INTERVAL_END_DATE    VARCHAR(8);  -- 近30天区间结束日期,格式 YYYYMMDD
  V_SYSDAT_DATE          DATE;        -- 批处理日期的 DATE 类型值,仅在过程开头统一转换
  V_IS_MONTH_END         VARCHAR(1);  -- 批处理日期是否为月末,Y-是,N-否
  V_DATA_DATE_CURR       VARCHAR(8);  -- 当前批处理日期,格式 YYYYMMDD
  V_DATA_DATE_M01        VARCHAR(8);  -- 前1个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M02        VARCHAR(8);  -- 前2个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M03        VARCHAR(8);  -- 前3个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M04        VARCHAR(8);  -- 前4个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M05        VARCHAR(8);  -- 前5个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M06        VARCHAR(8);  -- 前6个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M07        VARCHAR(8);  -- 前7个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M08        VARCHAR(8);  -- 前8个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M09        VARCHAR(8);  -- 前9个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M10        VARCHAR(8);  -- 前10个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M11        VARCHAR(8);  -- 前11个月月末日期,格式 YYYYMMDD
  V_DATA_DATE_M12        VARCHAR(8);  -- 前12个月月末日期,格式 YYYYMMDD
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT_DATE := TO_DATE(V_SYSDAT, 'yyyymmdd');
  V_SYSDAT2 := TO_CHAR(V_SYSDAT_DATE, 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(V_SYSDAT_DATE - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_DATA_DATE_CURR      := V_SYSDAT;
  V_DATA_DATE_M01       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -1)), 'YYYYMMDD');
  V_DATA_DATE_M02       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -2)), 'YYYYMMDD');
  V_DATA_DATE_M03       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -3)), 'YYYYMMDD');
  V_DATA_DATE_M04       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -4)), 'YYYYMMDD');
  V_DATA_DATE_M05       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -5)), 'YYYYMMDD');
  V_DATA_DATE_M06       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -6)), 'YYYYMMDD');
  V_DATA_DATE_M07       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -7)), 'YYYYMMDD');
  V_DATA_DATE_M08       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -8)), 'YYYYMMDD');
  V_DATA_DATE_M09       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -9)), 'YYYYMMDD');
  V_DATA_DATE_M10       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -10)), 'YYYYMMDD');
  V_DATA_DATE_M11       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -11)), 'YYYYMMDD');
  V_DATA_DATE_M12       := TO_CHAR(LAST_DAY(ADD_MONTHS(V_SYSDAT_DATE, -12)), 'YYYYMMDD');
  V_IS_MONTH_END        := CASE WHEN V_SYSDAT = TO_CHAR(LAST_DAY(V_SYSDAT_DATE), 'yyyymmdd') THEN 'Y' ELSE 'N' END;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_INDX_TRND_ANLYZ';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_INDX_TRND_ANLYZ';

  --***************************************
  -- 2.1 -- 第1段处理开始：装载客户指标当前值临时表
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_ADS_CUST_INDX_TRND_ANLYZ (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      INDX_CODE,
      VALUE_01,
      DATA_DATE
  )
  SELECT T1.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.CUST_ID             AS CUST_ID,             -- 客户编号
         CASE WHEN T1.BAL_TYPE = '1' THEN 'AUM'
              WHEN T1.BAL_TYPE = '2' THEN 'AUM_MTH_AVG'
              WHEN T1.BAL_TYPE = '3' THEN 'AUM_QRT_AVG'
              ELSE 'AUM_YER_AVG'
          END                   AS INDX_CODE,           -- 指标编号
         T1.AUM_BAL             AS VALUE_01,            -- 当前值/AUM余额
         T1.DATA_DATE           AS DATA_DATE            -- 数据日期
    FROM DWS_CUST_ASSE_LIAB T1                          -- 客户资产负债表
   WHERE T1.BAL_TYPE IN ('1', '2', '3', '4')
  UNION ALL
  SELECT T1.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.CUST_ID             AS CUST_ID,             -- 客户编号
         CASE WHEN T1.BAL_TYPE = '1' THEN 'DEPO_BAL'
              WHEN T1.BAL_TYPE = '2' THEN 'DEPO_MTH_AVG'
              WHEN T1.BAL_TYPE = '3' THEN 'DEPO_QRT_AVG'
              ELSE 'DEPO_YER_AVG'
          END                   AS INDX_CODE,           -- 指标编号
         NVL(T1.FIXD_DEPO_BAL, 0)
       + NVL(T1.DEPO_CURNT_DEPO_BAL, 0)
                               AS VALUE_01,             -- 当前值/存款余额
         T1.DATA_DATE           AS DATA_DATE            -- 数据日期
    FROM DWS_CUST_ASSE_LIAB T1                          -- 客户资产负债表
   WHERE T1.BAL_TYPE IN ('1', '2', '3', '4')
  UNION ALL
  SELECT T1.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.CUST_ID             AS CUST_ID,             -- 客户编号
         CASE WHEN T1.BAL_TYPE = '1' THEN 'FIN_AMT'
              WHEN T1.BAL_TYPE = '2' THEN 'FIN_MTH_AVG'
              WHEN T1.BAL_TYPE = '3' THEN 'FIN_QRT_AVG'
              ELSE 'FIN_YER_AVG'
          END                   AS INDX_CODE,           -- 指标编号
         T1.FIN_BAL             AS VALUE_01,            -- 当前值/理财余额
         T1.DATA_DATE           AS DATA_DATE            -- 数据日期
    FROM DWS_CUST_ASSE_LIAB T1                          -- 客户资产负债表
   WHERE T1.BAL_TYPE IN ('1', '2', '3', '4')
  UNION ALL
  SELECT T1.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.CUST_ID             AS CUST_ID,             -- 客户编号
         CASE WHEN T1.BAL_TYPE = '1' THEN 'INSUR_BAL'
              WHEN T1.BAL_TYPE = '2' THEN 'INSUR_MTH_AVG'
              WHEN T1.BAL_TYPE = '3' THEN 'INSUR_QRT_AVG'
              ELSE 'INSUR_YER_AVG'
          END                   AS INDX_CODE,           -- 指标编号
         T1.INSUR_BAL           AS VALUE_01,            -- 当前值/保险余额
         T1.DATA_DATE           AS DATA_DATE            -- 数据日期
    FROM DWS_CUST_ASSE_LIAB T1                          -- 客户资产负债表
   WHERE T1.BAL_TYPE IN ('1', '2', '3', '4')
  UNION ALL
  SELECT T1.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.CUST_ID             AS CUST_ID,             -- 客户编号
         CASE WHEN T1.BAL_TYPE = '1' THEN 'LOAN_BAL'
              WHEN T1.BAL_TYPE = '2' THEN 'LOAN_MTH_AVG'
              WHEN T1.BAL_TYPE = '3' THEN 'LOAN_QRT_AVG'
              ELSE 'LOAN_YER_AVG'
          END                   AS INDX_CODE,           -- 指标编号
         T1.LOAN_BAL            AS VALUE_01,            -- 当前值/贷款余额
         T1.DATA_DATE           AS DATA_DATE            -- 数据日期
    FROM DWS_CUST_ASSE_LIAB T1                          -- 客户资产负债表
   WHERE T1.BAL_TYPE IN ('1', '2', '3', '4')
  UNION ALL
  SELECT T1.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.CUST_ID             AS CUST_ID,             -- 客户编号
         'CUST_LVL'             AS INDX_CODE,           -- 指标编号
         TO_NUMBER(T1.CUST_LVL) AS VALUE_01,            -- 当前值/客户等级,字符型转数值
         T1.DATA_DATE           AS DATA_DATE            -- 数据日期
    FROM DWS_CUST_LVL_INFO T1                           -- 客户等级
   WHERE 1 = 1;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：生成13个月客户趋势数据
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CUST_INDX_TRND_ANLYZ (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      INDX_CODE,
      VALUE_01,
      VALUE_02,
      VALUE_03,
      VALUE_04,
      VALUE_05,
      VALUE_06,
      VALUE_07,
      VALUE_08,
      VALUE_09,
      VALUE_10,
      VALUE_11,
      VALUE_12,
      VALUE_13,
      DATA_DATE
  )
  SELECT B.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         B.CUST_ID             AS CUST_ID,             -- 客户编号
         B.INDX_CODE           AS INDX_CODE,           -- 指标编号
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_CURR THEN B.VALUE_01 ELSE 0 END) AS VALUE_01, -- 当前值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M01  THEN B.VALUE_01 ELSE 0 END) AS VALUE_02, -- 前1个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M02  THEN B.VALUE_01 ELSE 0 END) AS VALUE_03, -- 前2个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M03  THEN B.VALUE_01 ELSE 0 END) AS VALUE_04, -- 前3个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M04  THEN B.VALUE_01 ELSE 0 END) AS VALUE_05, -- 前4个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M05  THEN B.VALUE_01 ELSE 0 END) AS VALUE_06, -- 前5个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M06  THEN B.VALUE_01 ELSE 0 END) AS VALUE_07, -- 前6个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M07  THEN B.VALUE_01 ELSE 0 END) AS VALUE_08, -- 前7个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M08  THEN B.VALUE_01 ELSE 0 END) AS VALUE_09, -- 前8个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M09  THEN B.VALUE_01 ELSE 0 END) AS VALUE_10, -- 前9个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M10  THEN B.VALUE_01 ELSE 0 END) AS VALUE_11, -- 前10个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M11  THEN B.VALUE_01 ELSE 0 END) AS VALUE_12, -- 前11个月末值
         SUM(CASE WHEN B.DATA_DATE = V_DATA_DATE_M12  THEN B.VALUE_01 ELSE 0 END) AS VALUE_13, -- 前12个月末值
         V_DATA_DATE_CURR      AS DATA_DATE            -- 数据日期
    FROM (
          SELECT T1.DATA_DATE,
                 T1.PERSN_LEGAL_BK_CODE,
                 T1.CUST_ID,
                 T1.INDX_CODE,
                 T1.VALUE_01
            FROM TMP_ADS_CUST_INDX_TRND_ANLYZ T1        -- 客户指标趋势分析表_临时表
           WHERE T1.DATA_DATE = V_DATA_DATE_CURR
          UNION ALL
          SELECT T2.DATA_DATE,
                 T2.PERSN_LEGAL_BK_CODE,
                 T2.CUST_ID,
                 T2.INDX_CODE,
                 T2.VALUE_01
            FROM TMP2_ADS_CUST_INDX_TRND_ANLYZ T2       -- 客户指标趋势分析表_月表
           WHERE T2.DATA_DATE >= V_DATA_DATE_M12
             AND T2.DATA_DATE <  V_DATA_DATE_CURR
         ) B
   GROUP BY B.PERSN_LEGAL_BK_CODE,
            B.CUST_ID,
            B.INDX_CODE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：月末保存当月数据
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  IF V_IS_MONTH_END = 'Y' THEN
    DELETE FROM TMP2_ADS_CUST_INDX_TRND_ANLYZ
     WHERE DATA_DATE = V_DATA_DATE_CURR;

    INSERT INTO TMP2_ADS_CUST_INDX_TRND_ANLYZ (
        PERSN_LEGAL_BK_CODE,
        CUST_ID,
        INDX_CODE,
        VALUE_01,
        DATA_DATE
    )
    SELECT T1.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
           T1.CUST_ID             AS CUST_ID,             -- 客户编号
           T1.INDX_CODE           AS INDX_CODE,           -- 指标编号
           T1.VALUE_01            AS VALUE_01,            -- 当前值
           T1.DATA_DATE           AS DATA_DATE            -- 数据日期
      FROM TMP_ADS_CUST_INDX_TRND_ANLYZ T1                -- 客户指标趋势分析表_临时表
     WHERE 1 = 1;
  END IF;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

    -- ***************************************
    -- 3. 异常处理区(捕获错误码并记录详细日志)
    -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_label_aa01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_label_aa01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_基础信息表
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AA01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：DWD_CUST_INDV_INFO(客户基本信息表)
  -- 目标表：ADS_CUST_LABEL_AA01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_基础信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_LABEL_AA01';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_AA01';

  --***************************************
  -- 2.1 -- 第1段处理开始：客户基础标签
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：客户基础标签
  INSERT INTO ADS_CUST_LABEL_AA01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      AA02,
      AA03,
      AA04,
      AA05,
      AA06,
      AA07,
      AA08,
      AA09,
      AA10,
      AA11
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 核心客户号
         T1.CUST_NAME            AS AA02                 , -- 客户名称
         T1.CERT_ID              AS AA03                 , -- 证件号码
         T1.GEND                 AS AA04                 , -- 性别
         T1.AGE                  AS AA05                 , -- 年龄
         T1.NATION               AS AA06                 , -- 民族
         T1.MARI_SITU            AS AA07                 , -- 婚姻状况
         T1.PHONE_NO             AS AA08                 , -- 手机号码
         T1.OCCU_CLS             AS AA09                 , -- 职业
         T1.MAX_DEG_EDU          AS AA10                 , -- 最高学历
         T1.CERT_TYP             AS AA11                  -- 证件类型
    FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
   WHERE 1=1;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：客户基础标签';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_label_ab01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_label_ab01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_否小微企业主表
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AB01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：CMS_ENT_INFO(待确认：来源表中文名缺失)；CMS_KH(信贷小微企业客户)；DWD_CUST_INDV_INFO(客户基本信息表)
  -- 目标表：ADS_CUST_LABEL_AB01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_否小微企业主表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_LABEL_AB01';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_AB01';

  --***************************************
  -- 2.1 -- 第1段处理开始：处理是否小微企业主
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理是否小微企业主
  INSERT INTO ADS_CUST_LABEL_AB01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      AB01
  )
  WITH CMS_KH AS (
    SELECT
    DISTINCT ECIFID
    FROM CMS_ENT_INFO EI --企业客户表
    INNER JOIN CMS_CUSTOMER_RELATIVE CR --客户关联表
    ON EI.CUSTOMERID = CR.CUSTOMERID
      AND CR.RELATIONSHIP = '0100'
    WHERE EI.SCOPE IN ('4', '5') --企业规模
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 客户编号
         CASE
          WHEN T2.ECIFID IS NOT NULL
          THEN 1 
          ELSE 0
         END AS AB01 -- 是否小微企业主
    FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
    LEFT JOIN CMS_KH T2 -- 信贷小微企业客户
      ON T1.PARTY_ID = T2.ECIFID
   WHERE 1=1;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理是否小微企业主';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
