-- DROP PROCEDURE crmdm.prc_ads_cust_label_ae01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_label_ae01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_是否代发客户表
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AE01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：CBS_KDPL_ZHMINX(账户余额发生明细)；DF_CUST(代发客户核心客户号)；DWD_CUST_INDV_INFO(客户基本信息表)；IBP_CZDF_BAT_DETAIL(惠民惠农代发明细表)；IBP_LSSB_BAT_INFO(待确认：来源表中文名缺失)；IBP_LSSB_TRANS_DETAIL(市社保代发明细表)；IBP_SCSB_BAT_DETAIL(省社保代发明细表)；TMP_ADS_CUST_LABEL_AE01(待确认：来源表中文名缺失);CBS_KCDA_PZJCXX(银行卡卡凭证基础表)
  -- 目标表：ADS_CUST_LABEL_AE01；TMP_ADS_CUST_LABEL_AE01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_是否代发客户表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_LABEL_AE01';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_LAST_MONTH_START    VARCHAR(8);
  V_LAST_MONTH_END      VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_LAST_MONTH_START   := TO_CHAR(TRUNC(ADD_MONTHS(TO_DATE(V_SYSDAT, 'yyyymmdd'), -1), 'MM'), 'yyyymmdd');
  V_LAST_MONTH_END     := TO_CHAR(LAST_DAY(ADD_MONTHS(TO_DATE(V_SYSDAT, 'yyyymmdd'), -1)), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABEL_AE01';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_AE01';

  --***************************************
  -- 2.1 -- 第1段处理开始：处理省社保行内代发成功客户、处理市社保行内代发成功客户、处理惠民惠农代发成功客户、处理核心代发成功客户
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理省社保行内代发成功客户、处理市社保行内代发成功客户、处理惠民惠农代发成功客户、处理核心代发成功客户
  INSERT INTO TMP_ADS_CUST_LABEL_AE01 (
      DATA_DATE,
      ACCT_NO
  )
  SELECT DISTINCT
         T.DATA_DATE             , -- 数据日期
         T.ACCT_NO                -- 银行账号
    FROM (
          -- 处理省社保行内代发成功客户
          SELECT
                 V_SYSDAT  AS DATA_DATE  , -- 数据日期
                 T1.ACCT   AS ACCT_NO     -- 银行账号
            FROM IBP_SCSB_BAT_DETAIL T1 -- 省社保代发明细表
           WHERE T1.IS_OTHER_BANK = '1' AND T1.STATUS = '2'
          UNION
          -- 处理市社保行内代发成功客户
          SELECT
                 V_SYSDAT    AS DATA_DATE  , -- 数据日期
                 T1.ACCT_NO  AS ACCT_NO     -- 银行账号
            FROM IBP_LSSB_TRANS_DETAIL T1 -- 市社保代发明细表
            LEFT JOIN IBP_LSSB_BAT_INFO T2 -- 待确认：来源表中文名缺失
              ON T1.BATCH_NO = T2.BATCH_NO
           WHERE T2.IS_OTHER_BANK = '1' AND T1.STATUS = '2'
             AND T2.BUILD_TIME >= V_LAST_MONTH_START
             AND T2.BUILD_TIME <= V_LAST_MONTH_END
          UNION
          -- 处理惠民惠农代发成功客户
          SELECT
                 V_SYSDAT         AS DATA_DATE  , -- 数据日期
                 T1.COLL_ACCOUNT  AS ACCT_NO     -- 银行账号
            FROM IBP_CZDF_BAT_DETAIL T1 -- 惠民惠农代发明细表
           WHERE T1.IS_OTHER_BANK = '1' AND T1.STATUS = '2'
          UNION
          -- 处理核心代发成功客户
          SELECT
                 V_SYSDAT     AS DATA_DATE  , -- 数据日期
                 T1.KEHUZHAO  AS ACCT_NO     -- 银行账号
            FROM CBS_KDPL_ZHMINX T1 -- 账户余额发生明细
           WHERE T1.ZHAIYOMS LIKE '%工资%' AND T1.JIAOYIRQ >= V_LAST_MONTH_START AND T1.JIAOYIRQ <= V_LAST_MONTH_END
         ) T;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理省社保行内代发成功客户、处理市社保行内代发成功客户、处理惠民惠农代发成功客户、处理核心代发成功客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：处理省是否代发客户
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：处理省是否代发客户
  INSERT INTO ADS_CUST_LABEL_AE01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      AE01
  )
  SELECT
         V_SYSDAT                               AS DATA_DATE            , -- 数据日期
         CASE
			  WHEN T2.FAKAJIGO LIKE '12%' THEN '1200'
			  WHEN T2.FAKAJIGO LIKE '15%' THEN '1500'
			  WHEN T2.FAKAJIGO LIKE '18%' THEN '1800'
			  ELSE '9999'
			END                                 AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.KEHUHAOO                            AS AA01                 , -- 客户编号
         '1'                                    AS AE01 -- 是否代发客户
    FROM TMP_ADS_CUST_LABEL_AE01 T1	--客户基础标签_是否代发客户表_临时表
    LEFT JOIN CBS_KCDA_PZJCXX T2	--银行卡卡凭证基础表
      ON T1.ACCT_NO = T2.KAHAOOOO
   WHERE T2.KEHUHAOO IS NOT NULL;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：处理省是否代发客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_label_af01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_label_af01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_纯新户开户标志表
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AF01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：CBS_KDPA_ZHXINX(负债账户信息表)；DWD_CUST_INDV_INFO(客户基本信息表)；TMP1_ADS_CUST_LABEL_AF01(客户基础标签_纯新户开户标志表_临时表)
  -- 目标表：ADS_CUST_LABEL_AF01；TMP1_ADS_CUST_LABEL_AF01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_纯新户开户标志表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_LABEL_AF01';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_CUST_LABEL_AF01';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_AF01';

  --***************************************
  -- 2.1 -- 第1段处理开始：处理客户负债账号数据
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理客户负债账号数据
  INSERT INTO TMP1_ADS_CUST_LABEL_AF01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      ACTIVE_CNT,
      OLD_ACTIVE_CNT,
      MIN_ACTIVE_OPEN_DATE,
      MAX_CLOSE_DATE
  )
  SELECT
         V_SYSDAT     AS DATA_DATE             , -- 数据日期
         CASE
           WHEN T1.KAIHJIGO LIKE '12%' THEN '1200'
           WHEN T1.KAIHJIGO LIKE '15%' THEN '1500'
           WHEN T1.KAIHJIGO LIKE '18%' THEN '1800'
           ELSE '9999'
         END AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.KEHUHAOO  AS CUST_ID               , -- 客户编号
         SUM(
          CASE
           WHEN T1.ZHHUZTAI <> 'C' OR T1.ZHHUZTAI IS NULL
           THEN 1
           ELSE 0
          END
         ) AS ACTIVE_CNT, -- 当前未销户负债账号数量
         SUM(
          CASE
           WHEN (T1.ZHHUZTAI <> 'C' OR T1.ZHHUZTAI IS NULL)
           AND T1.KAIHRIQI IS NOT NULL
           AND TO_DATE(T1.KAIHRIQI, 'YYYYMMDD') < TO_DATE(V_SYSDAT, 'YYYYMMDD') - 180
           THEN 1
           ELSE 0
          END
         ) AS OLD_ACTIVE_CNT, -- 当前未销户但开户超过 180 天的负债账号数量
         MIN(
          CASE
           WHEN (T1.ZHHUZTAI <> 'C' OR T1.ZHHUZTAI IS NULL)
           AND T1.KAIHRIQI IS NOT NULL
           THEN T1.KAIHRIQI
          END
         ) AS MIN_ACTIVE_OPEN_DATE, -- 当前未销户负债账号中最早开户日期
         MAX(
          CASE
           WHEN T1.ZHHUZTAI = 'C'
           AND T1.XIOHRIQI IS NOT NULL
           THEN T1.XIOHRIQI
          END
         ) AS MAX_CLOSE_DATE -- 最近一次销户日期
    FROM CBS_KDPA_ZHXINX T1 -- 负债账户信息表
   GROUP BY T1.KEHUHAOO,
     CASE
     WHEN T1.KAIHJIGO LIKE '12%' THEN '1200'
     WHEN T1.KAIHJIGO LIKE '15%' THEN '1500'
     WHEN T1.KAIHJIGO LIKE '18%' THEN '1800'
     ELSE '9999'
     END;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理客户负债账号数据';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：处理纯新开户标志
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：处理纯新开户标志
  INSERT INTO ADS_CUST_LABEL_AF01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      AF01
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 客户编号
         CASE
          WHEN NVL(T2.ACTIVE_CNT, 0) > 0                         -- 当前存在未销户负债账号
          AND NVL(T2.OLD_ACTIVE_CNT, 0) = 0                      -- 当前未销户负债账号全部为 180 天内新开
          AND (
           T2.MAX_CLOSE_DATE IS NULL                       -- 无历史销户记录,视为首次新开户
           OR T2.MIN_ACTIVE_OPEN_DATE >= T2.MAX_CLOSE_DATE + 180 -- 最近销户满 180 天后重新开户
           )
          THEN 1
          ELSE 0
         END AS AF01 -- 纯新户开户标志
    FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
    LEFT JOIN TMP1_ADS_CUST_LABEL_AF01 T2 -- 客户基础标签_纯新户开户标志表_临时表
      ON T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T1.CUST_ID = T2.CUST_ID
   WHERE 1=1;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：处理纯新开户标志';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_label_ag01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_label_ag01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_是否本行员工表
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AG01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：CBS_KDPA_ZHXINX(待确认：来源表中文名缺失)；DWD_CUST_INDV_INFO(客户基本信息表)；TYRZ_TB_SUSR(用户信息表)
  -- 目标表：ADS_CUST_LABEL_AG01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_是否本行员工表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_LABEL_AG01';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_AG01';

  --***************************************
  -- 2.1 -- 第1段处理开始：处理是否本行员工表
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理是否本行员工表
  INSERT INTO ADS_CUST_LABEL_AG01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      AG01
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 客户编号
         CASE
          WHEN T2.SUSR_MOBILE IS NULL 
          THEN 0
          ELSE 1
         END AS AG01 -- 是否本行员工
    FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
    LEFT JOIN TYRZ_TB_SUSR T2 -- 用户信息表
      ON T1.PHONE_NO = T2.SUSR_MOBILE
   WHERE 1=1;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理是否本行员工表';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_label_ah01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_label_ah01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_产品偏好表
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AH01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：DWD_CUST_INDV_INFO(客户基本信息表)；DWS_CUST_ASSE_LIAB_HIS(客户资产负债历史表)
  -- 目标表：ADS_CUST_LABEL_AH01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_产品偏好表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_LABEL_AH01';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_LAST_YEAR_END       VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_LAST_YEAR_END      := TO_CHAR(LAST_DAY(ADD_MONTHS(TRUNC(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'YYYY'), -1)), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_AH01';

  --***************************************
  -- 2.1 -- 第1段处理开始：处理产品偏好
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理产品偏好
  INSERT INTO ADS_CUST_LABEL_AH01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      AF01
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 客户编号
         CASE
               /* 四类储蓄产品上年年日均合计为0,则无法判断偏好产品 */
               WHEN NVL(T2.DEPO_CURNT_DEPO_BAL, 0)
                  + NVL(T2.FIXD_DEPO_BAL, 0)
                  + NVL(T2.LEHUI_BAL, 0)
                  + NVL(T2.LARGEDP_BAL, 0) = 0
               THEN NULL
         
               /* 活期余额年日均占比最高 */
               WHEN NVL(T2.DEPO_CURNT_DEPO_BAL, 0) >= NVL(T2.FIXD_DEPO_BAL, 0)
                AND NVL(T2.DEPO_CURNT_DEPO_BAL, 0) >= NVL(T2.LEHUI_BAL, 0)
                AND NVL(T2.DEPO_CURNT_DEPO_BAL, 0) >= NVL(T2.LARGEDP_BAL, 0)
               THEN '01'
         
               /* 普通定期余额年日均占比最高 */
               WHEN NVL(T2.FIXD_DEPO_BAL, 0) >= NVL(T2.LEHUI_BAL, 0)
                AND NVL(T2.FIXD_DEPO_BAL, 0) >= NVL(T2.LARGEDP_BAL, 0)
               THEN '02'
         
               /* 乐惠存产品余额年日均占比最高 */
               WHEN NVL(T2.LEHUI_BAL, 0) >= NVL(T2.LARGEDP_BAL, 0)
               THEN '03'
         
               /* 大额存单余额年日均占比最高 */
               ELSE '05'
             END AS AF01 -- 产品偏好
    FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
    LEFT JOIN DWS_CUST_ASSE_LIAB_HIS T2 -- 客户资产负债历史表
      ON T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T1.CUST_ID = T2.CUST_ID AND T2.BAL_TYPE = '4' AND T2.DATA_DATE = V_LAST_YEAR_END
   WHERE 1=1;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理产品偏好';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_label_ai01(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_label_ai01(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基础标签_储蓄产品期限偏好表
  -- 存储过程编号：PRC_ADS_CUST_LABEL_AI01
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：DWD_ACCT_DEPO(存款账户信息表)；DWD_CUST_INDV_INFO(客户基本信息表)；DWS_CUST_ASSE_LIAB_CUMU_HIS(客户资产负债基数历史表)；TMP_ADS_CUST_LABEL_AI01(产品期限年日均)
  -- 目标表：ADS_CUST_LABEL_AI01；TMP_ADS_CUST_LABEL_AI01
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基础标签_储蓄产品期限偏好表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_LABEL_AI01';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_LAST_YEAR_END       VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_LAST_YEAR_END      := TO_CHAR(ADD_MONTHS(TRUNC(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'YYYY'), -1), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABEL_AI01';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_AI01';

  --***************************************
  -- 2.1 -- 第1段处理开始：处理储蓄产品期限年日均
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理储蓄产品期限年日均
  INSERT INTO TMP_ADS_CUST_LABEL_AI01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUNQ,
      QX_YAR_AVG
  )
  SELECT
         V_SYSDAT                 AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE   AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID               AS CUST_ID              , -- 客户编号
         CASE
			WHEN T1.CUNQ IN ('5Y', '6Y') THEN '03'
			WHEN T1.CUNQ IN ('2Y', '3Y') THEN '02'
			ELSE '01'
		 END                       AS CUNQ                 , -- 存期
         SUM(YAR_BAL / YAR_DAYS)  AS QX_YAR_AVG            -- 储蓄产品期限年日均
    FROM DWD_ACCT_DEPO T1 -- 存款账户信息表
    LEFT JOIN DWS_CUST_ASSE_LIAB_CUMU_HIS T2 -- 客户资产负债基数历史表
      ON T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T1.CUST_ID = T2.CUST_ID AND T1.ACCT_ID = T2.ACCT_ID AND T1.PRDKT_ID = T2.PRDKT_ID AND T2.PRDKT_TYP = '4' AND T2.DATA_DATE = V_LAST_YEAR_END
   WHERE T1.CUNKZLEI IN ('01', '02', '03', '04', '05', '06', '07', '26', '29')
     GROUP BY T1.PERSN_LEGAL_BK_CODE,T1.CUST_ID,T1.CUNQ;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理储蓄产品期限年日均';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：处理储蓄产品期限偏好
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：处理储蓄产品期限偏好
  INSERT INTO ADS_CUST_LABEL_AI01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      AI01
  )
  SELECT
         R.DATA_DATE         , -- 数据日期
         R.PERSN_LEGAL_BK_CODE, -- 法人行号
         R.AA01              , -- 客户编号
         R.AI01               -- 储蓄产品期限偏好
    FROM (
          SELECT
                 V_SYSDAT                AS DATA_DATE            , -- 数据日期
                 T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID              AS AA01                 , -- 客户编号
                 T2.CUNQ                 AS AI01                 , -- 储蓄产品期限偏好
                 ROW_NUMBER() OVER (
                   PARTITION BY T1.PERSN_LEGAL_BK_CODE,T1.CUST_ID
                   ORDER BY T2.QX_YAR_AVG DESC
                 ) AS RN
      FROM DWD_CUST_INDV_INFO T1 -- 客户基本信息表
      LEFT JOIN TMP_ADS_CUST_LABEL_AI01 T2 -- 产品期限年日均
        ON T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T1.CUST_ID = T2.CUST_ID
     WHERE 1=1
         ) R
   WHERE R.RN = 1;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：处理储蓄产品期限偏好';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

