  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_NEAR_MONTH_START    VARCHAR(8);
  V_CUR_MONTH_START     VARCHAR(8);
  V_CUR_YEAR_START      VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_NEAR_MONTH_START   := TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'yyyymmdd'), -1), 'yyyymmdd');
  V_CUR_MONTH_START    := TO_CHAR(TRUNC(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'MM'), 'yyyymmdd');
  V_CUR_YEAR_START     := TO_CHAR(TRUNC(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'YYYY'), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABEL_QDFX';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD01';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD02';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD03';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD05';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD06';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD07';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD08';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD09';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD10';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABEL_QD11';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD11';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD12';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD13';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_CUST_LABEL_QD14';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_CUST_LABEL_QD14';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP2_ADS_CUST_LABEL_QD14';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_CUST_LABEL_QD14';
  DELETE FROM TMP1_ADS_CUST_LABEL_QD11 WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：处理-临时表银行卡发卡机构
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理-临时表银行卡发卡机构
  INSERT INTO TMP_ADS_CUST_LABEL_QDFX (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CARD_NO
  )
  SELECT
         V_SYSDAT     AS DATA_DATE            , -- 数据日期
         CASE
           WHEN T1.FAKAJIGO LIKE '12%' THEN '1200'
           WHEN T1.FAKAJIGO LIKE '15%' THEN '1500'
           WHEN T1.FAKAJIGO LIKE '18%' THEN '1800'
           ELSE '9999'
         END AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.KEHUHAOO  AS CUST_ID              , -- 客户编号
         T1.KAHAOOOO  AS CARD_NO               -- 卡号
    FROM CBS_KCDA_PZJCXX T1 WHERE T1.KEHUHAOO IS NOT NULL; -- 银行卡卡凭证基础表

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理-临时表银行卡发卡机构';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：处理-是否自助注册手机银行
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：处理-是否自助注册手机银行
  INSERT INTO ADS_CUST_LABEL_QD01 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD01
  )
  SELECT
         V_SYSDAT         AS DATA_DATE            , -- 数据日期
         '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_CORE_NO  AS AA01                 , -- 客户编号
         '1'              AS QD01                  -- 是否自助注册手机银行
    FROM MBK_CUST_INFO T1 -- 客户信息表
   WHERE T1.CUST_CAP_LVL IN ('01','02')
     AND T1.CUST_STATUS != '0'
     AND T1.CUST_CORE_NO IS NOT NULL
     AND TO_NUMBER(TO_DATE(V_SYSDAT, 'YYYY-MM-DD') -
     TO_DATE(T1.CUST_OPEN_DATE, 'YYYY-MM-DD')) >= 1;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：处理-是否自助注册手机银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：处理-是否柜面签约手机银行
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：处理-是否柜面签约手机银行
  INSERT INTO ADS_CUST_LABEL_QD02 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD02
  )
  SELECT
         V_SYSDAT         AS DATA_DATE            , -- 数据日期
         '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_CORE_NO  AS AA01                 , -- 客户编号
         '1'              AS QD02                  -- 是否柜面签约手机银行
    FROM MBK_CUST_INFO T1 -- 客户信息表
   WHERE T1.CUST_CAP_LVL IN ('03')
     AND T1.CUST_CORE_NO IS NOT NULL
     AND T1.CUST_STATUS != '0';

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：处理-是否柜面签约手机银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：处理-近1月手机银行累计交易笔数_金额
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 第4段业务逻辑：处理-近1月手机银行累计交易笔数_金额
  INSERT INTO ADS_CUST_LABEL_QD03 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD03,
      QD04
  )
  SELECT
         V_SYSDAT     AS DATA_DATE            , -- 数据日期
         '9999'       AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID   AS AA01                 , -- 客户编号
         COUNT(*)     AS QD03                 , -- 交易笔数
         SUM(T1.AMT)  AS QD04                  -- 交易金额
    FROM DWD_TX_ASET T1 -- 资产交易信息表
   WHERE T1.TX_DATE >= V_NEAR_MONTH_START  --近一个月
     AND T1.TX_CHNL = '3031' --手机银行
     AND T1.XIANZZBZ = '1' --1 代表转账
     AND T1.CHONGZBZ = '0' --要未冲正的数据
     GROUP BY T1.CUST_ID;

  -- 提交第4段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：处理-近1月手机银行累计交易笔数_金额';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5 -- 第5段处理开始：处理-近1月行外入账金额
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  -- 第5段业务逻辑：处理-近1月行外入账金额
  INSERT INTO ADS_CUST_LABEL_QD05 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD05
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 客户编号
         SUM(T1.AMT)             AS QD05                  -- 近1月行外入账金额
    FROM DWD_TX_ASET T1 -- 资产交易信息表
   WHERE T1.TX_DATE >= V_NEAR_MONTH_START  --近一个月
     AND T1.XIANZZBZ = '1' --1 代表转账
     AND T1.LOAN_FLG = '1' --代表转入
     AND T1.CHONGZBZ = '0' --要未冲正的数据
     AND (T1.OPNT_NAME_BK NOT LIKE '%乐山%' OR T1.OPNT_NAME_BK IS NULL)
     GROUP BY T1.PERSN_LEGAL_BK_CODE, T1.CUST_ID;

  -- 提交第5段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第5段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段业务逻辑处理完成：处理-近1月行外入账金额';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第5段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.6 -- 第6段处理开始：处理-是否登录手机银行并完成绑卡客户
  --***************************************
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  -- 第6段业务逻辑：处理-是否登录手机银行并完成绑卡客户
  INSERT INTO ADS_CUST_LABEL_QD06 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD06
  )
  SELECT
         V_SYSDAT         AS DATA_DATE            , -- 数据日期
         '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_CORE_NO  AS AA01                 , -- 客户编号
         '1'              AS QD06                  -- 是否登录手机银行并完成绑卡
    FROM MBK_CUST_INFO T1 -- 客户信息表
    LEFT JOIN MBK_CUST_LOGIN_AUTH T2 -- 客户登录密码认证表
      ON T1.CUST_NO = T2.CUST_NO
   WHERE T1.CUST_STATUS != '0' AND T1.CUST_CAP_LVL IN ('02','03')
     AND T1.CUST_CORE_NO IS NOT NULL
     AND T2.FIRST_LGN_FLAG = 'Y';

  -- 提交第6段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第6段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6段业务逻辑处理完成：处理-是否登录手机银行并完成绑卡客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第6段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.7 -- 第7段处理开始：处理-注册并登录手机银行客户的天数
  --***************************************
  V_NO_ID := '7';
  V_BGN_DATE := SYSDATE;

  -- 第7段业务逻辑：处理-注册并登录手机银行客户的天数
  INSERT INTO ADS_CUST_LABEL_QD07 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD07
  )
  SELECT
         V_SYSDAT                                     AS DATA_DATE            , -- 数据日期
         '9999'                                       AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_CORE_NO                              AS AA01                 , -- 客户编号
         TO_NUMBER(TO_DATE(V_SYSDAT, 'yyyy-mm-dd') -
                              TO_DATE(T2.FIRST_LGN_DATE, 'yyyy-mm-dd')) AS QD07 -- 注册并登录手机银行客户的天数
    FROM MBK_CUST_INFO T1 -- 客户信息表
    LEFT JOIN MBK_CUST_LOGIN_AUTH T2 -- 客户登录密码认证表
      ON T1.CUST_NO = T2.CUST_NO
   WHERE T1.CUST_STATUS != '0'
     AND T1.CUST_CORE_NO IS NOT NULL
     AND T2.FIRST_LGN_FLAG = 'Y';

  -- 提交第7段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第7段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第7段业务逻辑处理完成：处理-注册并登录手机银行客户的天数';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第7段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.8 -- 第8段处理开始：处理-当月登录手机银行次数
  --***************************************
  V_NO_ID := '8';
  V_BGN_DATE := SYSDATE;

  -- 第8段业务逻辑：处理-当月登录手机银行次数
  INSERT INTO ADS_CUST_LABEL_QD08 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD08
  )
  SELECT
         V_SYSDAT         AS DATA_DATE            , -- 数据日期
         '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_CORE_NO  AS AA01                 , -- 客户编号
         COUNT(*)         AS QD08                  -- 当月登录手机银行次数
    FROM MBK_CUST_INFO T1 -- 客户信息表
    LEFT JOIN MBK_CUST_LOG_LOGIN T2 -- 客户登录日志表
      ON T1.CUST_NO = T2.CUST_NO
   WHERE T1.CUST_STATUS != '0'
     AND T1.CUST_CORE_NO IS NOT NULL
     AND T2.LGN_STATUS = '1' -- 登录成功
     AND T2.LGN_DATE >= V_CUR_MONTH_START  --月初
     GROUP BY T1.CUST_CORE_NO;

  -- 提交第8段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第8段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第8段业务逻辑处理完成：处理-当月登录手机银行次数';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第8段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.9 -- 第9段处理开始：处理-是否完成三方支付绑卡
  --***************************************
  V_NO_ID := '9';
  V_BGN_DATE := SYSDATE;

  -- 第9段业务逻辑：处理-是否完成三方支付绑卡
  INSERT INTO ADS_CUST_LABEL_QD09 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD09
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期；待确认：DATA_DATE 缺少来源字段或映射规则
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 客户编号
         '1'                     AS QD09                  -- 是否完成三方支付绑卡
    FROM DWD_CUST_SIGN_CTRAKT T1 -- 客户签约信息
   WHERE T1.SIGN_TYPE IN ('134','136','131','135','3381','3302','','') --签约类型
     GROUP BY T1.PERSN_LEGAL_BK_CODE, T1.CUST_ID;

  -- 提交第9段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第9段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第9段业务逻辑处理完成：处理-是否完成三方支付绑卡';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第9段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.10 -- 第10段处理开始：处理-当年客户参与手机银行热门活动的次数、折扣活动、普通活动
  --***************************************
  V_NO_ID := '10';
  V_BGN_DATE := SYSDATE;

  -- 第10段业务逻辑：处理-当年客户参与手机银行热门活动的次数、折扣活动、普通活动
  INSERT INTO ADS_CUST_LABEL_QD10 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD10
  )
  SELECT
         T.DATA_DATE             AS DATA_DATE             , -- 数据日期
         T.PERSN_LEGAL_BK_CODE   AS PERSN_LEGAL_BK_CODE   , -- 法人行号
         T.AA01                  AS AA01                  , -- 客户编号
         SUM(NVL(T.QD10, 0))     AS QD10                   -- 热门活动的次数
    FROM (
          -- 处理-当年客户参与手机银行热门活动的次数
          SELECT
                 V_SYSDAT    AS DATA_DATE            , -- 数据日期
                 '9999'      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T2.ECIF_NO  AS AA01                 , -- 客户编号
                 COUNT(*)    AS QD10                  -- 热门活动的次数
            FROM MBK_MKP_JL_JOIN_INFO T1 -- 净蓝活动参与表
            LEFT JOIN MBK_MKP_JL_CUST T2 -- 待确认：来源表中文名缺失
              ON T1.USER_ID = T2.USER_ID
           WHERE TO_CHAR(TO_DATE(T1.TRAN_DATE,'YYYY-MM-DD'),'YYYYMMDD') > V_CUR_YEAR_START
             GROUP BY T2.ECIF_NO
          UNION
          -- 折扣活动
          SELECT
                 V_SYSDAT         AS DATA_DATE            , -- 数据日期
                 '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_CORE_NO  AS AA01                 , -- 客户编号
                 COUNT(*)         AS QD10                  -- 热门活动的次数
            FROM MBK_CUST_INFO T1 -- 客户信息表
            LEFT JOIN MBK_MKP_REBAT_RECODE T2 -- 手机银行折扣活动记录表
              ON T1.CUST_NO = T2.CUST_NO
           WHERE TO_CHAR(TO_DATE(T2.USER_TIME,'YYYY-MM-DD'),'YYYYMMDD') > V_CUR_YEAR_START AND T1.CUST_STATUS != '0'
             AND T1.CUST_CORE_NO IS NOT NULL
             GROUP BY T1.CUST_CORE_NO
          UNION
          -- 普通活动
          SELECT
                 V_SYSDAT         AS DATA_DATE            , -- 数据日期
                 '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_CORE_NO  AS AA01                 , -- 客户编号
                 COUNT(*)         AS QD10                  -- 热门活动的次数
            FROM MBK_CUST_INFO T1 -- 客户信息表
            LEFT JOIN MBK_MKP_ACTI_DRAWN_LIST T2 -- 手机银行普通活动中间记录表
              ON T1.CUST_NO = T2.CUST_NO
           WHERE TO_CHAR(TO_DATE(T2.DRAWN_TIME,'YYYY-MM-DD'),'YYYYMMDD') > V_CUR_YEAR_START AND T1.CUST_STATUS != '0'
             AND T1.CUST_CORE_NO IS NOT NULL
             GROUP BY T1.CUST_CORE_NO
         ) T
   GROUP BY T.DATA_DATE, T.PERSN_LEGAL_BK_CODE, T.AA01;

  -- 提交第10段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第10段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第10段业务逻辑处理完成：处理-当年客户参与手机银行热门活动的次数、折扣活动、普通活动';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第10段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.11 -- 第11段处理开始：处理-交易渠道偏好、处理-交易渠道偏好、处理-交易渠道偏好、处理-交易渠道偏好、处理-手机银行
  --***************************************
  V_NO_ID := '11';
  V_BGN_DATE := SYSDATE;

  -- 第11段业务逻辑：处理-交易渠道偏好、处理-交易渠道偏好、处理-交易渠道偏好、处理-交易渠道偏好、处理-手机银行
  INSERT INTO TMP_ADS_CUST_LABEL_QD11 (
      DATA_DATE,
      CARD_NO,
      ISSR_ID
  )
  -- 处理-交易渠道偏好
  SELECT
         V_SYSDAT              AS DATA_DATE  , -- 数据日期
         T1.PYER_ACCT_NO       AS CARD_NO    , -- 卡号
         T1.PYEE_ACCT_ISSR_ID  AS ISSR_ID     -- 渠道号
    FROM ECPP_E_TXN_COLLECTION T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND REPLACE(T1.SYS_DATE,'-','') = V_SYSDAT
  UNION
  -- 处理-交易渠道偏好
  SELECT
         V_SYSDAT              AS DATA_DATE  , -- 数据日期
         T1.PYER_ACCT_NO       AS CARD_NO    , -- 卡号
         T1.PYEE_ACCT_ISSR_ID  AS ISSR_ID     -- 渠道号
    FROM ECPP_E_HIS_COLLECTION T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND REPLACE(T1.SYS_DATE,'-','') = V_SYSDAT
  UNION
  -- 处理-交易渠道偏好
  SELECT
         V_SYSDAT              AS DATA_DATE  , -- 数据日期
         T1.PYER_ACCT_NO_DE    AS CARD_NO    , -- 卡号
         T1.PYEE_ACCT_ISSR_ID  AS ISSR_ID     -- 渠道号
    FROM ECPP_E_TXN_PAYMENT T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND REPLACE(T1.SYS_DATE,'-','') = V_SYSDAT
  UNION
  -- 处理-交易渠道偏好
  SELECT
         V_SYSDAT              AS DATA_DATE  , -- 数据日期
         T1.PYER_ACCT_NO_DE    AS CARD_NO    , -- 卡号
         T1.PYEE_ACCT_ISSR_ID  AS ISSR_ID     -- 渠道号
    FROM ECPP_E_HIS_PAYMENT T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND REPLACE(T1.SYS_DATE,'-','') = V_SYSDAT
  UNION
  -- 处理-手机银行
  SELECT
         V_SYSDAT    AS DATA_DATE  , -- 数据日期
         T1.CARD_NO  AS CARD_NO    , -- 卡号
         '3031'      AS ISSR_ID     -- 渠道号
    FROM DWD_TX_ASET T1 -- 资产交易信息表
   WHERE T1.TX_DATE = V_SYSDAT
     AND T1.TX_CHNL = '3031' --手机银行
     AND T1.XIANZZBZ = '1' --1 代表转账
     AND T1.CHONGZBZ = '0'; --要未冲正的数据

  -- 提交第11段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第11段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第11段业务逻辑处理完成：处理-交易渠道偏好、处理-交易渠道偏好、处理-交易渠道偏好、处理-交易渠道偏好、处理-手机银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第11段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.12 -- 第12段处理开始：处理-交易渠道偏好
  --***************************************
  V_NO_ID := '12';
  V_BGN_DATE := SYSDATE;

  -- 第12段业务逻辑：处理-交易渠道偏好
  INSERT INTO TMP1_ADS_CUST_LABEL_QD11 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      TX_CHNL_PREF,
      TXN_CNT
  )
  SELECT
         V_SYSDAT                                        AS DATA_DATE            , -- 数据日期
         T2.PERSN_LEGAL_BK_CODE                          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.CUST_ID                                      AS CUST_ID              , -- 客户编号
         CASE WHEN ISSR_ID IN ('134','136')  THEN 'TXCHNL001'
           WHEN ISSR_ID IN ('131','135')  THEN 'TXCHNL002'
           WHEN ISSR_ID IN ('3302')       THEN 'TXCHNL003'
           WHEN ISSR_ID IN ('138')        THEN 'TXCHNL004'
           WHEN ISSR_ID IN ('3381')       THEN 'TXCHNL005'
           WHEN ISSR_ID IN ('3031')       THEN 'TXCHNL006'
         END AS TX_CHNL_PREF, -- 交易渠道偏好
         COUNT(*)                                        AS TXN_CNT               -- 交易数量
    FROM TMP_ADS_CUST_LABEL_QD11 T1 -- 交易渠道偏好_三方支付交易临时表
    LEFT JOIN TMP_ADS_CUST_LABEL_QDFX T2 -- 客户基础标签_临时表银行卡发卡机构
      ON T1.CARD_NO = T2.CARD_NO
    LEFT JOIN DWD_ACCT_DEPO T3 -- 存款账户信息表
      ON T2.CUST_ID = T3.CUST_ID AND T2.PERSN_LEGAL_BK_CODE = T3.PERSN_LEGAL_BK_CODE AND T2.CARD_NO = T3.CARD_NO
   WHERE T1.ISSR_ID IN ('134','136','3031','131','135','3302','138','3381')
     GROUP BY T2.CUST_ID,T2.PERSN_LEGAL_BK_CODE,
     CASE WHEN T1.ISSR_ID IN ('134','136')  THEN 'TXCHNL001'
     WHEN T1.ISSR_ID IN ('131','135')  THEN 'TXCHNL002'
     WHEN T1.ISSR_ID IN ('3302')       THEN 'TXCHNL003'
     WHEN T1.ISSR_ID IN ('138')        THEN 'TXCHNL004'
     WHEN T1.ISSR_ID IN ('3381')       THEN 'TXCHNL005'
     WHEN T1.ISSR_ID IN ('3031')       THEN 'TXCHNL006'
     END;

  -- 提交第12段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第12段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第12段业务逻辑处理完成：处理-交易渠道偏好';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第12段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.13 -- 第13段处理开始：处理-交易渠道偏好
  --***************************************
  V_NO_ID := '13';
  V_BGN_DATE := SYSDATE;

  -- 第13段业务逻辑：处理-交易渠道偏好
  INSERT INTO ADS_CUST_LABEL_QD11 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD11
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS AA01                 , -- 客户编号
         T1.PREFER_CHANNEL       AS QD11                  -- 交易渠道偏好
    FROM (
         SELECT PERSN_LEGAL_BK_CODE,CUST_ID,
                PREFER_CHANNEL
         FROM (
                SELECT D.CUST_ID,D.PERSN_LEGAL_BK_CODE,
                       D.TX_CHNL_PREF AS PREFER_CHANNEL,
                       ROW_NUMBER() OVER (
                           PARTITION BY D.CUST_ID,D.PERSN_LEGAL_BK_CODE
                           ORDER BY SUM(D.TXN_CNT) DESC
                       ) AS RN
                  FROM TMP1_ADS_CUST_LABEL_QD11 D
            WHERE D.DATA_DATE >= V_CUR_YEAR_START
                 GROUP BY D.CUST_ID,D.PERSN_LEGAL_BK_CODE, D.TX_CHNL_PREF
           )
          WHERE RN = 1
         ) T1; -- 交易渠道偏好_交易笔数临时表

  -- 提交第13段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第13段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第13段业务逻辑处理完成：处理-交易渠道偏好';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第13段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.14 -- 第14段处理开始：处理-连续登录手机银行状态表
  --***************************************
  V_NO_ID := '14';
  V_BGN_DATE := SYSDATE;

  -- 第14段业务逻辑：处理-连续登录手机银行状态表
MERGE INTO TMP_ADS_CUST_LABEL_QD12 T
USING (
    /* 跑批日当天成功登录的有效客户,同一天多次登录只保留一条 */
    SELECT DISTINCT
           A.CUST_NO
      FROM MBK_CUST_INFO A              -- 客户信息表
      JOIN MBK_CUST_LOG_LOGIN B         -- 客户登录日志表
        ON A.CUST_NO = B.CUST_NO
     WHERE A.CUST_STATUS <> '0'         -- 有效客户
       AND A.CUST_CORE_NO IS NOT NULL   -- 客户号不能为空
       AND B.LGN_STATUS = '1'           -- 登录成功
       AND TO_CHAR(TO_DATE(B.LGN_DATE,'YYYY-MM-DD'),'YYYYMMDD') = V_SYSDAT        -- 跑批日当天登录
) S
ON (
    T.CUST_NO = S.CUST_NO               -- 按客户号匹配状态表
)
WHEN MATCHED THEN
  UPDATE SET
      T.CONT_LOGIN_DAYS =
        CASE
          WHEN T.LAST_LOGIN_DATE = V_SYSDAT
          THEN T.CONT_LOGIN_DAYS        -- 当天重复跑批,避免重复 +1
          WHEN T.LAST_LOGIN_DATE = TO_CHAR(TO_DATE(V_SYSDAT, 'YYYYMMDD') - 1, 'YYYYMMDD')
          THEN NVL(T.CONT_LOGIN_DAYS, 0) + 1
                                          -- 昨天也登录成功,连续天数 +1
          ELSE 1                          -- 中间断登后重新登录,从 1 开始
        END,
      T.LAST_LOGIN_DATE = V_SYSDAT,       -- 最近成功登录日期更新为跑批日
      T.UPDATE_DATE     = V_SYSDAT        -- 状态更新时间更新为跑批日

WHEN NOT MATCHED THEN
  INSERT (
      CUST_NO,                            -- 客户号
      LAST_LOGIN_DATE,                    -- 最近成功登录日期
      CONT_LOGIN_DAYS,                    -- 当前连续登录天数
      UPDATE_DATE                         -- 状态更新时间
  )
  VALUES (
      S.CUST_NO,                          -- 客户号
      V_SYSDAT,                           -- 首次纳入统计,最近登录日期为跑批日
      1,                                  -- 当天成功登录,连续天数初始化为 1
      V_SYSDAT                            -- 状态更新时间为跑批日
  );


/* 跑批日当天未成功登录的有效客户,连续登录天数置 0 */
UPDATE TMP_ADS_CUST_LABEL_QD12 T
   SET T.CONT_LOGIN_DAYS = 0,             -- 当天未登录,连续登录天数清零
       T.UPDATE_DATE     = V_SYSDAT       -- 状态更新时间更新为跑批日
 WHERE NVL(T.UPDATE_DATE, '19000101') <> V_SYSDAT
       -- 排除当天已经在 MERGE 中处理过的成功登录客户

   AND EXISTS (
       -- 只处理当前仍有效的客户
       SELECT 1
         FROM MBK_CUST_INFO A
        WHERE A.CUST_NO = T.CUST_NO
          AND A.CUST_STATUS <> '0'
   )

   AND NOT EXISTS (
       -- 确认客户跑批日当天没有成功登录记录
       SELECT 1
         FROM MBK_CUST_LOG_LOGIN B
        WHERE B.CUST_NO = T.CUST_NO
          AND B.LGN_STATUS = '1'
          AND TO_CHAR(TO_DATE(B.LGN_DATE,'YYYY-MM-DD'),'YYYYMMDD') = V_SYSDAT
   );

  -- 提交第14段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第14段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第14段业务逻辑处理完成：处理-连续登录手机银行状态表';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第14段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.15 -- 第15段处理开始：处理-连续登录手机银行天数
  --***************************************
  V_NO_ID := '15';
  V_BGN_DATE := SYSDATE;

  -- 第15段业务逻辑：处理-连续登录手机银行天数
  INSERT INTO ADS_CUST_LABEL_QD12 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD12
  )
  SELECT
         V_SYSDAT            AS DATA_DATE            , -- 数据日期
         '9999'              AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_CORE_NO     AS AA01                 , -- 客户编号
         T2.CONT_LOGIN_DAYS  AS QD12                  -- 连续登录天数
    FROM MBK_CUST_INFO T1 -- 客户信息表
    LEFT JOIN TMP_ADS_CUST_LABEL_QD12 T2 -- 连续登录手机银行状态表
      ON T1.CUST_NO = T2.CUST_NO
   WHERE T1.CUST_STATUS != '0' AND T1.CUST_CORE_NO IS NOT NULL;

  -- 提交第15段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第15段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第15段业务逻辑处理完成：处理-连续登录手机银行天数';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第15段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.16 -- 第16段处理开始：处理-是否为手机银行月活跃客户
  --***************************************
  V_NO_ID := '16';
  V_BGN_DATE := SYSDATE;

  -- 第16段业务逻辑：处理-是否为手机银行月活跃客户
  INSERT INTO ADS_CUST_LABEL_QD13 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD13
  )
  WITH SJ_YUEH AS (
    SELECT T2.CUST_CORE_NO,
    T1.TX_DATE,
    T3.TRAN_DATE,
    CASE
    WHEN REPLACE(T3.TRAN_DATE, '-', '') = T1.TX_DATE AND COUNT(1) > 4 THEN 4
    ELSE COUNT(1)
    END JYBS --交易笔数   交易日期等于签约日期 大于4笔 按4笔计算
    FROM DWD_TX_ASET T1     --资产交易信息表
    LEFT JOIN MBK_CUST_INFO T2 --客户信息表
    ON T1.CUST_ID = T2.CUST_CORE_NO
    LEFT JOIN MBK_CUST_LOG_SIGN T3 --签约日志表
    ON T2.CUST_NO = T3.CUST_NO
      AND LOG_STATUS = '1'
      AND ACT_TYPE <> 0
      AND T1.TX_DATE = REPLACE(T3.TRAN_DATE, '-', '')
    WHERE NVL(T2.CUST_CORE_NO, 'ISNULL') <> 'ISNULL'
      AND T1.TX_CHNL = '3031'
      AND T1.TX_DATE >= V_CUR_MONTH_START
      AND T1.CHONGZBZ = '0' --要未冲正的数据
    GROUP BY T2.CUST_CORE_NO, T1.TX_DATE, T3.TRAN_DATE
  )
  SELECT
         V_SYSDAT                         AS DATA_DATE            , -- 数据日期
         '9999'                           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_CORE_NO                  AS AA01                 , -- 客户编号
         CASE WHEN SUM(JYBS) >= 6 THEN 1
          ELSE 0
          END AS QD13 -- 是否为手机银行月活跃客户
    FROM SJ_YUEH T1 -- 手机银行月活数据
   GROUP BY CUST_CORE_NO;

  -- 提交第16段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第16段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第16段业务逻辑处理完成：处理-是否为手机银行月活跃客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第16段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.17 -- 第17段处理开始：处理-各卡微信新绑卡日期
  --***************************************
  V_NO_ID := '17';
  V_BGN_DATE := SYSDATE;

  -- 第17段业务逻辑：处理-各卡微信新绑卡日期
  INSERT INTO TMP_ADS_CUST_LABEL_QD14 (
      DATA_DATE,
      CARD_NO,
      BIND_DATE
  )
  SELECT
         V_SYSDAT           AS DATA_DATE  , -- 数据日期
         T1.SGN_ACCT_ID_DE  AS CARD_NO    , -- 卡号
         MIN(TXN_DATE)      AS BIND_DATE   -- 最小绑卡日期
    FROM ECPP_E_TXN_SIGN T1 -- 待确认：来源表中文名缺失
   WHERE T1.STATUS = '00' AND T1.INSTG_ID IN ('134','136')
     GROUP BY T1.SGN_ACCT_ID_DE;

  -- 提交第17段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第17段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第17段业务逻辑处理完成：处理-各卡微信新绑卡日期';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第17段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.18 -- 第18段处理开始：处理-处理微信交易记录、MAPPING映射_(G_02)、MAPPING映射_(G_03)、MAPPING映射_(G_04)
  --***************************************
  V_NO_ID := '18';
  V_BGN_DATE := SYSDATE;

  -- 第18段业务逻辑：处理-处理微信交易记录、MAPPING映射_(G_02)、MAPPING映射_(G_03)、MAPPING映射_(G_04)
  INSERT INTO TMP1_ADS_CUST_LABEL_QD14 (
      DATA_DATE,
      CARD_NO,
      TXN_DATE
  )
  -- 处理-处理微信交易记录
  SELECT
         V_SYSDAT         AS DATA_DATE  , -- 数据日期
         T1.PYER_ACCT_NO  AS CARD_NO    , -- 卡号
         REPLACE(T1.SYS_DATE,'-','')      AS TXN_DATE    -- 交易日期
    FROM ECPP_E_TXN_COLLECTION T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND T1.PYEE_ACCT_ISSR_ID IN ('134','136')
     AND REPLACE(T1.SYS_DATE,'-','') >= V_CUR_MONTH_START
  UNION
  -- MAPPING映射_(G_02)
  SELECT
         V_SYSDAT         AS DATA_DATE  , -- 数据日期
         T1.PYER_ACCT_NO  AS CARD_NO    , -- 卡号
         REPLACE(T1.SYS_DATE,'-','')      AS TXN_DATE    -- 交易日期
    FROM ECPP_E_HIS_COLLECTION T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND PYEE_ACCT_ISSR_ID IN ('134','136')
     AND REPLACE(T1.SYS_DATE,'-','') >= V_CUR_MONTH_START
  UNION
  -- MAPPING映射_(G_03)
  SELECT
         V_SYSDAT            AS DATA_DATE  , -- 数据日期
         T1.PYER_ACCT_NO_DE  AS CARD_NO    , -- 卡号
         REPLACE(T1.SYS_DATE,'-','')         AS TXN_DATE    -- 交易日期
    FROM ECPP_E_TXN_PAYMENT T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND T1.PYEE_ACCT_ISSR_ID IN ('134','136')
     AND REPLACE(T1.SYS_DATE,'-','') >= V_CUR_MONTH_START
  UNION
  -- MAPPING映射_(G_04)
  SELECT
         V_SYSDAT            AS DATA_DATE  , -- 数据日期；待确认：DATA_DATE 缺少来源字段或映射规则
         T1.PYER_ACCT_NO_DE  AS CARD_NO    , -- 卡号
         REPLACE(T1.SYS_DATE,'-','')         AS TXN_DATE    -- 交易日期
    FROM ECPP_E_HIS_PAYMENT T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRX_STATUS IN ('00', '03') AND T1.PYEE_ACCT_ISSR_ID IN ('134','136')
     AND REPLACE(T1.SYS_DATE,'-','') >= V_CUR_MONTH_START;

  -- 提交第18段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第18段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第18段业务逻辑处理完成：处理-处理微信交易记录、MAPPING映射_(G_02)、MAPPING映射_(G_03)、MAPPING映射_(G_04)';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第18段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.19 -- 第19段处理开始：处理-微信绑卡单日最高4笔
  --***************************************
  V_NO_ID := '19';
  V_BGN_DATE := SYSDATE;

  -- 第19段业务逻辑：处理-微信绑卡单日最高4笔
  INSERT INTO TMP2_ADS_CUST_LABEL_QD14 (
      DATA_DATE,
      CARD_NO,
      TXN_DATE,
      TXN_CNT
  )
  SELECT
         V_SYSDAT                                        AS DATA_DATE  , -- 数据日期
         T2.CARD_NO                                      AS CARD_NO    , -- 卡号
         T2.TXN_DATE                                     AS TXN_DATE   , -- 交易日期
         CASE WHEN T1.BIND_DATE = T2.TXN_DATE   -- bind_date 为 yyyyMMdd,对齐后比较
                          AND COUNT(*) > 4
                         THEN 4                                            -- 新绑卡当日封顶 4 笔
                         ELSE COUNT(*) END AS TXN_CNT -- 交易笔数
    FROM TMP_ADS_CUST_LABEL_QD14 T1 -- 客户基础标签_临时表微信新绑卡日期
    LEFT JOIN TMP1_ADS_CUST_LABEL_QD14 T2 -- 客户基础标签_临时表微信交易记录
      ON T1.CARD_NO = T2.CARD_NO
   GROUP BY T2.CARD_NO, T2.TXN_DATE, T1.BIND_DATE;

  -- 提交第19段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第19段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第19段业务逻辑处理完成：处理-微信绑卡单日最高4笔';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第19段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.20 -- 第20段处理开始：处理-是否为微信绑卡交易月活跃客户
  --***************************************
  V_NO_ID := '20';
  V_BGN_DATE := SYSDATE;

  -- 第20段业务逻辑：处理-是否为微信绑卡交易月活跃客户
  INSERT INTO ADS_CUST_LABEL_QD14 (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      AA01,
      QD14
  )
  SELECT
         V_SYSDAT                AS DATA_DATE            , -- 数据日期
         T2.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.CUST_ID              AS AA01                 , -- 客户编号
         '1'                     AS QD14                  -- 是否为微信绑卡交易月活跃客户
    FROM TMP2_ADS_CUST_LABEL_QD14 T1 -- 客户基础标签_临时表微信绑卡单日最高4笔
    LEFT JOIN TMP_ADS_CUST_LABEL_QDFX T2 -- 客户基础标签_临时表银行卡发卡机构
      ON T1.CARD_NO = T2.CARD_NO
   GROUP BY T2.PERSN_LEGAL_BK_CODE, T2.CUST_ID
     HAVING SUM(TXN_CNT) >= 6;

  -- 提交第20段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第20段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第20段业务逻辑处理完成：处理-是否为微信绑卡交易月活跃客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第20段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_lost_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_lost_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：客户流失清单处理
  -- 处理周期: 日
  -- 过程描述: 按轻度、重度流失规则,计算接触、挽回和挽回金融资产
  -- 来源表: DWS_CUST_ASSE_LIAB(当月)、DWS_CUST_ASSE_LIAB_HIS(历史月末), DWD_CUST_INDV_INFO, DWS_CUST_LVL_INFO, ADS_MKT_REC_INFO
  -- 目标表: ADS_CUST_LOST_DTL
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.5.0
  -- 关联需求: REQ-CUST-001
  -- 变更记录:
  --   v2.1.0: 1.已挽回金融资产口径确认：T-1日金融资产余额达标的客户,从月初~T-1日金融资产新增总金额
  --           2.明细表新增RESCUED_FINA_ASSET字段
  --   v2.3.0 2026-07-28 月/季/年切片接触状态按不同时间窗口独立计算
  --   v2.4.1 2026-07-30 去掉季/年统计周期切片仅保留月度；T-1日统一为V_SYSDAT(与潜力提升一致)；
  --            删除第5段历史客群持续经营；全字段补充注释
  --   v2.5.0 2026-08-04 F-01:接触EXISTS补PERSN_LEGAL_BK_CODE+MKT_PERSN关联；
  --                       F-02:POST_ID改用m.MNGR_POST_ID(DWD_CUST_MAN,与潜力提升一致)；
  --                       F-03:新增V_RUN_DATE_DT变量分离业务/日志用途；
  --                       F-05:阈值CASE封装为TMP_ADS_LOST_THRESH查找表(消除6处重复)；
  --                       F-06:子查询过滤NULL LVL_CHURN(消除先INSERT后DELETE)
   --   v2.6.0 2026-08-06【待确认】 历史日期查询(上月末/上上月末AUM)改用DWS_CUST_ASSE_LIAB_HIS(与当期表同构)
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '客户流失清单处理';                     -- 过程描述
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_LOST_DTL';              -- 过程名称
  V_LOG_MSG              VARCHAR(4000);                                         -- 日志消息文本
  V_LOG_FLG              INTEGER;                                               -- 日志标志(0=成功)
  V_LOG_BUTTON           INTEGER := 1;                                          -- 日志记录开关(1=启用)
  V_NO_ID                VARCHAR(10);                                           -- 当前步骤序号
  V_BGN_DATE             DATE;                                                  -- 步骤开始时间
  V_END_DATE             DATE;                                                  -- 步骤结束时间
  V_DURA_DATE            INTEGER;                                               -- 步骤耗时(秒)
  V_DATA_DATE            VARCHAR2(8);                                           -- 跑批日期(=V_SYSDAT)
  V_PREV_MONTH_END       VARCHAR2(8);                                           -- 上月末日期(YYYYMMDD),用于判定轻度流失和上月末余额
  V_PREV_PREV_MONTH_END  VARCHAR2(8);                                           -- 上上月末日期(YYYYMMDD),用于判定重度流失
  V_CURR_MONTH_BEGIN_DT  DATE;                                                  -- 当月初日期,用于限定月接触窗口起点
  V_RUN_DATE_DT          DATE;                                                  -- 跑批日期DATE类型,专用于业务逻辑(接触窗口上界)
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);                                           -- 三年历史清理边界(参数19)

  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS                                 -- 清空物理临时表
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 1. 参数检查：校验跑批日期并初始化相对业务日期参数
  ------------------------------------------------------------------
  V_NO_ID := 'TMP1' || '_CHK';
  IF V_SYSDAT IS NULL
     OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')
  THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_DATA_DATE := V_SYSDAT;                                                  -- 跑批日期=T-1日
  V_PREV_MONTH_END := sys_fun_deal_date(V_SYSDAT, 2);                       -- 上月末(参数2)
  V_PREV_PREV_MONTH_END := sys_fun_deal_date(V_SYSDAT, 6);                  -- 上上月末(参数6)
  V_END_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');                              -- 转换为DATE类型
  V_RUN_DATE_DT := V_END_DATE;                              -- 跑批日期DATE类型(业务逻辑用,V_END_DATE后续仅用于日志)
  V_CURR_MONTH_BEGIN_DT := TO_DATE(sys_fun_deal_date(V_SYSDAT, 9), 'YYYYMMDD');  -- 当月初(参数9)
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);                      -- 三年历史清理边界(参数19)

  ------------------------------------------------------------------
  -- 2. TMP1：清理当前数据日明细、三年历史数据和物理临时表,保证可重跑
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  DELETE FROM ADS_CUST_LOST_DTL D                                           -- 清理当天数据(支持重跑)
   WHERE D.DATA_DATE = V_DATA_DATE;

  DELETE FROM ADS_CUST_LOST_DTL D                                           -- 清理三年历史清理边界(参数19)之前的数据
   WHERE D.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  TRUNC_TMP('TMP_ADS_LOST_BASE');                                           -- 清空物理临时表
  TRUNC_TMP('TMP_ADS_LOST_THRESH');                             -- 清空阈值查找表
  TRUNC_TMP('TMP_ADS_LOST_BASE_MONTH');
  TRUNC_TMP('TMP_ADS_LOST_BASE_MONTH_T');
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '1 完成：清理当前数据日明细、三年前历史数据和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 3. TMP2：生成轻度和重度流失客户基础数据
  --
  -- 流失判定逻辑：
  --   轻度流失(1)：上月月日均AUM达标 + 上月末时点AUM不达标
  --   重度流失(2)：上上月月日均AUM达标 + 上月月日均AUM不达标 + 上月末时点AUM不达标
  --
  -- 表别名说明：
  --   p  = 上月月日均(DATA_DATE=V_PREV_MONTH_END, BAL_TYPE='2')
  --   pp = 上上月月日均(DATA_DATE=V_PREV_PREV_MONTH_END, BAL_TYPE='2')
  --   c  = 客户基本信息(DWD_CUST_INDV_INFO)
  --   cur_l = 当前客户等级(DATA_DT=V_DATA_DATE)
  --   e  = 上月末时点AUM(DATA_DATE=V_PREV_MONTH_END, BAL_TYPE='1')—用于判定上月末余额是否达标
  --   b  = T-1日时点资产(DATA_DATE=V_DATA_DATE, BAL_TYPE='1')—用于取T-1日各资产余额
  ------------------------------------------------------------------
  -- F-05: 客户等级达标阈值查找表(消除6处CASE WHEN重复)
  INSERT INTO TMP_ADS_LOST_THRESH (LVL_CODE, THRESHOLD)
  SELECT '04', 50000 FROM DUAL UNION ALL                       -- 优质/财富1/财富2：5万
  SELECT '05', 50000 FROM DUAL UNION ALL
  SELECT '06', 50000 FROM DUAL UNION ALL
  SELECT '07', 300000 FROM DUAL UNION ALL                      -- 贵宾：30万
  SELECT '08', 500000 FROM DUAL UNION ALL                      -- 私行1：50万
  SELECT '09', 1000000 FROM DUAL UNION ALL                     -- 私行2：100万
  SELECT '10', 3000000 FROM DUAL;                              -- 私行3：300万
  COMMIT;

  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

 -- p：上月月日均AUM + 上月客户等级
 INSERT INTO TMP_ADS_LOST_BASE_MONTH
                 SELECT a.CUST_ID, a.ORG_ID, a.PERSN_LEGAL_BK_CODE, a.AUM_BAL, l.CUST_LVL LVL
                   FROM DWS_CUST_ASSE_LIAB_HIS a
                   JOIN DWS_CUST_LVL_INFO_HIS l
                     ON l.CUST_ID = a.CUST_ID
                    AND l.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
                    AND l.DATA_DATE = a.DATA_DATE
                  WHERE a.DATA_DATE = V_PREV_MONTH_END
                    AND a.BAL_TYPE = '2';
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '2 完成：生成轻度流失客户基础数据';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- pp：上上月月日均AUM + 上上月客户等级
   INSERT INTO TMP_ADS_LOST_BASE_MONTH_T
                 SELECT a.CUST_ID, a.ORG_ID, a.PERSN_LEGAL_BK_CODE, a.AUM_BAL, l.CUST_LVL LVL
                   FROM DWS_CUST_ASSE_LIAB_HIS a
                   JOIN DWS_CUST_LVL_INFO_HIS l
                     ON l.CUST_ID = a.CUST_ID
                    AND l.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE
                    AND l.DATA_DATE = a.DATA_DATE
                  WHERE a.DATA_DATE = V_PREV_PREV_MONTH_END
                    AND a.BAL_TYPE = '2';
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '3 完成：生成重度流失客户基础数据';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );


  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- F-05/F-06: 阈值通过TMP_ADS_LOST_THRESH查找；子查询过滤NULL LVL_CHURN
  INSERT INTO TMP_ADS_LOST_BASE (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      CUST_ID,                                                  -- 客户号
      CUST_NAME,                                                -- 客户姓名
      CUST_LVL,                                                 -- 当前客户等级
      LVL_CHURN,                                                -- 流失等级(1=轻度流失,2=重度流失)
      DEPO_CURNT_DEPO_BAL,                                      -- T-1日活期存款余额
      FIXD_DEPO_BAL,                                            -- T-1日定期存款余额
      FIN_AMT,                                                  -- T-1日理财余额
      CNTCT_STATE_M,                                            -- 月接触状态
      RESCUE_STATE,                                             -- 挽回状态
      CUR_AUM_BAL,                                              -- T-1日时点AUM
      LAST_MONTH_END_AUM_BAL,                                   -- 上月末时点AUM
      POST_ID,                                                  -- 管户经理岗位ID
      ORG_ID                                                    -- 归属机构ID
  )
  SELECT src.PERSN_LEGAL_BK_CODE,
         src.CUST_ID,
         src.CUST_NAME,
         src.CUST_LVL,
         src.LVL_CHURN,
         src.DEPO_CURNT_DEPO_BAL,
         src.FIXD_DEPO_BAL,
         src.FIN_AMT,
         src.CNTCT_STATE_M,
         src.RESCUE_STATE,
         src.CUR_AUM_BAL,
         src.LAST_MONTH_END_AUM_BAL,
         src.POST_ID,
         src.ORG_ID
    FROM (
         SELECT COALESCE(p.PERSN_LEGAL_BK_CODE, pp.PERSN_LEGAL_BK_CODE) AS PERSN_LEGAL_BK_CODE,
                c.CUST_ID,
                c.CUST_NAME,
                cur_l.CUST_LVL,
                CASE                                                     -- 流失等级判定(F-05: 阈值来自TMP_ADS_LOST_THRESH)
                  -- 重度流失(2)：上上月月日均达标 AND 上月月日均不达标 AND 上月末时点不达标
                  WHEN pp.AUM_BAL >= NVL(ppt.THRESHOLD, 0)
                   AND NVL(p.AUM_BAL, 0) < NVL(ppt.THRESHOLD, 0)
                   AND NVL(e.AUM_BAL, 0) < NVL(ppt.THRESHOLD, 0)
                  THEN '2'
                  -- 轻度流失(1)：上月月日均达标 AND 上月末时点不达标
                  WHEN p.AUM_BAL >= NVL(pt.THRESHOLD, 0)
                   AND NVL(e.AUM_BAL, 0) < NVL(pt.THRESHOLD, 0)
                  THEN '1'
                END AS LVL_CHURN,
                NVL(b.DEPO_CURNT_DEPO_BAL, 0) AS DEPO_CURNT_DEPO_BAL,
                NVL(b.FIXD_DEPO_BAL, 0) AS FIXD_DEPO_BAL,
                NVL(b.FIN_BAL, 0) AS FIN_AMT,
                CASE                                                     -- 月接触(F-01: 补PERSN_LEGAL_BK_CODE+MKT_PERSN)
                  WHEN EXISTS (
                    SELECT 1
                      FROM ADS_MKT_REC_INFO r
                     WHERE r.CUST_ID = c.CUST_ID
                       AND r.PERSN_LEGAL_BK_CODE = c.PERSN_LEGAL_BK_CODE  -- 双键关联
                       AND r.MKT_PERSN = m.MNGR_POST_ID                    -- 仅统计本管户经理的接触
                       AND r.MKT_TYP IN ('1', '2', '3', '4')
                       AND r.MKT_TIME IS NOT NULL
                       AND TO_DATE(REPLACE(SUBSTR(r.MKT_TIME, 1, 10), '-', ''), 'YYYYMMDD')
                           BETWEEN V_CURR_MONTH_BEGIN_DT AND V_RUN_DATE_DT  -- F-03: 使用V_RUN_DATE_DT
                  ) THEN '1'
                  ELSE '0'
                END AS CNTCT_STATE_M,
                CASE                                                     -- 挽回状态(F-05: 阈值来自TMP_ADS_LOST_THRESH)
                  WHEN NVL(b.AUM_BAL, 0) >= NVL(COALESCE(pt.THRESHOLD, ppt.THRESHOLD), 0)
                  THEN '1'
                  ELSE '0'
                END AS RESCUE_STATE,
                NVL(b.AUM_BAL, 0) AS CUR_AUM_BAL,
                NVL(e.AUM_BAL, 0) AS LAST_MONTH_END_AUM_BAL,
                m.MNGR_POST_ID AS POST_ID,                               -- F-02: 改用DWD_CUST_MAN的理财管户经理
                COALESCE(p.ORG_ID, pp.ORG_ID) AS ORG_ID
           FROM TMP_ADS_LOST_BASE_MONTH p -- p：上月月日均AUM + 上月客户等级  
           LEFT JOIN TMP_ADS_LOST_THRESH pt ON pt.LVL_CODE = p.LVL      -- F-05: p对应达标阈值
           FULL JOIN TMP_ADS_LOST_BASE_MONTH_T  pp -- pp：上上月月日均AUM + 上上月客户等级
             ON pp.CUST_ID = p.CUST_ID
            AND pp.PERSN_LEGAL_BK_CODE = p.PERSN_LEGAL_BK_CODE
           LEFT JOIN TMP_ADS_LOST_THRESH ppt ON ppt.LVL_CODE = pp.LVL   -- F-05: pp对应达标阈值
           JOIN DWD_CUST_INDV_INFO c                                    -- c：客户基本信息
             ON c.CUST_ID = COALESCE(p.CUST_ID, pp.CUST_ID)
            AND c.PERSN_LEGAL_BK_CODE = COALESCE(p.PERSN_LEGAL_BK_CODE, pp.PERSN_LEGAL_BK_CODE)
           LEFT JOIN DWD_CUST_MAN m                                     -- m：理财管户(F-02: POST_ID来源)
             ON m.CUST_ID = c.CUST_ID
            AND m.PERSN_LEGAL_BK_CODE = COALESCE(p.PERSN_LEGAL_BK_CODE, pp.PERSN_LEGAL_BK_CODE)
            AND m.MNG_TYP = '1'
           LEFT JOIN DWS_CUST_LVL_INFO cur_l                            -- cur_l：当前客户等级
             ON cur_l.CUST_ID = c.CUST_ID
            AND cur_l.PERSN_LEGAL_BK_CODE = c.PERSN_LEGAL_BK_CODE
            AND cur_l.DATA_DATE = V_DATA_DATE
           LEFT JOIN DWS_CUST_ASSE_LIAB_HIS e                           -- e：上月末时点AUM(HIS)
             ON e.CUST_ID = c.CUST_ID
            AND e.PERSN_LEGAL_BK_CODE = COALESCE(p.PERSN_LEGAL_BK_CODE, pp.PERSN_LEGAL_BK_CODE)
            AND e.DATA_DATE = V_PREV_MONTH_END
            AND e.BAL_TYPE = '1'
           LEFT JOIN DWS_CUST_ASSE_LIAB b                               -- b：T-1日时点资产
             ON b.CUST_ID = c.CUST_ID
            AND b.PERSN_LEGAL_BK_CODE = COALESCE(p.PERSN_LEGAL_BK_CODE, pp.PERSN_LEGAL_BK_CODE)
            AND b.DATA_DATE = V_DATA_DATE
            AND b.BAL_TYPE = '1'
         ) src
   WHERE src.LVL_CHURN IS NOT NULL;                                     -- F-06: 子查询过滤NULL(消除DELETE)

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '4 完成：生成轻度和重度流失客户基础数据';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 4. 目标表写入：生成月度统计周期明细
  --
  -- 接触窗口：当月初至跑批日
  -- RESCUED_FINA_ASSET = MAX(T-1日时点AUM - 上月末时点AUM, 0)
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CUST_LOST_DTL (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      DATA_DATE,                                                -- 数据日期(YYYYMMDD,=V_DATA_DATE)
      CUST_ID,                                                  -- 客户号
      CUST_NAME,                                                -- 客户姓名
      CUST_LVL,                                                 -- 当前客户等级
      LVL_CHURN,                                                -- 流失等级(1=轻度,2=重度)
      DEPO_CURNT_DEPO_BAL,                                      -- T-1日活期存款余额
      FIXD_DEPO_BAL,                                            -- T-1日定期存款余额
      FIN_AMT,                                                  -- T-1日理财余额
      CNTCT_STATE,                                              -- 月接触状态(1=有接触,0=无)
      RESCUE_STATE,                                             -- 挽回状态(1=已挽回,0=未挽回)
      RESCUED_FINA_ASSET,                                       -- 已挽回金融资产(T-1日AUM-上月末AUM,最小为0)
      POST_ID,                                                  -- 管户经理岗位ID
      ORG_ID,                                                   -- 归属机构ID
      STATIS_CYCLE                                              -- 统计周期(M=月度)
  )
  SELECT x.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         V_DATA_DATE,                                           -- 数据日期=跑批日期
         x.CUST_ID,                                             -- 客户号
         x.CUST_NAME,                                           -- 客户姓名
         x.CUST_LVL,                                            -- 当前客户等级
         x.LVL_CHURN,                                            -- 流失等级
         x.DEPO_CURNT_DEPO_BAL,                                  -- T-1日活期存款余额
         x.FIXD_DEPO_BAL,                                       -- T-1日定期存款余额
         x.FIN_AMT,                                             -- T-1日理财余额
         x.CNTCT_STATE_M,                                       -- 月接触状态(来自临时表)
         x.RESCUE_STATE,                                         -- 挽回状态
         CASE WHEN x.RESCUE_STATE = '1'                          -- 已挽回金融资产：已挽回客户才计算
              THEN GREATEST(NVL(x.CUR_AUM_BAL, 0) - NVL(x.LAST_MONTH_END_AUM_BAL, 0), 0)  -- MAX(T-1余额-上月末余额, 0)
              ELSE 0                                            -- 未挽回=0
         END,
         x.POST_ID,                                             -- 管户经理岗位ID
         x.ORG_ID,                                              -- 归属机构ID
         'M'                                                    -- 统计周期：月度
    FROM TMP_ADS_LOST_BASE x;

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：写入客户流失清单';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

EXCEPTION
  -- 发生异常时回滚本过程事务并记录失败日志。
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_lost_statis(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_lost_statis(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：客户挽回统计处理
  -- 处理周期: 日
  -- 过程描述: 按机构向上汇总和客户经理维度生成客户挽回统计(月度统计周期)
  -- 来源表: ADS_CUST_LOST_DTL, DWS_CUST_ASSE_LIAB, DWD_SYS_ORG
  -- 目标表: ADS_CUST_LOST_STATIS
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.4.2
  -- 关联需求: REQ-CUST-001
  -- 变更记录:
  --   v2.1.0: 1.已挽回金融资产口径确认
  --           2.统计表使用明细表RESCUED_FINA_ASSET字段汇总已挽回金融资产
  --   v2.3.0 2026-07-28 年码值N→Y统一；配合DTL月/季/年切片接触状态按不同时间窗口独立计算
  --   v2.4.1 2026-07-30 去掉季/年统计周期切片仅保留月度；简化TMP1/TMP2清理逻辑；
  --            统计周期统一为月度；全字段补充注释
  --   v2.4.2 2026-08-04 F-07:删除V_END_DATE无效初始化赋值
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '客户挽回统计处理';                     -- 过程描述
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_LOST_STATIS';          -- 过程名称
  V_LOG_MSG              VARCHAR(4000);                                        -- 日志消息文本
  V_LOG_FLG              INTEGER;                                              -- 日志标志(0=成功)
  V_LOG_BUTTON           INTEGER := 1;                                         -- 日志记录开关(1=启用)
  V_NO_ID                VARCHAR(10);                                          -- 当前步骤序号
  V_BGN_DATE             DATE;                                                 -- 步骤开始时间
  V_END_DATE             DATE;                                                 -- 步骤结束时间
  V_DURA_DATE            INTEGER;                                              -- 步骤耗时(秒)
  V_DATA_DATE            VARCHAR2(8);                                          -- 跑批日期(=V_SYSDAT)
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);                                          -- 三年历史清理边界(参数19)

  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS                                 -- 清空物理临时表
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 1. 参数检查：校验跑批日期格式
  ------------------------------------------------------------------
  IF V_SYSDAT IS NULL
     OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')
  THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;
  V_DATA_DATE := V_SYSDAT;                                                  -- 跑批日期
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);                 -- 三年历史清理边界(参数19)

  ------------------------------------------------------------------
  -- 2. TMP1：清理当前数据日统计结果、三年历史数据和物理临时表,保证可重跑
  ------------------------------------------------------------------
  V_NO_ID := 'TMP1';
  V_BGN_DATE := SYSDATE;

  DELETE FROM ADS_CUST_LOST_STATIS T                                       -- 清理当天数据(支持重跑)
   WHERE T.DATA_DATE = V_DATA_DATE;

  DELETE FROM ADS_CUST_LOST_STATIS T                                       -- 清理超过三年的历史数据
   WHERE T.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  TRUNC_TMP('TMP_ADS_LOST_STAT_SRC');                                       -- 清空物理临时表
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理当前数据日统计结果、三年前历史数据和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 3. TMP2：展开机构和客户经理统计对象
  --
  -- 将明细按机构层级向上展开为祖先机构统计口径,同时保存管户经理维度。
  -- 表别名说明：
  --   D = 流失挽回明细(ADS_CUST_LOST_DTL)
  --   X = 机构树(DWD_SYS_ORG)
  --   O = 机构层级展开结果(叶子机构→祖先机构)
  ------------------------------------------------------------------
  V_NO_ID := 'TMP2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_ADS_LOST_STAT_SRC (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      DATA_DATE,                                                -- 数据日期(YYYYMMDD)
      STATIS_CYCLE,                                             -- 统计周期(M=月度)
      STATIS_OBJ,                                               -- 统计对象(机构ID或管户经理岗位ID)
      LVL_CHURN,                                                -- 流失等级(1=轻度,2=重度)
      CNTCT_STATE,                                              -- 接触状态(1=有接触,0=无)
      RESCUE_STATE,                                             -- 挽回状态(1=已挽回,0=未挽回)
      RESCUED_FINA_ASSET                                        -- 已挽回金融资产金额
  )
  -- 机构分支：将客户所属叶子机构向上展开至各级祖先机构,形成机构统计口径。
  SELECT D.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         D.DATA_DATE,                                           -- 数据日期
         D.STATIS_CYCLE,                                        -- 统计周期
         O.ANCESTOR_ORG_ID,                                     -- 祖先机构ID(作为统计对象)
         D.LVL_CHURN,                                           -- 流失等级
         D.CNTCT_STATE,                                          -- 接触状态(直接取自明细表)
         D.RESCUE_STATE,                                         -- 挽回状态(直接取自明细表)
         D.RESCUED_FINA_ASSET                                    -- 已挽回金融资产
    FROM ADS_CUST_LOST_DTL D                                    -- D：流失挽回客户明细
    JOIN (
          SELECT DISTINCT
                 CONNECT_BY_ROOT X.ORG_ID AS LEAF_ORG_ID,       -- 叶子机构ID(起点)
                 X.ORG_ID AS ANCESTOR_ORG_ID                    -- 祖先机构ID(向上展开的所有祖先)
            FROM DWD_SYS_ORG X                                  -- X：机构树表
           START WITH X.ORG_ID IN (
                 SELECT DISTINCT ORG_ID
                   FROM ADS_CUST_LOST_DTL
                  WHERE ORG_ID IS NOT NULL                      -- 以明细中出现的机构为起点
                )
         CONNECT BY NOCYCLE PRIOR X.SUP_ORG_ID = X.ORG_ID       -- 沿上级机构向上递归
    ) O                                                        -- O：机构层级展开结果
      ON O.LEAF_ORG_ID = D.ORG_ID                               -- 明细的叶子机构匹配展开起点的叶子机构
   WHERE D.DATA_DATE = V_DATA_DATE                              -- 仅统计当天跑批产生的明细

  UNION ALL

  -- 客户经理分支：按管户经理岗位ID直接分组统计。
  SELECT D.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         D.DATA_DATE,                                           -- 数据日期
         D.STATIS_CYCLE,                                        -- 统计周期
         D.POST_ID,                                             -- 管户经理岗位ID(作为统计对象)
         D.LVL_CHURN,                                           -- 流失等级
         D.CNTCT_STATE,                                          -- 接触状态
         D.RESCUE_STATE,                                         -- 挽回状态
         D.RESCUED_FINA_ASSET                                    -- 已挽回金融资产
    FROM ADS_CUST_LOST_DTL D
   WHERE D.POST_ID IS NOT NULL                                  -- 仅统计有管户经理的客户
     AND D.DATA_DATE = V_DATA_DATE;                             -- 仅统计当天跑批产生的明细

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP2 完成：展开机构和客户经理统计对象';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 4. 目标表写入：按统计对象和流失等级汇总客户数、接触数、挽回数及比例
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CUST_LOST_STATIS (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      DATA_DATE,                                                -- 数据日期(YYYYMMDD)
      STATIS_OBJ,                                               -- 统计对象(机构ID或管户经理岗位ID)
      STATIS_CYCLE,                                             -- 统计周期(M=月度)
      LVL_CHURN,                                                -- 流失等级(1=轻度,2=重度)
      CUST_CNT,                                                 -- 总客户数
      CNTCT_CUST_CNT,                                           -- 已接触客户数
      CNTCT_RATE,                                               -- 接触率(%,保留2位小数)
      RESCUED_CUST_CNT,                                         -- 已挽回客户数
      RESCUE_RATE,                                              -- 挽回率(%,保留2位小数)
      RESCUED_FINA_ASSET                                        -- 已挽回金融资产总额
  )
  SELECT S.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         S.DATA_DATE,                                           -- 数据日期
         S.STATIS_OBJ,                                           -- 统计对象
         S.STATIS_CYCLE,                                        -- 统计周期
         S.LVL_CHURN,                                           -- 流失等级
         COUNT(*),                                              -- 总客户数：每个展开记录算1个统计单位
         SUM(CASE WHEN S.CNTCT_STATE = '1' THEN 1 ELSE 0 END),  -- 已接触客户数
         CASE WHEN COUNT(*) = 0 THEN 0                          -- 接触率=接触数/总数×100
              ELSE ROUND(SUM(CASE WHEN S.CNTCT_STATE = '1' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2)
         END,
         SUM(CASE WHEN S.RESCUE_STATE = '1' THEN 1 ELSE 0 END), -- 已挽回客户数
         CASE WHEN COUNT(*) = 0 THEN 0                          -- 挽回率=挽回数/总数×100
              ELSE ROUND(SUM(CASE WHEN S.RESCUE_STATE = '1' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2)
         END,
         SUM(S.RESCUED_FINA_ASSET)                              -- 已挽回金融资产总额：SUM各客户RESCUED_FINA_ASSET
    FROM TMP_ADS_LOST_STAT_SRC S                                 -- S：统计源数据(已按机构/客户经理展开)
   GROUP BY S.PERSN_LEGAL_BK_CODE,                               -- 按法人行号
            S.DATA_DATE,                                         -- 按数据日期
            S.STATIS_OBJ,                                         -- 按统计对象
            S.STATIS_CYCLE,                                      -- 按统计周期
            S.LVL_CHURN;                                          -- 按流失等级

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：按统计对象和流失等级汇总写入统计';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

EXCEPTION
  -- 发生异常时回滚本过程事务并记录失败日志。
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_ads_cust_new_cust_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_new_cust_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: PRC_ADS_CUST_NEW_CUST_DTL
  -- 中文名称: 新客经营明细处理
  -- 处理周期: 日
  -- 过程描述: 以客户基本信息OPEN_DATE字段确定180天内新客,按新客周期
  --           (0~30天/30~100天/100~180天)分类统计,生成月度明细数据
  -- 来源表: DWD_CUST_INDV_INFO(客户基本信息_OPEN_DATE开户日期),
  --         DWS_CUST_LVL_INFO(客户等级信息),
  --         DWS_CUST_ASSE_LIAB(客户资产负债=BAL_TYPE=1余额),
  --         DWD_CUST_INDV_KYC(客户KYC信息_主表14项),
  --         DWD_CUST_INDV_CAR_KYC(客户车辆KYC_4项),
  --         DWD_CUST_INDV_HOUSE_KYC(客户房产KYC_4项),
  --         DWD_CUST_INDV_KYC_OTHR(KYC其他信息_2项),
  --         DWD_CUST_INDV_SHOP_KYC(客户商铺KYC_4项),
  --         ADS_MKT_REC_INFO(营销活动记录_接触状态判断)
  -- 目标表: ADS_CUST_NEW_CUST_DTL(新客经营明细)
  -- 临时表: TMP_ADS_NEW_CUST_BASE(物理临时表,存储新客基础数据)
  -- 基表(ADS): ADS_NEW_CUST_KYC(客户级KYC完整度,v2.6.0由临时表转正式表,
  --             含KYC_STATE完整标志(阈值≥23)与KYC_COMPL_RATE完整度率值)
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.6.0
  -- 关联需求: REQ-CUST-007(新客定义), REQ-CUST-009(计算单位),
  --           REQ-CUST-010(去季年切片+未评级), REQ-CUST-011(接触时间调整),
  --           REQ-CUST-012(关联计算补齐法人行号), REQ-CUST-013(月度数据隔离),
  --           REQ-CUST-014(理财管户经理提取)
  -- 变更记录:
  --   v2.1.0(2026-07-22): 1.新客定义改为使用DWD_CUST_INDV_INFO的OPEN_DATE字段
  --                       2.新客周期边界值改为左闭右开(0~30、30~100、100~180)
  --   v2.2.0(2026-07-27): 计算单位调整为客户号+归属机构；明细由当日资产快照拆分
  --                       机构,法人行和归属机构取资产快照
  --   v2.3.0(2026-07-30): 1.统计周期去掉季/年切片,仅保留月度(M)
  --                       2.当月新客展示'未评级'
  --   v2.3.1(2026-07-30): 已接触客户数时间范围从"当月"调整为"新客周期内"
  --        (从OPEN_DATE到DATA_DATE期间的接触均计入)
  --   v2.3.2(2026-07-30): 修复关联计算缺少PERSN_LEGAL_BK_CODE问题,所有JOIN统一
  --                       使用CUST_ID+PERSN_LEGAL_BK_CODE作为基础计算单位；
  --                       DWD_CUST_INDV_KYC因不含PERSN_LEGAL_BK_CODE除外
  --   v2.3.3(2026-07-30): 移除历史客群持续经营步骤(原步骤5),实现月度数据隔离：
  --                       本月接触/KYC状态仅记录在当月数据文件中,不再回溯写入
  --                       上一月历史明细记录
  --   v2.3.4(2026-07-30): 管户经理信息源从DWD_CUST_INDV_INFO.HOST_CUST_MNGR_POST_ID
  --                       改为DWD_CUST_MAN(MNG_TYP='1'理财管户).MNGR_POST_ID；
  --                       归属机构同步改为DWD_CUST_MAN.ORG_ID
  --   v2.3.5(2026-08-04): F-01:记录2026-08-01口径确认(ORG_ID取DWS_CUST_ASSE_LIAB资产快照,
  --                       非DWD_CUST_MAN.ORG_ID)；客户等级一律取DWS_CUST_LVL_INFO(无记录兜底'11'),
  --                       不再按开户月判断当月新客；F-06:删除V_END_DATE无效初始化
  --   v2.5.0(2026-08-25): KYC完整度口径重构：DWD_CUST_INDV_KYC拆分为5张KYC表(主表/车辆/
  --                       房产/其他/商铺),完整度改为28个字段判定(主表14+车辆4+房产4+商铺4+
  --                       其他2,跨表同名字段不去重),阈值由≥18/22调整为≥23/28；
  --                       新增步骤TMP2先按5表计算客户级完整度写入TMP_ADS_NEW_CUST_KYC,
  --                       主查询(原TMP2,现TMP3)改用临时表关联获取KYC_STATE
  --   v2.6.0(2026-08-25): TMP_ADS_NEW_CUST_KYC由临时表转正式ADS表ADS_NEW_CUST_KYC；
  --                       新增完整度率值字段KYC_COMPL_RATE(NUMBER),按28项字段非空数/28*100
  --                       四舍五入(ROUND)输出整数百分比(如85%)；保留KYC_STATE阈值判断
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  -- 局部变量声明
  ------------------------------------------------------------------
  -- V_PRC_DESC:     存储过程描述文字(用于日志记录)
  V_PRC_DESC             VARCHAR(100) := '新客经营明细处理';
  -- V_PRC_NAME:     存储过程名称(用于日志记录)
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_NEW_CUST_DTL';
  -- V_LOG_MSG:      日志消息内容(最大4000字符)
  V_LOG_MSG              VARCHAR(4000);
  -- V_LOG_FLG:      日志标记(OUTCDE值,0=正常,-1=异常)
  V_LOG_FLG              INTEGER;
  -- V_LOG_BUTTON:    是否记录日志(1=记录,0=不记录),默认1
  V_LOG_BUTTON           INTEGER := 1;
  -- V_NO_ID:         当前步骤编号标识,用于日志定位(TMP1/TMP2/3)
  V_NO_ID                VARCHAR(10);
  -- V_BGN_DATE:      步骤开始时间(用于计算耗时)
  V_BGN_DATE             DATE;
  -- V_END_DATE:      步骤结束时间
  V_END_DATE             DATE;
  -- V_DURA_DATE:     步骤耗时(秒),(V_END_DATE - V_BGN_DATE) * 86400
  V_DURA_DATE            INTEGER;
  -- V_DATA_DATE:     数据日期,取V_SYSDAT值,格式YYYYMMDD
  V_DATA_DATE            VARCHAR2(8);
  -- V_HISTORY_CUTOFF_DATE: 三年历史清理边界(参数19),用于清理过期数据
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);
  -- V_180D_WINDOW_BEGIN: 180天新客窗口开始日(参数27)
  V_180D_WINDOW_BEGIN    VARCHAR2(8);

  ------------------------------------------------------------------
  -- 内部辅助过程：清空指定物理临时表
  -- 参数 P_TABLE_NAME: 临时表名称,直接拼接为TRUNCATE语句执行
  ------------------------------------------------------------------
  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 步骤1: 参数检查
  -- 校验V_SYSDAT格式：必须为8位数字YYYYMMDD
  ------------------------------------------------------------------
  IF V_SYSDAT IS NULL
     OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')
  THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  -- 设置数据日期 = 跑批日期
  V_DATA_DATE := V_SYSDAT;
  -- 三年历史清理边界(参数19)
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);
  -- 180天新客窗口开始日(参数27)
  V_180D_WINDOW_BEGIN := sys_fun_deal_date(V_SYSDAT, 27);

  ------------------------------------------------------------------
  -- 步骤2_TMP1: 清理当前数据日明细和物理临时表
  --   - 删除当天已存在的明细数据(幂等重跑)
  --   - 删除三年前的历史过期数据(保留近三年)
  --   - 清空物理临时表 TMP_ADS_NEW_CUST_BASE / KYC基表 ADS_NEW_CUST_KYC
  ------------------------------------------------------------------
  V_NO_ID := 'TMP1';
  V_BGN_DATE := SYSDATE;

  -- 删除当天明细(支持重跑幂等)
  DELETE FROM ADS_CUST_NEW_CUST_DTL D
   WHERE D.DATA_DATE = V_DATA_DATE;

  -- 删除三年历史清理边界(参数19)之前的历史数据
  DELETE FROM ADS_CUST_NEW_CUST_DTL D
   WHERE D.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  -- 清空临时表与KYC基表
  TRUNC_TMP('TMP_ADS_NEW_CUST_BASE');
  TRUNC_TMP('ADS_NEW_CUST_KYC');
  COMMIT;

  V_END_DATE := SYSDATE;
  -- 计算本步骤耗时(秒)
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理当前数据日明细、三年前历史数据和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 步骤3_TMP2: 计算客户级KYC完整度(v2.5.0新增,v2.6.0转正式基表ADS_NEW_CUST_KYC)
  --   口径: 5张KYC表共28个字段参与判定
  --     - KYC_STATE: 阈值≥23个非空即完整('1'/'0')(v2.6.0保留)
  --     - KYC_COMPL_RATE: 完整度率值 = 非空字段数/28*100,四舍五入(ROUND)输出整数百分比(如85%)
  --   参与字段(各表均排除PK_ID/法人行号/客户编号/客户名称/创建人/创建机构/创建时间):
  --     DWD_CUST_INDV_KYC(主表,14项): ESTT_INF,SHOP_INF,VIKL_INF,
  --       BK_OUTER_DEPO,BK_OUTER_FIN,BK_OUTER_FUND,BK_OUTER_INSUR,BK_OUTER_GOLD,
  --       STK_INVEST,MTH_INCOM,YR_INCOM,BK_OUTER_LOAN_BAL,BK_OUTER_CRDT_LMT,AVAIL_LMT
  --     DWD_CUST_INDV_CAR_KYC(车辆,4项): VEHICLE_PLATE_NO,USAGE_NATURE,
  --       IS_CAR_LOAN,IS_CAR_MORTGAGED
  --     DWD_CUST_INDV_HOUSE_KYC(房产,4项): PROP_OWNER_CERT_NO,HOUSE_AREA,
  --       IS_HOUSE_MORTGAGED,RES_ADDRS
  --     DWD_CUST_INDV_SHOP_KYC(商铺,4项): PROP_OWNER_CERT_NO,HOUSE_AREA,
  --       IS_HOUSE_MORTGAGED,RES_ADDRS(与房产同名字段不去重,独立计数)
  --     DWD_CUST_INDV_KYC_OTHR(其他,2项): KYC_INF,APDIX_ID
  --   子表(1:N)处理: 按客户+法人行号聚合MAX,任一记录非空即计1项
  --   驱动范围: 5张KYC表客户集UNION(任一表有记录的客户均参与计算)
  ------------------------------------------------------------------
  V_NO_ID := 'TMP2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_NEW_CUST_KYC (
      PERSN_LEGAL_BK_CODE,       -- 法人行号
      CUST_ID,                   -- 客户编号
      KYC_STATE,                 -- KYC完成状态(1=完整≥23/28,0=不完整)
      KYC_COMPL_RATE                   -- KYC完整度率值(非空字段数/28*100,ROUND取整)
  )
  SELECT x.PERSN_LEGAL_BK_CODE,                                               -- 法人行号
         x.CUST_ID,                                                           -- 客户编号
         CASE WHEN x.cnt >= 23 THEN '1' ELSE '0' END,                        -- v2.6.0: KYC完整(≥23/28)由内层计数派生
         ROUND(x.cnt * 100 / 28)                                             -- v2.6.0: KYC完整度率值(ROUND四舍五入取整)
    FROM (
      SELECT u.PERSN_LEGAL_BK_CODE,
             u.CUST_ID,
             (CASE WHEN k.ESTT_INF IS NOT NULL THEN 1 ELSE 0 END             -- 1.住宅信息
              + CASE WHEN k.SHOP_INF IS NOT NULL THEN 1 ELSE 0 END           -- 2.商铺信息
              + CASE WHEN k.VIKL_INF IS NOT NULL THEN 1 ELSE 0 END           -- 3.车辆信息
              + CASE WHEN k.BK_OUTER_DEPO IS NOT NULL THEN 1 ELSE 0 END      -- 4.行外存款
              + CASE WHEN k.BK_OUTER_FIN IS NOT NULL THEN 1 ELSE 0 END       -- 5.行外理财
              + CASE WHEN k.BK_OUTER_FUND IS NOT NULL THEN 1 ELSE 0 END      -- 6.行外基金
              + CASE WHEN k.BK_OUTER_INSUR IS NOT NULL THEN 1 ELSE 0 END     -- 7.行外保险
              + CASE WHEN k.BK_OUTER_GOLD IS NOT NULL THEN 1 ELSE 0 END      -- 8.行外贵金属
              + CASE WHEN k.STK_INVEST IS NOT NULL THEN 1 ELSE 0 END         -- 9.股票投资
              + CASE WHEN k.MTH_INCOM IS NOT NULL THEN 1 ELSE 0 END          -- 10.月收入
              + CASE WHEN k.YR_INCOM IS NOT NULL THEN 1 ELSE 0 END           -- 11.年收入
              + CASE WHEN k.BK_OUTER_LOAN_BAL IS NOT NULL THEN 1 ELSE 0 END  -- 12.行外贷款余额
              + CASE WHEN k.BK_OUTER_CRDT_LMT IS NOT NULL THEN 1 ELSE 0 END  -- 13.行外授信额度
              + CASE WHEN k.AVAIL_LMT IS NOT NULL THEN 1 ELSE 0 END          -- 14.可用额度
              + CASE WHEN v.VEHICLE_PLATE_NO IS NOT NULL THEN 1 ELSE 0 END   -- 15.车牌号
              + CASE WHEN v.USAGE_NATURE IS NOT NULL THEN 1 ELSE 0 END       -- 16.使用性质
              + CASE WHEN v.IS_CAR_LOAN IS NOT NULL THEN 1 ELSE 0 END        -- 17.是否有车贷
              + CASE WHEN v.IS_CAR_MORTGAGED IS NOT NULL THEN 1 ELSE 0 END   -- 18.车辆是否抵押
              + CASE WHEN h.PROP_OWNER_CERT_NO IS NOT NULL THEN 1 ELSE 0 END -- 19.房产证号
              + CASE WHEN h.HOUSE_AREA IS NOT NULL THEN 1 ELSE 0 END         -- 20.房屋面积
              + CASE WHEN h.IS_HOUSE_MORTGAGED IS NOT NULL THEN 1 ELSE 0 END -- 21.房产是否抵押
              + CASE WHEN h.RES_ADDRS IS NOT NULL THEN 1 ELSE 0 END          -- 22.房产地址
              + CASE WHEN s.PROP_OWNER_CERT_NO IS NOT NULL THEN 1 ELSE 0 END -- 23.商铺房产证号
              + CASE WHEN s.HOUSE_AREA IS NOT NULL THEN 1 ELSE 0 END         -- 24.商铺面积
              + CASE WHEN s.IS_HOUSE_MORTGAGED IS NOT NULL THEN 1 ELSE 0 END -- 25.商铺是否抵押
              + CASE WHEN s.RES_ADDRS IS NOT NULL THEN 1 ELSE 0 END          -- 26.商铺地址
              + CASE WHEN o.KYC_INF IS NOT NULL THEN 1 ELSE 0 END            -- 27.KYC信息
              + CASE WHEN o.APDIX_ID IS NOT NULL THEN 1 ELSE 0 END) AS cnt   -- 28.附件ID(非空计数)
        FROM (SELECT PERSN_LEGAL_BK_CODE, CUST_ID FROM DWD_CUST_INDV_KYC    -- 主表客户集
              UNION
              SELECT PERSN_LEGAL_BK_CODE, CUST_ID FROM DWD_CUST_INDV_CAR_KYC -- 车辆表客户集
              UNION
              SELECT PERSN_LEGAL_BK_CODE, CUST_ID FROM DWD_CUST_INDV_HOUSE_KYC -- 房产表客户集
              UNION
              SELECT PERSN_LEGAL_BK_CODE, CUST_ID FROM DWD_CUST_INDV_KYC_OTHR -- 其他信息表客户集
              UNION
              SELECT PERSN_LEGAL_BK_CODE, CUST_ID FROM DWD_CUST_INDV_SHOP_KYC) u -- 商铺表客户集
        LEFT JOIN (SELECT CUST_ID, PERSN_LEGAL_BK_CODE,
                          MAX(ESTT_INF) ESTT_INF, MAX(SHOP_INF) SHOP_INF,
                          MAX(VIKL_INF) VIKL_INF, MAX(BK_OUTER_DEPO) BK_OUTER_DEPO,
                          MAX(BK_OUTER_FIN) BK_OUTER_FIN, MAX(BK_OUTER_FUND) BK_OUTER_FUND,
                          MAX(BK_OUTER_INSUR) BK_OUTER_INSUR, MAX(BK_OUTER_GOLD) BK_OUTER_GOLD,
                          MAX(STK_INVEST) STK_INVEST, MAX(MTH_INCOM) MTH_INCOM,
                          MAX(YR_INCOM) YR_INCOM, MAX(BK_OUTER_LOAN_BAL) BK_OUTER_LOAN_BAL,
                          MAX(BK_OUTER_CRDT_LMT) BK_OUTER_CRDT_LMT, MAX(AVAIL_LMT) AVAIL_LMT
                     FROM DWD_CUST_INDV_KYC
                    GROUP BY CUST_ID, PERSN_LEGAL_BK_CODE) k                 -- 主表14项(客户级聚合)
          ON k.CUST_ID = u.CUST_ID
         AND k.PERSN_LEGAL_BK_CODE = u.PERSN_LEGAL_BK_CODE
        LEFT JOIN (SELECT CUST_ID, PERSN_LEGAL_BK_CODE,
                          MAX(VEHICLE_PLATE_NO) VEHICLE_PLATE_NO, MAX(USAGE_NATURE) USAGE_NATURE,
                          MAX(IS_CAR_LOAN) IS_CAR_LOAN, MAX(IS_CAR_MORTGAGED) IS_CAR_MORTGAGED
                     FROM DWD_CUST_INDV_CAR_KYC
                    GROUP BY CUST_ID, PERSN_LEGAL_BK_CODE) v                 -- 车辆表4项(任一记录非空即计)
          ON v.CUST_ID = u.CUST_ID
         AND v.PERSN_LEGAL_BK_CODE = u.PERSN_LEGAL_BK_CODE
        LEFT JOIN (SELECT CUST_ID, PERSN_LEGAL_BK_CODE,
                          MAX(PROP_OWNER_CERT_NO) PROP_OWNER_CERT_NO, MAX(HOUSE_AREA) HOUSE_AREA,
                          MAX(IS_HOUSE_MORTGAGED) IS_HOUSE_MORTGAGED, MAX(RES_ADDRS) RES_ADDRS
                     FROM DWD_CUST_INDV_HOUSE_KYC
                    GROUP BY CUST_ID, PERSN_LEGAL_BK_CODE) h                 -- 房产表4项(任一记录非空即计)
          ON h.CUST_ID = u.CUST_ID
         AND h.PERSN_LEGAL_BK_CODE = u.PERSN_LEGAL_BK_CODE
        LEFT JOIN (SELECT CUST_ID, PERSN_LEGAL_BK_CODE,
                          MAX(KYC_INF) KYC_INF, MAX(APDIX_ID) APDIX_ID
                     FROM DWD_CUST_INDV_KYC_OTHR
                    GROUP BY CUST_ID, PERSN_LEGAL_BK_CODE) o                 -- 其他信息表2项(任一记录非空即计)
          ON o.CUST_ID = u.CUST_ID
         AND o.PERSN_LEGAL_BK_CODE = u.PERSN_LEGAL_BK_CODE
        LEFT JOIN (SELECT CUST_ID, PERSN_LEGAL_BK_CODE,
                          MAX(PROP_OWNER_CERT_NO) PROP_OWNER_CERT_NO, MAX(HOUSE_AREA) HOUSE_AREA,
                          MAX(IS_HOUSE_MORTGAGED) IS_HOUSE_MORTGAGED, MAX(RES_ADDRS) RES_ADDRS
                     FROM DWD_CUST_INDV_SHOP_KYC
                    GROUP BY CUST_ID, PERSN_LEGAL_BK_CODE) s                 -- 商铺表4项(任一记录非空即计)
          ON s.CUST_ID = u.CUST_ID
         AND s.PERSN_LEGAL_BK_CODE = u.PERSN_LEGAL_BK_CODE
    ) x;

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP2 完成：按5张KYC表计算客户级KYC完整度并写入ADS_NEW_CUST_KYC(KYC_STATE阈值≥23+KYC_COMPL_RATE率值)';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 步骤4_TMP3: 生成180天内新客基础数据
  --   新客定义: OPEN_DATE距今180天内(含180天)
  --   数据来源:
  --     DWS_CUST_ASSE_LIAB(a): 客户资产负债,取BAL_TYPE='1'余额快照
  --     DWD_CUST_INDV_INFO(c): 客户基本信息,获取OPEN_DATE开户日期
  --     DWD_CUST_MAN(m):       信贷管户关系表,MNG_TYP='1'获取理财管户经理
  --     DWS_CUST_LVL_INFO(l):  客户等级信息
  --     ADS_NEW_CUST_KYC(t): 客户级KYC完整度(v2.6.0转正式基表)
  --     ADS_MKT_REC_INFO(r):   营销接触记录,判断新客周期内有效接触
  --
  --   新客周期计算(左闭右开):
  --      NEW_CUST_CYCLE='1': 0≤(DATA_DATE-OPEN_DATE)<30天
  --      NEW_CUST_CYCLE='2': 30≤(DATA_DATE-OPEN_DATE)<100天
  --      NEW_CUST_CYCLE='3': 100≤(DATA_DATE-OPEN_DATE)≤180天
  --
  --   接触状态(v2.3.1更新):
  --      时间范围: 从客户OPEN_DATE到DATA_DATE期间的接触均计入
  --      接触类型: 电话('1')/面访('2')/企微('3')/短信('4')
  --      接触人员: 理财管户客户经理(DWD_CUST_MAN, MNG_TYP='1')
  --      CNTCT_STATE='1': 新客周期内有有效接触; CNTCT_STATE='0': 无
  --
  --   当月新客未评级(v2.3.0新增):
  --      OPEN_DATE所在月份 = 跑批日所在月份 → CUST_LVL='未评级'
  --      非当月新客 → 取DWS_CUST_LVL_INFO的CUST_LVL
  --      若DWS_CUST_LVL_INFO无记录也默认'未评级'
  --
  --   KYC完整度(v2.5.0更新):
  --      KYC_STATE直接取自基表ADS_NEW_CUST_KYC(步骤TMP2按5张KYC表
  --      28项字段计算,阈值≥23)；无KYC记录的客户兜底为'0'不完整
  ------------------------------------------------------------------
  V_NO_ID := 'TMP3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_ADS_NEW_CUST_BASE (
      PERSN_LEGAL_BK_CODE,       -- 法人行号
      CUST_ID,                   -- 客户编号
      CUST_NAME,                 -- 客户姓名
      CUST_LVL,                  -- 客户等级(当月新客='未评级')
      NEW_CUST_CYCLE,            -- 新客周期(1=0~30天,2=30~100天,3=100~180天)
      DEPO_CURNT_DEPO_BAL,       -- 活期存款余额
      FIXD_DEPO_BAL,             -- 定期存款余额
      FIN_AMT,                   -- 理财余额
      CNTCT_STATE,               -- 接触状态(1=已接触,0=未接触)
      KYC_STATE,                 -- KYC完成状态(1=完整≥23/28,0=不完整)
      POST_ID,                   -- 管户经理岗位编号
      ORG_ID                     -- 归属机构编号
  )
  SELECT a.PERSN_LEGAL_BK_CODE,                                             -- 法人行号_取资产快照的法人行号
         a.CUST_ID,                                                         -- 客户编号
         c.CUST_NAME,                                                       -- 客户姓名_取客户基本信息
         -- 2026-08-01口径确认: 客户等级一律取DWS_CUST_LVL_INFO(新客等级含未评级码值11
         -- 亦记录于等级表),不再按开户月重新判断；无等级记录时兜底未评级(码值11)
         NVL(l.CUST_LVL, '11'),                                             -- 客户等级
         CASE
           -- v2.1.0: 新客周期左闭右开
           -- 周期1: 开户0~30天(不含30天)
           WHEN TO_DATE(V_DATA_DATE, 'YYYYMMDD') - TO_DATE(REPLACE(SUBSTR(c.OPEN_DATE, 1, 10), '-', ''), 'YYYYMMDD') < 30 THEN '1'
           -- 周期2: 开户30~100天(不含100天)
           WHEN TO_DATE(V_DATA_DATE, 'YYYYMMDD') - TO_DATE(REPLACE(SUBSTR(c.OPEN_DATE, 1, 10), '-', ''), 'YYYYMMDD') < 100 THEN '2'
           -- 周期3: 开户100~180天(含180天)
           WHEN TO_DATE(V_DATA_DATE, 'YYYYMMDD') - TO_DATE(REPLACE(SUBSTR(c.OPEN_DATE, 1, 10), '-', ''), 'YYYYMMDD') <= 180 THEN '3'
         END,                                                                -- 新客周期
         NVL(a.DEPO_CURNT_DEPO_BAL, 0),                                     -- 活期存款余额_取当日余额快照
         NVL(a.FIXD_DEPO_BAL, 0),                                           -- 定期存款余额_取当日余额快照
         NVL(a.FIN_BAL, 0),                                                  -- 理财余额_取当日余额快照
         CASE
           -- v2.3.1: 接触状态判断时间范围改为"新客周期内"
           -- 从客户OPEN_DATE到当前DATA_DATE期间,管户经理有有效接触则标记为已接触
           WHEN EXISTS (
             SELECT 1
               FROM ADS_MKT_REC_INFO r                                         -- 营销活动记录表
              WHERE r.CUST_ID = c.CUST_ID                                      -- 关联客户号
                AND r.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE             -- v2.3.2: 强制联动法人行号作为基础计算单位
                AND r.MKT_PERSN = m.MNGR_POST_ID                         -- v2.3.4: 关联理财管户经理
                AND r.MKT_TYP IN ('1', '2', '3', '4')                          -- 有效接触类型:1=电话,2=面访,3=企微,4=短信
                AND r.MKT_TIME IS NOT NULL                                     -- 接触时间不为空
                AND TO_DATE(REPLACE(SUBSTR(r.MKT_TIME, 1, 10), '-', ''), 'YYYYMMDD')
                    BETWEEN TO_DATE(REPLACE(SUBSTR(c.OPEN_DATE, 1, 10), '-', ''), 'YYYYMMDD')  -- 起始: 客户开户日期
                        AND TO_DATE(V_DATA_DATE, 'YYYYMMDD')                                    -- 截止: 当前跑批日期
           ) THEN '1'                                                          -- 新客周期内有有效接触
           ELSE '0'                                                            -- 新客周期内无有效接触
         END,                                                                -- 接触状态
         NVL(t.KYC_STATE, '0'),                                                -- v2.6.0: KYC状态取基表(无KYC记录兜底'0')
         m.MNGR_POST_ID,                                                      -- v2.3.4: 理财管户经理岗位编号_取自DWD_CUST_MAN(MNG_TYP='1')
         a.ORG_ID                                                             -- 2026-08-01口径确认: 归属机构_取DWS_CUST_ASSE_LIAB资产快照
    FROM DWS_CUST_ASSE_LIAB a                                                 -- 客户资产负债表(当日余额快照)
    JOIN DWD_CUST_INDV_INFO c                                                  -- 客户基本信息(OPEN_DATE,管户经理)
      ON c.CUST_ID = a.CUST_ID
     AND c.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE                        -- v2.3.2: 强制联动法人行号作为基础计算单位
    LEFT JOIN DWD_CUST_MAN m                                                    -- v2.3.4: 信贷管户关系表
      ON m.CUST_ID = c.CUST_ID                                                  -- 关联客户号
     AND m.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE                          -- v2.3.2: 强制联动法人行号
     AND m.MNG_TYP = '1'                                                        -- MNG_TYP='1'=理财管户,仅取理财管户经理
    LEFT JOIN DWS_CUST_LVL_INFO l                                              -- 客户等级信息(当前等级)
      ON l.CUST_ID = c.CUST_ID
     AND l.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE                        -- v2.3.2: 强制联动法人行号作为基础计算单位
     AND l.DATA_DATE = V_DATA_DATE                                               -- 取当日等级快照
    LEFT JOIN ADS_NEW_CUST_KYC t                                                -- v2.6.0: 客户级KYC完整度(基表,步骤TMP2生成)
      ON t.CUST_ID = c.CUST_ID                                                 -- 关联客户号
     AND t.PERSN_LEGAL_BK_CODE = a.PERSN_LEGAL_BK_CODE                         -- v2.3.2: 强制联动法人行号作为基础计算单位
   WHERE a.DATA_DATE = V_DATA_DATE                                             -- 取当日资产快照
     AND a.BAL_TYPE = '1'                                                      -- BAL_TYPE='1'=余额类型
     AND c.OPEN_DATE IS NOT NULL                                               -- 开户日期不为空
    AND TO_DATE(REPLACE(SUBSTR(c.OPEN_DATE, 1, 10), '-', ''), 'YYYYMMDD')
        BETWEEN TO_DATE(V_180D_WINDOW_BEGIN, 'YYYYMMDD')                       -- 开户日≥180天前(左闭,参数27)
            AND TO_DATE(V_DATA_DATE, 'YYYYMMDD');                             -- 开户日≤当天(右闭)—即180天内新客

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP3 完成：生成180天内新客基础数据（含当月新客未评级+新客周期内接触判断+临时表取KYC状态）';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 步骤4: 目标表写入 — 生成月度(M)明细数据
  --   v2.3.0: 去掉季(Q)/年(N)切片,仅保留月度(M)
  --   每轮跑批写入当天(DATA_DATE=V_SYSDAT)的月度新客明细
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CUST_NEW_CUST_DTL (
      PERSN_LEGAL_BK_CODE,       -- 法人行号
      DATA_DATE,                  -- 数据日期(YYYYMMDD)
      CUST_ID,                    -- 客户编号
      CUST_NAME,                  -- 客户姓名
      CUST_LVL,                   -- 客户等级
      NEW_CUST_CYCLE,             -- 新客周期(1/2/3)
      DEPO_CURNT_DEPO_BAL,        -- 活期存款余额
      FIXD_DEPO_BAL,              -- 定期存款余额
      FIN_AMT,                    -- 理财余额
      CNTCT_STATE,                -- 接触状态(1=已接触,0=未接触)
      KYC_STATE,                  -- KYC完成状态(1=完整,0=不完整)
      POST_ID,                    -- 管户经理岗位编号
      ORG_ID,                     -- 归属机构编号
      STATIS_CYCLE                -- 统计周期 - v2.3.0: 仅保留M(月度)
  )
  SELECT b.PERSN_LEGAL_BK_CODE,
         V_DATA_DATE,                                                         -- 数据日期=跑批日期
         b.CUST_ID,
         b.CUST_NAME,
         b.CUST_LVL,
         b.NEW_CUST_CYCLE,
         b.DEPO_CURNT_DEPO_BAL,
         b.FIXD_DEPO_BAL,
         b.FIN_AMT,
         b.CNTCT_STATE,
         b.KYC_STATE,
         b.POST_ID,
         b.ORG_ID,
         'M'                                                                   -- v2.3.0: 仅生成月度(M)统计周期
    FROM TMP_ADS_NEW_CUST_BASE b;                                              -- 从临时表读取新客基础数据

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：写入月度(M)新客经营明细';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_new_cust_statis(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_new_cust_statis(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: PRC_ADS_CUST_NEW_CUST_STATIS
  -- 中文名称: 新客经营统计处理
  -- 处理周期: 日
  -- 过程描述: 从新客经营明细表按机构向上汇总和客户经理维度
  --           生成新客经营统计数据,包含新客数、接触率、KYC完成率、
  --           金融资产区间分布等指标
  -- 来源表: ADS_CUST_NEW_CUST_DTL(新客经营明细),
  --         DWS_CUST_ASSE_LIAB(客户资产负债_获取T-1日AUM),
  --         DWD_SYS_ORG(机构层级_递归向上汇总)
  -- 目标表: ADS_CUST_NEW_CUST_STATIS(新客经营统计表)
  -- 临时表: TMP_ADS_NEW_CUST_STAT_SRC(物理临时表,存储展开后的统计源数据)
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.4.1
  -- 关联需求: REQ-CUST-007(新客定义), REQ-CUST-009(计算单位),
  --           REQ-CUST-010(去季年切片)
  -- 变更记录:
  --   v2.1.0(2026-07-22): 1.新客定义改为使用DWD_CUST_INDV_INFO的OPEN_DATE字段
  --                       2.新客周期边界值改为左闭右开(0~30、30~100、100~180)
  --   v2.2.0(2026-07-27): 计算单位调整为客户号+归属机构；统计上一日资产使用
  --                       sys_fun_deal_date(V_SYSDAT, 1)
  --   v2.3.0(2026-07-30): 1.统计周期去掉季(Q)/年(N)切片,仅保留月度(M)
  --                       2.移除PREV_QUARTER_END/PREV_YEAR_END变量
  --   v2.3.1(2026-07-30): 继承DTL的接触状态变更(无需独立修改统计逻辑)
  --   v2.3.2(2026-07-30): 修复关联计算缺少PERSN_LEGAL_BK_CODE问题,
  --                       DWS_CUST_ASSE_LIAB左关联强制联动法人行号
  --   v2.4.0(2026-08-04): F-04:DWS T-1日AUM预查询写入TMP共用(消除UNION ALL重复JOIN)；
  --                       F-05:非月末日不再重算上月末统计(消除冗余)；
  --                       F-07:删除V_END_DATE无效初始化
  --   v2.4.1(2026-08-05): F-01:TMP_AUM段独立日志步骤(模板合规修复)；
  --                       F-03:删除V_PREV_MONTH_END死变量；
  --                       F-06:CROSS JOIN改用静态值(避免重复扫描大临时表)
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  -- 局部变量声明
  ------------------------------------------------------------------
  -- V_PRC_DESC:     存储过程描述文字(用于日志记录)
  V_PRC_DESC             VARCHAR(100) := '新客经营统计处理';
  -- V_PRC_NAME:     存储过程名称(用于日志记录)
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_NEW_CUST_STATIS';
  -- V_LOG_MSG:      日志消息内容(最大4000字符)
  V_LOG_MSG              VARCHAR(4000);
  -- V_LOG_FLG:      日志标记(OUTCDE值,0=正常,-1=异常)
  V_LOG_FLG              INTEGER;
  -- V_LOG_BUTTON:    是否记录日志(1=记录,0=不记录),默认1
  V_LOG_BUTTON           INTEGER := 1;
  -- V_NO_ID:         当前步骤编号标识,用于日志定位(TMP1/TMP2/3)
  V_NO_ID                VARCHAR(10);
  -- V_BGN_DATE:      步骤开始时间(用于计算耗时)
  V_BGN_DATE             DATE;
  -- V_END_DATE:      步骤结束时间
  V_END_DATE             DATE;
  -- V_DURA_DATE:     步骤耗时(秒),(V_END_DATE - V_BGN_DATE) * 86400
  V_DURA_DATE            INTEGER;
  -- V_DATA_DATE:     数据日期,取V_SYSDAT值,格式YYYYMMDD
  V_DATA_DATE            VARCHAR2(8);
  -- V_PREV_DAY:       上一天日期(T-1),通过sys_fun_deal_date(V_SYSDAT, 1)计算,
  --                    用于获取T-1日的客户AUM余额快照
  V_PREV_DAY             VARCHAR2(8);
  -- V_PREV_MONTH_END: v2.4.1 F-03 删除死变量(v2.4.0 F-05去掉非月末重算后已无引用)
  -- V_HISTORY_CUTOFF_DATE: 三年历史清理边界(参数19),用于清理过期历史数据
  V_HISTORY_CUTOFF_DATE   VARCHAR2(8);

  ------------------------------------------------------------------
  -- 内部辅助过程：清空指定物理临时表
  -- 参数 P_TABLE_NAME: 临时表名称
  ------------------------------------------------------------------
  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 步骤1: 参数检查
  -- 校验V_SYSDAT格式：必须为8位数字YYYYMMDD
  ------------------------------------------------------------------
  IF V_SYSDAT IS NULL
     OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')
  THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  -- 设置数据日期 = 跑批日期
  V_DATA_DATE := V_SYSDAT;
  -- 计算上一天日期(T-1),用于获取T-1日AUM余额
  V_PREV_DAY := sys_fun_deal_date(V_SYSDAT, 1);
  -- v2.4.1 F-03: 删除V_PREV_MONTH_END赋值(v2.4.0 F-05去掉非月末重算后已无引用)
  ------------------------------------------------------------------
  -- 步骤2_TMP1: 清理当前数据日统计结果和历史数据
  --   - 删除当天+上月末的统计结果(幂等重跑)
  --   - 删除三年前的历史过期数据
  --   - 清空物理临时表 TMP_ADS_NEW_CUST_STAT_SRC
  --   v2.3.0: 去掉季/年切片,删除条件从M/Q/N简化为M
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 删除当天月度统计(支持重跑幂等)和上一月末统计(将被重新计算覆盖)
  DELETE FROM ADS_CUST_NEW_CUST_STATIS T
   WHERE T.DATA_DATE = V_DATA_DATE;                                       -- 当天统计(支持重跑幂等)

  -- 删除三年历史清理边界(参数19)之前的历史数据
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);
  DELETE FROM ADS_CUST_NEW_CUST_STATIS T
   WHERE T.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  -- 清空临时表
  TRUNC_TMP('TMP_ADS_NEW_CUST_STAT_SRC');
  TRUNC_TMP('TMP_ADS_NEW_CUST_AUM');                                     -- 清空T-1日AUM预查询表
  COMMIT;

  V_END_DATE := SYSDATE;
  -- 计算本步骤耗时(秒)
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理当前数据日统计结果、三年前历史数据和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 步骤2: T-1日AUM预查询(F-04: DWS只扫描一次,两个UNION ALL分支共用)
  --   v2.4.1 F-01: 独立日志步骤,符合模板规则#4
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_ADS_NEW_CUST_AUM (
      CUST_ID, PERSN_LEGAL_BK_CODE, ORG_ID, AUM_BAL
  )
  SELECT A.CUST_ID,
         A.PERSN_LEGAL_BK_CODE,
         A.ORG_ID,
         NVL(A.AUM_BAL, 0)
    FROM DWS_CUST_ASSE_LIAB A
   WHERE A.DATA_DATE = V_PREV_DAY
     AND A.BAL_TYPE = '1';
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP_AUM 完成：T-1日AUM预查询写入TMP';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE,
      V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 步骤4_TMP2: 展开机构和客户经理统计对象
  --   从明细表读取新客数据,按两个维度展开：
  --     维度1: 机构向上汇总 — 使用DWD_SYS_ORG递归CONNECT_BY_ROOT
  --             从网点级机构向上汇总到所有上级机构
  --     维度2: 客户经理维度 — 直接从明细表取POST_ID
  --   数据来源: ADS_CUST_NEW_CUST_DTL(新客明细) + TMP_ADS_NEW_CUST_AUM(预查询AUM)
  --   v2.3.0: 去掉季/年切片,仅处理M(月度)统计周期数据
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_ADS_NEW_CUST_STAT_SRC (
      PERSN_LEGAL_BK_CODE,       -- 法人行号
      DATA_DATE,                  -- 数据日期(YYYYMMDD)
      STATIS_CYCLE,               -- 统计周期(M=月度)
      STATIS_OBJ,                 -- 统计对象(机构编号或客户经理岗位编号)
      NEW_CUST_CYCLE,             -- 新客周期(1=0~30,2=30~100,3=100~180)
      CNTCT_STATE,                -- 接触状态(1=已接触,0=未接触)
      KYC_STATE,                  -- KYC完成状态(1=完整,0=不完整)
      PNT_AUM_BAL                 -- T-1日AUM余额(用于资产区间分段统计)
  )
  -- ============================
  -- 维度1: 机构向上汇总
  -- ============================
  SELECT D.PERSN_LEGAL_BK_CODE,                                               -- 法人行号
         D.DATA_DATE,                                                         -- 数据日期
         D.STATIS_CYCLE,                                                      -- 统计周期(M)
         O.ANCESTOR_ORG_ID,                                                   -- 统计对象=上级机构编号
         D.NEW_CUST_CYCLE,                                                    -- 新客周期
         D.CNTCT_STATE,                                                       -- 接触状态
         D.KYC_STATE,                                                         -- KYC状态
         NVL(P.AUM_BAL, 0)                                                    -- T-1日AUM余额(来自预查询表)
    FROM ADS_CUST_NEW_CUST_DTL D
    JOIN (
          SELECT DISTINCT
                 CONNECT_BY_ROOT X.ORG_ID AS LEAF_ORG_ID,
                 X.ORG_ID AS ANCESTOR_ORG_ID
            FROM DWD_SYS_ORG X
           START WITH X.ORG_ID IN (
                 SELECT DISTINCT ORG_ID
                   FROM ADS_CUST_NEW_CUST_DTL
                  WHERE ORG_ID IS NOT NULL
                )
         CONNECT BY NOCYCLE PRIOR X.SUP_ORG_ID = X.ORG_ID
    ) O
      ON O.LEAF_ORG_ID = D.ORG_ID
    LEFT JOIN TMP_ADS_NEW_CUST_AUM P                                          -- F-04: 预查询AUM表(替代DWS直接JOIN)
     ON P.CUST_ID = D.CUST_ID
     AND P.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE
     AND P.ORG_ID = D.ORG_ID
   WHERE D.DATA_DATE = V_DATA_DATE                                            -- F-05: 仅当日明细

  UNION ALL

  -- ============================
  -- 维度2: 客户经理维度
  -- ============================
  SELECT D.PERSN_LEGAL_BK_CODE,
         D.DATA_DATE,
         D.STATIS_CYCLE,
         D.POST_ID,                                                           -- 统计对象=客户经理岗位编号
         D.NEW_CUST_CYCLE,
         D.CNTCT_STATE,
         D.KYC_STATE,
         NVL(P.AUM_BAL, 0)                                                    -- T-1日AUM余额(来自预查询表)
    FROM ADS_CUST_NEW_CUST_DTL D
    LEFT JOIN TMP_ADS_NEW_CUST_AUM P                                          -- F-04: 预查询AUM表
     ON P.CUST_ID = D.CUST_ID
     AND P.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE
     AND P.ORG_ID = D.ORG_ID
   WHERE D.POST_ID IS NOT NULL
     AND D.DATA_DATE = V_DATA_DATE;                                           -- F-05: 仅当日明细

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP2 完成：展开机构向上汇总和客户经理统计对象（仅M周期）';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 步骤5: 目标表写入 — 按统计对象和新客周期汇总
  --   汇总维度: PERSN_LEGAL_BK_CODE + DATA_DATE + STATIS_OBJ + STATIS_CYCLE + NEW_CUST_CYCLE
  --   统计指标:
  --     NEW_CUST_CNT:          新客总数(COUNT)
  --     CNTCT_CUST_CNT:        已接触客户数(CNTCT_STATE='1')
  --     ASSET_BAL_SEG1~5:      金融资产五段区间客户数
  --     CNTCT_RATE:            接触率(已接触/总数 ×100%)
  --     KYC_CUST_CNT:          KYC完整客户数(KYC_STATE='1')
  --     COMP_RATE:             KYC完成率(KYC完整/总数 ×100%)
  --   新客周期: 通过CROSS JOIN生成全部(4)汇总行 + 各周期(1/2/3)明细行
  --
  --   金融资产区间分段(基于T-1日AUM余额PNT_AUM_BAL):
  --     段1(0~5万):        PNT_AUM_BAL < 50,000
  --     段2(5~30万):       50,000 ≤ PNT_AUM_BAL < 300,000
  --     段3(30~100万):     300,000 ≤ PNT_AUM_BAL < 1,000,000
  --     段4(100~300万):    1,000,000 ≤ PNT_AUM_BAL < 3,000,000
  --     段5(300万及以上):   PNT_AUM_BAL ≥ 3,000,000
  ------------------------------------------------------------------
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CUST_NEW_CUST_STATIS (
      PERSN_LEGAL_BK_CODE,       -- 法人行号
      DATA_DATE,                  -- 数据日期
      STATIS_OBJ,                 -- 统计对象(机构编号/客户经理编号)
      STATIS_CYCLE,               -- 统计周期(M=月度)
      NEW_CUST_CYCLE,             -- 新客周期(1/2/3/4=全部)
      NEW_CUST_CNT,               -- 新客总数
      CNTCT_CUST_CNT,             -- 已接触客户数
      ASSET_BAL_SEG1_CUST_CNT,    -- 资产段1(0~5万)客户数
      ASSET_BAL_SEG2_CUST_CNT,    -- 资产段2(5~30万)客户数
      ASSET_BAL_SEG3_CUST_CNT,    -- 资产段3(30~100万)客户数
      ASSET_BAL_SEG4_CUST_CNT,    -- 资产段4(100~300万)客户数
      ASSET_BAL_SEG5_CUST_CNT,    -- 资产段5(300万及以上)客户数
      CNTCT_RATE,                 -- 接触率(%)=已接触客户数/新客总数×100
      KYC_CUST_CNT,               -- KYC完整客户数
      COMP_RATE                   -- KYC完成率(%)=KYC完整客户数/新客总数×100
  )
  SELECT S.PERSN_LEGAL_BK_CODE,                                               -- 法人行号
         S.DATA_DATE,                                                         -- 数据日期
         S.STATIS_OBJ,                                                        -- 统计对象
         S.STATIS_CYCLE,                                                      -- 统计周期(M)
         C.NEW_CUST_CYCLE,                                                    -- 新客周期(含全部=4)
         COUNT(*) AS NEW_CUST_CNT,                                            -- 新客总数=该分组下的客户记录数
         SUM(CASE WHEN S.CNTCT_STATE = '1' THEN 1 ELSE 0 END) AS CNTCT_CUST_CNT,  -- 已接触客户数
         SUM(CASE WHEN S.PNT_AUM_BAL < 50000 THEN 1 ELSE 0 END) AS ASSET_BAL_SEG1_CUST_CNT,   -- 资产段1: 0~5万
         SUM(CASE WHEN S.PNT_AUM_BAL >= 50000 AND S.PNT_AUM_BAL < 300000 THEN 1 ELSE 0 END) AS ASSET_BAL_SEG2_CUST_CNT, -- 资产段2: 5~30万
         SUM(CASE WHEN S.PNT_AUM_BAL >= 300000 AND S.PNT_AUM_BAL < 1000000 THEN 1 ELSE 0 END) AS ASSET_BAL_SEG3_CUST_CNT, -- 资产段3: 30~100万
         SUM(CASE WHEN S.PNT_AUM_BAL >= 1000000 AND S.PNT_AUM_BAL < 3000000 THEN 1 ELSE 0 END) AS ASSET_BAL_SEG4_CUST_CNT, -- 资产段4: 100~300万
         SUM(CASE WHEN S.PNT_AUM_BAL >= 3000000 THEN 1 ELSE 0 END) AS ASSET_BAL_SEG5_CUST_CNT, -- 资产段5: 300万及以上
         -- 接触率: 防止除以零,当总数为0时返回0
         CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN S.CNTCT_STATE = '1' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) END AS CNTCT_RATE,
         SUM(CASE WHEN S.KYC_STATE = '1' THEN 1 ELSE 0 END) AS KYC_CUST_CNT,  -- KYC完整客户数
         -- KYC完成率: 防止除以零,当总数为0时返回0
         CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN S.KYC_STATE = '1' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) END AS COMP_RATE
    FROM TMP_ADS_NEW_CUST_STAT_SRC S                                            -- 展开后的统计源数据
   CROSS JOIN (
         -- v2.4.1 F-06: 改用静态值避免重复扫描大临时表
         -- 1=0~30天, 2=30~100天, 3=100~180天, 4=全部(汇总)
         SELECT '1' AS NEW_CUST_CYCLE FROM DUAL
         UNION ALL SELECT '2' FROM DUAL
         UNION ALL SELECT '3' FROM DUAL
         UNION ALL SELECT '4' FROM DUAL
   ) C
   -- 对于全部(4): 包含所有周期客户; 对于具体周期: 仅包含该周期客户
   WHERE C.NEW_CUST_CYCLE = '4' OR S.NEW_CUST_CYCLE = C.NEW_CUST_CYCLE
   GROUP BY S.PERSN_LEGAL_BK_CODE,                                             -- 按法人行号分组
            S.DATA_DATE,                                                       -- 按数据日期分组
            S.STATIS_OBJ,                                                      -- 按统计对象分组
            S.STATIS_CYCLE,                                                    -- 按统计周期分组
            C.NEW_CUST_CYCLE;                                                  -- 按新客周期分组

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：按机构/客户经理和新客周期汇总写入统计(v2.4.1)';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_ads_cust_others_rmnd_org(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_others_rmnd_org(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户调配提醒表
  -- 存储过程编号：PRC_ADS_CUST_OTHERS_RMND_ORG
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：DWD_CUST_MAN(信贷管户关系表)；DWS_CUST_LVL_INFO(客户等级信息表)；TMP2_DWS_CUST_ASSE_LIAB(客户资产负债表_临时表)
  -- 目标表：ADS_CUST_OTHERS_RMND_ORG
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户调配提醒表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_CUST_OTHERS_RMND_ORG';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  -- 只有当日期为 0531 或 1031 时才执行,其他日期直接结束
  IF SUBSTR(V_SYSDAT, 5, 4) NOT IN ('0531', '1031') THEN
    OUTCDE := 0;
    RETURN;
  END IF;


  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  DELETE FROM ADS_CUST_OTHERS_RMND_ORG WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：客户调配提醒
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：客户调配提醒
  INSERT INTO ADS_CUST_OTHERS_RMND_ORG (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      RMND_ID,
      RMND_CATE_BIG,
      RMND_CATE_SML,
      MNGR_POST_ID,
      MNGR_NAME,
      ORG_ID,
      CUST_TYP,
      CUST_ID,
      CUST_NAME,
      PHONE_NO,
      RMND_INF,
      HDLE_STATE,
      RMND_DATE,
      HDLE_TIME,
      DEL_FLG,
      HDLE_DSC,
      CUST_HRAKY,
      ACCT_NO,
      HAPN_BAL,
      ORG_NAME
  )
  SELECT
         V_SYSDAT                          AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE            AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         SEQ_ADS_CUST_OTHERS_RMND_ORG.NEXTVAL  AS RMND_ID              , -- 提醒ID
         '308'                             AS RMND_CATE_BIG        , -- 提醒类型
         '客户调配'                            AS RMND_CATE_SML        , -- 提醒名称
         ''                                AS MNGR_POST_ID         , -- 客户经理编号
         ''                                AS MNGR_NAME            , -- 客户经理名称
         T4.ORG_ID                         AS ORG_ID               , -- 机构编号
         '1'                               AS CUST_TYP             , -- 客户类型
         T2.CUST_ID                        AS CUST_ID              , -- 客户编号
         T4.CUST_NAME                      AS CUST_NAME            , -- 客户名称
         ''                                AS PHONE_NO             , -- 手机号
         ''                                AS RMND_INF             , -- 提醒内容
         '0'                               AS HDLE_STATE           , -- 处理状态
         V_SYSDAT                          AS RMND_DATE            , -- 提醒日期
         ''                                AS HDLE_TIME            , -- 处理时间
         ''                                AS DEL_FLG              , -- 删除标志
         ''                                AS HDLE_DSC             , -- 处理说明
         T4.CUST_HRAKY                     AS CUST_HRAKY           , -- 客户层级
         ''                                AS ACCT_NO              , -- 客户账户
         ''                                AS HAPN_BAL             , -- 交易金额
         ''                                AS ORG_NAME              -- 归属机构
    FROM TMP2_DWS_CUST_ASSE_LIAB T1 -- 客户资产负债表_临时表
    INNER JOIN DWD_CUST_MAN T2 -- 信贷管户关系表
      ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE AND T1.ORG_ID <> T2.ORG_ID AND T2.MNG_TYP = '1'
    INNER JOIN DWS_CUST_LVL_INFO T4 -- 客户等级信息表
      ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：客户调配提醒';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_potn_upgrade_cust_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_potn_upgrade_cust_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：潜力提升客户明细处理
  -- 处理周期: 日
  -- 过程描述: 按临界等级、月日均资产和T-1时点资产计算达标、接触及统计指标
  -- 来源表: DWS_CUST_ASSE_LIAB(当月)、DWS_CUST_ASSE_LIAB_HIS(上月末), DWD_CUST_INDV_INFO, DWD_CUST_MAN, DWS_CUST_LVL_INFO, ADS_MKT_REC_INFO
  -- 目标表: ADS_CUST_POTN_UPGRADE_CUST_DTL
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v3.1.2
  -- 变更记录:
  --   v2.2.0 2026-07-27 计算单位调整为客户号+归属机构(ORG_ID)
  --   v2.3.0 2026-07-27 相对日期统一使用sys_fun_deal_date
  --   v2.4.0 2026-07-27 补充三键关联及业务处理段说明
  --   v2.4.1 2026-07-28 年码值N→Y；DWS_CUST_LVL_INFO关联补PERSN_LEGAL_BK_CODE
  --   v2.4.2 2026-07-28 月初日期参数改用DATE类型声明
  --   v2.4.3 2026-07-28 DWS_CUST_ASSE_LIAB关联移除ORG_ID条件
  --   v2.4.4 2026-07-28 DWD_CUST_INDV_INFO关联补PERSN_LEGAL_BK_CODE
  --   v2.5.0 2026-07-28 管户经理改用DWD_CUST_MAN表(MNG_TYP='1'理财管户)
  --   v3.0.0 2026-07-28 月/季/年切片按不同时间窗口独立计算接触状态：月=当月初,季=TRUNC(Q),年=TRUNC(Y)
  --   v3.1.0 2026-07-30 去掉季/年统计周期切片,仅保留月度(对应v2.0.3需求变更)
  --   v3.1.1 2026-07-30 T-1日=跑批日期V_SYSDAT；PNT_AUM_BAL改为从b取AUM_BAL,移除冗余q关联和V_PREV_DAY变量
  --   v3.1.2 2026-07-30 补充所有变量、字段、表别名、逻辑参数的注释
  --   v3.2.0 2026-08-04 F-01:接触EXISTS补PERSN_LEGAL_BK_CODE+MKT_PERSN关联(防跨法人行误匹配)；
  --                       F-02:LVL_CRIT先INSERT后DELETE改为WHERE条件直接过滤；
  --                       F-04:新增V_RUN_DATE_DT变量专用于业务逻辑,V_END_DATE仅用于日志
   --   v3.2.1 2026-08-06【待确认】 上月末月日均查询(p)改用DWS_CUST_ASSE_LIAB_HIS(与当期表同构)
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '潜力提升客户明细处理';                  -- 过程描述
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_POTN_UPGRADE_CUST_DTL';  -- 过程名称
  V_LOG_MSG              VARCHAR(4000);                                         -- 日志消息文本
  V_LOG_FLG              INTEGER;                                               -- 日志标志(0=成功)
  V_LOG_BUTTON           INTEGER := 1;                                          -- 日志记录开关(1=启用)
  V_NO_ID                VARCHAR(10);                                           -- 当前步骤序号
  V_BGN_DATE             DATE;                                                  -- 步骤开始时间
  V_END_DATE             DATE;                                                  -- 步骤结束时间
  V_DURA_DATE            INTEGER;                                               -- 步骤耗时(秒)
  V_PREV_MONTH_END       VARCHAR2(8);                                           -- 上月末日期(YYYYMMDD),用于取上月月日均资产筛选临界客户
  V_CURR_MONTH_BEGIN_DT  DATE;                                                  -- 当月初日期,用于限定月接触窗口起点
  V_RUN_DATE_DT          DATE;                                                  -- 跑批日期DATE类型,专用于业务逻辑(接触窗口上界)
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);                                           -- 三年历史清理边界(YYYYMMDD),sys_fun_deal_date(V_SYSDAT,19)

  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 1. 参数检查
  ------------------------------------------------------------------
  -- 1. 校验跑批日期并初始化本过程使用的相对业务日期参数。
  IF V_SYSDAT IS NULL
     OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')
  THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_END_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_RUN_DATE_DT := V_END_DATE;                                                  -- 跑批日期DATE类型(业务逻辑用,V_END_DATE后续仅用于日志)
  V_PREV_MONTH_END := sys_fun_deal_date(V_SYSDAT, 2);
  V_CURR_MONTH_BEGIN_DT := TO_DATE(sys_fun_deal_date(V_SYSDAT, 9), 'YYYYMMDD');
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);

  ------------------------------------------------------------------
  -- 2. TMP1：清理当前数据日明细和物理临时表
  ------------------------------------------------------------------
  V_NO_ID := 'TMP1';
  V_BGN_DATE := SYSDATE;

  -- 2. 清理本跑批日已生成的明细和超过保留期限的历史数据,保证过程可重跑。
  DELETE FROM ADS_CUST_POTN_UPGRADE_CUST_DTL D
   WHERE D.DATA_DATE = V_SYSDAT;

  DELETE FROM ADS_CUST_POTN_UPGRADE_CUST_DTL D
   WHERE D.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  TRUNC_TMP('TMP_ADS_POTN_BASE');
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理当前数据日明细和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 3. TMP2：生成临界客户及月均、时点、接触基础数据
  ------------------------------------------------------------------
  V_NO_ID := 'TMP2';
  V_BGN_DATE := SYSDATE;

  -- 3. 基于上月末月日均资产筛选临界客户,并按客户、法人行、归属机构关联资产和接触记录。
  INSERT INTO TMP_ADS_POTN_BASE (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      CUST_ID,                                                  -- 客户号
      CUST_NAME,                                                -- 客户姓名
      CUST_LVL,                                                 -- 当前客户等级(来源DWS_CUST_LVL_INFO)
      LVL_CRIT,                                                 -- 临界升级等级(03=优质/04=财富1/05=财富2/06=贵宾/07=私行)
      DEPO_CURNT_DEPO_BAL,                                      -- T-1日活期存款余额(来源b.DEPO_CURNT_DEPO_BAL)
      FIXD_DEPO_BAL,                                            -- T-1日定期存款余额(来源b.FIXD_DEPO_BAL)
      FIN_AMT,                                                  -- T-1日理财余额(来源b.FIN_BAL)
      CURR_MTH_AVG_AUM,                                         -- 当月月日均AUM(来源m.AUM_BAL,BAL_TYPE='2')
      PNT_AUM_BAL,                                              -- T-1日时点AUM(T-1=跑批日,来源b.AUM_BAL,BAL_TYPE='1')
      CNTCT_STATE_M,                                            -- 月接触状态(1=当月初至跑批日有营销接触,0=无)
      POST_ID,                                                  -- 管户经理岗位ID(来源DWD_CUST_MAN,MNG_TYP='1'理财管户)
      ORG_ID                                                    -- 归属机构ID(来源上月末资产记录的ORG_ID)
  )
  SELECT p.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         c.CUST_ID,                                             -- 客户号
         c.CUST_NAME,                                           -- 客户姓名(来源DWD_CUST_INDV_INFO)
         l.CUST_LVL,                                            -- 当前客户等级(来源DWS_CUST_LVL_INFO,取跑批日最新等级)
         CASE                                                   -- 根据上月末月日均AUM确定临界升级等级
           WHEN p.AUM_BAL >= 45000 AND p.AUM_BAL < 50000 THEN '03'       -- 临界优质：4.5万≤AUM<5万
           WHEN p.AUM_BAL >= 270000 AND p.AUM_BAL < 300000 THEN '04'     -- 临界财富1：27万≤AUM<30万
           WHEN p.AUM_BAL >= 450000 AND p.AUM_BAL < 500000 THEN '05'     -- 临界财富2：45万≤AUM<50万
           WHEN p.AUM_BAL >= 900000 AND p.AUM_BAL < 1000000 THEN '06'    -- 临界贵宾：90万≤AUM<100万
           WHEN p.AUM_BAL >= 2700000 AND p.AUM_BAL < 3000000 THEN '07'   -- 临界私行：270万≤AUM<300万
         END,
         NVL(b.DEPO_CURNT_DEPO_BAL, 0),                         -- T-1日活期存款余额(BAL_TYPE='1'时点,若无则0)
         NVL(b.FIXD_DEPO_BAL, 0),                               -- T-1日定期存款余额(BAL_TYPE='1'时点,若无则0)
         NVL(b.FIN_BAL, 0),                                     -- T-1日理财余额(BAL_TYPE='1'时点,若无则0)
         NVL(m.AUM_BAL, 0),                                     -- 当月月日均AUM(BAL_TYPE='2'月日均,若无则0)
         NVL(b.AUM_BAL, 0),                                     -- T-1日时点AUM(T-1=跑批日,BAL_TYPE='1'时点)
         CASE                                                   -- 月接触：当月初至跑批日存在有效营销接触记录
           WHEN EXISTS (
             SELECT 1
               FROM ADS_MKT_REC_INFO r                           -- 营销接触记录表
              WHERE r.CUST_ID = c.CUST_ID
                AND r.PERSN_LEGAL_BK_CODE = c.PERSN_LEGAL_BK_CODE  -- 双键关联：客户号+法人行号
                AND r.MKT_PERSN = cm.MNGR_POST_ID               -- 仅统计本管户经理的接触
                AND r.MKT_TYP IN ('1', '2', '3', '4')           -- 营销接触类型(1=电话/2=短信/3=微信/4=上门)
                AND r.MKT_TIME IS NOT NULL                      -- 接触时间不为空
                AND TO_DATE(REPLACE(SUBSTR(r.MKT_TIME, 1, 10), '-', ''), 'YYYYMMDD')
                    BETWEEN V_CURR_MONTH_BEGIN_DT AND V_RUN_DATE_DT  -- 接触时间在当月初至跑批日范围内
           ) THEN '1'                                           -- 有接触
           ELSE '0'                                             -- 无接触
         END,
         cm.MNGR_POST_ID,                                       -- 管户经理岗位ID
         p.ORG_ID                                               -- 归属机构ID
    FROM DWS_CUST_ASSE_LIAB_HIS p                               -- p：上月末月日均资产(HIS),用于筛选临界客户(DATA_DATE=V_PREV_MONTH_END, BAL_TYPE='2')
    JOIN DWD_CUST_INDV_INFO c                                   -- c：客户基本信息(客户姓名)
      ON c.CUST_ID = p.CUST_ID
     AND c.PERSN_LEGAL_BK_CODE = p.PERSN_LEGAL_BK_CODE         -- 双键关联：客户号+法人行号
    LEFT JOIN DWD_CUST_MAN cm                                   -- cm：管户经理关系(理财管户)
      ON cm.CUST_ID = p.CUST_ID
     AND cm.PERSN_LEGAL_BK_CODE = p.PERSN_LEGAL_BK_CODE
     AND cm.MNG_TYP = '1'                                       -- 理财管户类型
    LEFT JOIN DWS_CUST_LVL_INFO l                               -- l：客户等级(跑批日最新等级)
      ON l.CUST_ID = p.CUST_ID
     AND l.PERSN_LEGAL_BK_CODE = p.PERSN_LEGAL_BK_CODE
     AND l.DATA_DATE = V_SYSDAT                                 -- 取跑批日等级数据
    LEFT JOIN DWS_CUST_ASSE_LIAB m                              -- m：当月月日均AUM(DATA_DATE=V_SYSDAT, BAL_TYPE='2')
     ON m.CUST_ID = p.CUST_ID
     AND m.PERSN_LEGAL_BK_CODE = p.PERSN_LEGAL_BK_CODE
     AND m.DATA_DATE = V_SYSDAT
     AND m.BAL_TYPE = '2'                                       -- 月日均余额类型
    LEFT JOIN DWS_CUST_ASSE_LIAB b                              -- b：T-1日时点资产(DATA_DATE=V_SYSDAT, BAL_TYPE='1')
     ON b.CUST_ID = p.CUST_ID
     AND b.PERSN_LEGAL_BK_CODE = p.PERSN_LEGAL_BK_CODE
     AND b.DATA_DATE = V_SYSDAT                                 -- T-1日=跑批日期
     AND b.BAL_TYPE = '1'                                       -- 时点余额类型
   WHERE p.DATA_DATE = V_PREV_MONTH_END                         -- 取上月末月日均资产
     AND p.BAL_TYPE = '2'                                       -- 月日均余额类型
     AND (
       (p.AUM_BAL >= 45000 AND p.AUM_BAL < 50000) OR           -- 临界优质：4.5万≤AUM<5万
       (p.AUM_BAL >= 270000 AND p.AUM_BAL < 300000) OR         -- 临界财富1：27万≤AUM<30万
       (p.AUM_BAL >= 450000 AND p.AUM_BAL < 500000) OR         -- 临界财富2：45万≤AUM<50万
       (p.AUM_BAL >= 900000 AND p.AUM_BAL < 1000000) OR        -- 临界贵宾：90万≤AUM<100万
       (p.AUM_BAL >= 2700000 AND p.AUM_BAL < 3000000)          -- 临界私行：270万≤AUM<300万
     );

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP2 完成：生成临界客户及月均、时点、接触基础数据';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 4. 目标表写入：生成月度统计周期明细
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 4. 接触窗口为当月初至跑批日,达标判断使用T-1时点AUM。
  INSERT INTO ADS_CUST_POTN_UPGRADE_CUST_DTL (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      DATA_DATE,                                                -- 数据日期(YYYYMMDD,=跑批日期V_SYSDAT)
      CUST_ID,                                                  -- 客户号
      CUST_NAME,                                                -- 客户姓名
      CUST_LVL,                                                 -- 当前客户等级
      LVL_CRIT,                                                 -- 临界升级等级(03/04/05/06/07)
      DEPO_CURNT_DEPO_BAL,                                      -- T-1日活期存款余额
      FIXD_DEPO_BAL,                                            -- T-1日定期存款余额
      FIN_AMT,                                                  -- T-1日理财余额
      CNTCT_STATE,                                              -- 月接触状态(1=有接触,0=无接触)
      QUAL_STATE,                                               -- T-1时点达标状态(1=达标,0=未达标)
      POST_ID,                                                  -- 管户经理岗位ID
      ORG_ID,                                                   -- 归属机构ID
      STATIS_CYCLE                                              -- 统计周期(M=月度)
  )
  SELECT x.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         V_SYSDAT,                                              -- 数据日期=跑批日期
         x.CUST_ID,                                             -- 客户号
         x.CUST_NAME,                                           -- 客户姓名
         x.CUST_LVL,                                            -- 当前客户等级
         x.LVL_CRIT,                                            -- 临界升级等级
         x.DEPO_CURNT_DEPO_BAL,                                 -- T-1日活期存款余额
         x.FIXD_DEPO_BAL,                                       -- T-1日定期存款余额
         x.FIN_AMT,                                             -- T-1日理财余额
         x.CNTCT_STATE_M,                                       -- 月接触状态(来自TMP_ADS_POTN_BASE.CNTCT_STATE_M)
         CASE                                                   -- T-1时点达标判断：按临界等级阈值比较T-1时点AUM
           WHEN (x.LVL_CRIT = '03' AND x.PNT_AUM_BAL >= 50000)      -- 临界优质→达标阈值5万
             OR (x.LVL_CRIT = '04' AND x.PNT_AUM_BAL >= 300000)     -- 临界财富1→达标阈值30万
             OR (x.LVL_CRIT = '05' AND x.PNT_AUM_BAL >= 500000)     -- 临界财富2→达标阈值50万
             OR (x.LVL_CRIT = '06' AND x.PNT_AUM_BAL >= 1000000)    -- 临界贵宾→达标阈值100万
             OR (x.LVL_CRIT = '07' AND x.PNT_AUM_BAL >= 3000000)    -- 临界私行→达标阈值300万
           THEN '1'                                             -- 达标
           ELSE '0'                                             -- 未达标
         END,
         x.POST_ID,                                             -- 管户经理岗位ID
         x.ORG_ID,                                              -- 归属机构ID
         'M'                                                    -- 统计周期：月度
    FROM TMP_ADS_POTN_BASE x;

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：写入潜力提升客户明细';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

EXCEPTION
  -- 5. 发生异常时回滚本过程事务并记录失败日志。
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_potn_upgrade_statis(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_potn_upgrade_statis(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：潜力提升统计处理
  -- 处理周期: 日
  -- 过程描述: 按机构向上汇总和客户经理维度生成潜力提升统计
  -- 来源表: ADS_CUST_POTN_UPGRADE_CUST_DTL, DWS_CUST_ASSE_LIAB, DWD_SYS_ORG
  -- 目标表: ADS_CUST_POTN_UPGRADE_STATIS
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v3.1.1
  -- 变更记录:
  --   v2.2.0 2026-07-27 计算单位调整为客户号+归属机构(ORG_ID)
  --   v2.3.0 2026-07-27 相对日期统一使用sys_fun_deal_date
  --   v2.4.0 2026-07-27 补充三键关联及各业务处理段说明
  --   v2.4.1 2026-07-28 DWS_CUST_ASSE_LIAB关联移除ORG_ID条件
  --   v3.0.0 2026-07-28 同步DTL：月/季/年切片接触状态按不同时间窗口独立计算
  --   v3.1.0 2026-07-30 去掉季/年统计周期切片,仅保留月度(对应v2.0.3需求变更)
  --   v3.1.1 2026-07-30 补充所有变量、字段、表别名、逻辑参数的注释
  --   v3.2.0 2026-08-04 F-05:DWS月日均AUM预计算写入TMP_ADS_POTN_MTH_AVG,两分支共用(消除重复JOIN)；
  --                       F-06:CASE WHEN达标逻辑随F-05消除重复；
  --                       F-07:删除V_END_DATE无效初始化赋值
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '潜力提升统计处理';                     -- 过程描述
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_POTN_UPGRADE_STATIS';  -- 过程名称
  V_LOG_MSG              VARCHAR(4000);                                        -- 日志消息文本
  V_LOG_FLG              INTEGER;                                              -- 日志标志(0=成功)
  V_LOG_BUTTON           INTEGER := 1;                                         -- 日志记录开关(1=启用)
  V_NO_ID                VARCHAR(10);                                          -- 当前步骤序号
  V_BGN_DATE             DATE;                                                 -- 步骤开始时间
  V_END_DATE             DATE;                                                 -- 步骤结束时间
  V_DURA_DATE            INTEGER;                                              -- 步骤耗时(秒)
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);                                          -- 三年历史清理边界(YYYYMMDD)

  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 1. 参数检查
  ------------------------------------------------------------------
  -- 1. 校验跑批日期并初始化三年历史清理边界。
  IF V_SYSDAT IS NULL
     OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')
  THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);

  ------------------------------------------------------------------
  -- 2. TMP1：清理当前数据日统计结果、三年前历史数据和物理临时表
  ------------------------------------------------------------------
  V_NO_ID := 'TMP1';
  V_BGN_DATE := SYSDATE;

  -- 2. 清理本跑批日统计结果和超过三年保留期限的历史数据,保证过程可重跑。
  DELETE FROM ADS_CUST_POTN_UPGRADE_STATIS T
   WHERE T.DATA_DATE = V_SYSDAT;

  DELETE FROM ADS_CUST_POTN_UPGRADE_STATIS T
   WHERE T.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  TRUNC_TMP('TMP_ADS_POTN_STAT_SRC');
  TRUNC_TMP('TMP_ADS_POTN_MTH_AVG');
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理当前数据日统计结果、三年前历史数据和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 3. TMP2：预计算月日均达标状态 + 展开机构和客户经理统计对象
  ------------------------------------------------------------------
  V_NO_ID := 'TMP2';
  V_BGN_DATE := SYSDATE;

  -- 3a. 预计算月日均达标状态(DWS只扫描一次,两个分支共用)
  INSERT INTO TMP_ADS_POTN_MTH_AVG (
      CUST_ID,                                                  -- 客户编号
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      MTH_AVG_QUAL_STATE                                        -- 月日均达标状态
  )
  SELECT D.CUST_ID,                                             -- 客户编号
         D.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         CASE                                                   -- 按跑批日月日均AUM判断是否达到临界等级阈值
           WHEN (D.LVL_CRIT = '03' AND NVL(M.AUM_BAL, 0) >= 50000)      -- 临界优质：月日均AUM≥5万
             OR (D.LVL_CRIT = '04' AND NVL(M.AUM_BAL, 0) >= 300000)     -- 临界财富1：月日均AUM≥30万
             OR (D.LVL_CRIT = '05' AND NVL(M.AUM_BAL, 0) >= 500000)     -- 临界财富2：月日均AUM≥50万
             OR (D.LVL_CRIT = '06' AND NVL(M.AUM_BAL, 0) >= 1000000)    -- 临界贵宾：月日均AUM≥100万
             OR (D.LVL_CRIT = '07' AND NVL(M.AUM_BAL, 0) >= 3000000)    -- 临界私行：月日均AUM≥300万
           THEN '1'                                             -- 达标
           ELSE '0'                                             -- 未达标
         END AS MTH_AVG_QUAL_STATE
    FROM ADS_CUST_POTN_UPGRADE_CUST_DTL D                       -- D：潜力提升客户明细
    LEFT JOIN DWS_CUST_ASSE_LIAB M                              -- M：当月月日均AUM(DATA_DATE=V_SYSDAT, BAL_TYPE='2')
     ON M.CUST_ID = D.CUST_ID
     AND M.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE         -- 双键关联：客户号+法人行号
     AND M.DATA_DATE = V_SYSDAT                                 -- 取跑批日数据
     AND M.BAL_TYPE = '2'                                       -- 月日均余额类型
   WHERE D.DATA_DATE = V_SYSDAT;                                -- 仅统计当天跑批产生的明细

  -- 3b. 展开机构和客户经理统计对象(JOIN预计算表,DWS不再重复扫描)
  INSERT INTO TMP_ADS_POTN_STAT_SRC (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      DATA_DATE,                                                -- 数据日期(YYYYMMDD)
      STATIS_CYCLE,                                             -- 统计周期(M=月度)
      STATIS_OBJ,                                               -- 统计对象(机构ID或客户经理岗位ID)
      LVL_CRIT,                                                 -- 临界等级(03/04/05/06/07)
      MTH_AVG_QUAL_STATE,                                       -- 月日均达标状态(1=达标,0=未达标)
      PNT_QUAL_STATE,                                           -- T-1时点达标状态(1=达标,0=未达标)
      CNTCT_STATE                                               -- 月接触状态(1=有接触,0=无接触)
  )
  -- 机构分支：将客户所属叶子机构向上展开至各级祖先机构,形成机构统计口径。
  SELECT D.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         D.DATA_DATE,                                           -- 数据日期
         D.STATIS_CYCLE,                                        -- 统计周期
         O.ANCESTOR_ORG_ID,                                     -- 祖先机构ID(作为统计对象)
         D.LVL_CRIT,                                            -- 临界等级
         NVL(MA.MTH_AVG_QUAL_STATE, '0'),                       -- 月日均达标状态(来自预计算表)
         D.QUAL_STATE,                                          -- T-1时点达标状态(直接取自明细表)
         D.CNTCT_STATE                                          -- 月接触状态(直接取自明细表)
    FROM ADS_CUST_POTN_UPGRADE_CUST_DTL D                       -- D：潜力提升客户明细
    JOIN (
          SELECT DISTINCT
                 CONNECT_BY_ROOT X.ORG_ID AS LEAF_ORG_ID,       -- 叶子机构ID(起点)
                 X.ORG_ID AS ANCESTOR_ORG_ID                    -- 祖先机构ID(向上展开的所有祖先)
            FROM DWD_SYS_ORG X                                  -- X：机构树表
           START WITH X.ORG_ID IN (
                 SELECT DISTINCT ORG_ID
                   FROM ADS_CUST_POTN_UPGRADE_CUST_DTL
                  WHERE ORG_ID IS NOT NULL                      -- 以潜力提升明细中出现的机构为起点
                )
         CONNECT BY NOCYCLE PRIOR X.SUP_ORG_ID = X.ORG_ID       -- 沿上级机构向上递归
    ) O                                                        -- O：机构层级展开结果
      ON O.LEAF_ORG_ID = D.ORG_ID                               -- 明细的叶子机构匹配展开起点的叶子机构
    LEFT JOIN TMP_ADS_POTN_MTH_AVG MA                           -- MA：预计算的月日均达标状态
     ON MA.CUST_ID = D.CUST_ID
     AND MA.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE         -- 双键关联：客户号+法人行号
   WHERE D.DATA_DATE = V_SYSDAT                                 -- 仅统计当天跑批产生的明细

  UNION ALL

  -- 客户经理分支：按管户经理岗位ID直接分组统计。
  SELECT D.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         D.DATA_DATE,                                           -- 数据日期
         D.STATIS_CYCLE,                                        -- 统计周期
         D.POST_ID,                                             -- 管户经理岗位ID(作为统计对象)
         D.LVL_CRIT,                                            -- 临界等级
         NVL(MA.MTH_AVG_QUAL_STATE, '0'),                       -- 月日均达标状态(来自预计算表)
         D.QUAL_STATE,                                          -- T-1时点达标状态
         D.CNTCT_STATE                                          -- 月接触状态
    FROM ADS_CUST_POTN_UPGRADE_CUST_DTL D                       -- D：潜力提升客户明细
    LEFT JOIN TMP_ADS_POTN_MTH_AVG MA                           -- MA：预计算的月日均达标状态
     ON MA.CUST_ID = D.CUST_ID
     AND MA.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE         -- 双键关联：客户号+法人行号
   WHERE D.POST_ID IS NOT NULL                                  -- 仅统计有管户经理的客户
     AND D.DATA_DATE = V_SYSDAT;

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP2 完成：展开机构和客户经理统计对象';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  ------------------------------------------------------------------
  -- 4. 目标表写入：按统计对象和月度周期汇总
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 4. 按统计对象、法人行、统计周期和临界等级汇总客户数、达标人数、接触人数及比例。
  INSERT INTO ADS_CUST_POTN_UPGRADE_STATIS (
      PERSN_LEGAL_BK_CODE,                                      -- 法人行号
      DATA_DATE,                                                -- 数据日期(YYYYMMDD)
      STATIS_OBJ,                                               -- 统计对象(机构ID或管户经理岗位ID)
      STATIS_CYCLE,                                             -- 统计周期(M=月度)
      LVL_CRIT,                                                 -- 临界等级(03/04/05/06/07)
      TTL_CUST_CNT,                                             -- 总客户数
      MTH_AVG_QUAL_CNT,                                         -- 月日均达标客户数
      MTH_AVG_QUAL_RATE,                                        -- 月日均达标率(%,保留2位小数)
      PNT_QUAL_CNT,                                             -- T-1时点达标客户数
      PNT_QUAL_RATE,                                            -- T-1时点达标率(%,保留2位小数)
      CNTCT_CUST_CNT,                                           -- 接触客户数
      CNTCT_RATE                                                -- 接触率(%,保留2位小数)
  )
  SELECT S.PERSN_LEGAL_BK_CODE,                                 -- 法人行号
         S.DATA_DATE,                                           -- 数据日期
         S.STATIS_OBJ,                                           -- 统计对象
         S.STATIS_CYCLE,                                        -- 统计周期
         S.LVL_CRIT,                                            -- 临界等级
         COUNT(*),                                              -- 总客户数：每个展开记录算1个统计单位
         SUM(CASE WHEN S.MTH_AVG_QUAL_STATE = '1' THEN 1 ELSE 0 END),  -- 月日均达标客户数
         CASE WHEN COUNT(*) = 0 THEN 0                          -- 月日均达标率=达标数/总数×100
              ELSE ROUND(SUM(CASE WHEN S.MTH_AVG_QUAL_STATE = '1' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2)
         END,
         SUM(CASE WHEN S.PNT_QUAL_STATE = '1' THEN 1 ELSE 0 END),      -- T-1时点达标客户数
         CASE WHEN COUNT(*) = 0 THEN 0                          -- T-1时点达标率=达标数/总数×100
              ELSE ROUND(SUM(CASE WHEN S.PNT_QUAL_STATE = '1' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2)
         END,
         SUM(CASE WHEN S.CNTCT_STATE = '1' THEN 1 ELSE 0 END),         -- 接触客户数
         CASE WHEN COUNT(*) = 0 THEN 0                          -- 接触率=接触数/总数×100
              ELSE ROUND(SUM(CASE WHEN S.CNTCT_STATE = '1' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2)
         END
    FROM TMP_ADS_POTN_STAT_SRC S                                 -- S：统计源数据(已按机构/客户经理展开)
   GROUP BY S.PERSN_LEGAL_BK_CODE,                               -- 按法人行号
            S.DATA_DATE,                                         -- 按数据日期
            S.STATIS_OBJ,                                         -- 按统计对象
            S.STATIS_CYCLE,                                      -- 按统计周期
            S.LVL_CRIT;                                          -- 按临界等级

  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第3段完成：按统计对象和月度周期汇总写入统计';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

EXCEPTION
  -- 5. 发生异常时回滚本过程事务并记录失败日志。
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_ads_cust_sleep_wake_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_sleep_wake_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：睡眠户唤醒明细
  -- 处理周期: 日
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.16.2
  -- 关联需求: REQ-CUST-008(睡眠户唤醒), REQ-CUST-028(最新唤醒口径确认)
  -- 变更记录:
  --   v2.1.0-v2.11.0: 见前续版本
  --   v2.12.0(2026-08-04):
  --     唤醒判定重构: IS_WAKE改为账户表日期驱动,新增TMP_ADS_SLEEP_WAKE_PROD
  --   v2.13.0(2026-08-04): 性能优化版
  --     O-01: 新增TMP_ADS_SLEEP_ACTIVE_TXN预聚合主动动账客户,
  --           消除[A][B]步骤中DWD_TX_ASET重复扫描
  --     O-02: 合并[B][C]步骤,[B]直接写入TMP_BASE,移除TMP_CANDIDATE
  --     O-03: [D]步骤拆分为[D1]余额+唤醒更新和[D2]接触状态更新,
  --           消除嵌套子查询LEFT JOIN,改为两个简单UPDATE
  --   v2.14.0(2026-08-04): 模板规范+性能优化
  --     F-1: [B]步骤JOIN DWS_CUST_ASSE_LIAB改为JOIN TMP_ADS_SLEEP_DWS_WAKE,
  --          消除[A0]和[B]对DWS的重复全表扫描
  --     F-2: MKT_TIME/TX_DATE函数转换(TO_DATE)改为字符串范围比较,利用索引
  --     F-3: TMP2拆分为TMP2~TMP8独立步骤,每个临时表段独立编号+日志,
  --          符合模板规则#3/#4/#5
  --     F-5: 日志消息修正: 版本号v2.11.0→v2.14.0,移除废弃[C]引用,
  --          移除多余括号
  --   v2.15.0(2026-08-05): 唤醒按当月新增持有产品业务日期判定,
  --          不再要求历史余额为0或当日余额大于0；同一法人+客户仅对应一个机构。
  --   v2.16.0(2026-08-17): 睡眠户来源切换
  --     S-1: 睡眠户身份唯一来源改为DWS_CUST_DORMANT_ACCOUT(当日快照),
  --          过程内禁止按资产/交易重算睡眠户；
  --     S-2: 月初取当日快照全量作为当月清单基数,月内取「当日快照存在且
  --          NOT EXISTS当月BASE」的新产生睡眠户追加,清单只增不减；
  --     S-3: 只做个人客户(INNER JOIN DWD_CUST_INDV_INFO)；
  --     S-4: ORG_ID仅由资产快照解析,缺失置空并预警,不兜底；
  --     S-5: TMP3(TMP_ADS_SLEEP_ACTIVE_TXN)下线；
  --     S-6: TMP4新增DORMANT客户UNION补齐分支(F-16-1)；
  --     S-7: [D1] ORG空值安全匹配(F-16-2)。
  --   v2.16.1(2026-08-17): 重构为先身份后属性(R-1)
  --     R-1: 先确定当日全部睡眠户([A]/[B]仅构建身份+状态),
  --          再按清单客户补余额/等级/名称/管户经理/机构([D1]属性补全)；
  --     R-2: TMP4(TMP_ADS_SLEEP_DWS_WAKE)下线,消除DWS_CUST_ASSE_LIAB
  --          全表扫描分支；[D1]仅按BASE客户键联查；
  --     R-3: 唤醒判定(WAKE_STATE)由TMP_ADS_SLEEP_WAKE_PROD独立全量更新,
  --          不依赖资产快照匹配,覆盖所有BASE客户且月内不可逆。
  --   v2.16.2(2026-08-17): 属性计算式重构(R-4)
  --     R-4a: TMP_ADS_SLEEP_WAKE_BASE瘦身为仅存身份(法人行+客户号)；
  --     R-4b: 删除[D1]/[D2]的UPDATE,余额/名称/等级/管户经理在第4段
  --          写入目标表时以LEFT JOIN直接计算；
  --     R-4c: 接触状态直接按当月(月初~跑批日)有效接触EXISTS判定；
  --     R-4d: 唤醒状态直接按当月(月初~跑批日)产品新增EXISTS判定。
  ------------------------------------------------------------------
  -- === 输入参数 ===
  -- V_SYSDAT: 系统跑批日期 VARCHAR(8),取值YYYYMMDD,非NULL且必须为有效日期格式。
  --           作为当日资产、交易和营销数据快照日期,不直接代表数据库当前时间。
  -- OUTCDE:   输出状态码 INTEGER OUT,0=成功,-1=异常；异常时事务回滚并记录日志。
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '睡眠户唤醒明细处理';        -- 过程描述
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_SLEEP_WAKE_DTL'; -- 过程名
  V_LOG_MSG              VARCHAR(4000);                               -- 日志消息
  V_LOG_FLG              INTEGER;                                     -- 日志标志(0正常)
  V_LOG_BUTTON           INTEGER := 1;                                -- 日志按钮标识
  V_NO_ID                VARCHAR(10);                                 -- 步骤编号
  V_BGN_DATE             DATE;                                        -- 步骤开始时间
  V_END_DATE             DATE;                                        -- 步骤结束时间
  V_DURA_DATE            INTEGER;                                     -- 步骤耗时(秒)
  V_DATA_DATE            VARCHAR2(8);                                 -- 数据日期,YYYYMMDD,等于V_SYSDAT。
  V_PREV_DAY             VARCHAR2(8);                                 -- 上一日,YYYYMMDD,由sys_fun_deal_date(V_SYSDAT,1)生成。
  V_CURR_MONTH_BEGIN     VARCHAR2(8);                                 -- 当月首日,YYYYMMDD,由sys_fun_deal_date(V_SYSDAT,9)生成。
  V_IS_MONTH_BEGIN       CHAR(1);                                     -- 月首标志,仅允许Y/N；Y时月初重置月度清单。
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);                                 -- 三年历史清理边界(参数19)
  V_SNAP_CNT             INTEGER;                                      -- DORMANT当日快照记录数(v2.16.0前置校验)
  -- 截断指定临时表
  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 步骤1: 参数校验与日期变量初始化
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 参数校验：V_SYSDAT必须为8位数字
  IF V_SYSDAT IS NULL OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$') THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_DATA_DATE       := V_SYSDAT;
  V_PREV_DAY        := sys_fun_deal_date(V_SYSDAT, 1);             -- T-1日(参数1)
  V_CURR_MONTH_BEGIN:= sys_fun_deal_date(V_SYSDAT, 9);             -- 当月首日(参数9)
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);        -- 三年历史清理边界(参数19)
  -- 判断月首日：
  --   月首日：[A]读昨日DTL作为上月末基石
  --   非月首：[A]读昨日DTL继续累积
  IF V_DATA_DATE = V_CURR_MONTH_BEGIN THEN
    V_IS_MONTH_BEGIN := 'Y';
  ELSE
    V_IS_MONTH_BEGIN := 'N';
  END IF;

  -- v2.16.0 S-1前置校验: DORMANT当日快照必须就绪,未就绪直接终止(不回退T-1)
  SELECT COUNT(*)
    INTO V_SNAP_CNT
    FROM DWS_CUST_DORMANT_ACCOUT
   WHERE DATA_DATE = V_DATA_DATE;
  IF V_SNAP_CNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20003, 'DWS_CUST_DORMANT_ACCOUT当日快照未就绪: ' || V_DATA_DATE);
  END IF;

  ------------------------------------------------------------------
  -- 步骤2: 清理当日目标数据、三年前历史数据、所有TMP临时表
  ------------------------------------------------------------------
  DELETE FROM ADS_CUST_SLEEP_WAKE_DTL D
   WHERE D.DATA_DATE = V_DATA_DATE;                                  -- 当日(支持重跑)

  DELETE FROM ADS_CUST_SLEEP_WAKE_DTL D
   WHERE D.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  TRUNC_TMP('TMP_ADS_SLEEP_WAKE_BASE');
  TRUNC_TMP('TMP_ADS_SLEEP_DWS_WAKE');                              -- v2.16.1已下线,保留清理用于对账
  TRUNC_TMP('TMP_ADS_SLEEP_CNTCT');
  TRUNC_TMP('TMP_ADS_SLEEP_WAKE_PROD');
  TRUNC_TMP('TMP_ADS_SLEEP_ACTIVE_TXN');                              -- v2.16.0已下线,保留清理用于对账
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '1 完成: 清理目标数据+TMP表; 月首=' || V_IS_MONTH_BEGIN;
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 步骤3: 预聚合 + 身份清单 + 目标表写入 (v2.16.2)
  --   '2'  预聚合当月产品新增客户 → TMP_ADS_SLEEP_WAKE_PROD(唤醒源)
  --   '3'  预计算当月已接触客户 → TMP_ADS_SLEEP_CNTCT(接触判定源)
  --   '4'  身份清单基底: 月初=DORMANT当日全量,月内=昨日DTL继承(仅客户号+法人行)
  --   '5'  当日新产生睡眠户追加(DORMANT当日增量,仅客户号+法人行)
  --   '6'  目标表写入: 属性LEFT JOIN计算 + 接触/唤醒当月窗口EXISTS判定
  --   (TMP3/TMP4/TMP8等下线步骤占位已移除,详见变更记录)
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- ================================================================
  -- [A0a] 预聚合当月产品新增客户 → TMP_ADS_SLEEP_WAKE_PROD
  --      从三张账户表按日期范围聚合有新增的客户,供[A0]步骤IS_WAKE判断。
  --      v2.12.0: 消除[A0]中三个EXISTS子查询,提升可读性和性能。
  -- ================================================================
  INSERT INTO TMP_ADS_SLEEP_WAKE_PROD (PERSN_LEGAL_BK_CODE, CUST_ID)
  SELECT DISTINCT d.PERSN_LEGAL_BK_CODE, d.CUST_ID
    FROM DWD_ACCT_DEPO d
   WHERE d.INTRI_BGN_DATE >= V_CURR_MONTH_BEGIN                          -- 定期起息日在当月范围内
     AND d.INTRI_BGN_DATE <= V_DATA_DATE
     AND d.FIX_CURNT_FLG = '1'                                           -- 定期
  UNION
  SELECT DISTINCT f.PERSN_LEGAL_BK_CODE, f.CUST_ID
    FROM DWD_ACCT_FIN f
   WHERE f.ISSU_DATE >= V_CURR_MONTH_BEGIN                               -- 理财办理日在当月范围内
     AND f.ISSU_DATE <= V_DATA_DATE
  UNION
  SELECT DISTINCT i.PERSN_LEGAL_BK_CODE, i.CUST_ID
    FROM DWD_ACCT_INSUR i
   WHERE i.LAST_TX_DATE >= V_CURR_MONTH_BEGIN                            -- 保险最近交易日在当月范围内
     AND i.LAST_TX_DATE <= V_DATA_DATE;
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '2 完成: 预聚合当月产品新增客户(定期+理财+保险)';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

  -- ================================================================
  -- [A1] 预计算当月已接触客户 → TMP_ADS_SLEEP_CNTCT
  --     当月(V_CURR_MONTH_BEGIN~V_DATA_DATE)有有效接触(MKT_TYP IN 1/2/3/4)
  --     的客户-管户经理组合,供[D]步骤LEFT JOIN判断接触状态(F-05)。
  --     v2.14.0 F-2: MKT_TIME字符串范围比较利用索引。
  -- ================================================================
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
  INSERT INTO TMP_ADS_SLEEP_CNTCT (
      PERSN_LEGAL_BK_CODE, CUST_ID, MKT_PERSN
  )
  SELECT DISTINCT r.PERSN_LEGAL_BK_CODE,                               -- 法人行号
                  r.CUST_ID,                                            -- 客户号
                  r.MKT_PERSN                                           -- 管户经理(=POST_ID)
    FROM ADS_MKT_REC_INFO r
   WHERE r.MKT_TYP IN ('1','2','3','4')                                -- 有效接触类型
     AND r.MKT_TIME IS NOT NULL
     AND r.MKT_TIME >= SUBSTR(V_CURR_MONTH_BEGIN,1,4) || '-' ||
                       SUBSTR(V_CURR_MONTH_BEGIN,5,2) || '-' ||
                       SUBSTR(V_CURR_MONTH_BEGIN,7,2)                     -- v2.14.0 F-2: 字符串范围比较利用索引
     AND r.MKT_TIME <= SUBSTR(V_DATA_DATE,1,4) || '-' ||
                       SUBSTR(V_DATA_DATE,5,2) || '-' ||
                       SUBSTR(V_DATA_DATE,7,2);
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '3 完成: 预聚合当月已接触客户';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

  -- ================================================================
  -- [A] 当日身份清单基底构建 (v2.16.2)
  --     仅获取睡眠户身份(客户号+法人行号)；属性(余额/名称/等级/管户经理)
  --     与状态(接触/唤醒)均在步骤'6'写入目标表时直接计算,不使用UPDATE。
  --     月初：DORMANT当日快照全量作为当月清单基数；
  --     月内：昨日DTL身份继承(清单只增不减)。
  --     所有睡眠户一律出自DORMANT表,过程内不再按资产/交易重算。
  -- ================================================================
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  IF V_IS_MONTH_BEGIN = 'Y' THEN
    -- 月初: DORMANT当日快照全量,仅身份
    INSERT INTO TMP_ADS_SLEEP_WAKE_BASE (PERSN_LEGAL_BK_CODE, CUST_ID)
    SELECT d.PERSN_LEGAL_BK_CODE, d.CUST_ID
      FROM DWS_CUST_DORMANT_ACCOUT d
     WHERE d.DATA_DATE = V_DATA_DATE;
  ELSE
    -- 月内: 昨日DTL身份继承(清单只增不减)
    INSERT INTO TMP_ADS_SLEEP_WAKE_BASE (PERSN_LEGAL_BK_CODE, CUST_ID)
    SELECT y.PERSN_LEGAL_BK_CODE, y.CUST_ID
      FROM ADS_CUST_SLEEP_WAKE_DTL y
     WHERE y.DATA_DATE = V_PREV_DAY
       AND y.STATIS_CYCLE = 'M';
  END IF;
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '4 完成: 身份清单基底构建(客户号+法人行); 月首=' || V_IS_MONTH_BEGIN;
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

  -- ================================================================
  -- [B] 当日新产生睡眠户追加 (v2.16.2)
  --     仅身份(客户号+法人行号)；增量=当日快照存在且NOT EXISTS当月BASE
  -- ================================================================
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
  INSERT INTO TMP_ADS_SLEEP_WAKE_BASE (PERSN_LEGAL_BK_CODE, CUST_ID)
  SELECT d.PERSN_LEGAL_BK_CODE, d.CUST_ID
    FROM DWS_CUST_DORMANT_ACCOUT d
   WHERE d.DATA_DATE = V_DATA_DATE                                   -- 当日快照
     AND NOT EXISTS (                                                -- 增量: 不在当月清单
           SELECT 1 FROM TMP_ADS_SLEEP_WAKE_BASE b
            WHERE b.CUST_ID = d.CUST_ID
              AND b.PERSN_LEGAL_BK_CODE = d.PERSN_LEGAL_BK_CODE
        );
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '5 完成: 当日新产生睡眠户身份追加';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

  -- ================================================================
  ------------------------------------------------------------------
  -- 步骤6: 目标表写入 — 身份BASE + 属性联查 + 接触/唤醒直接判定
  --   v2.16.2 R-4b/R-4c/R-4d: 不使用UPDATE；
  --   余额/名称/等级/管户经理/ORG 以LEFT JOIN直接计算(缺失按0/空)；
  --   接触 = 当月(月初~跑批日)有效接触EXISTS(TMP5预聚合)；
  --   唤醒 = 当月(月初~跑批日)产品新增EXISTS(TMP2预聚合)。
  ------------------------------------------------------------------
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CUST_SLEEP_WAKE_DTL (
      PERSN_LEGAL_BK_CODE, DATA_DATE, CUST_ID, CUST_NAME, CUST_LVL,
      DEPO_CURNT_DEPO_BAL, FIXD_DEPO_BAL, FIN_AMT, INSUR_AMT,
      CNTCT_STATE, WAKE_STATE, POST_ID, ORG_ID, STATIS_CYCLE
  )
  SELECT b.PERSN_LEGAL_BK_CODE,                                       -- 法人行号
         V_DATA_DATE,                                                  -- 数据日期
         b.CUST_ID,                                                    -- 客户号
         NVL(c.CUST_NAME, ''),                                         -- 客户名称(客户信息表)
         l.CUST_LVL,                                                   -- 客户等级(等级快照)
         NVL(w.DEPO_CURNT_DEPO_BAL, 0),                                -- 活期余额(资产快照,缺失按0)
         NVL(w.FIXD_DEPO_BAL, 0),                                      -- 定期余额
         NVL(w.FIN_BAL, 0),                                            -- 理财余额
         NVL(w.INSUR_BAL, 0),                                          -- 保险余额
         CASE WHEN EXISTS (                                            -- 接触: 当月窗口直接判定
                 SELECT 1 FROM TMP_ADS_SLEEP_CNTCT ct
                  WHERE ct.CUST_ID = b.CUST_ID
                    AND ct.PERSN_LEGAL_BK_CODE = b.PERSN_LEGAL_BK_CODE
                    AND ct.MKT_PERSN = m.MNGR_POST_ID
              ) THEN '1' ELSE '0' END AS CNTCT_STATE,
         CASE WHEN EXISTS (                                            -- 唤醒: 当月窗口直接判定
                 SELECT 1 FROM TMP_ADS_SLEEP_WAKE_PROD p
                  WHERE p.CUST_ID = b.CUST_ID
                    AND p.PERSN_LEGAL_BK_CODE = b.PERSN_LEGAL_BK_CODE
              ) THEN '1' ELSE '0' END AS WAKE_STATE,
         m.MNGR_POST_ID,                                               -- 理财管户经理
         w.ORG_ID,                                                     -- 归属机构(资产快照,可为空)
         'M'                                                           -- 统计周期(M=月度)
    FROM TMP_ADS_SLEEP_WAKE_BASE b                                    -- 身份清单(仅客户号+法人行)
    LEFT JOIN DWD_CUST_INDV_INFO c
      ON c.CUST_ID = b.CUST_ID
     AND c.PERSN_LEGAL_BK_CODE = b.PERSN_LEGAL_BK_CODE
    LEFT JOIN DWS_CUST_LVL_INFO l
      ON l.CUST_ID = b.CUST_ID
     AND l.PERSN_LEGAL_BK_CODE = b.PERSN_LEGAL_BK_CODE
     AND l.DATA_DATE = V_DATA_DATE
    LEFT JOIN DWS_CUST_ASSE_LIAB w
      ON w.CUST_ID = b.CUST_ID
     AND w.PERSN_LEGAL_BK_CODE = b.PERSN_LEGAL_BK_CODE
     AND w.DATA_DATE = V_DATA_DATE
     AND w.BAL_TYPE = '1'
    LEFT JOIN DWD_CUST_MAN m
      ON m.CUST_ID = b.CUST_ID
     AND m.PERSN_LEGAL_BK_CODE = b.PERSN_LEGAL_BK_CODE
     AND m.MNG_TYP = '1'                                              -- 仅理财管户
     AND (m.ORG_ID = w.ORG_ID OR (m.ORG_ID IS NULL AND w.ORG_ID IS NULL));
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第6段完成: 写入睡眠户唤醒明细(v2.16.2 属性计算式)';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE WHEN V_BGN_DATE IS NOT NULL AND V_END_DATE IS NOT NULL
                        THEN TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60) END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
        V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_cust_sleep_wake_statis(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_cust_sleep_wake_statis(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程：睡眠户唤醒统计
  -- 处理周期: 日
  -- 适配数据库: Kingbase Oracle 兼容模式
  -- 需求版本: v2.16.2
  -- 关联需求: REQ-CUST-008(睡眠户唤醒), REQ-CUST-028(最新唤醒口径确认)
  -- 变更记录:
  --   v2.1.0-v2.8.0: 见前续版本
  --   v2.10.0(2026-07-31): 月首先由明细过程完成上月末复核及当日合并；
  --   v2.11.0(2026-08-04): F-06: 删除V_END_DATE无效初始化；
  --                        F-09: 移除上月末数据取数条件及清理逻辑。
  --   v2.12.0(2026-08-04): O-04: CONNECT BY机构递归预物化到
  --        TMP_ADS_SLEEP_ORG_HIER临时表,消除TMP2步骤INSERT子查询内
  --        的实时递归计算,提升大机构树场景下的执行效率。
  --   v2.12.1(2026-08-04): 模板规范化
  --        F-6: 步骤编号规范化: TMP1→'1'(清理), TMP2→'TMP1'(层级+维度展开),
  --              '3'→'2'(目标表写入),同步日志消息
  --   v2.15.0(2026-08-05): 与明细过程同步采用本月新增持有产品唤醒口径；
  --          统计仅汇总当日月度明细,机构向上汇总和客户经理维度保持不变。
  --   v2.16.0(2026-08-17): 睡眠户清单来源切换至DWS_CUST_DORMANT_ACCOUT
  --          (明细过程v2.16.0)；本过程统计逻辑不变,仅版本同步。
  --          注: ORG_ID可能为空(不兜底),机构维度不包含ORG为空的客户,
  --          建议在统计前输出ORG空值占比预警。
  --   v2.16.1(2026-08-17): 明细过程重构为先身份后属性([D1]属性补全),
  --          本过程统计逻辑仍不变,仅版本同步。
  --   v2.16.2(2026-08-17): 明细过程改为属性计算式([D1]/[D2]下线,属性与
  --          接触/唤醒状态在第4段直接计算),本过程统计逻辑仍不变,仅版本同步。
  ------------------------------------------------------------------
  -- === 输入参数 ===
  -- V_SYSDAT: 系统跑批日期 VARCHAR(8),取值YYYYMMDD,非NULL且必须为有效日期格式；
  --           用于当前统计日数据聚合。
  -- OUTCDE:   输出状态码 INTEGER OUT,0=成功,-1=异常；异常时回滚并记录步骤日志。
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '睡眠户唤醒统计表';             -- 过程描述,固定值。
  V_PRC_NAME             VARCHAR(64)  := 'PRC_ADS_CUST_SLEEP_WAKE_STATIS'; -- 过程名,固定值。
  V_LOG_MSG              VARCHAR(4000);                                 -- 步骤/异常消息,最多4000字符。
  V_LOG_FLG              INTEGER;                                       -- 日志状态,0成功、-1异常。
  V_LOG_BUTTON           INTEGER := 1;                                  -- 日志按钮标识,固定为1。
  V_NO_ID                VARCHAR(10);                                   -- 步骤编号,TMP1/TMP2/3或异常步骤。
  V_BGN_DATE             DATE;                                          -- 步骤开始时间,仅用于耗时日志。
  V_END_DATE             DATE;                                          -- 步骤结束时间,仅用于耗时日志。
  V_DURA_DATE            INTEGER;                                       -- 步骤耗时,单位秒,非负整数。
  V_DATA_DATE            VARCHAR2(8);                                   -- 当前统计日期,YYYYMMDD,等于V_SYSDAT。
  V_HISTORY_CUTOFF_DATE  VARCHAR2(8);                                   -- 三年历史清理边界(参数19)

  PROCEDURE TRUNC_TMP(P_TABLE_NAME VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE ' || P_TABLE_NAME;
  END;

BEGIN
  ------------------------------------------------------------------
  -- 步骤1: 参数校验与日期初始化
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  IF V_SYSDAT IS NULL OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$') THEN
    RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');
  END IF;

  V_DATA_DATE := V_SYSDAT;
  V_HISTORY_CUTOFF_DATE := sys_fun_deal_date(V_SYSDAT, 19);         -- 三年历史清理边界(参数19)

  ------------------------------------------------------------------
  -- 步骤2: 清理当日统计、三年前历史、统计临时表
  -- F-09: 移除上月末统计清理(DTL月首已复核并写入当日,不再需要上月末数据)
  ------------------------------------------------------------------
  DELETE FROM ADS_CUST_SLEEP_WAKE_STATIS s
   WHERE s.DATA_DATE = V_DATA_DATE;

  DELETE FROM ADS_CUST_SLEEP_WAKE_STATIS s
   WHERE s.DATA_DATE < V_HISTORY_CUTOFF_DATE;

  TRUNC_TMP('TMP_ADS_SLEEP_STAT_SRC');
  TRUNC_TMP('TMP_ADS_SLEEP_ORG_HIER');                               -- v2.12.0 O-04机构递归预物化
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '1 完成: 清理统计表数据和临时表';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 步骤3: TMP1 — 预物化机构层级 + 展开统计维度
  --   [O-04] 预物化CONNECT BY机构递归 → TMP_ADS_SLEEP_ORG_HIER
  --   展开: 机构维度(JOIN预物化表) + 客户经理维度(UNION ALL)
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- ================================================================
  -- [O-04] 预物化机构层级: 从DTL叶子机构递归找所有祖先
  -- ================================================================
  INSERT INTO TMP_ADS_SLEEP_ORG_HIER (LEAF_ORG_ID, ANCESTOR_ORG_ID)
  SELECT DISTINCT
         CONNECT_BY_ROOT o.ORG_ID AS LEAF_ORG_ID,
         o.ORG_ID AS ANCESTOR_ORG_ID
    FROM DWD_SYS_ORG o
   START WITH o.ORG_ID IN (
         SELECT DISTINCT d1.ORG_ID
           FROM ADS_CUST_SLEEP_WAKE_DTL d1
          WHERE d1.DATA_DATE = V_DATA_DATE
            AND d1.ORG_ID IS NOT NULL
   )
 CONNECT BY NOCYCLE PRIOR o.SUP_ORG_ID = o.ORG_ID;
  COMMIT;

  INSERT INTO TMP_ADS_SLEEP_STAT_SRC (
      PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_CYCLE, STATIS_OBJ,
      CNTCT_STATE, WAKE_STATE
  )
  -- 维度1: 机构递归向上汇总 (JOIN预物化表)
  SELECT d.PERSN_LEGAL_BK_CODE,                                       -- 法人行号
         d.DATA_DATE,                                                  -- 数据日期
         d.STATIS_CYCLE,                                               -- 统计周期
         o.ANCESTOR_ORG_ID,                                            -- 统计对象=层级机构
         d.CNTCT_STATE,                                                -- 接触状态
         d.WAKE_STATE                                                  -- 唤醒状态
    FROM ADS_CUST_SLEEP_WAKE_DTL d                                     -- 明细表
    JOIN TMP_ADS_SLEEP_ORG_HIER o                                      -- v2.12.0 O-04: 预物化层级表
      ON o.LEAF_ORG_ID = d.ORG_ID
   WHERE d.DATA_DATE = V_DATA_DATE

  UNION ALL

  -- 维度2: 客户经理维度
  SELECT d.PERSN_LEGAL_BK_CODE,                                       -- 法人行号
         d.DATA_DATE,                                                  -- 数据日期
         d.STATIS_CYCLE,                                               -- 统计周期
         d.POST_ID,                                                    -- 统计对象=客户经理编号
         d.CNTCT_STATE,                                                -- 接触状态
         d.WAKE_STATE                                                  -- 唤醒状态
    FROM ADS_CUST_SLEEP_WAKE_DTL d                                     -- 明细表
   WHERE d.DATA_DATE = V_DATA_DATE                                     -- F-09: 仅取当日数据
     AND d.POST_ID IS NOT NULL;
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '1 完成: 机构递归+客户经理维度展开';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 步骤4: 目标表写入 — 按统计对象聚合
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO ADS_CUST_SLEEP_WAKE_STATIS (
      PERSN_LEGAL_BK_CODE, DATA_DATE, STATIS_OBJ, STATIS_CYCLE,
      CUST_CNT, CNTCT_CUST_CNT, CNTCT_RATE,
      WAKE_CUST_CNT, WAKE_RATE
  )
  SELECT s.PERSN_LEGAL_BK_CODE,                                       -- 法人行号
         s.DATA_DATE,                                                  -- 数据日期
         s.STATIS_OBJ,                                                 -- 统计对象
         s.STATIS_CYCLE,                                               -- 统计周期
         COUNT(*) AS CUST_CNT,                                         -- 睡眠客户总数
         SUM(CASE WHEN s.CNTCT_STATE='1' THEN 1 ELSE 0 END) AS CNTCT, -- 已接触数
         CASE WHEN COUNT(*)=0 THEN 0
              ELSE ROUND(SUM(CASE WHEN s.CNTCT_STATE='1' THEN 1 ELSE 0 END)/COUNT(*)*100,2)
         END AS CNTCT_RATE,                                            -- 接触率
         SUM(CASE WHEN s.WAKE_STATE='1' THEN 1 ELSE 0 END) AS WAKE,  -- 已唤醒数
         CASE WHEN COUNT(*)=0 THEN 0
              ELSE ROUND(SUM(CASE WHEN s.WAKE_STATE='1' THEN 1 ELSE 0 END)/COUNT(*)*100,2)
         END AS WAKE_RATE                                              -- 唤醒率
    FROM TMP_ADS_SLEEP_STAT_SRC s
   GROUP BY s.PERSN_LEGAL_BK_CODE, s.DATA_DATE, s.STATIS_OBJ, s.STATIS_CYCLE;
  COMMIT;

  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := '第2段完成: 写入睡眠户唤醒统计(v2.16.2 来源DORMANT口径)';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
      V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE WHEN V_BGN_DATE IS NOT NULL AND V_END_DATE IS NOT NULL
                        THEN TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60) END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,
        V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_mkt_salon_act_statis(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_mkt_salon_act_statis(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 沙龙活动客户AUM余额汇总
  -- 作业编号: PRC_ADS_MKT_SALON_ACT_STATIS
  -- 处理周期: 每日
  -- 来源表: DWD_SALON_CUST_DTL
			DWS_CUST_ASSE_LIAB
  -- 目标表: PRC_ADS_MKT_SALON_ACT_STATIS
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-贷款余额';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_MKT_SALON_ACT_STATIS';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_MKT_SALON_ACT_STATIS';  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2. 统计沙龙活动客户AUM余额汇总
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_MKT_SALON_ACT_STATIS(
   	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  ACT_ID  , -- 沙龙活动ID
      AUM_BAL , -- AUM余额
	  DEPO_BAL , -- 存款余额
	  FIN_BAL , -- 理财余额
	  INSUR_BAL --保险余额
   )
   SELECT 
   	  B.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE , -- 法人行号
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.ACT_ID AS ACT_ID  , -- 沙龙活动ID
      SUM(B.AUM_BAL) AS AUM_BAL , -- AUM余额
	  SUM(B.DEPO_BAL) AS DEPO_BAL , -- 存款余额
	  SUM(FIN_BAL) AS FIN_BAL , -- 理财余额
	  SUM(INSUR_BAL) AS INSUR_BAL --保险余额
   FROM DWD_SALON_CUST_DTL A 
  INNER JOIN DWS_CUST_ASSE_LIAB B 
     ON A.CORE_CUST_ID = B.CUST_ID 
    AND B.BAL_TYPE  = '1' --余额
    AND B.data_date  = V_SYSDAT
  GROUP BY B.PERSN_LEGAL_BK_CODE,A.ACT_ID
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步统计沙龙活动客户AUM余额汇总数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_perf_battle_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_perf_battle_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 业绩战报明细表
  -- 存储过程编号：PRC_ADS_PERF_BATTLE_DTL
  -- 处理周期：日
  -- 过程描述：根据 ADS 数据模型映射生成
  -- 来源表：DWD_ACCT_DEPO(存款账户信息表)；DWD_ACCT_FIN(理财账户信息表)；DWD_ACCT_INSUR(保险账户信息表)；DWD_ACCT_LOAN(保险账户信息表)；DWD_CUST_INDV_INFO(客户基本信息表)；DWD_CUST_MAN(客户管户关系)；DWS_CUST_LVL_INFO(客户等级)
  -- 目标表：ADS_PERF_BATTLE_DTL
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '业绩战报明细表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_PERF_BATTLE_DTL';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);


BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;



  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  DELETE FROM ADS_PERF_BATTLE_DTL WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：业绩战报明细汇总
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：业绩战报明细汇总
  INSERT INTO ADS_PERF_BATTLE_DTL (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      ORG_ID,
      POST_ID,
      DEPO_SALE_AMT,
      FIN_SALE_AMT,
      INSUR_SALE_AMT,
      LOAN_SALE_AMT
  )
  SELECT
         T.DATA_DATE                   AS DATA_DATE             , -- 数据日期
         T.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE   , -- 法人行号
         T.CUST_ID                     AS CUST_ID               , -- 客户编号
         MAX(T.CUST_NAME)              AS CUST_NAME             , -- 客户名称
         MAX(T.ORG_ID)                 AS ORG_ID                , -- 管户机构
         MAX(T.POST_ID)                AS POST_ID               , -- 管户经理
         SUM(NVL(T.DEPO_SALE_AMT, 0))  AS DEPO_SALE_AMT         , -- 存款销量
         SUM(NVL(T.FIN_SALE_AMT, 0))   AS FIN_SALE_AMT          , -- 理财销量
         SUM(NVL(T.INSUR_SALE_AMT, 0)) AS INSUR_SALE_AMT        , -- 保险销量
         SUM(NVL(T.LOAN_SALE_AMT, 0))  AS LOAN_SALE_AMT          -- 贷款销量
    FROM (
          -- 存款销量
          SELECT
                 V_SYSDAT                AS DATA_DATE            , -- 数据日期
                 T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID              AS CUST_ID              , -- 客户编号
                 T2.CUST_NAME            AS CUST_NAME            , -- 客户名称
                 T4.ORG_ID               AS ORG_ID               , -- 管户机构
                 T3.MNGR_POST_ID         AS POST_ID              , -- 管户经理
                 SUM(T1.DEPO_BAL)        AS DEPO_SALE_AMT        , -- 存款销量
                 0                       AS FIN_SALE_AMT         , -- 理财销量
                 0                       AS INSUR_SALE_AMT       , -- 保险销量
                 0                       AS LOAN_SALE_AMT         -- 贷款销量
      FROM DWD_ACCT_DEPO T1 -- 存款账户信息表
      LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
        ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWD_CUST_MAN T3 -- 客户管户关系
        ON T1.CUST_ID = T3.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T3.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWS_CUST_LVL_INFO T4 -- 客户等级
        ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
     WHERE T1.DEPO_BAL <> 0
         GROUP BY V_SYSDAT, T1.PERSN_LEGAL_BK_CODE, T1.CUST_ID, T2.CUST_NAME, T4.ORG_ID, T3.MNGR_POST_ID
          UNION ALL
          -- 理财销量
          SELECT
                 V_SYSDAT                AS DATA_DATE            , -- 数据日期
                 T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID              AS CUST_ID              , -- 客户编号
                 T2.CUST_NAME            AS CUST_NAME            , -- 客户名称
                 T4.ORG_ID               AS ORG_ID               , -- 管户机构
                 T3.MNGR_POST_ID         AS POST_ID              , -- 管户经理
                 0                       AS DEPO_SALE_AMT        , -- 存款销量
                 T1.CFM_AMT              AS FIN_SALE_AMT         , -- 理财销量
                 0                       AS INSUR_SALE_AMT       , -- 保险销量
                 0                       AS LOAN_SALE_AMT         -- 贷款销量
      FROM DWD_ACCT_FIN T1 -- 理财账户信息表
      LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
        ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWD_CUST_MAN T3 -- 客户管户关系
        ON T1.CUST_ID = T3.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T3.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWS_CUST_LVL_INFO T4 -- 客户等级
        ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
     WHERE T1.CFM_AMT <> 0
          UNION ALL
          -- 保险销量
          SELECT
                 V_SYSDAT                AS DATA_DATE            , -- 数据日期
                 T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID              AS CUST_ID              , -- 客户编号
                 T2.CUST_NAME            AS CUST_NAME            , -- 客户名称
                 T4.ORG_ID               AS ORG_ID               , -- 管户机构
                 T3.MNGR_POST_ID         AS POST_ID              , -- 管户经理
                 0                       AS DEPO_SALE_AMT        , -- 存款销量
                 0                       AS FIN_SALE_AMT         , -- 理财销量
                 T1.INSUR_AMT            AS INSUR_SALE_AMT       , -- 保险销量
                 0                       AS LOAN_SALE_AMT         -- 贷款销量
      FROM DWD_ACCT_INSUR T1 -- 保险账户信息表
      LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
        ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWD_CUST_MAN T3 -- 客户管户关系
        ON T1.CUST_ID = T3.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T3.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWS_CUST_LVL_INFO T4 -- 客户等级
        ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
     WHERE T1.TX_DATE = V_SYSDAT AND T1.INSUR_AMT <> 0
          UNION ALL
          -- 贷款销量
          SELECT
                 V_SYSDAT                AS DATA_DATE            , -- 数据日期
                 T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID              AS CUST_ID              , -- 客户编号
                 T2.CUST_NAME            AS CUST_NAME            , -- 客户名称
                 T4.ORG_ID               AS ORG_ID               , -- 管户机构
                 T3.MNGR_POST_ID         AS POST_ID              , -- 管户经理
                 0                       AS DEPO_SALE_AMT        , -- 存款销量
                 0                       AS FIN_SALE_AMT         , -- 理财销量
                 0                       AS INSUR_SALE_AMT       , -- 保险销量
                 T1.LOAN_ISSU_AMT        AS LOAN_SALE_AMT         -- 贷款销量
      FROM DWD_ACCT_LOAN T1 -- 保险账户信息表
      LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
        ON T1.CUST_ID = T2.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWD_CUST_MAN T3 -- 客户管户关系
        ON T1.CUST_ID = T3.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T3.PERSN_LEGAL_BK_CODE
      LEFT JOIN DWS_CUST_LVL_INFO T4 -- 客户等级
        ON T1.CUST_ID = T4.CUST_ID AND T1.PERSN_LEGAL_BK_CODE = T4.PERSN_LEGAL_BK_CODE
     WHERE T1.LOAN_ISSU_DATE = V_SYSDAT AND T1.LOAN_ISSU_AMT <> 0
         ) T
   GROUP BY T.DATA_DATE, T.PERSN_LEGAL_BK_CODE, T.CUST_ID;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：业绩战报明细汇总';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_perf_battle_rep(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_perf_battle_rep(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 业绩战报统计表
  -- 存储过程编号：PRC_ADS_PERF_BATTLE_REP
  -- 处理周期：日
  -- 过程描述：根据 ADS_PERF_BATTLE_DTL 按客户经理、机构和统计周期汇总生成
  -- 来源表：ADS_PERF_BATTLE_DTL(业绩战报明细表)
  -- 目标表：TMP_ADS_PERF_BATTLE_REP；ADS_PERF_BATTLE_REP
  -- author :
  -- date   ： 2026-08-04
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '业绩战报统计表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_ADS_PERF_BATTLE_REP';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_MTH_BGN              VARCHAR(8);
  V_QTR_BGN              VARCHAR(8);
  V_YEAR_BGN             VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 计算月初、季初、年初日期,用于月/季/年统计周期汇总
  V_MTH_BGN  := TO_CHAR(TRUNC(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'MM'), 'yyyymmdd');
  V_QTR_BGN  := TO_CHAR(TRUNC(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'Q'), 'yyyymmdd');
  V_YEAR_BGN := TO_CHAR(TRUNC(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'YYYY'), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_PERF_BATTLE_REP';
  DELETE FROM ADS_PERF_BATTLE_REP WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：客户经理业绩统计入临时表
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：客户经理业绩统计入临时表
  INSERT INTO TMP_ADS_PERF_BATTLE_REP (
      DATA_DATE,
      STATIS_OBJ,
      STATIS_CYCLE,
      CUST_CNT,
      DEPO_SALE_AMT,
      FIN_SALE_AMT,
      INSUR_SALE_AMT,
      LOAN_SALE_AMT
  )
  SELECT
         V_SYSDAT                         AS DATA_DATE,       -- 数据日期
         '1'                              AS STATIS_OBJ,      -- 统计对象：客户经理
         T.STATIS_CYCLE                   AS STATIS_CYCLE,    -- 统计周期：M-月,Q-季,Y-年
         COUNT(DISTINCT T.CUST_ID)        AS CUST_CNT,        -- 客户数
         SUM(T.DEPO_SALE_AMT)             AS DEPO_SALE_AMT,   -- 存款销量
         SUM(T.FIN_SALE_AMT)              AS FIN_SALE_AMT,    -- 理财销量
         SUM(T.INSUR_SALE_AMT)            AS INSUR_SALE_AMT,  -- 保险销量
         SUM(T.LOAN_SALE_AMT)             AS LOAN_SALE_AMT    -- 贷款销量
    FROM (
          -- 客户经理-月：按客户经理和客户去重后统计本月累计业绩
          SELECT 'M' AS STATIS_CYCLE, -- 统计周期：月
                 POST_ID,             -- 管户经理
                 CUST_ID,             -- 客户编号
                 SUM(NVL(DEPO_SALE_AMT, 0))  AS DEPO_SALE_AMT,   -- 存款销量
                 SUM(NVL(FIN_SALE_AMT, 0))   AS FIN_SALE_AMT,    -- 理财销量
                 SUM(NVL(INSUR_SALE_AMT, 0)) AS INSUR_SALE_AMT,  -- 保险销量
                 SUM(NVL(LOAN_SALE_AMT, 0))  AS LOAN_SALE_AMT    -- 贷款销量
            FROM ADS_PERF_BATTLE_DTL -- 业绩战报明细表
           WHERE DATA_DATE BETWEEN V_MTH_BGN AND V_SYSDAT
           GROUP BY POST_ID, CUST_ID
          UNION ALL
          -- 客户经理-季：按客户经理和客户去重后统计本季累计业绩
          SELECT 'Q' AS STATIS_CYCLE, -- 统计周期：季
                 POST_ID,             -- 管户经理
                 CUST_ID,             -- 客户编号
                 SUM(NVL(DEPO_SALE_AMT, 0))  AS DEPO_SALE_AMT,   -- 存款销量
                 SUM(NVL(FIN_SALE_AMT, 0))   AS FIN_SALE_AMT,    -- 理财销量
                 SUM(NVL(INSUR_SALE_AMT, 0)) AS INSUR_SALE_AMT,  -- 保险销量
                 SUM(NVL(LOAN_SALE_AMT, 0))  AS LOAN_SALE_AMT    -- 贷款销量
            FROM ADS_PERF_BATTLE_DTL -- 业绩战报明细表
           WHERE DATA_DATE BETWEEN V_QTR_BGN AND V_SYSDAT
           GROUP BY POST_ID, CUST_ID
          UNION ALL
          -- 客户经理-年：按客户经理和客户去重后统计本年累计业绩
          SELECT 'Y' AS STATIS_CYCLE, -- 统计周期：年
                 POST_ID,             -- 管户经理
                 CUST_ID,             -- 客户编号
                 SUM(NVL(DEPO_SALE_AMT, 0))  AS DEPO_SALE_AMT,   -- 存款销量
                 SUM(NVL(FIN_SALE_AMT, 0))   AS FIN_SALE_AMT,    -- 理财销量
                 SUM(NVL(INSUR_SALE_AMT, 0)) AS INSUR_SALE_AMT,  -- 保险销量
                 SUM(NVL(LOAN_SALE_AMT, 0))  AS LOAN_SALE_AMT    -- 贷款销量
            FROM ADS_PERF_BATTLE_DTL -- 业绩战报明细表
           WHERE DATA_DATE BETWEEN V_YEAR_BGN AND V_SYSDAT
           GROUP BY POST_ID, CUST_ID
         ) T
   GROUP BY T.STATIS_CYCLE;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：客户经理业绩统计入临时表';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：机构业绩统计入临时表
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：机构业绩统计入临时表
  INSERT INTO TMP_ADS_PERF_BATTLE_REP (
      DATA_DATE,
      STATIS_OBJ,
      STATIS_CYCLE,
      CUST_CNT,
      DEPO_SALE_AMT,
      FIN_SALE_AMT,
      INSUR_SALE_AMT,
      LOAN_SALE_AMT
  )
  SELECT
         V_SYSDAT                         AS DATA_DATE,       -- 数据日期
         '2'                              AS STATIS_OBJ,      -- 统计对象：机构
         T.STATIS_CYCLE                   AS STATIS_CYCLE,    -- 统计周期：M-月,Q-季,Y-年
         COUNT(DISTINCT T.CUST_ID)        AS CUST_CNT,        -- 客户数
         SUM(T.DEPO_SALE_AMT)             AS DEPO_SALE_AMT,   -- 存款销量
         SUM(T.FIN_SALE_AMT)              AS FIN_SALE_AMT,    -- 理财销量
         SUM(T.INSUR_SALE_AMT)            AS INSUR_SALE_AMT,  -- 保险销量
         SUM(T.LOAN_SALE_AMT)             AS LOAN_SALE_AMT    -- 贷款销量
    FROM (
          -- 机构-月：按机构和客户去重后统计本月累计业绩
          SELECT 'M' AS STATIS_CYCLE, -- 统计周期：月
                 ORG_ID,              -- 管户机构
                 CUST_ID,             -- 客户编号
                 SUM(NVL(DEPO_SALE_AMT, 0))  AS DEPO_SALE_AMT,   -- 存款销量
                 SUM(NVL(FIN_SALE_AMT, 0))   AS FIN_SALE_AMT,    -- 理财销量
                 SUM(NVL(INSUR_SALE_AMT, 0)) AS INSUR_SALE_AMT,  -- 保险销量
                 SUM(NVL(LOAN_SALE_AMT, 0))  AS LOAN_SALE_AMT    -- 贷款销量
            FROM ADS_PERF_BATTLE_DTL -- 业绩战报明细表
           WHERE DATA_DATE BETWEEN V_MTH_BGN AND V_SYSDAT
           GROUP BY ORG_ID, CUST_ID
          UNION ALL
          -- 机构-季：按机构和客户去重后统计本季累计业绩
          SELECT 'Q' AS STATIS_CYCLE, -- 统计周期：季
                 ORG_ID,              -- 管户机构
                 CUST_ID,             -- 客户编号
                 SUM(NVL(DEPO_SALE_AMT, 0))  AS DEPO_SALE_AMT,   -- 存款销量
                 SUM(NVL(FIN_SALE_AMT, 0))   AS FIN_SALE_AMT,    -- 理财销量
                 SUM(NVL(INSUR_SALE_AMT, 0)) AS INSUR_SALE_AMT,  -- 保险销量
                 SUM(NVL(LOAN_SALE_AMT, 0))  AS LOAN_SALE_AMT    -- 贷款销量
            FROM ADS_PERF_BATTLE_DTL -- 业绩战报明细表
           WHERE DATA_DATE BETWEEN V_QTR_BGN AND V_SYSDAT
           GROUP BY ORG_ID, CUST_ID
          UNION ALL
          -- 机构-年：按机构和客户去重后统计本年累计业绩
          SELECT 'Y' AS STATIS_CYCLE, -- 统计周期：年
                 ORG_ID,              -- 管户机构
                 CUST_ID,             -- 客户编号
                 SUM(NVL(DEPO_SALE_AMT, 0))  AS DEPO_SALE_AMT,   -- 存款销量
                 SUM(NVL(FIN_SALE_AMT, 0))   AS FIN_SALE_AMT,    -- 理财销量
                 SUM(NVL(INSUR_SALE_AMT, 0)) AS INSUR_SALE_AMT,  -- 保险销量
                 SUM(NVL(LOAN_SALE_AMT, 0))  AS LOAN_SALE_AMT    -- 贷款销量
            FROM ADS_PERF_BATTLE_DTL -- 业绩战报明细表
           WHERE DATA_DATE BETWEEN V_YEAR_BGN AND V_SYSDAT
           GROUP BY ORG_ID, CUST_ID
         ) T
   GROUP BY T.STATIS_CYCLE;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：机构业绩统计入临时表';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：临时表汇总写入结果表
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：临时表汇总写入结果表
  INSERT INTO ADS_PERF_BATTLE_REP (
      DATA_DATE,
      STATIS_OBJ,
      STATIS_CYCLE,
      CUST_CNT,
      DEPO_SALE_AMT,
      FIN_SALE_AMT,
      INSUR_SALE_AMT,
      LOAN_SALE_AMT
  )
  SELECT
         T.DATA_DATE                       AS DATA_DATE,       -- 数据日期
         T.STATIS_OBJ                      AS STATIS_OBJ,      -- 统计对象：1-客户经理,2-机构
         T.STATIS_CYCLE                    AS STATIS_CYCLE,    -- 统计周期：M-月,Q-季,Y-年
         SUM(T.CUST_CNT)                   AS CUST_CNT,        -- 客户数
         SUM(T.DEPO_SALE_AMT)              AS DEPO_SALE_AMT,   -- 存款销量
         SUM(T.FIN_SALE_AMT)               AS FIN_SALE_AMT,    -- 理财销量
         SUM(T.INSUR_SALE_AMT)             AS INSUR_SALE_AMT,  -- 保险销量
         SUM(T.LOAN_SALE_AMT)              AS LOAN_SALE_AMT    -- 贷款销量
    FROM TMP_ADS_PERF_BATTLE_REP T -- 业绩战报统计表_临时汇总表
   GROUP BY T.DATA_DATE, T.STATIS_OBJ, T.STATIS_CYCLE;

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：临时表汇总写入结果表';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_report_0001(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_report_0001(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /* 作业名称: 客户分级数据报表
  -- 作业编号: PRC_ADS_REPORT_0001
  -- 处理周期: 每月末
  -- 来源表: DWS_CUST_LVL_INFO
   	         DWS_CUST_ASSE_LIAB
  			DWD_SYS_ORG
  -- 目标表: ADS_REPORT_0001
  -- author：张方涛
  -- create_date：2026-08-21
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户分级数据报表';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_REPORT_0001';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_CNT			INTEGER;
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  IF V_SYSDAT = TO_CHAR(LAST_DAY(TO_DATE(V_SYSDAT,'YYYY/MM/DD')),'YYYYMMDD') THEN
  ------------------------------------------------------------------
  -- 1. 删除目标表当期数据数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  SELECT COUNT(1) INTO V_CNT FROM ADS_REPORT_0001 WHERE DATA_DATE = V_SYSDAT;
  IF V_CNT <> 0 THEN 
  DELETE FROM ADS_REPORT_0001 WHERE DATA_DATE = V_SYSDAT;
  COMMIT;
  END IF;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步删除目标表当期数据数据完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 2 客户分级指标数据插入目标表
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;  
   INSERT INTO ADS_REPORT_0001(
   	   DATA_DATE , --数据日期
   	   BLNG_BRCH, --所属分行
	   BLNG_BRCH_SUB,--所属支行
	   BLNG_BRCH_NET, --所属网点
	   ORG_PATH, --机构路径
	   CUST_LVL, --客户层级
	   CUST_CNT, --客户数
	   AUM_BAL,--AUM余额
	   AUM_MTH_AVG, --AUM月日均
	   COMN_FIXD_BAL,--普通定期余额
	   LEHUI_BAL,--乐慧存余额
	   LARGEDP_BAL, --大额存单余额
	   FIXD_BAL, --定期存款余额合计
	   DEPO_CURNT_DEPO_BAL, --活期存款余额
	   DEOP_BAL, --存款余额合计
	   BIZ_SELF_FIN_BAL, --自营理财余额
	   PROXY_SELL_FIN_BAL, --代销理财余额
	   FIN_BAL,--理财余额合计
	   INSUR_BAL, --保险余额
	   LOAN_BAL --贷款余额
   )
   SELECT V_SYSDAT AS DATA_DATE,--数据日期
          NVL(ORG1.SUP_ORG_ID,ORG1.SUP_ORG_ID) AS BLNG_BRCH,--所属分行
	      ORG1.SUP_ORG_ID AS BLNG_BRCH_SUB,--所属支行
	   	  T.ORG_ID AS BLNG_BRCH_NET,--所属网点
	   	  ORG1.ORG_PATH AS ORG_PATH, --机构路径
	   	  T.CUST_LVL AS CUST_LVL,--客户层级
	      COUNT(1) AS CUST_CNT,--客户数
	      SUM(NVL(T1.AUM_BAL,0)) AS AUM_BAL,--AUM余额
	      SUM(NVL(T2.AUM_BAL,0)) AS AUM_MTH_AVG,--AUM月日均
	      SUM(NVL(T1.FIXD_DEPO_BAL,0)) AS COMN_FIXD_BAL,--普通定期余额
	      SUM(NVL(T1.LEHUI_BAL,0)) AS LEHUI_BAL,--乐慧存余额
	      SUM(NVL(T1.LARGEDP_BAL,0)) AS LARGEDP_BAL, --大额存单余额
	      SUM(NVL(T1.FIXD_DEPO_BAL,0) + NVL(T1.LEHUI_BAL,0) + NVL(T1.LARGEDP_BAL,0)) AS FIXD_BAL,--定期存款余额合计
	      SUM(NVL(T1.DEPO_CURNT_DEPO_BAL,0)) AS DEPO_CURNT_DEPO_BAL,--活期存款余额
	      SUM(NVL(T1.FIXD_DEPO_BAL,0) + NVL(T1.LEHUI_BAL,0) + NVL(T1.LARGEDP_BAL,0) + NVL(T1.DEPO_CURNT_DEPO_BAL,0)) AS DEOP_BAL,--存款余额合计
	      SUM(NVL(T1.CLOSE_SELF_FIN_BAL,0) + NVL(T1.OPEN_SELF_FIN_BAL,0)) AS BIZ_SELF_FIN_BAL,--自营理财余额
	      SUM(NVL(T1.CLOSE_AGEN_FIN_BAL,0) + NVL(T1.OPEN_AGEN_FIN_BAL,0)) AS PROXY_SELL_FIN_BAL,--代销理财余额
	      SUM(NVL(T1.CLOSE_SELF_FIN_BAL,0) + NVL(T1.OPEN_SELF_FIN_BAL,0) + NVL(T1.CLOSE_AGEN_FIN_BAL,0) + NVL(T1.OPEN_AGEN_FIN_BAL,0)) AS FIN_BAL,--理财余额合计
	      SUM(NVL(T1.INSUR_BAL,0)) AS INSUR_BAL,--保险余额
	      SUM(NVL(T1.LOAN_BAL,0)) AS LOAN_BAL --贷款余额
 FROM DWS_CUST_LVL_INFO T 
LEFT JOIN DWS_CUST_ASSE_LIAB T1 
   ON T.CUST_ID = T1.CUST_ID 
  AND T.PERSN_LEGAL_BK_CODE = T1.PERSN_LEGAL_BK_CODE
  AND T1.BAL_TYPE = '1' -- 余额
  AND T1.DATA_DATE = V_SYSDAT
LEFT JOIN DWS_CUST_ASSE_LIAB T2 
   ON T.CUST_ID = T2.CUST_ID 
  AND T.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE
  AND T2.BAL_TYPE = '2' -- 月日均
  AND T2.DATA_DATE = V_SYSDAT
INNER JOIN DWD_SYS_ORG ORG1
   ON T.ORG_ID = ORG1.ORG_ID
  AND T.PERSN_LEGAL_BK_CODE = ORG1.PERSN_LEGAL_BK_CODE
 LEFT JOIN DWD_SYS_ORG ORG2
  ON ORG1.SUP_ORG_ID = ORG2.ORG_ID
 AND ORG1.PERSN_LEGAL_BK_CODE = ORG2.PERSN_LEGAL_BK_CODE
WHERE T."DATA_DATE"  = V_SYSDAT
GROUP BY NVL(ORG1.SUP_ORG_ID,ORG1.SUP_ORG_ID),
	     ORG1.SUP_ORG_ID,
	     T.ORG_ID,
	     ORG1.ORG_PATH,
	     T.CUST_LVL;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步客户分级指标数据插入目标表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  END IF;
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /* 作业名称: 汇总所有指标数据到结果表
  -- 作业编号: PRC_ADS_STAT_INDX_DATA
  -- 处理周期: 每日
  -- 来源表: ADS_STAT_INDX_DATA_INDX_0001~ADS_STAT_INDX_DATA_INDX_0083
  -- 目标表: ADS_STAT_INDX_DATA,ADS_STAT_INDX_DATA_HIS
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '汇总所有指标数据到结果表';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  V_ITEM		INTEGER;
  V_ITEM_CODE 	VARCHAR(4);
  V_PROCEDURE_NAME	VARCHAR(50);
  V_SQL 		VARCHAR(2000);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA';
  DELETE FROM ADS_STAT_INDX_DATA_HIS T WHERE T.DATA_DATE = V_SYSDAT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空目标表数据完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 2 将各个指标的表循环插入结果表
  ------------------------------------------------------------------
  V_ITEM := 1;
  WHILE V_ITEM <= 45 LOOP 
  V_ITEM_CODE = LPAD(V_ITEM,4,'0');
  V_PROCEDURE_NAME := 'ADS_STAT_INDX_DATA_INDX_'||V_ITEM_CODE;
  V_SQL := 'INSERT INTO ADS_STAT_INDX_DATA(
   	  				INDX_CODE , -- 指标编码
	  				DATA_BLNG , -- 数据归属
	  				STATIS_DIM  , -- 统计维度
      				STATIS_CALIB , -- 统计口径
	  				CURNT_VAL , -- 本期值
	  				TERM_LAST_VAL , -- 上期值
	  				MTH_END_VAL , -- 月末值
	  				YR_BGN_VAL , -- 年初值
	  				DATA_DATE , -- 数据日期
	  				PERSN_LEGAL_BK_CODE -- 法人行号
   					)
   			SELECT INDX_CODE , -- 指标编码
	  				DATA_BLNG , -- 数据归属
	  				STATIS_DIM  , -- 统计维度
      				STATIS_CALIB , -- 统计口径
	  				CURNT_VAL , -- 本期值
	  				TERM_LAST_VAL , -- 上期值
	  				MTH_END_VAL , -- 月末值
	  				YR_BGN_VAL , -- 年初值
	  				DATA_DATE , -- 数据日期
	  				PERSN_LEGAL_BK_CODE -- 法人行号
   			   FROM '||V_PROCEDURE_NAME;
   EXECUTE IMMEDIATE V_SQL;
   COMMIT;
   V_ITEM = V_ITEM + 1;
   END LOOP;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步将各个指标的表循环插入结果表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3 将ADS_STAT_INDX_DATA表的数据插入ADS_STAT_INDX_DATA_HIS表中
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
  INSERT INTO ADS_STAT_INDX_DATA(
   	  				INDX_CODE , -- 指标编码
	  				DATA_BLNG , -- 数据归属
	  				STATIS_DIM  , -- 统计维度
      				STATIS_CALIB , -- 统计口径
	  				CURNT_VAL , -- 本期值
	  				TERM_LAST_VAL , -- 上期值
	  				MTH_END_VAL , -- 月末值
	  				YR_BGN_VAL , -- 年初值
	  				DATA_DATE , -- 数据日期
	  				PERSN_LEGAL_BK_CODE -- 法人行号
   					)
   SELECT INDX_CODE , -- 指标编码
	  	  DATA_BLNG , -- 数据归属
	  	  STATIS_DIM  , -- 统计维度
      	  STATIS_CALIB , -- 统计口径
	  	  CURNT_VAL , -- 本期值
	  	  TERM_LAST_VAL , -- 上期值
	  	  MTH_END_VAL , -- 月末值
	  	  YR_BGN_VAL , -- 年初值
	  	  DATA_DATE , -- 数据日期
	  	  PERSN_LEGAL_BK_CODE -- 法人行号			
   	 FROM ADS_STAT_INDX_DATA
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3步将ADS_STAT_INDX_DATA表的数据插入ADS_STAT_INDX_DATA_HIS表中完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0001(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0001(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /* 作业名称: 指标-客户数
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0001
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
  			DWS_CUST_LVL_INFO
  			DWS_CUST_PRDKT_HOLD
  			DWS_CUST_LIFE_CYCLE_STAGE
  			DWD_CUST_GRP_DETAIL
  			DWD_SYS_ORG_JGCSV
  			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0001
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-客户数';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0001';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0001';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0001';
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步理财经理客户数指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 2.1 理财经理客户数指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;  
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0001(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0001' INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID DATA_BLNG , -- 数据归属
	  '00' STATIS_DIM  , -- 统计维度
      '00' STATIS_CALIB , -- 统计口径
	  COUNT(DISTINCT A.CUST_ID) CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步理财经理客户数指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.2 理财经理客户数按客户层级指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0001(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0001' INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID DATA_BLNG , -- 数据归属
	  '01' STATIS_DIM  , -- 统计维度
      B.CUST_HRAKY STATIS_CALIB , -- 统计口径
	  COUNT(DISTINCT A.CUST_ID) CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN DWS_CUST_LVL_INFO B 
     ON A.CUST_ID =B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE =B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE = V_SYSDAT
  GROUP BY A.MNGR_POST_ID,B.CUST_HRAKY,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.2步理财经理客户数按客户层级指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.3. 理财经理客户数按产品持有数指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0001(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0001' INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID DATA_BLNG , -- 数据归属
	  '02' STATIS_DIM  , -- 统计维度
      B.PRC_CNT STATIS_CALIB , -- 统计口径
	  COUNT(DISTINCT A.CUST_ID) CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN (SELECT CUST_ID,PERSN_LEGAL_BK_CODE,COUNT(1) AS PRC_CNT 
                FROM DWS_CUST_PRDKT_HOLD
               WHERE DATA_DATE = V_SYSDAT
               GROUP BY CUST_ID,PERSN_LEGAL_BK_CODE
  			  ) B 
     ON A.CUST_ID =B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE =B.PERSN_LEGAL_BK_CODE 
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE,B.PRC_CNT
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.3步理财经理客户数按产品持有数数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.4. 理财经理客户数按生命周期指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2.4';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0001(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0001' INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID DATA_BLNG , -- 数据归属
	  '03' STATIS_DIM  , -- 统计维度
      B.LIFE_CYCLE_STAGE STATIS_CALIB , -- 统计口径
	  COUNT(DISTINCT A.CUST_ID) CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN DWS_CUST_LIFE_CYCLE_STAGE B 
     ON A.CUST_ID =B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE =B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DT = V_SYSDAT
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE,B.LIFE_CYCLE_STAGE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.4步理财经理客户数按生命周期数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.5 理财经理客户数按客户等级指标统计
  ------------------------------------------------------------------
