     ON A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = B.ORG_ID
  INNER JOIN DWS_CUST_LIFE_CYCLE_STAGE C
     ON A.CUST_ID = C.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE
    AND C.DATA_DT = V_SYSDAT
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY B.SUP_ORG_ID,C.LIFE_CYCLE_STAGE,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
