  V_LOG_MSG := '第3.4步机构客户数按生命周期指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.5. 机构客户数按客户等级指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0001(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0001' INDX_CODE , -- 指标编码
	  B.SUP_ORG_ID DATA_BLNG , -- 数据归属
	  '11' STATIS_DIM  , -- 统计维度
      A.CUST_LVL STATIS_CALIB , -- 统计口径
	  COUNT(1) CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN DWD_SYS_ORG_JGCSV B 
     ON A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = B.ORG_ID
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY B.SUP_ORG_ID,A.CUST_LVL,A.PERSN_LEGAL_BK_CODE
