  COMMIT;
  
  ------------------------------------------------------------------
  -- 5. 汇总AUM余额指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0002(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0002 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0002'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
