  INNER JOIN DWS_CUST_LIFE_CYCLE_STAGE B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DT = V_SYSDAT
  INNER JOIN DWS_CUST_ASSE_LIAB C
     ON A.CUST_ID  = C.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE 
    AND C.BAL_TYPE  = '2' --月日均
    AND C.DATA_DATE = V_SYSDAT  
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,B.LIFE_CYCLE_STAGE,A.PERSN_LEGAL_BK_CODE
