   )
   SELECT 
   	  'INDX_0003' INDX_CODE , -- 指标编码
	  A.CREATR AS DATA_BLNG , -- 数据归属
	  '10' STATIS_DIM  , -- 统计维度
      A.CUST_GRP_ID STATIS_CALIB , -- 统计口径
	  SUM(B.AUM_BAL) AS CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
