    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE
    AND B.BAL_TYPE = '2' --月日均
    AND B.DATA_DATE = V_SYSDAT
  GROUP BY A.CREATR,A.CUST_GRP_ID,A.PERSN_LEGAL_BK_CODE
