  ------------------------------------------------------------------
  -- 5. 汇总活期余额季日均指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0008(
   	  INDX_CODE , -- 指标编码
