  ------------------------------------------------------------------
  -- 5. 汇总活期余额年日均指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0009(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
