     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
    AND B.BAL_TYPE  = '1' --余额
    AND B.DATA_DATE = V_SYSDAT     
  INNER JOIN DWD_SYS_ORG_JGCSV C
     ON A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = C.ORG_ID
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY C.SUP_ORG_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1步机构定期余额指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.2. 机构定期余额指标按客户层级统计
  ------------------------------------------------------------------
  V_NO_ID := '3.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0010(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0010' AS INDX_CODE , -- 指标编码
	  C.SUP_ORG_ID AS DATA_BLNG , -- 数据归属
	  '01' AS STATIS_DIM  , -- 统计维度
      A.CUST_HRAKY AS STATIS_CALIB , -- 统计口径
	  SUM(B.FIXD_DEPO_BAL+B.LEHUI_BAL+B.LARGEDP_BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN DWS_CUST_ASSE_LIAB B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
    AND B.BAL_TYPE  = '1' --余额
    AND B.DATA_DATE = V_SYSDAT     
  INNER JOIN DWD_SYS_ORG_JGCSV C
     ON A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = C.ORG_ID
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY C.SUP_ORG_ID,A.CUST_HRAKY,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2步机构定期余额指标按客户层级统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 4.1. 客群定期余额指标统计
  ------------------------------------------------------------------
  V_NO_ID := '4.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0010(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0010' INDX_CODE , -- 指标编码
	  A.CREATR AS DATA_BLNG , -- 数据归属
	  '10' STATIS_DIM  , -- 统计维度
      A.CUST_GRP_ID STATIS_CALIB , -- 统计口径
	  SUM(B.FIXD_DEPO_BAL+B.LEHUI_BAL+B.LARGEDP_BAL) AS CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_GRP_DETAIL A
  INNER JOIN DWS_CUST_ASSE_LIAB B 
     ON A.CUST_ID = B.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE
    AND B.BAL_TYPE = '1' --余额
    AND B.DATA_DATE = V_SYSDAT
  GROUP BY A.CREATR,A.CUST_GRP_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.1步客群定期余额指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 5. 汇总定期余额指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0010(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0010 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0010'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步汇总定期余额指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

