	  '10' STATIS_DIM  , -- 统计维度
      A.CUST_GRP_ID STATIS_CALIB , -- 统计口径
	  SUM(B.FIXD_DEPO_BAL+B.LEHUI_BAL+B.LARGEDP_BAL) AS CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
