CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0014(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-个人理财余额
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0014
  -- 处理周期: 每日
