      A.CUST_GRP_ID STATIS_CALIB , -- 统计口径
	  SUM(B.FIN_BAL) AS CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
