  ------------------------------------------------------------------
  -- 5. 汇总理财余额季日均指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0016(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
