	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号	
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN DWS_CUST_ASSE_LIAB B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
    AND B.BAL_TYPE  = '4' --年日均
    AND B.DATA_DATE = V_SYSDAT     
  INNER JOIN DWD_SYS_ORG_JGCSV C
     ON A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = C.ORG_ID
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY C.SUP_ORG_ID,A.CUST_HRAKY,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2步机构理财余额年日均指标按客户层级统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 4.1. 客群理财余额年日均指标统计
  ------------------------------------------------------------------
  V_NO_ID := '4.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0017(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0017' INDX_CODE , -- 指标编码
	  A.CREATR AS DATA_BLNG , -- 数据归属
	  '10' STATIS_DIM  , -- 统计维度
      A.CUST_GRP_ID STATIS_CALIB , -- 统计口径
	  SUM(B.FIN_BAL) AS CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_GRP_DETAIL A
  INNER JOIN DWS_CUST_ASSE_LIAB B 
     ON A.CUST_ID = B.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE
    AND B.BAL_TYPE = '4' --年日均
    AND B.DATA_DATE = V_SYSDAT
  GROUP BY A.CREATR,A.CUST_GRP_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.1步客群理财余额年日均指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 5. 汇总理财余额年日均指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0017(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0017 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0017'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步汇总理财余额年日均指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0018(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0018(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-贷款余额
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0018
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
			DWS_CUST_ASSE_LIAB
			DWS_CUST_LVL_INFO
			DWD_SYS_ORG_JGCSV
			ADS_STAT_INDX_DATA_HIS
			DWD_CUST_GRP_DETAIL
			DWD_ACCT_LOAN
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0018
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-贷款余额';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0018';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0018';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_STAT_INDX_DATA_INDX_0018';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0018';  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空临时表和目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.1. 理财经理贷款余额指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0018(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0018' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.LOAN_BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN DWS_CUST_ASSE_LIAB B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND B.BAL_TYPE  = '1' --余额
    AND B.data_date  = V_SYSDAT
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.1步理财经理贷款余额指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.2. 理财经理贷款余额指标按客户层级统计
  ------------------------------------------------------------------
  V_NO_ID := '2.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0018(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0018' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '01' AS STATIS_DIM  , -- 统计维度
      C.CUST_HRAKY AS STATIS_CALIB , -- 统计口径
	  SUM(B.LOAN_BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN DWS_CUST_ASSE_LIAB B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND B.BAL_TYPE  = '1' --余额
    AND B.data_date  = V_SYSDAT
  INNER JOIN DWS_CUST_LVL_INFO C 
     ON A.CUST_ID = C.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE
    AND C.DATA_DATE = V_SYSDAT
  GROUP BY A.MNGR_POST_ID,C.CUST_HRAKY,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.2步理财经理贷款余额指标按客户层级统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.3. 理财经理贷款余额按贷款种类指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0018(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0018' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '05' AS STATIS_DIM  , -- 统计维度
      B.PRDKT_CATE_BIG AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN (SELECT T.PERSN_LEGAL_BK_CODE ,T.CUST_ID,T.PRDKT_CATE_BIG,SUM(BAL) AS BAL 
  			    FROM DWD_ACCT_LOAN T
  			   WHERE PRDKT_CATE_BIG IS NOT NULL --剔除贷款产品为空的数据
  			   GROUP BY T.PERSN_LEGAL_BK_CODE ,T.CUST_ID,T.PRDKT_CATE_BIG) B 
     ON A.CUST_ID = B.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,B.PRDKT_CATE_BIG,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.3步理财经理贷款余额指标按贷款种类统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.1. 机构贷款余额指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '3.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP1_ADS_STAT_INDX_DATA_INDX_0018(
	  ORG_ID , -- 机构编号 
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.LOAN_BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN DWS_CUST_ASSE_LIAB B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
    AND B.BAL_TYPE  = '1' --余额
    AND B.DATA_DATE = V_SYSDAT 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1步机构贷款余额指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  
  ------------------------------------------------------------------
  -- 3.2. 机构贷款余额指标按客户层级统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '3.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP1_ADS_STAT_INDX_DATA_INDX_0018(
	  ORG_ID , -- 机构编号 
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '01' AS STATIS_DIM  , -- 统计维度
      A.CUST_HRAKY AS STATIS_CALIB , -- 统计口径
	  SUM(B.LOAN_BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN DWS_CUST_ASSE_LIAB B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
    AND B.BAL_TYPE  = '1' --余额
    AND B.DATA_DATE = V_SYSDAT 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,A.CUST_HRAKY,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2步机构贷款余额指标按客户层级统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  
  ------------------------------------------------------------------
  -- 3.3. 机构贷款余额按贷款种类指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '3.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP1_ADS_STAT_INDX_DATA_INDX_0018(
   	  ORG_ID , -- 机构号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
      CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '05' AS STATIS_DIM  , -- 统计维度
      B.PRDKT_CATE_BIG AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A  
  INNER JOIN (SELECT T.PERSN_LEGAL_BK_CODE ,T.CUST_ID,T.PRDKT_CATE_BIG,SUM(BAL) AS BAL 
  			    FROM DWD_ACCT_LOAN T
  			   WHERE PRDKT_CATE_BIG IS NOT NULL --剔除贷款产品为空的数据
  			   GROUP BY T.PERSN_LEGAL_BK_CODE ,T.CUST_ID,T.PRDKT_CATE_BIG) B 
     ON A.CUST_ID = B.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,B.PRDKT_CATE_BIG,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.3步机构贷款余额指标按贷款种类统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 3.4. 汇总机构贷款余额指标
  ------------------------------------------------------------------
  V_NO_ID := '3.4';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0018(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0018'  AS INDX_CODE , -- 指标编码
	  B.SUP_ORG_ID  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  SUM(A.CURNT_VAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP1_ADS_STAT_INDX_DATA_INDX_0018 A 
  INNER JOIN DWD_SYS_ORG_JGCSV B 
     ON A.ORG_ID=B.ORG_ID 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE
  GROUP BY B.SUP_ORG_ID,A.STATIS_DIM,A.STATIS_CALIB,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.4步汇总机构贷款余额指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 4.1. 客群贷款余额指标统计
  ------------------------------------------------------------------
  V_NO_ID := '4.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0018(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0018' INDX_CODE , -- 指标编码
	  A.CREATR AS DATA_BLNG , -- 数据归属
	  '10' STATIS_DIM  , -- 统计维度
      A.CUST_GRP_ID STATIS_CALIB , -- 统计口径
	  SUM(B.LOAN_BAL) AS CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_GRP_DETAIL A
  INNER JOIN DWS_CUST_ASSE_LIAB B 
     ON A.CUST_ID = B.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE
    AND B.BAL_TYPE = '1' --余额 
    AND B.DATA_DATE = V_SYSDAT
  GROUP BY A.CREATR,A.CUST_GRP_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.1步客群贷款余额指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 5. 汇总贷款余额指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0018(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0018 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0018'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步汇总贷款余额指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0019(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0019(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-储蓄存款余额
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0019
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
			DWS_CUST_ASSE_LIAB
			DWS_CUST_LVL_INFO
			DWD_ACCT_DEPO
			DWD_SYS_ORG_JGCSV
			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0019
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-储蓄存款余额';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0019';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0019';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_STAT_INDX_DATA_INDX_0019'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP2_ADS_STAT_INDX_DATA_INDX_0019'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0019';  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空临时表和目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.1. 客户存款期限数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP1_ADS_STAT_INDX_DATA_INDX_0019(
   	  CUST_ID , -- 客户编号
	  PERSN_LEGAL_BK_CODE, -- 法人行号
	  QX, --期限
	  BAL --余额
   )
   SELECT T.CUST_ID , -- 客户编号
  		  T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END AS QX, --期限
			SUM(BAL) --余额
  	FROM DWD_ACCT_DEPO T
   GROUP BY T.CUST_ID , -- 客户编号
  		  	T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.1步客户存款期限数据插入临时表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.1. 理财经理储蓄存款余额指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0019(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0019' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0019 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1步理财经理储蓄存款余额指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.2. 理财经理储蓄存款余额按存款期限指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0019(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0019' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0019 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2步理财经理储蓄存款余额按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.1. 机构储蓄存款余额指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0019(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0019 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.1步机构储蓄存款余额指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT; 
  ------------------------------------------------------------------
  -- 4.2. 机构储蓄存款余额按存款期限指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0019(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0019 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.2步机构储蓄存款余额按存款期限指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.3. 机构储蓄存款余额汇总数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0019(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0019' AS INDX_CODE , -- 指标编码
	  B.SUP_ORG_ID AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB AS STATIS_CALIB , -- 统计口径
	  SUM(A.CURNT_VAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP2_ADS_STAT_INDX_DATA_INDX_0019 A
  INNER JOIN DWD_SYS_ORG_JGCSV B
     ON A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = B.ORG_ID
  GROUP BY B.SUP_ORG_ID,A.STATIS_DIM,A.STATIS_CALIB,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.3步机构储蓄存款余额按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 5. 汇总储蓄存款余额指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0019(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0019 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0019'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步汇总储蓄存款余额指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0020(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0020(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-储蓄存款余额月日均
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0020
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
			DWS_CUST_ASSE_LIAB
			DWS_CUST_LVL_INFO
			ADS_ACCT_DEPO_AVG
			DWD_SYS_ORG_JGCSV
			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0020
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-储蓄存款余额月日均';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0020';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0020';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_STAT_INDX_DATA_INDX_0020'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP2_ADS_STAT_INDX_DATA_INDX_0020'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0020';  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空临时表和目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.1. 客户存款期限数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP1_ADS_STAT_INDX_DATA_INDX_0020(
   	  CUST_ID , -- 客户编号
	  PERSN_LEGAL_BK_CODE, -- 法人行号
	  QX, --期限
	  BAL --余额
   )
   SELECT T.CUST_ID , -- 客户编号
  		  T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END AS QX, --期限
			SUM(BAL_MTH_AVG_DAY) --余额
  	FROM ADS_ACCT_DEPO_AVG T
   GROUP BY T.CUST_ID , -- 客户编号
  		  	T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.1步客户存款期限数据插入临时表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.1. 理财经理储蓄存款余额月日均指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0020(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0020' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0020 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1步理财经理储蓄存款余额月日均指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.2. 理财经理储蓄存款余额月日均按存款期限指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0020(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0020' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0020 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2步理财经理储蓄存款余额月日均按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.1. 机构储蓄存款余额月日均指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0020(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0020 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.1步机构储蓄存款余额月日均指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT; 
  ------------------------------------------------------------------
  -- 4.2. 机构储蓄存款余额月日均按存款期限指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0020(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0020 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.2步机构储蓄存款余额月日均按存款期限指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.3. 机构储蓄存款余额月日均汇总数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0020(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0020' AS INDX_CODE , -- 指标编码
	  B.SUP_ORG_ID AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB AS STATIS_CALIB , -- 统计口径
	  SUM(A.CURNT_VAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP2_ADS_STAT_INDX_DATA_INDX_0020 A
  INNER JOIN DWD_SYS_ORG_JGCSV B
     ON A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = B.ORG_ID
  GROUP BY B.SUP_ORG_ID,A.STATIS_DIM,A.STATIS_CALIB,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.3步机构储蓄存款余额月日均按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 5. 汇总储蓄存款余额月日均指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0020(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0020 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0020'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步汇总储蓄存款余额月日均指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0021(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0021(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-储蓄存款余额季日均
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0021
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
			DWS_CUST_ASSE_LIAB
			DWS_CUST_LVL_INFO
			ADS_ACCT_DEPO_AVG
			DWD_SYS_ORG_JGCSV
			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0021
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-储蓄存款余额季日均';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0021';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0021';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_STAT_INDX_DATA_INDX_0021'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP2_ADS_STAT_INDX_DATA_INDX_0021'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0021';  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空临时表和目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.1. 客户存款期限数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP1_ADS_STAT_INDX_DATA_INDX_0021(
   	  CUST_ID , -- 客户编号
	  PERSN_LEGAL_BK_CODE, -- 法人行号
	  QX, --期限
	  BAL --余额
   )
   SELECT T.CUST_ID , -- 客户编号
  		  T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END AS QX, --期限
			SUM(BAL_QRT_AVG_DAY) --余额
  	FROM ADS_ACCT_DEPO_AVG T
   GROUP BY T.CUST_ID , -- 客户编号
  		  	T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.1步客户存款期限数据插入临时表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.1. 理财经理储蓄存款余额季日均指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0021(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0021' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0021 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1步理财经理储蓄存款余额季日均指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.2. 理财经理储蓄存款余额季日均按存款期限指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0021(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0021' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0021 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2步理财经理储蓄存款余额季日均按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.1. 机构储蓄存款余额季日均指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0021(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0021 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.1步机构储蓄存款余额季日均指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT; 
  ------------------------------------------------------------------
  -- 4.2. 机构储蓄存款余额季日均按存款期限指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0021(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0021 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.2步机构储蓄存款余额季日均按存款期限指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.3. 机构储蓄存款余额季日均汇总数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0021(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0021' AS INDX_CODE , -- 指标编码
	  B.SUP_ORG_ID AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB AS STATIS_CALIB , -- 统计口径
	  SUM(A.CURNT_VAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP2_ADS_STAT_INDX_DATA_INDX_0021 A
  INNER JOIN DWD_SYS_ORG_JGCSV B
     ON A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = B.ORG_ID
  GROUP BY B.SUP_ORG_ID,A.STATIS_DIM,A.STATIS_CALIB,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.3步机构储蓄存款余额季日均按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 5. 汇总储蓄存款余额季日均指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0021(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0021 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0021'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步汇总储蓄存款余额季日均指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0022(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0022(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-储蓄存款余额年日均
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0022
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
			DWS_CUST_ASSE_LIAB
			DWS_CUST_LVL_INFO
			ADS_ACCT_DEPO_AVG
			DWD_SYS_ORG_JGCSV
			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0022
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-储蓄存款余额年日均';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0022';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0022';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_ADS_STAT_INDX_DATA_INDX_0022'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP2_ADS_STAT_INDX_DATA_INDX_0022'; 
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0022';  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空临时表和目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2.1. 客户存款期限数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP1_ADS_STAT_INDX_DATA_INDX_0022(
   	  CUST_ID , -- 客户编号
	  PERSN_LEGAL_BK_CODE, -- 法人行号
	  QX, --期限
	  BAL --余额
   )
   SELECT T.CUST_ID , -- 客户编号
  		  T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END AS QX, --期限
			SUM(BAL_YR_AVG_DAY) --余额
  	FROM ADS_ACCT_DEPO_AVG T
   GROUP BY T.CUST_ID , -- 客户编号
  		  	T.PERSN_LEGAL_BK_CODE , -- 法人行号
		  CASE WHEN UPPER(T.CUNQ) LIKE '%D' THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 12 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 12 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) <= 36 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%M' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'M','')) > 36 THEN '03' --3～5年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 1 THEN '01' --1年及以下
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 1 AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) <= 3 THEN '02' --1～3年
			   WHEN UPPER(T.CUNQ) LIKE '%Y' AND TO_NUMBER(REPLACE(UPPER(T.CUNQ),'Y','')) > 3 THEN '03' --3～5年
			END
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2.1步客户存款期限数据插入临时表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.1. 理财经理储蓄存款余额年日均指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0022(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0022' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0022 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1步理财经理储蓄存款余额年日均指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3.2. 理财经理储蓄存款余额年日均按存款期限指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0022(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0022' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0022 B 
     ON A.CUST_ID = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2步理财经理储蓄存款余额年日均按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.1. 机构储蓄存款余额年日均指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0022(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '00' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0022 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.1步机构储蓄存款余额年日均指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT; 
  ------------------------------------------------------------------
  -- 4.2. 机构储蓄存款余额年日均按存款期限指标统计数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP2_ADS_STAT_INDX_DATA_INDX_0022(
   	  ORG_ID , -- 机构编号
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.ORG_ID AS DATA_BLNG , -- 数据归属
	  '06' AS STATIS_DIM  , -- 统计维度
      B.QX AS STATIS_CALIB , -- 统计口径
	  SUM(B.BAL) AS CURNT_VAL , -- 本期值
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN TMP1_ADS_STAT_INDX_DATA_INDX_0022 B
     ON A.CUST_ID  = B.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE 
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY A.ORG_ID,B.QX,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.2步机构储蓄存款余额年日均按存款期限指标统计数据插入临时表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4.3. 机构储蓄存款余额年日均汇总数据插入临时表
  ------------------------------------------------------------------
  V_NO_ID := '4.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0022(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0022' AS INDX_CODE , -- 指标编码
	  B.SUP_ORG_ID AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB AS STATIS_CALIB , -- 统计口径
	  SUM(A.CURNT_VAL) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP2_ADS_STAT_INDX_DATA_INDX_0022 A
  INNER JOIN DWD_SYS_ORG_JGCSV B
     ON A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = B.ORG_ID
  GROUP BY B.SUP_ORG_ID,A.STATIS_DIM,A.STATIS_CALIB,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4.3步机构储蓄存款余额年日均按存款期限指标统计统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 5. 汇总储蓄存款余额年日均指标
  ------------------------------------------------------------------
  V_NO_ID := '5';
