   	  'INDX_0028' AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG AS DATA_BLNG , -- 数据归属
	  'Y' AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL - NVL(B.CURNT_VAL,0)  AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
