    AND B.INDX_CODE = 'INDX_0010'
    AND B.DATA_DATE = V_LAST_YEAR --上年末
  WHERE A.STATIS_DIM = '00' --只统计和机构的汇总项,不统计客户等级、生命周期、沙龙、客群的分项数据
  ;
