CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0030(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-面访活动量
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0030
  -- 处理周期: 每日
  -- 来源表: DWS_REC_CNT
  			DWD_CUST_MAN
  			DWS_CUST_LVL_INFO
  			DWD_SYS_ORG_JGCSV
  			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0030
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-面访活动量';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0030';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0030';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0030';  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空临时表和目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 2. 理财经理面访活动量指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0030(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0030' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  B.STATIS_DIM AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(CASE WHEN B.STATIS_DIM = 'M' THEN C.VISIT_CNT_M
	  		   WHEN B.STATIS_DIM = 'Q' THEN C.VISIT_CNT_Q
	  		   WHEN B.STATIS_DIM = 'Y' THEN C.VISIT_CNT_Y
	  	   END) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A  
  INNER JOIN (SELECT 'M' AS STATIS_DIM FROM DUAL
  			  UNION ALL
  			  SELECT 'Q' AS STATIS_DIM FROM DUAL
  			  UNION ALL
  			  SELECT 'Y' AS STATIS_DIM FROM DUAL) B
     ON 1=1
  INNER JOIN DWS_REC_CNT C
     ON A.CUST_ID  = C.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,B.STATIS_DIM,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步理财经理面访活动量指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 3. 机构面访活动量指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0030(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0030' AS INDX_CODE , -- 指标编码
	  D.SUP_ORG_ID AS DATA_BLNG , -- 数据归属
	  B.STATIS_DIM AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(CASE WHEN B.STATIS_DIM = 'M' THEN C.VISIT_CNT_M
	  		   WHEN B.STATIS_DIM = 'Q' THEN C.VISIT_CNT_Q
	  		   WHEN B.STATIS_DIM = 'Y' THEN C.VISIT_CNT_Y
	  	   END) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWS_CUST_LVL_INFO A 
  INNER JOIN (SELECT 'M' AS STATIS_DIM FROM DUAL
  			  UNION ALL
  			  SELECT 'Q' AS STATIS_DIM FROM DUAL
  			  UNION ALL
  			  SELECT 'Y' AS STATIS_DIM FROM DUAL) B
     ON 1=1
  INNER JOIN DWS_REC_CNT C
     ON A.CUST_ID  = C.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE 
  INNER JOIN DWD_SYS_ORG_JGCSV D
     ON A.PERSN_LEGAL_BK_CODE  = D.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = D.ORG_ID
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY D.SUP_ORG_ID,B.STATIS_DIM,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3步机构面访活动量指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 4. 汇总面访活动量指标
  ------------------------------------------------------------------
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0030(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
