  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0032';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0032';  
