	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0032' AS INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID AS DATA_BLNG , -- 数据归属
	  B.STATIS_DIM AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  SUM(CASE WHEN B.STATIS_DIM = 'M' THEN C.QYWX_CNT_M
	  		   WHEN B.STATIS_DIM = 'Q' THEN C.QYWX_CNT_Q
	  		   WHEN B.STATIS_DIM = 'Y' THEN C.QYWX_CNT_Y
	  	   END) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
