     ON A.CUST_ID  = C.CUST_ID 
    AND A.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE 
  INNER JOIN DWD_SYS_ORG_JGCSV D
     ON A.PERSN_LEGAL_BK_CODE  = D.PERSN_LEGAL_BK_CODE
    AND A.ORG_ID  = D.ORG_ID
  WHERE A.DATA_DATE = V_SYSDAT
  GROUP BY D.SUP_ORG_ID,B.STATIS_DIM,A.PERSN_LEGAL_BK_CODE
