  ------------------------------------------------------------------
  -- 2. 理财经理潜力提升户数指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0036(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
