   )
   SELECT 
   	  'INDX_0036' AS INDX_CODE , -- 指标编码
	  A.POST_ID AS DATA_BLNG , -- 数据归属
	  A.STATIS_CYCLE AS STATIS_DIM  , -- 统计维度
      '00' AS STATIS_CALIB , -- 统计口径
	  COUNT(DISTINCT CUST_ID) AS CURNT_VAL , -- 本期值
	  0 AS TERM_LAST_VAL , -- 上期值
	  0 AS MTH_END_VAL , -- 月末值
	  0 AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
