AS 
  ------------------------------------------------------------------
  /* 作业名称: 指标-有效客户数
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0040
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
  			ADS_CUST_LABLE_VALID_CUST
  			DWD_SYS_ORG_JGCSV
  			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0040
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '指标-有效客户数';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_ADS_STAT_INDX_DATA_INDX_0040';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YEAR	VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YEAR := sys_fun_deal_date(V_SYSDAT,4);
  
  ------------------------------------------------------------------
  -- 1. 清空临时表和目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_ADS_STAT_INDX_DATA_INDX_0040';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE ADS_STAT_INDX_DATA_INDX_0040';
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空临时表和目标表数据完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  ------------------------------------------------------------------
  -- 2.1 理财经理有效客户数指标统计
  ------------------------------------------------------------------
  V_NO_ID := '2.1';
  V_BGN_DATE := SYSDATE;  
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0040(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0040' INDX_CODE , -- 指标编码
	  A.MNGR_POST_ID DATA_BLNG , -- 数据归属
	  '00' STATIS_DIM  , -- 统计维度
      '00' STATIS_CALIB , -- 统计口径
	  COUNT(DISTINCT A.CUST_ID) CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM DWD_CUST_MAN A 
  INNER JOIN ADS_CUST_LABLE_VALID_CUST  B  --只有有效客户 
     ON A.CUST_ID = B.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE
  GROUP BY A.MNGR_POST_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步理财经理有效客户数指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 3.1 机构有效客户数指标统计
  ------------------------------------------------------------------
  V_NO_ID := '3.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO TMP_ADS_STAT_INDX_DATA_INDX_0040(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  'INDX_0040' INDX_CODE , -- 指标编码
	  C.SUP_ORG_ID DATA_BLNG , -- 数据归属
	  '00' STATIS_DIM  , -- 统计维度
      '00' STATIS_CALIB , -- 统计口径
	  COUNT(1) CURNT_VAL , -- 本期值
	  0 TERM_LAST_VAL , -- 上期值
	  0 MTH_END_VAL , -- 月末值
	  0 YR_BGN_VAL , -- 年初值
	  V_SYSDAT DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM ADS_CUST_LABLE_VALID_CUST A  --只有有效客户 
  INNER JOIN DWS_CUST_LVL_INFO B 
     ON A.CUST_ID = B.CUST_ID
    AND A.PERSN_LEGAL_BK_CODE  = B.PERSN_LEGAL_BK_CODE
    AND B.DATA_DATE = V_SYSDAT
  INNER JOIN DWD_SYS_ORG_JGCSV C 
     ON B.PERSN_LEGAL_BK_CODE  = C.PERSN_LEGAL_BK_CODE
    AND B.ORG_ID  = C.ORG_ID
  GROUP BY C.SUP_ORG_ID,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1步机构有效客户数指标统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 4. 汇总有效客户数指标
  ------------------------------------------------------------------
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;
   INSERT INTO ADS_STAT_INDX_DATA_INDX_0040(
   	  INDX_CODE , -- 指标编码
	  DATA_BLNG , -- 数据归属
	  STATIS_DIM  , -- 统计维度
      STATIS_CALIB , -- 统计口径
	  CURNT_VAL , -- 本期值
	  TERM_LAST_VAL , -- 上期值
	  MTH_END_VAL , -- 月末值
	  YR_BGN_VAL , -- 年初值
	  DATA_DATE , -- 数据日期
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	  A.INDX_CODE  AS INDX_CODE , -- 指标编码
	  A.DATA_BLNG  AS DATA_BLNG , -- 数据归属
	  A.STATIS_DIM  AS STATIS_DIM  , -- 统计维度
      A.STATIS_CALIB  AS STATIS_CALIB , -- 统计口径
	  A.CURNT_VAL AS CURNT_VAL , -- 本期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_DAY THEN B.CURNT_VAL ELSE 0 END) AS TERM_LAST_VAL , -- 上期值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_MTH THEN B.CURNT_VAL ELSE 0 END) AS MTH_END_VAL , -- 月末值
	  SUM(CASE WHEN B.DATA_DATE = V_LAST_YEAR THEN B.CURNT_VAL ELSE 0 END) AS YR_BGN_VAL , -- 年初值
	  V_SYSDAT AS DATA_DATE , -- 数据日期
	  A.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE -- 法人行号
   FROM TMP_ADS_STAT_INDX_DATA_INDX_0040 A 
   LEFT JOIN ADS_STAT_INDX_DATA_HIS B 
     ON A.DATA_BLNG=B.DATA_BLNG 
    AND A.STATIS_DIM  = B.STATIS_DIM 
    AND A.STATIS_CALIB  = B.STATIS_CALIB 
    AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE 
    AND B.DATA_DATE IN (V_LAST_DAY,V_LAST_MTH,V_LAST_YEAR)
    AND B.INDX_CODE = 'INDX_0040'
  GROUP BY A.INDX_CODE,A.DATA_BLNG,A.STATIS_DIM,A.STATIS_CALIB,A.CURNT_VAL,A.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4步汇总有效客户数指标完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
   
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

