CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0041(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-个人代销理财余额
