;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0042(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_data_indx_0042(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 指标-代发薪客户数
  -- 作业编号: PRC_ADS_STAT_INDX_DATA_INDX_0042
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
			ADS_CUST_LABEL_AE01
			DWS_CUST_LVL_INFO
			DWD_SYS_ORG_JGCSV
			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_0042
