BEGIN
    -------------------------------------------------------------------------
    -- 标准模板：参数校验与开始日志状态
    -------------------------------------------------------------------------
    V_NO_ID  := '0';  -- 初始化日志序号
    V_BGN_DATE := SYSDATE;   -- 记录过程开始时间

    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN   -- 校验业务日期为非空8位数字
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');      -- 格式非法则报错
    END IF;
    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 业务日期字符串转日期型

    -------------------------------------------------------------------------
    -- 初始化日期边界
    -------------------------------------------------------------------------
    V_NEXT_DAY := sys_fun_deal_date(v_sysdat, 31);  -- 计算顺延31天后日期(活动范围判断基准)

    -------------------------------------------------------------------------
    -- 路径08：营销活动范围写入
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_SCOPE (
        path_code, statis_dim, indx_code, data_blng,  -- 路径编码, 统计维度, 指标编码, 归属机构
        blng_type, blng_id, term_begin_date, persn_legal_bk_code   -- 归属类型(O机构/M客户经理), 归属ID, 期间开始日, 法人行号
    )
    SELECT DISTINCT
           '08'                          AS path_code,        -- 路径08：营销活动口径
           a.mkt_act_id                 AS statis_dim,       -- 统计维度=营销活动ID
           t.indx_id                    AS indx_code,        -- 统计指标编码
           'ORG_' || ti.mkt_persn_org   AS data_blng,        -- 归属机构=客户经理所属机构加前缀
           'O'                          AS blng_type,        -- 归属类型：机构维度
           ti.mkt_persn_org             AS blng_id,          -- 归属ID=客户经理所属机构
           a.act_bgn_date               AS term_begin_date,  -- 指标期间开始日期=活动开始日期
           ti.persn_legal_bk_code       AS persn_legal_bk_code   -- 法人机构行号
      FROM DWD_MKT_ACT_INFO a                        -- 营销活动信息表
     INNER JOIN DWD_MKT_ACT_TARGT t                  -- 营销活动目标表
        ON t.mkt_act_id = a.mkt_act_id               -- 按活动ID关联
     INNER JOIN DWD_MKT_TSK_INFO ti                  -- 营销任务信息表
        ON ti.mkt_act_id          = a.mkt_act_id     -- 按活动ID关联任务
       AND ti.mkt_persn_org       = t.prtspt_org     -- 任务机构=目标参与机构
       AND ti.persn_legal_bk_code = a.persn_legal_bk_code    -- 法人行号一致
       AND ti.data_date           = v_sysdat         -- 任务数据日期=跑批日期
     WHERE a.act_bgn_date                      <= V_NEXT_DAY -- 活动开始日在顺延31天范围内
       AND NVL(a.statis_stop_date, '99991231') >= v_sysdat   -- 统计截止日未结束或晚于跑批日
       AND a.camp_act_typ IN ('1', '2')              -- 活动类型仅取1/2(营销活动口径)
       AND ti.mkt_persn_org IS NOT NULL              -- 所属机构非空

    UNION

    SELECT DISTINCT
           '08', a.mkt_act_id, t.indx_id,                   -- 路径08/活动ID/指标编码
           'MGR_' || ti.mkt_persn, 'M', ti.mkt_persn,      -- 归属机构加MGR_前缀, 归属类型=客户经理, 归属ID=客户经理
           a.act_bgn_date, ti.persn_legal_bk_code          -- 期间开始日, 法人行号
      FROM DWD_MKT_ACT_INFO a                              -- 营销活动信息表
     INNER JOIN DWD_MKT_ACT_TARGT t                        -- 营销活动目标表
        ON t.mkt_act_id = a.mkt_act_id                     -- 按活动ID关联
     INNER JOIN DWD_MKT_TSK_INFO ti                        -- 营销任务信息表
        ON ti.mkt_act_id          = a.mkt_act_id           -- 按活动ID关联任务
       AND ti.mkt_persn_org       = t.prtspt_org           -- 任务机构=目标参与机构
       AND ti.persn_legal_bk_code = a.persn_legal_bk_code  -- 法人行号一致
       AND ti.data_date           = v_sysdat               -- 任务数据日期=跑批日期
     WHERE a.act_bgn_date                      <= V_NEXT_DAY   -- 活动开始日在顺延31天范围内
       AND NVL(a.statis_stop_date, '99991231') >= v_sysdat -- 统计截止日未结束或晚于跑批日
       AND a.camp_act_typ IN ('1', '2')                    -- 活动类型仅取1/2
       AND ti.mkt_persn IS NOT NULL;                       -- 客户经理非空

    -------------------------------------------------------------------------
    -- 路径09：目标任务范围写入
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_SCOPE (
        path_code, statis_dim, indx_code, data_blng,  -- 路径编码, 统计维度, 指标编码, 归属机构
        blng_type, blng_id, term_begin_date, persn_legal_bk_code   -- 归属类型, 归属ID, 期间开始日, 法人行号
    )
    SELECT DISTINCT
           '09'                          AS path_code,         -- 路径09：目标任务口径
           it.tsk_id                    AS statis_dim,        -- 统计维度=目标任务ID
           sub.indx_id                  AS indx_code,         -- 统计指标编码
           'ORG_' || it.rsv_obj_id      AS data_blng,         -- 归属机构=预留对象ID加前缀
           'O'                          AS blng_type,         -- 归属类型：机构维度
           it.rsv_obj_id                AS blng_id,           -- 归属ID=预留对象ID
           sub.tsk_bgn_date             AS term_begin_date,   -- 指标期间开始日=任务开始日
           it.persn_legal_bk_code       AS persn_legal_bk_code-- 法人机构行号
      FROM DWD_MKT_INDX_TSK it                       -- 指标任务表
     INNER JOIN DWD_MKT_TSK_INDX_SUB sub             -- 任务指标子表
        ON sub.tsk_id              = it.tsk_id       -- 按任务ID关联
       AND sub.persn_legal_bk_code = it.persn_legal_bk_code   -- 法人行号一致
     WHERE it.rsv_obj                            = '0'        -- 预留对象类型0=机构
       AND sub.tsk_bgn_date                      <= V_NEXT_DAY-- 任务开始日在顺延31天范围内
       AND NVL(sub.tsk_end_date, '99991231')     >= v_sysdat  -- 任务结束日未结束或晚于跑批日

    UNION

    SELECT DISTINCT
           '09',                                -- 路径09
           it.tsk_id,                          -- 任务ID
           sub.indx_id,                        -- 指标编码
           'MGR_' || it.rsv_obj_id, 
           'M', 
           it.rsv_obj_id,        -- 归属机构加MGR_前缀, 归属类型=客户经理, 归属ID=预留对象ID
           sub.tsk_bgn_date, 
           it.persn_legal_bk_code            -- 期间开始日, 法人行号
      FROM DWD_MKT_INDX_TSK it         -- 指标任务表
     INNER JOIN DWD_MKT_TSK_INDX_SUB sub                       -- 任务指标子表
        ON sub.tsk_id              = it.tsk_id                 -- 按任务ID关联
       AND sub.persn_legal_bk_code = it.persn_legal_bk_code    -- 法人行号一致
     WHERE it.rsv_obj                            = '1'         -- 预留对象类型1=客户经理
       AND sub.tsk_bgn_date                      <= V_NEXT_DAY -- 任务开始日在顺延31天范围内
       AND NVL(sub.tsk_end_date, '99991231')     >= v_sysdat;  -- 任务结束日未结束或晚于跑批日

    -------------------------------------------------------------------------
    -- 提交与执行日志记录
    -------------------------------------------------------------------------
    outcde := SQL%ROWCOUNT;                                   -- 返回最近DML影响行数
    COMMIT;                -- 提交事务
    V_END_DATE  := SYSDATE;                                   -- 记录过程结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
    V_LOG_MSG   := '步骤1处理完成，行数=' || NVL(outcde, 0);           -- 组装成功日志消息
    V_LOG_FLG   := 0;      -- 日志标志置成功
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录步骤日志

    -------------------------------------------------------------------------
    -- 异常处理：回滚并记录错误日志后重抛
    -------------------------------------------------------------------------
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;                                                 -- 异常回滚事务
        outcde := -1;                                             -- 输出行数置-1表示失败
        V_END_DATE  := SYSDATE;                                   -- 记录异常结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
        V_LOG_MSG   := SUBSTR(SQLERRM, 1, 1000);                  -- 截取错误信息
        V_LOG_FLG   := -1;                                        -- 日志标志置失败
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录错误日志
        RAISE;   -- 重新抛出异常
END prc_ads_stat_indx_plan_001
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_002(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_002(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC   VARCHAR2(100) := '指标数据统计步骤22处理完成 2';  -- 步骤描述文本(步骤22处理完成)
    V_PRC_NAME   VARCHAR2(32)  := 'PRC_ADS_STAT_INDX_PLAN_002';  -- 过程名
    V_LOG_MSG    VARCHAR2(4000);  -- 日志消息文本
    V_LOG_FLG    INTEGER;         -- 日志标志(0成功/-1失败)
    V_LOG_BUTTON INTEGER := 1;    -- 日志按钮标识
    V_NO_ID      VARCHAR2(10);    -- 跑批序号
    V_BGN_DATE   DATE;            -- 开始时间
    V_END_DATE   DATE;            -- 结束时间
    V_DURA_DATE  INTEGER;         -- 耗时(秒)
    V_NEXT_DAY   VARCHAR2(8);     -- 活动/任务开始日期(YYYYMMDD)
    V_MISSING_CNT INTEGER;        -- 缺失基准的计数
BEGIN
    -------------------------------------------------------------------------
    -- 标准模板：参数校验与开始日志状态
    -------------------------------------------------------------------------
    V_NO_ID := '0';                                                -- 跑批序号置0
    V_BGN_DATE := SYSDATE;                                         -- 记录开始时间
    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN  -- 校验跑批日期必须为8位数字YYYYMMDD
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 日期格式非法则报错终止
    END IF;
    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 将跑批日期字符串转为日期类型

    -------------------------------------------------------------------------
    -- 初始化日期边界
    -------------------------------------------------------------------------
    V_NEXT_DAY := sys_fun_deal_date(v_sysdat, 31);  -- 调用日期处理函数获取活动/任务开始日期(下一自然日)

    -------------------------------------------------------------------------
    -- 3.1 冻结成员表 ADS_STAT_INDX_BASELINE_MEMBER
    -------------------------------------------------------------------------
    INSERT INTO ADS_STAT_INDX_BASELINE_MEMBER (        -- 插入冻结成员表
        statis_calib, statis_dim, data_blng, cust_id,  -- 统计口径、统计维度、数据归属、客户ID
        persn_legal_bk_code, base_data_date, base_run_date  -- 法人机构编号、基准数据日期、基准跑批日期
    )
    WITH scope_member AS (  -- 组装本次需冻结的成员范围(A/B多路径汇总)
        -- 路径08：营销活动成员
        SELECT s.path_code, s.statis_dim, s.indx_code, s.data_blng,    -- 路径代码、统计维度、指标代码、数据归属
               s.term_begin_date, ti.cust_id, s.persn_legal_bk_code    -- 开始日期、客户ID、法人机构编号
          FROM TMP_STAT_INDX_SCOPE s                                   -- 指标范围临时表
         INNER JOIN DWD_MKT_TSK_INFO ti                                -- 关联营销活动任务信息表
            ON s.path_code             = '08'                           -- 限定路径08(营销活动)
           AND ti.mkt_act_id           = s.statis_dim                  -- 营销活动ID等于统计维度
           AND ti.persn_legal_bk_code  = s.persn_legal_bk_code         -- 法人机构编号一致
           AND ti.data_date            = v_sysdat                      -- 取跑批日期当日的活动信息
           AND ((s.blng_type = 'O' AND ti.mkt_persn_org = s.blng_id)   -- 按机构归属匹配活动归属机构
             OR (s.blng_type = 'M' AND ti.mkt_persn     = s.blng_id))  -- 按客户经理归属匹配活动客户经理
         WHERE s.term_begin_date = V_NEXT_DAY                          -- 仅取开始日期为今日(活动昨日建立)的范围
           AND s.indx_code IN ('INDX_0050','INDX_0051','INDX_0052','INDX_0053','INDX_0054','INDX_0055',  -- 仅取需冻结的指标集合(含新增0050/0051)
                               'INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062','INDX_0063')  -- 其余需冻结指标代码

        UNION  -- 合并去重

        -- 路径09-机构归属成员
        SELECT s.path_code, s.statis_dim, s.indx_code, s.data_blng,  -- 路径代码、统计维度、指标代码、数据归属
               s.term_begin_date, lv.cust_id, s.persn_legal_bk_code  -- 开始日期、客户ID、法人机构编号
          FROM TMP_STAT_INDX_SCOPE s                                 -- 指标范围临时表
         INNER JOIN DWS_CUST_LVL_INFO lv                             -- 关联客户层级信息表
            ON s.path_code             = '09'                         -- 限定路径09(目标任务)
           AND s.blng_type             = 'O'                         -- 归属类型为机构
           AND lv.org_id               = s.blng_id                   -- 客户机构ID等于范围归属机构ID
           AND lv.persn_legal_bk_code  = s.persn_legal_bk_code       -- 法人机构编号一致
           AND lv.data_date            = v_sysdat                    -- 取跑批日期当日的客户层级信息
         WHERE s.term_begin_date = V_NEXT_DAY                        -- 仅取开始日期为今日的范围
           AND s.indx_code IN ('INDX_0050','INDX_0051','INDX_0052','INDX_0053','INDX_0054','INDX_0055',  -- 需冻结的指标集合
                               'INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062','INDX_0063')  -- 其余需冻结指标代码

        UNION  -- 合并去重

        -- 路径09-客户经理归属成员
        SELECT s.path_code, s.statis_dim, s.indx_code, s.data_blng,  -- 路径代码、统计维度、指标代码、数据归属
               s.term_begin_date, cm.cust_id, s.persn_legal_bk_code  -- 开始日期、客户ID、法人机构编号
          FROM TMP_STAT_INDX_SCOPE s                                 -- 指标范围临时表
         INNER JOIN DWD_CUST_MAN cm                                  -- 关联客户经理归属表
            ON s.path_code             = '09'                         -- 限定路径09(目标任务)
           AND s.blng_type             = 'M'                         -- 归属类型为客户经理
           AND cm.mngr_post_id         = s.blng_id                   -- 客户经理岗位ID等于范围归属岗位ID
           AND cm.mng_typ              = '1'                         -- 客户经理类型为主号
           AND cm.persn_legal_bk_code  = s.persn_legal_bk_code       -- 法人机构编号一致
         WHERE s.term_begin_date = V_NEXT_DAY                        -- 仅取开始日期为今日的范围
           AND s.indx_code IN ('INDX_0050','INDX_0051','INDX_0052','INDX_0053','INDX_0054','INDX_0055',  -- 需冻结的指标集合
                               'INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062','INDX_0063')  -- 其余需冻结指标代码
    )
    SELECT DISTINCT                      -- 客户维度去重
           CASE WHEN sm.path_code = '08' THEN '08' ELSE '09' END AS statis_calib,  -- 按路径映射统计口径
           sm.statis_dim,                -- 统计维度(活动ID/任务机构岗位ID)
           sm.data_blng,                 -- 数据归属
           sm.cust_id,                   -- 客户ID
           sm.persn_legal_bk_code,       -- 法人机构编号
           v_sysdat  AS base_data_date,  -- 基准数据日期=跑批日期
           v_sysdat  AS base_run_date    -- 基准跑批日期=跑批日期
      FROM scope_member sm               -- 范围成员结果集
     WHERE NOT EXISTS (                  -- 过滤掉已存在的成员基准,避免重复冻结
         SELECT 1
           FROM ADS_STAT_INDX_BASELINE_MEMBER x                 -- 冻结成员表
          WHERE x.statis_calib        = CASE WHEN sm.path_code = '08' THEN '08' ELSE '09' END  -- 口径一致
            AND x.statis_dim          = sm.statis_dim           -- 维度一致
            AND x.data_blng           = sm.data_blng            -- 归属一致
            AND x.cust_id             = sm.cust_id              -- 客户一致
            AND x.persn_legal_bk_code = sm.persn_legal_bk_code  -- 法人机构一致
     );

    -------------------------------------------------------------------------
    -- 3.2 冻结明细表 ADS_STAT_INDX_BASELINE_DTL
    -------------------------------------------------------------------------
    INSERT INTO ADS_STAT_INDX_BASELINE_DTL (                 -- 插入冻结明细表
        statis_calib, statis_dim, indx_code, data_blng, cust_id,  -- 统计口径、统计维度、指标代码、数据归属、客户ID
        persn_legal_bk_code, base_data_date, base_run_date,  -- 法人机构编号、基准数据日期、基准跑批日期
        base_cust_lvl, base_mth_avg_aum                      -- 基准客户等级、基准月日均AUM
    )
    SELECT CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END,  -- 路径映射统计口径
           s.statis_dim,                                             -- 统计维度
           s.indx_code,                                              -- 指标代码
           s.data_blng,                                              -- 数据归属
           m.cust_id,                                                -- 客户ID(取自成员基准)
           m.persn_legal_bk_code,                                    -- 法人机构编号
           m.base_data_date,                                         -- 基准数据日期
           m.base_run_date,                                          -- 基准跑批日期
           CASE WHEN s.indx_code IN ('INDX_0052','INDX_0053','INDX_0054')  -- 仅客户维护/客户提升/新增类指标需要客户等级
                THEN lv.cust_lvl END,                                -- 取客户层级
           CASE WHEN s.indx_code = 'INDX_0063'                       -- 仅月日均AUM指标需要
                THEN b.aum_bal END                                   -- 取月日均金融资产余额
      FROM TMP_STAT_INDX_SCOPE s                                     -- 指标范围临时表
     INNER JOIN ADS_STAT_INDX_BASELINE_MEMBER m                      -- 关联已冻结的成员基准
        ON m.statis_calib        = CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END  -- 口径一致
       AND m.statis_dim          = s.statis_dim                      -- 维度一致
       AND m.data_blng           = s.data_blng                       -- 归属一致
       AND m.persn_legal_bk_code = s.persn_legal_bk_code             -- 法人机构一致
      LEFT JOIN DWS_CUST_LVL_INFO lv                                 -- 关联客户层级信息
        ON lv.cust_id             = m.cust_id                        -- 客户ID一致
       AND lv.persn_legal_bk_code = m.persn_legal_bk_code            -- 法人机构一致
       AND lv.data_date           = v_sysdat                         -- 取跑批日期当日层级
      LEFT JOIN DWS_CUST_ASSE_LIAB b                                 -- 关联资产负债表
        ON b.cust_id             = m.cust_id                         -- 客户ID一致
       AND b.persn_legal_bk_code = m.persn_legal_bk_code             -- 法人机构一致
       AND b.data_date           = v_sysdat                          -- 取跑批日期当日余额
       AND b.bal_type            = '2'                               -- 余额类型为月日均
     WHERE s.term_begin_date = V_NEXT_DAY                            -- 仅取开始日期为今日的范围
       AND s.indx_code IN ('INDX_0052','INDX_0053','INDX_0054','INDX_0063')  -- 仅需冻结明细的指标
       AND (s.indx_code NOT IN ('INDX_0052','INDX_0053','INDX_0054') OR lv.cust_id IS NOT NULL)  -- 需客户等级的指标必须能取到层级(内连接效果)
       AND (s.indx_code <> 'INDX_0063' OR b.cust_id IS NOT NULL)     -- 需AUM的指标必须能取到余额(内连接效果)
       AND NOT EXISTS (                                              -- 过滤已冻结的明细,避免重复
           SELECT 1
             FROM ADS_STAT_INDX_BASELINE_DTL d                   -- 冻结明细表
            WHERE d.statis_calib        = CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END  -- 口径一致
              AND d.statis_dim          = s.statis_dim           -- 维度一致
              AND d.indx_code           = s.indx_code            -- 指标一致
              AND d.data_blng           = s.data_blng            -- 归属一致
              AND d.cust_id             = m.cust_id              -- 客户一致
              AND d.persn_legal_bk_code = m.persn_legal_bk_code  -- 法人机构一致
       );

    -------------------------------------------------------------------------
    -- 3.3 冻结汇总表 ADS_STAT_INDX_BASELINE_SUM
    -------------------------------------------------------------------------
    INSERT INTO ADS_STAT_INDX_BASELINE_SUM (                            -- 插入冻结汇总表
        statis_calib, statis_dim, indx_code, data_blng, persn_legal_bk_code,  -- 统计口径、统计维度、指标代码、数据归属、法人机构编号
        base_data_date, base_run_date, base_loan_bal, base_yr_avg_fin,  -- 基准数据日期、基准跑批日期、基准贷款余额、基准年日均金融资产
        base_mth_avg_fin, base_yr_avg_agen_fin, base_mth_avg_agen_fin,  -- 基准月日均金融资产、基准年日均代发金融资产、基准月日均代发金融资产
        base_fin_bal, base_agen_fin_bal,                                -- 基准金融资产余额、基准代发金融资产余额
        base_yr_avg_depo, base_mth_avg_depo                             -- 基准年日均存款、基准月日均存款(v4.6新增)
    )
    SELECT CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END,                                                     -- 路径映射统计口径
           s.statis_dim,                                                                                                -- 统计维度
           s.indx_code,                                                                                                 -- 指标代码
           s.data_blng,                                                                                                 -- 数据归属
           s.persn_legal_bk_code,                                                                                       -- 法人机构编号
           MAX(m.base_data_date),                                                                                       -- 取最大基准数据日期
           v_sysdat,                                                                                                    -- 基准跑批日期=跑批日期
           SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.loan_bal, 0) ELSE 0 END),                                          -- 贷款余额(余额类型=贷款)
           SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.fin_bal, 0) ELSE 0 END),                                           -- 年日均金融资产(余额类型=年日均)
           SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.fin_bal, 0) ELSE 0 END),                                           -- 月日均金融资产(余额类型=月日均)
           SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END),  -- 年日均代发金融资产(未代发+已代发余额)
           SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END),  -- 月日均代发金融资产
           SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.fin_bal, 0) ELSE 0 END),                                           -- 金融资产余额(余额类型=贷款时点为金融资产)
           SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END),  -- 代发金融资产余额
           SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.depo_bal, 0) ELSE 0 END),                                          -- 年日均存款
           SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.depo_bal, 0) ELSE 0 END)                                           -- 月日均存款
      FROM TMP_STAT_INDX_SCOPE s                                                                                        -- 指标范围临时表
     INNER JOIN ADS_STAT_INDX_BASELINE_MEMBER m                                                                         -- 关联已冻结的成员基准
        ON m.statis_calib        = CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END                              -- 口径一致
       AND m.statis_dim          = s.statis_dim                                                                         -- 维度一致
       AND m.data_blng           = s.data_blng                                                                          -- 归属一致
       AND m.persn_legal_bk_code = s.persn_legal_bk_code                                                                -- 法人机构一致
      INNER JOIN DWS_CUST_ASSE_LIAB b                                                                                   -- 关联资产负债余额表(仅取有余额的成员)
        ON b.cust_id             = m.cust_id                                                                            -- 客户ID一致
       AND b.persn_legal_bk_code = m.persn_legal_bk_code                                                                -- 法人机构一致
       AND b.data_date           = m.base_data_date                                                                     -- 余额取基准数据日期
     WHERE s.term_begin_date = V_NEXT_DAY                                                                               -- 仅取开始日期为今日的范围
       AND s.indx_code IN ('INDX_0050','INDX_0051','INDX_0055','INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062')  -- 需冻结至汇总表的指标集合
       AND NOT EXISTS (                                                                                                 -- 过滤已冻结的汇总,避免重复
           SELECT 1
             FROM ADS_STAT_INDX_BASELINE_SUM x                   -- 冻结汇总表
            WHERE x.statis_calib        = CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END  -- 口径一致
              AND x.statis_dim          = s.statis_dim           -- 维度一致
              AND x.indx_code           = s.indx_code            -- 指标一致
              AND x.data_blng           = s.data_blng            -- 归属一致
              AND x.persn_legal_bk_code = s.persn_legal_bk_code  -- 法人机构一致
       )
     GROUP BY s.path_code, s.statis_dim, s.indx_code, s.data_blng, s.persn_legal_bk_code;  -- 按路径/维度/指标/归属/法人机构分组汇总



    -------------------------------------------------------------------------
    -- 3.3b 存量活动0050/0051基准补跑(v4.6)
    --     活动已开始但缺少0050/0051冻结基准时,按当日最新快照补建基准
    -------------------------------------------------------------------------
    INSERT INTO ADS_STAT_INDX_BASELINE_SUM (                                -- 补跑插入冻结汇总表(仅存款基准)
        statis_calib, statis_dim, indx_code, data_blng, persn_legal_bk_code,-- 统计口径、统计维度、指标代码、数据归属、法人机构编号
        base_data_date, base_run_date, base_yr_avg_depo, base_mth_avg_depo  -- 基准数据日期、基准跑批日期、基准年日均存款、基准月日均存款
    )
    WITH scope_member AS (  -- 组装存量活动范围内成员
        -- 路径08：营销活动成员
        SELECT s.path_code, s.statis_dim, s.indx_code, s.data_blng,  -- 路径代码、统计维度、指标代码、数据归属
               s.term_begin_date, ti.cust_id, s.persn_legal_bk_code  -- 开始日期、客户ID、法人机构编号
          FROM TMP_STAT_INDX_SCOPE s                                 -- 指标范围临时表
         INNER JOIN DWD_MKT_TSK_INFO ti                              -- 关联营销活动任务信息
            ON s.path_code             = '08'                         -- 限定路径08(营销活动)
           AND ti.mkt_act_id           = s.statis_dim                -- 活动ID等于统计维度
           AND ti.persn_legal_bk_code  = s.persn_legal_bk_code       -- 法人机构一致
           AND ti.data_date            = v_sysdat                    -- 取跑批日期当日活动信息
           AND ((s.blng_type = 'O' AND ti.mkt_persn_org = s.blng_id) -- 按机构归属匹配
             OR (s.blng_type = 'M' AND ti.mkt_persn     = s.blng_id))-- 按客户经理归属匹配
         WHERE s.term_begin_date < v_sysdat                          -- 仅取已开始(存量)的活动范围
           AND s.indx_code IN ('INDX_0050','INDX_0051')              -- 仅补跑0050/0051指标
        UNION                                                        -- 合并
        -- 路径09-机构归属成员
        SELECT s.path_code, s.statis_dim, s.indx_code, s.data_blng,  -- 路径代码、统计维度、指标代码、数据归属
               s.term_begin_date, lv.cust_id, s.persn_legal_bk_code  -- 开始日期、客户ID、法人机构编号
          FROM TMP_STAT_INDX_SCOPE s                            -- 指标范围临时表
         INNER JOIN DWS_CUST_LVL_INFO lv                        -- 关联客户层级信息
            ON s.path_code             = '09'                    -- 限定路径09
           AND s.blng_type             = 'O'                    -- 归属类型为机构
           AND lv.org_id               = s.blng_id              -- 机构ID一致
           AND lv.persn_legal_bk_code  = s.persn_legal_bk_code  -- 法人机构一致
           AND lv.data_date            = v_sysdat               -- 取跑批日期当日层级
         WHERE s.term_begin_date < v_sysdat                     -- 仅取已开始范围
           AND s.indx_code IN ('INDX_0050','INDX_0051')         -- 仅补跑0050/0051
        UNION                                                   -- 合并
        -- 路径09-客户经理归属成员
        SELECT s.path_code, s.statis_dim, s.indx_code, s.data_blng,  -- 路径代码、统计维度、指标代码、数据归属
               s.term_begin_date, cm.cust_id, s.persn_legal_bk_code  -- 开始日期、客户ID、法人机构编号
          FROM TMP_STAT_INDX_SCOPE s                            -- 指标范围临时表
         INNER JOIN DWD_CUST_MAN cm                             -- 关联客户经理归属表
            ON s.path_code             = '09'                    -- 限定路径09
           AND s.blng_type             = 'M'                    -- 归属类型为客户经理
           AND cm.mngr_post_id         = s.blng_id              -- 客户经理岗位ID一致
           AND cm.mng_typ              = '1'                    -- 客户经理类型主号
           AND cm.persn_legal_bk_code  = s.persn_legal_bk_code  -- 法人机构一致
         WHERE s.term_begin_date < v_sysdat                     -- 仅取已开始范围
           AND s.indx_code IN ('INDX_0050','INDX_0051')         -- 仅补跑0050/0051
    )
    SELECT CASE WHEN sm.path_code = '08' THEN '08' ELSE '09' END,  -- 路径映射统计口径
           sm.statis_dim,                                             -- 统计维度
           sm.indx_code,                                              -- 指标代码
           sm.data_blng,                                              -- 数据归属
           sm.persn_legal_bk_code,                                    -- 法人机构编号
           v_sysdat,                                                  -- 基准数据日期=跑批日期
           v_sysdat,                                                  -- 基准跑批日期=跑批日期
           SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.depo_bal, 0) ELSE 0 END),  -- 年日均存款
           SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.depo_bal, 0) ELSE 0 END)  -- 月日均存款
      FROM scope_member sm                                            -- 范围成员结果集
     INNER JOIN DWS_CUST_ASSE_LIAB b                                  -- 关联资产负债余额表
        ON b.cust_id             = sm.cust_id                         -- 客户ID一致
       AND b.persn_legal_bk_code = sm.persn_legal_bk_code             -- 法人机构一致
       AND b.data_date           = v_sysdat                           -- 取跑批日期当日余额
     WHERE NOT EXISTS (                                               -- 过滤已存在基准,避免重复补跑
         SELECT 1
           FROM ADS_STAT_INDX_BASELINE_SUM x                    -- 冻结汇总表
          WHERE x.statis_calib        = CASE WHEN sm.path_code = '08' THEN '08' ELSE '09' END  -- 口径一致
            AND x.statis_dim          = sm.statis_dim           -- 维度一致
            AND x.indx_code           = sm.indx_code            -- 指标一致
            AND x.data_blng           = sm.data_blng            -- 归属一致
            AND x.persn_legal_bk_code = sm.persn_legal_bk_code  -- 法人机构一致
     )
     GROUP BY sm.path_code, sm.statis_dim, sm.indx_code, sm.data_blng, sm.persn_legal_bk_code;  -- 按路径/维度/指标/归属/机构分组汇总


    -------------------------------------------------------------------------
    -- 3.4 个贷新形成不良贷款率期初基准(0066)
    --     活动开始前一天冻结正常(1)/关注(2)贷款账户为基准, 后续沿用不重建
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_LOAN_BASE (                 -- 插入个贷贷款期初基准临时表
        path_code, statis_dim, data_blng, persn_legal_bk_code,  -- 路径代码、统计维度、数据归属、法人机构编号
        cust_id, acct_id, loan_bal, cate_5lvl, base_date  -- 客户ID、账户ID、贷款余额、五级分类、基准日期
    )
    WITH scope_cust AS (                                              -- 组装0066指标范围内客户
        SELECT s.path_code, s.statis_dim, s.data_blng, s.persn_legal_bk_code, ti.cust_id  -- 路径/维度/归属/机构及客户ID
          FROM TMP_STAT_INDX_SCOPE s                                  -- 指标范围临时表
         INNER JOIN DWD_MKT_TSK_INFO ti                               -- 关联营销活动任务信息
            ON ti.mkt_act_id           = s.statis_dim                 -- 活动ID等于统计维度
           AND ti.persn_legal_bk_code  = s.persn_legal_bk_code        -- 法人机构一致
           AND ti.data_date            = v_sysdat                     -- 取跑批日期当日活动信息
           AND ((s.blng_type = 'O' AND ti.mkt_persn_org = s.blng_id)  -- 按机构归属匹配
             OR (s.blng_type = 'M' AND ti.mkt_persn     = s.blng_id)) -- 按客户经理归属匹配
         WHERE s.term_begin_date = V_NEXT_DAY                         -- 仅取开始日期为今日的范围
           AND s.path_code       = '08'                                -- 限定路径08(营销活动)
           AND s.indx_code       = 'INDX_0066'                        -- 仅取0066指标
        UNION                                                         -- 合并
        SELECT s.path_code, s.statis_dim, s.data_blng, s.persn_legal_bk_code, lv.cust_id  -- 路径/维度/归属/机构及客户ID
          FROM TMP_STAT_INDX_SCOPE s                                  -- 指标范围临时表
         INNER JOIN DWS_CUST_LVL_INFO lv                              -- 关联客户层级信息
            ON lv.org_id              = s.blng_id                     -- 机构ID一致
           AND lv.persn_legal_bk_code = s.persn_legal_bk_code         -- 法人机构一致
           AND lv.data_date           = v_sysdat                      -- 取跑批日期当日层级
         WHERE s.term_begin_date = V_NEXT_DAY                         -- 仅取开始日期为今日的范围
           AND s.path_code       = '09'                                -- 限定路径09
           AND s.blng_type       = 'O'                                -- 归属类型为机构
           AND s.indx_code       = 'INDX_0066'                        -- 仅取0066指标
        UNION                                                         -- 合并
        SELECT s.path_code, s.statis_dim, s.data_blng, s.persn_legal_bk_code, cm.cust_id  -- 路径/维度/归属/机构及客户ID
          FROM TMP_STAT_INDX_SCOPE s                                  -- 指标范围临时表
         INNER JOIN DWD_CUST_MAN cm                                   -- 关联客户经理归属表
            ON cm.mngr_post_id        = s.blng_id                     -- 客户经理岗位ID一致
           AND cm.mng_typ             = '1'                           -- 客户经理类型主号
           AND cm.persn_legal_bk_code = s.persn_legal_bk_code         -- 法人机构一致
         WHERE s.term_begin_date = V_NEXT_DAY                         -- 仅取开始日期为今日的范围
           AND s.path_code       = '09'                                -- 限定路径09
           AND s.blng_type       = 'M'                                -- 归属类型为客户经理
           AND s.indx_code       = 'INDX_0066'                        -- 仅取0066指标
    )
    SELECT sc.path_code, sc.statis_dim, sc.data_blng, sc.persn_legal_bk_code,  -- 路径/维度/归属/机构
           a.cust_id, a.acct_id, a.bal, a.cate_5lvl, v_sysdat  -- 客户ID、账户ID、贷款余额、五级分类、基准日期
      FROM scope_cust sc                                       -- 范围内客户
     INNER JOIN DWD_ACCT_LOAN a                                -- 关联个贷账户表(仅取有贷款账户的客户)
        ON a.cust_id             = sc.cust_id                  -- 客户ID一致
       AND a.persn_legal_bk_code = sc.persn_legal_bk_code      -- 法人机构一致
       AND a.cate_5lvl IN ('1', '2')                           -- 仅取五级分类为正常(1)、关注(2)的账户
     WHERE NOT EXISTS (                                        -- 过滤已建立的期初基准,不重复(后续沿用不重建)
         SELECT 1 FROM TMP_STAT_INDX_LOAN_BASE b               -- 个贷期初基准临时表
          WHERE b.path_code           = sc.path_code           -- 路径一致
            AND b.statis_dim          = sc.statis_dim          -- 维度一致
            AND b.data_blng           = sc.data_blng           -- 归属一致
            AND b.persn_legal_bk_code = sc.persn_legal_bk_code -- 法人机构一致
            AND b.cust_id             = sc.cust_id             -- 客户一致
     );

    -------------------------------------------------------------------------
    -- 清理仅用于冻结的范围数据
    -- 清理仅用于冻结的范围数据
    -------------------------------------------------------------------------
    DELETE FROM TMP_STAT_INDX_SCOPE WHERE term_begin_date = V_NEXT_DAY;  -- 删除开始日期为今日的范围数据(冻结用毕即清)

    -------------------------------------------------------------------------
    -- 缺失基准强校验
    -------------------------------------------------------------------------
    SELECT COUNT(*) INTO V_MISSING_CNT                                                               -- 统计缺失基准行数
      FROM TMP_STAT_INDX_SCOPE s                                                                     -- 指标范围临时表
     WHERE s.indx_code IN ('INDX_0050','INDX_0051','INDX_0052','INDX_0053','INDX_0054','INDX_0055',  -- 需校验的指标集合
                           'INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062','INDX_0063')  -- 其余校验指标
       AND (                                                                                         -- 分两类校验其对应冻结表是否有基准
           (s.indx_code IN ('INDX_0052','INDX_0053','INDX_0054','INDX_0063')                         -- 明细类指标
            AND NOT EXISTS (                                                                         -- 明细表中无对应基准
                SELECT 1 FROM ADS_STAT_INDX_BASELINE_DTL d                                           -- 冻结明细表
                 WHERE d.statis_calib        = CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END  -- 口径一致
                   AND d.statis_dim          = s.statis_dim                                          -- 维度一致
                   AND d.indx_code           = s.indx_code                                           -- 指标一致
                   AND d.data_blng           = s.data_blng                                           -- 归属一致
                   AND d.persn_legal_bk_code = s.persn_legal_bk_code                                 -- 法人机构一致
            ))
           OR
           (s.indx_code IN ('INDX_0050','INDX_0051','INDX_0055','INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062')  -- 汇总类指标
            AND NOT EXISTS (                                                                            -- 汇总表中无对应基准
                SELECT 1 FROM ADS_STAT_INDX_BASELINE_SUM b                                              -- 冻结汇总表
                 WHERE b.statis_calib        = CASE WHEN s.path_code = '08' THEN '08' ELSE '09' END  -- 口径一致
                   AND b.statis_dim          = s.statis_dim                                             -- 维度一致
                   AND b.indx_code           = s.indx_code                                              -- 指标一致
                   AND b.data_blng           = s.data_blng                                              -- 归属一致
                   AND b.persn_legal_bk_code = s.persn_legal_bk_code                                    -- 法人机构一致
            ))
       );

    IF V_MISSING_CNT > 0 THEN            -- 存在缺失基准则报错
        RAISE_APPLICATION_ERROR(-20002,  -- 抛强校验错误
            '已开始活动/任务缺少开始前一天冻结的基准数据，严禁在活动期间补建基准');  -- 错误提示：禁止活动期间补建基准
    END IF;
    outcde := SQL%ROWCOUNT;                                   -- 输出影响行数
    COMMIT;                                                   -- 提交事务
    V_END_DATE := SYSDATE;                                    -- 记录结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时(秒)
    V_LOG_MSG := '步骤2处理完成，行数=' || NVL(outcde, 0);             -- 拼装成功日志消息
    V_LOG_FLG := 0;                                           -- 成功标志
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 调用通用跑批日志过程写成功日志
EXCEPTION
    WHEN OTHERS THEN                                              -- 异常捕获
        ROLLBACK;                                                 -- 回滚事务
        outcde := -1;                                             -- 输出错误标志
        V_END_DATE := SYSDATE;                                    -- 记录结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算耗时
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 取错误信息前1000字符
        V_LOG_FLG := -1;                                          -- 失败标志
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 调用通用跑批日志过程写失败日志
        RAISE;                                                    -- 重新抛出异常
END prc_ads_stat_indx_plan_002
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_003(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_003(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC   VARCHAR2(100) := '指标数据统计步骤3';   -- 过程描述,用于日志
    V_PRC_NAME   VARCHAR2(32)  := 'PRC_ADS_STAT_INDX_PLAN_003';   -- 过程名称,用于日志
    V_LOG_MSG    VARCHAR2(4000);  -- 日志消息
    V_LOG_FLG    INTEGER;         -- 日志标志(0成功/-1失败)
    V_LOG_BUTTON INTEGER := 1;    -- 日志按钮,1启用步骤日志
    V_NO_ID      VARCHAR2(10);    -- 日志序号标识
    V_BGN_DATE   DATE;            -- 过程开始时间
    V_END_DATE   DATE;            -- 过程结束时间
    V_DURA_DATE  INTEGER;         -- 过程耗时(秒)
    V_MTH_BEGIN    VARCHAR2(8);   -- 当月月初
    V_MTH_END      VARCHAR2(8);   -- 上月月末
    V_QRT_END      VARCHAR2(8);   -- 上季末
    V_YAR_BEGIN    VARCHAR2(8);   -- 当年初
BEGIN
    -------------------------------------------------------------------------
    -- 标准模板：参数校验与开始日志状态
    -------------------------------------------------------------------------
    V_NO_ID := '0';                                                -- 初始化日志序号
    V_BGN_DATE := SYSDATE;                                         -- 记录过程开始时间
    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN   -- 校验业务日期为非空8位数字
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 格式非法报错
    END IF;

    -- 段首自清：本过程专属汇总临时表,防止重跑/并行残留
    DELETE FROM TMP_STAT_INDX_AGGR_003;

    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 业务日期字符串转日期型

    -------------------------------------------------------------------------
    -- 初始化日期边界
    -------------------------------------------------------------------------
    V_MTH_BEGIN    := sys_fun_deal_date(v_sysdat, 9);  -- 当月月初
    V_MTH_END      := sys_fun_deal_date(v_sysdat, 2);  -- 上月月末
    V_QRT_END      := sys_fun_deal_date(v_sysdat, 3);  -- 上季末
    V_YAR_BEGIN    := sys_fun_deal_date(v_sysdat, 13); -- 当年初

    -------------------------------------------------------------------------
    -- 4.1 余额预聚合到 TMP_STAT_INDX_BAL_AGGR
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_BAL_AGGR (
        path_code, statis_dim, data_blng, persn_legal_bk_code,   -- 路径编码, 统计维度, 归属机构, 法人行号
        curnt_aum, yr_begin_aum, mth_end_aum, qrt_end_aum,  -- 当期AUM, 年期初AUM, 月期末AUM, 季期末AUM
        curnt_yr_avg_aum, curnt_mth_avg_aum                 -- 当年日均AUM, 当月日均AUM
    )
    WITH base_scope AS (
        SELECT DISTINCT path_code, statis_dim, data_blng,          -- 路径编码, 统计维度, 归属机构
               blng_type, blng_id, persn_legal_bk_code             -- 归属类型, 归属ID, 法人行号
          FROM TMP_STAT_INDX_SCOPE                                 -- 指标统计范围表
         WHERE indx_code IN ('INDX_0046','INDX_0047','INDX_0048',  -- 仅取存款类AUM相关指标
                             'INDX_0049','INDX_0050','INDX_0051')  -- 承上：其余存款类AUM指标
           AND (indx_code <> 'INDX_0047' OR blng_type = 'O')       -- INDX_0047 仅机构维度口径
    ),
    scope_member AS (
        -- 路径08：营销活动成员
        SELECT s.path_code, s.statis_dim, s.data_blng,                -- 路径编码, 统计维度, 归属机构
               ti.cust_id, s.persn_legal_bk_code                      -- 客户ID, 法人行号
          FROM base_scope s                                           -- 复用统计范围CTE
         INNER JOIN DWD_MKT_TSK_INFO ti                               -- 营销任务信息表
            ON s.path_code             = '08'                          -- 限定路径08
           AND ti.mkt_act_id           = s.statis_dim                 -- 任务活动ID=统计维度
           AND ti.persn_legal_bk_code  = s.persn_legal_bk_code        -- 法人行号一致
           AND ti.data_date            = v_sysdat                     -- 任务数据日期=跑批日期
           AND ((s.blng_type = 'O' AND ti.mkt_persn_org = s.blng_id)  -- 机构口径按机构归属匹配
             OR (s.blng_type = 'M' AND ti.mkt_persn     = s.blng_id)) -- 客户经理口径按客户经理匹配

        UNION

        -- 路径09-机构归属
        SELECT s.path_code, s.statis_dim, s.data_blng,  -- 路径编码, 统计维度, 归属机构
               lv.cust_id, s.persn_legal_bk_code        -- 客户ID, 法人行号
          FROM base_scope s                             -- 复用统计范围CTE
         INNER JOIN DWS_CUST_LVL_INFO lv                -- 客户层级信息表
            ON s.path_code             = '09'            -- 限定路径09
           AND s.blng_type             = 'O'            -- 只取机构口径
           AND lv.org_id               = s.blng_id      -- 客户所属机构=归属ID
           AND lv.persn_legal_bk_code  = s.persn_legal_bk_code   -- 法人行号一致
           AND lv.data_date            = v_sysdat       -- 数据日期=跑批日期

        UNION

        -- 路径09-客户经理归属
        SELECT s.path_code, s.statis_dim, s.data_blng,  -- 路径编码, 统计维度, 归属机构
               cm.cust_id, s.persn_legal_bk_code        -- 客户ID, 法人行号
          FROM base_scope s                             -- 复用统计范围CTE
         INNER JOIN DWD_CUST_MAN cm                     -- 客户管户关系表
            ON s.path_code             = '09'            -- 限定路径09
           AND s.blng_type             = 'M'            -- 只取客户经理口径
           AND cm.mngr_post_id         = s.blng_id      -- 管户经理岗位ID=归属ID
           AND cm.mng_typ              = '1'            -- 主管类型1(主管户)
           AND cm.persn_legal_bk_code  = s.persn_legal_bk_code   -- 法人行号一致
    )
    SELECT sm.path_code,                                      -- 路径编码
           sm.statis_dim,                                     -- 统计维度
           sm.data_blng,                                      -- 归属机构
           sm.persn_legal_bk_code,                            -- 法人行号
           SUM(NVL(b.curnt_aum, 0))         AS curnt_aum,     -- 当期AUM合计=存款余额(type1)
           SUM(NVL(hb.yr_begin_aum, 0))     AS yr_begin_aum,  -- 年期初AUM合计
           SUM(NVL(hb.mth_end_aum, 0))      AS mth_end_aum,   -- 月期末AUM合计
           SUM(NVL(hb.qrt_end_aum, 0))      AS qrt_end_aum,   -- 季期末AUM合计
           SUM(NVL(b.curnt_yr_avg_aum, 0))  AS curnt_yr_avg_aum,   -- 当年日均AUM合计
           SUM(NVL(b.curnt_mth_avg_aum, 0)) AS curnt_mth_avg_aum   -- 当月日均AUM合计
      FROM scope_member sm                                    -- 成员明细CTE
      LEFT JOIN (
          SELECT cust_id,                                                                             -- 客户ID
                 persn_legal_bk_code,                                                                 -- 法人行号
                 SUM(CASE WHEN bal_type = '1' THEN NVL(depo_bal, 0) ELSE 0 END) AS curnt_aum,         -- 存款余额(type1)=当期AUM
                 SUM(CASE WHEN bal_type = '4' THEN NVL(depo_bal, 0) ELSE 0 END) AS curnt_yr_avg_aum,  -- 当年日均存款(type4)
                 SUM(CASE WHEN bal_type = '2' THEN NVL(depo_bal, 0) ELSE 0 END) AS curnt_mth_avg_aum  -- 当月日均存款(type2)
            FROM DWS_CUST_ASSE_LIAB                                                                   -- 客户资产负债表(当日)
           WHERE data_date = v_sysdat                                                                 -- 取跑批日数据
             AND EXISTS (SELECT 1 FROM scope_member sm2                                               -- 成员明细CTE2   -- 仅统计范围内客户
                          WHERE sm2.cust_id = DWS_CUST_ASSE_LIAB.cust_id                              -- 匹配客户ID
                            AND sm2.persn_legal_bk_code = DWS_CUST_ASSE_LIAB.persn_legal_bk_code)     -- 匹配法人行号
           GROUP BY cust_id, persn_legal_bk_code
      ) b
        ON b.cust_id             = sm.cust_id  -- 按客户ID关联
       AND b.persn_legal_bk_code = sm.persn_legal_bk_code   -- 法人行号一致
      LEFT JOIN (
          SELECT cust_id,                                                                         -- 客户ID
                 persn_legal_bk_code,                                                             -- 法人行号
                 SUM(CASE WHEN data_date = V_YAR_BEGIN                                            -- 年初日
                            AND bal_type = '1' THEN NVL(depo_bal, 0) ELSE 0 END) AS yr_begin_aum, -- 年期初存款余额
                 SUM(CASE WHEN data_date = V_MTH_END                                              -- 月末日
                            AND bal_type = '1' THEN NVL(depo_bal, 0) ELSE 0 END) AS mth_end_aum,  -- 月期末存款余额
                 SUM(CASE WHEN data_date = V_QRT_END                                              -- 季末日
                            AND bal_type = '1' THEN NVL(depo_bal, 0) ELSE 0 END) AS qrt_end_aum   -- 季期末存款余额
            FROM DWS_CUST_ASSE_LIAB_HIS                                                           -- 客户资产负债历史表
           WHERE data_date IN (V_YAR_BEGIN, V_MTH_END, V_QRT_END)                                 -- 取年初/月末/季末时点
             AND EXISTS (SELECT 1 FROM scope_member sm2                                           -- 成员明细CTE2   -- 仅统计范围内客户
                          WHERE sm2.cust_id = DWS_CUST_ASSE_LIAB_HIS.cust_id                      -- 匹配客户ID
                            AND sm2.persn_legal_bk_code = DWS_CUST_ASSE_LIAB_HIS.persn_legal_bk_code)   -- 匹配法人行号
           GROUP BY cust_id, persn_legal_bk_code
      ) hb
        ON hb.cust_id             = sm.cust_id              -- 按客户ID关联
       AND hb.persn_legal_bk_code = sm.persn_legal_bk_code  -- 法人行号一致
     GROUP BY sm.path_code, sm.statis_dim, sm.data_blng, sm.persn_legal_bk_code;   -- 按路径/维度/机构/法人行汇总

    -------------------------------------------------------------------------
    -- 4.2 标准期间增量写入(INDX_0046/0048/0049/0050/0051)- 路径08
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_003 (
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径, 数据日期, 归属机构, 统计维度, 统计口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标编码, 当期值, 上期值, 法人行号
    )
    SELECT '08', v_sysdat, s.data_blng, s.statis_dim, '08', s.indx_code,      -- 路径08/数据日期/归属机构/统计维度/口径/指标编码
           CASE s.indx_code                                                    -- 按指标编码取当期标准期间增量
               WHEN 'INDX_0046' THEN b.curnt_aum - b.yr_begin_aum              -- 当年存款新增=当期-年期初
               WHEN 'INDX_0048' THEN b.curnt_aum - b.mth_end_aum               -- 当月存款新增=当期-月期初(上月末)
               WHEN 'INDX_0049' THEN b.curnt_aum - b.qrt_end_aum               -- 当季存款新增=当期-季期初(上季末)
               WHEN 'INDX_0050' THEN b.curnt_yr_avg_aum - bs.base_yr_avg_depo  -- 当年日均存款增量=当期日均-年度基数日均
               WHEN 'INDX_0051' THEN b.curnt_mth_avg_aum - bs.base_mth_avg_depo-- 当月日均存款增量=当期日均-月份基数日均
           END,
           CASE s.indx_code                               -- 按指标编码取对应上期值
               WHEN 'INDX_0046' THEN b.yr_begin_aum       -- 上期值=年期初
               WHEN 'INDX_0048' THEN b.mth_end_aum        -- 上期值=月期初
               WHEN 'INDX_0049' THEN b.qrt_end_aum        -- 上期值=季期初
               WHEN 'INDX_0050' THEN bs.base_yr_avg_depo  -- 上期值=年度基数日均
               WHEN 'INDX_0051' THEN bs.base_mth_avg_depo -- 上期值=月份基数日均
           END,
           s.persn_legal_bk_code                          -- 法人行号
      FROM TMP_STAT_INDX_SCOPE s                          -- 指标统计范围表
     INNER JOIN TMP_STAT_INDX_BAL_AGGR b                  -- 余额预聚合表
        ON b.path_code           = '08'                    -- 只取路径08余额
       AND b.statis_dim          = s.statis_dim           -- 统计维度一致
       AND b.data_blng           = s.data_blng            -- 归属机构一致
       AND b.persn_legal_bk_code = s.persn_legal_bk_code  -- 法人行号一致
      LEFT JOIN ADS_STAT_INDX_BASELINE_SUM bs             -- 指标存款基数汇总表
        ON bs.statis_calib        = '08'                -- 统计口径=营销活动
       AND bs.statis_dim          = s.statis_dim          -- 统计维度一致
       AND bs.indx_code           = s.indx_code           -- 指标编码一致
       AND bs.data_blng           = s.data_blng           -- 归属机构一致
       AND bs.persn_legal_bk_code = s.persn_legal_bk_code -- 法人行号一致
     WHERE s.path_code = '08'                              -- 仅路径08
       AND s.indx_code IN ('INDX_0046','INDX_0048','INDX_0049','INDX_0050','INDX_0051');   -- 仅标准期间指标

    -------------------------------------------------------------------------
    -- 4.2 标准期间增量写入(INDX_0046/0048/0049/0050/0051)- 路径09
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_003 (
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径, 数据日期, 归属机构, 统计维度, 统计口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标编码, 当期值, 上期值, 法人行号
    )
    SELECT '09', v_sysdat, s.data_blng, s.statis_dim, '09', s.indx_code,
           CASE s.indx_code                                                    -- 按指标编码取当期标准期间增量
               WHEN 'INDX_0046' THEN b.curnt_aum - b.yr_begin_aum              -- 当年存款新增=当期-年期初
               WHEN 'INDX_0048' THEN b.curnt_aum - b.mth_end_aum               -- 当月存款新增=当期-月期初
               WHEN 'INDX_0049' THEN b.curnt_aum - b.qrt_end_aum               -- 当季存款新增=当期-季期初
               WHEN 'INDX_0050' THEN b.curnt_yr_avg_aum - bs.base_yr_avg_depo  -- 当年日均存款增量
               WHEN 'INDX_0051' THEN b.curnt_mth_avg_aum - bs.base_mth_avg_depo-- 当月日均存款增量
           END,
           CASE s.indx_code                               -- 按指标编码取对应上期值
               WHEN 'INDX_0046' THEN b.yr_begin_aum       -- 上期值=年期初
               WHEN 'INDX_0048' THEN b.mth_end_aum        -- 上期值=月期初
               WHEN 'INDX_0049' THEN b.qrt_end_aum        -- 上期值=季期初
               WHEN 'INDX_0050' THEN bs.base_yr_avg_depo  -- 上期值=年度基数日均
               WHEN 'INDX_0051' THEN bs.base_mth_avg_depo -- 上期值=月份基数日均
           END,
           s.persn_legal_bk_code                          -- 法人行号
      FROM TMP_STAT_INDX_SCOPE s                          -- 指标统计范围表
     INNER JOIN TMP_STAT_INDX_BAL_AGGR b                  -- 余额预聚合表
        ON b.path_code           = '09'                    -- 只取路径09余额
       AND b.statis_dim          = s.statis_dim           -- 统计维度一致
       AND b.data_blng           = s.data_blng            -- 归属机构一致
       AND b.persn_legal_bk_code = s.persn_legal_bk_code  -- 法人行号一致
      LEFT JOIN ADS_STAT_INDX_BASELINE_SUM bs             -- 指标存款基数汇总表
        ON bs.statis_calib        = '09'                -- 统计口径=目标任务
       AND bs.statis_dim          = s.statis_dim          -- 统计维度一致
       AND bs.indx_code           = s.indx_code           -- 指标编码一致
       AND bs.data_blng           = s.data_blng           -- 归属机构一致
       AND bs.persn_legal_bk_code = s.persn_legal_bk_code -- 法人行号一致
     WHERE s.path_code = '09'                              -- 仅路径09
       AND s.indx_code IN ('INDX_0046','INDX_0048','INDX_0049','INDX_0050','INDX_0051');   -- 仅标准期间指标

    -------------------------------------------------------------------------
    -- 4.3 存款基数扣减指标 INDX_0047 - 路径08(仅机构维度)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_003 (
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径, 数据日期, 归属机构, 统计维度, 统计口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标编码, 当期值, 上期值, 法人行号
    )
    SELECT '08', v_sysdat, s.data_blng, s.statis_dim, '08', 'INDX_0047',   -- 路径08/数据日期/归属机构/统计维度/口径/固定指标0047
           CASE WHEN SUM(v.value_init) IS NULL THEN NULL           -- 基数缺失时当期值置NULL
                ELSE b.curnt_aum - SUM(NVL(v.value_init, 0)) END,  -- 指标当期值=当期AUM-存款基数
           SUM(v.value_init),                                      -- 上期值=存款基数合计
           s.persn_legal_bk_code                                   -- 法人行号
      FROM TMP_STAT_INDX_SCOPE s                                   -- 指标统计范围表
     INNER JOIN TMP_STAT_INDX_BAL_AGGR b                           -- 余额预聚合表
        ON b.path_code           = '08'                             -- 只取路径08余额
       AND b.statis_dim          = s.statis_dim                    -- 统计维度一致
       AND b.data_blng           = s.data_blng                     -- 归属机构一致
       AND b.persn_legal_bk_code = s.persn_legal_bk_code           -- 法人行号一致
      LEFT JOIN DWD_DEPO_VALUE_INIT v                              -- 存款基数初始化表
        ON v.org_id = s.blng_id                                    -- 按机构ID关联
     WHERE s.path_code = '08'                                       -- 仅路径08
       AND s.blng_type = 'O'                                       -- 仅机构口径
       AND s.indx_code = 'INDX_0047'                               -- 仅存款基数扣减指标
     GROUP BY s.data_blng, s.statis_dim, b.curnt_aum, s.persn_legal_bk_code;   -- 按维度/机构/当期AUM/法人行聚合

    -------------------------------------------------------------------------
    -- 4.3 存款基数扣减指标 INDX_0047 - 路径09(仅机构维度)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_003 (
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径, 数据日期, 归属机构, 统计维度, 统计口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标编码, 当期值, 上期值, 法人行号
    )
    SELECT '09', v_sysdat, s.data_blng, s.statis_dim, '09', 'INDX_0047',   -- 路径09/数据日期/归属机构/统计维度/口径/固定指标0047
           CASE WHEN SUM(v.value_init) IS NULL THEN NULL           -- 基数缺失时当期值置NULL
                ELSE b.curnt_aum - SUM(NVL(v.value_init, 0)) END,  -- 指标当期值=当期AUM-存款基数
           SUM(v.value_init),                                      -- 上期值=存款基数合计
           s.persn_legal_bk_code                                   -- 法人行号
      FROM TMP_STAT_INDX_SCOPE s                                   -- 指标统计范围表
     INNER JOIN TMP_STAT_INDX_BAL_AGGR b                           -- 余额预聚合表
        ON b.path_code           = '09'                             -- 只取路径09余额
       AND b.statis_dim          = s.statis_dim                    -- 统计维度一致
       AND b.data_blng           = s.data_blng                     -- 归属机构一致
       AND b.persn_legal_bk_code = s.persn_legal_bk_code           -- 法人行号一致
      LEFT JOIN DWD_DEPO_VALUE_INIT v                              -- 存款基数初始化表
        ON v.org_id = s.blng_id                                    -- 按机构ID关联
     WHERE s.path_code = '09'                                       -- 仅路径09
       AND s.blng_type = 'O'                                       -- 仅机构口径
       AND s.indx_code = 'INDX_0047'                               -- 仅存款基数扣减指标
     GROUP BY s.data_blng, s.statis_dim, b.curnt_aum, s.persn_legal_bk_code;   -- 按维度/机构/当期AUM/法人行聚合

    -------------------------------------------------------------------------
    -- 收尾：本次处理行数回填、提交并记录步骤日志
    -------------------------------------------------------------------------
    outcde := SQL%ROWCOUNT;                                   -- 返回最近DML影响行数
    COMMIT;                                                   -- 提交事务
    V_END_DATE := SYSDATE;                                    -- 记录过程结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
    V_LOG_MSG := '步骤3处理完成，行数=' || NVL(outcde, 0);             -- 组装成功日志消息
    V_LOG_FLG := 0;                                           -- 日志标志置成功
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录步骤日志

    -------------------------------------------------------------------------
    -- 异常处理：回滚并记录错误日志后重抛
    -------------------------------------------------------------------------
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;                                                 -- 异常回滚事务
        outcde := -1;                                             -- 输出行数置-1表示失败
        V_END_DATE := SYSDATE;                                    -- 记录异常结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 截取错误信息
        V_LOG_FLG := -1;                                          -- 日志标志置失败
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录错误日志
        RAISE;                                                    -- 重新抛出异常
END prc_ads_stat_indx_plan_003
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_004(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_004(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC VARCHAR2(100) := '指标数据统计步骤44处理完成 4';  -- 过程描述,用于日志
    V_PRC_NAME VARCHAR2(32) := 'prc_ads_stat_indx_plan_004';   -- 过程名称,用于日志
    V_LOG_MSG VARCHAR2(4000);                        -- 日志消息
    V_LOG_FLG INTEGER;                               -- 日志标志(0成功/-1失败)
    V_LOG_BUTTON INTEGER := 1;                       -- 日志按钮,1启用步骤日志
    V_NO_ID VARCHAR2(10);                            -- 日志序号标识
    V_BGN_DATE DATE;                                 -- 过程开始时间
    V_END_DATE DATE;                                 -- 过程结束时间
    V_DURA_DATE INTEGER;                             -- 过程耗时(秒)
BEGIN
    V_NO_ID := '0';  -- 初始化日志序号
    V_BGN_DATE := SYSDATE;   -- 记录过程开始时间
    -------------------------------------------------------------------------
    -- 参数校验：跑批业务日期格式校验(必须为 8 位数字 YYYYMMDD)
    -------------------------------------------------------------------------
    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN   -- 校验业务日期为非空8位数字
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 格式非法报错
    END IF;

    -- 段首自清：本过程专属汇总临时表,防止重跑/并行残留
    DELETE FROM TMP_STAT_INDX_AGGR_004;
    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 业务日期字符串转日期型
    -------------------------------------------------------------------------
    -- 营销活动路径(A)：理财产品/代销理财/贷款 0055/0056/0057/0058/0059/0060/0062
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_004 (
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径, 数据日期, 归属机构, 统计维度, 统计口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标编码, 当期值, 上期值, 法人行号
    )
    SELECT '08', v_sysdat, s.data_blng, s.statis_dim, '08', s.indx_code,                                                                                                       -- 路径08/数据日期/归属机构/统计维度/口径/指标编码
           CASE s.indx_code                                                                                                                                                     -- 按指标编码取当期增量
               WHEN 'INDX_0055' THEN SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.fin_bal, 0) ELSE 0 END) - MAX(bs.base_yr_avg_fin)                                                -- 当年日均理财增量=当年日均理财-年度基数日均理财
               WHEN 'INDX_0056' THEN SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.fin_bal, 0) ELSE 0 END) - MAX(bs.base_mth_avg_fin)                                               -- 当月日均理财增量=当月日均理财-月份基数日均理财
               WHEN 'INDX_0057' THEN SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.fin_bal, 0) ELSE 0 END) - MAX(bs.base_fin_bal)                                                   -- 当月理财新增=当期理财余额-基数理财余额
               WHEN 'INDX_0058' THEN SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END) - MAX(bs.base_yr_avg_agen_fin)  -- 当年日均代销理财增量
               WHEN 'INDX_0059' THEN SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END) - MAX(bs.base_mth_avg_agen_fin) -- 当月日均代销理财增量
               WHEN 'INDX_0060' THEN SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END) - MAX(bs.base_agen_fin_bal)     -- 当月代销理财新增
               WHEN 'INDX_0062' THEN SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.loan_bal, 0) ELSE 0 END) - MAX(bs.base_loan_bal)                                                 -- 当月贷款新增=当期贷款余额-基数贷款余额
           END,
           CASE s.indx_code                                        -- 按指标编码取对应上期值
               WHEN 'INDX_0055' THEN MAX(bs.base_yr_avg_fin)       -- 上期值=年度基数日均理财
               WHEN 'INDX_0056' THEN MAX(bs.base_mth_avg_fin)      -- 上期值=月份基数日均理财
               WHEN 'INDX_0057' THEN MAX(bs.base_fin_bal)          -- 上期值=基数理财余额
               WHEN 'INDX_0058' THEN MAX(bs.base_yr_avg_agen_fin)  -- 上期值=年度基数日均代销理财
               WHEN 'INDX_0059' THEN MAX(bs.base_mth_avg_agen_fin) -- 上期值=月份基数日均代销理财
               WHEN 'INDX_0060' THEN MAX(bs.base_agen_fin_bal)     -- 上期值=基数代销理财余额
               WHEN 'INDX_0062' THEN MAX(bs.base_loan_bal)         -- 上期值=基数贷款余额
           END,
           s.persn_legal_bk_code                  -- 法人行号
      FROM TMP_STAT_INDX_SCOPE s                  -- 指标统计范围表(路径08源数据)
     INNER JOIN ADS_STAT_INDX_BASELINE_MEMBER d   -- 指标基数成员表
        ON d.statis_calib        = '08'         -- 统计口径=营销活动
       AND d.statis_dim          = s.statis_dim   -- 统计维度一致
       AND d.data_blng           = s.data_blng    -- 归属机构一致
       AND d.persn_legal_bk_code = s.persn_legal_bk_code   -- 法人行号一致
     INNER JOIN ADS_STAT_INDX_BASELINE_SUM bs     -- 指标基数汇总表
        ON bs.statis_calib        = '08'        -- 统计口径=营销活动
       AND bs.statis_dim          = s.statis_dim  -- 统计维度一致
       AND bs.indx_code           = s.indx_code   -- 指标编码一致
       AND bs.data_blng           = s.data_blng   -- 归属机构一致
       AND bs.persn_legal_bk_code = s.persn_legal_bk_code   -- 法人行号一致
      LEFT JOIN (
          SELECT cust_id, persn_legal_bk_code, bal_type, fin_bal,  -- 客户ID, 法人行号, 余额类型, 理财余额
                 close_agen_fin_bal, open_agen_fin_bal, loan_bal   -- 封闭期代销理财余额, 开放期代销理财余额, 贷款余额
            FROM DWS_CUST_ASSE_LIAB                                -- 客户资产负债表(当日)
           WHERE data_date = v_sysdat                              -- 取跑批日数据
             AND EXISTS (SELECT 1 FROM ADS_STAT_INDX_BASELINE_MEMBER d2 WHERE d2.cust_id = DWS_CUST_ASSE_LIAB.cust_id AND d2.persn_legal_bk_code = DWS_CUST_ASSE_LIAB.persn_legal_bk_code)   -- 仅统计基数范围内客户
      ) b
        ON b.cust_id             = d.cust_id                                  -- 按客户ID关联
       AND b.persn_legal_bk_code = d.persn_legal_bk_code                      -- 法人行号一致
     WHERE s.path_code = '08'                                                  -- 仅路径08
       AND s.indx_code IN ('INDX_0055','INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062')   -- 仅理财/贷款类指标
     GROUP BY s.data_blng, s.statis_dim, s.indx_code, s.persn_legal_bk_code;  -- 按机构/维度/指标/法人行聚合

    -------------------------------------------------------------------------
    -- 目标任务路径(B)：理财产品/代销理财/贷款 0055/0056/0057/0058/0059/0060/0062
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_004 (
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径, 数据日期, 归属机构, 统计维度, 统计口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标编码, 当期值, 上期值, 法人行号
    )
    SELECT '09', v_sysdat, s.data_blng, s.statis_dim, '09', s.indx_code,                                                                                                       -- 路径09/数据日期/归属机构/统计维度/口径/指标编码
           CASE s.indx_code                                                                                                                                                     -- 按指标编码取当期增量
               WHEN 'INDX_0055' THEN SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.fin_bal, 0) ELSE 0 END) - MAX(bs.base_yr_avg_fin)                                                -- 当年日均理财增量
               WHEN 'INDX_0056' THEN SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.fin_bal, 0) ELSE 0 END) - MAX(bs.base_mth_avg_fin)                                               -- 当月日均理财增量
               WHEN 'INDX_0057' THEN SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.fin_bal, 0) ELSE 0 END) - MAX(bs.base_fin_bal)                                                   -- 当月理财新增
               WHEN 'INDX_0058' THEN SUM(CASE WHEN b.bal_type = '4' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END) - MAX(bs.base_yr_avg_agen_fin)  -- 当年日均代销理财增量
               WHEN 'INDX_0059' THEN SUM(CASE WHEN b.bal_type = '2' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END) - MAX(bs.base_mth_avg_agen_fin) -- 当月日均代销理财增量
               WHEN 'INDX_0060' THEN SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.close_agen_fin_bal, 0) + NVL(b.open_agen_fin_bal, 0) ELSE 0 END) - MAX(bs.base_agen_fin_bal)     -- 当月代销理财新增
               WHEN 'INDX_0062' THEN SUM(CASE WHEN b.bal_type = '1' THEN NVL(b.loan_bal, 0) ELSE 0 END) - MAX(bs.base_loan_bal)                                                 -- 当月贷款新增
           END,
           CASE s.indx_code                                        -- 按指标编码取对应上期值
               WHEN 'INDX_0055' THEN MAX(bs.base_yr_avg_fin)       -- 上期值=年度基数日均理财
               WHEN 'INDX_0056' THEN MAX(bs.base_mth_avg_fin)      -- 上期值=月份基数日均理财
               WHEN 'INDX_0057' THEN MAX(bs.base_fin_bal)          -- 上期值=基数理财余额
               WHEN 'INDX_0058' THEN MAX(bs.base_yr_avg_agen_fin)  -- 上期值=年度基数日均代销理财
               WHEN 'INDX_0059' THEN MAX(bs.base_mth_avg_agen_fin) -- 上期值=月份基数日均代销理财
               WHEN 'INDX_0060' THEN MAX(bs.base_agen_fin_bal)     -- 上期值=基数代销理财余额
               WHEN 'INDX_0062' THEN MAX(bs.base_loan_bal)         -- 上期值=基数贷款余额
           END,
           s.persn_legal_bk_code                  -- 法人行号
      FROM TMP_STAT_INDX_SCOPE s                  -- 指标统计范围表(路径09源数据)
     INNER JOIN ADS_STAT_INDX_BASELINE_MEMBER d   -- 指标基数成员表
        ON d.statis_calib        = '09'         -- 统计口径=目标任务
       AND d.statis_dim          = s.statis_dim   -- 统计维度一致
       AND d.data_blng           = s.data_blng    -- 归属机构一致
       AND d.persn_legal_bk_code = s.persn_legal_bk_code   -- 法人行号一致
     INNER JOIN ADS_STAT_INDX_BASELINE_SUM bs     -- 指标基数汇总表
        ON bs.statis_calib        = '09'        -- 统计口径=目标任务
       AND bs.statis_dim          = s.statis_dim  -- 统计维度一致
       AND bs.indx_code           = s.indx_code   -- 指标编码一致
       AND bs.data_blng           = s.data_blng   -- 归属机构一致
       AND bs.persn_legal_bk_code = s.persn_legal_bk_code   -- 法人行号一致
      LEFT JOIN (
          SELECT cust_id, persn_legal_bk_code, bal_type, fin_bal,  -- 客户ID, 法人行号, 余额类型, 理财余额
                 close_agen_fin_bal, open_agen_fin_bal, loan_bal   -- 封闭期代销理财余额, 开放期代销理财余额, 贷款余额
            FROM DWS_CUST_ASSE_LIAB                                -- 客户资产负债表(当日)
           WHERE data_date = v_sysdat                              -- 取跑批日数据
             AND EXISTS (SELECT 1 FROM ADS_STAT_INDX_BASELINE_MEMBER d2 WHERE d2.cust_id = DWS_CUST_ASSE_LIAB.cust_id AND d2.persn_legal_bk_code = DWS_CUST_ASSE_LIAB.persn_legal_bk_code)   -- 仅统计基数范围内客户
      ) b
        ON b.cust_id             = d.cust_id                                  -- 按客户ID关联
       AND b.persn_legal_bk_code = d.persn_legal_bk_code                      -- 法人行号一致
     WHERE s.path_code = '09'                                                  -- 仅路径09
       AND s.indx_code IN ('INDX_0055','INDX_0056','INDX_0057','INDX_0058','INDX_0059','INDX_0060','INDX_0062')   -- 仅理财/贷款类指标
     GROUP BY s.data_blng, s.statis_dim, s.indx_code, s.persn_legal_bk_code;  -- 按机构/维度/指标/法人行聚合

    outcde := SQL%ROWCOUNT;  -- 返回最近DML影响行数
    -------------------------------------------------------------------------
    -- 提交事务并记录成功日志
    -------------------------------------------------------------------------
    COMMIT;                                                   -- 提交事务
    V_END_DATE := SYSDATE;                                    -- 记录过程结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
    V_LOG_MSG := '步骤4处理完成，行数=' || NVL(outcde, 0);             -- 组装成功日志消息
    V_LOG_FLG := 0;                                           -- 日志标志置成功
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录步骤日志
EXCEPTION
    -------------------------------------------------------------------------
    -- 异常处理：回滚事务、记录失败日志后向上抛出
    -------------------------------------------------------------------------
    WHEN OTHERS THEN
        ROLLBACK;                                                 -- 异常回滚事务
        outcde := -1;                                             -- 输出行数置-1表示失败
        V_END_DATE := SYSDATE;                                    -- 记录异常结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 截取错误信息
        V_LOG_FLG := -1;                                          -- 日志标志置失败
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录错误日志
        RAISE;                                                    -- 重新抛出异常
END prc_ads_stat_indx_plan_004
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_005(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_005(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC VARCHAR2(100) := '指标数据统计步骤55处理完成 5';  -- 过程描述(写入步骤日志)
    V_PRC_NAME VARCHAR2(32) := 'prc_ads_stat_indx_plan_005';     -- 过程名
    V_LOG_MSG VARCHAR2(4000);                        -- 日志消息内容
    V_LOG_FLG INTEGER;                               -- 日志标志(0正常 -1异常)
    V_LOG_BUTTON INTEGER := 1;                       -- 日志按钮标识(固定1)
    V_NO_ID VARCHAR2(10);                            -- 业务流水号(固定'0')
    V_BGN_DATE DATE;                                 -- 过程起始时间
    V_END_DATE DATE;                                 -- 过程结束时间
    V_DURA_DATE INTEGER;                             -- 运行耗时(秒)
BEGIN
    V_NO_ID := '0';                                                -- 业务流水号(固定'0')
    V_BGN_DATE := SYSDATE;                                         -- 过程起始时间
    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN  -- 校验入参必须为8位数字日期
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 入参非法则抛错
    END IF;

    -- 段首自清：本过程专属汇总临时表,防止重跑/并行残留
    DELETE FROM TMP_STAT_INDX_AGGR_005;
    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 跑批业务日期转 DATE

    -------------------------------------------------------------------------
    -- 段落: 6.1 提取符合提升条件的客户明细
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_CUST_STATE (                   -- 写入客户提升状态明细表
        path_code, statis_dim, indx_code, data_blng, cust_id,-- 路径/维度/指标/数据归属/客户
        persn_legal_bk_code, base_cust_lvl, curnt_cust_lvl,  -- 法人机构/期初层级/当前层级
        base_mth_avg_aum, curnt_mth_avg_aum                  -- 期初月日均AUM/当前月日均AUM
    )
    SELECT CASE WHEN d.statis_calib = '08' THEN '08' ELSE '09' END,  -- 路径标识：营销活动→A 目标任务→B
           d.statis_dim,                                  -- 统计维度
           d.indx_code,                                   -- 指标编码
           d.data_blng,                                   -- 数据归属
           d.cust_id,                                     -- 客户ID
           d.persn_legal_bk_code,                         -- 法人机构编码
           d.base_cust_lvl,                               -- 期初客户层级
           lv.cust_lvl,                                   -- 当前客户层级
           d.base_mth_avg_aum,                            -- 期初月日均AUM
           NVL(b.aum_bal, 0)                              -- 当前月日均AUM(无AUM记录取0)
      FROM ADS_STAT_INDX_BASELINE_DTL d                   -- 期初提升基准明细表
      LEFT JOIN DWS_CUST_LVL_INFO lv                      -- 客户层级信息表
        ON lv.cust_id             = d.cust_id             -- 客户ID匹配
       AND lv.persn_legal_bk_code = d.persn_legal_bk_code -- 法人机构匹配
       AND lv.data_date           = v_sysdat              -- 取跑批日层级快照
      LEFT JOIN DWS_CUST_ASSE_LIAB b                      -- 客户资产负债(AUM)表
        ON b.cust_id             = d.cust_id              -- 客户ID匹配
       AND b.persn_legal_bk_code = d.persn_legal_bk_code  -- 法人机构匹配
       AND b.data_date           = v_sysdat               -- 取跑批日快照
       AND b.bal_type            = '2'                    -- 余额类型=2(AUM)
     WHERE d.indx_code IN ('INDX_0052','INDX_0053','INDX_0054','INDX_0063')  -- 仅统计提升类指标
       AND (
           (d.indx_code = 'INDX_0052'                     -- 指标0052：层级提升至4级
            AND TO_NUMBER(NVL(d.base_cust_lvl, '0')) < 4  -- 期初层级<4
            AND TO_NUMBER(NVL(lv.cust_lvl, '0'))    >= 4) -- 当前层级>=4(达成提升)
           OR
           (d.indx_code = 'INDX_0053'                     -- 指标0053：层级提升至6级
            AND TO_NUMBER(NVL(d.base_cust_lvl, '0')) < 6  -- 期初层级<6
            AND TO_NUMBER(NVL(lv.cust_lvl, '0'))    >= 6) -- 当前层级>=6
           OR
           (d.indx_code = 'INDX_0054'                     -- 指标0054：层级提升至7级
            AND TO_NUMBER(NVL(d.base_cust_lvl, '0')) < 7  -- 期初层级<7
            AND TO_NUMBER(NVL(lv.cust_lvl, '0'))    >= 7) -- 当前层级>=7
           OR
           (d.indx_code = 'INDX_0063'  -- 指标0063：AUM临界档提升
            AND b.cust_id IS NOT NULL  -- 存在AUM记录
            AND (
                (b.aum_bal >= 45000   AND b.aum_bal < 50000)   OR                    -- 当前AUM 4.5万~5万档
                (b.aum_bal >= 270000  AND b.aum_bal < 300000)  OR                    -- 当前AUM 27万~30万档
                (b.aum_bal >= 450000  AND b.aum_bal < 500000)  OR                    -- 当前AUM 45万~50万档
                (b.aum_bal >= 900000  AND b.aum_bal < 1000000) OR                    -- 当前AUM 90万~100万档
                (b.aum_bal >= 2700000 AND b.aum_bal < 3000000) OR                    -- 当前AUM 270万~300万档
                (d.base_mth_avg_aum >= 45000   AND d.base_mth_avg_aum < 50000)   OR  -- 期初AUM 4.5万~5万档
                (d.base_mth_avg_aum >= 270000  AND d.base_mth_avg_aum < 300000)  OR  -- 期初AUM 27万~30万档
                (d.base_mth_avg_aum >= 450000  AND d.base_mth_avg_aum < 500000)  OR  -- 期初AUM 45万~50万档
                (d.base_mth_avg_aum >= 900000  AND d.base_mth_avg_aum < 1000000) OR  -- 期初AUM 90万~100万档
                (d.base_mth_avg_aum >= 2700000 AND d.base_mth_avg_aum < 3000000)     -- 期初AUM 270万~300万档
            ))
       );

    -------------------------------------------------------------------------
    -- 段落: 6.2 汇总写入 AGGR(路径08：营销活动)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_005 (                          -- 写入本步骤专项汇总表
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径/数据日期/归属/维度/口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标/当前值/期初值/法人机构
    )
    SELECT '08', v_sysdat, s.data_blng, s.statis_dim, '08', s.indx_code,                               -- 路径08汇总头：数据日期/归属/维度/营销活动/指标
           CASE s.indx_code                                                                             -- 按指标分类型计算客户数
               WHEN 'INDX_0052' THEN COUNT(c.cust_id)                                                   -- 0052：层级提升至4级的客户数
               WHEN 'INDX_0053' THEN COUNT(c.cust_id)                                                   -- 0053：层级提升至6级的客户数
               WHEN 'INDX_0054' THEN COUNT(c.cust_id)                                                   -- 0054：层级提升至7级的客户数
               WHEN 'INDX_0063' THEN                                                                    -- 0063：AUM临界档提升客户数(当前档-期初档)
                   SUM(CASE WHEN (c.curnt_mth_avg_aum >= 45000   AND c.curnt_mth_avg_aum < 50000)   OR  -- 当前AUM 4.5万~5万档
                                 (c.curnt_mth_avg_aum >= 270000  AND c.curnt_mth_avg_aum < 300000)  OR  -- 当前AUM 27万~30万档
                                 (c.curnt_mth_avg_aum >= 450000  AND c.curnt_mth_avg_aum < 500000)  OR  -- 当前AUM 45万~50万档
                                 (c.curnt_mth_avg_aum >= 900000  AND c.curnt_mth_avg_aum < 1000000) OR  -- 当前AUM 90万~100万档
                                 (c.curnt_mth_avg_aum >= 2700000 AND c.curnt_mth_avg_aum < 3000000)     -- 当前AUM 270万~300万档
                            THEN 1 ELSE 0 END)
                 - SUM(CASE WHEN (c.base_mth_avg_aum >= 45000   AND c.base_mth_avg_aum < 50000)   OR   -- 期初AUM 4.5万~5万档(减去已在档客户)
                                  (c.base_mth_avg_aum >= 270000  AND c.base_mth_avg_aum < 300000)  OR  -- 期初AUM 27万~30万档
                                  (c.base_mth_avg_aum >= 450000  AND c.base_mth_avg_aum < 500000)  OR  -- 期初AUM 45万~50万档
                                  (c.base_mth_avg_aum >= 900000  AND c.base_mth_avg_aum < 1000000) OR  -- 期初AUM 90万~100万档
                                  (c.base_mth_avg_aum >= 2700000 AND c.base_mth_avg_aum < 3000000)     -- 期初AUM 270万~300万档
                             THEN 1 ELSE 0 END)
           END,
           CASE WHEN s.indx_code = 'INDX_0063' THEN                                               -- 期初值：仅0063统计期初临界档客户数
               SUM(CASE WHEN (c.base_mth_avg_aum >= 45000   AND c.base_mth_avg_aum < 50000)   OR  -- 期初AUM 4.5万~5万档
                             (c.base_mth_avg_aum >= 270000  AND c.base_mth_avg_aum < 300000)  OR  -- 期初AUM 27万~30万档
                             (c.base_mth_avg_aum >= 450000  AND c.base_mth_avg_aum < 500000)  OR  -- 期初AUM 45万~50万档
                             (c.base_mth_avg_aum >= 900000  AND c.base_mth_avg_aum < 1000000) OR  -- 期初AUM 90万~100万档
                             (c.base_mth_avg_aum >= 2700000 AND c.base_mth_avg_aum < 3000000)     -- 期初AUM 270万~300万档
                        THEN 1 ELSE 0 END)
           ELSE 0 END,
           s.persn_legal_bk_code                                              -- 法人机构编码
      FROM (SELECT DISTINCT path_code, statis_dim, indx_code, data_blng, persn_legal_bk_code  -- 子查询：路径08去重(路径/维度/指标/归属/法人)
              FROM TMP_STAT_INDX_SCOPE                                        -- A/路径09目标客户范围表
             WHERE path_code = '08'                                            -- 仅路径08(营销活动)
               AND indx_code IN ('INDX_0052','INDX_0053','INDX_0054','INDX_0063')) s  -- 仅提升类指标
      LEFT JOIN TMP_STAT_INDX_CUST_STATE c                                    -- 关联客户提升状态明细(取客户数)
        ON c.path_code           = s.path_code                                -- 路径匹配
       AND c.statis_dim          = s.statis_dim                               -- 维度匹配
       AND c.indx_code           = s.indx_code                                -- 指标匹配
       AND c.data_blng           = s.data_blng                                -- 数据归属匹配
       AND c.persn_legal_bk_code = s.persn_legal_bk_code                      -- 法人机构匹配
     GROUP BY s.data_blng, s.statis_dim, s.indx_code, s.persn_legal_bk_code;  -- 按归属/维度/指标/法人机构分组

    -------------------------------------------------------------------------
    -- 段落: 6.3 汇总写入 AGGR(路径09：目标任务)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_005 (                          -- 写入本步骤专项汇总表
        path_code, data_date, data_blng, statis_dim, statis_calib,-- 路径/数据日期/归属/维度/口径
        indx_code, curnt_val, term_last_val, persn_legal_bk_code  -- 指标/当前值/期初值/法人机构
    )
    SELECT '09', v_sysdat, s.data_blng, s.statis_dim, '09', s.indx_code,                               -- 路径09汇总头：数据日期/归属/维度/目标任务/指标
           CASE s.indx_code                                                                             -- 按指标分类型计算客户数
               WHEN 'INDX_0052' THEN COUNT(c.cust_id)                                                   -- 0052：层级提升至4级的客户数
               WHEN 'INDX_0053' THEN COUNT(c.cust_id)                                                   -- 0053：层级提升至6级的客户数
               WHEN 'INDX_0054' THEN COUNT(c.cust_id)                                                   -- 0054：层级提升至7级的客户数
               WHEN 'INDX_0063' THEN                                                                    -- 0063：AUM临界档提升客户数(当前档-期初档)
                   SUM(CASE WHEN (c.curnt_mth_avg_aum >= 45000   AND c.curnt_mth_avg_aum < 50000)   OR  -- 当前AUM 4.5万~5万档
                                 (c.curnt_mth_avg_aum >= 270000  AND c.curnt_mth_avg_aum < 300000)  OR  -- 当前AUM 27万~30万档
                                 (c.curnt_mth_avg_aum >= 450000  AND c.curnt_mth_avg_aum < 500000)  OR  -- 当前AUM 45万~50万档
                                 (c.curnt_mth_avg_aum >= 900000  AND c.curnt_mth_avg_aum < 1000000) OR  -- 当前AUM 90万~100万档
                                 (c.curnt_mth_avg_aum >= 2700000 AND c.curnt_mth_avg_aum < 3000000)     -- 当前AUM 270万~300万档
                            THEN 1 ELSE 0 END)
                 - SUM(CASE WHEN (c.base_mth_avg_aum >= 45000   AND c.base_mth_avg_aum < 50000)   OR   -- 期初AUM 4.5万~5万档(减去已在档客户)
                                  (c.base_mth_avg_aum >= 270000  AND c.base_mth_avg_aum < 300000)  OR  -- 期初AUM 27万~30万档
                                  (c.base_mth_avg_aum >= 450000  AND c.base_mth_avg_aum < 500000)  OR  -- 期初AUM 45万~50万档
                                  (c.base_mth_avg_aum >= 900000  AND c.base_mth_avg_aum < 1000000) OR  -- 期初AUM 90万~100万档
                                  (c.base_mth_avg_aum >= 2700000 AND c.base_mth_avg_aum < 3000000)     -- 期初AUM 270万~300万档
                             THEN 1 ELSE 0 END)
           END,
           CASE WHEN s.indx_code = 'INDX_0063' THEN                                               -- 期初值：仅0063统计期初临界档客户数
               SUM(CASE WHEN (c.base_mth_avg_aum >= 45000   AND c.base_mth_avg_aum < 50000)   OR  -- 期初AUM 4.5万~5万档
                             (c.base_mth_avg_aum >= 270000  AND c.base_mth_avg_aum < 300000)  OR  -- 期初AUM 27万~30万档
                             (c.base_mth_avg_aum >= 450000  AND c.base_mth_avg_aum < 500000)  OR  -- 期初AUM 45万~50万档
                             (c.base_mth_avg_aum >= 900000  AND c.base_mth_avg_aum < 1000000) OR  -- 期初AUM 90万~100万档
                             (c.base_mth_avg_aum >= 2700000 AND c.base_mth_avg_aum < 3000000)     -- 期初AUM 270万~300万档
                        THEN 1 ELSE 0 END)
           ELSE 0 END,
           s.persn_legal_bk_code                                              -- 法人机构编码
      FROM (SELECT DISTINCT path_code, statis_dim, indx_code, data_blng, persn_legal_bk_code  -- 子查询：路径09去重(路径/维度/指标/归属/法人)
              FROM TMP_STAT_INDX_SCOPE                                        -- A/路径09目标客户范围表
             WHERE path_code = '09'                                            -- 仅路径09(目标任务)
               AND indx_code IN ('INDX_0052','INDX_0053','INDX_0054','INDX_0063')) s  -- 仅提升类指标
      LEFT JOIN TMP_STAT_INDX_CUST_STATE c                                    -- 关联客户提升状态明细(取客户数)
        ON c.path_code           = s.path_code                                -- 路径匹配
       AND c.statis_dim          = s.statis_dim                               -- 维度匹配
       AND c.indx_code           = s.indx_code                                -- 指标匹配
       AND c.data_blng           = s.data_blng                                -- 数据归属匹配
       AND c.persn_legal_bk_code = s.persn_legal_bk_code                      -- 法人机构匹配
     GROUP BY s.data_blng, s.statis_dim, s.indx_code, s.persn_legal_bk_code;  -- 按归属/维度/指标/法人机构分组

    -------------------------------------------------------------------------
    -- 段落: 结果行数回写与日志记录
    -------------------------------------------------------------------------
    outcde := SQL%ROWCOUNT;                                   -- 写入行数(取最后一条DML的影响行数)
    COMMIT;                                                   -- 提交事务
    V_END_DATE := SYSDATE;                                    -- 过程结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 运行耗时(秒)
    V_LOG_MSG := '步骤5处理完成，行数=' || NVL(outcde, 0);             -- 拼接日志消息(含写入行数)
    V_LOG_FLG := 0;                                           -- 日志标志：0=正常
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 写入步骤执行日志
EXCEPTION
    WHEN OTHERS THEN
    -------------------------------------------------------------------------
    -- 段落: 异常处理——回滚并记录错误日志后重抛
    -------------------------------------------------------------------------
        ROLLBACK;                                                 -- 异常回滚
        outcde := -1;                                             -- 异常标识：-1
        V_END_DATE := SYSDATE;                                    -- 过程结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 运行耗时(秒)
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 截取异常信息(前1000字符)
        V_LOG_FLG := -1;                                          -- 日志标志：-1=异常
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 写入异常日志
        RAISE;                                                    -- 重新抛出异常
END prc_ads_stat_indx_plan_005
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_006(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_006(v_sysdat varchar, outcde OUT integer)
AS -- 参数定义结束,过程体声明开始
    V_PRC_DESC   VARCHAR2(100) := '指标数据统计步骤66处理完成 6';           -- 过程描述文本
    V_PRC_NAME   VARCHAR2(32) := 'PRC_ADS_STAT_INDX_PLAN_006';  -- 过程名
    V_LOG_MSG    VARCHAR2(4000);                                -- 日志消息缓冲
    V_LOG_FLG    INTEGER;                                       -- 日志写入标志(0成功,-1失败)
    V_LOG_BUTTON INTEGER := 1;                                  -- 日志按钮标识
    V_NO_ID      VARCHAR2(10);                                  -- 步骤编号
    V_BGN_DATE   DATE;   -- 开始时间
    V_END_DATE   DATE;   -- 结束时间
    V_DURA_DATE  INTEGER;                                       -- 耗时(秒)
    V_YEAR_BEGIN    VARCHAR2(8) := SYS_FUN_DEAL_DATE(V_SYSDAT, 13);    -- 本年起始日(YYYYMMDD),用于 INDX_0071
    V_180_DAY_BEGIN VARCHAR2(8) := SYS_FUN_DEAL_DATE(V_SYSDAT, 27);    -- 近180天起始日(YYYYMMDD),用于 INDX_0072
BEGIN
    V_NO_ID    := '0';      -- 步骤编号
    V_BGN_DATE := SYSDATE;  -- 记录开始时间
    IF V_SYSDAT IS NULL     -- 跑批日期为空校验
       OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$')         -- 非YYYYMMDD格式校验
    THEN
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 参数非法抛错
    END IF;
    V_END_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');  -- 跑批日期转日期型

    -------------------------------------------------------------------------
    -- 7.0.0 基数表生命周期清理(INDX_0064)
    -- 每日巡检：活动/任务结束日+3个自然月 <= 跑批日 → 删除该活动基数
    --   路径08: DWD_MKT_ACT_INFO.STATIS_STOP_DATE
    --   路径09: DWD_MKT_TSK_INDX_SUB.TSK_END_DATE(任务级一致)
    --   另：AGGR 段首自清,本过程专属汇总临时表,防止重跑/并行残留
    -------------------------------------------------------------------------
    DELETE FROM TMP_STAT_INDX_AGGR_006;  -- AGGR 汇总临时表段首自清

    DELETE FROM ADS_CRM_R_SALRY_PAYROL_BASE T                       -- 代发薪客户基数表
     WHERE (T.PATH_CODE = '08'                                       -- 08=营销活动路径
            AND EXISTS (SELECT 1                                    -- 存在该活动基数记录则进入清理判定
                          FROM DWD_MKT_ACT_INFO A                   -- 营销活动信息表
                         WHERE A.MKT_ACT_ID = T.STATIS_DIM          -- 活动ID与统计维度匹配
                           AND ADD_MONTHS(TO_DATE(A.STATIS_STOP_DATE, 'YYYYMMDD'), 3)  -- 活动结束日+3个自然月
                               <= TO_DATE(V_SYSDAT, 'YYYYMMDD')))   -- 不晚于跑批日可清理
        OR (T.PATH_CODE = '09'                                       -- 09=目标任务路径
            AND EXISTS (SELECT 1                                    -- 存在该任务基数记录则进入清理判定
                          FROM DWD_MKT_TSK_INDX_SUB S               -- 任务指标明细表
                         WHERE S.TSK_ID = T.STATIS_DIM              -- 任务ID与统计维度匹配
                           AND ADD_MONTHS(TO_DATE(S.TSK_END_DATE, 'YYYYMMDD'), 3)  -- 任务结束日+3个自然月
                               <= TO_DATE(V_SYSDAT, 'YYYYMMDD')));  -- 不晚于跑批日可清理
    -------------------------------------------------------------------------
    -- 7.0 代发薪客户基数表刷新(INDX_0064)
    -- 每日跑批：范围内客户标签 IS_NOT_SALRY_PAYROL_BK='1' 入基数表
    --   新活动/任务首次出现：FRST_MARK_DATE='19000101'(活动前基数,不计新增)
    --   活动期间新增标记：FRST_MARK_DATE=跑批日
    -------------------------------------------------------------------------
    INSERT INTO ADS_CRM_R_SALRY_PAYROL_BASE                           -- 写入代发薪客户基数表
          (PATH_CODE, STATIS_DIM, PERSN_LEGAL_BK_CODE, CUST_ID, FRST_MARK_DATE)  -- 插入列：路径/统计维度/法人机构/客户ID/首次标记日期
          WITH SCOPE_BASE AS            -- 范围客户集合基础CTE
           (SELECT '08' AS PATH_CODE,    -- 路径标识 08=营销活动
                   S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                   TI.CUST_ID,          -- 客户ID
                   S.PERSN_LEGAL_BK_CODE                              -- 法人机构编码
              FROM TMP_STAT_INDX_SCOPE S                              -- 范围集合表(源)
             INNER JOIN DWD_MKT_TSK_INFO TI ON TI.MKT_ACT_ID = S.STATIS_DIM   -- 活动ID关联
                  AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
                  AND TI.DATA_DATE = V_SYSDAT                         -- 跑批当日参与机构
                  AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID) OR   -- 机构级归属匹配
                       (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))   -- 经理级归属匹配
             WHERE S.PATH_CODE = '08'    -- 仅营销活动路径
               AND S.INDX_CODE = 'INDX_0064'                          -- 指标编码
             UNION ALL                  -- 合并路径08与路径09
            SELECT '09',                 -- 路径标识 B=目标任务
                   S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                   LV.CUST_ID,          -- 客户ID
                   S.PERSN_LEGAL_BK_CODE                              -- 法人机构编码
              FROM TMP_STAT_INDX_SCOPE S                              -- 范围集合表(源)
             INNER JOIN DWS_CUST_LVL_INFO LV ON S.BLNG_TYPE = 'O'     -- 机构级客户层级
                  AND LV.ORG_ID = S.BLNG_ID                           -- 机构ID关联
                  AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
                  AND LV.DATA_DATE = V_SYSDAT                         -- 跑批当日
             WHERE S.PATH_CODE = '09'    -- 目标任务路径
               AND S.INDX_CODE = 'INDX_0064'                          -- 指标编码
             UNION ALL                  -- 合并路径08与路径09
            SELECT '09',                 -- 路径标识 B=目标任务
                   S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                   CM.CUST_ID,          -- 客户ID
                   S.PERSN_LEGAL_BK_CODE                              -- 法人机构编码
              FROM TMP_STAT_INDX_SCOPE S                              -- 范围集合表(源)
             INNER JOIN DWD_CUST_MAN CM ON S.BLNG_TYPE = 'M'          -- 经理级客户经理关系
                  AND CM.MNGR_POST_ID = S.BLNG_ID                     -- 客户经理岗位ID关联
                  AND CM.MNG_TYP = '1'  -- 主管类型
                  AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
             WHERE S.PATH_CODE = '09'    -- 目标任务路径
               AND S.INDX_CODE = 'INDX_0064')                         -- 指标编码
          SELECT DISTINCT               -- 去重后的目标插入行
                 SB.PATH_CODE,          -- 路径标识
                 SB.STATIS_DIM,         -- 统计维度(活动/任务编号)
                 SB.PERSN_LEGAL_BK_CODE,                              -- 法人机构编码
                 SB.CUST_ID,            -- 客户ID
                 CASE                   -- 判断活动是首次出现(初始基数)还是期间新增
                     WHEN EXISTS (SELECT 1
                                    FROM ADS_CRM_R_SALRY_PAYROL_BASE EB  -- 基数表已有记录判定
                                   WHERE EB.PATH_CODE = SB.PATH_CODE   -- 同活动/任务路径已存在
                                     AND EB.STATIS_DIM = SB.STATIS_DIM) THEN  -- 同活动/任务已存在→期间新增分支
                         V_SYSDAT                                      -- 已存在→本次为活动期间新增,记跑批日
                     ELSE
                         '19000101'  -- 新活动→活动前基数,标记初始值
                 END AS FRST_MARK_DATE
            FROM SCOPE_BASE SB                                     -- 主表为范围客户基础集
           INNER JOIN ADS_CRM_R_CUST_LABLE L                       -- 关联客户标签表
               ON L.CUST_ID = SB.CUST_ID                           -- 客户ID对应
              AND L.PERSN_LEGAL_BK_CODE = SB.PERSN_LEGAL_BK_CODE   -- 法人机构一致
           WHERE L.IS_NOT_SALRY_PAYROL_BK = '1'                    -- 非代发薪客户标签
             AND NOT EXISTS (SELECT 1                              -- 基数表中不存在该客户才新增
                               FROM ADS_CRM_R_SALRY_PAYROL_BASE NB -- 基数表子查询
                              WHERE NB.PATH_CODE = SB.PATH_CODE    -- 同路径判定
                                AND NB.STATIS_DIM = SB.STATIS_DIM  -- 同统计维度判定
                                AND NB.CUST_ID = SB.CUST_ID        -- 同客户ID判定
                                AND NB.PERSN_LEGAL_BK_CODE = SB.PERSN_LEGAL_BK_CODE);  -- 基数表不存在则新增

    -------------------------------------------------------------------------
    -- 7.1/7.2 保险新保保费 INDX_0061 (合并 A/B)
    -- 范围客户保单(POLICY_STATE='1')在[活动开始日,跑批日]内新保保费之和,SUM(NEW_INSUR_AMT)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_006                          -- 写入步骤6专属汇总临时表
        (PATH_CODE,                   -- 路径标识
         DATA_DATE,                   -- 跑批业务日期(YYYYMMDD)
         DATA_BLNG,                   -- 数据归属
         STATIS_DIM,                  -- 统计维度(活动/任务编号)
         STATIS_CALIB,                -- 统计口径名称
         INDX_CODE,                   -- 指标编码
         CURNT_VAL,                   -- 本期统计值
         TERM_LAST_VAL,               -- 上期统计值
         PERSN_LEGAL_BK_CODE)         -- 法人机构编码
        WITH SCOPE_ALL AS             -- 全范围客户集合CTE
         (SELECT '08' AS PATH_CODE,    -- 路径标识 08=营销活动
                 '08' AS STATIS_CALIB,                        -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 S.TERM_BEGIN_DATE,   -- 活动开始日期
                 TI.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                          -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                          -- 范围集合表(源)
           INNER JOIN DWD_MKT_TSK_INFO TI ON TI.MKT_ACT_ID = S.STATIS_DIM        -- 活动ID关联
                AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE              -- 法人机构一致
                AND TI.DATA_DATE = V_SYSDAT                     -- 跑批当日参与机构
                AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID) OR    -- 机构级归属匹配
                     (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))          -- 经理级归属匹配
           WHERE S.PATH_CODE = '08'    -- 仅营销活动路径
             AND S.INDX_CODE = 'INDX_0061'                      -- 指标编码
          UNION ALL                   -- 合并A/路径09
          SELECT '09',                 -- 路径标识 B=目标任务
                 '09',              -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 S.TERM_BEGIN_DATE,   -- 活动开始日期
                 LV.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                          -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                          -- 范围集合表(源)
           INNER JOIN DWS_CUST_LVL_INFO LV ON S.BLNG_TYPE = 'O' -- 机构级客户层级
                AND LV.ORG_ID = S.BLNG_ID                       -- 机构ID关联
                AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE             -- 法人机构一致
                AND LV.DATA_DATE = V_SYSDAT                     -- 跑批当日
           WHERE S.PATH_CODE = '09'    -- 目标任务路径
             AND S.INDX_CODE = 'INDX_0061'                      -- 指标编码
          UNION ALL                   -- 合并A/路径09
          SELECT '09',                 -- 路径标识 B=目标任务
                 '09',              -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 S.TERM_BEGIN_DATE,   -- 活动开始日期
                 CM.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                          -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                          -- 范围集合表(源)
           INNER JOIN DWD_CUST_MAN CM ON S.BLNG_TYPE = 'M'      -- 经理级客户经理关系
                AND CM.MNGR_POST_ID = S.BLNG_ID                 -- 客户经理岗位ID关联
                AND CM.MNG_TYP = '1'  -- 主管类型
                AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE            -- 法人机构一致
           WHERE S.PATH_CODE = '09'    -- 仅目标任务路径
             AND S.INDX_CODE = 'INDX_0061')                     -- 指标编码
        SELECT SM.PATH_CODE,          -- 路径标识
               V_SYSDAT,              -- 跑批业务日期
               SM.DATA_BLNG,          -- 数据归属
               SM.STATIS_DIM,         -- 统计维度(活动/任务编号)
               SM.STATIS_CALIB,       -- 统计口径名称
               'INDX_0061',           -- 指标编码
               SUM(NVL(I.NEW_INSUR_AMT, 0)),                    -- 保险新保保费合计
               0,                     -- 上期值(本期不统计)
               SM.PERSN_LEGAL_BK_CODE -- 法人机构编码
          FROM (SELECT DISTINCT PATH_CODE,                      -- 路径标识
                                STATIS_CALIB,                   -- 统计口径名称
                                STATIS_DIM,                     -- 统计维度(活动/任务编号)
                                DATA_BLNG,                      -- 数据归属
                                TERM_BEGIN_DATE,                -- 活动开始日期
                                CUST_ID,                        -- 客户ID
                                PERSN_LEGAL_BK_CODE             -- 法人机构编码
                  FROM SCOPE_ALL) SM  -- 去重后的范围集
         INNER JOIN DWD_ACCT_INSUR I ON I.CUST_ID = SM.CUST_ID  -- 客户保单关联
              AND I.PERSN_LEGAL_BK_CODE = SM.PERSN_LEGAL_BK_CODE-- 法人机构一致
              AND I.POLICY_STATE = '1'                          -- 保单有效状态
              AND I.TX_DATE BETWEEN SM.TERM_BEGIN_DATE AND V_SYSDAT      -- 保单交易日落在[开始日,跑批日]
         GROUP BY SM.PATH_CODE,       -- 按路径分组
                  SM.DATA_BLNG,       -- 按数据归属分组
                  SM.STATIS_DIM,      -- 按统计维度分组
                  SM.STATIS_CALIB,    -- 按统计口径分组
                  SM.PERSN_LEGAL_BK_CODE;                       -- 按法人机构分组

    -------------------------------------------------------------------------
    -- 7.3/7.4 手机银行活跃客户数 INDX_0067 (合并 A/B)
    -- 范围客户中手机银行活跃标签(IS_NOT_BK_PHONE_ACTV_CUST='1')的去重客户数,COUNT(DISTINCT CUST_ID)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_006                           -- 写入步骤6专属汇总临时表
        (PATH_CODE,                   -- 路径标识
         DATA_DATE,                   -- 跑批业务日期(YYYYMMDD)
         DATA_BLNG,                   -- 数据归属
         STATIS_DIM,                  -- 统计维度(活动/任务编号)
         STATIS_CALIB,                -- 统计口径名称
         INDX_CODE,                   -- 指标编码
         CURNT_VAL,                   -- 本期统计值
         TERM_LAST_VAL,               -- 上期统计值
         PERSN_LEGAL_BK_CODE)         -- 法人机构编码
        WITH SCOPE_ALL AS             -- 全范围客户集合CTE
         (SELECT '08' AS PATH_CODE,    -- 路径标识 08=营销活动
                 '08' AS STATIS_CALIB,                         -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 TI.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                           -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                           -- 范围集合表(源)
           INNER JOIN DWD_MKT_TSK_INFO TI ON TI.MKT_ACT_ID = S.STATIS_DIM        -- 活动ID关联
                AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE              -- 法人机构一致
                AND TI.DATA_DATE = V_SYSDAT                      -- 跑批当日参与机构
                AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID) OR    -- 机构级归属匹配
                     (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))          -- 经理级归属匹配
           WHERE S.PATH_CODE = '08'    -- 仅营销活动路径
             AND S.INDX_CODE = 'INDX_0067'                       -- 指标编码
          UNION ALL                   -- 合并A/路径09
          SELECT '09',                 -- 路径标识 B=目标任务
                 '09',              -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 LV.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                           -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                           -- 范围集合表(源)
           INNER JOIN DWS_CUST_LVL_INFO LV ON S.BLNG_TYPE = 'O'  -- 机构级客户层级
                AND LV.ORG_ID = S.BLNG_ID                        -- 机构ID关联
                AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE             -- 法人机构一致
                AND LV.DATA_DATE = V_SYSDAT                      -- 跑批当日
           WHERE S.PATH_CODE = '09'    -- 目标任务路径
             AND S.INDX_CODE = 'INDX_0067'                       -- 指标编码
          UNION ALL                   -- 合并A/路径09
          SELECT '09',                 -- 路径标识 B=目标任务
                 '09',              -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 CM.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                           -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                           -- 范围集合表(源)
           INNER JOIN DWD_CUST_MAN CM ON S.BLNG_TYPE = 'M'       -- 经理级客户经理关系
                AND CM.MNGR_POST_ID = S.BLNG_ID                  -- 客户经理岗位ID关联
                AND CM.MNG_TYP = '1'  -- 主管类型
                AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE            -- 法人机构一致
           WHERE S.PATH_CODE = '09'    -- 目标任务路径
             AND S.INDX_CODE = 'INDX_0067')                      -- 指标编码
        SELECT SM.PATH_CODE,          -- 路径标识
               V_SYSDAT,              -- 跑批业务日期
               SM.DATA_BLNG,          -- 数据归属
               SM.STATIS_DIM,         -- 统计维度(活动/任务编号)
               SM.STATIS_CALIB,       -- 统计口径名称
               'INDX_0067',           -- 指标编码
               COUNT(DISTINCT SM.CUST_ID),                       -- 手机银行活跃客户去重数
               0,                     -- 上期值(本期不统计)
               SM.PERSN_LEGAL_BK_CODE -- 法人机构编码
          FROM SCOPE_ALL SM           -- 全范围客户集为主表
         INNER JOIN ADS_CRM_R_CUST_LABLE L ON L.CUST_ID = SM.CUST_ID      -- 客户标签关联
              AND L.PERSN_LEGAL_BK_CODE = SM.PERSN_LEGAL_BK_CODE -- 法人机构一致
              AND L.IS_NOT_BK_PHONE_ACTV_CUST = '1'              -- 手机银行活跃客户标签
         GROUP BY SM.PATH_CODE,       -- 按路径分组
                  SM.DATA_BLNG,       -- 按数据归属分组
                  SM.STATIS_DIM,      -- 按统计维度分组
                  SM.STATIS_CALIB,    -- 按统计口径分组
                  SM.PERSN_LEGAL_BK_CODE;                        -- 按法人机构分组

    -------------------------------------------------------------------------
    -- 7.5/7.6 收单价值商户数 INDX_0068 (合并 A/B)
    -- 范围商户经结算户关联的标签客户为收单价值商户(IS_NOT_BILL_RSV_VAL_MKNT='1')的去重客户数
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_006                  -- 写入步骤6专属汇总临时表
        (PATH_CODE,                                     -- 路径标识
         DATA_DATE,                                     -- 跑批业务日期(YYYYMMDD)
         DATA_BLNG,                                     -- 数据归属
         STATIS_DIM,                                    -- 统计维度(活动/任务编号)
         STATIS_CALIB,                                  -- 统计口径名称
         INDX_CODE,                                     -- 指标编码
         CURNT_VAL,                                     -- 本期统计值
         TERM_LAST_VAL,                                 -- 上期统计值
         PERSN_LEGAL_BK_CODE)                           -- 法人机构编码
        WITH SCOPE_ALL AS                               -- 全范围商户集合CTE
         (SELECT '08' AS PATH_CODE,                      -- 路径标识 08=营销活动
                 '08' AS STATIS_CALIB,                -- 统计口径名称
                 S.STATIS_DIM,                          -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,                           -- 数据归属
                 S.PERSN_LEGAL_BK_CODE,                 -- 法人机构编码
                 M.MCT_ID                               -- 商户ID(收单商户)
            FROM TMP_STAT_INDX_SCOPE S                  -- 范围集合表(源)
           INNER JOIN UEPP_PAY_MCT_INFO M ON ((S.BLNG_TYPE = 'O' AND M.ORG_ID = S.BLNG_ID) OR    -- 机构级归属匹配
                                              (S.BLNG_TYPE = 'M' AND M.JOB_ID = S.BLNG_ID))     -- 经理级归属匹配
           WHERE S.PATH_CODE = '08'                      -- 仅营销活动路径
             AND S.INDX_CODE = 'INDX_0068'              -- 指标编码
          UNION ALL                                     -- 合并A/路径09
          SELECT '09',                                   -- 路径标识 B=目标任务
                 '09',                                -- 统计口径名称
                 S.STATIS_DIM,                          -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,                           -- 数据归属
                 S.PERSN_LEGAL_BK_CODE,                 -- 法人机构编码
                 M.MCT_ID                               -- 商户ID(收单商户)
            FROM TMP_STAT_INDX_SCOPE S                  -- 范围集合表(源)
           INNER JOIN UEPP_PAY_MCT_INFO M ON ((S.BLNG_TYPE = 'O' AND M.ORG_ID = S.BLNG_ID) OR    -- 机构级归属匹配
                                              (S.BLNG_TYPE = 'M' AND M.JOB_ID = S.BLNG_ID))     -- 经理级归属匹配
           WHERE S.PATH_CODE = '09'                      -- 目标任务路径
             AND S.INDX_CODE = 'INDX_0068'),            -- 指标编码
        VAL_MERCHANT AS                                 -- 收单价值商户集合CTE
         (SELECT DISTINCT SM.PATH_CODE,                 -- 路径标识
                          SM.STATIS_CALIB,              -- 统计口径名称
                          SM.STATIS_DIM,                -- 统计维度(活动/任务编号)
                          SM.DATA_BLNG,                 -- 数据归属
                          SM.PERSN_LEGAL_BK_CODE,       -- 法人机构编码
                          L.CUST_ID                     -- 收单价值商户客户ID
            FROM (SELECT DISTINCT PATH_CODE,            -- 去重范围集内层：路径
                                  STATIS_CALIB,         -- 统计口径
                                  STATIS_DIM,           -- 统计维度
                                  DATA_BLNG,            -- 数据归属
                                  PERSN_LEGAL_BK_CODE,  -- 法人机构编码
                                  MCT_ID                -- 商户ID
                    FROM SCOPE_ALL) SM                  -- 去重后的范围集
           INNER JOIN UEPP_PAY_MCT_SETTLE_ACCOUNT SA ON SA.MCT_ID = SM.MCT_ID    -- 商户结算账户关联
                AND SA.CUST_NO IS NOT NULL              -- 结算账户已有客户号
           INNER JOIN ADS_CRM_R_CUST_LABLE L ON L.CUST_ID = SA.CUST_NO  -- 商户结算账户关联标签客户
                AND L.PERSN_LEGAL_BK_CODE = SM.PERSN_LEGAL_BK_CODE  -- 法人机构一致
                AND L.IS_NOT_BILL_RSV_VAL_MKNT = '1')   -- 收单价值商户标签
        SELECT PATH_CODE,                               -- 路径标识
               V_SYSDAT,                                -- 跑批业务日期
               DATA_BLNG,                               -- 数据归属
               STATIS_DIM,                              -- 统计维度(活动/任务编号)
               STATIS_CALIB,                            -- 统计口径名称
               'INDX_0068',                             -- 指标编码
               COUNT(DISTINCT CUST_ID),                 -- 收单价值商户去重数
               0,  -- 上期值(本期不统计)
               PERSN_LEGAL_BK_CODE                      -- 法人机构编码
          FROM VAL_MERCHANT                             -- 收单价值商户集为主表
         GROUP BY PATH_CODE,                            -- 按路径分组
                  DATA_BLNG,                            -- 按数据归属分组
                  STATIS_DIM,                           -- 按统计维度分组
                  STATIS_CALIB,                         -- 按统计口径分组
                  PERSN_LEGAL_BK_CODE;                  -- 按法人机构分组

    -------------------------------------------------------------------------
    -- 7.7/7.8 一码付收款客户数 INDX_0076 (合并 A/B)
