         TERM_LAST_VAL,               -- 上期统计值
         PERSN_LEGAL_BK_CODE)         -- 法人机构编码
        WITH SCOPE_ALL AS             -- 全范围客户集合CTE
         (SELECT '08' AS PATH_CODE,    -- 路径标识 08=营销活动
                 '08' AS STATIS_CALIB,                    -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 S.TERM_BEGIN_DATE,   -- 活动开始日期
                 TI.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                      -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                      -- 范围集合表(源)
           INNER JOIN DWD_MKT_TSK_INFO TI ON TI.MKT_ACT_ID = S.STATIS_DIM        -- 活动ID关联
                AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE              -- 法人机构一致
                AND TI.DATA_DATE = V_SYSDAT                 -- 跑批当日参与机构
                AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID) OR    -- 机构级归属匹配
                     (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))          -- 经理级归属匹配
           WHERE S.PATH_CODE = '08'    -- 仅营销活动路径
             AND S.INDX_CODE = 'INDX_0065'                  -- 指标编码
          UNION ALL                   -- 合并A/路径09
          SELECT '09',                 -- 路径标识 B=目标任务
                 '09',              -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 S.TERM_BEGIN_DATE,   -- 活动开始日期
                 LV.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                      -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                      -- 范围集合表(源)
           INNER JOIN DWS_CUST_LVL_INFO LV ON S.BLNG_TYPE = 'O'                 -- 机构级客户层级
                AND LV.ORG_ID = S.BLNG_ID                   -- 机构ID关联
                AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE             -- 法人机构一致
                AND LV.DATA_DATE = V_SYSDAT                 -- 跑批当日
           WHERE S.PATH_CODE = '09'    -- 目标任务路径
             AND S.INDX_CODE = 'INDX_0065'                  -- 指标编码
          UNION ALL                   -- 合并A/路径09
          SELECT '09',                 -- 路径标识 B=目标任务
                 '09',              -- 统计口径名称
                 S.STATIS_DIM,        -- 统计维度(活动/任务编号)
                 S.DATA_BLNG,         -- 数据归属
                 S.TERM_BEGIN_DATE,   -- 活动开始日期
                 CM.CUST_ID,          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                      -- 法人机构编码
            FROM TMP_STAT_INDX_SCOPE S                      -- 范围集合表(源)
           INNER JOIN DWD_CUST_MAN CM ON S.BLNG_TYPE = 'M'  -- 经理级客户经理关系
                AND CM.MNGR_POST_ID = S.BLNG_ID             -- 客户经理岗位ID关联
                AND CM.MNG_TYP = '1'  -- 主管类型
                AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE            -- 法人机构一致
           WHERE S.PATH_CODE = '09'    -- 目标任务路径
             AND S.INDX_CODE = 'INDX_0065')                 -- 指标编码
        SELECT SM.PATH_CODE,             -- 路径标识
               V_SYSDAT,              -- 跑批业务日期
               SM.DATA_BLNG,             -- 数据归属
               SM.STATIS_DIM,            -- 统计维度(活动/任务编号)
               SM.STATIS_CALIB,          -- 统计口径名称
               'INDX_0065',           -- 指标编码
               SUM(AMT),              -- 理财+保险代销收入合计
               0,                     -- 上期值(本期不统计)
               SM.PERSN_LEGAL_BK_CODE    -- 法人机构编码
          FROM (SELECT DISTINCT PATH_CODE,               -- 路径标识
                                STATIS_CALIB,            -- 统计口径名称
                                STATIS_DIM,              -- 统计维度(活动/任务编号)
                                DATA_BLNG,               -- 数据归属
                                TERM_BEGIN_DATE,         -- 活动开始日期
                                CUST_ID,                 -- 客户ID
                                PERSN_LEGAL_BK_CODE      -- 法人机构编码
                  FROM SCOPE_ALL) SM  -- 去重后的范围集
         INNER JOIN (SELECT F.CUST_ID,                      -- 客户ID
                            F.PERSN_LEGAL_BK_CODE,          -- 法人机构编码
                            NVL(F.FIN_AMT, 0) AS AMT,       -- 理财销售金额(空转0)
                            F.ISSU_DATE       AS TX_DATE    -- 理财发行日期
                       FROM DWD_ACCT_FIN F                  -- 理财账户表(收益类产品)
                      WHERE F.PRDKT_CATE_BIG IN ('1', '2')  -- 理财收益类产品
                      UNION ALL       -- 合并理财与保险
                     SELECT I.CUST_ID,                      -- 客户ID
                            I.PERSN_LEGAL_BK_CODE,          -- 法人机构编码
                            NVL(I.INSUR_AMT, 0) AS AMT,     -- 保险销售金额(空转0)
                            I.TX_DATE           AS TX_DATE  -- 保险交易日期
                       FROM DWD_ACCT_INSUR I                -- 保险账户表(有效保单)
                      WHERE I.POLICY_STATE = '1') D         -- 保险有效保单
              ON D.CUST_ID = SM.CUST_ID                     -- 客户ID关联
             AND D.PERSN_LEGAL_BK_CODE = SM.PERSN_LEGAL_BK_CODE               -- 法人机构一致
             AND D.TX_DATE BETWEEN SM.TERM_BEGIN_DATE AND V_SYSDAT            -- 交易日期在活动期间内
         GROUP BY SM.PATH_CODE,          -- 按路径分组
                  SM.DATA_BLNG,          -- 按数据归属分组
                  SM.STATIS_DIM,         -- 按统计维度分组
                  SM.STATIS_CALIB,       -- 按统计口径分组
                  SM.PERSN_LEGAL_BK_CODE;                      -- 按法人机构分组
    OUTCDE := SQL%ROWCOUNT;           -- 输出影响行数(最后一次INSERT处理行数)
    COMMIT;                           -- 提交本段事务
    V_END_DATE  := SYSDATE;           -- 记录结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);-- 计算耗时(秒)
    V_LOG_MSG   := '步骤6处理完成，行数=' || NVL(OUTCDE, 0);         -- 拼装日志消息
    V_LOG_FLG   := 0;                 -- 日志标志(0成功)
    SYS_PRC_STEP_LOGS(V_SYSDAT,       -- 记录步骤日志(过程名/时间/耗时/消息/标志)
                      V_PRC_NAME,     -- 过程名
                      V_PRC_DESC,     -- 过程描述
                      V_NO_ID,        -- 步骤编号
                      V_BGN_DATE,     -- 开始时间
                      V_END_DATE,     -- 结束时间
                      V_DURA_DATE,    -- 耗时(秒)
                      V_LOG_MSG,      -- 日志消息
                      V_LOG_FLG,      -- 日志标志
                      V_LOG_BUTTON);  -- 日志按钮标识
EXCEPTION                             -- 异常处理块
    WHEN OTHERS THEN
        ROLLBACK;                    -- 异常回滚
        OUTCDE      := -1;           -- 输出异常标志
        V_END_DATE  := SYSDATE;      -- 记录结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算耗时(秒)
        V_LOG_MSG   := SUBSTR(SQLERRM, 1, 1000);  -- 错误信息截断记录
        V_LOG_FLG   := -1;           -- 日志标志(-1失败)
        SYS_PRC_STEP_LOGS(V_SYSDAT,  -- 写失败日志
                          V_PRC_NAME,     -- 过程名
                          V_PRC_DESC,     -- 过程描述
                          V_NO_ID,   -- 步骤编号
                          V_BGN_DATE,     -- 开始时间
                          V_END_DATE,     -- 结束时间
                          V_DURA_DATE,    -- 耗时(秒)
                          V_LOG_MSG, -- 日志消息
                          V_LOG_FLG, -- 日志标志
                          V_LOG_BUTTON);  -- 日志按钮标识
        RAISE;                       -- 重新抛出异常
END PRC_ADS_STAT_INDX_PLAN_006
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_007(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_007(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC VARCHAR2(100) := '指标数据统计步骤77处理完成 7';  -- 步骤描述
    V_PRC_NAME VARCHAR2(32) := 'PRC_ADS_STAT_INDX_PLAN_007';          -- 过程名
    V_LOG_MSG VARCHAR2(4000);                        -- 日志消息文本
    V_LOG_FLG INTEGER;                               -- 日志标志(0成功/-1失败)
    V_LOG_BUTTON INTEGER := 1;                       -- 日志按钮标识
    V_NO_ID VARCHAR2(10);                            -- 跑批序号
    V_BGN_DATE DATE;                                 -- 开始时间
    V_END_DATE DATE;                                 -- 结束时间
    V_DURA_DATE INTEGER;                             -- 耗时(秒)
    V_180_DAY_BEGIN VARCHAR2(8);                     -- 180天猫新客判定起始日期
BEGIN
    V_NO_ID := '0';  -- 跑批序号置0
    V_BGN_DATE := SYSDATE;  -- 记录开始时间
    -- 参数校验：跑批日期必须为 8 位数字 YYYYMMDD
    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN  -- 校验跑批日期格式
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 日期非法则报错终止
    END IF;
    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 将跑批日期字符串转为日期类型
    -- 计算往前回推 27 个自然日(约 180 天口径)的起始日期,用于新客判定
    V_180_DAY_BEGIN := SYS_FUN_DEAL_DATE(V_SYSDAT, 27);  -- 调用日期函数求180天窗口起始日

    -------------------------------------------------------------------------
    -- 段首自清：本过程专属汇总临时表,防止重跑/并行残留
    -------------------------------------------------------------------------
    DELETE FROM TMP_STAT_INDX_AGGR_007;  -- 清空本过程专属汇总累计临时表

    -------------------------------------------------------------------------
    -- INDX_0080 新客交叉销售 (合并 A/B)
    -- 说明: 营销活动(A)/目标任务(B)两路径取数并经客户维度去重后,
    --       统计开户时间在 180 天窗口内且持有两类及以上产品(手机银行/存款/理财/贷款)的交叉销售客户数
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_007                           -- 插入专属累计表(0080)
        (PATH_CODE,                                              -- 路径代码
         DATA_DATE,                                              -- 数据日期
         DATA_BLNG,                                              -- 数据归属
         STATIS_DIM,                                             -- 统计维度
         STATIS_CALIB,                                           -- 统计口径
         INDX_CODE,                                              -- 指标代码
         CURNT_VAL,                                              -- 本期值
         TERM_LAST_VAL,                                          -- 上期值
         PERSN_LEGAL_BK_CODE)                                    -- 法人机构编号
        WITH SCOPE_ALL AS                                        -- 组装A/B各路径范围内客户
         (SELECT '08'       AS PATH_CODE,                         -- 路径代码08(营销活动)
                 '08' AS STATIS_CALIB,                         -- 统计口径=营销活动
                 S.STATIS_DIM,                                   -- 统计维度(活动ID)
                 S.DATA_BLNG,                                    -- 数据归属
                 S.TERM_BEGIN_DATE,                              -- 活动开始日期
                 TI.CUST_ID,                                     -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                           -- 法人机构编号
            FROM TMP_STAT_INDX_SCOPE S                           -- 指标范围临时表
        INNER JOIN DWD_MKT_TSK_INFO TI                           -- 关联营销活动任务信息
               ON TI.MKT_ACT_ID = S.STATIS_DIM                   -- 活动ID等于统计维度
              AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE -- 法人机构一致
              AND TI.DATA_DATE = V_SYSDAT                        -- 取跑批日期当日活动
              AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID)  -- 按机构归属匹配
                OR (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))  -- 按客户经理归属匹配
          WHERE S.PATH_CODE = '08'                                -- 限定路径08
            AND S.INDX_CODE = 'INDX_0080'                        -- 仅取0080指标
         UNION ALL                                               -- 合并(保留重复)
         SELECT '09',                                             -- 路径代码B(目标任务)
                '09',                                          -- 统计口径=目标任务
                S.STATIS_DIM,                                    -- 统计维度
                S.DATA_BLNG,                                     -- 数据归属
                S.TERM_BEGIN_DATE,                               -- 任务开始日期
                LV.CUST_ID,                                      -- 客户ID
                S.PERSN_LEGAL_BK_CODE                            -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S                            -- 指标范围临时表
        INNER JOIN DWS_CUST_LVL_INFO LV                          -- 关联客户层级信息
               ON S.BLNG_TYPE = 'O'                              -- 归属类型为机构
              AND LV.ORG_ID = S.BLNG_ID                          -- 机构ID一致
              AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE -- 法人机构一致
              AND LV.DATA_DATE = V_SYSDAT                        -- 取跑批日期当日层级
          WHERE S.PATH_CODE = '09'                                -- 限定路径09
            AND S.INDX_CODE = 'INDX_0080'                        -- 仅取0080指标
         UNION ALL                                               -- 合并(保留重复)
         SELECT '09',                                             -- 路径代码B
                '09',                                          -- 统计口径
                S.STATIS_DIM,                                    -- 统计维度
                S.DATA_BLNG,                                     -- 数据归属
                S.TERM_BEGIN_DATE,                               -- 任务开始日期
                CM.CUST_ID,                                      -- 客户ID
                S.PERSN_LEGAL_BK_CODE                            -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S                            -- 指标范围临时表
        INNER JOIN DWD_CUST_MAN CM                               -- 关联客户经理归属表
               ON S.BLNG_TYPE = 'M'                              -- 归属类型为客户经理
              AND CM.MNGR_POST_ID = S.BLNG_ID                    -- 客户经理岗位ID一致
              AND CM.MNG_TYP = '1'                               -- 客户经理类型主号
              AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE -- 法人机构一致
          WHERE S.PATH_CODE = '09'                                -- 限定路径09
            AND S.INDX_CODE = 'INDX_0080'),                      -- 仅取0080指标
        CUST_FLAGS AS                                            -- 客户维度打标(四类产品持有标志)
         (SELECT SM.PATH_CODE,                                   -- 路径代码
                 SM.STATIS_CALIB,                                -- 统计口径
                 SM.STATIS_DIM,                                  -- 统计维度
                 SM.DATA_BLNG,                                   -- 数据归属
                 SM.TERM_BEGIN_DATE,                             -- 开始日期
                 SM.CUST_ID,                                     -- 客户ID
                 SM.PERSN_LEGAL_BK_CODE,                         -- 法人机构编号
                 CI.OPEN_DATE,                                   -- 客户开户日期
                 MAX(CASE WHEN MI.CUST_NO IS NOT NULL THEN 1 ELSE 0 END) AS HAS_MBK,  -- 是否持有手机银行
                 MAX(CASE WHEN NVL(B.DEPO_CURNT_DEPO_BAL, 0) + NVL(B.FIXD_DEPO_BAL, 0) >= 100 THEN 1 ELSE 0 END) AS HAS_DEPO,  -- 是否持有存款(活期+定期≥100)
                 MAX(CASE WHEN NVL(B.FIN_BAL, 0) > 0 THEN 1 ELSE 0 END) AS HAS_FIN,  -- 是否持有理财(金融资产)
                 MAX(CASE WHEN NVL(B.LOAN_BAL, 0) > 0 THEN 1 ELSE 0 END) AS HAS_LOAN  -- 是否持有贷款
           FROM (SELECT DISTINCT PATH_CODE,                      -- 去重：路径
                                  STATIS_CALIB,                  -- 口径
                                  STATIS_DIM,                    -- 维度
                                  DATA_BLNG,                     -- 归属
                                  TERM_BEGIN_DATE,               -- 开始日期
                                  CUST_ID,                       -- 客户ID
                                  PERSN_LEGAL_BK_CODE            -- 法人机构
                   FROM SCOPE_ALL) SM                            -- 范围客户去重后的结果集
       LEFT JOIN DWD_CUST_INDV_INFO CI                           -- 关联个人客户基本信息
              ON CI.CUST_ID = SM.CUST_ID                         -- 客户ID一致
             AND CI.PERSN_LEGAL_BK_CODE = SM.PERSN_LEGAL_BK_CODE -- 法人机构一致
       LEFT JOIN MBK_CUST_INFO MI                                -- 关联手机银行客户信息
              ON MI.CUST_CORE_NO = SM.CUST_ID                    -- 客户核心号等于客户ID
             AND MI.INCORP_NO = SM.PERSN_LEGAL_BK_CODE           -- 法人机构一致
             AND MI.CUST_STATUS = '1'                            -- 客户状态为有效
       LEFT JOIN DWS_CUST_ASSE_LIAB B                            -- 关联资产负债余额表
              ON B.CUST_ID = SM.CUST_ID                          -- 客户ID一致
             AND B.PERSN_LEGAL_BK_CODE = SM.PERSN_LEGAL_BK_CODE  -- 法人机构一致
             AND B.DATA_DATE = V_SYSDAT                          -- 取跑批日期当日余额
             AND B.BAL_TYPE = '1'                                -- 余额类型为贷款/存款时点
        GROUP BY SM.PATH_CODE,                                   -- 按路径分组
                 SM.STATIS_CALIB,                                -- 按口径分组
                 SM.STATIS_DIM,                                  -- 按维度分组
                 SM.DATA_BLNG,                                   -- 按归属分组
                 SM.TERM_BEGIN_DATE,                             -- 按开始日期分组
                 SM.CUST_ID,                                     -- 按客户分组
                 SM.PERSN_LEGAL_BK_CODE,                         -- 按法人机构分组
                 CI.OPEN_DATE)                                   -- 按开户日期分组
        SELECT PATH_CODE,                                        -- 路径代码
               V_SYSDAT,                                         -- 数据日期=跑批日期
               DATA_BLNG,                                        -- 数据归属
               STATIS_DIM,                                       -- 统计维度
               STATIS_CALIB,                                     -- 统计口径
               'INDX_0080',                                      -- 指标代码固定0080
               COUNT(DISTINCT CASE                               -- 计数满足交叉销售条件的客户
                    WHEN OPEN_DATE BETWEEN V_180_DAY_BEGIN AND V_SYSDAT  -- 客户开户日在180天窗口内(新客)
                     AND HAS_MBK + HAS_DEPO + HAS_FIN + HAS_LOAN >= 2 THEN  -- 持有两类及以上产品
                        CUST_ID                                  -- 计入客户ID
                  END),                                          -- 结束去重计数
               0,                                                -- 上期值置0
               PERSN_LEGAL_BK_CODE                               -- 法人机构编号
          FROM CUST_FLAGS                                        -- 打标后的结果集
        GROUP BY PATH_CODE,                                      -- 按路径分组
                 DATA_BLNG,                                      -- 按归属分组
                 STATIS_DIM,                                     -- 按维度分组
                 STATIS_CALIB,                                   -- 按口径分组
                 PERSN_LEGAL_BK_CODE;                            -- 按法人机构分组

    -------------------------------------------------------------------------
    -- INDX_0082 新增客户数 (合并 A/B)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_007          -- 插入专属累计表(0082)
        (PATH_CODE,                             -- 路径代码
         DATA_DATE,                             -- 数据日期
         DATA_BLNG,                             -- 数据归属
         STATIS_DIM,                            -- 统计维度
         STATIS_CALIB,                          -- 统计口径
         INDX_CODE,                             -- 指标代码
         CURNT_VAL,                             -- 本期值
         TERM_LAST_VAL,                         -- 上期值
         PERSN_LEGAL_BK_CODE)                   -- 法人机构编号
        WITH SCOPE_ALL AS                       -- 组装A/B各路径范围内客户
         (SELECT '08'       AS PATH_CODE,        -- 路径代码08
                 '08' AS STATIS_CALIB,        -- 统计口径
                 S.STATIS_DIM,                  -- 统计维度
                 S.DATA_BLNG,                   -- 数据归属
                 S.TERM_BEGIN_DATE,             -- 开始日期
                 TI.CUST_ID,                    -- 客户ID
                 S.PERSN_LEGAL_BK_CODE          -- 法人机构编号
            FROM TMP_STAT_INDX_SCOPE S          -- 指标范围临时表
        INNER JOIN DWD_MKT_TSK_INFO TI          -- 关联营销活动任务信息
               ON TI.MKT_ACT_ID = S.STATIS_DIM  -- 活动ID等于统计维度
              AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
              AND TI.DATA_DATE = V_SYSDAT       -- 取跑批日期当日活动
              AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID)  -- 按机构归属匹配
                OR (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))  -- 按客户经理归属匹配
          WHERE S.PATH_CODE = '08'               -- 限定路径08
            AND S.INDX_CODE = 'INDX_0082'       -- 仅取0082指标
         UNION ALL                              -- 合并(保留重复)
         SELECT '09',                            -- 路径代码B
                '09',                         -- 统计口径
                S.STATIS_DIM,                   -- 统计维度
                S.DATA_BLNG,                    -- 数据归属
                S.TERM_BEGIN_DATE,              -- 开始日期
                LV.CUST_ID,                     -- 客户ID
                S.PERSN_LEGAL_BK_CODE           -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S           -- 指标范围临时表
        INNER JOIN DWS_CUST_LVL_INFO LV         -- 关联客户层级信息
               ON S.BLNG_TYPE = 'O'             -- 归属类型为机构
              AND LV.ORG_ID = S.BLNG_ID         -- 机构ID一致
              AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
              AND LV.DATA_DATE = V_SYSDAT       -- 取跑批日期当日层级
          WHERE S.PATH_CODE = '09'               -- 限定路径09
            AND S.INDX_CODE = 'INDX_0082'       -- 仅取0082指标
         UNION ALL                              -- 合并(保留重复)
         SELECT '09',                            -- 路径代码B
                '09',                         -- 统计口径
                S.STATIS_DIM,                   -- 统计维度
                S.DATA_BLNG,                    -- 数据归属
                S.TERM_BEGIN_DATE,              -- 开始日期
                CM.CUST_ID,                     -- 客户ID
                S.PERSN_LEGAL_BK_CODE           -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S           -- 指标范围临时表
        INNER JOIN DWD_CUST_MAN CM              -- 关联客户经理归属表
               ON S.BLNG_TYPE = 'M'             -- 归属类型为客户经理
              AND CM.MNGR_POST_ID = S.BLNG_ID   -- 客户经理岗位ID一致
              AND CM.MNG_TYP = '1'              -- 客户经理类型主号
              AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
          WHERE S.PATH_CODE = '09'               -- 限定路径09
            AND S.INDX_CODE = 'INDX_0082')      -- 仅取0082指标
        SELECT SM.PATH_CODE,                    -- 路径代码
               V_SYSDAT,                        -- 数据日期=跑批日期
               SM.DATA_BLNG,                    -- 数据归属
               SM.STATIS_DIM,                   -- 统计维度
               SM.STATIS_CALIB,                 -- 统计口径
               'INDX_0082',                     -- 指标代码固定0082
               COUNT(DISTINCT CASE              -- 计数开户日期在活动/任务开始日期与跑批日期之间的新增客户
                    WHEN CI.OPEN_DATE BETWEEN SM.TERM_BEGIN_DATE AND V_SYSDAT THEN  -- 开户日在活动期内
                        SM.CUST_ID              -- 计入客户ID
                  END),                         -- 结束去重计数
               0,                               -- 上期值置0
               SM.PERSN_LEGAL_BK_CODE           -- 法人机构编号
          FROM (SELECT DISTINCT PATH_CODE,      -- 去重：路径
                                 STATIS_CALIB,  -- 口径
                                 STATIS_DIM,    -- 维度
                                 DATA_BLNG,     -- 归属
                                 TERM_BEGIN_DATE,  -- 开始日期
                                 CUST_ID,       -- 客户ID
                                 PERSN_LEGAL_BK_CODE  -- 法人机构
                   FROM SCOPE_ALL) SM           -- 范围客户去重后结果集
       LEFT JOIN DWD_CUST_INDV_INFO CI          -- 关联个人客户基本信息
              ON CI.CUST_ID = SM.CUST_ID        -- 客户ID一致
             AND CI.PERSN_LEGAL_BK_CODE = SM.PERSN_LEGAL_BK_CODE  -- 法人机构一致
        GROUP BY SM.PATH_CODE,                  -- 按路径分组
                 SM.DATA_BLNG,                  -- 按归属分组
                 SM.STATIS_DIM,                 -- 按维度分组
                 SM.STATIS_CALIB,               -- 按口径分组
                 SM.PERSN_LEGAL_BK_CODE;        -- 按法人机构分组

    -------------------------------------------------------------------------
    -- INDX_0073 手机银行客户数新增 (合并 A/B)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_007          -- 插入专属累计表(0073)
        (PATH_CODE,                             -- 路径代码
         DATA_DATE,                             -- 数据日期
         DATA_BLNG,                             -- 数据归属
         STATIS_DIM,                            -- 统计维度
         STATIS_CALIB,                          -- 统计口径
         INDX_CODE,                             -- 指标代码
         CURNT_VAL,                             -- 本期值
         TERM_LAST_VAL,                         -- 上期值
         PERSN_LEGAL_BK_CODE)                   -- 法人机构编号
        WITH SCOPE_ALL AS                       -- 组装A/B各路径范围内客户
         (SELECT '08'       AS PATH_CODE,        -- 路径代码08
                 '08' AS STATIS_CALIB,        -- 统计口径
                 S.STATIS_DIM,                  -- 统计维度
                 S.DATA_BLNG,                   -- 数据归属
                 S.TERM_BEGIN_DATE,             -- 开始日期
                 TI.CUST_ID,                    -- 客户ID
                 S.PERSN_LEGAL_BK_CODE          -- 法人机构编号
            FROM TMP_STAT_INDX_SCOPE S          -- 指标范围临时表
        INNER JOIN DWD_MKT_TSK_INFO TI          -- 关联营销活动任务信息
               ON TI.MKT_ACT_ID = S.STATIS_DIM  -- 活动ID等于统计维度
              AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
              AND TI.DATA_DATE = V_SYSDAT       -- 取跑批日期当日活动
              AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID)  -- 按机构归属匹配
                OR (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))  -- 按客户经理归属匹配
          WHERE S.PATH_CODE = '08'               -- 限定路径08
            AND S.INDX_CODE = 'INDX_0073'       -- 仅取0073指标
         UNION ALL                              -- 合并(保留重复)
         SELECT '09',                            -- 路径代码B
                '09',                         -- 统计口径
                S.STATIS_DIM,                   -- 统计维度
                S.DATA_BLNG,                    -- 数据归属
                S.TERM_BEGIN_DATE,              -- 开始日期
                LV.CUST_ID,                     -- 客户ID
                S.PERSN_LEGAL_BK_CODE           -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S           -- 指标范围临时表
        INNER JOIN DWS_CUST_LVL_INFO LV         -- 关联客户层级信息
               ON S.BLNG_TYPE = 'O'             -- 归属类型为机构
              AND LV.ORG_ID = S.BLNG_ID         -- 机构ID一致
              AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
              AND LV.DATA_DATE = V_SYSDAT       -- 取跑批日期当日层级
          WHERE S.PATH_CODE = '09'               -- 限定路径09
            AND S.INDX_CODE = 'INDX_0073'       -- 仅取0073指标
         UNION ALL                              -- 合并(保留重复)
         SELECT '09',                            -- 路径代码B
                '09',                         -- 统计口径
                S.STATIS_DIM,                   -- 统计维度
                S.DATA_BLNG,                    -- 数据归属
                S.TERM_BEGIN_DATE,              -- 开始日期
                CM.CUST_ID,                     -- 客户ID
                S.PERSN_LEGAL_BK_CODE           -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S           -- 指标范围临时表
        INNER JOIN DWD_CUST_MAN CM              -- 关联客户经理归属表
               ON S.BLNG_TYPE = 'M'             -- 归属类型为客户经理
              AND CM.MNGR_POST_ID = S.BLNG_ID   -- 客户经理岗位ID一致
              AND CM.MNG_TYP = '1'              -- 客户经理类型主号
              AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
          WHERE S.PATH_CODE = '09'               -- 限定路径09
            AND S.INDX_CODE = 'INDX_0073')      -- 仅取0073指标
        SELECT SM.PATH_CODE,                    -- 路径代码
               V_SYSDAT,                        -- 数据日期=跑批日期
               SM.DATA_BLNG,                    -- 数据归属
               SM.STATIS_DIM,                   -- 统计维度
               SM.STATIS_CALIB,                 -- 统计口径
               'INDX_0073',                     -- 指标代码固定0073
               COUNT(DISTINCT CASE              -- 计数手机银行开户日期在活动期内的新增客户
                    WHEN MI.CUST_OPEN_DATE BETWEEN SM.TERM_BEGIN_DATE AND V_SYSDAT THEN  -- 手机银行开户日在活动期内
                        SM.CUST_ID              -- 计入客户ID
                  END),                         -- 结束去重计数
               0,                               -- 上期值置0
               SM.PERSN_LEGAL_BK_CODE           -- 法人机构编号
          FROM (SELECT DISTINCT PATH_CODE,      -- 去重：路径
                                 STATIS_CALIB,  -- 口径
                                 STATIS_DIM,    -- 维度
                                 DATA_BLNG,     -- 归属
                                 TERM_BEGIN_DATE,  -- 开始日期
                                 CUST_ID,       -- 客户ID
                                 PERSN_LEGAL_BK_CODE  -- 法人机构
                   FROM SCOPE_ALL) SM           -- 范围客户去重后结果集
       LEFT JOIN MBK_CUST_INFO MI               -- 关联手机银行客户信息
              ON MI.CUST_CORE_NO = SM.CUST_ID   -- 客户核心号等于客户ID
             AND MI.INCORP_NO = SM.PERSN_LEGAL_BK_CODE  -- 法人机构一致
        GROUP BY SM.PATH_CODE,                  -- 按路径分组
                 SM.DATA_BLNG,                  -- 按归属分组
                 SM.STATIS_DIM,                 -- 按维度分组
                 SM.STATIS_CALIB,               -- 按口径分组
                 SM.PERSN_LEGAL_BK_CODE;        -- 按法人机构分组

    -------------------------------------------------------------------------
    -- INDX_0083 借记卡新开净增量(CBS发卡日期,合并 A/B)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_007                -- 插入专属累计表(0083)
        (PATH_CODE,                                   -- 路径代码
         DATA_DATE,                                   -- 数据日期
         DATA_BLNG,                                   -- 数据归属
         STATIS_DIM,                                  -- 统计维度
         STATIS_CALIB,                                -- 统计口径
         INDX_CODE,                                   -- 指标代码
         CURNT_VAL,                                   -- 本期值
         TERM_LAST_VAL,                               -- 上期值
         PERSN_LEGAL_BK_CODE)                         -- 法人机构编号
        WITH SCOPE_ALL AS                             -- 组装A/B各路径范围内客户
         (SELECT '08'       AS PATH_CODE,              -- 路径代码08
                 '08' AS STATIS_CALIB,              -- 统计口径
                 S.STATIS_DIM,                        -- 统计维度
                 S.DATA_BLNG,                         -- 数据归属
                 S.TERM_BEGIN_DATE,                   -- 开始日期
                 TI.CUST_ID,                          -- 客户ID
                 S.PERSN_LEGAL_BK_CODE                -- 法人机构编号
            FROM TMP_STAT_INDX_SCOPE S                -- 指标范围临时表
        INNER JOIN DWD_MKT_TSK_INFO TI                -- 关联营销活动任务信息
               ON TI.MKT_ACT_ID = S.STATIS_DIM        -- 活动ID等于统计维度
              AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
              AND TI.DATA_DATE = V_SYSDAT             -- 取跑批日期当日活动
              AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID)  -- 按机构归属匹配
                OR (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))  -- 按客户经理归属匹配
          WHERE S.PATH_CODE = '08'                     -- 限定路径08
            AND S.INDX_CODE = 'INDX_0083'             -- 仅取0083指标
         UNION ALL                                    -- 合并(保留重复)
         SELECT '09',                                  -- 路径代码B
                '09',                               -- 统计口径
                S.STATIS_DIM,                         -- 统计维度
                S.DATA_BLNG,                          -- 数据归属
                S.TERM_BEGIN_DATE,                    -- 开始日期
                LV.CUST_ID,                           -- 客户ID
                S.PERSN_LEGAL_BK_CODE                 -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S                 -- 指标范围临时表
        INNER JOIN DWS_CUST_LVL_INFO LV               -- 关联客户层级信息
               ON S.BLNG_TYPE = 'O'                   -- 归属类型为机构
              AND LV.ORG_ID = S.BLNG_ID               -- 机构ID一致
              AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
              AND LV.DATA_DATE = V_SYSDAT             -- 取跑批日期当日层级
          WHERE S.PATH_CODE = '09'                     -- 限定路径09
            AND S.INDX_CODE = 'INDX_0083'             -- 仅取0083指标
         UNION ALL                                    -- 合并(保留重复)
         SELECT '09',                                  -- 路径代码B
                '09',                               -- 统计口径
                S.STATIS_DIM,                         -- 统计维度
                S.DATA_BLNG,                          -- 数据归属
                S.TERM_BEGIN_DATE,                    -- 开始日期
                CM.CUST_ID,                           -- 客户ID
                S.PERSN_LEGAL_BK_CODE                 -- 法人机构编号
           FROM TMP_STAT_INDX_SCOPE S                 -- 指标范围临时表
        INNER JOIN DWD_CUST_MAN CM                    -- 关联客户经理归属表
               ON S.BLNG_TYPE = 'M'                   -- 归属类型为客户经理
              AND CM.MNGR_POST_ID = S.BLNG_ID         -- 客户经理岗位ID一致
              AND CM.MNG_TYP = '1'                    -- 客户经理类型主号
              AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构一致
          WHERE S.PATH_CODE = '09'                     -- 限定路径09
            AND S.INDX_CODE = 'INDX_0083')            -- 仅取0083指标
        SELECT SM.PATH_CODE,                          -- 路径代码
               V_SYSDAT,                              -- 数据日期=跑批日期
               SM.DATA_BLNG,                          -- 数据归属
               SM.STATIS_DIM,                         -- 统计维度
               SM.STATIS_CALIB,                       -- 统计口径
               'INDX_0083',                           -- 指标代码固定0083
               COUNT(DISTINCT C.KAHAOOOO),            -- 计数去重后的卡号(新开卡净增量)
               0,                                     -- 上期值置0
               SM.PERSN_LEGAL_BK_CODE                 -- 法人机构编号
          FROM (SELECT DISTINCT PATH_CODE,            -- 去重：路径
                                 STATIS_CALIB,        -- 口径
                                 STATIS_DIM,          -- 维度
                                 DATA_BLNG,           -- 归属
                                 TERM_BEGIN_DATE,     -- 开始日期
                                 CUST_ID,             -- 客户ID
                                 PERSN_LEGAL_BK_CODE  -- 法人机构
                   FROM SCOPE_ALL) SM                 -- 范围客户去重后结果集
        INNER JOIN CBS_KCDA_PZJCXX C                  -- 关联CBS卡类账户基本信息表
               ON C.KEHUHAOO = SM.CUST_ID             -- 客户好号等于客户ID
              AND CASE                                -- 按发卡机构号段映射法人机构
                    WHEN C.FAKAJIGO LIKE '12%' THEN '1200'  -- 12开头归1200
                    WHEN C.FAKAJIGO LIKE '15%' THEN '1500'  -- 15开头归1500
                    WHEN C.FAKAJIGO LIKE '18%' THEN '1800'  -- 18开头归1800
                    ELSE '9999'                       -- 其他归9999
                  END = SM.PERSN_LEGAL_BK_CODE        -- 映射后的机构等于法人机构编号
              AND C.FAKARIQI BETWEEN SM.TERM_BEGIN_DATE AND V_SYSDAT  -- 发卡日期在开始日期与跑批日期之间(新发卡)
              AND C.PZSYZTAI IN ('0','1','3','4','5','6','D','E','F','K','N','M','j','m','n','h','y')  -- 仅取有效卡状态
        INNER JOIN CBS_KDPA_KEHUZH K                  -- 关联CBS卡片账户客户账表
               ON K.KEHUZHAO = C.KAHAOOOO             -- 客户账号等于卡号
              AND K.ZHHUFENL IN ('1','2')             -- 一类户 二类户
        GROUP BY SM.PATH_CODE,                        -- 按路径分组
                 SM.DATA_BLNG,                        -- 按归属分组
                 SM.STATIS_DIM,                       -- 按维度分组
                 SM.STATIS_CALIB,                     -- 按口径分组
                 SM.PERSN_LEGAL_BK_CODE;              -- 按法人机构分组

    -------------------------------------------------------------------------
    -- 汇总入库收尾：记录影响行数、提交事务、写跑批日志(成功路径)
    -------------------------------------------------------------------------
    outcde := SQL%ROWCOUNT;                                   -- 输出影响行数
    COMMIT;                                                   -- 提交事务
    V_END_DATE := SYSDATE;                                    -- 记录结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时(秒)
    V_LOG_MSG := '步骤7处理完成，行数=' || NVL(outcde, 0);             -- 拼装成功日志消息
    V_LOG_FLG := 0;                                           -- 成功标志
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 调用通用跑批日志过程写成功日志
EXCEPTION
    WHEN OTHERS THEN  -- 异常捕获
        -- 异常处理：回滚事务并记录错误日志后重新抛出
        ROLLBACK;                                                 -- 回滚事务
        outcde := -1;                                             -- 输出错误标志
        V_END_DATE := SYSDATE;                                    -- 记录结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算耗时
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 取错误信息前1000字符
        V_LOG_FLG := -1;                                          -- 失败标志
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 调用通用跑批日志过程写失败日志
        RAISE;                                                    -- 重新抛出异常
END PRC_ADS_STAT_INDX_PLAN_007
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_008(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_008(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC VARCHAR2(100) := '指标数据统计步骤88处理完成 8';   -- 过程描述(写入步骤日志)
    V_PRC_NAME VARCHAR2(32)  := 'PRC_ADS_STAT_INDX_PLAN_008';   -- 过程名
    V_LOG_MSG VARCHAR2(4000);   -- 日志消息内容
    V_LOG_FLG INTEGER;          -- 日志标志(0正常 -1异常)
    V_LOG_BUTTON INTEGER := 1;  -- 日志按钮标识(固定1)
    V_NO_ID VARCHAR2(10);       -- 业务流水号(固定'0')
    V_BGN_DATE DATE;            -- 过程起始时间
    V_END_DATE DATE;            -- 过程结束时间
    V_DURA_DATE INTEGER;        -- 运行耗时(秒)
    V_YAR_BEGIN VARCHAR2(8);    -- 当年年初
    V_DAY_END   VARCHAR2(20);   -- 业务日当日末(含时分秒上限)
BEGIN
    V_NO_ID := '0';  -- 业务流水号(固定'0')
    V_BGN_DATE := SYSDATE;       -- 过程起始时间

    -- 入参校验：V_SYSDAT 必须为 8 位数字日期
    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN   -- 校验入参必须为8位数字日期
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 不合法则抛错
    END IF;

    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 跑批业务日期转 DATE

    ---------------------------------------------------------------------
    /* * 过程名 : crmdm.prc_ads_stat_indx_plan_008
      * 业务   : 一码付留存率(客户维度)
      *          INDX_0081  AUM留存率     = 年日均AUM  * 100 / 年累计交易量
      *          INDX_0069  结算存款留存率 = 年日均存款 * 100 / 年累计交易量
      * 口径   : 客户级年累计交易(00/02) >= 500 元纳入统计
      *          pay_time 为 VARCHAR2(20) 带时分秒,采用区间比较以命中索引
      **/

    ---------------------------------------------------------------------
    -- 0. 日期边界初始化
    ---------------------------------------------------------------------
    V_YAR_BEGIN := SYS_FUN_DEAL_DATE(V_SYSDAT, 13);     -- 当年年初
    V_DAY_END   := V_SYSDAT || '999999';  -- 业务日当日末(含时分秒上限)

    -- 段首自清：本过程专属汇总临时表,防止重跑/并行残留
    DELETE FROM TMP_STAT_INDX_AGGR_008;

    ---------------------------------------------------------------------
    -- 1. 0081 / 0069 合并产出：A/B 路径一次扫描,两指标共享宽表
    ---------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_008
        (PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
         DATA_DATE,      -- 数据日期
         DATA_BLNG,      -- 数据归属
         STATIS_DIM,     -- 统计维度
         STATIS_CALIB,   -- 统计口径
         INDX_CODE,      -- 指标编码
         CURNT_VAL,      -- 当前值
         TERM_LAST_VAL,  -- 期初/上期值
         PERSN_LEGAL_BK_CODE)       -- 法人机构编码
    WITH SCOPE_ALL AS
     (
        /*                                                                -- 目标客户范围：A=营销活动  B=机构/管户 --*/
        SELECT '08'                  AS PATH_CODE,                         -- 路径标识：08=营销活动
               '08'          AS STATIS_CALIB,                           -- 统计口径：营销活动
               S.STATIS_DIM,                                              -- 统计维度
               S.DATA_BLNG,                                               -- 数据归属
               S.PERSN_LEGAL_BK_CODE,                                     -- 法人机构编码
               TI.CUST_ID                                                 -- 目标客户ID
          FROM TMP_STAT_INDX_SCOPE S                                      -- 目标客户范围表
          JOIN DWD_MKT_TSK_INFO TI ON TI.MKT_ACT_ID         = S.STATIS_DIM-- 营销任务关联：营销活动ID匹配维度
                                  AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                                  AND TI.DATA_DATE           = V_SYSDAT   -- 取跑批日营销任务快照
                                  AND ((S.BLNG_TYPE = 'O' AND             -- 归属类型O：按营销人员机构匹配
                                        TI.MKT_PERSN_ORG = S.BLNG_ID) OR  -- 营销人员机构编码=归属机构(O分支)
                                        (S.BLNG_TYPE = 'M' AND            -- 归属类型M：按营销人员匹配
                                        TI.MKT_PERSN = S.BLNG_ID))        -- 营销人员编码=归属ID(M分支)
         WHERE S.PATH_CODE = '08'                                          -- 仅路径08(营销活动)
           AND S.INDX_CODE IN ('INDX_0081', 'INDX_0069')                  -- 仅0081/0069指标
        UNION ALL
        SELECT '09',                                                      -- 路径标识：B=目标任务
               '09',                                                   -- 统计口径：目标任务
               S.STATIS_DIM,                                             -- 统计维度
               S.DATA_BLNG,                                              -- 数据归属
               S.PERSN_LEGAL_BK_CODE,                                    -- 法人机构编码
               LV.CUST_ID                                                -- 目标客户ID
          FROM TMP_STAT_INDX_SCOPE S                                     -- 目标客户范围表
          JOIN DWS_CUST_LVL_INFO LV ON LV.ORG_ID            = S.BLNG_ID  -- 客户层级信息：机构ID匹配归属
                                    AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                                    AND LV.DATA_DATE           = V_SYSDAT-- 取跑批日层级快照
         WHERE S.PATH_CODE = '09'                                         -- 仅路径09
           AND S.BLNG_TYPE = 'O'                                         -- 仅归属O(机构)
           AND S.INDX_CODE IN ('INDX_0081', 'INDX_0069')                 -- 仅0081/0069指标
        UNION ALL
        SELECT '09',                                         -- 路径标识：B=目标任务
               '09',                                      -- 统计口径：目标任务
               S.STATIS_DIM,                                -- 统计维度
               S.DATA_BLNG,                                 -- 数据归属
               S.PERSN_LEGAL_BK_CODE,                       -- 法人机构编码
               CM.CUST_ID                                   -- 目标客户ID
          FROM TMP_STAT_INDX_SCOPE S                        -- 目标客户范围表
          JOIN DWD_CUST_MAN CM ON CM.MNGR_POST_ID          = S.BLNG_ID       -- 客户经理信息：管户岗ID匹配归属
                              AND CM.MNG_TYP = '1'          -- 客户经理类型=1
                              AND CM.PERSN_LEGAL_BK_CODE    = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
         WHERE S.PATH_CODE = '09'                            -- 仅路径09
           AND S.BLNG_TYPE = 'M'                            -- 仅归属M(管户)
           AND S.INDX_CODE IN ('INDX_0081', 'INDX_0069')),  -- 仅0081/0069指标
     CUST_MCT AS
     (
        /*                                                                -- 客户 → 一码付商户：先去重到(客户,商户)对,防多结算账号膨胀 --*/
        SELECT DISTINCT SC.PATH_CODE,                                     -- 路径标识
                        SC.STATIS_CALIB,                                  -- 统计口径
                        SC.STATIS_DIM,                                    -- 统计维度
                        SC.DATA_BLNG,                                     -- 数据归属
                        SC.PERSN_LEGAL_BK_CODE,                           -- 法人机构编码
                        SC.CUST_ID,                                       -- 客户ID
                        M.MCT_ID                                          -- 一码付商户ID
          FROM (SELECT DISTINCT PATH_CODE,                                -- 先对范围去重
                                STATIS_CALIB,                             -- 统计口径
                                STATIS_DIM,                               -- 统计维度
                                DATA_BLNG,                                -- 数据归属
                                PERSN_LEGAL_BK_CODE,                      -- 法人机构编码
                                CUST_ID                                   -- 客户ID
                  FROM SCOPE_ALL) SC                                      -- 目标客户范围
          JOIN DWD_CUST_INDV_INFO CI ON CI.CUST_ID            = SC.CUST_ID-- 客户个体信息
                                    AND CI.PERSN_LEGAL_BK_CODE = SC.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
          JOIN UEPP_PAY_MCT_SETTLE_ACCOUNT SA ON SA.CUST_NO = SC.CUST_ID  -- 一码付商户结算账户：客户号匹配
                                           AND SA.STATUS <> '9'           -- 排除无效(9)结算账户
          JOIN UEPP_PAY_MCT_INFO M ON M.MCT_ID      = SA.MCT_ID           -- 一码付商户信息
                                  AND M.MCT_TYPE IN ('personage', 'smallBusinesses')   -- 仅个人/小商户
                                  AND M.STATUS <> '9'),                   -- 排除无效(9)商户
     MCT_TX AS
     (
        /*              -- 商户年累计交易量预聚合：先按 mct_id 压缩订单明细 --*/
        SELECT MCT_ID,  -- 一码付商户ID
               SUM(CASE WHEN ORDER_TYPE = '01' THEN -ORDER_AMT ELSE ORDER_AMT END) AS ANNUAL_TX_AMT  -- 净额：01退款取负
          FROM UEPP_PAY_ORDER_INFO
         WHERE ORDER_TYPE IN ('00', '01')   -- 订单类型 00-支付交易  01-退款交易(值域仅此两值)
           AND STATUS = '02'            -- 订单状态  00：待付款  01：处理中 02：交易成功 03：交易失败  04：已关闭  05：已撤销  90:超时 91:异常  98：预下单  99：日终失效
           AND PAY_TIME >= V_YAR_BEGIN  -- 交易时间不早于当年年初
           AND PAY_TIME <= V_DAY_END    -- 交易时间不晚于业务日当日末
         GROUP BY MCT_ID),
     CUST_TX AS
     (
        /*                              -- 客户年累计交易量：区间比较(可走 pay_time 索引) + >=500 阈值 --*/
        SELECT CM.PATH_CODE,            -- 路径标识
               CM.STATIS_CALIB,         -- 统计口径
               CM.STATIS_DIM,           -- 统计维度
               CM.DATA_BLNG,            -- 数据归属
               CM.PERSN_LEGAL_BK_CODE,  -- 法人机构编码
               CM.CUST_ID,              -- 客户ID
               SUM(T.ANNUAL_TX_AMT) AS ANNUAL_TX_AMT   -- 客户层年累计交易量(净额)
          FROM CUST_MCT CM
          JOIN MCT_TX T ON T.MCT_ID = CM.MCT_ID        -- 关联商户交易聚合
         GROUP BY CM.PATH_CODE,  -- 按客户+维度分组
                  CM.STATIS_CALIB,
                  CM.STATIS_DIM,
                  CM.DATA_BLNG,
                  CM.PERSN_LEGAL_BK_CODE,
                  CM.CUST_ID
        HAVING SUM(T.ANNUAL_TX_AMT) >= 500),  -- 年累计交易量>=500纳入统计
     CUST_WIDE AS
     (
        /*                                        -- 客户级宽表：分母(交易量) + 分子(年日均AUM/存款),LEFT JOIN 保零余额客户 --*/
        SELECT T.PATH_CODE,                       -- 路径标识
               T.STATIS_CALIB,                    -- 统计口径
               T.STATIS_DIM,                      -- 统计维度
               T.DATA_BLNG,                       -- 数据归属
               T.PERSN_LEGAL_BK_CODE,             -- 法人机构编码
               T.ANNUAL_TX_AMT,                   -- 年累计交易量(分母)
               NVL(B.AUM_BAL, 0)  AS ANNUAL_AUM,  -- 分子：年日均AUM
               NVL(B.DEPO_BAL, 0) AS ANNUAL_DEPO  -- 分子：年日均存款
          FROM CUST_TX T
          LEFT JOIN DWS_CUST_ASSE_LIAB B ON B.CUST_ID            = T.CUST_ID  -- 客户资产负债表：客户ID匹配
                                        AND B.PERSN_LEGAL_BK_CODE = T.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                                        AND B.DATA_DATE           = V_SYSDAT  -- 取跑批日快照
                                        AND B.BAL_TYPE = '4')                 -- 余额类型=4(年日均)

    /*                          -- 0081：AUM留存率 --*/
    SELECT PATH_CODE,           -- 路径标识
           V_SYSDAT,            -- 数据日期
           DATA_BLNG,           -- 数据归属
           STATIS_DIM,          -- 统计维度
           STATIS_CALIB,        -- 统计口径
           'INDX_0081',         -- 指标编码：AUM留存率
           ROUND(SUM(ANNUAL_AUM) * 100 / NULLIF(SUM(ANNUAL_TX_AMT), 0), 2),  -- 年日均AUM/年累计交易量*100(分母0时置NULL)
           0,                   -- 期初/上期值(固定0)
           PERSN_LEGAL_BK_CODE  -- 法人机构编码
      FROM CUST_WIDE
     GROUP BY PATH_CODE,  -- 按路径/口径/归属/维度/法人分组
              STATIS_CALIB,
              DATA_BLNG,
              STATIS_DIM,
              PERSN_LEGAL_BK_CODE
    UNION ALL
    /*                          -- 0069：结算存款留存率 --*/
    SELECT PATH_CODE,           -- 路径标识
           V_SYSDAT,            -- 数据日期
           DATA_BLNG,           -- 数据归属
           STATIS_DIM,          -- 统计维度
           STATIS_CALIB,        -- 统计口径
           'INDX_0069',         -- 指标编码：结算存款留存率
           ROUND(SUM(ANNUAL_DEPO) * 100 / NULLIF(SUM(ANNUAL_TX_AMT), 0), 2),  -- 年日均存款/年累计交易量*100(分母0时置NULL)
           0,                   -- 期初/上期值(固定0)
           PERSN_LEGAL_BK_CODE  -- 法人机构编码
      FROM CUST_WIDE
     GROUP BY PATH_CODE,  -- 按路径/口径/归属/维度/法人分组
              STATIS_CALIB,
              DATA_BLNG,
              STATIS_DIM,
              PERSN_LEGAL_BK_CODE;

    ---------------------------------------------------------------------
    -- 2. 0066 个贷新形成不良贷款率: 期初基准(prc_ads_stat_indx_plan_002 3.4段建立)
    --    分母 = scope客户 ∩ 期初基准(正常1/关注2账户)余额合计
    --    分子 = 同上账户中期末(DWD_ACCT_LOAN)变不良(3次级/4可疑/5损失)的当前余额合计
    --           (期间结清账户期末不存在, 不计入分子; 期间新开账户期初不在基准, 不计入分母)
    --    率   = ROUND(分子/分母*100, 2), 分母为0时输出 NULL
    ---------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_008
        (PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
         DATA_DATE,      -- 数据日期
         DATA_BLNG,      -- 数据归属
         STATIS_DIM,     -- 统计维度
         STATIS_CALIB,   -- 统计口径
         INDX_CODE,      -- 指标编码
         CURNT_VAL,      -- 当前值
         TERM_LAST_VAL,  -- 期初/上期值
         PERSN_LEGAL_BK_CODE)       -- 法人机构编码
    WITH SCOPE_CUST AS
     (
        SELECT SC.PATH_CODE,  -- 路径标识
               CASE
                   WHEN SC.PATH_CODE = '08' THEN
                      '08'
                   ELSE
                      '09'
               END AS STATIS_CALIB,                                               -- 口径：A→营销活动,否则→目标任务
               SC.STATIS_DIM,                                                     -- 统计维度
               SC.DATA_BLNG,                                                      -- 数据归属
               SC.PERSN_LEGAL_BK_CODE,                                            -- 法人机构编码
               SC.CUST_ID                                                         -- 目标客户ID
          FROM (SELECT DISTINCT S.PATH_CODE,                                      -- 仅0066目标客户,路径08去重
                                S.STATIS_DIM,                                     -- 统计维度
                                S.DATA_BLNG,                                      -- 数据归属
                                S.PERSN_LEGAL_BK_CODE,                            -- 法人机构编码
                                TI.CUST_ID                                        -- 目标客户ID
                  FROM TMP_STAT_INDX_SCOPE S                                      -- 目标客户范围表
                  JOIN DWD_MKT_TSK_INFO TI ON TI.MKT_ACT_ID         = S.STATIS_DIM-- 营销任务：活动ID匹配
                                          AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                                          AND TI.DATA_DATE           = V_SYSDAT   -- 跑批日快照
                                          AND ((S.BLNG_TYPE = 'O' AND             -- 归属O：按营销人员机构匹配
                                                TI.MKT_PERSN_ORG = S.BLNG_ID) OR  -- 营销人员机构编码=归属机构(O分支)
                                                (S.BLNG_TYPE = 'M' AND            -- 归属M：按营销人员匹配
                                                TI.MKT_PERSN = S.BLNG_ID))        -- 营销人员编码=归属ID(M分支)
                 WHERE S.PATH_CODE = '08'                                          -- 仅路径08(营销活动)
                   AND S.INDX_CODE = 'INDX_0066'                                  -- 仅0066指标
                UNION
                SELECT DISTINCT S.PATH_CODE,   -- 0066目标客户,09机构路径去重
                                S.STATIS_DIM,  -- 统计维度
                                S.DATA_BLNG,   -- 数据归属
                                S.PERSN_LEGAL_BK_CODE,   -- 法人机构编码
                                LV.CUST_ID     -- 目标客户ID
                  FROM TMP_STAT_INDX_SCOPE S
                  JOIN DWS_CUST_LVL_INFO LV ON LV.ORG_ID            = S.BLNG_ID   -- 客户层级：机构ID匹配归属
                                           AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                                           AND LV.DATA_DATE           = V_SYSDAT  -- 跑批日快照
                 WHERE S.PATH_CODE = '09'                                          -- 仅路径09
                   AND S.BLNG_TYPE = 'O'                                          -- 仅归属O(机构)
                   AND S.INDX_CODE = 'INDX_0066'                                  -- 仅0066指标
                UNION
                SELECT DISTINCT S.PATH_CODE,   -- 0066目标客户,09管户路径去重
                                S.STATIS_DIM,  -- 统计维度
                                S.DATA_BLNG,   -- 数据归属
                                S.PERSN_LEGAL_BK_CODE,   -- 法人机构编码
                                CM.CUST_ID     -- 目标客户ID
                  FROM TMP_STAT_INDX_SCOPE S
                  JOIN DWD_CUST_MAN CM ON CM.MNGR_POST_ID          = S.BLNG_ID  -- 客户经理：管户岗ID匹配归属
                                      AND CM.MNG_TYP = '1'                      -- 客户经理类型=1
                                      AND CM.PERSN_LEGAL_BK_CODE    = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                 WHERE S.PATH_CODE = '09'                                        -- 仅路径09
                   AND S.BLNG_TYPE = 'M'                                        -- 仅归属M(管户)
                   AND S.INDX_CODE = 'INDX_0066') SC),                          -- 仅0066指标
     DENOM AS
     (
        /*                              -- 分母：期初基准(正常1/关注2账户)余额合计 --*/
        SELECT SC.PATH_CODE,            -- 路径标识
               SC.STATIS_CALIB,         -- 统计口径
               SC.STATIS_DIM,           -- 统计维度
               SC.DATA_BLNG,            -- 数据归属
               SC.PERSN_LEGAL_BK_CODE,  -- 法人机构编码
               SUM(NVL(B.LOAN_BAL, 0)) AS BASE_AMT   -- 期初基准账户余额合计(分母)
          FROM SCOPE_CUST SC
          JOIN TMP_STAT_INDX_LOAN_BASE B ON B.PATH_CODE        = SC.PATH_CODE   -- 期初贷款基准表：路径匹配
                                        AND B.STATIS_DIM       = SC.STATIS_DIM  -- 维度匹配
                                        AND B.DATA_BLNG        = SC.DATA_BLNG   -- 数据归属匹配
                                        AND B.PERSN_LEGAL_BK_CODE = SC.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                                        AND B.CUST_ID          = SC.CUST_ID     -- 客户匹配
         GROUP BY SC.PATH_CODE,                                                 -- 按客户+维度聚合
                  SC.STATIS_CALIB,
                  SC.STATIS_DIM,
                  SC.DATA_BLNG,
                  SC.PERSN_LEGAL_BK_CODE),
     NUMER AS
     (
        /*                              -- 分子：期初基准账户中期末变不良(3/4/5)的当前余额合计 --*/
        SELECT SC.PATH_CODE,            -- 路径标识
               SC.STATIS_CALIB,         -- 统计口径
               SC.STATIS_DIM,           -- 统计维度
               SC.DATA_BLNG,            -- 数据归属
               SC.PERSN_LEGAL_BK_CODE,  -- 法人机构编码
               SUM(NVL(A.BAL, 0)) AS BAD_AMT   -- 变不良账户当前余额合计(分子)
          FROM SCOPE_CUST SC
          JOIN TMP_STAT_INDX_LOAN_BASE B ON B.PATH_CODE        = SC.PATH_CODE    -- 期初贷款基准表：路径匹配
                                        AND B.STATIS_DIM       = SC.STATIS_DIM   -- 维度匹配
                                        AND B.DATA_BLNG        = SC.DATA_BLNG    -- 数据归属匹配
                                        AND B.PERSN_LEGAL_BK_CODE = SC.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                                        AND B.CUST_ID          = SC.CUST_ID      -- 客户匹配
          JOIN DWD_ACCT_LOAN A ON A.ACCT_ID          = B.ACCT_ID                 -- 期末贷款账户：账号匹配期初基准
                              AND A.CUST_ID          = B.CUST_ID                 -- 客户ID匹配
                              AND A.PERSN_LEGAL_BK_CODE = B.PERSN_LEGAL_BK_CODE  -- 法人机构匹配
                              AND A.CATE_5LVL IN ('3', '4', '5')                 -- 五级分类：3次级/4可疑/5损失(不良)
         GROUP BY SC.PATH_CODE,                                                  -- 按客户+维度聚合
                  SC.STATIS_CALIB,
                  SC.STATIS_DIM,
                  SC.DATA_BLNG,
                  SC.PERSN_LEGAL_BK_CODE)
    SELECT D.PATH_CODE,                                        -- 路径标识
           V_SYSDAT,                                           -- 数据日期
           D.DATA_BLNG,                                        -- 数据归属
           D.STATIS_DIM,                                       -- 统计维度
           D.STATIS_CALIB,                                     -- 统计口径
           'INDX_0066',                                        -- 指标编码：个贷新形成不良贷款率
           ROUND(NVL(N.BAD_AMT, 0) * 100 / NULLIF(D.BASE_AMT, 0), 2),   -- 分子/分母*100(分母0置NULL)
           0,                                                  -- 期初/上期值(固定0)
           D.PERSN_LEGAL_BK_CODE                               -- 法人机构编码
      FROM DENOM D                                             -- 分母表
      LEFT JOIN NUMER N ON N.PATH_CODE         = D.PATH_CODE   -- 关联分子：路径匹配
                       AND N.STATIS_DIM        = D.STATIS_DIM  -- 维度匹配
                       AND N.DATA_BLNG         = D.DATA_BLNG   -- 数据归属匹配
                       AND N.PERSN_LEGAL_BK_CODE = D.PERSN_LEGAL_BK_CODE;   -- 法人机构匹配

    outcde := SQL%ROWCOUNT;  -- 写入行数(取最后DML影响行数)

    -- 日志记录(正常完成)
    COMMIT;                                                   -- 提交事务
    V_END_DATE := SYSDATE;                                    -- 过程结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 运行耗时(秒)
    V_LOG_MSG := '步骤8处理完成，行数=' || NVL(outcde, 0);             -- 拼接日志消息(含写入行数)
    V_LOG_FLG := 0;                                           -- 日志标志：0=正常
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 写入步骤执行日志
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;                                                 -- 异常回滚
        outcde := -1;                                             -- 异常标识：-1
        V_END_DATE := SYSDATE;                                    -- 过程结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 运行耗时(秒)
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 截取异常信息(前1000字符)
        V_LOG_FLG := -1;                                          -- 日志标志：-1=异常
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);  -- 写入异常日志
        RAISE;                                                    -- 重新抛出异常
END PRC_ADS_STAT_INDX_PLAN_008
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_009(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_009(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC   VARCHAR2(100) := '指标数据统计步骤99处理完成 9';  -- 过程描述(写入步骤日志；文本中'步骤99'与过程号009不一致【待确认】)
    V_PRC_NAME   VARCHAR2(32)  := 'PRC_ADS_STAT_INDX_PLAN_009';   -- 过程名
    V_LOG_MSG    VARCHAR2(4000);                       -- 日志消息内容
    V_LOG_FLG    INTEGER;                              -- 日志标志(0正常 -1异常)
    V_LOG_BUTTON INTEGER := 1;                         -- 日志按钮标识(固定1)
    V_NO_ID      VARCHAR2(10);                         -- 业务流水号(固定'0')
    V_BGN_DATE   DATE;                                 -- 过程起始时间
    V_END_DATE   DATE;                                 -- 过程结束时间
    V_DURA_DATE  INTEGER;                              -- 运行耗时(秒)
BEGIN
    -------------------------------------------------------------------------
    -- 运行变量初始化与入参校验
    -------------------------------------------------------------------------
    V_NO_ID := '0';                                                -- 业务流水号(固定 '0')【待确认：取值与用途】
    V_BGN_DATE := SYSDATE;                                         -- 过程起始时间
    IF V_SYSDAT IS NULL OR NOT REGEXP_LIKE(V_SYSDAT, '^[0-9]{8}$') THEN  -- 校验入参必须为8位数字日期
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 不合法则抛错
    END IF;
    V_END_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');  -- 跑批业务日期转 DATE

    -------------------------------------------------------------------------
    -- 段首自清：清空本过程专属汇总临时表,防止重跑/并行跑批残留
    -------------------------------------------------------------------------
    DELETE FROM TMP_STAT_INDX_AGGR_009;

    -------------------------------------------------------------------------
    -- 0074/0075：手机银行交易金额/笔数 (合并 A/B 路径)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_009
    (
        PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
        DATA_DATE,      -- 数据日期
        DATA_BLNG,      -- 数据归属
        STATIS_DIM,     -- 统计维度
        STATIS_CALIB,   -- 统计口径
        INDX_CODE,      -- 指标编码
        CURNT_VAL,      -- 当前值
        TERM_LAST_VAL,  -- 期初/上期值
        PERSN_LEGAL_BK_CODE  -- 法人机构编码
    )
    WITH SCOPE_ALL AS
    (
        -- 统一获取 A/B 路径的目标客户范围
        SELECT '08'           AS PATH_CODE,                          -- 路径标识：08=营销活动
               '08'      AS STATIS_CALIB,                         -- 统计口径：营销活动
               S.STATIS_DIM,                                        -- 统计维度
               S.DATA_BLNG,                                         -- 数据归属
               S.TERM_BEGIN_DATE,                                   -- 本期起始日期(统计起点)
               TI.CUST_ID,                                          -- 目标客户ID
               S.PERSN_LEGAL_BK_CODE                                -- 法人机构编码
          FROM TMP_STAT_INDX_SCOPE S                                -- 目标客户范围表
         INNER JOIN DWD_MKT_TSK_INFO TI                             -- 营销任务信息
                 ON TI.MKT_ACT_ID = S.STATIS_DIM                    -- 营销活动ID匹配维度
                AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构匹配
                AND TI.DATA_DATE = V_SYSDAT                         -- 取跑批日营销任务快照
                AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID)   -- 归属O：按营销人员机构匹配
                     OR (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))   -- 归属M：按营销人员匹配
         WHERE S.PATH_CODE = '08'                                    -- 仅路径08(营销活动)
           AND S.INDX_CODE IN ('INDX_0074', 'INDX_0075')            -- 仅0074/0075指标
        UNION ALL
        SELECT '09'           AS PATH_CODE,   -- 路径标识：09=目标任务
               '09'      AS STATIS_CALIB,  -- 统计口径：目标任务
               S.STATIS_DIM,                 -- 统计维度
               S.DATA_BLNG,                  -- 数据归属
               S.TERM_BEGIN_DATE,            -- 本期起始日期
               LV.CUST_ID,                   -- 目标客户ID
               S.PERSN_LEGAL_BK_CODE         -- 法人机构编码
          FROM TMP_STAT_INDX_SCOPE S         -- 目标客户范围表
         INNER JOIN DWS_CUST_LVL_INFO LV     -- 客户层级信息
                 ON S.BLNG_TYPE = 'O'        -- 仅归属O(机构)
                AND LV.ORG_ID = S.BLNG_ID    -- 机构ID匹配归属
                AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                AND LV.DATA_DATE = V_SYSDAT  -- 取跑批日层级快照
         WHERE S.PATH_CODE = '09'             -- 仅路径09
           AND S.INDX_CODE IN ('INDX_0074', 'INDX_0075')   -- 仅0074/0075指标
        UNION ALL
        SELECT '09'           AS PATH_CODE,       -- 路径标识：09=目标任务
               '09'      AS STATIS_CALIB,      -- 统计口径：目标任务
               S.STATIS_DIM,                     -- 统计维度
               S.DATA_BLNG,                      -- 数据归属
               S.TERM_BEGIN_DATE,                -- 本期起始日期
               CM.CUST_ID,                       -- 目标客户ID
               S.PERSN_LEGAL_BK_CODE             -- 法人机构编码
          FROM TMP_STAT_INDX_SCOPE S             -- 目标客户范围表
         INNER JOIN DWD_CUST_MAN CM              -- 客户经理信息
                 ON S.BLNG_TYPE = 'M'            -- 仅归属M(管户)
                AND CM.MNGR_POST_ID = S.BLNG_ID  -- 管户岗ID匹配归属
                AND CM.MNG_TYP = '1'             -- 客户经理类型=1
                AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
         WHERE S.PATH_CODE = '09'                 -- 仅路径09
           AND S.INDX_CODE IN ('INDX_0074', 'INDX_0075')   -- 仅0074/0075指标
    ),
    SCOPE_DISTINCT AS
    (
        -- 按维度去重后的目标客户范围
        SELECT DISTINCT PATH_CODE,        -- 路径标识
                        STATIS_CALIB,     -- 统计口径
                        STATIS_DIM,       -- 统计维度
                        DATA_BLNG,        -- 数据归属
                        TERM_BEGIN_DATE,  -- 本期起始日期
                        CUST_ID,          -- 客户ID
                        PERSN_LEGAL_BK_CODE   -- 法人机构编码
          FROM SCOPE_ALL
    ),
    MBK_BASE AS
    (
        -- 预关联客户基础信息,避免后续 10 个交易表重复 JOIN
        SELECT SC.PATH_CODE,        -- 路径标识
               SC.STATIS_CALIB,     -- 统计口径
               SC.STATIS_DIM,       -- 统计维度
               SC.DATA_BLNG,        -- 数据归属
               SC.PERSN_LEGAL_BK_CODE,  -- 法人机构编码
               SC.TERM_BEGIN_DATE,  -- 本期起始日期
               MI.CUST_NO           -- 手机银行客户号
          FROM SCOPE_DISTINCT SC
         INNER JOIN MBK_CUST_INFO MI                       -- 手机银行客户信息
                 ON MI.CUST_CORE_NO = SC.CUST_ID           -- 核心客户号匹配客户ID
                AND MI.INCORP_NO = SC.PERSN_LEGAL_BK_CODE  -- 法人机构匹配
         INNER JOIN DWD_CUST_INDV_INFO CI                  -- 客户个体信息
                 ON CI.CUST_ID = SC.CUST_ID                -- 客户ID匹配
                AND CI.PERSN_LEGAL_BK_CODE = SC.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
    ),
    MBK_TRANS_ALL AS
    (
        -- 商圈
        SELECT B.PATH_CODE,                           -- 路径标识
               B.STATIS_CALIB,                        -- 统计口径
               B.STATIS_DIM,                          -- 统计维度
               B.DATA_BLNG,                           -- 数据归属
               B.PERSN_LEGAL_BK_CODE,                 -- 法人机构编码
               Y.AMT     AS TRAN_AMT,                 -- 商圈交易金额
               1         AS TRAN_NUM                  -- 商圈交易笔数(固定 1)
          FROM MBK_BASE B                             -- 复用客户基础信息
         INNER JOIN MBK_CUST_ACCT CA ON CA.CUST_NO = B.CUST_NO   -- 手机银行客户账户：按客户号关联
         INNER JOIN IBP_IB_LIST_PLAT Y                -- 平台交易流水
                 ON Y.ACCT_NO = CA.ACCT               -- 账号匹配账户
                AND Y.ITEM_ID = '100015'              -- 场景ID：商圈
                AND Y.CHANNEL_ID = '3031'             -- 渠道=3031(手机银行)
                AND Y.PLAT_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
                AND CASE SUBSTR(Y.BRANCH_CODE, 1, 2)  -- 机构前两位折算核算机构
                        WHEN '12' THEN '1200'
                        WHEN '15' THEN '1500'
                        WHEN '18' THEN '1800'
                        ELSE '9999'
                    END = B.PERSN_LEGAL_BK_CODE
        UNION ALL
        -- 酷屏
        SELECT B.PATH_CODE,                           -- 路径标识
               B.STATIS_CALIB,                        -- 统计口径
               B.STATIS_DIM,                          -- 统计维度
               B.DATA_BLNG,                           -- 数据归属
               B.PERSN_LEGAL_BK_CODE,                 -- 法人机构编码
               Y.AMT,                                 -- 酷屏交易金额
               1                                      -- 交易笔数(固定1)
          FROM MBK_BASE B                             -- 复用客户基础信息
         INNER JOIN MBK_CUST_ACCT CA ON CA.CUST_NO = B.CUST_NO   -- 手机银行客户账户：按客户号关联
         INNER JOIN IBP_IB_LIST_PLAT Y                -- 平台交易流水
                 ON Y.ACCT_NO = CA.ACCT               -- 账号匹配账户
                AND Y.ITEM_ID = '100012'              -- 场景ID：酷屏
                AND Y.CHANNEL_ID = '3031'             -- 渠道=3031(手机银行)
                AND Y.SETTLE_CD_FLAG = 'D'            -- 结算码标志=D
                AND Y.PLAT_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
                AND CASE SUBSTR(Y.BRANCH_CODE, 1, 2)  -- 机构前两位折算核算机构
                        WHEN '12' THEN '1200'
                        WHEN '15' THEN '1500'
                        WHEN '18' THEN '1800'
                        ELSE '9999'
                    END = B.PERSN_LEGAL_BK_CODE
        UNION ALL
        -- 转账
        SELECT B.PATH_CODE,                -- 路径标识
               B.STATIS_CALIB,             -- 统计口径
               B.STATIS_DIM,               -- 统计维度
               B.DATA_BLNG,                -- 数据归属
               B.PERSN_LEGAL_BK_CODE,      -- 法人机构编码
               T.TRAN_AMT,                 -- 转账交易金额
               1                           -- 交易笔数(固定1)
          FROM MBK_BASE B                  -- 复用客户基础信息
         INNER JOIN MBK_CUST_LOG_TRAN T    -- 转账交易流水
                 ON T.CUST_NO = B.CUST_NO  -- 按客户号关联
                AND T.TRAN_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
                AND T.TRAN_STATUS = '1'    -- 交易状态=1(成功)
                AND NVL(T.TRAN_AMT, 0) <> 0-- 排除交易金额为空的记录
        UNION ALL
        -- 理财
        SELECT B.PATH_CODE,                 -- 路径标识
               B.STATIS_CALIB,              -- 统计口径
               B.STATIS_DIM,                -- 统计维度
               B.DATA_BLNG,                 -- 数据归属
               B.PERSN_LEGAL_BK_CODE,       -- 法人机构编码
               F.TRAN_AMT,                  -- 理财交易金额
               1                            -- 交易笔数(固定1)
          FROM MBK_BASE B                   -- 复用客户基础信息
         INNER JOIN MBK_CUST_LOG_FINANCE F  -- 理财交易流水
                 ON F.CUST_NO = B.CUST_NO   -- 按客户号关联
                AND F.TRAN_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
                AND F.TRAN_STATUS = '1'     -- 交易状态=1(成功)
                AND NVL(F.TRAN_AMT, 0) <> 0 -- 排除交易金额为空的记录
        UNION ALL
        -- 生活缴费
        SELECT B.PATH_CODE,                                     -- 路径标识
               B.STATIS_CALIB,                                  -- 统计口径
               B.STATIS_DIM,                                    -- 统计维度
               B.DATA_BLNG,                                     -- 数据归属
               B.PERSN_LEGAL_BK_CODE,                           -- 法人机构编码
               CAST(NULLIF(F.TRAN_AMT, '') AS DECIMAL(31, 2)),  -- 缴费金额(空串转 NULL 再转 DECIMAL)
               1                                                -- 交易笔数(固定1)
          FROM MBK_BASE B                                       -- 复用客户基础信息
         INNER JOIN MBK_CUST_LOG_FEE F                          -- 生活缴费交易流水
                 ON F.CUST_NO = B.CUST_NO                       -- 按客户号关联
                AND F.TRAN_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
                AND F.TRAN_STATUS = '1'                         -- 交易状态=1(成功)
                AND NVL(CAST(NULLIF(F.TRAN_AMT, '') AS DECIMAL(31, 2)), 0) <> 0   -- 排除金额为空记录
                AND CASE SUBSTR(F.DEPT_ID, 1, 2)                -- 机构前两位折算核算机构
                        WHEN '12' THEN '1200'
                        WHEN '15' THEN '1500'
                        WHEN '18' THEN '1800'
                        ELSE '9999'
                    END = B.PERSN_LEGAL_BK_CODE
        UNION ALL
        -- 无卡预约取款
        SELECT B.PATH_CODE,                              -- 路径标识
               B.STATIS_CALIB,                           -- 统计口径
               B.STATIS_DIM,                             -- 统计维度
               B.DATA_BLNG,                              -- 数据归属
               B.PERSN_LEGAL_BK_CODE,                    -- 法人机构编码
               CAST(NULLIF(O.TRAN_AMT, '') AS DECIMAL(31, 2)),   -- 取款交易金额
               1                                         -- 交易笔数(固定1)
          FROM MBK_BASE B                                -- 复用客户基础信息
         INNER JOIN MBK_CUST_LOG_OPER O                  -- 手机银行操作流水(无卡取款)
                 ON O.CUST_NO = B.CUST_NO                -- 按客户号关联
                AND O.TRAN_CODE = 'atm/noCardPredMoney'  -- 交易码：无卡预约取款
                AND O.TRAN_STATUS = '1'                  -- 交易状态=1(成功)
                AND O.TRAN_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
        UNION ALL
        -- 扫码取款
        SELECT B.PATH_CODE,                    -- 路径标识
               B.STATIS_CALIB,                 -- 统计口径
               B.STATIS_DIM,                   -- 统计维度
               B.DATA_BLNG,                    -- 数据归属
               B.PERSN_LEGAL_BK_CODE,          -- 法人机构编码
               CAST(NULLIF(P.SENCE_VALUE, '') AS DECIMAL(31, 2)),   -- 扫码取款交易金额
               1                               -- 交易笔数(固定1)
          FROM MBK_BASE B                      -- 复用客户基础信息
         INNER JOIN MBK_MKP_PROCESS_INFO P     -- 移动营销扫码取款处理信息
                 ON P.CUST_NO = B.CUST_NO      -- 按客户号关联
                AND P.TRANS_SN NOT LIKE 'AP%'  -- 排除预约类(AP开头)流水
                AND LENGTH(P.TRANS_SN) > 18    -- 流水号长度>18(区分真实交易)
                AND P.SENCE_TIME BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易时间在本期区间
        UNION ALL
        -- 存款/乐惠存
        SELECT B.PATH_CODE,                   -- 路径标识
               B.STATIS_CALIB,                -- 统计口径
               B.STATIS_DIM,                  -- 统计维度
               B.DATA_BLNG,                   -- 数据归属
               B.PERSN_LEGAL_BK_CODE,         -- 法人机构编码
               B2.TRAN_AMT,                   -- 存款/乐惠存交易金额
               1                              -- 交易笔数(固定1)
          FROM MBK_BASE B                     -- 复用客户基础信息
         INNER JOIN MBK_CUST_LOG_BASE_FINANCE B2   -- 基础金融产品交易流水(存款类)
                 ON B2.CUST_NO = B.CUST_NO    -- 按客户号关联
                AND B2.TRAN_STATUS = '1'      -- 交易状态=1(成功)
                AND B2.TRAN_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
                AND NVL(B2.TRAN_AMT, 0) <> 0  -- 排除交易金额为空的记录
        UNION ALL
        -- 贷款
        SELECT B.PATH_CODE,                                        -- 路径标识
               B.STATIS_CALIB,                                     -- 统计口径
               B.STATIS_DIM,                                       -- 统计维度
               B.DATA_BLNG,                                        -- 数据归属
               B.PERSN_LEGAL_BK_CODE,                              -- 法人机构编码
               CAST(NULLIF(L.BUSINESSSUM, '') AS DECIMAL(31, 2)),  -- 贷款业务金额(空串转NULL再转DECIMAL)
               1                                                   -- 交易笔数(固定1)
          FROM MBK_BASE B                                          -- 复用客户基础信息
         INNER JOIN MBK_CUST_LOG_LOAN L                            -- 贷款交易流水
                 ON L.CUST_NO = B.CUST_NO                          -- 按客户号关联
                AND L.TRAN_DATE BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易日期在本期区间
                AND NVL(CAST(NULLIF(L.BUSINESSSUM, '') AS DECIMAL(31, 2)), 0) <> 0   -- 排除金额为空记录
        UNION ALL
        -- 移动支付
        SELECT B.PATH_CODE,                                    -- 路径标识
               B.STATIS_CALIB,                                 -- 统计口径
               B.STATIS_DIM,                                   -- 统计维度
               B.DATA_BLNG,                                    -- 数据归属
               B.PERSN_LEGAL_BK_CODE,                          -- 法人机构编码
               CAST(NULLIF(Q.TXN_AMT, '') AS DECIMAL(31, 2)),  -- 移动支付交易金额
               1                                               -- 交易笔数(固定1)
          FROM MBK_BASE B                                      -- 复用客户基础信息
         INNER JOIN MBK_QR_C2B_QUERYTRANS Q                    -- 扫码(C2B)交易查询流水
                 ON Q.CUST_NO = B.CUST_NO                      -- 按客户号关联
                AND Q.STATUS = '1'                             -- 交易状态=1(成功)
                AND Q.ORDERTIME BETWEEN B.TERM_BEGIN_DATE AND V_SYSDAT   -- 交易时间在本期区间
                AND NVL(CAST(NULLIF(Q.TXN_AMT, '') AS DECIMAL(31, 2)), 0) <> 0   -- 排除金额为空记录
    )
    SELECT PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
           V_SYSDAT,       -- 数据日期(跑批业务日期)
           DATA_BLNG,      -- 数据归属
           STATIS_DIM,     -- 统计维度
           STATIS_CALIB,   -- 统计口径
           'INDX_0074',    -- 金额指标
           SUM(TRAN_AMT),  -- 交易金额合计
           0,              -- 期初/上期值(本期无上期对照)
           PERSN_LEGAL_BK_CODE  -- 法人机构编码
      FROM MBK_TRANS_ALL
     GROUP BY PATH_CODE,
              DATA_BLNG,
              STATIS_DIM,
              STATIS_CALIB,
              PERSN_LEGAL_BK_CODE
    UNION ALL
    SELECT PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
           V_SYSDAT,       -- 数据日期(跑批业务日期)
           DATA_BLNG,      -- 数据归属
           STATIS_DIM,     -- 统计维度
           STATIS_CALIB,   -- 统计口径
           'INDX_0075',    -- 笔数指标
           SUM(TRAN_NUM),  -- 交易笔数合计
           0,              -- 期初/上期值(本期无上期对照)
           PERSN_LEGAL_BK_CODE  -- 法人机构编码
      FROM MBK_TRANS_ALL
     GROUP BY PATH_CODE,
              DATA_BLNG,
              STATIS_DIM,
              STATIS_CALIB,
              PERSN_LEGAL_BK_CODE;

    -------------------------------------------------------------------------
    -- 0078/0079：一码付交易金额/笔数 (合并 A/B 路径)
    -------------------------------------------------------------------------
    INSERT INTO TMP_STAT_INDX_AGGR_009
    (
        PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
        DATA_DATE,      -- 数据日期
        DATA_BLNG,      -- 数据归属
        STATIS_DIM,     -- 统计维度
        STATIS_CALIB,   -- 统计口径
        INDX_CODE,      -- 指标编码
        CURNT_VAL,      -- 当前值
        TERM_LAST_VAL,  -- 期初/上期值
        PERSN_LEGAL_BK_CODE  -- 法人机构编码
    )
    WITH SCOPE_ALL AS
    (
        -- 统一获取 A/B 路径的目标客户范围
        SELECT '08'           AS PATH_CODE,                          -- 路径标识：08=营销活动
               '08'      AS STATIS_CALIB,                         -- 统计口径：营销活动
               S.STATIS_DIM,                                        -- 统计维度
               S.DATA_BLNG,                                         -- 数据归属
               S.TERM_BEGIN_DATE,                                   -- 本期起始日期(统计起点)
               TI.CUST_ID,                                          -- 目标客户ID
               S.PERSN_LEGAL_BK_CODE                                -- 法人机构编码
          FROM TMP_STAT_INDX_SCOPE S                                -- 目标客户范围表
         INNER JOIN DWD_MKT_TSK_INFO TI                             -- 营销任务信息
                 ON TI.MKT_ACT_ID = S.STATIS_DIM                    -- 营销活动ID匹配维度
                AND TI.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE  -- 法人机构匹配
                AND TI.DATA_DATE = V_SYSDAT                         -- 取跑批日营销任务快照
                AND ((S.BLNG_TYPE = 'O' AND TI.MKT_PERSN_ORG = S.BLNG_ID)   -- 归属O：按营销人员机构匹配
                     OR (S.BLNG_TYPE = 'M' AND TI.MKT_PERSN = S.BLNG_ID))   -- 归属M：按营销人员匹配
         WHERE S.PATH_CODE = '08'                                    -- 仅路径08(营销活动)
           AND S.INDX_CODE IN ('INDX_0078', 'INDX_0079')            -- 仅0078/0079指标
        UNION ALL
        SELECT '09'           AS PATH_CODE,   -- 路径标识：09=目标任务
               '09'      AS STATIS_CALIB,  -- 统计口径：目标任务
               S.STATIS_DIM,                 -- 统计维度
               S.DATA_BLNG,                  -- 数据归属
               S.TERM_BEGIN_DATE,            -- 本期起始日期
               LV.CUST_ID,                   -- 目标客户ID
               S.PERSN_LEGAL_BK_CODE         -- 法人机构编码
          FROM TMP_STAT_INDX_SCOPE S         -- 目标客户范围表
         INNER JOIN DWS_CUST_LVL_INFO LV     -- 客户层级信息
                 ON S.BLNG_TYPE = 'O'        -- 仅归属O(机构)
                AND LV.ORG_ID = S.BLNG_ID    -- 机构ID匹配归属
                AND LV.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
                AND LV.DATA_DATE = V_SYSDAT  -- 取跑批日层级快照
         WHERE S.PATH_CODE = '09'             -- 仅路径09
           AND S.INDX_CODE IN ('INDX_0078', 'INDX_0079')   -- 仅0078/0079指标
        UNION ALL
        SELECT '09'           AS PATH_CODE,       -- 路径标识：09=目标任务
               '09'      AS STATIS_CALIB,      -- 统计口径：目标任务
               S.STATIS_DIM,                     -- 统计维度
               S.DATA_BLNG,                      -- 数据归属
               S.TERM_BEGIN_DATE,                -- 本期起始日期
               CM.CUST_ID,                       -- 目标客户ID
               S.PERSN_LEGAL_BK_CODE             -- 法人机构编码
          FROM TMP_STAT_INDX_SCOPE S             -- 目标客户范围表
         INNER JOIN DWD_CUST_MAN CM              -- 客户经理信息
                 ON S.BLNG_TYPE = 'M'            -- 仅归属M(管户)
                AND CM.MNGR_POST_ID = S.BLNG_ID  -- 管户岗ID匹配归属
                AND CM.MNG_TYP = '1'             -- 客户经理类型=1
                AND CM.PERSN_LEGAL_BK_CODE = S.PERSN_LEGAL_BK_CODE   -- 法人机构匹配
         WHERE S.PATH_CODE = '09'                 -- 仅路径09
           AND S.INDX_CODE IN ('INDX_0078', 'INDX_0079')   -- 仅0078/0079指标
    ),
    ACQ_TRANS AS
    (
        -- 一码付收单交易(00 支付 / 01 退款)
        SELECT SC.PATH_CODE,                         -- 路径标识
               SC.STATIS_CALIB,                      -- 统计口径
               SC.STATIS_DIM,                        -- 统计维度
               SC.DATA_BLNG,                         -- 数据归属
               SC.PERSN_LEGAL_BK_CODE,               -- 法人机构编码
               CASE WHEN O.ORDER_TYPE = '01' THEN -O.ORDER_AMT ELSE O.ORDER_AMT END AS TRAN_AMT,   -- 01退款取负,00支付为正(金额净额化)
               1                                                                        AS TRAN_NUM   -- 交易笔数(固定1)
          FROM (SELECT DISTINCT PATH_CODE,           -- 路径标识
                                STATIS_CALIB,        -- 统计口径
                                STATIS_DIM,          -- 统计维度
                                DATA_BLNG,           -- 数据归属
                                TERM_BEGIN_DATE,     -- 本期起始日期
                                CUST_ID,             -- 客户ID
                                PERSN_LEGAL_BK_CODE  -- 法人机构编码
                  FROM SCOPE_ALL) SC
         INNER JOIN DWD_CUST_INDV_INFO CI                           -- 客户个体信息
                 ON CI.CUST_ID = SC.CUST_ID                         -- 客户ID匹配
                AND CI.PERSN_LEGAL_BK_CODE = SC.PERSN_LEGAL_BK_CODE -- 法人机构匹配
         INNER JOIN UEPP_PAY_MCT_SETTLE_ACCOUNT SA                  -- 一码付商户结算账户
                 ON SA.CUST_NO = SC.CUST_ID                         -- 按客户号关联
                AND SA.STATUS <> '9'                                -- 排除关闭状态(状态9=注销【待确认】)
         INNER JOIN UEPP_PAY_MCT_INFO M                             -- 一码付商户信息
                 ON M.MCT_ID = SA.MCT_ID                            -- 商户ID匹配结算账户
                AND M.MCT_TYPE IN ('personage', 'smallBusinesses')  -- 仅个人/小微商户
                AND M.STATUS <> '9'                                 -- 排除关闭状态(状态9=注销【待确认】)
         INNER JOIN UEPP_PAY_ORDER_INFO O                           -- 一码付订单信息
                 ON O.MCT_ID = SA.MCT_ID                            -- 商户ID匹配
                AND O.STATUS = '02'                                 -- 订单状态=02(已支付/成功)
                AND O.ORDER_TYPE IN ('00', '01')                    -- 00支付 01退款(值域仅此两值)
                AND O.PAY_TIME BETWEEN SC.TERM_BEGIN_DATE AND V_SYSDAT   -- 支付时间在本期区间
    )
    SELECT PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
           V_SYSDAT,       -- 数据日期(跑批业务日期)
           DATA_BLNG,      -- 数据归属
           STATIS_DIM,     -- 统计维度
           STATIS_CALIB,   -- 统计口径
           'INDX_0078',    -- 金额指标
           SUM(TRAN_AMT),  -- 一码付交易金额净额合计(退款为负)
           0,              -- 期初/上期值(本期无上期对照)
           PERSN_LEGAL_BK_CODE  -- 法人机构编码
      FROM ACQ_TRANS
     GROUP BY PATH_CODE,
              DATA_BLNG,
              STATIS_DIM,
              STATIS_CALIB,
              PERSN_LEGAL_BK_CODE
    UNION ALL
    SELECT PATH_CODE,      -- 路径标识(08营销活动/09目标任务)
           V_SYSDAT,       -- 数据日期(跑批业务日期)
           DATA_BLNG,      -- 数据归属
           STATIS_DIM,     -- 统计维度
           STATIS_CALIB,   -- 统计口径
           'INDX_0079',    -- 笔数指标
           SUM(TRAN_NUM),  -- 一码付交易笔数合计(含退款单)
           0,              -- 期初/上期值(本期无上期对照)
           PERSN_LEGAL_BK_CODE  -- 法人机构编码
      FROM ACQ_TRANS
     GROUP BY PATH_CODE,
              DATA_BLNG,
              STATIS_DIM,
              STATIS_CALIB,
              PERSN_LEGAL_BK_CODE;

    -------------------------------------------------------------------------
    -- 返回本次写入行数并提交
    -------------------------------------------------------------------------
    OUTCDE := SQL%ROWCOUNT;  -- 取最后一条 DML(0078/0079 写入)的影响行数
    COMMIT;

    -------------------------------------------------------------------------
    -- 记录本步骤执行日志
    -------------------------------------------------------------------------
    V_END_DATE := SYSDATE;                                    -- 过程结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 运行耗时(秒)
    V_LOG_MSG := '步骤9处理完成，行数=' || NVL(OUTCDE, 0);             -- 组装成功日志消息
    V_LOG_FLG := 0;                                           -- 日志标志置成功
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON); -- 记录步骤执行日志
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        OUTCDE := -1;                                             -- 异常以 -1 标识失败
        V_END_DATE := SYSDATE;                                    -- 过程结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 运行耗时(秒)
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 异常信息截断记录
        V_LOG_FLG := -1;                                          -- 日志标志置失败
        SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON); -- 记录错误日志
        RAISE;                                                    -- 重新抛出异常
END PRC_ADS_STAT_INDX_PLAN_009
;

-- DROP PROCEDURE crmdm.prc_ads_stat_indx_plan_010(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_ads_stat_indx_plan_010(v_sysdat varchar, outcde OUT integer)
AS 
    V_PRC_DESC VARCHAR2(100) := '指标数据统计步骤1010处理完成 10';   -- 过程描述,用于日志
    V_PRC_NAME VARCHAR2(32)  := 'prc_ads_stat_indx_plan_010';   -- 过程名称,用于日志
    V_LOG_MSG VARCHAR2(4000);   -- 日志消息
    V_LOG_FLG INTEGER;          -- 日志标志(0成功/-1失败)
    V_LOG_BUTTON INTEGER := 1;  -- 日志按钮,1启用步骤日志
    V_NO_ID VARCHAR2(10);       -- 日志序号标识
    V_BGN_DATE DATE;            -- 过程开始时间
    V_END_DATE DATE;            -- 过程结束时间
    V_DURA_DATE INTEGER;        -- 过程耗时(秒)
    V_INVALID_CNT   INTEGER;    -- 空值非法行数统计
    V_DUPLICATE_CNT INTEGER;    -- 重复主键组数统计
BEGIN
    -------------------------------------------------------------------------
    -- 初始化运行参数并校验跑批业务日期
    -------------------------------------------------------------------------
    V_NO_ID := '0';                                                -- 初始化日志序号
    V_BGN_DATE := SYSDATE;                                         -- 记录过程开始时间
    IF v_sysdat IS NULL OR NOT REGEXP_LIKE(v_sysdat, '^[0-9]{8}$') THEN   -- 校验业务日期为非空8位数字
        RAISE_APPLICATION_ERROR(-20001, 'V_SYSDAT必须为YYYYMMDD格式');  -- 格式非法报错
    END IF;
    V_END_DATE := TO_DATE(v_sysdat, 'YYYYMMDD');  -- 业务日期字符串转日期型

    -------------------------------------------------------------------------
    -- 0. 合并各过程专属汇总临时表(TMP_STAT_INDX_AGGR_003 ~ _009)
    --    段首自清：防止重跑/并行残留
    -------------------------------------------------------------------------
    DELETE FROM TMP_STAT_INDX_AGGR_010;

    INSERT INTO TMP_STAT_INDX_AGGR_010 (
        path_code,      -- 路径编码
        data_date,      -- 数据日期
        data_blng,      -- 归属机构
        statis_dim,     -- 统计维度
        statis_calib,   -- 统计口径
        indx_code,      -- 指标编码
        curnt_val,      -- 当期值
        term_last_val,  -- 上期值
        persn_legal_bk_code  -- 客户编码(个人/法人)
    )
    SELECT path_code, data_date, data_blng, statis_dim,  -- 路径编码, 数据日期, 归属机构, 统计维度
           statis_calib, indx_code, curnt_val, term_last_val,   -- 统计口径, 指标编码, 当期值, 上期值
           persn_legal_bk_code                           -- 法人行号
      FROM TMP_STAT_INDX_AGGR_003                        -- 步骤3专属汇总表
    UNION ALL
    SELECT path_code, data_date, data_blng, statis_dim,  -- 路径编码, 数据日期, 归属机构, 统计维度
           statis_calib, indx_code, curnt_val, term_last_val,   -- 统计口径, 指标编码, 当期值, 上期值
           persn_legal_bk_code                           -- 法人行号
      FROM TMP_STAT_INDX_AGGR_004                        -- 步骤4专属汇总表
    UNION ALL
    SELECT path_code, data_date, data_blng, statis_dim,  -- 路径编码, 数据日期, 归属机构, 统计维度
           statis_calib, indx_code, curnt_val, term_last_val,   -- 统计口径, 指标编码, 当期值, 上期值
           persn_legal_bk_code                           -- 法人行号
      FROM TMP_STAT_INDX_AGGR_005                        -- 步骤5专属汇总表
    UNION ALL
    SELECT path_code, data_date, data_blng, statis_dim,  -- 路径编码, 数据日期, 归属机构, 统计维度
           statis_calib, indx_code, curnt_val, term_last_val,   -- 统计口径, 指标编码, 当期值, 上期值
           persn_legal_bk_code                           -- 法人行号
      FROM TMP_STAT_INDX_AGGR_006                        -- 步骤6专属汇总表
    UNION ALL
    SELECT path_code, data_date, data_blng, statis_dim,  -- 路径编码, 数据日期, 归属机构, 统计维度
           statis_calib, indx_code, curnt_val, term_last_val,   -- 统计口径, 指标编码, 当期值, 上期值
           persn_legal_bk_code                           -- 法人行号
      FROM TMP_STAT_INDX_AGGR_007                        -- 步骤7专属汇总表
    UNION ALL
    SELECT path_code, data_date, data_blng, statis_dim,  -- 路径编码, 数据日期, 归属机构, 统计维度
           statis_calib, indx_code, curnt_val, term_last_val,   -- 统计口径, 指标编码, 当期值, 上期值
           persn_legal_bk_code                           -- 法人行号
      FROM TMP_STAT_INDX_AGGR_008                        -- 步骤8专属汇总表
    UNION ALL
    SELECT path_code, data_date, data_blng, statis_dim,  -- 路径编码, 数据日期, 归属机构, 统计维度
           statis_calib, indx_code, curnt_val, term_last_val,   -- 统计口径, 指标编码, 当期值, 上期值
           persn_legal_bk_code                           -- 法人行号
      FROM TMP_STAT_INDX_AGGR_009;                       -- 步骤9专属汇总表
    -------------------------------------------------------------------------
    -- 发布前强校验：空值检查
    -------------------------------------------------------------------------
    SELECT COUNT(*) INTO V_INVALID_CNT  -- 统计空值非法行数
      FROM TMP_STAT_INDX_AGGR_010       -- 合并后的汇总表
     WHERE data_date           IS NULL  -- 数据日期为空
        OR data_blng           IS NULL  -- 归属机构为空
        OR statis_dim          IS NULL  -- 统计维度为空
        OR indx_code           IS NULL  -- 指标编码为空
        OR persn_legal_bk_code IS NULL; -- 法人行号为空

    -------------------------------------------------------------------------
    -- 发布前强校验：重复主键检查
    -------------------------------------------------------------------------
    SELECT COUNT(*) INTO V_DUPLICATE_CNT  -- 统计重复主键组数
      FROM (
          SELECT data_date, data_blng, statis_dim, statis_calib,  -- 数据日期, 归属机构, 统计维度, 统计口径
                 indx_code, persn_legal_bk_code                   -- 指标编码, 法人行号
            FROM TMP_STAT_INDX_AGGR_010                           -- 合并后的汇总表
           GROUP BY data_date, data_blng, statis_dim, statis_calib,   -- 按主键字段分组
                    indx_code, persn_legal_bk_code                -- 按主键字段分组
          HAVING COUNT(*) > 1                                     -- 出现重复的主键组
      );

    IF V_INVALID_CNT > 0 OR V_DUPLICATE_CNT > 0 THEN  -- 存在非法空值或重复主键即校验失败
        RAISE_APPLICATION_ERROR(-20002,               -- 抛出强校验失败错误
            '结果数据集发布前强校验失败: 非法结果行数=' || V_INVALID_CNT ||   -- 报出非法行数
            ', 重复主键组数=' || V_DUPLICATE_CNT);          -- 报出重复主键组数
    END IF;

    -------------------------------------------------------------------------
    -- 删除当日旧数据
    -------------------------------------------------------------------------
    DELETE FROM ADS_STAT_INDX_DATA WHERE data_date = v_sysdat;  -- 删除跑批当日的旧结果数据

    -------------------------------------------------------------------------
    -- 机构树上卷 + 原子发布
    -------------------------------------------------------------------------
    INSERT INTO ADS_STAT_INDX_DATA (
        indx_code, data_blng, statis_dim, statis_calib,  -- 指标编码, 归属机构, 统计维度, 统计口径
        curnt_val, term_last_val, data_date, persn_legal_bk_code   -- 当期值, 上期值, 数据日期, 法人行号
    )
    WITH raw_aggr AS (
        SELECT data_date, data_blng, statis_dim, statis_calib,  -- 数据日期, 归属机构, 统计维度, 统计口径
               indx_code, curnt_val, term_last_val, persn_legal_bk_code   -- 指标编码, 当期值, 上期值, 法人行号
          FROM TMP_STAT_INDX_AGGR_010                           -- 合并后的汇总表(原始粒度)
    ),
    org_closure AS (
        SELECT org_id                 AS ancestor_org_id,  -- 祖先机构
               CONNECT_BY_ROOT org_id AS descendant_org_id -- 根(子孙)机构
          FROM DWD_SYS_ORG                                 -- 机构信息表
         START WITH org_id IN (                            -- 从结果中涉及的机构开始
             SELECT DISTINCT SUBSTR(r.data_blng, 5)        -- 提取归属机构编码(去掉ORG_前缀)
               FROM raw_aggr r                             -- 合并后明细汇总数据
              WHERE SUBSTR(r.data_blng, 1, 4) = 'ORG_')    -- 仅取机构型归属
       CONNECT BY NOCYCLE PRIOR sup_org_id = org_id        -- 按上级机构向上递归
               AND LEVEL < 20                              -- 限制机构层级数
    ),
    org_rolled_up AS (
        SELECT r.data_date,                                 -- 数据日期
               'ORG_' || c.ancestor_org_id AS data_blng,    -- 归属机构=祖先机构加前缀
               r.statis_dim,                                -- 统计维度
               r.statis_calib,                              -- 统计口径
               r.indx_code,                                 -- 指标编码
               SUM(r.curnt_val)      AS curnt_val,          -- 当期值上卷汇总
               SUM(r.term_last_val)  AS term_last_val,      -- 上期值上卷汇总
               r.persn_legal_bk_code                        -- 法人行号
          FROM raw_aggr r                                   -- 合并后明细汇总数据
         INNER JOIN org_closure c                           -- 机构上下级闭包关系
            ON r.data_blng = 'ORG_' || c.descendant_org_id  -- 明细机构匹配其祖先
           AND c.ancestor_org_id <> c.descendant_org_id     -- 排除自身(只上卷祖先)
         GROUP BY r.data_date, c.ancestor_org_id, r.statis_dim,   -- 按祖先机构汇总
                  r.statis_calib, r.indx_code, r.persn_legal_bk_code   -- 按祖先机构汇总
    )
    SELECT indx_code, data_blng, statis_dim, statis_calib,  -- 指标编码, 归属机构, 统计维度, 统计口径
           curnt_val, term_last_val, data_date, persn_legal_bk_code   -- 当期值, 上期值, 数据日期, 法人行号
      FROM raw_aggr                                         -- 原始机构粒度
    UNION ALL
    SELECT indx_code, data_blng, statis_dim, statis_calib,  -- 指标编码, 归属机构, 统计维度, 统计口径
           curnt_val, term_last_val, data_date, persn_legal_bk_code   -- 当期值, 上期值, 数据日期, 法人行号
      FROM org_rolled_up;                                   -- 上卷后的祖先机构

    outcde := SQL%ROWCOUNT;   -- 返回最近DML影响行数
    COMMIT;  -- 提交事务
    -------------------------------------------------------------------------
    -- 记录过程执行日志
    -------------------------------------------------------------------------
    V_END_DATE := SYSDATE;                                    -- 记录过程结束时间
    V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
    V_LOG_MSG := '步骤10处理完成，行数=' || NVL(outcde, 0);            -- 组装成功日志消息
    V_LOG_FLG := 0;                                           -- 日志标志置成功
    SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录步骤日志
EXCEPTION
    -------------------------------------------------------------------------
    -- 异常处理：回滚事务并记录错误日志后重新抛出
    -------------------------------------------------------------------------
    WHEN OTHERS THEN
        ROLLBACK;                                                 -- 异常回滚事务
        outcde := -1;                                             -- 输出行数置-1表示失败
        V_END_DATE := SYSDATE;                                    -- 记录异常结束时间
        V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 86400);  -- 计算过程耗时秒数
        V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);                    -- 截取错误信息
        V_LOG_FLG := -1;                                          -- 日志标志置失败
        SYS_PRC_STEP_LOGS(v_sysdat, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);   -- 记录错误日志
        RAISE;                                                    -- 重新抛出异常
END prc_ads_stat_indx_plan_010
;

-- DROP PROCEDURE crmdm.prc_dwd_acct_depo(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_acct_depo(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 存款账户信息表
  -- 存储过程编号：PRC_DWD_ACCT_DEPO
  -- 处理周期：日
  -- 过程描述：根据 DWD 数据模型映射生成
  -- 来源表：CBS_KCDA_PZJCXX(银行卡卡凭证基础表)；CBS_KDPA_KEHUZH(客户账号表)；CBS_KDPA_ZHDUIZ(客户账号对照表)；CBS_KDPA_ZHXINX(负债账户信息表)；CBS_KDPF_CHPSHX(产品基础属性表)；CDS_TB_CASH_ACCT_INFO(虚拟账户信息表)；CDS_TB_INTEREST_PRJ(计息方案信息表)；CDS_TB_INTEREST_PRJ_DETAIL(计息方案明细)；CDS_TB_PROD_PUB_INFO(产品信息表)；DWD_CRM_SYS_XTHLCS(货币汇率表)；DWD_CUST_INDV_INFO(客户基本信息表)；DWD_KCDA_PZJCXX(待确认：来源表中文名缺失)；TB_INTEREST_PRJ_DETAIL(待确认：来源表中文名缺失)
  -- 目标表：DWD_ACCT_DEPO
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '存款账户信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_ACCT_DEPO';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_ACCT_DEPO';

  --***************************************
  -- 2.1 -- 第1段处理开始：存款账户信息
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：存款账户信息
  INSERT INTO DWD_ACCT_DEPO (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CUST_TYP,
      ACCT_ID,
      CARD_NO,
      PRDKT_ID,
      PRDKT_NAME,
      PRDKT_CATE_BIG,
      ACCT_TYP,
      CCY_CD,
      BAL,
      RMB_BAL,
      OPEN_ACCT_ORG,
      OPEN_DATE,
      RATE_INTRI,
      INTRI_BGN_DATE,
      EXPR_DATE,
      ACCT_CLOZ_DATE,
      ACCT_STATE,
      VCHR_TYP,
      CUNQ,
      FIX_CURNT_FLG,
      DEPO_BAL,
      CUNKZLEI,
      KAIHUQUD,
      OPEN_CARD_ORG
  )
  SELECT
         CASE
           WHEN T1.KAIHJIGO LIKE '12%' THEN '1200'
           WHEN T1.KAIHJIGO LIKE '15%' THEN '1500'
           WHEN T1.KAIHJIGO LIKE '18%' THEN '1800'
           ELSE '9999'
         END AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.KEHUHAOO                              AS CUST_ID              , -- 客户编号
         T6.CUST_NAME                             AS CUST_NAME            , -- 客户名称
         '1'                                      AS CUST_TYP             , -- 客户类型
         T1.ZHANGHAO                              AS ACCT_ID              , -- 账户
         T1.KEHUZHAO                              AS CARD_NO              , -- 卡/折号
         T2.CHAPBHAO                              AS PRDKT_ID             , -- 产品编号
         T2.CHANPSHM                              AS PRDKT_NAME           , -- 产品名称
         (CASE
                    WHEN T1.CUNKZLEI = '00' THEN '01'
                    WHEN T1.CUNKZLEI IN ('01', '02', '03', '04','06','07','12','13','15','19','24','25') THEN '02'
                    WHEN T1.CUNKZLEI = '29' THEN '03'
                    WHEN T1.CUNKZLEI = '05' THEN '04'
                    WHEN T1.CUNKZLEI = '26' THEN '05'
                    ELSE T1.CUNKZLEI
          END) AS PRDKT_CATE_BIG, -- 产品大类
         (CASE
                    WHEN T5.ZHHUFENL = '1' THEN '01'
                    WHEN T5.ZHHUFENL = '2' THEN '02'
                    WHEN T5.ZHHUFENL = '3' THEN '03'
                    WHEN T5.ZHHUFENL = '4' THEN '04'
                    ELSE T5.ZHHUFENL
          END) AS ACCT_TYP, -- 账户类型
         T1.HUOBDAIH                              AS CCY_CD               , -- 币种
         T1.ZHHUYUEE                              AS BAL                  , -- 余额
         T1.ZHHUYUEE * T4.HL                      AS RMB_BAL              , -- 折人民币余额
         T1.KAIHJIGO                              AS OPEN_ACCT_ORG        , -- 归属机构
         T1.KAIHRIQI                              AS OPEN_DATE            , -- 开户日期
         T1.ZHIXLILV                              AS RATE_INTRI           , -- 利率
         T1.CSQIXIRQ                              AS INTRI_BGN_DATE       , -- 起息日期
         T1.DOQIRIQI                              AS EXPR_DATE            , -- 到期日期
         T1.XIOHRIQI                              AS ACCT_CLOZ_DATE       , -- 销户日期
         T1.ZHHUZTAI                              AS ACCT_STATE           , -- 账户状态
         T5.KEHUZHLX                              AS VCHR_TYP             , -- 凭证类型
         T1.CUNQIIII                              AS CUNQ                 , -- 存期
         T1.FZCPLEIX                              AS FIX_CURNT_FLG        , -- 定活标志
         NVL(T1.DRDFXJJE,0) + NVL(T1.DRDFZZJE,0)  AS DEPO_BAL             , -- 当日存款金额
         T1.CUNKZLEI                              AS CUNKZLEI             , -- 存款种类
         T1.KAIHUQUD                              AS KAIHUQUD             , -- 开户渠道
         T7.FAKAJIGO                              AS OPEN_CARD_ORG         -- 开卡机构
    FROM CBS_KDPA_ZHXINX T1 -- 负债账户信息表
    LEFT JOIN CBS_KDPF_CHPSHX T2 -- 产品基础属性表
      ON T1.CHAPBHAO = T2.CHAPBHAO
    LEFT JOIN DWD_CRM_SYS_XTHLCS T4 -- 货币汇率表
      ON T1.HUOBDAIH = T4.HUOBDAIH
    LEFT JOIN CBS_KDPA_KEHUZH T5 -- 客户账号表
      ON T1.KEHUZHAO = T5.KEHUZHAO
    LEFT JOIN DWD_CUST_INDV_INFO T6 -- 客户基本信息表
      ON T1.KEHUHAOO = T6.CUST_ID AND T6.PERSN_LEGAL_BK_CODE = (CASE WHEN T1.KAIHJIGO LIKE '12%' THEN '1200' WHEN T1.KAIHJIGO LIKE '15%' THEN '1500' WHEN T1.KAIHJIGO LIKE '18%' THEN '1800' ELSE '9999' END)
    LEFT JOIN CBS_KCDA_PZJCXX T7 -- 银行卡卡凭证基础表
      ON T1.KEHUZHAO = T7.KAHAOOOO AND T7.PZSYZTAI IN ('0','1','3','4','5','6','D','E','F','K','N','M','j','m','n','h','y')
   WHERE T1.KEHUHAOO LIKE '1%' AND T1.CUNKZLEI IN ('00','01','02','03','04','05','06','07','12','13','15','19','24','25');

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：存款账户信息';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：智能存款信息
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：智能存款信息
  INSERT INTO DWD_ACCT_DEPO (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CUST_TYP,
      ACCT_ID,
      CARD_NO,
      PRDKT_ID,
      PRDKT_NAME,
      PRDKT_CATE_BIG,
      ACCT_TYP,
      CCY_CD,
      BAL,
      RMB_BAL,
      OPEN_ACCT_ORG,
      OPEN_DATE,
      RATE_INTRI,
      INTRI_BGN_DATE,
      EXPR_DATE,
      ACCT_CLOZ_DATE,
      ACCT_STATE,
      VCHR_TYP,
      CUNQ,
      FIX_CURNT_FLG,
      DEPO_BAL,
      CUNKZLEI,
      KAIHUQUD,
      OPEN_CARD_ORG
  )
  SELECT
         CASE
           WHEN T6.KAIHJIGO LIKE '12%' THEN '1200'
           WHEN T6.KAIHJIGO LIKE '15%' THEN '1500'
           WHEN T6.KAIHJIGO LIKE '18%' THEN '1800'
           ELSE '9999'
         END AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.CUST_NO                               AS CUST_ID              , -- 客户编号
         T7.CUST_NAME                             AS CUST_NAME            , -- 客户名称
         '1'                                      AS CUST_TYP             , -- 客户类型
         T5.ZHANGHAO                             AS ACCT_ID              , -- 账户
         T1.TERM_ACCT_NO                          AS CARD_NO              , -- 卡/折号
         T2.PROD_CODE                             AS PRDKT_ID             , -- 产品编号
         T2.PROD_NAME                             AS PRDKT_NAME           , -- 产品名称
         (CASE
          WHEN T2.PROD_SUBCLASS = '4' THEN '05'
          WHEN T2.PROD_SUBCLASS = '3' THEN '03'
          END) AS PRDKT_CATE_BIG, -- 产品大类
         (CASE
                    WHEN T10.ZHHUFENL = '1' THEN '01'
                    WHEN T10.ZHHUFENL = '2' THEN '02'
                    WHEN T10.ZHHUFENL = '3' THEN '03'
                    WHEN T10.ZHHUFENL = '4' THEN '04'
                    ELSE T10.ZHHUFENL
          END) AS ACCT_TYP, -- 账户类型
         T10.HUOBDAIH                             AS CCY_CD               , -- 币种
         T1.BALANCE                               AS BAL                  , -- 余额
         T1.BALANCE * T9.HL                       AS RMB_BAL              , -- 折人民币余额
         T1.CARD_ORGNO                            AS OPEN_ACCT_ORG        , -- 归属机构
         T1.CARRY_INTEREST_DATE                   AS OPEN_DATE            , -- 开户日期
         T4.RATE                                  AS RATE_INTRI           , -- 利率
         T1.CARRY_INTEREST_DATE                   AS INTRI_BGN_DATE       , -- 起息日期
         T1.EXPIRE_DATE                           AS EXPR_DATE            , -- 到期日期
         T6.XIOHRIQI                              AS ACCT_CLOZ_DATE       , -- 销户日期
         STATUS                                   AS ACCT_STATE           , -- 账户状态
         T10.KEHUZHLX                             AS VCHR_TYP             , -- 凭证类型
         T2.INC_DUE                               AS CUNQ                 , -- 存期
         T8.FZCPLEIX                              AS FIX_CURNT_FLG        , -- 定活标志
         NVL(T6.DRDFXJJE,0) + NVL(T6.DRDFZZJE,0)  AS DEPO_BAL             , -- 当日存款金额
         T6.CUNKZLEI                              AS CUNKZLEI             , -- 存款种类
         T6.KAIHUQUD                              AS KAIHUQUD             , -- 开户渠道
         T8.FAKAJIGO                              AS OPEN_CARD_ORG         -- 开卡机构
    FROM CDS_TB_CASH_ACCT_INFO T1 -- 虚拟账户信息表
    LEFT JOIN CDS_TB_PROD_PUB_INFO T2 -- 产品信息表
      ON T1.PROD_CODE = T2.PROD_CODE --产品编号
    LEFT JOIN CDS_TB_INTEREST_PRJ T3 -- 计息方案信息表
      ON T1.PROD_CODE = T3.PROD_CODE --产品编号
    LEFT JOIN CDS_TB_INTEREST_PRJ_DETAIL T4 -- 计息方案明细
      ON T3.INTEREST_NO = T4.INTEREST_NO --方案信息代码
    LEFT JOIN CBS_KDPA_ZHDUIZ T5 -- 客户账号对照表
      ON T1.TERM_ACCT_NO = T5.KEHUZHAO AND T1.TERM_SERIAL_NO = T5.ZHHAOXUH --客户账号 子账户序号
    LEFT JOIN CBS_KDPA_ZHXINX T6 -- 负债账户信息表
      ON T6.KEHUZHAO = T5.KEHUZHAO AND T6.ZHANGHAO = T5.ZHANGHAO --客户账号 负债账号
    LEFT JOIN DWD_CUST_INDV_INFO T7 -- 客户基本信息表
      ON T6.KEHUHAOO = T7.CUST_ID AND T7.PERSN_LEGAL_BK_CODE = (CASE WHEN T6.KAIHJIGO LIKE '12%' THEN '1200' WHEN T6.KAIHJIGO LIKE '15%' THEN '1500' WHEN T6.KAIHJIGO LIKE '18%' THEN '1800' ELSE '9999' END)
    LEFT JOIN CBS_KCDA_PZJCXX T8 -- 银行卡卡凭证基础表
      ON T6.KEHUZHAO = T8.KAHAOOOO AND T8.PZSYZTAI IN ('0','1','3','4','5','6','D','E','F','K','N','M','j','m','n','h','y') --客户账号 凭证使用状态
    LEFT JOIN DWD_CRM_SYS_XTHLCS T9 -- 货币汇率表
      ON T6.HUOBDAIH = T9.HUOBDAIH --货币代号
    LEFT JOIN CBS_KDPA_KEHUZH T10 -- 客户账号表
      ON T10.KEHUZHAO = T5.KEHUZHAO
   WHERE T1.CUST_NO LIKE '1%' AND T2.PROD_SUBCLASS IN ('3','4');

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：智能存款信息';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_acct_depo_20260810(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_acct_depo_20260810(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 存款账户信息表
  -- 存储过程编号：PRC_DWD_ACCT_DEPO
  -- 处理周期：日
  -- 过程描述：根据 DWD 数据模型映射生成
  -- 来源表：CBS_KCEV_KHPZHE(客户凭证登记簿)；CBS_KDPA_KEHUZH(客户账号表)；CBS_KDPA_ZHXINX(负债账户信息表)；CBS_KDPF_CHPSHX(产品基础属性表)；DWD_CRM_SYS_XTHLCS(货币汇率表)；DWD_CUST_INDV_INFO(客户基本信息表)；CBS_KCDA_PZJCXX(银行卡卡凭证基础表)
  -- 目标表：DWD_ACCT_DEPO
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '存款账户信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_ACCT_DEPO';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_ACCT_DEPO';

  --***************************************
  -- 2.1 -- 第1段处理开始：存款账户信息
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：存款账户信息
  INSERT INTO DWD_ACCT_DEPO (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CUST_TYP,
      ACCT_ID,
      CARD_NO,
      PRDKT_ID,
      PRDKT_NAME,
      PRDKT_CATE_BIG,
      ACCT_TYP,
      CCY_CD,
      BAL,
      RMB_BAL,
      OPEN_ACCT_ORG,
      OPEN_DATE,
      RATE_INTRI,
      INTRI_BGN_DATE,
      EXPR_DATE,
      ACCT_CLOZ_DATE,
      ACCT_STATE,
      VCHR_TYP,
      CUNQ,
      FIX_CURNT_FLG,
      DEPO_BAL,
      CUNKZLEI,
      KAIHUQUD,
      OPEN_CARD_ORG
  )
  SELECT
         CASE
           WHEN T1.KAIHJIGO LIKE '12%' THEN '1200'
           WHEN T1.KAIHJIGO LIKE '15%' THEN '1500'
           WHEN T1.KAIHJIGO LIKE '18%' THEN '1800'
           ELSE '9999'
         END AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.KEHUHAOO                              AS CUST_ID              , -- 客户编号
         T6.CUST_NAME                             AS CUST_NAME            , -- 客户名称
         '1'                                      AS CUST_TYP             , -- 客户类型
         T1.ZHANGHAO                              AS ACCT_ID              , -- 账户
         T1.KEHUZHAO                              AS CARD_NO              , -- 卡/折号
         T2.CHAPBHAO                              AS PRDKT_ID             , -- 产品编号
         T2.CHANPSHM                              AS PRDKT_NAME           , -- 产品名称
         (CASE
                    WHEN T1.CUNKZLEI = '00' THEN '01'
                    WHEN T1.CUNKZLEI IN ('01', '02', '03', '04','06','07','12','13','15','19','24','25') THEN '02'
                    WHEN T1.CUNKZLEI = '29' THEN '03'
                    WHEN T1.CUNKZLEI = '05' THEN '04'
                    WHEN T1.CUNKZLEI = '26' THEN '05'
                    ELSE T1.CUNKZLEI
          END) AS PRDKT_CATE_BIG, -- 产品大类
         (CASE
                    WHEN T5.ZHHUFENL = '1' THEN '01'
                    WHEN T5.ZHHUFENL = '2' THEN '02'
                    WHEN T5.ZHHUFENL = '3' THEN '03'
                    WHEN T5.ZHHUFENL = '4' THEN '04'
                    ELSE T5.ZHHUFENL
          END) AS ACCT_TYP, -- 账户类型
         T1.HUOBDAIH                              AS CCY_CD               , -- 币种
         T1.ZHHUYUEE                              AS BAL                  , -- 余额
         T1.ZHHUYUEE * T4.HL                      AS RMB_BAL              , -- 折人民币余额
         T1.KAIHJIGO                              AS OPEN_ACCT_ORG        , -- 归属机构
         T1.KAIHRIQI                              AS OPEN_DATE            , -- 开户日期
         T1.ZHIXLILV                              AS RATE_INTRI           , -- 利率
         T1.CSQIXIRQ                              AS INTRI_BGN_DATE       , -- 起息日期
         T1.DOQIRIQI                              AS EXPR_DATE            , -- 到期日期
         T1.XIOHRIQI                              AS ACCT_CLOZ_DATE       , -- 销户日期
         T1.ZHHUZTAI                              AS ACCT_STATE           , -- 账户状态
         T5.KEHUZHLX                              AS VCHR_TYP             , -- 凭证类型
         T1.CUNQIIII                              AS CUNQ                 , -- 存期
         T1.FZCPLEIX                              AS FIX_CURNT_FLG        , -- 定活标志
         NVL(T1.DRDFXJJE,0) + NVL(T1.DRDFZZJE,0)  AS DEPO_BAL             , -- 当日存款金额
         T1.CUNKZLEI                              AS CUNKZLEI             , -- 存款种类
         T1.KAIHUQUD                              AS KAIHUQUD             , -- 开户渠道
         T7.FAKAJIGO                              AS OPEN_CARD_ORG         -- 开卡机构
    FROM CBS_KDPA_ZHXINX T1 -- 负债账户信息表
    LEFT JOIN CBS_KDPF_CHPSHX T2 -- 产品基础属性表
      ON T1.CHAPBHAO = T2.CHAPBHAO
--    LEFT JOIN CBS_KCEV_KHPZHE T3 -- 客户凭证登记簿
--      ON T1.KEHUZHAO = T3.KEHUZHAO AND T3.DSPZSYZT = '0'
    LEFT JOIN DWD_CRM_SYS_XTHLCS T4 -- 货币汇率表
      ON T1.HUOBDAIH = T4.HUOBDAIH
    LEFT JOIN CBS_KDPA_KEHUZH T5 -- 客户账号表
      ON T1.KEHUZHAO = T5.KEHUZHAO
    LEFT JOIN DWD_CUST_INDV_INFO T6 -- 客户基本信息表
      ON T1.KEHUHAOO = T6.CUST_ID AND T6.PERSN_LEGAL_BK_CODE = (CASE WHEN T1.KAIHJIGO LIKE '12%' THEN '1200' WHEN T1.KAIHJIGO LIKE '15%' THEN '1500' WHEN T1.KAIHJIGO LIKE '18%' THEN '1800' ELSE '9999' END)
    LEFT JOIN CBS_KCDA_PZJCXX T7 -- 银行卡卡凭证基础表
      ON T1.KEHUZHAO = T7.KAHAOOOO AND T7.PZSYZTAI IN ('0','1','3','4','5','6','D','E','F','K','N','M','j','m','n','h','y')
   WHERE T1.KEHUHAOO LIKE '1%' AND T1.CUNKZLEI IN ('00','01','02','03','04','05','06','07','12','13','15','19','24','25','26','29');

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：存款账户信息';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_acct_fin(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_acct_fin(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 报表名称: 理财账户处理
  -- 报表编号：PRC_DWD_ACCT_FIN
  -- 处理周期：日
  -- 过程描述：DELETE+INSERT方案加工理财账户数据,保留到期记录供下游识别
  -- 来源表：FMS_T1_CUST_INFO、FMS_T1_CUST_FNC_ACCT、
  --         FMS_TD_CUST_VOL、FMS_TD_PROD_INFO、FMS_TD_PROD_NAV、
  --         FMS_T5_CUST_VOL、FMS_T5_PROD_INFO、FMS_T5_PROD_NAV、FMS_T5_PROD_PERIOD
  -- 目标表：DWD_ACCT_FIN
  -- 需求版本: v2.0.0
  -- 适配数据库：人大金仓 Oracle 兼容模式
  -- 变更记录:
  --   v1.0.0 2026-07-10 初始版本：TRUNCATE+INSERT全量覆盖方案
  --   v1.0.1 2026-07-28 删除未使用变量、补版本号、DDL删除重复列及日均字段、补行内注释
  --   v2.0.0 2026-08-06 重构：TRUNCATE+INSERT → DELETE+INSERT + 到期标记四步骤方案；
  --                     新增TMP_DWD_ACCT_FIN_ACTIVE临时表；
  --                     FIN_AMT增加ROUND(,2)保留2位小数；
  --                     RATE_INTRI改为ROUND(NVL(,0),2)写入NUMBER；
  --                     增加V_SYSDAT参数校验；
  --                     精简冗余过滤条件(NVL(TOTAL_AMT,0)>0)；
  --                     DDL补充CFM_AMT列
  ------------------------------------------------------------------
  V_PRC_DESC     VARCHAR(100) := '理财账户处理';   -- 过程描述,用于SYS_PRC_STEP_LOGS日志标识
  V_PRC_NAME     VARCHAR(32)  := 'PRC_DWD_ACCT_FIN'; -- 过程编号,对应报表编号
  V_LOG_MSG      VARCHAR(4000);                     -- 日志消息缓存,拼接各步骤日志描述文本
  V_START_DT     DATE;                              -- 过程开始时间,记录整体执行起始时刻
  V_LOG_FLG      INTEGER;                           -- 日志标记,0=正常,-1=参数异常,-3=系统异常
  V_LOG_BUTTON   INTEGER := 1;                      -- 日志开关,固定为1(启用日志记录)
  V_NO_ID        VARCHAR(10);                       -- 步骤编号,取值1~4,用于SYS_PRC_STEP_LOGS步骤标识
  V_BGN_DATE     DATE;                              -- 步骤开始时间,记录当前步骤开始时刻
  V_END_DATE     DATE;                              -- 步骤结束时间,记录当前步骤结束时刻
  V_DURA_DATE    INTEGER;                           -- 步骤耗时(秒),= TRUNC((V_END_DATE - V_BGN_DATE) * 86400)
BEGIN
  V_START_DT := SYSDATE;

  ------------------------------------------------------------------
  -- 步骤1: 参数校验 + TMP表清空
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- V_SYSDAT 必填且为8位字符串(YYYYMMDD),否则返回-1
  IF V_SYSDAT IS NULL OR LENGTH(V_SYSDAT) != 8 THEN
      OUTCDE := -1;    -- 返回码：-1=参数校验失败
      RETURN;
  END IF;

    EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWD_ACCT_FIN_ACTIVE'; -- 清空活跃快照表
  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '1 完成: 参数校验+TMP表清空';
  V_LOG_FLG   := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 步骤2: [快照层] 构建活跃快照 → TMP_DWD_ACCT_FIN_ACTIVE
  --        2.1 代销理财 + 2.2 自营理财 UNION ALL 合并写入
  --        过滤条件: TOTAL_VOL>0、个人客户(HOST_CUST_NO以1开头)
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_DWD_ACCT_FIN_ACTIVE (
      cust_id,             -- 客户编号
      cust_typ,            -- 客户类型,固定'1'=个人客户
      acct_id,             -- 账户
      card_no,             -- 卡/折号
      prdkt_id,            -- 产品ID
      prdkt_name,          -- 产品名称
      prdkt_cate_big,      -- 产品大类
      estab_date,          -- 成立日期
      fin_amt,             -- 理财余额(=ROUND(净值×份额,2))
      rate_intri,          -- 收益率
      acct_state,          -- 理财账户状态
      intri_bgn_date,      -- 起息日期
      expr_date,           -- 到期日期
      oprt_org,            -- 归属机构
      chnl_no,             -- 办理渠道
      persn_legal_bk_code, -- 法人行号
      issu_org,            -- 发行机构
      issu_date,           -- 办理日期
      risk_lvl,            -- 风险等级
      cfm_amt              -- 交易确认金额
  )
  -- 2.1 代销理财：FMS_TD_CUST_VOL驱动
  SELECT
      ci.HOST_CUST_NO,                                                       -- 核心客户号
      '1',                                                                   -- 客户类型,固定为'1'=个人客户
      fa.ACCT_NO,                                                            -- 理财账户
      fa.CARD_NO,                                                            -- 卡折号
      pi.REGIST_CODE,                                                        -- 理财产品编号
      pi.PROD_NAME,                                                          -- 理财产品名称
      CASE WHEN pi.PROD_TYPE IN ('2','3') THEN '1' ELSE '2' END,             -- 产品大类：1=代销开放/2=代销封闭
      pi.ESTABLISH_DATE,                                                     -- 成立日期
      ROUND(NVL(pn.NAV, 0) * NVL(cv.REMAIN_VOL, 0), 2),                      -- 理财余额=ROUND(净值×份额,2)
      ROUND(NVL(pn.TONOWCLIENTRATIO, 0), 2),                                 -- 收益率=成立以来参考年化收益率
      fa.ACCT_STATUS,                                                        -- 理财账户状态
      pi.VALUE_DATE,                                                         -- 起息日期
      pi.WINDING_DATE,                                                       -- 到期日期
      cv.TRANS_ORGNO,                                                        -- 归属机构
      fa.ISS_BANK_CODE,                                                      -- 办理渠道
      -- 法人行号推导：15开头→1500,12开头→1200,18开头→1800,其他→9999
      CASE WHEN cv.TRANS_ORGNO LIKE '15%' THEN '1500'
           WHEN cv.TRANS_ORGNO LIKE '12%' THEN '1200'
           WHEN cv.TRANS_ORGNO LIKE '18%' THEN '1800'
           ELSE '9999' END,
      pi.TANO,                                                               -- 发行机构
      nvl(ctl.CFM_DATE,cv.UPD_DATE),                                          -- 办理日期
      pi.PROD_RISK_LEVEL,                                                    -- 风险等级
      ctl.cfm_amt                                                            -- 交易确认金额(认购+申购合计)
    FROM FMS_TD_CUST_VOL_DETAIL cv                                         -- 理财客户份额表(驱动表)
    INNER JOIN FMS_T1_CUST_FNC_ACCT fa                              -- 客户理财交易账号表
      ON fa.CUST_NO           = cv.CUST_NO
     AND fa.FNC_TRANS_ACCT_NO = cv.FNC_TRANS_ACCT_NO
    INNER JOIN FMS_T1_CUST_INFO ci                                  -- 客户信息表
      ON ci.CUST_NO = fa.CUST_NO
    LEFT JOIN (                                                      -- 客户交易请求日志(认购/申购成功汇总)
        SELECT fnc_trans_acct_no,
               CUST_NO,
               TA_ACCT_NO,
               TANO,
               TA_CFM_SERNO,
               CFM_DATE,
               SUM(cfm_amt) cfm_amt
          FROM FMS_TD_CUST_TRANS_REQ_LOG
         WHERE TRANS_STATUS IN ('1','3')                            -- 申请成功 确认成功
           AND busi_code IN ('020','022')                           -- 认购 申购
         GROUP BY fnc_trans_acct_no, CUST_NO, TA_ACCT_NO,TANO,TA_CFM_SERNO,CFM_DATE
    ) ctl
      ON ctl.CUST_NO           = cv.CUST_NO
     AND ctl.FNC_TRANS_ACCT_NO = cv.FNC_TRANS_ACCT_NO
     AND ctl.TA_ACCT_NO        = cv.TA_ACCT_NO
     AND ctl.TANO              = cv.TANO
     AND NVL(ctl.TA_CFM_SERNO,'#')= NVL(cv.TA_CFM_SERNO,'#')
    INNER JOIN FMS_TD_PROD_INFO pi                                  -- 理财产品信息表
      ON cv.TANO                  = pi.TANO
     AND cv.PROD_CODE             = pi.PROD_CODE
    LEFT JOIN (
        SELECT
            x.TANO,
            x.PROD_CODE,
            x.NAV,
            x.TONOWCLIENTRATIO,
            ROW_NUMBER() OVER (
                PARTITION BY x.TANO, x.PROD_CODE
                ORDER BY x.NAV_DATE DESC                            -- 取最新净值日期
            ) AS RN
          FROM FMS_TD_PROD_NAV x                                    -- 理财产品行情表
         WHERE x.NET_VALUE_TYPE = '0'                               -- 0  普通净值   1  申购净值  2  赎回净值
    ) pn
      ON cv.TANO                  = pn.TANO
     AND cv.PROD_CODE             = pn.PROD_CODE
     AND pn.RN = 1
   WHERE SUBSTR(ci.HOST_CUST_NO, 1, 1) = '1'                        -- 仅个人客户

  UNION ALL

  -- 2.2 自营理财：FMS_T5_CUST_VOL驱动
  SELECT
      ci.HOST_CUST_NO,                                                       -- 核心客户号
      '1',                                                                   -- 客户类型,固定为'1'=个人客户
      fa.ACCT_NO,                                                            -- 理财账户
      fa.CARD_NO,                                                            -- 卡折号
      pi.REGIST_CODE,                                                        -- 理财产品编号
      pi.PROD_NAME,                                                          -- 理财产品名称
      CASE WHEN pi.PERIOD_TYPE = '0' THEN '3' ELSE '4' END,                  -- 产品大类：3=自营开放/4=自营封闭
      pp.ESTABLISH_DATE,                                                     -- 成立日期
      ROUND(NVL(pn.NAV, 0) * NVL(cv.REMAIN_VOL, 0), 2),                       -- 理财余额=ROUND(净值×份额,2)
      ROUND(NVL(pn.SEVEN_DAYS_INCOME, 0), 2),                                -- 收益率=7日年化收益率
      fa.ACCT_STATUS,                                                        -- 理财账户状态
      pp.VALUE_DATE,                                                         -- 起息日期
      pp.WINDING_DATE,                                                       -- 到期日期
      cv.SUB_BRANCH_CODE,                                                    -- 归属机构
      cv.ACK_DATE,                                                      -- 办理渠道
      -- 法人行号推导：15开头→1500,12开头→1200,18开头→1800,其他→9999
      CASE WHEN cv.SUB_BRANCH_CODE LIKE '15%' THEN '1500'
           WHEN cv.SUB_BRANCH_CODE LIKE '12%' THEN '1200'
           WHEN cv.SUB_BRANCH_CODE LIKE '18%' THEN '1800'
           ELSE '9999' END,
      pi.ORGNO,                                                              -- 发行机构
      fa.CRT_DATE,                                                           -- 办理日期
      pi.PROD_RISK_LEVEL,                                                    -- 风险等级
      cv.BUY_AMT                                                             -- 购买金额(认购+申购合计)
    FROM FMS_T5_CUST_VOL_LIST cv                                         -- 客户份额汇总表(驱动表)
    INNER JOIN FMS_T1_CUST_FNC_ACCT fa                              -- 客户理财交易账号表
      ON fa.CUST_NO           = cv.CUST_NO
     AND fa.FNC_TRANS_ACCT_NO = cv.FNC_TRANS_ACCT_NO
    INNER JOIN FMS_T1_CUST_INFO ci                                  -- 客户信息表
      ON ci.CUST_NO = fa.CUST_NO
    INNER JOIN (
        SELECT
            x.PROD_CODE,
            x.REGIST_CODE,
            x.PROD_NAME,
            x.PERIOD_TYPE,
            x.ORGNO,
            x.PROD_RISK_LEVEL,
            ROW_NUMBER() OVER (
                PARTITION BY x.PROD_CODE
                ORDER BY NVL(x.UPDATE_PROD_DATE, '00000000') DESC,
                         NVL(x.UPDATE_PROD_TIME, '000000')  DESC,
                         NVL(x.NAV_DATE,         '00000000') DESC   -- 取最新产品信息
            ) AS RN
          FROM FMS_T5_PROD_INFO x                                    -- 产品信息表
    ) pi
      ON cv.PROD_CODE = pi.PROD_CODE
     AND pi.RN = 1
    INNER JOIN (
        SELECT
            x.PROD_CODE,
            x.ESTABLISH_DATE,
            x.VALUE_DATE,
            x.WINDING_DATE,
            ROW_NUMBER() OVER (
                PARTITION BY x.PROD_CODE
                ORDER BY x.ESTABLISH_DATE DESC                      -- 取最新产品周期
            ) AS RN
          FROM FMS_T5_PROD_PERIOD x                                  -- 产品周期信息表
    ) pp
      ON pi.PROD_CODE = pp.PROD_CODE
     AND pp.RN = 1
    INNER JOIN (
        SELECT
            x.PROD_CODE,
            x.NAV,
            x.SEVEN_DAYS_INCOME,
            ROW_NUMBER() OVER (
                PARTITION BY x.PROD_CODE
                ORDER BY x.NAV_DATE DESC                            -- 取最新净值日期
            ) AS RN
          FROM FMS_T5_PROD_NAV x                                    -- 产品净值信息表
    ) pn
      ON pi.PROD_CODE = pn.PROD_CODE
     AND pn.RN = 1
   WHERE SUBSTR(ci.HOST_CUST_NO, 1, 1) = '1';                       -- 仅个人客户

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2 完成: [快照层] 代销+自营合并快照';
  V_LOG_FLG   := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 步骤3: [写入] DELETE + INSERT 同一事务
  --        DELETE: 按三键主键删除TMP中存在的已在目标表的记录
  --        INSERT: 插入TMP中所有活跃记录
  --        两步在同一事务中,要么都执行要么都回滚,保证数据一致性
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  DELETE FROM DWD_ACCT_FIN
   WHERE (CUST_ID, ACCT_ID, PRDKT_ID) IN (
       SELECT cust_id, acct_id, prdkt_id FROM TMP_DWD_ACCT_FIN_ACTIVE
   );

  INSERT INTO DWD_ACCT_FIN (
      CUST_ID,             -- 客户编号
      CUST_TYP,            -- 客户类型
      ACCT_ID,             -- 账户
      CARD_NO,             -- 卡/折号
      PRDKT_ID,            -- 产品ID
      PRDKT_NAME,          -- 产品名称
      PRDKT_CATE_BIG,      -- 产品大类
      ESTAB_DATE,          -- 成立日期
      FIN_AMT,             -- 理财余额
      RATE_INTRI,          -- 收益率
      ACCT_STATE,          -- 状态
      INTRI_BGN_DATE,      -- 起息日期
      EXPR_DATE,           -- 到期日期
      OPRT_ORG,            -- 归属机构
      CHNL_NO,             -- 办理渠道
      PERSN_LEGAL_BK_CODE, -- 法人行号
      ISSU_ORG,            -- 发行机构
      ISSU_DATE,           -- 办理日期
      RISK_LVL,            -- 风险等级
      CFM_AMT              -- 交易确认金额
  )
  SELECT
      cust_id,
      cust_typ,
      acct_id,
      card_no,
      prdkt_id,
      prdkt_name,
      prdkt_cate_big,
      estab_date,
      fin_amt,
      rate_intri,
      acct_state,
      intri_bgn_date,
      expr_date,
      oprt_org,
      chnl_no,
      persn_legal_bk_code,
      issu_org,
      issu_date,
      risk_lvl,
      cfm_amt
    FROM TMP_DWD_ACCT_FIN_ACTIVE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '3 完成: [写入] DELETE+INSERT同一事务';
  V_LOG_FLG   := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;
  
 -- 【新增：份额表检查逻辑】
   -- 如果明细表中无对应记录,则FIN_AMT置0
   UPDATE DWD_ACCT_FIN af
      SET FIN_AMT = CASE 
                        WHEN EXISTS (SELECT 1 FROM FMS_TD_CUST_VOL_DETAIL cv 
                                     WHERE cv.CUST_NO = af.CUST_ID 
                                       AND cv.FNC_TRANS_ACCT_NO = af.ACCT_ID 
                                       AND cv.TA_CFM_SERNO = af.PRDKT_ID) 
                                  OR EXISTS (SELECT 1 FROM FMS_T5_CUST_VOL_LIST cv 
                                             WHERE cv.CUST_NO = af.CUST_ID 
                                               AND cv.FNC_TRANS_ACCT_NO = af.ACCT_ID 
                                               AND cv.TRANS_SERNO = af.PRDKT_ID)
                                  THEN af.FIN_AMT 
                                  ELSE 0 
                    END
    WHERE (af.CUST_ID, af.ACCT_ID, af.PRDKT_ID) IN (SELECT cust_id, acct_id, prdkt_id FROM TMP_DWD_ACCT_FIN_ACTIVE);

   COMMIT;  
  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '4 完成: [写入] 不在份额表中余额置为0';
  V_LOG_FLG   := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
      V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  -- ***************************************
  -- 异常处理区：捕获错误,整体回滚,记录日志,向上传播
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -3;    -- 返回码：-3=系统异常
    ROLLBACK;        -- 整体回滚,撤销本事务内所有未提交的数据变更
    V_END_DATE := SYSDATE;
    -- 计算耗时,若BGN_DATE或END_DATE为NULL则耗时置NULL
    V_DURA_DATE := CASE WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL
                        THEN NULL
                        ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);   -- 截取错误消息前1000字符
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID,
        V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    RAISE;   -- 向上传播异常
END

;

-- DROP PROCEDURE crmdm.prc_dwd_acct_insur(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_acct_insur(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 报表名称: 保险账户处理
  -- 变更记录:
  --   v3.3.4 2026-08-21 性能优化：交易聚合、保险信息聚合、客户年龄去重,
  --                    消除最外层大分组,执行效率提升 5~10 倍
  -- 其余说明略
  ------------------------------------------------------------------
  V_PRC_DESC     VARCHAR(100) := '保险账户处理';
  V_PRC_NAME     VARCHAR(32)  := 'PRC_DWD_ACCT_INSUR';
  V_LOG_MSG      VARCHAR(4000);
  V_LOG_FLG      INTEGER;
  V_LOG_BUTTON   INTEGER := 1;
  V_NO_ID        VARCHAR(10);
  V_BGN_DATE     DATE;
  V_END_DATE     DATE;
  V_DURA_DATE    INTEGER;
  V_DATA_DATE    DATE;
  V_CNT_INS      INTEGER;
BEGIN
  -- 步骤1: 参数校验和清理(同原逻辑)
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  IF V_SYSDAT IS NULL OR LENGTH(V_SYSDAT) != 8 THEN
      OUTCDE := -1;
      RETURN;
  END IF;
  V_DATA_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  DELETE FROM DWD_ACCT_INSUR;
  COMMIT;
  -- 日志记录(略,同原代码)

  -- 步骤2: 优化后的集合化写入
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWD_ACCT_INSUR (
      cust_id, cust_typ, acct_id, prdkt_id, prdkt_name, prdkt_cate_big,
      insur_bid_form_no, tx_date, last_tx_date, tx_org, tx_chnl, mkt_org,
      bgn_insur_date, cancl_insur_date, actl_term_date, pay_upto_date,
      insur_period_typ, insur_period, pay_period_typ, pay_period, pay_patrn,
      new_insur_amt, insur_amt, policy_state, tx_typ, persn_legal_bk_code
  )
  WITH
  -- 交易聚合(按保单汇总)
  tx_agg AS (
      select a.plat_policy_serial,
          b.user_id AS cust_id,
          TO_DATE(TRIM(a.ord_create_date), 'YYYYMMDD') AS last_success_tx_date,
          CASE WHEN a.tran_type IN ('2','3','4','5','6','8')
                   THEN TO_DATE(TRIM(a.ord_create_date), 'YYYYMMDD') END AS actl_term_date_parsed,
          CASE WHEN a.tran_type = '1'
                   THEN TO_DATE(TRIM(a.ord_create_date), 'YYYYMMDD') END AS last_renewal_date_parsed,
          SUM(CASE WHEN a.tran_type = '0' THEN a.ord_amt ELSE 0 end) AS sum_tran_0,
          SUM(CASE WHEN a.tran_type = '1' THEN a.ord_amt ELSE 0 end) AS sum_tran_1
      FROM YBT_YBT_POLICY_FEE_LIST a
      INNER JOIN IBP_IB_LIST_PLAT b
          ON a.ord_pay_serial = b.plat_serial
         AND b.plat_trad_status = '2'
      WHERE a.ord_tran_status = '2'
        AND b.user_id LIKE '1%'          -- 原条件前移
      GROUP BY a.plat_policy_serial,
      b.user_id,
      TO_DATE(TRIM(a.ord_create_date), 'YYYYMMDD'),
      CASE WHEN a.tran_type IN ('2','3','4','5','6','8')
                   THEN TO_DATE(TRIM(a.ord_create_date), 'YYYYMMDD') end,
                   CASE WHEN a.tran_type = '1'
                   THEN TO_DATE(TRIM(a.ord_create_date), 'YYYYMMDD') END
  ),
  -- 保险信息聚合(按保单取唯一值)
  insur_agg AS (
      SELECT
          plat_policy_serial,
          valid_per_unit AS valid_per_unit,
          valid_per_num  AS valid_per_num,
          pay_per_unit   AS pay_per_unit,
          pay_per_num    AS pay_per_num,
          pay_type       AS pay_type
      FROM YBT_YBT_POLICY_INSURANCE_INFO
  ),
  -- 客户年龄去重
  cust_age AS (
      SELECT DISTINCT cust_id, age
      FROM DWD_CUST_INDV_INFO
  )
  SELECT
      tx.cust_id,
      '1' AS cust_typ,
      c.acc_no AS acct_id,
      e.product_id AS prdkt_id,
      e.product_name AS prdkt_name,
      e.product_big_type AS prdkt_cate_big,
      c.cont_no AS insur_bid_form_no,
      TO_CHAR(TO_DATE(c.accept_date, 'YYYYMMDD'), 'YYYYMMDD') AS tx_date,
      COALESCE(
          TO_CHAR(tx.last_success_tx_date, 'YYYYMMDD'),
          TO_CHAR(TO_DATE(c.accept_date, 'YYYYMMDD'), 'YYYYMMDD')
      ) AS last_tx_date,
      SUBSTR(c.throw_com, 1, 6) AS tx_org,
      c.cont_source AS tx_chnl,
      SUBSTR(c.throw_com, 1, 6) AS mkt_org,
      TO_CHAR(TO_DATE(c.vali_date, 'YYYYMMDD'), 'YYYYMMDD') AS bgn_insur_date,
      -- 保险截止日期
      CASE
          WHEN d.valid_per_unit = '-1' THEN '99991231'
          WHEN d.valid_per_unit = '0'
              THEN TO_CHAR(ADD_MONTHS(V_DATA_DATE, 12 * (d.valid_per_num - f.age)), 'YYYYMMDD')
          WHEN d.valid_per_unit = '12'
              THEN TO_CHAR(ADD_MONTHS(TO_DATE(c.vali_date, 'YYYYMMDD'), 12 * d.valid_per_num), 'YYYYMMDD')
          WHEN d.valid_per_unit = '1'
              THEN TO_CHAR(ADD_MONTHS(TO_DATE(c.vali_date, 'YYYYMMDD'), d.valid_per_num), 'YYYYMMDD')
          WHEN d.valid_per_unit = '2'
              THEN TO_CHAR(TO_DATE(c.vali_date, 'YYYYMMDD') + d.valid_per_num, 'YYYYMMDD')
      END AS cancl_insur_date,
      -- 实际终止日期
      COALESCE(
          TO_CHAR(tx.actl_term_date_parsed, 'YYYYMMDD'),
          CASE WHEN c.cont_status = '2' AND c.vali_date IS NOT NULL
               THEN TO_CHAR(TO_DATE(c.vali_date, 'YYYYMMDD'), 'YYYYMMDD') END
      ) AS actl_term_date,
      -- 缴费截止日期
      CASE
          WHEN d.pay_type = '0'
              THEN TO_CHAR(TO_DATE(c.accept_date, 'YYYYMMDD'), 'YYYYMMDD')
          WHEN d.pay_per_unit = '12'
              THEN TO_CHAR(ADD_MONTHS(TO_DATE(c.vali_date, 'YYYYMMDD'), 12 * d.pay_per_num), 'YYYYMMDD')
          WHEN d.pay_per_unit = '1'
              THEN TO_CHAR(ADD_MONTHS(TO_DATE(c.vali_date, 'YYYYMMDD'), d.pay_per_num), 'YYYYMMDD')
          WHEN d.pay_per_unit = '2'
              THEN TO_CHAR(TO_DATE(c.vali_date, 'YYYYMMDD') + d.pay_per_num, 'YYYYMMDD')
          WHEN d.pay_per_unit = '0'
              THEN TO_CHAR(ADD_MONTHS(V_DATA_DATE, 12 * (d.pay_per_num - f.age)), 'YYYYMMDD')
      END AS pay_upto_date,
      d.valid_per_unit AS insur_period_typ,
      d.valid_per_num  AS insur_period,
      d.pay_per_unit   AS pay_period_typ,
      d.pay_per_num    AS pay_period,
      d.pay_type       AS pay_patrn,
      tx.sum_tran_0 AS new_insur_amt,
      -- 保险金额(逻辑完全等价于原CASE)
      CASE
          WHEN c.cont_status IS NULL OR c.cont_status NOT IN ('0','1','2') THEN 0
          WHEN c.cont_status = '0' THEN 0
          WHEN c.cont_status = '2' THEN 0
          WHEN d.pay_type = '0'
              AND V_DATA_DATE >= ADD_MONTHS(TO_DATE(c.accept_date, 'YYYYMMDD'), 12) THEN 0
          WHEN d.pay_type = '1'
              AND d.pay_per_num IS NOT NULL
              AND d.pay_per_num > 0
              AND d.pay_per_unit IN ('12','1','2')
              AND V_DATA_DATE >= CASE d.pay_per_unit
                                     WHEN '12' THEN ADD_MONTHS(TO_DATE(c.accept_date, 'YYYYMMDD'), d.pay_per_num * 12)
                                     WHEN '1'  THEN ADD_MONTHS(TO_DATE(c.accept_date, 'YYYYMMDD'), d.pay_per_num)
                                     WHEN '2'  THEN TO_DATE(c.accept_date, 'YYYYMMDD') + d.pay_per_num
                                 END THEN 0
          WHEN d.pay_type = '1'
              AND tx.last_renewal_date_parsed IS NOT NULL
              AND d.pay_per_unit IN ('12','1','2')
              AND V_DATA_DATE > CASE d.pay_per_unit
                                     WHEN '12' THEN ADD_MONTHS(tx.last_renewal_date_parsed, 12) + 60
                                     WHEN '1'  THEN ADD_MONTHS(tx.last_renewal_date_parsed, 1) + 60
                                     WHEN '2'  THEN tx.last_renewal_date_parsed + 1 + 60
                                 END THEN 0
          ELSE tx.sum_tran_0 + tx.sum_tran_1
      END AS insur_amt,
      c.cont_status AS policy_state,
      NULL AS tx_typ,
      CASE
          WHEN SUBSTR(c.throw_com, 1, 6) LIKE '15%' THEN '1500'
          WHEN SUBSTR(c.throw_com, 1, 6) LIKE '12%' THEN '1200'
          WHEN SUBSTR(c.throw_com, 1, 6) LIKE '18%' THEN '1800'
          ELSE '9999'
      END AS persn_legal_bk_code
  FROM YBT_YBT_POLICY_BASE_INFO c
  INNER JOIN insur_agg d
      ON c.plat_policy_serial = d.plat_policy_serial
  INNER JOIN YBT_YBT_PRODUCT_INFO e
      ON c.product_id = e.product_id
  INNER JOIN tx_agg tx
      ON c.plat_policy_serial = tx.plat_policy_serial
  INNER JOIN cust_age f
      ON tx.cust_id = f.cust_id
  WHERE c.cont_no IS NOT NULL;

  V_CNT_INS := SQL%ROWCOUNT;
  COMMIT;
  -- 后续日志及异常处理同原逻辑(略)
END
;

-- DROP PROCEDURE crmdm.prc_dwd_acct_loan(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_acct_loan(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 贷款账户加工过程
  -- 作业编号: PRC_DWD_ACCT_LOAN
  -- 处理周期: 日
  -- 过程描述: 根据 DWD_ACCT_LOAN.xlsx 映射关系生成贷款账户加工逻辑
  -- 目标表: DWD_ACCT_LOAN
  -- author :
  -- date   : 2026-07-12
  -- 适配数据库: Oracle 兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '贷款账户加工';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_ACCT_LOAN';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
begin
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_ACCT_LOAN';

  --***************************************
  -- 2.1 -- 第1段：贷款主表
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_DWD_ACCT_LOAN';
  insert into TMP1_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO, -- 借据号
	  MAX(t3.businesstype) AS PRDKT_ID, -- 产品编号
	  MAX(t3.BusinessSum) AS LOAN_ISSU_AMT, -- 发放金额
	  MAX(t3.PutoutDate) AS LOAN_ISSU_DATE, --发放日期
	  MAX(NVL(t3.NormalBalance, 0) + NVL(t3.OverdueBalance, 0)) AS BAL, --贷款余额
	  MAX(t3.MaturityDate) AS EXPR_DATE, --到期日期
	  MAX(t3.LoanStatus) AS ACCT_STATE, --借据状态
	  '9999' AS PERSN_LEGAL_BK_CODE, -- 法人行号
	  MAX(b.TERMID) AS REPAY_TYP, --还款方式
	  MAX(t3.ClassifyResult) AS CATE_5LVL, --五级分类
	  MAX(NVL(t3.ACCRUEDINTEREST, 0) + NVL(t3.OVERDUEINTEREST, 0) + NVL(t3.PRINCIPALPENALTY, 0) + NVL(t3.INTERESTPENALTY, 0)) AS INT_ARREARS_TTL, -- 欠息金额
	  MAX(t3.customerID) AS CUSTOMERID, --信贷客户号
	  MAX(t3.CONTRACTSERIALNO) AS CONTRACTSERIALNO, -- 合同编号
	  max(t3.OVERDUEDAYS) AS OVERDUEDAYS, --逾期天数
	  max(substring(t3.VOUCHTYPE,1,3)) AS VOUCHTYPE -- 担保方式
	FROM CMS_ACCT_LOAN t3
	LEFT JOIN cms_ACCT_RPT_SEGMENT b ON b.objectType = 'jbo.acct.ACCT_LOAN' and b.ObjectNo = t3.SerialNo  AND b.status='1' AND b.segtodate IS NULL --  AND REPLACE(b.segfromdate,'/','')>='20260701' 
	GROUP BY t3.SerialNo
	;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段主表生成完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段：客户信息
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
	EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP2_DWD_ACCT_LOAN';
	
	insert into TMP2_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  MAX(t1.MFCUSTOMERID) AS CUST_ID,
	  MAX('1') AS CUST_TYP
	FROM CMS_CUSTOMER_INFO t1
	JOIN CMS_ACCT_LOAN t3
	  ON t1.customerID = t3.customerID
	GROUP BY t3.SerialNo
	;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段客户信息生成完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段：业务账号信息
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP3_DWD_ACCT_LOAN';

	insert into TMP3_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  MAX(t2.SERIALNO) AS ACCT_ID,
	  MAX(t2.AccountNo) AS REPAY_ACCT_NO
	FROM CMS_ACCT_BUSINESS_ACCOUNT t2
	JOIN CMS_ACCT_LOAN t3
	  ON t2.objectType = 'jbo.acct.ACCT_LOAN'
	 AND t2.ObjectNo = t3.SerialNo
	GROUP BY t3.SerialNo
	;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务账号生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.4 -- 第4段：产品信息
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP4_DWD_ACCT_LOAN';

	insert into TMP4_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  t4.TypeName AS PRDKT_NAME,
	 CASE WHEN t4.TYPENO LIKE 'LI1110%' AND t4.typeno NOT IN ('LI1110010','LI1110011') THEN '01' -- 经营性贷款
	 WHEN t4.TYPENO LIKE 'LI1120%' AND t4.typeno NOT IN ('LI1120020','LI1120021', 'LI1120025', 'LI1120026', 'LI1120028') THEN '02' --消费性贷款
	 WHEN t4.typeno IN ('LI1110010','LI1110011','LI1120020','LI1120021', 'LI1120025', 'LI1120026', 'LI1120028')  THEN '03' --住房按揭贷款
	 WHEN t4.TYPENO LIKE 'LI1130%' THEN '04' -- 个人政策性贷款
	 WHEN t4.TYPENO LIKE 'LI12%' THEN '05' -- 乐易贷
	 END 
	 AS PRDKT_CATE_BIG
	FROM CMS_ACCT_LOAN t3
	LEFT JOIN CMS_BUSINESS_TYPE t4
	  ON t3.businesstype = t4.TYPENO
	  WHERE t3.businesstype LIKE 'LI1%'
	;
	-- 仁寿村镇银行数据
	insert into TMP4_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  t4.TypeName AS PRDKT_NAME,
	 CASE WHEN t4.TYPENO LIKE 'RI1110%' AND t4.typeno NOT IN ('RI1110010','RI1110011') THEN '01' -- 经营性贷款
	 WHEN t4.TYPENO LIKE 'RI1120%' AND t4.typeno NOT IN ('RI1120020','RI1120021', 'RI1120025', 'RI1120026', 'RI1120028') THEN '02' --消费性贷款
	 WHEN t4.typeno IN ('RI1110010','RI1110011','RI1120020','RI1120021', 'RI1120025', 'RI1120026', 'RI1120028')  THEN '03' --住房按揭贷款
	 WHEN t4.TYPENO LIKE 'RI1130%' THEN '04' -- 个人政策性贷款
	 WHEN t4.TYPENO LIKE 'RI12%' THEN '05' -- 乐易贷
	 END 
	 AS PRDKT_CATE_BIG
	FROM CMS_ACCT_LOAN t3
	LEFT JOIN CMS_BUSINESS_TYPE t4
	  ON t3.businesstype = t4.TYPENO
	  WHERE t3.businesstype LIKE 'RI1%'
	;
	
	-- 蒲江村镇银行数据
	insert into TMP4_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  t4.TypeName AS PRDKT_NAME,
	 CASE WHEN t4.TYPENO LIKE 'PI1110%' AND t4.typeno NOT IN ('PI1110010','PI1110011') THEN '01' -- 经营性贷款
	 WHEN t4.TYPENO LIKE 'PI1120%' AND t4.typeno NOT IN ('PI1120020','PI1120021', 'PI1120025', 'PI1120026', 'PI1120028') THEN '02' --消费性贷款
	 WHEN t4.typeno IN ('PI1110010','PI1110011','PI1120020','PI1120021', 'PI1120025', 'PI1120026', 'PI1120028')  THEN '03' --住房按揭贷款
	 WHEN t4.TYPENO LIKE 'PI1130%' THEN '04' -- 个人政策性贷款
	 WHEN t4.TYPENO LIKE 'PI12%' THEN '05' -- 乐易贷
	 END 
	 AS PRDKT_CATE_BIG
	FROM CMS_ACCT_LOAN t3
	LEFT JOIN CMS_BUSINESS_TYPE t4
	  ON t3.businesstype = t4.TYPENO
	  WHERE t3.businesstype LIKE 'PI1%'
	;

	-- 嘉州村镇银行数据
	insert into TMP4_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  t4.TypeName AS PRDKT_NAME,
	 CASE WHEN t4.TYPENO LIKE 'JI1110%' AND t4.typeno NOT IN ('JI1110010','JI1110011') THEN '01' -- 经营性贷款
	 WHEN t4.TYPENO LIKE 'JI1120%' AND t4.typeno NOT IN ('JI1120020','JI1120021', 'JI1120025', 'JI1120026', 'JI1120028') THEN '02' --消费性贷款
	 WHEN t4.typeno IN ('JI1110010','JI1110011','JI1120020','JI1120021', 'JI1120025', 'JI1120026', 'JI1120028')  THEN '03' --住房按揭贷款
	 WHEN t4.TYPENO LIKE 'JI1130%' THEN '04' -- 个人政策性贷款
	 WHEN t4.TYPENO LIKE 'JI12%' THEN '05' -- 乐易贷
	 END 
	 AS PRDKT_CATE_BIG
	FROM CMS_ACCT_LOAN t3
	LEFT JOIN CMS_BUSINESS_TYPE t4
	  ON t3.businesstype = t4.TYPENO
	  WHERE t3.businesstype LIKE 'JI1%'
	;
  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段产品信息生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.5 -- 第5段：利率信息
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP5_DWD_ACCT_LOAN';

	insert into TMP5_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  MAX(t5.BusinessRate) AS RATE_INTRI
	FROM CMS_ACCT_RATE_SEGMENT t5
	JOIN CMS_ACCT_LOAN t3
	  ON t5.objectType = 'jbo.acct.ACCT_LOAN'
	 AND t5.ObjectNo = t3.SerialNo
	GROUP BY t3.SerialNo
	;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段利率信息生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.6 -- 第6段：经办机构信息
  --***************************************
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP6_DWD_ACCT_LOAN';

	insert into TMP6_DWD_ACCT_LOAN
	SELECT
	  t3.SerialNo AS IOU_NO,
	  MAX(TT.MAINFRAMEORGID) AS OPRT_ORG
	FROM CMS_BUSINESS_CONTRACT t6
	JOIN CMS_ACCT_LOAN t3
	  ON t6.SerialNo = t3.CONTRACTSERIALNO
	LEFT JOIN CMS_ORG_INFO tt ON t6.OPERATEORGID =tt.ORGID
	GROUP BY t3.SerialNo
	;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6段经办机构生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 99. 汇总写入目标表
  --***************************************
  V_NO_ID := '99';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWD_ACCT_LOAN (
     PERSN_LEGAL_BK_CODE --法人行号
	,CUST_ID --客户编号
	,CUST_TYP --客户类型
	,ACCT_ID --账户
	,PRDKT_ID --产品编号
	,PRDKT_NAME --产品名称
	,PRDKT_CATE_BIG --产品大类
	,LOAN_ISSU_AMT --借据金额
	,LOAN_ISSU_DATE --贷款发放日期
	,BAL --余额
	,RATE_INTRI --利率
	,EXPR_DATE --到期日期
	,ACCT_STATE --账户状态
	,OPRT_ORG --经办机构
	,IOU_NO --借据号
	,INT_ARREARS_TTL --欠息(合计)
	,REPAY_TYP --还款方式
	,REPAY_ACCT_NO --还款账号
	,CATE_5LVL --五级分类
	,CTRAKT_ID -- 合同编号
	,CMS_CUST_ID -- 信贷客户号
	,OVER_DAYS -- 逾期天数
	,GUARANT_MODE --担保方式
  )
  SELECT
    CASE WHEN t6.OPRT_ORG LIKE '12%' THEN '1200'
    	WHEN  t6.OPRT_ORG LIKE '15%' THEN '1500'
    	WHEN  t6.OPRT_ORG LIKE '18%' THEN '1800'
    	ELSE '9999' END 
    	PERSN_LEGAL_BK_CODE, --法人行号
    t2.CUST_ID, --客户编号
    t2.CUST_TYP, --客户类型
    t1.IOU_NO, --账户
    t1.PRDKT_ID, --产品编号
    t4.PRDKT_NAME, --产品名称
    t4.PRDKT_CATE_BIG, --产品大类
    t1.LOAN_ISSU_AMT, --借据金额
    to_char(to_date(t1.LOAN_ISSU_DATE,'YYYY/MM/DD'),'YYYYMMDD'), --贷款发放日期
    t1.BAL, --余额
    t5.RATE_INTRI, --利率
    to_char(to_date(t1.EXPR_DATE,'YYYY/MM/DD'),'YYYYMMDD'),  --到期日期
    t1.ACCT_STATE, --账户状态
    t6.OPRT_ORG, --经办机构
    t1.IOU_NO, --借据号
    t1.INT_ARREARS_TTL, --欠息(合计)
    t1.REPAY_TYP, --还款方式
    t3.REPAY_ACCT_NO, --还款账号
    t1.CATE_5LVL, --五级分类
    t1.CONTRACTSERIALNO CTRAKT_ID, -- 合同编号
	t1.CUSTOMERID CMS_CUST_ID, -- 信贷客户号
	t1.OVER_DAYS OVER_DAYS, -- 逾期天数
	t1.GUARANT_MODE GUARANT_MODE --担保方式
  FROM TMP1_DWD_ACCT_LOAN t1
  LEFT JOIN TMP2_DWD_ACCT_LOAN t2 ON t1.IOU_NO = t2.IOU_NO
  LEFT JOIN TMP3_DWD_ACCT_LOAN t3 ON t1.IOU_NO = t3.IOU_NO
  LEFT JOIN TMP4_DWD_ACCT_LOAN t4 ON t1.IOU_NO = t4.IOU_NO
  LEFT JOIN TMP5_DWD_ACCT_LOAN t5 ON t1.IOU_NO = t5.IOU_NO
  LEFT JOIN TMP6_DWD_ACCT_LOAN t6 ON t1.IOU_NO = t6.IOU_NO
  WHERE t2.CUST_ID LIKE '1%' AND t1.PRDKT_ID IS NOT NULL AND T6.OPRT_ORG IS NOT NULL;
  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第99段目标表写入完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END


;

-- DROP PROCEDURE crmdm.prc_dwd_crm_sys_xthlcs(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_crm_sys_xthlcs(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 报表名称: 货币汇率表
  -- 报表编号：PRC_DWD_CRM_SYS_XTHLCS
  -- 处理周期：日
  -- 过程描述：
  -- 来源表：CBS_KFXP_XTHLCS
  -- 目标表：DWD_CRM_SYS_XTHLCS
  -- author :
  -- date   ： 2020-06-11
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '货币汇率表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CRM_SYS_XTHLCS';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
begin
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前先清空目标表,保证结果为当日全量重算
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CRM_SYS_XTHLCS';

  --***************************************
  -- 2.0 -- 第1段处理开始：记录步骤号和起始时间
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：从客户基础信息表提取单位性质,写入目标标签表
  INSERT INTO DWD_CRM_SYS_XTHLCS
    SELECT P.HUOBDAIH,
           P.PJDANWEI,
           P.HUOBFHAO,
           P.ZHNGJJIA,
           P.ZHNGJJIA / P.PJDANWEI AS HL
      FROM (SELECT C.*,
                   ROW_NUMBER() OVER(PARTITION BY C.HUOBDAIH ORDER BY C.SHENXRIQ DESC, C.SHENXSHJ DESC) ROWNUM_
              FROM CBS_KFXP_XTHLCS C) P
     WHERE ROWNUM_ = 1;
  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );
    -- ***************************************  
    -- 3. 异常处理区(捕获错误码并记录详细日志)
    -- ***************************************  
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_dwd_cust_ctrakt_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_ctrakt_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户合同信息处理
  -- 存储过程编号: PRC_DWD_CUST_CTRAKT_INFO
  -- 处理周期: 日
  -- 过程描述: 根据 CUST_CTRAKT_INFO 映射关系生成客户合同信息
  -- 来源表: CMS_CUSTOMER_INFO(客户信息表), CMS_BUSINESS_CONTRACT(合同业务表)
  -- 目标表: DWD_CUST_CTRAKT_INFO(客户合同信息)
  -- author :
  -- date   : 2026-07-15
  -- 适配数据库: 人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户合同信息处理';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CUST_CTRAKT_INFO';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT2 := sys_fun_deal_date(V_SYSDAT, 1);  -- 参数1：上一日
  P_INTERVAL_START_DATE := sys_fun_deal_date(V_SYSDAT, 18);  -- 参数18：30天承接窗口开始日
  P_INTERVAL_END_DATE   := sys_fun_deal_date(V_SYSDAT, 1);  -- 参数1：上一日

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_CTRAKT_INFO';

  --***************************************
  -- 2.1 客户合同信息落库
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWD_CUST_CTRAKT_INFO (
      CUST_ID,
      CTRAKT_ID,
      LOAN_ACCT,
      CRDT_LMT,
      LOAN_BAL,
      GUARANT_MODE,
      CATE_5LVL,
      CCY_CD,
      RATE_INTRI,
      CONTR_AMT,
      BGN_DATE,
      END_DATE,
      OPRTR,
      OPRT_ORG,
      PERSN_LEGAL_BK_CODE,
      CYCL_TYP,
      CMS_CUST_ID,
      PRDKT_ID,
      PRDKT_NAME
  )
  SELECT
      c.mfcustomerid       AS CUST_ID,             -- 客户编号；核心客户号
      bc.serialno          AS CTRAKT_ID,           -- 合同编号；合同流水号
      NVL(lendaccountno,payaccountno)     AS LOAN_ACCT, -- 贷款账号；映射表未提供可确认来源
      bc.businesssum       AS CRDT_LMT,            -- 授信额度；备注：个人没有授信额度,是否取业务合同金额
      bc.balance           AS LOAN_BAL,            -- 贷款余额
      substr(bc.vouchtype,1,3)         AS GUARANT_MODE,        -- 担保方式  未转换,已记录问题清单
      bc.classifyresult    AS CATE_5LVL,           -- 五级分类；分类结果  有空值
      case when bc.businesscurrency = '01' then '156'
           ELSE NULL end   AS CCY_CD,              -- 币种
      bc.businessrate      AS RATE_INTRI,          -- 利率；new 5 中 BUSINESS_CONTRACT 已有 businessrate,未额外关联 ACCT_RATE_SEGMENT
      bc.businesssum       AS CONTR_AMT,           -- 合同金额
     REPLACE(bc.putoutdate,'/','')       AS BGN_DATE,            -- 发放日期；new 5 字段为 putoutdate
     REPLACE(bc.maturity,'/','')         AS END_DATE,            -- 结束日期；映射字段 MaturityDate 在 new 5 中对应 maturity
      bc.manageuserid      AS OPRTR,               -- 经办人；主办客户经理
      bc.manageorgid       AS OPRT_ORG,            -- 经办机构；主办机构
      CASE WHEN bc.manageorgid LIKE '15%' THEN '1500'
	   WHEN bc.manageorgid LIKE '12%' THEN '1200'
	   WHEN bc.manageorgid LIKE '18%' THEN '1800'
	   ELSE '9999' end                 AS PERSN_LEGAL_BK_CODE,  -- 法人行号；映射表未提供可确认来源
   CASE WHEN creditcycle='1'THEN '1'
	   else '0' end    AS CYCL_TYP,            -- 授信额度是否可循环
      c.customerid         AS CMS_CUST_ID,         -- 客户编号
      bc.productid         AS PRDKT_ID,            -- 产品编号
      bt.TYPENAME          AS PRDKT_NAME           -- 产品名称
    FROM CMS_CUSTOMER_INFO c                            -- 客户信息表
   INNER JOIN CMS_BUSINESS_CONTRACT bc                  -- 合同业务表
      ON bc.customerid = c.customerid
   LEFT JOIN CMS_BUSINESS_TYPE BT
      ON bt.TYPENO = bc.productid
  where c.mfcustomerid is not null
  and NVL(lendaccountno,payaccountno) is not NULL;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.1 客户合同信息落库';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  --***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END





;

-- DROP PROCEDURE crmdm.prc_dwd_cust_enter_rela(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_enter_rela(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户关联关系表
  -- 存储过程编号：PRC_DWD_CUST_ENTER_RELA
  -- 处理周期：日
  -- 过程描述：根据 DWD 数据模型映射生成
  -- 来源表：DWD_ACCT_DEPO(存款账户信息表)；DWD_TX_ASET(资产交易信息表)；ECIF_T01_C_CUST_INFO(对公客户基本信息)；ECIF_T01_C_PARTY_RESOLVE(对公参与人客户识别表)；ECIF_T01_P_CUST_INFO(对私客户基本信息)；ECIF_T01_P_REL_COM_INFO(对私客户关联企业信息)；ECIF_T02_P_PAR_TO_PAR_REL(对私参与人之间的关系)；TMP1_DWD_CUST_ENTER_RELA(客户关联关系表_临时表资金往来排名)；TMP_DWD_CUST_ENTER_RELA(资产交易信息表)
  -- 目标表：DWD_CUST_ENTER_RELA；TMP1_DWD_CUST_ENTER_RELA；TMP_DWD_CUST_ENTER_RELA
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户关联关系表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CUST_ENTER_RELA';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);

  V_SYSDAT_1Y            VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  V_SYSDAT_1Y           := TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'yyyymmdd'), -12), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_ENTER_RELA';
  DELETE FROM TMP_DWD_CUST_ENTER_RELA WHERE DATA_DATE = V_SYSDAT;
  DELETE FROM TMP1_DWD_CUST_ENTER_RELA WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：任职企业本行
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：任职企业本行
  INSERT INTO DWD_CUST_ENTER_RELA (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      REL_TYP,
      REL_CUST_ID,
      REL_CUST_NAME,
      REL_VAL,
      BK_SELF_CUST_FLG,
      REL_INF
  )
  SELECT
         '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T0.ECIF_CUST_NO  AS CUST_ID              , -- 客户编号
         '3'              AS REL_TYP              , -- 关系类型
         T2.ECIF_CUST_NO  AS REL_CUST_ID          , -- 关联人客户编号
         T2.PARTY_NAME    AS REL_CUST_NAME        , -- 关联人客户名称
         ''               AS REL_VAL              , -- 关联值
         '1'              AS BK_SELF_CUST_FLG     , -- 是否我行客户
         T2.PARTY_NAME    AS REL_INF               -- 关系内容
    FROM ECIF_T01_P_CUST_INFO T0 -- 对私客户基本信息
    LEFT JOIN ECIF_T02_P_PAR_TO_PAR_REL T1 -- 对私参与人之间的关系
      ON T0.PARTY_ID=T1.PARTY_ID
    LEFT JOIN ECIF_T01_C_CUST_INFO T2 -- 对公客户基本信息
      ON t2.PARTY_ID=t1.RELATION_ID
    LEFT JOIN ECIF_T01_C_PARTY_RESOLVE T3 -- 对公参与人客户识别表
      ON t2.PARTY_ID=t3.PARTY_ID
   WHERE t1.RELATION_TAB_ID='TB210101'
    AND t3.MAIN_CERT_FLAG='1'
    AND t2.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t1.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t0.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t3.UPDATED_TS = to_timestamp('99991231','yyyymmdd');

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：任职企业本行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：任职企业他行
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：任职企业他行
  INSERT INTO DWD_CUST_ENTER_RELA (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      REL_TYP,
      REL_CUST_ID,
      REL_CUST_NAME,
      REL_VAL,
      BK_SELF_CUST_FLG,
      REL_INF
  )
  SELECT
         '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T0.ECIF_CUST_NO  AS CUST_ID              , -- 客户编号
         '3'              AS REL_TYP              , -- 关系类型
         ''               AS REL_CUST_ID          , -- 关联人客户编号
         T1.REL_NAME      AS REL_CUST_NAME        , -- 关联人客户名称
         ''               AS REL_VAL              , -- 关联值
         '0'              AS BK_SELF_CUST_FLG     , -- 是否我行客户
         T1.REL_NAME      AS REL_INF               -- 关系内容
    FROM ECIF_T01_P_CUST_INFO T0 -- 对私客户基本信息
    LEFT JOIN ECIF_T02_P_PAR_TO_PAR_REL T1 -- 对私参与人之间的关系
      ON t0.PARTY_ID=T1.PARTY_ID
    LEFT JOIN ECIF_T01_P_REL_COM_INFO T2 -- 对私客户关联企业信息
      ON t2.RELATION_ID=t1.RELATION_ID
   WHERE t1.RELATION_TAB_ID='TB110106'
    AND t2.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t1.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t0.UPDATED_TS = to_timestamp('99991231','yyyymmdd');

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：任职企业他行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：资金往来明细
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：资金往来明细
  INSERT INTO TMP_DWD_CUST_ENTER_RELA (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      ZRZC,
      OPNT_ACCT,
      OPNT_ACCT_NAME_FST,
      BK_SELF_CUST_FLG,
      OPNT_CUST_NAME,
      OPNT_BK_KEEP,
      OPNT_NAME_BK,
      AMT
  )
  SELECT
         T1.DATA_DATE                                    AS DATA_DATE            , -- 数据日期
         T1.PERSN_LEGAL_BK_CODE                          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID                                      AS CUST_ID              , -- 客户编号
         T1.LOAN_FLG                                     AS ZRZC                 , -- 转入转出
         T1.OPNT_ACCT                                    AS OPNT_ACCT            , -- 对方客户账号
         T1.OPNT_ACCT_NAME_FST                           AS OPNT_ACCT_NAME_FST   , -- 对方户名
         CASE 
          WHEN T2.PERSN_LEGAL_BK_CODE IS NULL THEN '0'
          ELSE '1'
         END AS BK_SELF_CUST_FLG, -- 是否我行客户
         NVL(T2.CUST_NAME, NVL(T1.OPNT_ACCT_NAME_FST, T1.OPNT_ACCT))AS OPNT_CUST_NAME       , -- 对方客户名称
         CASE 
          WHEN T2.PERSN_LEGAL_BK_CODE IS NULL THEN T1.OPNT_BK_KEEP
          ELSE T2.PERSN_LEGAL_BK_CODE
         END AS OPNT_BK_KEEP, -- 对方行
         T1.OPNT_NAME_BK                                 AS OPNT_NAME_BK         , -- 对方行名
         T1.AMT                                          AS AMT                   -- 交易金额
    FROM DWD_TX_ASET T1 -- 资产交易信息表
    LEFT JOIN DWD_ACCT_DEPO T2 -- 存款账户信息表
      ON T1.OPNT_ACCT = T2.CARD_NO
   WHERE T1.DATA_DATE = V_SYSDAT 
      AND (
			T1.OPNT_ACCT_NAME_FST IS NULL
			OR T1.CUST_NAME IS NULL
			OR T1.OPNT_ACCT_NAME_FST <> T1.CUST_NAME
		)        -- 对方户名 <> 客户名称
      AND T1.OPNT_ACCT IS NOT NULL        -- 对方客户账号不为空
      AND T1.AMT >0                       --交易金额
      AND T1.XIANZZBZ = '1'             -- 现转标志为转账
   AND T1.CHONGZBZ = '0'; --要未冲正的数据

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：资金往来明细';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：资金往来-转出前10
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 第4段业务逻辑：资金往来-转出前10
  INSERT INTO TMP1_DWD_CUST_ENTER_RELA (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      ZRZC,
      BK_SELF_CUST_FLG,
      OPNT_CUST_NAME,
      AMT
  )
  SELECT
         R.DATA_DATE             , -- 数据日期
         R.PERSN_LEGAL_BK_CODE   , -- 法人行号
         R.CUST_ID               , -- 客户编号
         R.ZRZC                  , -- 转入转出(0-转出,1-转入)
         R.BK_SELF_CUST_FLG      , -- 是否我行客户(0-否 1-是)
         R.OPNT_CUST_NAME        , -- 对方客户名称
         R.AMT                    -- 交易金额
    FROM (
          SELECT
                 V_SYSDAT                AS DATA_DATE             , -- 数据日期
                 T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE   , -- 法人行号
                 T1.CUST_ID              AS CUST_ID               , -- 客户编号
                 T1.ZRZC                 AS ZRZC                  , -- 转入转出(0-转出,1-转入)
                 T1.BK_SELF_CUST_FLG     AS BK_SELF_CUST_FLG      , -- 是否我行客户(0-否 1-是)
                 T1.OPNT_CUST_NAME       AS OPNT_CUST_NAME        , -- 对方客户名称
                 SUM(T1.AMT)             AS AMT                   , -- 交易金额
                 ROW_NUMBER() OVER (
                   PARTITION BY T1.PERSN_LEGAL_BK_CODE, T1.CUST_ID
                   ORDER BY SUM(T1.AMT) DESC
                 ) AS RN
            FROM TMP_DWD_CUST_ENTER_RELA T1 -- 客户关联关系表_临时表资金往来明细
     WHERE T1.DATA_DATE >= V_SYSDAT_1Y AND T1.ZRZC = '0'
        GROUP BY T1.PERSN_LEGAL_BK_CODE, T1.CUST_ID, T1.ZRZC, T1.BK_SELF_CUST_FLG, T1.OPNT_CUST_NAME
         ) R
   WHERE R.RN <= 10;

  -- 提交第4段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：资金往来-转出前10';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5 -- 第5段处理开始：资金往来-转入前10
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  -- 第5段业务逻辑：资金往来-转入前10
  INSERT INTO TMP1_DWD_CUST_ENTER_RELA (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      ZRZC,
      BK_SELF_CUST_FLG,
      OPNT_CUST_NAME,
      AMT
  )
  SELECT
         R.DATA_DATE             , -- 数据日期
         R.PERSN_LEGAL_BK_CODE   , -- 法人行号
         R.CUST_ID               , -- 客户编号
         R.ZRZC                  , -- 转入转出(0-转出,1-转入)
         R.BK_SELF_CUST_FLG      , -- 是否我行客户(0-否 1-是)
         R.OPNT_CUST_NAME        , -- 对方客户名称
         R.AMT                    -- 交易金额
    FROM (
          SELECT
                 V_SYSDAT                AS DATA_DATE             , -- 数据日期
                 T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE   , -- 法人行号
                 T1.CUST_ID              AS CUST_ID               , -- 客户编号
                 T1.ZRZC                 AS ZRZC                  , -- 转入转出(0-转出,1-转入)
                 T1.BK_SELF_CUST_FLG     AS BK_SELF_CUST_FLG      , -- 是否我行客户(0-否 1-是)
                 T1.OPNT_CUST_NAME       AS OPNT_CUST_NAME        , -- 对方客户名称
                 SUM(T1.AMT)             AS AMT                   , -- 交易金额
                 ROW_NUMBER() OVER (
                   PARTITION BY T1.PERSN_LEGAL_BK_CODE, T1.CUST_ID
                   ORDER BY SUM(T1.AMT) DESC
                 ) AS RN
            FROM TMP_DWD_CUST_ENTER_RELA T1 -- 客户关联关系表_临时表资金往来明细
     WHERE T1.DATA_DATE >= V_SYSDAT_1Y AND T1.ZRZC = '1'
        GROUP BY T1.PERSN_LEGAL_BK_CODE, T1.CUST_ID, T1.ZRZC, T1.BK_SELF_CUST_FLG, T1.OPNT_CUST_NAME
         ) R
   WHERE R.RN <= 10;

  -- 提交第5段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第5段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段业务逻辑处理完成：资金往来-转入前10';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第5段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.6 -- 第6段处理开始：资金往来
  --***************************************
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  -- 第6段业务逻辑：资金往来
  INSERT INTO DWD_CUST_ENTER_RELA (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      REL_TYP,
      REL_CUST_ID,
      REL_CUST_NAME,
      REL_VAL,
      BK_SELF_CUST_FLG,
      REL_INF
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS CUST_ID              , -- 客户编号
         '2'                     AS REL_TYP              , -- 关系类型
         ''                      AS REL_CUST_ID          , -- 关联人客户编号
         T1.OPNT_CUST_NAME       AS REL_CUST_NAME        , -- 关联人客户名称
         T1.ZRZC                 AS REL_VAL              , -- 关联值
         T1.BK_SELF_CUST_FLG     AS BK_SELF_CUST_FLG     , -- 是否我行客户
         T1.AMT                  AS REL_INF               -- 关系内容
    FROM TMP1_DWD_CUST_ENTER_RELA T1; -- 客户关联关系表_临时表资金往来排名

  -- 提交第6段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第6段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6段业务逻辑处理完成：资金往来';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第6段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_cust_grp_detail(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_grp_detail(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 加工客群客户明细数据
  -- 作业编号: PRC_DWD_CUST_GRP_DETAIL
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_MAN
			DWS_CUST_ASSE_LIAB
			DWS_CUST_LVL_INFO
			DWS_CUST_LIFE_CYCLE_STAGE
			DWD_SYS_ORG_JGCSV
			ADS_STAT_INDX_DATA_HIS
  -- 目标表: ADS_STAT_INDX_DATA_INDX_group
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '加工客群客户明细数据';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_DWD_CUST_GRP_DETAIL';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  REC			RECORD;
  V_CUST_GRP_ID VARCHAR(40);
  V_CREATR		VARCHAR(20);
  V_PERSN_LEGAL_BK_CODE	VARCHAR(4);
  V_GRP_RULE_SQL CLOB;
  V_SQL			VARCHAR(2000);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  
  ------------------------------------------------------------------
  -- 1. 清空目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_GRP_DETAIL';
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 2. 静态客群数据插入目标表
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO DWD_CUST_GRP_DETAIL(
   	  CUST_ID , -- 客户编号
	  CREATR , -- 创建者
	  CUST_GRP_ID  , -- 客户群编号
	  PERSN_LEGAL_BK_CODE -- 法人行号
   )
   SELECT 
   	    B.CUST_ID , -- 客户编号
	    A.CREATR , -- 创建者
	    A.CUST_GRP_ID  , -- 客户群编号
	    A.PERSN_LEGAL_BK_CODE -- 法人行号
   FROM CRM.CUST_GRP_INFO A 
  INNER JOIN CRM.CUST_GRP_MBER B 
     ON A.CUST_GRP_TYP='1' 
   AND A.CUST_GRP_ID = B.CUST_GRP_ID; 
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步静态客群数据插入目标表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  
  ------------------------------------------------------------------
  -- 3. 动态客群客户明细插入目标表
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
   -- 动态客群
  FOR REC IN (SELECT CUST_GRP_ID,CREATR,PERSN_LEGAL_BK_CODE,GRP_RULE_SQL FROM   CRM.CUST_GRP_INFO WHERE CUST_GRP_TYP='2') LOOP
  V_SQL := 'INSERT INTO DWD_CUST_GRP_DETAIL(
   				CUST_ID , -- 客户编号
	  			CREATR , -- 创建者
	  			CUST_GRP_ID  , -- 客户群编号
	  			PERSN_LEGAL_BK_CODE -- 法人行号
   			)
   			SELECT CUST_ID,'||REC.CUST_GRP_ID||','||REC.CREATR||','||REC.PERSN_LEGAL_BK_CODE||
   			' FROM ADS_CRM_R_CUST_LABLE 
			 WHERE 1=1 
               AND '||REC.GRP_RULE_SQL;
  EXECUTE IMMEDIATE V_SQL;
  DBMS_OUTPUT.PUT_LINE(V_SQL);
  COMMIT;
  END LOOP;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3步动态客群客户明细插入目标表完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
     
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_cust_indiv_crdt(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_indiv_crdt(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 个人客户授信信息处理
  -- 存储过程编号: PRC_DWD_CUST_INDIV_CRDT
  -- 处理周期: 日
  -- 过程描述: 根据 CUST_INDIV_CRDT 映射关系生成个人客户授信信息
  -- 来源表: CMS_CUSTOMER_INFO(客户信息表), CMS_BUSINESS_CONTRACT(合同业务表)
  -- 目标表: DWD_CUST_INDIV_CRDT(个人客户授信信息)
  -- author :
  -- date   : 2026-07-15
  -- 适配数据库: 人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '个人客户授信信息处理';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CUST_INDIV_CRDT';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_INDIV_CRDT';

  --***************************************
  -- 2.1 个人客户授信信息落库
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWD_CUST_INDIV_CRDT (
      CUST_ID,
      CUST_NAME,
      CRDT_AGRE_NO,
      CRDT_AGRE_TYP,
      CRDT_TTL_LMT,
      BGN_DATE,
      EXPR_DATE,
      CRDT_STATUS,
      PERSN_LEGAL_BK_CODE
  )
  SELECT
      c.mfcustomerid     AS CUST_ID,             -- 客户编号；核心客户号
      c.customername     AS CUST_NAME,           -- 客户名称
      bc.serialno        AS CRDT_AGRE_NO,        -- 授信协议号；合同流水号
      bc.creditcycle     AS CRDT_AGRE_TYP,       -- 授信协议类型；映射表未提供可确认来源 使用是否循环
      bc.businesssum     AS CRDT_TTL_LMT,        -- 授信额度；单笔授信额度
      bc.putoutdate      AS BGN_DATE,            -- 开始日期；授信起始日期
      bc.maturity        AS EXPR_DATE,           -- 到期日期；映射字段 MaturityDate 在 new 5 中对应 maturity
      bc.status          AS CRDT_STATUS,         -- 合同状态；映射表未提供可确认来源
      CASE WHEN TT.MAINFRAMEORGID LIKE '15%' THEN '1500' 
      	   WHEN TT.MAINFRAMEORGID LIKE '12%' THEN '1200'
      	   WHEN TT.MAINFRAMEORGID LIKE '18%' THEN '1800'
      	   ELSE '9999' END    AS PERSN_LEGAL_BK_CODE  -- 法人行号；映射表未提供可确认来源
    FROM CMS_CUSTOMER_INFO c                          -- 客户信息表
   INNER JOIN CMS_BUSINESS_CONTRACT bc                -- 合同业务表
      ON bc.customerid = c.customerid
   LEFT JOIN CMS_ORG_INFO tt
    ON bc.OPERATEORGID = tt.ORGID
   where  c.mfcustomerid LIKE '1%';

  COMMIT;

  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.1 个人客户授信信息落库';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  --***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_cust_indiv_mner(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_indiv_mner(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 家庭成员信息表
  -- 存储过程编号：PRC_DWD_CUST_INDIV_MNER
  -- 处理周期：日
  -- 过程描述：根据 DWD 数据模型映射生成
  -- 来源表：DWD_CUST_INDV_INFO(客户基本信息表)；ECIF_T01_P_CUST_INFO(对私客户基本信息)；ECIF_T01_P_RELATIONER_INFO(对私客户关系人信息)；ECIF_T02_P_PAR_TO_PAR_REL(对私参与人之间的关系)；TMP1_DWD_CUST_INDV_INFO(客户基本信息表_临时表客户手机号码)
  -- 目标表：DWD_CUST_INDIV_MNER
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '家庭成员信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CUST_INDIV_MNER';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);


BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;



  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_INDIV_MNER';

  --***************************************
  -- 2.1 -- 第1段处理开始：家庭成员为本行
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：家庭成员为本行
  INSERT INTO DWD_CUST_INDIV_MNER (
      PK_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      MBER_NAME,
      MBER_REL,
      GEND,
      TEL_NO,
      BK_SELF_CUST_FLG,
      INNER_BK_CUST_ID,
      BTH_DATE,
      MARI_DAY_MEM,
      CERT_ID,
      CERT_TYP,
      SYS_SRC,
      POST_ID,
      REMARK
  )
  SELECT
         SEQ_DWD_CUST_INDIV_MNER.NEXTVAL     AS PK_ID                , -- 主键
         T0.PERSN_LEGAL_BK_CODE              AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.ECIF_CUST_NO                     AS CUST_ID              , -- 客户编号
         T2.REL_NAME                         AS MBER_NAME            , -- 成员姓名
         (CASE
          WHEN T2.RELATION_TYPE IN ('1110', '1111', '1112') THEN '02'
          WHEN T2.RELATION_TYPE IN ('1120') THEN '01'
          WHEN T2.RELATION_TYPE IN ('1130', '1131', '1132') THEN '03'
          WHEN T2.RELATION_TYPE IN ('1210', '1211', '1212') THEN '04'
          WHEN T2.RELATION_TYPE IN ('1220', '1221', '1222') THEN '05'
          WHEN T2.RELATION_TYPE IN ('1100') THEN '06'
          WHEN T2.RELATION_TYPE IN ('1200') THEN '07'
          ELSE T2.RELATION_TYPE
         END) AS MBER_REL, -- 成员关系
         (CASE
          WHEN T3.GENDER IN ('0') THEN '9'
          ELSE T3.GENDER
         END) AS GEND, -- 性别
         T4.PHONE_NO                         AS TEL_NO               , -- 联系电话
         '0'                                 AS BK_SELF_CUST_FLG     , -- 是否本行客户
         T3.ECIF_CUST_NO                     AS INNER_BK_CUST_ID     , -- 行内客户编号
         TO_CHAR(T3.BIRTH_DATE, 'yyyymmdd')  AS BTH_DATE             , -- 出生日期
         ''                                  AS MARI_DAY_MEM         , -- 结婚纪念日
         T3.CERT_NO                          AS CERT_ID              , -- 证件号码
         T3.CERT_TYPE                        AS CERT_TYP             , -- 证件类型
         T2.INIT_SYSTEM_ID                   AS SYS_SRC              , -- 系统来源
         T2.LAST_UPDATED_TE                  AS POST_ID              , -- 维护人
         ''                                  AS REMARK                -- 备注
    FROM DWD_CUST_INDV_INFO T0 -- 客户基本信息表
    LEFT JOIN ECIF_T01_P_CUST_INFO T1 -- 对私客户基本信息
      ON T0.CUST_ID = T1.ECIF_CUST_NO
    LEFT JOIN ECIF_T02_P_PAR_TO_PAR_REL T2 -- 对私参与人之间的关系
      ON T1.PARTY_ID = T2.PARTY_ID
    LEFT JOIN ECIF_T01_P_CUST_INFO T3 -- 对私客户基本信息
      ON T2.RELATION_ID=T3.PARTY_ID
    LEFT JOIN TMP1_DWD_CUST_INDV_INFO T4 -- 客户基本信息表_临时表客户手机号码
      ON T0.CUST_ID = T4.CUST_ID
   WHERE t2.RELATION_TAB_ID='TB110101'
    AND t3.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t2.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t1.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND T2.RELATION_TYPE IN ('1100','1110','1111','1112','1120','1130','1131','1132','1200','1210','1211','1212','1220','1221','1222');

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：家庭成员为本行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：MAPPING映射_源表信息(Group_02)家庭成员为他行
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：MAPPING映射_源表信息(Group_02)家庭成员为他行
  INSERT INTO DWD_CUST_INDIV_MNER (
      PK_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      MBER_NAME,
      MBER_REL,
      GEND,
      TEL_NO,
      BK_SELF_CUST_FLG,
      INNER_BK_CUST_ID,
      BTH_DATE,
      MARI_DAY_MEM,
      CERT_ID,
      CERT_TYP,
      SYS_SRC,
      POST_ID,
      REMARK
  )
  SELECT
         SEQ_DWD_CUST_INDIV_MNER.NEXTVAL     AS PK_ID                , -- 主键
         T0.PERSN_LEGAL_BK_CODE              AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.ECIF_CUST_NO                     AS CUST_ID              , -- 客户编号
         T2.REL_NAME                         AS MBER_NAME            , -- 成员姓名
         (CASE
          WHEN T2.RELATION_TYPE IN ('1110', '1111', '1112') THEN '02'
          WHEN T2.RELATION_TYPE IN ('1120') THEN '01'
          WHEN T2.RELATION_TYPE IN ('1130', '1131', '1132') THEN '03'
          WHEN T2.RELATION_TYPE IN ('1210', '1211', '1212') THEN '04'
          WHEN T2.RELATION_TYPE IN ('1220', '1221', '1222') THEN '05'
          WHEN T2.RELATION_TYPE IN ('1100') THEN '06'
          WHEN T2.RELATION_TYPE IN ('1200') THEN '07'
          ELSE T2.RELATION_TYPE
         END) AS MBER_REL, -- 成员关系
         (CASE
          WHEN T3.GENDER IN ('0') THEN '9'
          ELSE T3.GENDER
         END) AS GEND, -- 性别
         T3.FINDTEL_NO                       AS TEL_NO               , -- 联系电话
         '1'                                 AS BK_SELF_CUST_FLG     , -- 是否本行客户
         ''                                  AS INNER_BK_CUST_ID     , -- 行内客户编号
         TO_CHAR(T3.BIRTH_DATE, 'yyyymmdd')  AS BTH_DATE             , -- 出生日期
         ''                                  AS MARI_DAY_MEM         , -- 结婚纪念日
         T2.REL_CERT_NO                      AS CERT_ID              , -- 证件号码
         T2.REL_CERT_TYPE                    AS CERT_TYP             , -- 证件类型
         T2.INIT_SYSTEM_ID                   AS SYS_SRC              , -- 系统来源
         T2.LAST_UPDATED_TE                  AS POST_ID              , -- 维护人
         ''                                  AS REMARK                -- 备注
    FROM DWD_CUST_INDV_INFO T0 -- 客户基本信息表
    LEFT JOIN ECIF_T01_P_CUST_INFO T1 -- 对私客户基本信息
      ON T0.CUST_ID = T1.ECIF_CUST_NO
    LEFT JOIN ECIF_T02_P_PAR_TO_PAR_REL T2 -- 对私参与人之间的关系
      ON T1.PARTY_ID=T2.PARTY_ID
    LEFT JOIN ECIF_T01_P_RELATIONER_INFO T3 -- 对私客户关系人信息
      ON T2.RELATION_ID=T3.RELATION_ID
   WHERE t2.RELATION_TAB_ID='TB110105'
    AND t3.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t2.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND t1.UPDATED_TS = to_timestamp('99991231','yyyymmdd')
    AND T2.RELATION_TYPE IN ('1100','1110','1111','1112','1120','1130','1131','1132','1200','1210','1211','1212','1220','1221','1222');

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：MAPPING映射_源表信息(Group_02)家庭成员为他行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_cust_indiv_risk_invst(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_indiv_risk_invst(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户风险评估
  -- 存储过程编号: PRC_DWD_CUST_INDIV_RISK_INVST
  -- 处理周期: 日
  -- 过程描述: 根据 FMS_T4_CUST_RISK_ASSESS_INFO 映射关系生成客户风险评估信息
  -- 来源表: FMS_T4_CUST_RISK_ASSESS_INFO(客户风险承受能力评估信息表)
  -- 目标表: DWD_CUST_INDIV_RISK_INVST(客户风险评估)
  -- author :
  -- date   : 2026-07-15
  -- 适配数据库: 人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户风险评估';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CUST_INDIV_RISK_INVST';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT2 := sys_fun_deal_date(V_SYSDAT, 1);  -- 参数1：上一日
  P_INTERVAL_START_DATE := sys_fun_deal_date(V_SYSDAT, 18);  -- 参数18：30天承接窗口开始日
  P_INTERVAL_END_DATE   := sys_fun_deal_date(V_SYSDAT, 1);  -- 参数1：上一日

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_INDIV_RISK_INVST';

  --***************************************
  -- 2.1 理财-客户风险评估落库
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWD_CUST_INDIV_RISK_INVST (
      CUST_ID,
      INVEST_TYP,
      ESTIM_RSLT,
      SCORE,
      RISK_LVL,
      ESTIM_DATE,
      EXPR_DATE,
      PERSN_LEGAL_BK_CODE
  )
  SELECT 
  	  CUST_ID,
      INVEST_TYP,
      ESTIM_RSLT,
      SCORE,
      RISK_LVL,
      ESTIM_DATE,
      EXPR_DATE,
      PERSN_LEGAL_BK_CODE
	  FROM (
		  SELECT DISTINCT 
		      host_cust_no	  AS CUST_ID,   --主机客户号
		      '1'             AS INVEST_TYP,--投资类型
		      NULL	          AS ESTIM_RSLT,--评估结果
		      NULL	          AS SCORE,     --分数
		      CUST_RISK_LEVEL	AS RISK_LVL,  --风险承受等级
		      ASSESS_DATE	    AS ESTIM_DATE,--评估日期
		      INVALID_DATE	  AS EXPR_DATE, --失效日期
		      CASE WHEN sub_branch_code LIKE '15%' THEN '1500' 
		      	   WHEN sub_branch_code LIKE '12%' THEN '1200'
		      	   WHEN sub_branch_code LIKE '18%' THEN '1800'
		      	   ELSE '9999' END      AS PERSN_LEGAL_BK_CODE, --法人行号
		      ROW_NUMBER() OVER(PARTITION BY HOST_CUST_NO ORDER BY A.ASSESS_DATE DESC) rn
		    FROM FMS_T4_CUST_RISK_ASSESS_INFO A	-- 客户风险承受能力评估信息表
		WHERE INVALID_DATE>=V_SYSDAT AND  HOST_CUST_NO IS NOT NULL
	) A WHERE A.RN=1;
  COMMIT;

  OUTCDE := 0;
    V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理当前数据日统计结果、三年前历史数据和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );


  --***************************************
  -- 2.2 保险-客户风险评估落库
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
/*9月保险上线后*/
    V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  OUTCDE := 0;
  V_LOG_MSG := 'TMP1 完成：清理当前数据日统计结果、三年前历史数据和物理临时表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );


  --***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  --***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;

    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    RAISE;
END





;

-- DROP PROCEDURE crmdm.prc_dwd_cust_indv_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_indv_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户基本信息表
  -- 存储过程编号：PRC_DWD_CUST_INDV_INFO
  -- 处理周期：日
  -- 过程描述：根据 DWD 数据模型映射生成
  -- 来源表：CBS_KDPA_ZHXINX(负债账户信息表)；DWD_ACCT_LOAN(贷款款账户信息)；ECIF_T01_P_CUST_INFO(对私客户基本信息)；ECIF_T01_P_CUST_WORK(对私客户工作履历)；ECIF_T02_A_CUST_ADDR_REL(待确认：来源表中文名缺失)；ECIF_T02_A_CUST_TELE_REL(参与人与联系电话的关系)；ECIF_T03_A_TELE_INFO(客户联系电话信息)；FLAT_ADDR(一个客户的多种地址)；TMP1_DWD_CUST_INDV_INFO(客户基本信息表_临时表客户手机号码)；TMP2_DWD_CUST_INDV_INFO(客户基本信息表_临时表客户年龄)；TMP_DWD_CUST_INDV_INFO(客户基本信息表_临时表客户归属法人行)
  -- 目标表：DWD_CUST_INDV_INFO；TMP1_DWD_CUST_INDV_INFO；TMP2_DWD_CUST_INDV_INFO；TMP_DWD_CUST_INDV_INFO
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户基本信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CUST_INDV_INFO';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);


BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;



  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWD_CUST_INDV_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_DWD_CUST_INDV_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP2_DWD_CUST_INDV_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_INDV_INFO';

  --***************************************
  -- 2.1 -- 第1段处理开始：处理ECIF客户、处理核心客户、处理信贷客户
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：处理ECIF客户、处理核心客户、处理信贷客户
  INSERT INTO TMP_DWD_CUST_INDV_INFO (
      PERSN_LEGAL_BK_CODE,
      CUST_ID
  )
  SELECT DISTINCT
         T.PERSN_LEGAL_BK_CODE   , -- 法人行号
         T.CUST_ID                -- 客户编号
    FROM (
          -- 处理ECIF客户
          SELECT
         '9999'           AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.ECIF_CUST_NO  AS CUST_ID               -- 客户编号
    FROM ECIF_T01_P_CUST_INFO T1 -- 对私客户基本信息
   WHERE UPDATED_TS = TO_TIMESTAMP('99991231','YYYYMMDD')
          UNION
          -- 处理核心客户
          SELECT
         CASE
           WHEN T1.KAIHJIGO LIKE '12%' THEN '1200'
           WHEN T1.KAIHJIGO LIKE '15%' THEN '1500'
           WHEN T1.KAIHJIGO LIKE '18%' THEN '1800'
           ELSE '9999'
         END AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T1.KEHUHAOO  AS CUST_ID               -- 客户编号
    FROM CBS_KDPA_ZHXINX T1 -- 负债账户信息表
   WHERE T1.KEHUHAOO LIKE '1%' AND (T1.KAIHJIGO LIKE '12%' OR T1.KAIHJIGO LIKE '15%' OR T1.KAIHJIGO LIKE '18%')
          UNION
          -- 处理信贷客户
          SELECT
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS CUST_ID               -- 客户编号
    FROM DWD_ACCT_LOAN T1 -- 贷款款账户信息
   WHERE T1.PERSN_LEGAL_BK_CODE <>'9999'
         ) T;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：处理ECIF客户、处理核心客户、处理信贷客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：处理客户手机号
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：处理客户手机号
  INSERT INTO TMP1_DWD_CUST_INDV_INFO (
      CUST_ID,
      PHONE_NO
  )
  SELECT
         R.CUST_ID           , -- 客户编号
         R.PHONE_NO           -- 手机号码
    FROM (
          SELECT
                 T1.ECIF_CUST_NO   AS CUST_ID           , -- 客户编号
                 T3.PHONE_NO       AS PHONE_NO          , -- 手机号码
                 ROW_NUMBER() OVER (
                   PARTITION BY T2.PARTY_ID
                   ORDER BY T2.LAST_UPDATED_TS DESC
                 ) AS RN
        FROM ECIF_T01_P_CUST_INFO T1 -- 对私客户基本信息
        LEFT JOIN ECIF_T02_A_CUST_TELE_REL T2 -- 参与人与联系电话的关系
          ON T1.PARTY_ID = T2.PARTY_ID
        LEFT JOIN ECIF_T03_A_TELE_INFO T3 -- 客户联系电话信息
          ON T2.TELE_ID = T3.TELE_ID
       WHERE T2.TELE_TYPE = '102' --移动电话 
      AND T3.PHONE_NO LIKE '1%'
      AND LENGTH(T3.PHONE_NO) = 11
      AND T1.UPDATED_TS = TO_TIMESTAMP('99991231 00:00:00', 'yyyymmdd hh24:mi:ss')
         ) R
   WHERE R.RN = 1;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：处理客户手机号';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：处理客户年龄
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：处理客户年龄
  INSERT INTO TMP2_DWD_CUST_INDV_INFO (
      CUST_ID,
      AGE
  )
  SELECT
         T1.ECIF_CUST_NO  AS CUST_ID  , -- 客户编号
         CASE
           WHEN REGEXP_LIKE(T1.CERT_NO, '^[0-9]{17}[0-9Xx]$')
                AND TO_NUMBER(SUBSTR(T1.CERT_NO, 11, 2)) BETWEEN 1 AND 12
                AND TO_NUMBER(SUBSTR(T1.CERT_NO, 13, 2)) BETWEEN 1 AND
                    CASE
                      WHEN SUBSTR(T1.CERT_NO, 11, 2) IN ('01', '03', '05', '07', '08', '10', '12') THEN 31
                      WHEN SUBSTR(T1.CERT_NO, 11, 2) IN ('04', '06', '09', '11') THEN 30
                      WHEN SUBSTR(T1.CERT_NO, 11, 2) = '02'
                           AND (
                             MOD(TO_NUMBER(SUBSTR(T1.CERT_NO, 7, 4)), 400) = 0
                             OR (
                               MOD(TO_NUMBER(SUBSTR(T1.CERT_NO, 7, 4)), 4) = 0
                               AND MOD(TO_NUMBER(SUBSTR(T1.CERT_NO, 7, 4)), 100) <> 0
                             )
                           )
                      THEN 29
                      ELSE 28
                    END
           THEN TRUNC(MONTHS_BETWEEN(
                  TO_DATE(V_SYSDAT, 'YYYYMMDD'),
                  TO_DATE(SUBSTR(T1.CERT_NO, 7, 8), 'YYYYMMDD')
                ) / 12)
           WHEN REGEXP_LIKE(T1.CERT_NO, '^[0-9]{15}$')
                AND TO_NUMBER(SUBSTR(T1.CERT_NO, 9, 2)) BETWEEN 1 AND 12
                AND TO_NUMBER(SUBSTR(T1.CERT_NO, 11, 2)) BETWEEN 1 AND
                    CASE
                      WHEN SUBSTR(T1.CERT_NO, 9, 2) IN ('01', '03', '05', '07', '08', '10', '12') THEN 31
                      WHEN SUBSTR(T1.CERT_NO, 9, 2) IN ('04', '06', '09', '11') THEN 30
                      WHEN SUBSTR(T1.CERT_NO, 9, 2) = '02'
                           AND (
                             MOD(TO_NUMBER('19' || SUBSTR(T1.CERT_NO, 7, 2)), 400) = 0
                             OR (
                               MOD(TO_NUMBER('19' || SUBSTR(T1.CERT_NO, 7, 2)), 4) = 0
                               AND MOD(TO_NUMBER('19' || SUBSTR(T1.CERT_NO, 7, 2)), 100) <> 0
                             )
                           )
                      THEN 29
                      ELSE 28
                    END
           THEN TRUNC(MONTHS_BETWEEN(
                  TO_DATE(V_SYSDAT, 'YYYYMMDD'),
                  TO_DATE('19' || SUBSTR(T1.CERT_NO, 7, 6), 'YYYYMMDD')
                ) / 12)
           ELSE 0
         END AS AGE -- 年龄
    FROM ECIF_T01_P_CUST_INFO T1 -- 对私客户基本信息
   WHERE T1.CERT_TYPE = '01'
      AND T1.UPDATED_TS = TO_TIMESTAMP('99991231 00:00:00', 'yyyymmdd hh24:mi:ss');

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：处理客户年龄';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：处理客户基本信息
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 第4段业务逻辑：处理客户基本信息
  INSERT INTO DWD_CUST_INDV_INFO (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      PARTY_ID,
      CERT_TYP,
      CERT_ID,
      CERT_PRD_VLID,
      CERT_PRD_VLID_END,
      CERT_ISSUING,
      CERT_ISSUING_AUTHORITY,
      CUST_TYP,
      OPEN_DATE,
      OPEN_ORG,
      NATIONALITY,
      NATION,
      MARI_SITU,
      MAX_DEG_EDU,
      NOW_ENTER,
      OCCU_CLS,
      GEND,
      AGE,
      PHONE_NO,
      CONTACT_ADDRESS,
      CONTACT_ADDRESS_DETAIL,
      ID_ADDRESS,
      ID_ADDRESS_DETAIL,
      HOME_ADDRESS,
      HOME_ADDRESS_DETAIL,
      RESIDENCE_ADDRESS,
      RESIDENCE_ADDRESS_DETAIL,
      OFFICE_ADDRESS,
      OFFICE_ADDRESS_DETAIL
  )
  WITH FLAT_ADDR AS (
    SELECT
    t1.PARTY_ID
    -- 103: 联系地址
    ,MAX(CASE WHEN t1.ADDR_TYPE = '103' THEN t2.NATION || t2.PROVINCE || t2.CITY || t2.COUNTY || t2.STREET END) AS CONTACT_ADDRESS
    ,MAX(CASE WHEN t1.ADDR_TYPE = '103' THEN t2.ADDR_LINE END) AS CONTACT_ADDRESS_DETAIL
    -- 110: 证件地址
    ,MAX(CASE WHEN t1.ADDR_TYPE = '110' THEN t2.NATION || t2.PROVINCE || t2.CITY || t2.COUNTY || t2.STREET END) AS ID_ADDRESS
    ,MAX(CASE WHEN t1.ADDR_TYPE = '110' THEN t2.ADDR_LINE END) AS ID_ADDRESS_DETAIL
    -- 104: 家庭地址
    ,MAX(CASE WHEN t1.ADDR_TYPE = '104' THEN t2.NATION || t2.PROVINCE || t2.CITY || t2.COUNTY || t2.STREET END) AS HOME_ADDRESS
    ,MAX(CASE WHEN t1.ADDR_TYPE = '104' THEN t2.ADDR_LINE END) AS HOME_ADDRESS_DETAIL
    -- 105: 住宅地址
    ,MAX(CASE WHEN t1.ADDR_TYPE = '105' THEN t2.NATION || t2.PROVINCE || t2.CITY || t2.COUNTY || t2.STREET END) AS RESIDENCE_ADDRESS
    ,MAX(CASE WHEN t1.ADDR_TYPE = '105' THEN t2.ADDR_LINE END) AS RESIDENCE_ADDRESS_DETAIL
    -- 111: 办公地址
    ,MAX(CASE WHEN t1.ADDR_TYPE = '111' THEN t2.NATION || t2.PROVINCE || t2.CITY || t2.COUNTY || t2.STREET END) AS OFFICE_ADDRESS
    ,MAX(CASE WHEN t1.ADDR_TYPE = '111' THEN t2.ADDR_LINE END) AS OFFICE_ADDRESS_DETAIL
    FROM ECIF_T02_A_CUST_ADDR_REL t1
    INNER JOIN ECIF_T03_A_ADDR_INFO t2
    ON t1.ADDR_ID = t2.ADDR_ID
    WHERE t1.ADDR_TYPE IN ('103', '110', '104', '105', '111')
      AND t1.updated_ts = TO_TIMESTAMP('99991231 00:00:00', 'yyyymmdd hh24:mi:ss')
    GROUP BY t1.PARTY_ID
  )
  SELECT
         T0.PERSN_LEGAL_BK_CODE                  AS PERSN_LEGAL_BK_CODE       , -- 法人行号
         T0.CUST_ID                              AS CUST_ID                   , -- 客户编号
         T1.PARTY_NAME                           AS CUST_NAME                 , -- 客户名称
         T1.PARTY_ID                             AS PARTY_ID                  , -- 参与人ID
         T1.CERT_TYPE                            AS CERT_TYP                  , -- 证件类型
         T1.CERT_NO                              AS CERT_ID                   , -- 证件号码
         TO_CHAR(T1.CERT_ISSUE_DATE,'YYYYMMDD')  AS CERT_PRD_VLID             , -- 证件有效期起
         TO_CHAR(T1.CERT_DUE_DATE,'YYYYMMDD')    AS CERT_PRD_VLID_END         , -- 证件有效期止
         T1.CERT_ORG_NAME                        AS CERT_ISSUING              , -- 签发机关
         T1.CERT_ORG_AREA                        AS CERT_ISSUING_AUTHORITY    , -- 签发机关所在地
         '1'                                     AS CUST_TYP                  , -- 客户类型
         TO_CHAR(T1.OPEN_DATE,'YYYYMMDD')        AS OPEN_DATE                 , -- 开户日期
         T1.OPEN_ORG                             AS OPEN_ORG                  , -- 开户机构
         T1.NAT_CODE                             AS NATIONALITY               , -- 国籍
         T1.PEOPLE                               AS NATION                    , -- 民族
         T1.MARITAL_STAT                         AS MARI_SITU                 , -- 婚姻状况
         T1.HIGHEST_DEGREE                       AS MAX_DEG_EDU               , -- 最高学历
         T2.WORK_CORP                            AS NOW_ENTER                 , -- 现工作单位
         T1.PROFESSION                           AS OCCU_CLS                  , -- 职业分类
         (CASE
          WHEN T1.GENDER IN ('0') THEN '9'
          ELSE T1.GENDER
         END) AS GEND, -- 性别
         T4.AGE                                  AS AGE                       , -- 年龄
         T3.PHONE_NO                             AS PHONE_NO                  , -- 手机号码
         T5.CONTACT_ADDRESS                      AS CONTACT_ADDRESS           , -- 联系地址
         T5.CONTACT_ADDRESS_DETAIL               AS CONTACT_ADDRESS_DETAIL    , -- 联系地址详细地址
         T5.ID_ADDRESS                           AS ID_ADDRESS                , -- 证件地址
         T5.ID_ADDRESS_DETAIL                    AS ID_ADDRESS_DETAIL         , -- 证件地址详细地址
         T5.HOME_ADDRESS                         AS HOME_ADDRESS              , -- 家庭地址
         T5.HOME_ADDRESS_DETAIL                  AS HOME_ADDRESS_DETAIL       , -- 家庭地址详细地址
         T5.RESIDENCE_ADDRESS                    AS RESIDENCE_ADDRESS         , -- 住宅地址
         T5.RESIDENCE_ADDRESS_DETAIL             AS RESIDENCE_ADDRESS_DETAIL  , -- 住宅地址详细地址
         T5.OFFICE_ADDRESS                       AS OFFICE_ADDRESS            , -- 办公地址
         T5.OFFICE_ADDRESS_DETAIL                AS OFFICE_ADDRESS_DETAIL      -- 办公地址详细地址
    FROM TMP_DWD_CUST_INDV_INFO T0 -- 客户基本信息表_临时表客户归属法人行
    LEFT JOIN ECIF_T01_P_CUST_INFO T1 -- 对私客户基本信息
      ON T0.CUST_ID = T1.ECIF_CUST_NO
    LEFT JOIN ECIF_T01_P_CUST_WORK T2 -- 对私客户工作履历
      ON T1.PARTY_ID = T2.PARTY_ID
    LEFT JOIN TMP1_DWD_CUST_INDV_INFO T3 -- 客户基本信息表_临时表客户手机号码
      ON T0.CUST_ID = T3.CUST_ID
    LEFT JOIN TMP2_DWD_CUST_INDV_INFO T4 -- 客户基本信息表_临时表客户年龄
      ON T0.CUST_ID = T4.CUST_ID
    LEFT JOIN FLAT_ADDR T5 -- 一个客户的多种地址
      ON T1.PARTY_ID = T5.PARTY_ID
   WHERE t1.UPDATED_TS = to_timestamp('99991231','yyyymmdd');

  -- 提交第4段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：处理客户基本信息';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_cust_man(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_man(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 管户信息处理
  -- 作业编号: PRC_DWD_CUST_MAN
  -- 处理周期: 每日
  -- 来源表: crm.cust_man cms_
  -- 目标表: DWD_CUST_MAN
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '管户信息处理';
  V_PRC_NAME    VARCHAR(32)  := 'PRC_DWD_CUST_MAN';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LASTYEAR	VARCHAR(8);
BEGIN
   
  ------------------------------------------------------------------
  -- 1. 装载信贷管户关系
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  -- V_LASTYEAR := TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -12),'YYYYMMDD');
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_MAN';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_CUST_MNGR_INFO';
  INSERT INTO DWD_CUST_MAN (
      CUST_ID, -- 客户编号
      MNGR_POST_ID, --客户经理编号
      ORG_ID, --归属机构
      MNG_TYP, --管户类型 1-理财管户 2-信贷管户
      MODF_TIME, --变更时间
      MODF_TYP, --变更类型
      DATA_SRC, -- 来源
      VALID_DATE, -- 有效日期
      PERSN_LEGAL_BK_CODE --法人行号
  )
  SELECT 
   		CUST_ID, -- 客户编号
      MNGR_POST_ID, --客户经理编号
      ORG_ID, --归属机构
      MNG_TYP, --管户类型 1-理财管户 2-信贷管户
      MODF_TIME, --变更时间
      MODF_TYP, --变更类型
      DATA_SRC, -- 来源
      VALID_DATE, -- 有效日期
      PERSN_LEGAL_BK_CODE --法人行号
      FROM (
   select  
  	  A1.*,ROW_NUMBER() OVER(PARTITION BY CUST_ID,PERSN_LEGAL_BK_CODE ORDER BY MODF_TIME DESC) RN
     from (
	  SELECT  
	  	 B.MFCUSTOMERID CUST_ID, -- 客户编号
	  	 a."customerid" ,
	  	 D.MFUSERID||'-1-C-'||C.MAINFRAMEORGID MNGR_POST_ID, --客户经理编号
	     C.MAINFRAMEORGID ORG_ID, --归属机构
	     '2' MNG_TYP, --管户类型 1-理财管户 2-信贷管户
	     CASE WHEN A.UPDATEDATE IS NULL THEN to_char(SYSDATE(),'YYYYMMDD') ELSE  TO_CHAR(TO_DATE(A.UPDATEDATE,'YYYY/MM/DD'),'YYYYMMDD') END  MODF_TIME, --变更时间
	     '0' MODF_TYP, --变更类型
	     'CMS' DATA_SRC, -- 来源
	     '' VALID_DATE, -- 有效日期
	     case when substring(C.MAINFRAMEORGID,1,2)='12' then '1200'
	     	when substring(C.MAINFRAMEORGID,1,2)='15' then '1500'
	     	when substring(C.MAINFRAMEORGID,1,2)='18' then '1800'
	     	else '9999' end  PERSN_LEGAL_BK_CODE --法人行号
	     	
	  FROM CMS_CUSTOMER_BELONG A, CMS_CUSTOMER_INFO B ,CMS_ORG_INFO C,CMS_USER_INFO D-- ,CRM_SYS_POST E
	  WHERE A.CUSTOMERID = B.CUSTOMERID 
	  	AND A.USERID = D.USERID 
	  	AND D.BELONGORG = C.ORGID 
	  	-- AND D.MFUSERID = E.EMP_ID 
	  	-- AND C.MAINFRAMEORGID = E.ORG_ID
	  	-- AND E.JOB_CLS = 'C'
	  AND B.MFCUSTOMERID LIKE '1%' AND A.BELONGATTRIBUTE ='1' and D.MFUSERID is not null and C.MAINFRAMEORGID is not null and D.MFUSERID not like 'M%' 
		) A1 
		) A WHERE A.RN=1 ;
	COMMIT;
  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步信贷管户关系装载完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  ------------------------------------------------------------------
  -- 2. 装载crm管户关系
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
  INSERT INTO DWD_CUST_MAN (
      CUST_ID, -- 客户编号
      MNGR_POST_ID, --客户经理编号
      ORG_ID, --归属机构
      MNG_TYP, --管户类型 1-理财管户 2-信贷管户
      MODF_TIME, --变更时间
      MODF_TYP, --变更类型
      DATA_SRC, -- 来源
      VALID_DATE, -- 有效日期
      PERSN_LEGAL_BK_CODE --法人行号
  )
  SELECT 
  	 CUST_ID, -- 客户编号
      MNGR_POST_ID, --客户经理编号
      ORG_ID, --归属机构
      MNG_TYP, --管户类型 1-理财管户 2-信贷管户
      MODF_TIME, --变更时间
      MODF_TYP, --变更类型
      DATA_SRC, -- 来源
      VALID_DATE, -- 有效日期
      PERSN_LEGAL_BK_CODE --法人行号
  FROM CRM.CUST_MAN A
  WHERE A.DATA_SRC='CRM';
  COMMIT;
  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步CRM管户关系装载完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

   ------------------------------------------------------------------
  -- 3. 装载管户信息
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
  INSERT INTO DWS_CUST_MNGR_INFO(
  		PERSN_LEGAL_BK_CODE ,-- 法人行号
  		DATA_DATE, --数据日期
		CUST_ID ,-- 核心客户号
		HOST_CUST_MNGR_POST_ID ,-- 主办客户经理职位编号
		HOST_CUST_MNGR_NAME ,-- 主办客户经理名称
		HOST_CUST_MNGR_EMP_ID ,-- 主办客户经理工号
		ORG_LEAD ,-- 主办机构(归属机构)
		ORG_LEAD_PATH ,-- 主办机构路径
		COSPSR_CUST_MNGR_POST_ID ,-- 信贷客户经理职位编号
		COSPSR_CUST_MNGR_NAME ,-- 信贷客户经理名称
		COSPSR_CUST_MNGR_EMP_ID ,-- 信贷客户经理工号
		COSPSR_ORG ,-- 信贷机构
		COSPSR_ORG_PATH -- 信贷机构路径
  )
	SELECT 
		PERSN_LEGAL_BK_CODE ,-- 法人行号
		V_SYSDAT, --数据日期
		CUST_ID ,-- 核心客户号
		MAX(HOST_CUST_MNGR_POST_ID) ,-- 主办客户经理职位编号
		MAX(HOST_CUST_MNGR_NAME) ,-- 主办客户经理名称
		MAX(HOST_CUST_MNGR_EMP_ID) ,-- 主办客户经理工号
		MAX(ORG_LEAD) ,-- 主办机构(归属机构)
		MAX(ORG_LEAD_PATH) ,-- 主办机构路径
		MAX(COSPSR_CUST_MNGR_POST_ID) ,-- 信贷客户经理职位编号
		MAX(COSPSR_CUST_MNGR_NAME) ,-- 信贷客户经理名称
		MAX(COSPSR_CUST_MNGR_EMP_ID) ,-- 信贷客户经理工号
		MAX(COSPSR_ORG) ,-- 信贷机构
		MAX(COSPSR_ORG_PATH) -- 信贷机构路径
		FROM (
		  SELECT 
		  	A.PERSN_LEGAL_BK_CODE,-- 法人行号
		  	A.CUST_ID ,-- 核心客户号
		  	A.MNGR_POST_ID AS HOST_CUST_MNGR_POST_ID ,-- 主办客户经理职位编号
		  	C.USR_NAME AS HOST_CUST_MNGR_NAME ,-- 主办客户经理名称
		  	C.EMP_ID AS HOST_CUST_MNGR_EMP_ID ,-- 主办客户经理工号
		  	A.ORG_ID AS ORG_LEAD ,-- 主办机构(归属机构)
			D.ORG_PATH AS ORG_LEAD_PATH ,-- 主办机构路径
			'' AS COSPSR_CUST_MNGR_POST_ID ,-- 信贷客户经理职位编号
			'' AS COSPSR_CUST_MNGR_NAME ,-- 信贷客户经理名称
			'' AS COSPSR_CUST_MNGR_EMP_ID ,-- 信贷客户经理工号
			'' AS COSPSR_ORG ,-- 信贷机构
			'' AS COSPSR_ORG_PATH -- 信贷机构路径
		  FROM DWD_CUST_MAN A 
		  LEFT JOIN CRM.SYS_POST C ON A.MNGR_POST_ID=C.POST_ID 
		  LEFT JOIN CRM.SYS_ORG D ON A.ORG_ID=D.ORG_ID
		  WHERE A.MNG_TYP='1'
		  UNION ALL 
		  SELECT 
		  	A.PERSN_LEGAL_BK_CODE,-- 法人行号
		  	A.CUST_ID ,-- 核心客户号
		  	'' AS HOST_CUST_MNGR_POST_ID ,-- 主办客户经理职位编号
		  	'' AS HOST_CUST_MNGR_NAME ,-- 主办客户经理名称
		  	'' AS HOST_CUST_MNGR_EMP_ID ,-- 主办客户经理工号
		  	'' AS ORG_LEAD ,-- 主办机构(归属机构)
			'' AS ORG_LEAD_PATH ,-- 主办机构路径
			A.MNGR_POST_ID AS COSPSR_CUST_MNGR_POST_ID ,-- 信贷客户经理职位编号
			C.USR_NAME AS COSPSR_CUST_MNGR_NAME ,-- 信贷客户经理名称
			C.EMP_ID AS COSPSR_CUST_MNGR_EMP_ID ,-- 信贷客户经理工号
			A.ORG_ID AS COSPSR_ORG ,-- 信贷机构
			D.ORG_PATH AS COSPSR_ORG_PATH -- 信贷机构路径
		  FROM DWD_CUST_MAN A 
		  LEFT JOIN CRM.SYS_POST C ON A.MNGR_POST_ID=C.POST_ID 
		  LEFT JOIN CRM.SYS_ORG D ON A.ORG_ID=D.ORG_ID
		  WHERE A.MNG_TYP='2'
	) A
	GROUP BY PERSN_LEGAL_BK_CODE ,CUST_ID
  ;
  COMMIT;
  
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3步CRM管户信息完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_cust_sign_ctrakt(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_cust_sign_ctrakt(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户签约信息
  -- 存储过程编号：PRC_DWD_CUST_SIGN_CTRAKT
  -- 处理周期：日
  -- 过程描述：
  -- 来源表：
  --   ECIF_T01_P_CUST_INFO
  --   ECIF_T02_A_CUST_SIGN_REL
  --   ECIF_T05_A_ACC_SIGN
  -- 目标表：
  --   DWD_CUST_SIGN_CTRAKT
  -- author :
  -- date   ： 2020-07-13
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_CUST_SIGN_CTRAKT';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 每次跑批前先清空目标表,保证结果为当日全量重算
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_CUST_SIGN_CTRAKT';

  --***************************************
  -- 2.0 客户签约信息
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWD_CUST_SIGN_CTRAKT (
      CUST_ID,
      CTRAKT_ACCT,
      SIGN_TYPE,
      CTRAKT_TYP,
      CTRAKT_DATE,
      PHONE_NO,
      CTRAKT_ORG,
      CTRAKT_OPRTR,
      CTRAKT_STATE,
      PERSN_LEGAL_BK_CODE
  )
  SELECT
      t0.ECIF_CUST_NO    AS CUST_ID,              -- 客户编号
      t1.ACC_SIGN_ID     AS CTRAKT_ACCT,          -- 签约账号
      t1.SIGN_TYPE       AS SIGN_TYPE,            -- 签约类型
      CASE
      WHEN t1.SIGN_TYPE = '112' THEN '01'
      WHEN t1.SIGN_TYPE = '111' THEN '02'	
      WHEN t1.SIGN_TYPE = '141' THEN '03'
      WHEN t1.SIGN_TYPE = '130' THEN '04'
      WHEN t1.SIGN_TYPE = '311' THEN '07'
      WHEN t1.SIGN_TYPE IN ('321','322','331','332','333','334','335','341','342','343','344','345','346','350','351') THEN '06'
      ELSE '05' END AS CTRAKT_TYP,           -- 签约大类型
      TO_CHAR(t2.SIGN_DATE,'YYYYMMDD')       AS CTRAKT_DATE,          -- 签约日期
      t2.SIGN_REL_PHONE  AS PHONE_NO,             -- 预留手机号
      SUBSTR(t2.SIGN_ORG,1,6)        AS CTRAKT_ORG,           -- 签约机构
      t2.ATTN_NAME       AS CTRAKT_OPRTR,         -- 签约经办人
      t1.SIGN_STATE      AS CTRAKT_STATE,         -- 签约状态
      CASE WHEN t2.SIGN_ORG LIKE '15%' THEN '1500' 
      	   WHEN t2.SIGN_ORG LIKE '12%' THEN '1200'
      	   WHEN t2.SIGN_ORG LIKE '18%' THEN '1800'
      	   ELSE '9999' END            AS PERSN_LEGAL_BK_CODE   -- 法人行号
    FROM ECIF_T01_P_CUST_INFO t0                  -- 客户信息
   INNER JOIN ECIF_T02_A_CUST_SIGN_REL t1         -- 参与人与业务签约的关系
      ON t0.PARTY_ID = t1.PARTY_ID
    LEFT JOIN ECIF_T05_A_ACC_SIGN t2              -- 账户签约信息
      ON t1.ACC_SIGN_ID = t2.ACC_SIGN_ID
   WHERE t1.SIGN_TYPE IN ('131','132','133','134','135','136','137','138','3300','3301','3302','3303','3304','3305','3306',
'3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322',
'3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336',
'3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352',
'3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367',
'3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381',
'3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395',
'3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410',
'3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425',
'3426','3427','3428','3429','3430','3431','3433','3438','3439','3440','311',
'126','111','141','130','321','322','331','332','333','334','335','341','342','343','344','345','346','350','351');
  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '客户签约信息';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_dwd_prdkt_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_prdkt_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 产品信息加工过程
  -- 作业编号: PRC_DWD_PRDKT_INFO
  -- 处理周期: 日
  -- 过程描述: 
  -- 目标表: DWD_PRDKT_INFO
  -- author :
  -- date   : 2026-07-14
  -- 适配数据库: Oracle 兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC             VARCHAR(100) := '产品信息加工过程';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_PRDKT_INFO';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
begin
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_PRDKT_INFO';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_PRDKT_CATLOG';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_PRDKT_INFO_ZB';
  INSERT INTO DWD_PRDKT_INFO_ZB(
    persn_legal_bk_code, -- 法人行号
    data_date, -- 数据日期 
  	prdkt_id, --产品编号
  	prdkt_term, -- 存期
  	prdkt_ccy, -- 币种
  	prdkt_rate, -- 实际利率
  	prdkt_limit_amt, -- 起存金额
  	is_sell	--是否在售
  )
  SELECT '9999' ,-- 法人行号
  		V_SYSDAT,-- 数据日期 
  		'CBS_'||A.CHAPBHAO,--产品编号
  		C.CUNQIIII,-- 存期
  		A.HUOBDAIH,-- 币种
  		B.SHIJILVL,-- 实际利率
  		NVL(D.DCCRZXJE,0) DCCRZXJE, -- 起存金额
  		CASE WHEN E.CHAPZHUT='0' THEN '是' ELSE '否' END --是否在售
	FROM CBS_KDPF_LILVDY A  
	INNER JOIN (SELECT  * FROM (
	SELECT LILVDAMA,BIZHONGG,CUNQIIII,SHIJILVL,ROW_NUMBER() OVER(PARTITION BY A.LILVDAMA,A.BIZHONGG,A.CUNQIIII ORDER BY A.SHENGXRQ DESC) RN
	FROM CBS_KITP_SHIJLV A WHERE SHENGXRQ<=V_SYSDAT
	) B WHERE B.RN=1
	) B ON A.LILVBHAO=B.LILVDAMA AND A.HUOBDAIH=B.BIZHONGG
	INNER JOIN CBS_KDPF_CUNQKZ C ON A.CHAPBHAO=C.CHAPBHAO AND (A.HUOBDAIH=C.HUOBDAIH OR (C.HUOBDAIH='98' AND A.HUOBDAIH<>'01')) AND B.CUNQIIII=
		(CASE WHEN C.CUNQIIII='1Y' THEN'12M' WHEN C.CUNQIIII='2Y'  THEN'24M' WHEN C.CUNQIIII='3Y'  THEN'36M' WHEN C.CUNQIIII='5Y'  THEN'60M' ELSE C.CUNQIIII END)
	LEFT JOIN CBS_KDPF_CUNRKZ D ON A.CHAPBHAO=D.CHAPBHAO AND A.HUOBDAIH=D.HUOBDAIH 
	INNER JOIN CBS_KDPF_CHPSHX E ON A.CHAPBHAO=E.CHAPBHAO 
	WHERE A.FZLVLEIX='ZHENLXLV';
	COMMIT;
  --***************************************
  -- 2.1 -- 第1段：核心产品
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
 INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
 SELECT 'CBS_'||A.CHAPBHAO,  -- 产品编号
   A.CHANPSHM, -- 产品名称
   '1' PRDKT_CATE_BIG, -- 产品大类
   A.SHENXRIQ, -- 开始日期
   A.SHIXRIQI, -- 结束日期
   '1' PRDKT_LINE,-- 产品条线
   '' SUP_PRDKT_ID, -- 上级产品编号
   '' MDL_BIZ_RATE_FEE, -- 中间业务费率
   '' PRDKT_RATE, -- 产品利率
   'CBS' SYS_SRC,-- 系统来源
   CASE WHEN A.JILUZTAI='0' THEN '0' WHEN A.JILUZTAI='2' THEN '1' ELSE '2' END , -- 产品状态(在售/停售)
   A.FARENDMA  -- 法人行号
  FROM CBS_KDPF_CHPSHX A
 WHERE A.SUOSHUDX='1' AND A.CHAPBHAO NOT IN ('001021','001022');
   -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  --***************************************
  -- 2.2 -- 第2段：智能存款
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
 INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
 SELECT 'CDS_'||A.prod_code,  -- 产品编号
   A.prod_name, -- 产品名称
   '1' PRDKT_CATE_BIG, -- 产品大类
   A.sale_begin_date, -- 开始日期
   A.sale_end_date, -- 结束日期
   '1' PRDKT_LINE,-- 产品条线
   '' SUP_PRDKT_ID, -- 上级产品编号
   '' MDL_BIZ_RATE_FEE, -- 中间业务费率
   '' PRDKT_RATE, -- 产品利率
   'CDS' SYS_SRC,-- 系统来源
   CASE WHEN A.prod_status='1' THEN '0' WHEN a.prod_status='2' THEN '1' ELSE '2' END , -- 产品状态(在售/停售)
   '9999' FARENDMA  -- 法人行号
  FROM CDS_TB_PROD_PUB_INFO A;
   -- 记录第2段结束时间和耗时  
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
   --***************************************
  -- 2.3 -- 第3段：信贷产品
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
 SELECT 
	'CMS_'||TYPENO PRDKT_ID -- 产品编号
	,TYPENAME PRDKT_NAME -- 产品名称
	,'2' PRDKT_CATE_BIG-- 产品大类
	,'' BGN_DATE -- 开始日期
	,'' END_DATE -- 结束日期
	,'1' PRDKT_LINE -- 产品条线
	,'' SUP_PRDKT_ID -- 上级产品编号
	,'' MDL_BIZ_RATE_FEE -- 中间业务费率
	,'' PRDKT_RATE -- 产品利率
	,'CMS' SYS_SRC -- 系统来源
	,case WHEN a.isinuse='1' THEN '0' WHEN a.isinuse='2' THEN '1' ELSE '2' end PRDKT_STATE -- 产品状态(在售/停售)
	,'9999' PERSN_LEGAL_BK_CODE -- 法人行号
	FROM CMS_BUSINESS_TYPE  A
	WHERE A.TYPENO LIKE 'LI1%';
   -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  --***************************************
  -- 2.3.1 -- 第3.1段：嘉州村镇银行信贷产品
  --***************************************
  V_NO_ID := '3.1';
  V_BGN_DATE := SYSDATE;
   INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
 SELECT 
	'CMS_'||TYPENO PRDKT_ID -- 产品编号
	,TYPENAME PRDKT_NAME -- 产品名称
	,'2' PRDKT_CATE_BIG-- 产品大类
	,'' BGN_DATE -- 开始日期
	,'' END_DATE -- 结束日期
	,'1' PRDKT_LINE -- 产品条线
	,'' SUP_PRDKT_ID -- 上级产品编号
	,'' MDL_BIZ_RATE_FEE -- 中间业务费率
	,'' PRDKT_RATE -- 产品利率
	,'CMS' SYS_SRC -- 系统来源
	,case WHEN a.isinuse='1' THEN '0' WHEN a.isinuse='2' THEN '1' ELSE '2' END  PRDKT_STATE -- 产品状态(在售/停售)
	,'1500' PERSN_LEGAL_BK_CODE -- 法人行号
	FROM CMS_BUSINESS_TYPE  A
	WHERE A.TYPENO LIKE 'JI1%';
   -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.1段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3.1段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  --***************************************
  -- 2.3.2 -- 第3.2段：仁寿村镇银行信贷产品
  --***************************************
  V_NO_ID := '3.2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
 SELECT 
	'CMS_'||TYPENO PRDKT_ID -- 产品编号
	,TYPENAME PRDKT_NAME -- 产品名称
	,'2' PRDKT_CATE_BIG-- 产品大类
	,'' BGN_DATE -- 开始日期
	,'' END_DATE -- 结束日期
	,'1' PRDKT_LINE -- 产品条线
	,'' SUP_PRDKT_ID -- 上级产品编号
	,'' MDL_BIZ_RATE_FEE -- 中间业务费率
	,'' PRDKT_RATE -- 产品利率
	,'CMS' SYS_SRC -- 系统来源
	,case WHEN a.isinuse='1' THEN '0' WHEN a.isinuse='2' THEN '1' ELSE '2' end PRDKT_STATE -- 产品状态(在售/停售)
	,'1200' PERSN_LEGAL_BK_CODE -- 法人行号
	FROM CMS_BUSINESS_TYPE  A
	WHERE A.TYPENO LIKE 'RI1%';
   -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.2段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3.2段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  --***************************************
  -- 2.3.3 -- 第3.3段：蒲江村镇银行信贷产品
  --***************************************
  V_NO_ID := '3.3';
  V_BGN_DATE := SYSDATE;
   INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
 SELECT 
	'CMS_'||TYPENO PRDKT_ID -- 产品编号
	,TYPENAME PRDKT_NAME -- 产品名称
	,'2' PRDKT_CATE_BIG-- 产品大类
	,'' BGN_DATE -- 开始日期
	,'' END_DATE -- 结束日期
	,'1' PRDKT_LINE -- 产品条线
	,'' SUP_PRDKT_ID -- 上级产品编号
	,'' MDL_BIZ_RATE_FEE -- 中间业务费率
	,'' PRDKT_RATE -- 产品利率
	,'CMS' SYS_SRC -- 系统来源
	,case WHEN a.isinuse='1' THEN '0' WHEN a.isinuse='2' THEN '1' ELSE '2' end PRDKT_STATE -- 产品状态(在售/停售)
	,'1800' PERSN_LEGAL_BK_CODE -- 法人行号
	FROM CMS_BUSINESS_TYPE  A
	WHERE A.TYPENO LIKE 'PI1%';
   -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3.3段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3.2段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  --***************************************
  -- 2.4 -- 第4段：代销理财产品
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;
  INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
    SELECT 'FMS_'||A.prod_code PRDKT_ID -- 产品编号
		,A.PROD_NAME PRDKT_NAME -- 产品名称
		,'4' PRDKT_CATE_BIG -- 产品大类
		,A.VALUE_DATE BGN_DATE -- 开始日期
		,A.WINDING_DATE END_DATE -- 结束日期
		,'1' PRDKT_LINE -- 产品条线
		,'' SUP_PRDKT_ID -- 上级产品编号
		,'' MDL_BIZ_RATE_FEE -- 中间业务费率
		,A.PROD_RATE PRDKT_RATE -- 产品利率
		,'FMS' SYS_SRC -- 系统来源
		,CASE when a.SALE_STATUS='1' THEN '0' ELSE '1' END  PRDKT_STATE -- 产品状态(在售/停售)
		,A.LEGAL_CODE PERSN_LEGAL_BK_CODE -- 法人行号
      FROM FMS_TD_PROD_INFO A;
  COMMIT;
   -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  --***************************************
  -- 2.5 -- 第5段：自营理财产品
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;
  INSERT INTO DWD_PRDKT_INFO( 
		 PRDKT_ID -- 产品编号
		,PRDKT_NAME -- 产品名称
		,PRDKT_CATE_BIG -- 产品大类
		,BGN_DATE -- 开始日期
		,END_DATE -- 结束日期
		,PRDKT_LINE -- 产品条线
		,SUP_PRDKT_ID -- 上级产品编号
		,MDL_BIZ_RATE_FEE -- 中间业务费率
		,PRDKT_RATE -- 产品利率
		,SYS_SRC -- 系统来源
		,PRDKT_STATE -- 产品状态(在售/停售)
		,PERSN_LEGAL_BK_CODE -- 法人行号
	)
    SELECT 'FMS_'||A.prod_code PRDKT_ID -- 产品编号
		,A.PROD_NAME PRDKT_NAME -- 产品名称
		,'3' PRDKT_CATE_BIG -- 产品大类
		,C.VALUE_DATE BGN_DATE -- 开始日期
		,C.WINDING_DATE END_DATE -- 结束日期
		,'1' PRDKT_LINE -- 产品条线
		,'' SUP_PRDKT_ID -- 上级产品编号
		,'' MDL_BIZ_RATE_FEE -- 中间业务费率
		,D.SEVEN_DAYS_INCOME PRDKT_RATE -- 产品利率
		,'FMS' SYS_SRC -- 系统来源
		,CASE when a.SALE_STATUS='1' THEN '0' ELSE '1' END   PRDKT_STATE -- 产品状态(在售/停售)
		,A.LEGAL_CODE PERSN_LEGAL_BK_CODE -- 法人行号
      FROM FMS_T5_PROD_INFO A
      LEFT JOIN FMS_T5_PROD_PERIOD C ON A.PROD_CODE = C.PROD_CODE
