			,'PURCHASE_AUM' col_code --属性ID
			,'起购金额'col_name --属性名称
			,CASE WHEN c.is_part_buy='0' THEN  lowest_part*c.trialamt ELSE NVL(c.trialamt,0) END col_value --属性值
			,'' org_id -- 机构号	 
			,'9999' PERSN_LEGAL_BK_CODE --法人行号
	       FROM ybt_ybt_product_info A
	       LEFT JOIN YBT_YBT_INSURANCE_BASE_INFO c ON a."product_id" =c.insurance_id
	       LEFT JOIN dwd_prdkt_catlog b ON 'YBT_'||a.product_id = b.prdkt_catlog_id; 
	     
	    INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
		)
	   SELECT 
		     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
			,b.prdkt_catlog_path --产品目录
			,'INSUR_PAYTYPE' col_code --属性ID
			,'缴费方式'col_name --属性名称
			,'转账' col_value --属性值
			,'' org_id -- 机构号	 
			,'9999' PERSN_LEGAL_BK_CODE --法人行号
	       FROM ybt_ybt_product_info A
	       LEFT JOIN dwd_prdkt_catlog b ON 'YBT_'||a.product_id = b.prdkt_catlog_id;
	    
	   INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
		)
	   SELECT 
		     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
			,b.prdkt_catlog_path --产品目录
			,'IS_SELL' col_code --属性ID
			,'是否在售'col_name --属性名称
			,CASE when A.product_status='0' THEN '是' ELSE '否' END  col_value --属性值
			,'' org_id -- 机构号	 
			,'9999' PERSN_LEGAL_BK_CODE --法人行号
	       FROM ybt_ybt_product_info A
	       LEFT JOIN dwd_prdkt_catlog b ON 'YBT_'||a.product_id = b.prdkt_catlog_id;
       COMMIT;
  -- 记录第21段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第21段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;
  -- 调用日志过程,记录第16段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  --***************************************
  -- 2.22 -- 第22段：贷款产品属性
  --***************************************
  V_NO_ID := '22';
  V_BGN_DATE := SYSDATE;
  INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
	)
   SELECT 
	     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
		,b.prdkt_catlog_path --产品目录
		,'PRDKT_ID' col_code --属性ID
		,'产品编号'col_name --属性名称
		,a.typeno col_value --属性值
		,'' org_id -- 机构号	 
		,'9999' PERSN_LEGAL_BK_CODE --法人行号
       FROM cms_business_type A
       LEFT JOIN dwd_prdkt_catlog b ON 'CMS_'||a.typeno = b.prdkt_catlog_id;
  
    INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
	)
   SELECT 
	     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
		,b.prdkt_catlog_path --产品目录
		,'PRDKT_NAME' col_code --属性ID
		,'产品名称'col_name --属性名称
		,a.typename col_value --属性值
		,'' org_id -- 机构号	 
		,'9999' PERSN_LEGAL_BK_CODE --法人行号
       FROM cms_business_type A
       LEFT JOIN dwd_prdkt_catlog b ON 'CMS_'||a.typeno = b.prdkt_catlog_id;
     
     INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
	)
   SELECT 
	     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
		,b.prdkt_catlog_path --产品目录
		,'PRDKT_TYP' col_code --属性ID
		,'产品类型'col_name --属性名称
		,CASE WHEN A.TYPENO LIKE '%I1110%' and a.typeno not IN ('LI1110010','LI1110011','RI1110010','RI1110011','JI1110010','JI1110011','PI1110010','PI1110011') THEN '经营性贷款'
			  WHEN A.TYPENO LIKE '%I1120%' AND a.typeno not IN ('LI1120020','LI1120021', 'LI1120025', 'LI1120026', 'LI1120028','RI1120020','RI1120021', 'RI1120025', 'RI1120026', 'RI1120028','JI1120020','JI1120021', 'JI1120025', 'JI1120026', 'JI1120028','PI1120020','PI1120021', 'PI1120025', 'PI1120026', 'PI1120028') THEN '消费性贷款'
			  WHEN a.typeno IN ('LI1110010','LI1110011','RI1110010','RI1110011','JI1110010','JI1110011','PI1110010','PI1110011''LI1120020','LI1120021', 'LI1120025', 'LI1120026', 'LI1120028','RI1120020','RI1120021', 'RI1120025', 'RI1120026', 'RI1120028','JI1120020','JI1120021', 'JI1120025', 'JI1120026', 'JI1120028','PI1120020','PI1120021', 'PI1120025', 'PI1120026', 'PI1120028') THEN '住房贷款' END 
			  col_value --属性值
		,'' org_id -- 机构号	 
		,'9999' PERSN_LEGAL_BK_CODE --法人行号
       FROM cms_business_type A
       LEFT JOIN dwd_prdkt_catlog b ON 'CMS_'||a.typeno = b.prdkt_catlog_id;
     
       INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
	)
   SELECT 
	     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
		,b.prdkt_catlog_path --产品目录
		,'PRDKT_OBJ' col_code --属性ID
		,'产品对象'col_name --属性名称
		,'个人' col_value --属性值
		,'' org_id -- 机构号	 
		,'9999' PERSN_LEGAL_BK_CODE --法人行号
       FROM cms_business_type A
       LEFT JOIN dwd_prdkt_catlog b ON 'CMS_'||a.typeno = b.prdkt_catlog_id;
       
     INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
	)
   SELECT 
	     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
		,b.prdkt_catlog_path --产品目录
		,'GUARANT_MODE' col_code --属性ID
		,'可用担保方式'col_name --属性名称
		,c.vouchname col_value --属性值
		,'' org_id -- 机构号	 
		,'9999' PERSN_LEGAL_BK_CODE --法人行号
       FROM cms_business_type A
       LEFT JOIN (SELECT a.typeno ,a.vouchtypes ,string_agg(DISTINCT b.itemname,',') vouchname
			FROM cms_business_type a  CROSS JOIN LATERAL unnest(string_to_array(a.vouchtypes,',')) AS split_code 
			LEFT JOIN cms_code_library b ON b.codeno ='VouchType' AND b.itemno = LEFT(split_code,3)
			 GROUP BY a.typeno , a.vouchtypes)	c  ON a.typeno=c.typeno 
       LEFT JOIN dwd_prdkt_catlog b ON 'CMS_'||a.typeno = b.prdkt_catlog_id;
       
        INSERT INTO DWD_PRDKT_INFO_DETAIL( 
		 PK_ID --主键
		,prdkt_catlog_path --产品目录
		,col_code --属性ID
		,col_name --属性名称
		,col_value --属性值
		,org_id -- 机构号	 
		,PERSN_LEGAL_BK_CODE --法人行号
	)
   SELECT 
	     crmdm.seq_prdkt_info_detail.nextval AS PK_ID --主键
		,b.prdkt_catlog_path --产品目录
		,'MIN_RATE' col_code --属性ID
		,'最低利率定价'col_name --属性名称
		,a.rateleft col_value --属性值
		,'' org_id -- 机构号	 
		,'9999' PERSN_LEGAL_BK_CODE --法人行号
       FROM cms_business_type A
       LEFT JOIN dwd_prdkt_catlog b ON 'CMS_'||a.typeno = b.prdkt_catlog_id;
       COMMIT;
       
  -- 记录第22段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第22段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;
  -- 调用日志过程,记录第16段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  
  V_NO_ID := '23';
  V_BGN_DATE := SYSDATE;
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := 'end';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第17段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
  
  
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);
    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_dwd_salon_cust_dtl(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_salon_cust_dtl(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 统计三十天前参与正在进行的沙龙活动的客户
  -- 作业编号: PRC_DWD_SALON_CUST_DTL
  -- 处理周期: 每日
  -- 来源表: CRM.MKT_SALON_ACT_CUST_DTL 
     	     CRM.MKT_SALON_ACT
  -- 目标表: DWD_SALON_CUST_DTL
  --AUTHOR:张方涛
  --CREATE DATE: 20260821
  -- 适配数据库: Kingbase/Oracle兼容模式
  */
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '统计三十天前参与正在进行的沙龙活动的客户';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_DWD_SALON_CUST_DTL';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_30DAYS_AGO		VARCHAR(8);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_30DAYS_AGO :=TO_DATE(V_SYSDAT,'YYYY/MM/DD')-30;
  
  ------------------------------------------------------------------
  -- 1. 清空目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_SALON_CUST_DTL';
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 2. 统计三十天前参与正在进行的沙龙活动的客户
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO DWD_SALON_CUST_DTL(
   	  ACT_ID , -- 活动ID
	  CORE_CUST_ID -- 客户号
   )
	SELECT A.ACT_ID, A.CORE_CUST_ID  
      FROM CRM.MKT_SALON_ACT_CUST_DTL A 
     INNER JOIN CRM.MKT_SALON_ACT B
        ON A.ACT_ID = B.ACT_ID
     WHERE B.TIME_START_TIME >= V_30DAYS_AGO - (TO_DATE(B.TIME_END_TIME,'YYYY/MM/DD') - TO_DATE(B.TIME_START_TIME,'YYYY/MM/DD')) 
     	   /*统计三十天之内结束的沙龙活动,需统计活动开始时间大于等于三十天加上活动天数；例如某个沙龙活动20260725开始,20260730结束,
     	     则20260725~20260829(活动结束30天)时间段内均需统计该活动内的客户*/
       AND A.SIGN_IN_STAT = '1' --签到
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步三十天前参与正在进行的沙龙活动的客户统计数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dwd_sys_org(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_sys_org(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 报表名称: 机构表处理
  -- 报表编号: PRC_DWD_SYS_ORG
  -- 处理周期: 日
  -- 过程描述: 机构数据生成逻辑
  -- 来源表: kbrp_jgcshu(机构参数表), kbrp_jggxii(机构关系表)
  -- 目标表: DWD_SYS_ORG(机构表)
  -- author :
  -- date   : 2026-07-09
  -- 适配数据库: 人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR2(100) := '机构表处理';
  V_PRC_NAME             VARCHAR2(32)  := 'PRC_DWD_SYS_ORG';
  V_SYSDAT2              VARCHAR2(10);
  V_SQL                  VARCHAR2(4000);
  V_LOG_MSG              VARCHAR2(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR2(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR2(8);
  P_INTERVAL_END_DATE    VARCHAR2(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --***************************************
  -- 2.1 临时表1：基础数据
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_TMP_JIGOU_BASE';
  INSERT INTO DWD_TMP_JIGOU_BASE (
      JIGOUHAO,
      FARENDMA,
      FENHDAIM,
      JIGOLEIX,
      JIGOUZWM,
      DIZHIIII,
      YOUZHNBM,
      DIANHHMA,
      WEIHRIQI,
      WEIHSHIJ,
      JINGDUXX,
      WEIDUXXZ,
      YEWUGXJG,
      YEWUGXJB
  )
  SELECT
      c.JIGOUHAO, -- 营业机构号
      c.FARENDMA,
      c.FENHDAIM, -- 分行代码
      c.JIGOLEIX, -- 机构类型
      c.JIGOUZWM, -- 机构中文名称
      c.DIZHIIII, -- 地址
      c.YOUZHNBM, -- 邮政编码
      c.DIANHHMA, -- 电话号码
      c.WEIHRIQI,
      c.WEIHSHIJ,
      c.JINGDUXX, -- 经度
      c.WEIDUXXZ, -- 纬度
      CASE
          WHEN g.JIGOUHAO IS NOT NULL THEN g.YEWUGXJG
          WHEN c.FENHDAIM IS NOT NULL
               AND LPAD(c.FENHDAIM, 2, '0') || '0000' <> LPAD(c.JIGOUHAO, 6, '0')
               AND EXISTS (
                   SELECT 1
                     FROM CBS_kbrp_jgcshu f
                    WHERE f.FARENDMA = c.FARENDMA
                      AND f.JIGOUHAO = LPAD(c.FENHDAIM, 2, '0') || '0000'
               )
            THEN LPAD(c.FENHDAIM, 2, '0') || '0000'
          ELSE ''
      END AS YEWUGXJG, -- 业务关系机构；关系缺失时回退至存在的分行机构
      NVL(g.YEWUGXJB, 1) AS YEWUGXJB  -- 业务关系级别
    FROM CBS_kbrp_jgcshu c               -- 机构参数表
    LEFT JOIN cbs_kbrp_jggxii g          -- 机构关系表
      ON c.FARENDMA = g.FARENDMA
     AND c.JIGOUHAO = g.JIGOUHAO
  WHERE G.YEWUGXZL = 'BAOBSJ';

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.1 临时表1：基础数据';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 临时表2：机构编码与分类
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_TMP_JIGOU_CODE';
  INSERT INTO DWD_TMP_JIGOU_CODE (
      ORG_ID,
      SUP_ORG_ID,
      ORG_NAME,
      DIRECT_UNDER_ORG,
      ORG_TYP,
      ORG_ADDRS,
      ORG_STATE,
      DSPLY_SEQ,
      CREATR,
      CREAT_TIME,
      CREAT_ORG,
      PERSN_LEGAL_BK_CODE,
      HR_MS_ORG_ID,
      ORG_LGTUD,
      ORG_LATTUD,
      ORG_RSPONR,
      ORG_TEL
  )
  SELECT
      src.ORG_ID,
      src.SUP_ORG_ID,
      case when src.ORG_NAME = '乐山市商业银行' then '总行'
           else src.ORG_NAME end  as ORG_NAME,
      src.DIRECT_UNDER_ORG,
      src.ORG_TYP,
      src.ORG_ADDRS,
      src.ORG_STATE,
      src.DSPLY_SEQ,
      src.CREATR,
      src.CREAT_TIME,
      src.CREAT_ORG,
      src.PERSN_LEGAL_BK_CODE,
      src.HR_MS_ORG_ID,
      src.ORG_LGTUD,
      src.ORG_LATTUD,
      src.ORG_RSPONR,
      src.ORG_TEL
  FROM (
      SELECT
          LPAD(b.JIGOUHAO, 6, '0') AS ORG_ID,
          CASE
              WHEN b.JIGOUHAO = '000000' THEN '-1'
              WHEN b.JIGOUHAO IN ('120000', '150000', '180000') THEN '-1'
              WHEN b.YEWUGXJG = '000090' THEN '000000'
              WHEN b.YEWUGXJG = b.JIGOUHAO
                    AND b.JIGOUHAO IN ('010100', '010200', '010300', '010400', '010500', '010600', '010700', '010800', '010900', '011000', '011100', '012000')
                THEN LPAD(b.JIGOUHAO, 6, '0') || 'a'
              WHEN b.YEWUGXJG = b.JIGOUHAO THEN '000000'
              WHEN b.YEWUGXJG = '000095' THEN ''
              WHEN b.YEWUGXJG = '010000' THEN LPAD(b.JIGOUHAO, 6, '0') || 'a'
              ELSE NVL(LPAD(p.JIGOUHAO, 6, '0'), '')
          END AS SUP_ORG_ID,
          CASE
              WHEN b.YEWUGXJG = '010000' THEN
                  CASE
                      WHEN b.JIGOUZWM LIKE '%乐山市商业银行%' THEN
                          CASE
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%（汇总）' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '（汇总）', '') || '管理部'
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%支行' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '支行', '管理部')
                              ELSE REPLACE(b.JIGOUZWM, '乐山市商业银行', '') || '管理部'
                          END
                      ELSE b.JIGOUZWM || '管理部'
                  END
              WHEN b.YEWUGXJG = b.JIGOUHAO
                   AND b.JIGOUHAO IN ('010100', '010200', '010300', '010400', '010500', '010600', '010700', '010800', '010900', '011000', '011100', '012000')
                THEN
                  CASE
                      WHEN b.JIGOUZWM LIKE '%乐山市商业银行%' THEN
                          CASE
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%（汇总）' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '（汇总）', '') || '管理部'
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%支行' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '支行', '管理部')
                              ELSE REPLACE(b.JIGOUZWM, '乐山市商业银行', '') || '管理部'
                          END
                      ELSE b.JIGOUZWM || '管理部'
                  END
              ELSE b.JIGOUZWM
          END AS ORG_NAME,
          CASE
              WHEN LPAD(b.FENHDAIM, 2, '0') = '00' THEN ''
              WHEN LPAD(b.FENHDAIM, 2, '0') = '01' THEN '010000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '02' THEN '020000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '03' THEN '030000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '04' THEN '040000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '05' THEN '050000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '06' THEN '060000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '07' THEN '070000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '08' THEN '080000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '09' THEN '090000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '10' THEN '100000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '11' THEN '110000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '12' THEN '120000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '15' THEN '150000'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '18' THEN '180000'
              ELSE ''
          END AS DIRECT_UNDER_ORG,
          CASE
              WHEN b.JIGOUHAO = '000000' THEN '01'
              WHEN b.JIGOUZWM LIKE '%村镇银行%' THEN '07'
              WHEN b.JIGOUZWM LIKE '%汇总%' AND b.JIGOLEIX = '3' THEN '06'
              WHEN b.JIGOUZWM LIKE '%分行%' AND b.YEWUGXJB = 2 THEN '02'
              WHEN b.JIGOUZWM LIKE '%支行%' AND b.YEWUGXJB >= 3 AND b.JIGOLEIX = '2' THEN '03'
              WHEN b.JIGOUZWM LIKE '%营业部%' THEN '04'
              WHEN b.JIGOUZWM LIKE '%清算中心%' THEN '08'
              WHEN LPAD(b.FENHDAIM, 2, '0') = '00' AND (b.JIGOUZWM LIKE '%部%' OR b.JIGOUZWM LIKE '%办公室%') THEN '09'
              WHEN b.JIGOUZWM LIKE '%支行%' AND b.JIGOLEIX = '3' THEN '06'
              ELSE '05'
          END AS ORG_TYP,
          TRIM(
              NVL(b.DIZHIIII, '') ||
              CASE
                  WHEN b.YOUZHNBM IS NOT NULL THEN ' 邮编:' || TO_CHAR(b.YOUZHNBM)
                  ELSE ''
              END
          ) AS ORG_ADDRS,
          CASE
              WHEN b.JIGOUZWM LIKE '%撤并%' OR b.JIGOUZWM LIKE '%撤销%' THEN '0'
              WHEN b.JIGOUZWM LIKE '%测试%' THEN '2'
              ELSE '1'
          END AS ORG_STATE,
          TO_NUMBER(LPAD(b.JIGOUHAO, 6, '0')) AS DSPLY_SEQ,
          NULL AS CREATR,
          TRIM(
              CASE
                  WHEN b.WEIHRIQI IS NOT NULL THEN TO_CHAR(b.WEIHRIQI)
                  ELSE ''
              END ||
              CASE
                  WHEN b.WEIHSHIJ IS NOT NULL THEN ' ' || TO_CHAR(b.WEIHSHIJ)
                  ELSE ''
              END
          ) AS CREAT_TIME,
          NULL AS CREAT_ORG,
          TO_CHAR(b.FARENDMA) AS PERSN_LEGAL_BK_CODE,
          NULL AS HR_MS_ORG_ID,
          TO_CHAR(b.JINGDUXX) AS ORG_LGTUD,
          TO_CHAR(b.WEIDUXXZ) AS ORG_LATTUD,
          NULL AS ORG_RSPONR,
          b.DIANHHMA AS ORG_TEL
      FROM DWD_TMP_JIGOU_BASE b
      LEFT JOIN DWD_TMP_JIGOU_BASE p
        ON b.YEWUGXJG = p.JIGOUHAO
      WHERE NOT (
          LPAD(b.JIGOUHAO, 6, '0') IN ('000090', '000095', '010000', '001100', '002000', '002600')
          OR (
              NVL(b.JIGOUZWM, ' ') NOT LIKE '%营业部%'
              AND (NVL(b.JIGOUZWM, ' ') LIKE '%部%' OR NVL(b.JIGOUZWM, ' ') LIKE '%办公室%')
          )
      )

      UNION ALL

      SELECT
          LPAD(b.JIGOUHAO, 6, '0') || 'a' AS ORG_ID,
          '000000' AS SUP_ORG_ID,
          CASE
              WHEN b.JIGOUZWM LIKE '%乐山市商业银行%' THEN
                  CASE
                      WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%（汇总）' THEN
                          REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '（汇总）', '') || '管理部'
                      WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%支行' THEN
                          REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '支行', '管理部')
                      ELSE REPLACE(b.JIGOUZWM, '乐山市商业银行', '') || '管理部'
                  END
              ELSE b.JIGOUZWM || '管理部'
          END AS ORG_NAME,
          '000000' AS DIRECT_UNDER_ORG,
          '02' AS ORG_TYP,
          '' AS ORG_ADDRS,
          '1' AS ORG_STATE,
           TO_NUMBER(LPAD(b.JIGOUHAO, 6, '0')) AS DSPLY_SEQ,
          NULL AS CREATR,
          '' AS CREAT_TIME,
          NULL AS CREAT_ORG,
          NULL AS PERSN_LEGAL_BK_CODE,
          NULL AS HR_MS_ORG_ID,
          NULL AS ORG_LGTUD,
          NULL AS ORG_LATTUD,
          NULL AS ORG_RSPONR,
          NULL AS ORG_TEL
      FROM DWD_TMP_JIGOU_BASE b
      WHERE b.JIGOUHAO IN ('010100', '010200', '010300', '010400', '010500', '010600', '010700', '010800', '010900', '011000', '011100', '012000')
  ) src;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.2 临时表2：机构编码与分类';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 临时表3：机构路径
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_TMP_JIGOU_PATH';
  INSERT INTO DWD_TMP_JIGOU_PATH (
      ORG_ID,
      SUP_ORG_ID,
      ORG_PATH,
      ORG_HARCY
  )
  SELECT
      c.ORG_ID,
      c.SUP_ORG_ID,
      SYS_CONNECT_BY_PATH(c.ORG_ID, '/') || '/' AS ORG_PATH,
      TO_CHAR(LEVEL) AS ORG_HARCY
    FROM DWD_TMP_JIGOU_CODE c
   START WITH c.SUP_ORG_ID IS NULL
           OR c.SUP_ORG_ID = ''
           OR c.SUP_ORG_ID = '-1'
 CONNECT BY NOCYCLE PRIOR c.ORG_ID = c.SUP_ORG_ID;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.3 临时表3：机构路径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 汇总表落库
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_SYS_ORG';
  INSERT INTO DWD_SYS_ORG (
      ORG_ID,
      SUP_ORG_ID,
      ORG_PATH,
      ORG_NAME,
      SUP_ORG_NAME,
      DIRECT_UNDER_ORG,
      ORG_TYP,
      ORG_HARCY,
      ORG_ADDRS,
      ORG_STATE,
      DSPLY_SEQ,
      CREATR,
      CREAT_TIME,
      CREAT_ORG,
      PERSN_LEGAL_BK_CODE,
      HR_MS_ORG_ID,
      ORG_LGTUD,
      ORG_LATTUD,
      ORG_RSPONR,
      ORG_TEL
  )
  SELECT
      c.ORG_ID, -- 机构编号
      c.SUP_ORG_ID, -- 上级机构编号
      p.ORG_PATH, -- 机构路径
      REPLACE(c.ORG_NAME,'乐山市商业银行','') AS ORG_NAME, -- 机构名称
      REPLACE(s.ORG_NAME,'乐山市商业银行','') AS SUP_ORG_NAME, -- 上级机构名称
      c.DIRECT_UNDER_ORG, -- 直属机构
      c.ORG_TYP, -- 机构类型
      p.ORG_HARCY, -- 机构层级
      c.ORG_ADDRS, -- 机构地址
      c.ORG_STATE, -- 机构状态
      c.DSPLY_SEQ, -- 显示顺序
      c.CREATR, -- 创建人
      c.CREAT_TIME, -- 创建时间
      c.CREAT_ORG, -- 创建机构
      CASE WHEN ORG_PATH LIKE '/150000%' THEN '1500' 
      	   WHEN ORG_PATH LIKE '/120000%' THEN '1200'
      	   WHEN ORG_PATH LIKE '/180000%' THEN '1800'
      	   ELSE '9999' END as PERSN_LEGAL_BK_CODE, -- 法人行号
      c.HR_MS_ORG_ID, -- 人力资源系统机构号
      c.ORG_LGTUD, -- 机构经度
      c.ORG_LATTUD, -- 机构纬度
      c.ORG_RSPONR, -- 机构负责人
      c.ORG_TEL -- 机构电话
    FROM DWD_TMP_JIGOU_CODE c
    LEFT JOIN DWD_TMP_JIGOU_CODE s
      ON c.SUP_ORG_ID = s.ORG_ID
    LEFT JOIN DWD_TMP_JIGOU_PATH p
      ON c.ORG_ID = p.ORG_ID;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.4 汇总表落库';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  COMMIT;
    -- ***************************************
    -- 3. 异常处理区(捕获错误码并记录详细日志)
    -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60) END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    RAISE;
END







;

-- DROP PROCEDURE crmdm.prc_dwd_sys_org_20260720(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_sys_org_20260720(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 报表名称: 机构表处理
  -- 报表编号: PRC_DWD_SYS_ORG
  -- 处理周期: 日
  -- 过程描述: 机构数据生成逻辑
  -- 来源表: kbrp_jgcshu(机构参数表), kbrp_jggxii(机构关系表)
  -- 目标表: DWD_SYS_ORG(机构表)
  -- author :
  -- date   : 2026-07-09
  -- 适配数据库: 人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR2(100) := '机构表处理';
  V_PRC_NAME             VARCHAR2(32)  := 'PRC_DWD_SYS_ORG';
  V_SYSDAT2              VARCHAR2(10);
  V_SQL                  VARCHAR2(4000);
  V_LOG_MSG              VARCHAR2(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR2(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR2(8);
  P_INTERVAL_END_DATE    VARCHAR2(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  V_START_DT := SYSDATE;
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --***************************************
  -- 2.1 临时表1：基础数据
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_TMP_JIGOU_BASE';
  INSERT INTO DWD_TMP_JIGOU_BASE (
      JIGOUHAO,
      FARENDMA,
      FENHDAIM,
      JIGOLEIX,
      JIGOUZWM,
      DIZHIIII,
      YOUZHNBM,
      DIANHHMA,
      WEIHRIQI,
      WEIHSHIJ,
      JINGDUXX,
      WEIDUXXZ,
      YEWUGXJG,
      YEWUGXJB
  )
  SELECT
      c.JIGOUHAO, -- 营业机构号
      c.FARENDMA,
      c.FENHDAIM, -- 分行代码
      c.JIGOLEIX, -- 机构类型
      c.JIGOUZWM, -- 机构中文名称
      c.DIZHIIII, -- 地址
      c.YOUZHNBM, -- 邮政编码
      c.DIANHHMA, -- 电话号码
      c.WEIHRIQI,
      c.WEIHSHIJ,
      c.JINGDUXX, -- 经度
      c.WEIDUXXZ, -- 纬度
      NVL(g.YEWUGXJG, 0) AS YEWUGXJG, -- 业务关系机构
      NVL(g.YEWUGXJB, 1) AS YEWUGXJB  -- 业务关系级别
    FROM CBS_kbrp_jgcshu c               -- 机构参数表
    LEFT JOIN cbs_kbrp_jggxii g          -- 机构关系表
      ON c.JIGOUHAO = g.JIGOUHAO
  where YEWUGXZL = 'BAOBSJ';

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.1 临时表1：基础数据';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 临时表2：机构编码与分类
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_TMP_JIGOU_CODE';
  INSERT INTO DWD_TMP_JIGOU_CODE (
      ORG_ID,
      SUP_ORG_ID,
      ORG_NAME,
      DIRECT_UNDER_ORG,
      ORG_TYP,
      ORG_ADDRS,
      ORG_STATE,
      DSPLY_SEQ,
      CREATR,
      CREAT_TIME,
      CREAT_ORG,
      PERSN_LEGAL_BK_CODE,
      HR_MS_ORG_ID,
      ORG_LGTUD,
      ORG_LATTUD,
      ORG_RSPONR,
      ORG_TEL
  )
  SELECT
      src.ORG_ID,
      src.SUP_ORG_ID,
      src.ORG_NAME,
      src.DIRECT_UNDER_ORG,
      src.ORG_TYP,
      src.ORG_ADDRS,
      src.ORG_STATE,
      src.DSPLY_SEQ,
      src.CREATR,
      src.CREAT_TIME,
      src.CREAT_ORG,
      src.PERSN_LEGAL_BK_CODE,
      src.HR_MS_ORG_ID,
      src.ORG_LGTUD,
      src.ORG_LATTUD,
      src.ORG_RSPONR,
      src.ORG_TEL
  FROM (
      SELECT
          LPAD(TO_CHAR(b.JIGOUHAO), 6, '0') AS ORG_ID,
          CASE
              WHEN b.JIGOUHAO = 0 THEN '-1'
              WHEN b.JIGOUHAO IN (120000, 150000, 180000) THEN '-1'
              WHEN b.YEWUGXJG = 90 THEN '000000'
              WHEN b.YEWUGXJG = b.JIGOUHAO
                    AND b.JIGOUHAO IN (10100, 10200, 10300, 10400, 10500, 10600, 10700, 10800, 10900, 11000, 11100, 12000)
                THEN LPAD(TO_CHAR(b.JIGOUHAO), 6, '0') || 'a'
              WHEN b.YEWUGXJG = b.JIGOUHAO THEN '000000'
              WHEN b.YEWUGXJG = 95 THEN ''
              WHEN b.YEWUGXJG = 10000 THEN LPAD(TO_CHAR(b.JIGOUHAO), 6, '0') || 'a'
              ELSE NVL(LPAD(TO_CHAR(p.JIGOUHAO), 6, '0'), '')
          END AS SUP_ORG_ID,
          CASE
              WHEN b.YEWUGXJG = 10000 THEN
                  CASE
                      WHEN b.JIGOUZWM LIKE '%乐山市商业银行%' THEN
                          CASE
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%（汇总）' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '（汇总）', '') || '管理部'
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%支行' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '支行', '管理部')
                              ELSE REPLACE(b.JIGOUZWM, '乐山市商业银行', '') || '管理部'
                          END
                      ELSE b.JIGOUZWM || '管理部'
                  END
              WHEN b.YEWUGXJG = b.JIGOUHAO
                   AND b.JIGOUHAO IN (10100, 10200, 10300, 10400, 10500, 10600, 10700, 10800, 10900, 11000, 11100, 12000)
                THEN
                  CASE
                      WHEN b.JIGOUZWM LIKE '%乐山市商业银行%' THEN
                          CASE
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%（汇总）' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '（汇总）', '') || '管理部'
                              WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%支行' THEN
                                  REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '支行', '管理部')
                              ELSE REPLACE(b.JIGOUZWM, '乐山市商业银行', '') || '管理部'
                          END
                      ELSE b.JIGOUZWM || '管理部'
                  END
              ELSE b.JIGOUZWM
          END AS ORG_NAME,
          CASE
              WHEN b.FENHDAIM = 0 THEN ''
              WHEN b.FENHDAIM = 1 THEN '010000'
              WHEN b.FENHDAIM = 2 THEN '020000'
              WHEN b.FENHDAIM = 3 THEN '030000'
              WHEN b.FENHDAIM = 4 THEN '040000'
              WHEN b.FENHDAIM = 5 THEN '050000'
              WHEN b.FENHDAIM = 6 THEN '060000'
              WHEN b.FENHDAIM = 7 THEN '070000'
              WHEN b.FENHDAIM = 8 THEN '080000'
              WHEN b.FENHDAIM = 9 THEN '090000'
              WHEN b.FENHDAIM = 10 THEN '100000'
              WHEN b.FENHDAIM = 11 THEN '110000'
              WHEN b.FENHDAIM = 12 THEN '120000'
              WHEN b.FENHDAIM = 15 THEN '150000'
              WHEN b.FENHDAIM = 18 THEN '180000'
              ELSE ''
          END AS DIRECT_UNDER_ORG,
          CASE
              WHEN b.JIGOUHAO = 0 THEN '01'
              WHEN b.JIGOUZWM LIKE '%村镇银行%' THEN '07'
              WHEN b.JIGOUZWM LIKE '%汇总%' AND b.JIGOLEIX = 3 THEN '06'
              WHEN b.JIGOUZWM LIKE '%分行%' AND b.YEWUGXJB = 2 THEN '02'
              WHEN b.JIGOUZWM LIKE '%支行%' AND b.YEWUGXJB >= 3 AND b.JIGOLEIX = 2 THEN '03'
              WHEN b.JIGOUZWM LIKE '%营业部%' THEN '04'
              WHEN b.JIGOUZWM LIKE '%清算中心%' THEN '08'
              WHEN b.FENHDAIM = 0 AND (b.JIGOUZWM LIKE '%部%' OR b.JIGOUZWM LIKE '%办公室%') THEN '09'
              WHEN b.JIGOUZWM LIKE '%支行%' AND b.JIGOLEIX = 3 THEN '06'
              ELSE '05'
          END AS ORG_TYP,
          TRIM(
              NVL(b.DIZHIIII, '') ||
              CASE
                  WHEN b.YOUZHNBM IS NOT NULL THEN ' 邮编:' || TO_CHAR(b.YOUZHNBM)
                  ELSE ''
              END
          ) AS ORG_ADDRS,
          CASE
              WHEN b.JIGOUZWM LIKE '%撤并%' OR b.JIGOUZWM LIKE '%撤销%' THEN '0'
              WHEN b.JIGOUZWM LIKE '%测试%' THEN '2'
              ELSE '1'
          END AS ORG_STATE,
          TO_NUMBER(LPAD(TO_CHAR(b.JIGOUHAO), 6, '0')) AS DSPLY_SEQ,
          NULL AS CREATR,
          TRIM(
              CASE
                  WHEN b.WEIHRIQI IS NOT NULL THEN TO_CHAR(b.WEIHRIQI)
                  ELSE ''
              END ||
              CASE
                  WHEN b.WEIHSHIJ IS NOT NULL THEN ' ' || TO_CHAR(b.WEIHSHIJ)
                  ELSE ''
              END
          ) AS CREAT_TIME,
          NULL AS CREAT_ORG,
          TO_CHAR(b.FARENDMA) AS PERSN_LEGAL_BK_CODE,
          NULL AS HR_MS_ORG_ID,
          TO_CHAR(b.JINGDUXX) AS ORG_LGTUD,
          TO_CHAR(b.WEIDUXXZ) AS ORG_LATTUD,
          NULL AS ORG_RSPONR,
          b.DIANHHMA AS ORG_TEL
      FROM DWD_TMP_JIGOU_BASE b
      LEFT JOIN DWD_TMP_JIGOU_BASE p
        ON b.YEWUGXJG = p.JIGOUHAO
      WHERE NOT (
          LPAD(TO_CHAR(b.JIGOUHAO), 6, '0') IN ('000090', '000095', '010000', '001100', '002000', '002600')
          OR (
              NVL(b.JIGOUZWM, ' ') NOT LIKE '%营业部%'
              AND (NVL(b.JIGOUZWM, ' ') LIKE '%部%' OR NVL(b.JIGOUZWM, ' ') LIKE '%办公室%')
          )
      )

      UNION ALL

      SELECT
          LPAD(TO_CHAR(b.JIGOUHAO), 6, '0') || 'a' AS ORG_ID,
          '000000' AS SUP_ORG_ID,
          CASE
              WHEN b.JIGOUZWM LIKE '%乐山市商业银行%' THEN
                  CASE
                      WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%（汇总）' THEN
                          REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '（汇总）', '') || '管理部'
                      WHEN REPLACE(b.JIGOUZWM, '乐山市商业银行', '') LIKE '%支行' THEN
                          REPLACE(REPLACE(b.JIGOUZWM, '乐山市商业银行', ''), '支行', '管理部')
                      ELSE REPLACE(b.JIGOUZWM, '乐山市商业银行', '') || '管理部'
                  END
              ELSE b.JIGOUZWM || '管理部'
          END AS ORG_NAME,
          '000000' AS DIRECT_UNDER_ORG,
          '02' AS ORG_TYP,
          '' AS ORG_ADDRS,
          '1' AS ORG_STATE,
           TO_NUMBER(LPAD(TO_CHAR(b.JIGOUHAO), 6, '0')) AS DSPLY_SEQ,
          NULL AS CREATR,
          '' AS CREAT_TIME,
          NULL AS CREAT_ORG,
          NULL AS PERSN_LEGAL_BK_CODE,
          NULL AS HR_MS_ORG_ID,
          NULL AS ORG_LGTUD,
          NULL AS ORG_LATTUD,
          NULL AS ORG_RSPONR,
          NULL AS ORG_TEL
      FROM DWD_TMP_JIGOU_BASE b
      WHERE b.JIGOUHAO IN (10100, 10200, 10300, 10400, 10500, 10600, 10700, 10800, 10900, 11000, 11100, 12000)
  ) src;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.2 临时表2：机构编码与分类';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 临时表3：机构路径
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_TMP_JIGOU_PATH';
  INSERT INTO DWD_TMP_JIGOU_PATH (
      ORG_ID,
      SUP_ORG_ID,
      ORG_PATH,
      ORG_HARCY
  )
  SELECT
      c.ORG_ID,
      c.SUP_ORG_ID,
      SYS_CONNECT_BY_PATH(c.ORG_ID, '/') || '/' AS ORG_PATH,
      TO_CHAR(LEVEL) AS ORG_HARCY
    FROM DWD_TMP_JIGOU_CODE c
   START WITH c.SUP_ORG_ID IS NULL
           OR c.SUP_ORG_ID = ''
           OR c.SUP_ORG_ID = '-1'
 CONNECT BY NOCYCLE PRIOR c.ORG_ID = c.SUP_ORG_ID;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.3 临时表3：机构路径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 汇总表落库
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_SYS_ORG';
  INSERT INTO DWD_SYS_ORG (
      ORG_ID,
      SUP_ORG_ID,
      ORG_PATH,
      ORG_NAME,
      SUP_ORG_NAME,
      DIRECT_UNDER_ORG,
      ORG_TYP,
      ORG_HARCY,
      ORG_ADDRS,
      ORG_STATE,
      DSPLY_SEQ,
      CREATR,
      CREAT_TIME,
      CREAT_ORG,
      PERSN_LEGAL_BK_CODE,
      HR_MS_ORG_ID,
      ORG_LGTUD,
      ORG_LATTUD,
      ORG_RSPONR,
      ORG_TEL
  )
  SELECT
      c.ORG_ID, -- 机构编号
      c.SUP_ORG_ID, -- 上级机构编号
      p.ORG_PATH, -- 机构路径
      c.ORG_NAME, -- 机构名称
      s.ORG_NAME, -- 上级机构名称
      c.DIRECT_UNDER_ORG, -- 直属机构
      c.ORG_TYP, -- 机构类型
      p.ORG_HARCY, -- 机构层级
      c.ORG_ADDRS, -- 机构地址
      c.ORG_STATE, -- 机构状态
      c.DSPLY_SEQ, -- 显示顺序
      c.CREATR, -- 创建人
      c.CREAT_TIME, -- 创建时间
      c.CREAT_ORG, -- 创建机构
      CASE WHEN ORG_PATH LIKE '/150000%' THEN '1500' 
      	   WHEN ORG_PATH LIKE '/120000%' THEN '1200'
      	   WHEN ORG_PATH LIKE '/180000%' THEN '1800'
      	   ELSE '9999' END PERSN_LEGAL_BK_CODE, -- 法人行号
      c.HR_MS_ORG_ID, -- 人力资源系统机构号
      c.ORG_LGTUD, -- 机构经度
      c.ORG_LATTUD, -- 机构纬度
      c.ORG_RSPONR, -- 机构负责人
      c.ORG_TEL -- 机构电话
    FROM DWD_TMP_JIGOU_CODE c
    LEFT JOIN DWD_TMP_JIGOU_CODE s
      ON c.SUP_ORG_ID = s.ORG_ID
    LEFT JOIN DWD_TMP_JIGOU_PATH p
      ON c.ORG_ID = p.ORG_ID;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.4 汇总表落库';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

    --***************************************
  -- 2.5 汇总表b
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWD_SYS_ORG';
  INSERT INTO DWD_SYS_ORG (
      ORG_ID,
      SUP_ORG_ID,
      ORG_PATH,
      ORG_NAME,
      SUP_ORG_NAME,
      DIRECT_UNDER_ORG,
      ORG_TYP,
      ORG_HARCY,
      ORG_ADDRS,
      ORG_STATE,
      DSPLY_SEQ,
      CREATR,
      CREAT_TIME,
      CREAT_ORG,
      PERSN_LEGAL_BK_CODE,
      HR_MS_ORG_ID,
      ORG_LGTUD,
      ORG_LATTUD,
      ORG_RSPONR,
      ORG_TEL
  )
  SELECT
      c.ORG_ID, -- 机构编号
      c.SUP_ORG_ID, -- 上级机构编号
      p.ORG_PATH, -- 机构路径
      c.ORG_NAME, -- 机构名称
      s.ORG_NAME, -- 上级机构名称
      c.DIRECT_UNDER_ORG, -- 直属机构
      c.ORG_TYP, -- 机构类型
      p.ORG_HARCY, -- 机构层级
      c.ORG_ADDRS, -- 机构地址
      c.ORG_STATE, -- 机构状态
      c.DSPLY_SEQ, -- 显示顺序
      c.CREATR, -- 创建人
      c.CREAT_TIME, -- 创建时间
      c.CREAT_ORG, -- 创建机构
      c.PERSN_LEGAL_BK_CODE, -- 法人行号
      c.HR_MS_ORG_ID, -- 人力资源系统机构号
      c.ORG_LGTUD, -- 机构经度
      c.ORG_LATTUD, -- 机构纬度
      c.ORG_RSPONR, -- 机构负责人
      c.ORG_TEL -- 机构电话
    FROM DWD_TMP_JIGOU_CODE c
    LEFT JOIN DWD_TMP_JIGOU_CODE s
      ON c.SUP_ORG_ID = s.ORG_ID
    LEFT JOIN DWD_TMP_JIGOU_PATH p
      ON c.ORG_ID = p.ORG_ID;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '2.4 汇总表落库';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );
  COMMIT;
    -- ***************************************
    -- 3. 异常处理区(捕获错误码并记录详细日志)
    -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60) END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    RAISE;
END






;

-- DROP PROCEDURE crmdm.prc_dwd_tx_aset(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dwd_tx_aset(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 资产交易信息表
  -- 存储过程编号：PRC_DWD_TX_ASET
  -- 处理周期：日
  -- 过程描述：根据 DWD 数据模型映射生成
  -- 来源表：CBS_KDPA_ZHXINX(负债账户信息表)；CBS_KDPL_ZHMINX(账户余额发生明细)；DWD_CUST_INDV_INFO(客户基本信息表)
  -- 目标表：DWD_TX_ASET
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '资产交易信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWD_TX_ASET';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);

BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;


  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  DELETE FROM DWD_TX_ASET WHERE DATA_DATE = V_SYSDAT;

  --***************************************
  -- 2.1 -- 第1段处理开始：核心余额发生明细
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：核心余额发生明细
  INSERT INTO DWD_TX_ASET (
      DATA_DATE,
      SEQ_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CUST_TYP,
      CARD_NO,
      ACCT_ID,
      ACCT_BLNG_ORG,
      PRDKT_ID,
      TX_CHNL,
      TX_DATE,
      TX_TIME,
      CCY_CD,
      AMT,
      TX_ORG,
      OPRTR,
      LOAN_FLG,
      ACCT_BAL,
      TX_DSC,
      OPNT_ACCT,
      OPNT_ACCT_NAME_FST,
      OPNT_BK_KEEP,
      OPNT_NAME_BK,
      JIOYCFFS,
      XIANZZBZ,
      DUIFKHLX,
      CHONGZBZ
  )
  SELECT
         V_SYSDAT                  AS DATA_DATE            , -- 数据日期
         T1.ZHANGHAO||T1.MXIXUHAO  AS SEQ_ID               , -- 流水号
         CASE
           WHEN T1.JYYYJIGO LIKE '12%' THEN '1200'
           WHEN T1.JYYYJIGO LIKE '15%' THEN '1500'
           WHEN T1.JYYYJIGO LIKE '18%' THEN '1800'
           ELSE '9999'
         END AS PERSN_LEGAL_BK_CODE, -- 法人行号
         T2.KEHUHAOO               AS CUST_ID              , -- 客户编号
         T3.CUST_NAME              AS CUST_NAME            , -- 客户名称
         '1'                       AS CUST_TYP             , -- 客户类型
         T1.KEHUZHAO               AS CARD_NO              , -- 卡/折号
         T1.ZHANGHAO               AS ACCT_ID              , -- 账户
         T1.KAIHJIGO               AS ACCT_BLNG_ORG        , -- 账户归属机构
         T1.CHAPBHAO               AS PRDKT_ID             , -- 产品ID
         T1.QDAOLEIX               AS TX_CHNL              , -- 交易渠道
         T1.JIAOYIRQ               AS TX_DATE              , -- 交易日期
         T1.JIAOYISJ               AS TX_TIME              , -- 交易时间
         T1.JIAOYBIZ               AS CCY_CD               , -- 币种
         T1.JIAOYIJE               AS AMT                  , -- 发生额
         T1.JYYYJIGO               AS TX_ORG               , -- 交易机构
         T1.CAOZGUIY               AS OPRTR                , -- 经办人
         T1.JIEDAIBZ               AS LOAN_FLG             , -- 借贷标识
         T1.ZHANGHYE               AS ACCT_BAL             , -- 账户余额
         T1.BEIZHUUU               AS TX_DSC               , -- 交易说明
         T1.DUIFKHZH               AS OPNT_ACCT            , -- 对方账户
         T1.DUIFMINC               AS OPNT_ACCT_NAME_FST   , -- 对方户名
         T1.DUIFJGDM               AS OPNT_BK_KEEP         , -- 对方行
         T1.DUIFJGMC               AS OPNT_NAME_BK         , -- 对方行名
         T1.JIOYCFFS               AS JIOYCFFS             , -- 交易触发方式
         T1.XIANZZBZ               AS XIANZZBZ             , -- 现转标志
         T1.DUIFKHLX               AS DUIFKHLX             , -- 对方客户类型
         T1.CHONGZBZ               AS CHONGZBZ              -- 冲正标志
    FROM CBS_KDPL_ZHMINX T1 -- 账户余额发生明细
    LEFT JOIN CBS_KDPA_ZHXINX T2 -- 负债账户信息表
      ON T1.ZHANGHAO = T2.ZHANGHAO AND T1.KEHUZHAO = T2.KEHUZHAO
    LEFT JOIN DWD_CUST_INDV_INFO T3 -- 客户基本信息表
      ON T2.KEHUHAOO = T3.CUST_ID AND T3.PERSN_LEGAL_BK_CODE = '9999'
   WHERE T2.KEHUHAOO LIKE '1%' AND T1.JIAOYIRQ = V_SYSDAT; --AND T1.CHONGZBZ = '0' --要未冲正的数据

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：核心余额发生明细';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_asse_liab(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_asse_liab(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 报表名称: 客户资产负债处理
  -- 报表编号: PRC_DWS_CUST_ASSE_LIAB
  -- 处理周期: 日
  -- 来源表: DWS_CUST_ASSE_LIAB_CUMU / DWD_CUST_MAN / DWD_CUST_INDV_INFO / DWS_CUST_ASSE_LIAB_HIS
  -- 目标表: DWS_CUST_ASSE_LIAB / DWS_CUST_ASSE_LIAB_HIS
  -- 适配数据库: Kingbase/Oracle兼容模式
  -- 变更说明:
  -- 1. DWD_CUST_MAN(MNG_TYP='1') 归属机构永远优先
  -- 2. 仅非客户经理客户参与半年调配
  -- 3. 初始化、05-31、10-31 执行 60% 阈值调配
  -- 4. 非调配日回取最近一次半年调整结果
  ------------------------------------------------------------------
  V_PRC_DESC          VARCHAR(100) := '客户资产负债加工';
  V_PRC_NAME          VARCHAR(32)  := 'PRC_DWS_CUST_ASSE_LIAB';
  V_LOG_MSG           VARCHAR(4000);
  V_LOG_FLG           INTEGER;
  V_LOG_BUTTON        INTEGER := 1;
  V_NO_ID             VARCHAR(10);
  V_BGN_DATE          DATE;
  V_END_DATE          DATE;
  V_DURA_DATE         INTEGER;
  V_CURR_DATE         DATE;
  V_MMDD              VARCHAR(4);
  V_INIT_FLG          VARCHAR(1) := '0';
  V_REALLOC_FLG       VARCHAR(1) := '0';
  V_LAST_REALLOC_DATE VARCHAR(8);
BEGIN
  OUTCDE := 0;
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_MMDD := TO_CHAR(V_CURR_DATE, 'MMDD');

  ------------------------------------------------------------------
  -- 0. 判断是否执行半年调配,并计算最近一次半年调配日期
  ------------------------------------------------------------------
  IF V_INIT_FLG = '1' THEN
    V_REALLOC_FLG := '1';
  ELSIF V_MMDD IN ('0531', '1031') THEN
    V_REALLOC_FLG := '1';
  ELSE
    V_REALLOC_FLG := '0';
  END IF;

  IF V_MMDD >= '0601' AND V_MMDD <= '1030' THEN
    V_LAST_REALLOC_DATE := SUBSTR(V_SYSDAT, 1, 4) || '0531';
  ELSIF V_MMDD >= '1101' THEN
    V_LAST_REALLOC_DATE := SUBSTR(V_SYSDAT, 1, 4) || '1031';
  ELSE
    V_LAST_REALLOC_DATE := TO_CHAR(ADD_MONTHS(V_CURR_DATE, -12), 'YYYY') || '1031';
  END IF;

  ------------------------------------------------------------------
  -- 1. 客户机构维度汇总
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TMP1_DWS_CUST_ASSE_LIAB';
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  EXECUTE IMMEDIATE q'~
CREATE TABLE TMP1_DWS_CUST_ASSE_LIAB AS
SELECT
    T.DATA_DATE,                                                              -- 数据日期
    T.CUST_ID,                                                                -- 客户编号
    T.OPRT_ORG AS ORG_ID,                                                     -- 机构编号
    T.PERSN_LEGAL_BK_CODE,                                                    -- 法人行号
    SUM(CASE WHEN T.PRDKT_TYP IN ('1', '3', '4') THEN NVL(T.BAL, 0) ELSE 0 END) AS AUM_BAL_1,              -- AUM余额
    SUM(CASE WHEN T.PRDKT_TYP = '1' THEN NVL(T.BAL, 0) ELSE 0 END) AS DEPO_BAL_1,                           -- 存款余额
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '01' THEN NVL(T.BAL, 0) ELSE 0 END) AS DEPO_CURNT_DEPO_BAL_1, -- 活期余额
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG IN ('02', '04') THEN NVL(T.BAL, 0) ELSE 0 END) AS FIXD_DEPO_BAL_1, -- 定期余额
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '03' THEN NVL(T.BAL, 0) ELSE 0 END) AS LEHUI_BAL_1, -- 乐惠存余额
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '05' THEN NVL(T.BAL, 0) ELSE 0 END) AS LARGEDP_BAL_1, -- 大额存单余额
    SUM(CASE WHEN T.PRDKT_TYP = '3' THEN NVL(T.BAL, 0) ELSE 0 END) AS FIN_BAL_1,                             -- 理财余额
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '2' THEN NVL(T.BAL, 0) ELSE 0 END) AS CLOSE_AGEN_FIN_BAL_1, -- 代销封闭式理财余额
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '1' THEN NVL(T.BAL, 0) ELSE 0 END) AS OPEN_AGEN_FIN_BAL_1,  -- 代销开放式理财余额
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '4' THEN NVL(T.BAL, 0) ELSE 0 END) AS CLOSE_SELF_FIN_BAL_1, -- 自营封闭式理财余额
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '3' THEN NVL(T.BAL, 0) ELSE 0 END) AS OPEN_SELF_FIN_BAL_1,  -- 自营开放式理财余额
    SUM(CASE WHEN T.PRDKT_TYP = '4' THEN NVL(T.BAL, 0) ELSE 0 END) AS INSUR_BAL_1,                           -- 保险余额
    SUM(CASE WHEN T.PRDKT_TYP = '2' THEN NVL(T.BAL, 0) ELSE 0 END) AS LOAN_BAL_1,                            -- 贷款余额
    SUM(CASE WHEN T.PRDKT_TYP IN ('1', '3', '4') THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS AUM_BAL_2, -- AUM月日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS DEPO_BAL_2,              -- 存款月日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '01' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS DEPO_CURNT_DEPO_BAL_2, -- 活期月日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG IN ('02', '04') THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS FIXD_DEPO_BAL_2, -- 定期月日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '03' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS LEHUI_BAL_2, -- 乐惠存月日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '05' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS LARGEDP_BAL_2, -- 大额存单月日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS FIN_BAL_2,               -- 理财月日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '2' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS CLOSE_AGEN_FIN_BAL_2, -- 代销封闭式理财月日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '1' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS OPEN_AGEN_FIN_BAL_2,  -- 代销开放式理财月日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '4' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS CLOSE_SELF_FIN_BAL_2, -- 自营封闭式理财月日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '3' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS OPEN_SELF_FIN_BAL_2,  -- 自营开放式理财月日均
    SUM(CASE WHEN T.PRDKT_TYP = '4' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS INSUR_BAL_2,             -- 保险月日均
    SUM(CASE WHEN T.PRDKT_TYP = '2' THEN NVL(T.MTH_BAL, 0) / NULLIF(NVL(T.MTH_DAYS, 0), 0) ELSE 0 END) AS LOAN_BAL_2,              -- 贷款月日均
    SUM(CASE WHEN T.PRDKT_TYP IN ('1', '3', '4') THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS AUM_BAL_3,  -- AUM季日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS DEPO_BAL_3,              -- 存款季日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '01' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS DEPO_CURNT_DEPO_BAL_3, -- 活期季日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG IN ('02', '04') THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS FIXD_DEPO_BAL_3, -- 定期季日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '03' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS LEHUI_BAL_3, -- 乐惠存季日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '05' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS LARGEDP_BAL_3, -- 大额存单季日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS FIN_BAL_3,               -- 理财季日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '2' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS CLOSE_AGEN_FIN_BAL_3, -- 代销封闭式理财季日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '1' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS OPEN_AGEN_FIN_BAL_3,  -- 代销开放式理财季日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '4' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS CLOSE_SELF_FIN_BAL_3, -- 自营封闭式理财季日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '3' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS OPEN_SELF_FIN_BAL_3,  -- 自营开放式理财季日均
    SUM(CASE WHEN T.PRDKT_TYP = '4' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS INSUR_BAL_3,             -- 保险季日均
    SUM(CASE WHEN T.PRDKT_TYP = '2' THEN NVL(T.QRT_BAL, 0) / NULLIF(NVL(T.QRT_DAYS, 0), 0) ELSE 0 END) AS LOAN_BAL_3,              -- 贷款季日均
    SUM(CASE WHEN T.PRDKT_TYP IN ('1', '3', '4') THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS AUM_BAL_4,  -- AUM年日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS DEPO_BAL_4,              -- 存款年日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '01' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS DEPO_CURNT_DEPO_BAL_4, -- 活期年日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG IN ('02', '04') THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS FIXD_DEPO_BAL_4, -- 定期年日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '03' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS LEHUI_BAL_4, -- 乐惠存年日均
    SUM(CASE WHEN T.PRDKT_TYP = '1' AND T.PRDKT_CATE_BIG = '05' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS LARGEDP_BAL_4, -- 大额存单年日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS FIN_BAL_4,               -- 理财年日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '2' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS CLOSE_AGEN_FIN_BAL_4, -- 代销封闭式理财年日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '1' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS OPEN_AGEN_FIN_BAL_4,  -- 代销开放式理财年日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '4' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS CLOSE_SELF_FIN_BAL_4, -- 自营封闭式理财年日均
    SUM(CASE WHEN T.PRDKT_TYP = '3' AND T.PRDKT_CATE_BIG = '3' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS OPEN_SELF_FIN_BAL_4,  -- 自营开放式理财年日均
    SUM(CASE WHEN T.PRDKT_TYP = '4' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS INSUR_BAL_4,             -- 保险年日均
    SUM(CASE WHEN T.PRDKT_TYP = '2' THEN NVL(T.YAR_BAL, 0) / NULLIF(NVL(T.YAR_DAYS, 0), 0) ELSE 0 END) AS LOAN_BAL_4               -- 贷款年日均
FROM DWS_CUST_ASSE_LIAB_CUMU T
WHERE T.DATA_DATE = '~' || V_SYSDAT || q'~'
  AND T.OPRT_ORG IS NOT NULL
GROUP BY T.DATA_DATE, T.CUST_ID, T.OPRT_ORG, T.PERSN_LEGAL_BK_CODE
~';

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步客户机构汇总临时表生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 2. 客户默认归属机构临时表
  -- 用于兜底:
  -- 1. 月日均AUM最大机构
  -- 2. 月日均贷款最大机构
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TMP2_DWS_CUST_ASSE_LIAB';
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  EXECUTE IMMEDIATE q'~
CREATE TABLE TMP2_DWS_CUST_ASSE_LIAB AS
SELECT
    T.DATA_DATE,                                                              -- 数据日期
    T.CUST_ID,                                                                -- 客户编号
    T.PERSN_LEGAL_BK_CODE,                                                    -- 法人行号
    MAX(CASE WHEN T.RN_AUM = 1 THEN T.ORG_ID END) AS ORG_ID,                  -- 默认归属机构
    MAX(CASE WHEN T.RN_LOAN = 1 THEN T.ORG_ID END) AS ORG_ID_LOAN             -- 默认信贷归属机构
FROM (
    SELECT
        S.*,
        ROW_NUMBER() OVER (
            PARTITION BY S.DATA_DATE, S.CUST_ID, S.PERSN_LEGAL_BK_CODE
            ORDER BY NVL(S.AUM_BAL_2, 0) DESC, S.ORG_ID
        ) AS RN_AUM,
        ROW_NUMBER() OVER (
            PARTITION BY S.DATA_DATE, S.CUST_ID, S.PERSN_LEGAL_BK_CODE
            ORDER BY NVL(S.LOAN_BAL_2, 0) DESC, S.ORG_ID
        ) AS RN_LOAN
    FROM TMP1_DWS_CUST_ASSE_LIAB S
) T
GROUP BY T.DATA_DATE, T.CUST_ID, T.PERSN_LEGAL_BK_CODE
~';

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步客户默认归属机构临时表生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 3. 半年调配归属机构临时表
  -- 仅针对不在 DWD_CUST_MAN(MNG_TYP='1') 的客户
  ------------------------------------------------------------------
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TMP4_DWS_CUST_ASSE_REALLOC';
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  IF V_REALLOC_FLG = '1' THEN
    EXECUTE IMMEDIATE q'~
CREATE TABLE TMP4_DWS_CUST_ASSE_REALLOC AS
WITH BASE_CUST AS (
    SELECT
        T.DATA_DATE,                                                            -- 数据日期
        T.PERSN_LEGAL_BK_CODE,                                                  -- 法人行号
        T.CUST_ID,                                                              -- 客户编号
        T.ORG_ID,                                                               -- 机构编号
        NVL(T.AUM_BAL_2, 0) AS ORG_AUM_BAL_2                                    -- 机构金融资产月日均
    FROM TMP1_DWS_CUST_ASSE_LIAB T
    WHERE NOT EXISTS (
        SELECT 1
        FROM DWD_CUST_MAN M
        WHERE M.PERSN_LEGAL_BK_CODE = T.PERSN_LEGAL_BK_CODE
          AND M.CUST_ID = T.CUST_ID
          AND M.MNG_TYP = '1'
    )
),
CUST_AUM AS (
    SELECT
        DATA_DATE,                                                              -- 数据日期
        PERSN_LEGAL_BK_CODE,                                                    -- 法人行号
        CUST_ID,                                                                -- 客户编号
        SUM(ORG_AUM_BAL_2) AS CUST_AUM_BAL_2                                    -- 客户总金融资产月日均
    FROM BASE_CUST
    GROUP BY DATA_DATE, PERSN_LEGAL_BK_CODE, CUST_ID
),
HIT_ORG AS (
    SELECT
        B.DATA_DATE,                                                            -- 数据日期
        B.PERSN_LEGAL_BK_CODE,                                                  -- 法人行号
        B.CUST_ID,                                                              -- 客户编号
        B.ORG_ID,                                                               -- 命中调配机构
        CASE
            WHEN NVL(C.CUST_AUM_BAL_2, 0) = 0 THEN 0
            ELSE B.ORG_AUM_BAL_2 / C.CUST_AUM_BAL_2
        END AS REALLOC_RATE,                                                    -- 机构月日均占客户总月日均比例
        ROW_NUMBER() OVER (
            PARTITION BY B.DATA_DATE, B.PERSN_LEGAL_BK_CODE, B.CUST_ID
            ORDER BY DBMS_RANDOM.VALUE
        ) AS RN                                                                 -- 并列时随机排序序号
    FROM BASE_CUST B
    INNER JOIN CUST_AUM C
      ON B.DATA_DATE = C.DATA_DATE
     AND B.PERSN_LEGAL_BK_CODE = C.PERSN_LEGAL_BK_CODE
     AND B.CUST_ID = C.CUST_ID
    WHERE NVL(C.CUST_AUM_BAL_2, 0) > 0
      AND B.ORG_AUM_BAL_2 / C.CUST_AUM_BAL_2 >= 0.6
),
FALLBACK_ORG AS (
    SELECT
        C.DATA_DATE,                                                            -- 数据日期
        C.PERSN_LEGAL_BK_CODE,                                                  -- 法人行号
        C.CUST_ID,                                                              -- 客户编号
        I.OPEN_ORG AS REALLOC_ORG_ID,                                           -- 开户机构
        0 AS REALLOC_RATE,                                                      -- 未命中阈值时占比固定为0
        '2' AS RULE_FLG                                                         -- 规则标识 2-回退开户机构
    FROM CUST_AUM C
    LEFT JOIN DWD_CUST_INDV_INFO I
      ON C.PERSN_LEGAL_BK_CODE = I.PERSN_LEGAL_BK_CODE
     AND C.CUST_ID = I.CUST_ID
    WHERE NOT EXISTS (
        SELECT 1
        FROM HIT_ORG H
        WHERE H.DATA_DATE = C.DATA_DATE
          AND H.PERSN_LEGAL_BK_CODE = C.PERSN_LEGAL_BK_CODE
          AND H.CUST_ID = C.CUST_ID
    )
)
SELECT
    H.DATA_DATE,                                                                -- 数据日期
    H.PERSN_LEGAL_BK_CODE,                                                      -- 法人行号
    H.CUST_ID,                                                                  -- 客户编号
    H.ORG_ID AS REALLOC_ORG_ID,                                                 -- 调配后归属机构
    H.REALLOC_RATE,                                                             -- 调配命中占比
    '1' AS RULE_FLG                                                             -- 规则标识 1-命中60%阈值
FROM HIT_ORG H
WHERE H.RN = 1
UNION ALL
SELECT
    F.DATA_DATE,                                                                -- 数据日期
    F.PERSN_LEGAL_BK_CODE,                                                      -- 法人行号
    F.CUST_ID,                                                                  -- 客户编号
    F.REALLOC_ORG_ID,                                                           -- 回退后归属机构
    F.REALLOC_RATE,                                                             -- 占比
    F.RULE_FLG                                                                  -- 规则标识
FROM FALLBACK_ORG F
~';
  ELSE
    EXECUTE IMMEDIATE q'~
CREATE TABLE TMP4_DWS_CUST_ASSE_REALLOC AS
SELECT
    CAST(NULL AS VARCHAR(8)) AS DATA_DATE,                                      -- 数据日期
    CAST(NULL AS VARCHAR(10)) AS PERSN_LEGAL_BK_CODE,                           -- 法人行号
    CAST(NULL AS VARCHAR(50)) AS CUST_ID,                                       -- 客户编号
    CAST(NULL AS VARCHAR(20)) AS REALLOC_ORG_ID,                                -- 调配后归属机构
    CAST(NULL AS NUMBER(18,6)) AS REALLOC_RATE,                                 -- 调配命中占比
    CAST(NULL AS VARCHAR(1)) AS RULE_FLG                                        -- 规则标识
FROM DUAL
WHERE 1 = 0
~';
  END IF;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3步半年调配归属机构临时表生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 4. 非调配日最近一次半年调整结果临时表
  -- 仅针对不在 DWD_CUST_MAN(MNG_TYP='1') 的客户
  ------------------------------------------------------------------
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TMP5_DWS_CUST_ASSE_LAST_REALLOC';
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  IF V_REALLOC_FLG = '0' THEN
    EXECUTE IMMEDIATE q'~
CREATE TABLE TMP5_DWS_CUST_ASSE_LAST_REALLOC AS
SELECT
    H.PERSN_LEGAL_BK_CODE,                                                      -- 法人行号
    H.CUST_ID,                                                                  -- 客户编号
    H.ORG_ID AS LAST_REALLOC_ORG_ID,                                            -- 最近一次半年调整归属机构
    H.DATA_DATE AS LAST_REALLOC_DATE                                            -- 最近一次半年调整日期
FROM (
    SELECT
        H0.*,
        ROW_NUMBER() OVER (
            PARTITION BY H0.PERSN_LEGAL_BK_CODE, H0.CUST_ID
            ORDER BY H0.DATA_DATE DESC
        ) AS RN
    FROM DWS_CUST_ASSE_LIAB_HIS H0
    WHERE H0.DATA_DATE = '~' || V_LAST_REALLOC_DATE || q'~'
      AND H0.BAL_TYPE = '2'
      AND NOT EXISTS (
          SELECT 1
          FROM DWD_CUST_MAN M
          WHERE M.PERSN_LEGAL_BK_CODE = H0.PERSN_LEGAL_BK_CODE
            AND M.CUST_ID = H0.CUST_ID
            AND M.MNG_TYP = '1'
      )
) H
WHERE H.RN = 1
~';
  ELSE
    EXECUTE IMMEDIATE q'~
CREATE TABLE TMP5_DWS_CUST_ASSE_LAST_REALLOC AS
SELECT
    CAST(NULL AS VARCHAR(10)) AS PERSN_LEGAL_BK_CODE,                           -- 法人行号
    CAST(NULL AS VARCHAR(50)) AS CUST_ID,                                       -- 客户编号
    CAST(NULL AS VARCHAR(20)) AS LAST_REALLOC_ORG_ID,                           -- 最近一次半年调整归属机构
    CAST(NULL AS VARCHAR(8)) AS LAST_REALLOC_DATE                               -- 最近一次半年调整日期
FROM DUAL
WHERE 1 = 0
~';
  END IF;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4步最近一次半年调整归属机构临时表生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 5. 生成客户汇总结果
  ------------------------------------------------------------------
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP3_DWS_CUST_ASSE_LIAB';

  INSERT INTO TMP3_DWS_CUST_ASSE_LIAB (
      DATA_DATE,                                                                  -- 数据日期
      CUST_ID,                                                                    -- 客户编号
      BAL_TYPE,                                                                   -- 余额类型
      AUM_BAL,                                                                    -- AUM余额/均值
      DEPO_BAL,                                                                   -- 存款余额/均值
      DEPO_CURNT_DEPO_BAL,                                                        -- 活期存款余额/均值
      FIXD_DEPO_BAL,                                                              -- 定期存款余额/均值
      LEHUI_BAL,                                                                  -- 乐惠存余额/均值
      LARGEDP_BAL,                                                                -- 大额存单余额/均值
      FIN_BAL,                                                                    -- 理财余额/均值
      CLOSE_AGEN_FIN_BAL,                                                         -- 代销封闭式理财余额/均值
      OPEN_AGEN_FIN_BAL,                                                          -- 代销开放式理财余额/均值
      CLOSE_SELF_FIN_BAL,                                                         -- 自营封闭式理财余额/均值
      OPEN_SELF_FIN_BAL,                                                          -- 自营开放式理财余额/均值
      INSUR_BAL,                                                                  -- 保险余额/均值
      LOAN_BAL,                                                                   -- 贷款余额/均值
      PERSN_LEGAL_BK_CODE                                                         -- 法人行号
  )
  SELECT DATA_DATE, CUST_ID, '1',
         SUM(AUM_BAL_1), SUM(DEPO_BAL_1), SUM(DEPO_CURNT_DEPO_BAL_1),
         SUM(FIXD_DEPO_BAL_1), SUM(LEHUI_BAL_1), SUM(LARGEDP_BAL_1), SUM(FIN_BAL_1),
         SUM(CLOSE_AGEN_FIN_BAL_1), SUM(OPEN_AGEN_FIN_BAL_1), SUM(CLOSE_SELF_FIN_BAL_1),
         SUM(OPEN_SELF_FIN_BAL_1), SUM(INSUR_BAL_1), SUM(LOAN_BAL_1), PERSN_LEGAL_BK_CODE
    FROM TMP1_DWS_CUST_ASSE_LIAB
   GROUP BY DATA_DATE, CUST_ID, PERSN_LEGAL_BK_CODE
  UNION ALL
  SELECT DATA_DATE, CUST_ID, '2',
         SUM(AUM_BAL_2), SUM(DEPO_BAL_2), SUM(DEPO_CURNT_DEPO_BAL_2),
         SUM(FIXD_DEPO_BAL_2), SUM(LEHUI_BAL_2), SUM(LARGEDP_BAL_2), SUM(FIN_BAL_2),
         SUM(CLOSE_AGEN_FIN_BAL_2), SUM(OPEN_AGEN_FIN_BAL_2), SUM(CLOSE_SELF_FIN_BAL_2),
         SUM(OPEN_SELF_FIN_BAL_2), SUM(INSUR_BAL_2), SUM(LOAN_BAL_2), PERSN_LEGAL_BK_CODE
    FROM TMP1_DWS_CUST_ASSE_LIAB
   GROUP BY DATA_DATE, CUST_ID, PERSN_LEGAL_BK_CODE
  UNION ALL
  SELECT DATA_DATE, CUST_ID, '3',
         SUM(AUM_BAL_3), SUM(DEPO_BAL_3), SUM(DEPO_CURNT_DEPO_BAL_3),
         SUM(FIXD_DEPO_BAL_3), SUM(LEHUI_BAL_3), SUM(LARGEDP_BAL_3), SUM(FIN_BAL_3),
         SUM(CLOSE_AGEN_FIN_BAL_3), SUM(OPEN_AGEN_FIN_BAL_3), SUM(CLOSE_SELF_FIN_BAL_3),
         SUM(OPEN_SELF_FIN_BAL_3), SUM(INSUR_BAL_3), SUM(LOAN_BAL_3), PERSN_LEGAL_BK_CODE
    FROM TMP1_DWS_CUST_ASSE_LIAB
   GROUP BY DATA_DATE, CUST_ID, PERSN_LEGAL_BK_CODE
  UNION ALL
  SELECT DATA_DATE, CUST_ID, '4',
         SUM(AUM_BAL_4), SUM(DEPO_BAL_4), SUM(DEPO_CURNT_DEPO_BAL_4),
         SUM(FIXD_DEPO_BAL_4), SUM(LEHUI_BAL_4), SUM(LARGEDP_BAL_4), SUM(FIN_BAL_4),
         SUM(CLOSE_AGEN_FIN_BAL_4), SUM(OPEN_AGEN_FIN_BAL_4), SUM(CLOSE_SELF_FIN_BAL_4),
         SUM(OPEN_SELF_FIN_BAL_4), SUM(INSUR_BAL_4), SUM(LOAN_BAL_4), PERSN_LEGAL_BK_CODE
    FROM TMP1_DWS_CUST_ASSE_LIAB
   GROUP BY DATA_DATE, CUST_ID, PERSN_LEGAL_BK_CODE;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5步客户汇总结果临时表生成完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 6. 装载目标表
  -- ORG_ID 优先级:
  -- 1. DWD_CUST_MAN(MNG_TYP='1').ORG_ID
  -- 2. 当前调配结果
  -- 3. 最近一次半年调配结果
  -- 4. 原默认归属机构
  ------------------------------------------------------------------
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_CUST_ASSE_LIAB';

  INSERT INTO DWS_CUST_ASSE_LIAB (
      DATA_DATE,                                                                    -- 数据日期
      CUST_ID,                                                                      -- 客户编号
      ORG_ID,                                                                       -- 归属机构
      ORG_ID_LOAN,                                                                  -- 信贷归属机构
      BAL_TYPE,                                                                     -- 余额类型
      AUM_BAL,                                                                      -- AUM余额/均值
      DEPO_BAL,                                                                     -- 存款余额/均值
      DEPO_CURNT_DEPO_BAL,                                                          -- 活期存款余额/均值
      FIXD_DEPO_BAL,                                                                -- 定期存款余额/均值
      LEHUI_BAL,                                                                    -- 乐惠存余额/均值
      LARGEDP_BAL,                                                                  -- 大额存单余额/均值
      FIN_BAL,                                                                      -- 理财余额/均值
      CLOSE_AGEN_FIN_BAL,                                                           -- 代销封闭式理财余额/均值
      OPEN_AGEN_FIN_BAL,                                                            -- 代销开放式理财余额/均值
      CLOSE_SELF_FIN_BAL,                                                           -- 自营封闭式理财余额/均值
      OPEN_SELF_FIN_BAL,                                                            -- 自营开放式理财余额/均值
      INSUR_BAL,                                                                    -- 保险余额/均值
      LOAN_BAL,                                                                     -- 贷款余额/均值
      PERSN_LEGAL_BK_CODE                                                           -- 法人行号
  )
  SELECT
      X.DATA_DATE,                                                                  -- 数据日期
      X.CUST_ID,                                                                    -- 客户编号
      CASE
          WHEN CM1.CUST_ID IS NOT NULL THEN CM1.ORG_ID
          WHEN V_REALLOC_FLG = '1' AND R.REALLOC_ORG_ID IS NOT NULL THEN R.REALLOC_ORG_ID
          WHEN V_REALLOC_FLG = '0' AND LR.LAST_REALLOC_ORG_ID IS NOT NULL THEN LR.LAST_REALLOC_ORG_ID
          WHEN O.ORG_ID IS NULL THEN O.ORG_ID_LOAN
          ELSE O.ORG_ID
      END AS ORG_ID,                                                                -- 归属机构
      CM2.ORG_ID AS ORG_ID_LOAN,                                                    -- 信贷归属机构
      X.BAL_TYPE,                                                                   -- 余额类型 1-余额 2-月日均 3-季日均 4-年日均
      X.AUM_BAL,                                                                    -- AUM余额/均值
      X.DEPO_BAL,                                                                   -- 存款余额/均值
      X.DEPO_CURNT_DEPO_BAL,                                                        -- 活期存款余额/均值
      X.FIXD_DEPO_BAL,                                                              -- 定期存款余额/均值
      X.LEHUI_BAL,                                                                  -- 乐惠存余额/均值
      X.LARGEDP_BAL,                                                                -- 大额存单余额/均值
      X.FIN_BAL,                                                                    -- 理财余额/均值
      X.CLOSE_AGEN_FIN_BAL,                                                         -- 代销封闭式理财余额/均值
      X.OPEN_AGEN_FIN_BAL,                                                          -- 代销开放式理财余额/均值
      X.CLOSE_SELF_FIN_BAL,                                                         -- 自营封闭式理财余额/均值
      X.OPEN_SELF_FIN_BAL,                                                          -- 自营开放式理财余额/均值
      X.INSUR_BAL,                                                                  -- 保险余额/均值
      X.LOAN_BAL,                                                                   -- 贷款余额/均值
      X.PERSN_LEGAL_BK_CODE                                                         -- 法人行号
  FROM TMP3_DWS_CUST_ASSE_LIAB X
  LEFT JOIN TMP2_DWS_CUST_ASSE_LIAB O
    ON X.DATA_DATE = O.DATA_DATE
   AND X.CUST_ID = O.CUST_ID
   AND X.PERSN_LEGAL_BK_CODE = O.PERSN_LEGAL_BK_CODE
  LEFT JOIN TMP4_DWS_CUST_ASSE_REALLOC R
    ON X.DATA_DATE = R.DATA_DATE
   AND X.CUST_ID = R.CUST_ID
   AND X.PERSN_LEGAL_BK_CODE = R.PERSN_LEGAL_BK_CODE
  LEFT JOIN TMP5_DWS_CUST_ASSE_LAST_REALLOC LR
    ON X.CUST_ID = LR.CUST_ID
   AND X.PERSN_LEGAL_BK_CODE = LR.PERSN_LEGAL_BK_CODE
  LEFT JOIN DWD_CUST_MAN CM1
    ON X.CUST_ID = CM1.CUST_ID
   AND X.PERSN_LEGAL_BK_CODE = CM1.PERSN_LEGAL_BK_CODE
   AND CM1.MNG_TYP = '1'
  LEFT JOIN DWD_CUST_MAN CM2
    ON X.CUST_ID = CM2.CUST_ID
   AND X.PERSN_LEGAL_BK_CODE = CM2.PERSN_LEGAL_BK_CODE
   AND CM2.MNG_TYP = '2';

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6步目标表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  ------------------------------------------------------------------
  -- 7. 仅月末写历史
  ------------------------------------------------------------------
  V_NO_ID := '7';
  V_BGN_DATE := SYSDATE;

  IF V_CURR_DATE = LAST_DAY(V_CURR_DATE) THEN
    DELETE FROM DWS_CUST_ASSE_LIAB_HIS
     WHERE DATA_DATE = V_SYSDAT;

    INSERT INTO DWS_CUST_ASSE_LIAB_HIS (
        DATA_DATE,                                                                    -- 数据日期
        CUST_ID,                                                                      -- 客户编号
        ORG_ID,                                                                       -- 归属机构
        ORG_ID_LOAN,                                                                  -- 信贷归属机构
        BAL_TYPE,                                                                     -- 余额类型
        AUM_BAL,                                                                      -- AUM余额/均值
        DEPO_BAL,                                                                     -- 存款余额/均值
        DEPO_CURNT_DEPO_BAL,                                                          -- 活期存款余额/均值
        FIXD_DEPO_BAL,                                                                -- 定期存款余额/均值
        LEHUI_BAL,                                                                    -- 乐惠存余额/均值
        LARGEDP_BAL,                                                                  -- 大额存单余额/均值
        FIN_BAL,                                                                      -- 理财余额/均值
        CLOSE_AGEN_FIN_BAL,                                                           -- 代销封闭式理财余额/均值
        OPEN_AGEN_FIN_BAL,                                                            -- 代销开放式理财余额/均值
        CLOSE_SELF_FIN_BAL,                                                           -- 自营封闭式理财余额/均值
        OPEN_SELF_FIN_BAL,                                                            -- 自营开放式理财余额/均值
        INSUR_BAL,                                                                    -- 保险余额/均值
        LOAN_BAL,                                                                     -- 贷款余额/均值
        PERSN_LEGAL_BK_CODE                                                           -- 法人行号
    )
    SELECT
        DATA_DATE,                                                                    -- 数据日期
        CUST_ID,                                                                      -- 客户编号
        ORG_ID,                                                                       -- 归属机构
        ORG_ID_LOAN,                                                                  -- 信贷归属机构
        BAL_TYPE,                                                                     -- 余额类型 1-余额 2-月日均 3-季日均 4-年日均
        AUM_BAL,                                                                      -- AUM余额/均值
        DEPO_BAL,                                                                     -- 存款余额/均值
        DEPO_CURNT_DEPO_BAL,                                                          -- 活期存款余额/均值
        FIXD_DEPO_BAL,                                                                -- 定期存款余额/均值
        LEHUI_BAL,                                                                    -- 乐惠存余额/均值
        LARGEDP_BAL,                                                                  -- 大额存单余额/均值
        FIN_BAL,                                                                      -- 理财余额/均值
        CLOSE_AGEN_FIN_BAL,                                                           -- 代销封闭式理财余额/均值
        OPEN_AGEN_FIN_BAL,                                                            -- 代销开放式理财余额/均值
        CLOSE_SELF_FIN_BAL,                                                           -- 自营封闭式理财余额/均值
        OPEN_SELF_FIN_BAL,                                                            -- 自营开放式理财余额/均值
        INSUR_BAL,                                                                    -- 保险余额/均值
        LOAN_BAL,                                                                     -- 贷款余额/均值
        PERSN_LEGAL_BK_CODE                                                           -- 法人行号
    FROM DWS_CUST_ASSE_LIAB;
  END IF;

  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第7步历史表装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_asse_liab_cumu(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_asse_liab_cumu(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 报表名称：客户资产负债基数处理
  -- 报表编号：PRC_CUST_ASSE_LIAB_CUMU
  -- 处理周期：日
  -- 过程描述：按客户、账户、产品、产品大类、办理渠道、办理日期、投保单号/借据号、机构及法人行号等明细维度,
  --           生成存款、贷款、理财、保险余额基数及月/季/年累计余额基数。
  -- 来源表：DWD_ACCT_DEPO、DWD_ACCT_LOAN、DWD_ACCT_FIN、DWD_ACCT_INSUR(保单级主档)、DWS_CUST_ASSE_LIAB_CUMU_HIS
  -- 目标表：DWS_CUST_ASSE_LIAB_CUMU、DWS_CUST_ASSE_LIAB_CUMU_HIS
  -- 适配数据库：Oracle 兼容模式 / Kingbase Oracle 兼容模式
  -- 变更记录:
  --   v2.1.0 2026-08-03 适配DWD_ACCT_INSUR v1.1.0(TX_TYP置空等,已被v3.0.0取代)
  --   v3.0.0 2026-08-03 保单级主档重构：不再依赖HIS与交易类型；
  --                     状态判定完全基于DWD_ACCT_INSUR.POLICY_STATE(0/1/2)；
  --                     直接聚合INSUR_AMT生成保险余额,删除2.3-2.10中间段
  --   v4.0.0 2026-08-13 统一四类产品明细维度；保险按客户、账户、产品、渠道、办理日期、投保单号、机构等维度贯通；
  --                     新增CHNL_NO、ISSU_DATE、IOU_NO并纳入当日聚合、历史累计及当前/历史表写入键。
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户资产负债基数处理';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWS_CUST_ASSE_LIAB_CUMU';
  V_LOG_MSG              VARCHAR(4000);
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_DATA_DATE            VARCHAR(8);
  V_DT                   DATE;
  V_MTH_BEGIN            VARCHAR(8);  -- 当月初(参数9,sys_fun_deal_date)
  V_QRT_BEGIN            VARCHAR(8);  -- 当季初(参数11,sys_fun_deal_date)
  V_YAR_BEGIN            VARCHAR(8);  -- 当年初(参数13,sys_fun_deal_date)
  V_PRE_DATA_DATE        VARCHAR(8);  -- 上一日(参数1,sys_fun_deal_date)
  V_MTH_DAYS             NUMBER(10);
  V_QRT_DAYS             NUMBER(10);
  V_YAR_DAYS             NUMBER(10);
BEGIN
  --***************************************
  -- 2.业务逻辑区
  --***************************************
  V_DATA_DATE := V_SYSDAT;
  V_DT := TO_DATE(V_DATA_DATE, 'YYYYMMDD');
  V_PRE_DATA_DATE := sys_fun_deal_date(V_SYSDAT, 1);   -- 上一日(参数1)
  V_MTH_BEGIN := sys_fun_deal_date(V_SYSDAT, 9);       -- 当月初(参数9)
  V_QRT_BEGIN := sys_fun_deal_date(V_SYSDAT, 11);      -- 当季初(参数11)
  V_YAR_BEGIN := sys_fun_deal_date(V_SYSDAT, 13);      -- 当年初(参数13)
  V_MTH_DAYS := V_DT - TO_DATE(V_MTH_BEGIN, 'YYYYMMDD') + 1;   -- 月已过天数(记录日期运算)
  V_QRT_DAYS := V_DT - TO_DATE(V_QRT_BEGIN, 'YYYYMMDD') + 1;   -- 季已过天数(记录日期运算)
  V_YAR_DAYS := V_DT - TO_DATE(V_YAR_BEGIN, 'YYYYMMDD') + 1;   -- 年已过天数(记录日期运算)
  P_INTERVAL_START_DATE := V_YAR_BEGIN;
  P_INTERVAL_END_DATE   := V_DATA_DATE;

  --***************************************
  -- 2.1 清理当日目标数据和排查临时表
  -- 作用：重跑同一数据日期时先清理当日结果,并清空每段逻辑使用的中间排查表。
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  DELETE FROM DWS_CUST_ASSE_LIAB_CUMU
   WHERE DATA_DATE = V_DATA_DATE;

  DELETE FROM DWS_CUST_ASSE_LIAB_CUMU_HIS
   WHERE DATA_DATE = V_DATA_DATE;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_ASSE_LIAB_INSUR_BAL';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_ASSE_LIAB_TODAY_BAL';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_ASSE_LIAB_TODAY_AGG';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_ASSE_LIAB_KEY_SET';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_ASSE_LIAB_HIS_AGG';

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.1 清理当日目标数据和排查临时表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.2 生成保险当日余额临时表
  -- 作用：v3.0 起直接读取 DWD_ACCT_INSUR 保单级主档；状态判定完全基于 POLICY_STATE,
  --       余额直接取 INSUR_AMT(DWD 已按终止/缴费期满/宽限期规则清零),不再依赖 HIS 与交易类型。
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_DWS_CUST_ASSE_LIAB_INSUR_BAL (
      DATA_DATE,
      CUST_ID,
      ACCT_ID,
      PRDKT_ID,
      PRDKT_CATE_BIG,
      CHNL_NO,
      ISSU_DATE,
      IOU_NO,
      BAL,
      PERSN_LEGAL_BK_CODE,
      OPRT_ORG
  )
  SELECT
      V_DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      I.CUST_ID                                                         AS CUST_ID,        -- 客户号
      I.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      I.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      I.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG, -- 产品大类
      I.TX_CHNL                                                         AS CHNL_NO,       -- 办理渠道
      I.TX_DATE                                                         AS ISSU_DATE,     -- 办理日期
      I.INSUR_BID_FORM_NO                                               AS IOU_NO,        -- 投保单号
      SUM(NVL(I.INSUR_AMT, 0))                                          AS BAL,            -- 保险当日余额(仅有效保单)
      I.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      I.MKT_ORG                                                         AS OPRT_ORG        -- 归属机构
  FROM DWD_ACCT_INSUR I
  WHERE I.POLICY_STATE = '1'          -- 唯一状态判定源：仅正常保单参与(0/2余额已为0)
  GROUP BY
      I.CUST_ID,
      I.ACCT_ID,
      I.PRDKT_ID,
      I.PRDKT_CATE_BIG,
      I.TX_CHNL,
      I.TX_DATE,
      I.INSUR_BID_FORM_NO,
      I.PERSN_LEGAL_BK_CODE,
      I.MKT_ORG;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.2 生成保险当日余额临时表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.11 生成四类产品当日余额明细临时表
  -- 作用：存款、贷款、理财优先从当前账户表取当日余额,保险取前序规则计算后的余额；
  --       四类产品统一输出客户、账户、产品、产品大类、办理渠道、办理日期、投保单号/借据号、机构及法人行号等维度。
  --***************************************

  V_NO_ID := '11';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_DWS_CUST_ASSE_LIAB_TODAY_BAL (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      OPRT_ORG,
      CUST_ID,
      ACCT_ID,
      PRDKT_ID,
      PRDKT_CATE_BIG,
      CHNL_NO,
      ISSU_DATE,
      IOU_NO,
      BAL,
      PRDKT_TYP
  )
  SELECT
      V_DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      D.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      D.OPEN_ACCT_ORG                                                   AS OPRT_ORG,       -- 归属机构
      D.CUST_ID                                                         AS CUST_ID,        -- 客户号
      D.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      D.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      COALESCE(D.PRDKT_CATE_BIG, 'DEP')                                 AS PRDKT_CATE_BIG, -- 产品大类
      CAST(NULL AS VARCHAR(10))                                         AS CHNL_NO,       -- 存款暂无办理渠道字段
      D.OPEN_DATE                                                        AS ISSU_DATE,     -- 存款开户日期
      CAST(NULL AS VARCHAR(100))                                        AS IOU_NO,        -- 存款无投保单号或借据号
      NVL(D.BAL, 0)                                                     AS BAL,            -- 存款余额
      '1'                                                               AS PRDKT_TYP        -- 产品类型
  FROM DWD_ACCT_DEPO D
  WHERE D.CUST_ID IS NOT NULL
    AND D.ACCT_ID IS NOT NULL

  UNION ALL

  SELECT
      V_DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      L.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      L.OPRT_ORG                                                        AS OPRT_ORG,       -- 经办机构
      L.CUST_ID                                                         AS CUST_ID,        -- 客户号
      L.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      L.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      COALESCE(L.PRDKT_CATE_BIG, 'LOAN')                                AS PRDKT_CATE_BIG, -- 产品大类
      CAST(NULL AS VARCHAR(10))                                         AS CHNL_NO,       -- 贷款暂无办理渠道字段
      L.LOAN_ISSU_DATE                                                   AS ISSU_DATE,     -- 贷款发放日期
      L.IOU_NO                                                           AS IOU_NO,        -- 借据号
      NVL(L.BAL, 0)                                                     AS BAL,             -- 贷款余额
      '2'                                                               AS PRDKT_TYP        -- 产品类型
  FROM DWD_ACCT_LOAN L
  WHERE L.CUST_ID IS NOT NULL
    AND L.ACCT_ID IS NOT NULL

  UNION ALL

  SELECT
      V_DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      F.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      F.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      F.CUST_ID                                                         AS CUST_ID,        -- 客户号
      F.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      F.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      COALESCE(F.PRDKT_CATE_BIG, 'FIN')                                 AS PRDKT_CATE_BIG, -- 产品大类
      F.CHNL_NO                                                          AS CHNL_NO,       -- 理财办理渠道
      F.ISSU_DATE                                                        AS ISSU_DATE,     -- 理财办理日期
      CAST(NULL AS VARCHAR(100))                                        AS IOU_NO,        -- 理财无投保单号或借据号
      NVL(F.FIN_AMT, 0)                                                 AS BAL,            -- 理财余额,已为份额乘净值后的结果值
      '3'                                                               AS PRDKT_TYP        -- 产品类型
  FROM DWD_ACCT_FIN F
  WHERE F.CUST_ID IS NOT NULL
    AND F.ACCT_ID IS NOT NULL

  UNION ALL
  SELECT
      I.DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      I.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      I.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      I.CUST_ID                                                         AS CUST_ID,        -- 客户号
      I.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      I.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      I.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG, -- 产品大类
      I.CHNL_NO                                                          AS CHNL_NO,       -- 保险办理渠道
      I.ISSU_DATE                                                        AS ISSU_DATE,     -- 保险办理日期
      I.IOU_NO                                                           AS IOU_NO,        -- 投保单号
      I.BAL                                                             AS BAL,             -- 保险余额
      '4'                                                               AS PRDKT_TYP        -- 产品类型
  FROM TMP_DWS_CUST_ASSE_LIAB_INSUR_BAL I;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.11 生成四类产品当日余额明细临时表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.12 生成当日余额聚合临时表
  -- 作用：按完整明细维度汇总同日余额；其中保险的渠道、办理日期和投保单号共同保持保单级行粒度,避免不同保单被合并。
  --***************************************
  V_NO_ID := '12';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_DWS_CUST_ASSE_LIAB_TODAY_AGG (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      OPRT_ORG,
      CUST_ID,
      ACCT_ID,
      PRDKT_ID,
      PRDKT_CATE_BIG,
      CHNL_NO,
      ISSU_DATE,
      IOU_NO,
      BAL,
      PRDKT_TYP
  )
  SELECT
      T.DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      T.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      T.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      T.CUST_ID                                                         AS CUST_ID,        -- 客户号
      T.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      T.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      T.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG, -- 产品大类
      T.CHNL_NO                                                         AS CHNL_NO,
      T.ISSU_DATE                                                       AS ISSU_DATE,
      T.IOU_NO                                                          AS IOU_NO,
      SUM(NVL(T.BAL, 0))                                                AS BAL,            -- 聚合后当日余额
      PRDKT_TYP
  FROM TMP_DWS_CUST_ASSE_LIAB_TODAY_BAL T
  GROUP BY
      T.DATA_DATE,
      T.PERSN_LEGAL_BK_CODE,
      T.OPRT_ORG,
      T.CUST_ID,
      T.ACCT_ID,
      T.PRDKT_ID,
      T.PRDKT_CATE_BIG,
      T.CHNL_NO,
      T.ISSU_DATE,
      T.IOU_NO,
      PRDKT_TYP;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.12 生成当日余额聚合临时表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.13 生成结果补零KEY临时表
  -- 作用：按完整明细维度合并当日有余额的KEY和年内历史存在的KEY,确保余额清零后的产品仍能输出0并参与累计。
  --***************************************
  V_NO_ID := '13';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_DWS_CUST_ASSE_LIAB_KEY_SET (
      PERSN_LEGAL_BK_CODE,
      OPRT_ORG,
      CUST_ID,
      ACCT_ID,
      PRDKT_ID,
      PRDKT_CATE_BIG,
      CHNL_NO,
      ISSU_DATE,
      IOU_NO,
      PRDKT_TYP
  )
  SELECT
      A.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      A.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      A.CUST_ID                                                         AS CUST_ID,        -- 客户号
      A.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      A.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      A.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG, -- 产品大类
      A.CHNL_NO                                                          AS CHNL_NO,
      A.ISSU_DATE                                                        AS ISSU_DATE,
      A.IOU_NO                                                           AS IOU_NO,
      A.PRDKT_TYP                                                        AS PRDKT_TYP        -- 产品类型
  FROM TMP_DWS_CUST_ASSE_LIAB_TODAY_AGG A
  UNION
  SELECT
      H.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      H.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      H.CUST_ID                                                         AS CUST_ID,        -- 客户号
      H.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      H.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      H.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG,  -- 产品大类
      H.CHNL_NO                                                          AS CHNL_NO,
      H.ISSU_DATE                                                        AS ISSU_DATE,
      H.IOU_NO                                                           AS IOU_NO,
      H.PRDKT_TYP                                                        AS PRDKT_TYP        -- 产品类型
  FROM DWS_CUST_ASSE_LIAB_CUMU_HIS H
  WHERE H.DATA_DATE >= V_YAR_BEGIN
    AND H.DATA_DATE <  V_DATA_DATE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.13 生成结果补零KEY临时表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.14 生成历史累计余额临时表
  -- 作用：按完整明细维度直接取上一数据日期的月累计、季累计、年累计余额基数,月初/季初/年初分别重置为0。
  --***************************************
  V_NO_ID := '14';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_DWS_CUST_ASSE_LIAB_HIS_AGG (
      PERSN_LEGAL_BK_CODE,
      OPRT_ORG,
      CUST_ID,
      ACCT_ID,
      PRDKT_ID,
      PRDKT_CATE_BIG,
      CHNL_NO,
      ISSU_DATE,
      IOU_NO,
      PRDKT_TYP,
      HIS_MTH_BAL,
      HIS_QRT_BAL,
      HIS_YAR_BAL
  )
  SELECT
      H.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      H.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      H.CUST_ID                                                         AS CUST_ID,        -- 客户号
      H.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      H.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      H.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG, -- 产品大类
      H.CHNL_NO                                                          AS CHNL_NO,
      H.ISSU_DATE                                                        AS ISSU_DATE,
      H.IOU_NO                                                           AS IOU_NO,
      H.PRDKT_TYP                                                        AS PRDKT_TYP,       -- 产品类型
      CASE WHEN V_DATA_DATE = V_MTH_BEGIN THEN 0 ELSE NVL(H.MTH_BAL, 0) END AS HIS_MTH_BAL, -- 上日月累计余额
      CASE WHEN V_DATA_DATE = V_QRT_BEGIN THEN 0 ELSE NVL(H.QRT_BAL, 0) END AS HIS_QRT_BAL, -- 上日季累计余额
      CASE WHEN V_DATA_DATE = V_YAR_BEGIN THEN 0 ELSE NVL(H.YAR_BAL, 0) END AS HIS_YAR_BAL -- 上日年累计余额
  FROM DWS_CUST_ASSE_LIAB_CUMU_HIS H
  WHERE H.DATA_DATE = V_PRE_DATA_DATE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.14 生成历史累计余额临时表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.15 生成客户资产负债基数当前表
  -- 作用：按完整明细维度将当日余额与上一日累计余额合并,生成月/季/年累计余额基数。
  --***************************************
  V_NO_ID := '15';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWS_CUST_ASSE_LIAB_CUMU (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      OPRT_ORG,
      CUST_ID,
      ACCT_ID,
      PRDKT_ID,
      PRDKT_CATE_BIG,
      CHNL_NO,
      ISSU_DATE,
      IOU_NO,
      PRDKT_TYP,
      BAL,
      MTH_BAL,
      QRT_BAL,
      YAR_BAL,
      MTH_DAYS,
      QRT_DAYS,
      YAR_DAYS
  )
  SELECT
      V_DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      K.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      K.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      K.CUST_ID                                                         AS CUST_ID,        -- 客户号
      K.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      K.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      K.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG, -- 产品大类
      K.CHNL_NO                                                          AS CHNL_NO,
      K.ISSU_DATE                                                        AS ISSU_DATE,
      K.IOU_NO                                                           AS IOU_NO,
      K.PRDKT_TYP                                                        AS PRDKT_TYP,       -- 产品类型
      NVL(A.BAL, 0)                                                     AS BAL,            -- 当日余额
      NVL(H.HIS_MTH_BAL, 0) + NVL(A.BAL, 0)                             AS MTH_BAL,        -- 月累计余额
      NVL(H.HIS_QRT_BAL, 0) + NVL(A.BAL, 0)                             AS QRT_BAL,        -- 季累计余额
      NVL(H.HIS_YAR_BAL, 0) + NVL(A.BAL, 0)                             AS YAR_BAL,        -- 年累计余额
      V_MTH_DAYS                                                        AS MTH_DAYS,       -- 月已过天数
      V_QRT_DAYS                                                        AS QRT_DAYS,       -- 季已过天数
      V_YAR_DAYS                                                        AS YAR_DAYS        -- 年已过天数
  FROM TMP_DWS_CUST_ASSE_LIAB_KEY_SET K
  LEFT JOIN TMP_DWS_CUST_ASSE_LIAB_TODAY_AGG A
    ON K.PERSN_LEGAL_BK_CODE = A.PERSN_LEGAL_BK_CODE
   AND K.OPRT_ORG = A.OPRT_ORG
   AND K.CUST_ID = A.CUST_ID
   AND K.ACCT_ID = A.ACCT_ID
   AND K.PRDKT_ID = A.PRDKT_ID
   AND K.PRDKT_CATE_BIG = A.PRDKT_CATE_BIG
   AND ((K.CHNL_NO = A.CHNL_NO) OR (K.CHNL_NO IS NULL AND A.CHNL_NO IS NULL))
   AND ((K.ISSU_DATE = A.ISSU_DATE) OR (K.ISSU_DATE IS NULL AND A.ISSU_DATE IS NULL))
   AND ((K.IOU_NO = A.IOU_NO) OR (K.IOU_NO IS NULL AND A.IOU_NO IS NULL))
   AND K.PRDKT_TYP = A.PRDKT_TYP
  LEFT JOIN TMP_DWS_CUST_ASSE_LIAB_HIS_AGG H
    ON K.PERSN_LEGAL_BK_CODE = H.PERSN_LEGAL_BK_CODE
   AND K.OPRT_ORG = H.OPRT_ORG
   AND K.CUST_ID = H.CUST_ID
   AND K.ACCT_ID = H.ACCT_ID
   AND K.PRDKT_ID = H.PRDKT_ID
   AND K.PRDKT_CATE_BIG = H.PRDKT_CATE_BIG
   AND ((K.CHNL_NO = H.CHNL_NO) OR (K.CHNL_NO IS NULL AND H.CHNL_NO IS NULL))
   AND ((K.ISSU_DATE = H.ISSU_DATE) OR (K.ISSU_DATE IS NULL AND H.ISSU_DATE IS NULL))
   AND ((K.IOU_NO = H.IOU_NO) OR (K.IOU_NO IS NULL AND H.IOU_NO IS NULL))
   AND K.PRDKT_TYP = H.PRDKT_TYP;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.15 生成客户资产负债基数当前表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  --***************************************
  -- 2.16 写入客户资产负债基数历史表
  -- 作用：把当日当前表结果同步写入历史表,供后续日期直接取上一日累计余额。
  --***************************************
  V_NO_ID := '16';
  V_BGN_DATE := SYSDATE;

  INSERT INTO DWS_CUST_ASSE_LIAB_CUMU_HIS (
      DATA_DATE,
      PERSN_LEGAL_BK_CODE,
      OPRT_ORG,
      CUST_ID,
      ACCT_ID,
      PRDKT_ID,
      PRDKT_CATE_BIG,
      CHNL_NO,
      ISSU_DATE,
      IOU_NO,
      PRDKT_TYP,
      BAL,
      MTH_BAL,
      QRT_BAL,
      YAR_BAL,
      MTH_DAYS,
      QRT_DAYS,
      YAR_DAYS
  )
  SELECT
      C.DATA_DATE                                                       AS DATA_DATE,      -- 数据日期
      C.PERSN_LEGAL_BK_CODE                                             AS PERSN_LEGAL_BK_CODE, -- 法人行号
      C.OPRT_ORG                                                        AS OPRT_ORG,       -- 归属机构
      C.CUST_ID                                                         AS CUST_ID,        -- 客户号
      C.ACCT_ID                                                         AS ACCT_ID,        -- 账号
      C.PRDKT_ID                                                        AS PRDKT_ID,       -- 产品编号
      C.PRDKT_CATE_BIG                                                  AS PRDKT_CATE_BIG, -- 产品大类
      C.CHNL_NO                                                         AS CHNL_NO,        -- 办理渠道
      C.ISSU_DATE                                                       AS ISSU_DATE,      -- 办理日期
      C.IOU_NO                                                          AS IOU_NO,         -- 投保单号或者借据号
      C.PRDKT_TYP                                                        AS PRDKT_TYP,       -- 产品类型      
      C.BAL                                                             AS BAL,            -- 当日余额
      C.MTH_BAL                                                         AS MTH_BAL,        -- 月累计余额
      C.QRT_BAL                                                         AS QRT_BAL,        -- 季累计余额
      C.YAR_BAL                                                         AS YAR_BAL,        -- 年累计余额
      C.MTH_DAYS                                                        AS MTH_DAYS,       -- 月已过天数
      C.QRT_DAYS                                                        AS QRT_DAYS,       -- 季已过天数
      C.YAR_DAYS                                                        AS YAR_DAYS        -- 年已过天数
  FROM DWS_CUST_ASSE_LIAB_CUMU C
  WHERE C.DATA_DATE = V_DATA_DATE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE  := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG   := '2.16 写入客户资产负债基数历史表';
  V_LOG_FLG   := OUTCDE;

  SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);

  OUTCDE := 0;

  --***************************************
  -- 3.异常处理区
  --***************************************
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;
    SYS_PRC_STEP_LOGS(V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG, V_LOG_BUTTON);
    RAISE;
END

;

-- DROP PROCEDURE crmdm.prc_dws_cust_chnl_use(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_chnl_use(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户渠道使用表
  -- 存储过程编号：PRC_DWS_CUST_CHNL_USE
  -- 处理周期：日
  -- 过程描述：根据 DWS 数据模型映射生成
  -- 来源表：CBS_KDPA_XIUGMX(账户修改明细登记簿)；CBS_KDPA_ZHXINX(负债账户信息表)；DHYH_T_BASELOG_AGENT_SESSION_INFO(待确认：来源表中文名缺失)；DWD_CUST_INDV_INFO(客户基本信息表)；DWD_TX_ASET(资产交易信息表)；MBK_CUST_DETAIL_INFO(客户详细信息)；MBK_CUST_LOG_LOGIN(客户登录日志表)；MBK_CUST_LOG_WECHAT_LOGIN(登录日志)；SEBS_PB_CSTINF_PRO(个人注册客户网银信息表)；SEBS_PB_LOGINLOG_FLOW(个人网银登录信息交易表)；TEL_NUM(来电手机号)；TMP1_DWS_CUST_CHNL_USE(客户渠道使用表_临时表非动账口径)；TMP_DWS_CUST_CHNL_USE(客户渠道使用表_临时表动账口径)；ZHTT_T_BUSI_FLOW_RECORD(待确认：来源表中文名缺失)
  -- 目标表：DWS_CUST_CHNL_USE；TMP1_DWS_CUST_CHNL_USE；TMP_DWS_CUST_CHNL_USE
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户渠道使用表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWS_CUST_CHNL_USE';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_SYSDAT_3M         VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_SYSDAT_3M        := TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'yyyymmdd'), -3), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_CHNL_USE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_DWS_CUST_CHNL_USE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_CUST_CHNL_USE';

  --***************************************
  -- 2.1 -- 第1段处理开始：客户渠道使用-动账口径
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：客户渠道使用-动账口径
  INSERT INTO TMP_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE                          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID                                      AS CUST_ID              , -- 客户编号
         '2'                                             AS STATIS_TYP           , -- 统计口径
         CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '1'
            WHEN T1.TX_CHNL IN ('3001','3302') THEN '2'
            WHEN T1.TX_CHNL IN ('3003','3041') THEN '3' 
            WHEN T1.TX_CHNL IN ('031') THEN '4'
            WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '5'
            WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '6'
            WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '7'
            ELSE '9'
         END AS CHNL_CATE, -- 渠道种类
         CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '手机银行'
            WHEN T1.TX_CHNL IN ('3001','3302') THEN '网上银行'
            WHEN T1.TX_CHNL IN ('3003','3041') THEN '电话银行' 
            WHEN T1.TX_CHNL IN ('031') THEN '微信银行'
            WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '三方支付'
            WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '智能终端'
            WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '柜面'
            ELSE '其他'
         END AS CHNL_NAME, -- 渠道名称
         COUNT(1)                                        AS USE_CNT               -- 使用次数
    FROM DWD_TX_ASET T1 -- 资产交易信息表
   WHERE T1.DATA_DATE >= V_SYSDAT_3M --近三个月
     GROUP BY T1.CUST_ID,PERSN_LEGAL_BK_CODE,
     CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '1'
     WHEN T1.TX_CHNL IN ('3001','3302') THEN '2'
     WHEN T1.TX_CHNL IN ('3003','3041') THEN '3'
     WHEN T1.TX_CHNL IN ('031') THEN '4'
     WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '5'
     WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '6'
     WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '7'
     ELSE '9'
     END,
     CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '手机银行'
     WHEN T1.TX_CHNL IN ('3001','3302') THEN '网上银行'
     WHEN T1.TX_CHNL IN ('3003','3041') THEN '电话银行'
     WHEN T1.TX_CHNL IN ('031') THEN '微信银行'
     WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '三方支付'
     WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '智能终端'
     WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '柜面'
     ELSE '其他'
     END;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：客户渠道使用-动账口径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：客户渠道使用-非动账口径-手机银行
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：客户渠道使用-非动账口径-手机银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.ECIF_NO                                  AS CUST_ID              , -- 客户编号
         '1'                                         AS STATIS_TYP           , -- 统计口径
         '1'                                         AS CHNL_CATE            , -- 渠道种类
         '手机银行'                                      AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T1.LGN_DATE, 1, 10))  AS USE_CNT               -- 使用次数
    FROM MBK_CUST_LOG_LOGIN T1 -- 客户登录日志表
    LEFT JOIN MBK_CUST_DETAIL_INFO T2 -- 客户详细信息
      ON T1.CUST_NO = T2.CUST_NO
   WHERE T1.LGN_STATUS='1' and TO_CHAR(TO_DATE(T1.LGN_DATE,'YYYY-MM-DD'),'YYYYMMDD') > V_SYSDAT_3M
     GROUP BY T2.ECIF_NO;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：客户渠道使用-非动账口径-手机银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：客户渠道使用-非动账口径-网上银行
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：客户渠道使用-非动账口径-网上银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CIP_HOSTNO                                   AS CUST_ID              , -- 客户编号
         '1'                                             AS STATIS_TYP           , -- 统计口径
         '2'                                             AS CHNL_CATE            , -- 渠道种类
         '网上银行'                                          AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T2.PLF_LOGINDATE, 1, 10)) AS USE_CNT               -- 使用次数
    FROM SEBS_PB_CSTINF_PRO T1 -- 个人注册客户网银信息表
    LEFT JOIN SEBS_PB_LOGINLOG_FLOW T2 -- 个人网银登录信息交易表
      ON T1.CIP_CSTNO=T2.PLF_CSTNO
   WHERE T2.PLF_LOGINDATE > V_SYSDAT_3M
     GROUP BY T1.CIP_HOSTNO;

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：客户渠道使用-非动账口径-网上银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：客户渠道使用-非动账口径-电话银行
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 第4段业务逻辑：客户渠道使用-非动账口径-电话银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  WITH TEL_NUM AS (
    SELECT ANI, COUNT(DISTINCT(TO_CHAR(DATATIMESTAMP,'YYYYMMDD'))) AS TEL_NU
    FROM DHYH_T_BASELOG_AGENT_SESSION_INFO
    WHERE REGEXP_LIKE(ANI, '^1[3-9][0-9]{9}$')
      AND CHANNELTYPE = 'voice'
      AND TO_CHAR(DATATIMESTAMP,'YYYYMMDD') > V_SYSDAT_3M
    GROUP BY ANI
  )
  SELECT
         '9999'      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.CUST_ID  AS CUST_ID              , -- 客户编号
         '1'         AS STATIS_TYP           , -- 统计口径
         '3'         AS CHNL_CATE            , -- 渠道种类
         '电话银行'      AS CHNL_NAME            , -- 渠道名称
         T1.TEL_NU   AS USE_CNT               -- 使用次数
    FROM TEL_NUM T1 -- 来电手机号
    LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
      ON T1.ANI = T2.PHONE_NO
   WHERE 1=1;

  -- 提交第4段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：客户渠道使用-非动账口径-电话银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5 -- 第5段处理开始：客户渠道使用-非动账口径-微信银行
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  -- 第5段业务逻辑：客户渠道使用-非动账口径-微信银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.ECIF_NO                                  AS CUST_ID              , -- 客户编号
         '1'                                         AS STATIS_TYP           , -- 统计口径
         '4'                                         AS CHNL_CATE            , -- 渠道种类
         '微信银行'                                      AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T1.LGN_DATE, 1, 10))  AS USE_CNT               -- 使用次数
    FROM MBK_CUST_LOG_WECHAT_LOGIN T1 -- 登录日志
    LEFT JOIN MBK_CUST_DETAIL_INFO T2 -- 客户详细信息
      ON T1.CUST_NO = T1.CUST_NO
   WHERE T1.LGN_STATUS='1' and TO_CHAR(TO_DATE(T1.LGN_DATE,'YYYY-MM-DD'),'YYYYMMDD') > V_SYSDAT_3M
     GROUP BY T2.ECIF_NO;

  -- 提交第5段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第5段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段业务逻辑处理完成：客户渠道使用-非动账口径-微信银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第5段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.6 -- 第6段处理开始：客户渠道使用-非动账口径-智慧厅堂
  --***************************************
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  -- 第6段业务逻辑：客户渠道使用-非动账口径-智慧厅堂
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_NO                  AS CUST_ID              , -- 客户编号
         '1'                         AS STATIS_TYP           , -- 统计口径
         '6'                         AS CHNL_CATE            , -- 渠道种类
         '智慧厅堂'                      AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT TRANS_DATE)  AS USE_CNT               -- 使用次数
    FROM ZHTT_T_BUSI_FLOW_RECORD T1 -- 待确认：来源表中文名缺失
   WHERE T1.TRANS_AMT_FLAG = '0' AND T1.CUST_NO IS NOT NULL AND T1.TRANS_DATE >= V_SYSDAT_3M --动账类交易标志0-否,1-是
     GROUP BY CUST_NO;

  -- 提交第6段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第6段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6段业务逻辑处理完成：客户渠道使用-非动账口径-智慧厅堂';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第6段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.7 -- 第7段处理开始：客户渠道使用-非动账口径-柜面
  --***************************************
  V_NO_ID := '7';
  V_BGN_DATE := SYSDATE;

  -- 第7段业务逻辑：客户渠道使用-非动账口径-柜面
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.KEHUHAOO                                 AS CUST_ID              , -- 客户编号
         '1'                                         AS STATIS_TYP           , -- 统计口径
         '7'                                         AS CHNL_CATE            , -- 渠道种类
         '柜面'                                        AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T2.XIUGRIQI, 1, 10))  AS USE_CNT               -- 使用次数
    FROM CBS_KDPA_ZHXINX T1 -- 负债账户信息表
    LEFT JOIN CBS_KDPA_XIUGMX T2 -- 账户修改明细登记簿
      ON T1.ZHANGHAO = T2.ZHANGHAO
   WHERE T2.XIUGRIQI >'20260420'
     GROUP BY T1.KEHUHAOO;

  -- 提交第7段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第7段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第7段业务逻辑处理完成：客户渠道使用-非动账口径-柜面';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第7段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.8 -- 第8段处理开始：客户渠道使用-动账口径
  --***************************************
  V_NO_ID := '8';
  V_BGN_DATE := SYSDATE;

  -- 第8段业务逻辑：客户渠道使用-动账口径
  INSERT INTO DWS_CUST_CHNL_USE (
      PK_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         SEQ_DWS_CUST_CHNL_USE.NEXTVAL  AS PK_ID                , -- 主键
         T2.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID                     AS CUST_ID              , -- 客户编号
         T1.STATIS_TYP                  AS STATIS_TYP           , -- 统计口径
         T1.CHNL_CATE                   AS CHNL_CATE            , -- 渠道种类
         T1.CHNL_NAME                   AS CHNL_NAME            , -- 渠道名称
         T1.USE_CNT                     AS USE_CNT               -- 使用次数
    FROM TMP_DWS_CUST_CHNL_USE T1 -- 客户渠道使用表_临时表动账口径
    LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
      ON T1.CUST_ID = T2.CUST_ID
   WHERE 1=1;

  -- 提交第8段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第8段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第8段业务逻辑处理完成：客户渠道使用-动账口径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第8段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.9 -- 第9段处理开始：客户渠道使用-动账口径、客户渠道使用-非动账口径 合并为客户渠道使用-全口径
  --***************************************
  V_NO_ID := '9';
  V_BGN_DATE := SYSDATE;

  -- 第9段业务逻辑：客户渠道使用-动账口径、客户渠道使用-非动账口径 合并为客户渠道使用-全口径
  INSERT INTO DWS_CUST_CHNL_USE (
      PK_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         SEQ_DWS_CUST_CHNL_USE.NEXTVAL  AS PK_ID                 , -- 主键
         T.PERSN_LEGAL_BK_CODE   AS PERSN_LEGAL_BK_CODE   , -- 法人行号
         T.CUST_ID               AS CUST_ID               , -- 客户编号
         T.STATIS_TYP            AS STATIS_TYP            , -- 统计口径
         T.CHNL_CATE             AS CHNL_CATE             , -- 渠道种类
         T.CHNL_NAME             AS CHNL_NAME             , -- 渠道名称
         SUM(T.USE_CNT)          AS USE_CNT                -- 使用次数
    FROM (
          -- 客户渠道使用-动账口径
          SELECT
                 --SEQ_DWS_CUST_CHNL_USE.NEXTVAL  AS PK_ID                , -- 主键
                 T1.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID                     AS CUST_ID              , -- 客户编号
                 '1'                            AS STATIS_TYP           , -- 统计口径
                 T1.CHNL_CATE                   AS CHNL_CATE            , -- 渠道种类
                 T1.CHNL_NAME                   AS CHNL_NAME            , -- 渠道名称
                 T1.USE_CNT                     AS USE_CNT               -- 使用次数
            FROM TMP_DWS_CUST_CHNL_USE T1 -- 客户渠道使用表_临时表动账口径
           WHERE 1=1
          UNION
          -- 客户渠道使用-非动账口径
          SELECT
                 --SEQ_DWS_CUST_CHNL_USE.NEXTVAL  AS PK_ID                , -- 主键
                 T1.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID                     AS CUST_ID              , -- 客户编号
                 '1'                            AS STATIS_TYP           , -- 统计口径
                 T1.CHNL_CATE                   AS CHNL_CATE            , -- 渠道种类
                 T1.CHNL_NAME                   AS CHNL_NAME            , -- 渠道名称
                 T1.USE_CNT                     AS USE_CNT               -- 使用次数
            FROM TMP1_DWS_CUST_CHNL_USE T1 -- 客户渠道使用表_临时表非动账口径
           WHERE 1=1
         ) T
   GROUP BY T.PERSN_LEGAL_BK_CODE, T.CUST_ID, T.STATIS_TYP, T.CHNL_CATE, T.CHNL_NAME;

  -- 提交第9段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第9段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第9段业务逻辑处理完成：客户渠道使用-动账口径、客户渠道使用-非动账口径 合并为客户渠道使用-全口径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第9段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_chnl_use_copy(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_chnl_use_copy(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户渠道使用表
  -- 存储过程编号：PRC_DWS_CUST_CHNL_USE
  -- 处理周期：日
  -- 过程描述：根据 DWS 数据模型映射生成
  -- 来源表：CBS_KDPA_XIUGMX(账户修改明细登记簿)；CBS_KDPA_ZHXINX(负债账户信息表)；DHYH_T_BASELOG_AGENT_SESSION_INFO(待确认：来源表中文名缺失)；DWD_CUST_INDV_INFO(客户基本信息表)；DWD_TX_ASET(资产交易信息表)；MBK_CUST_DETAIL_INFO(客户详细信息)；MBK_CUST_LOG_LOGIN(客户登录日志表)；MBK_CUST_LOG_WECHAT_LOGIN(登录日志)；SEBS_PB_CSTINF_PRO(个人注册客户网银信息表)；SEBS_PB_LOGINLOG_FLOW(个人网银登录信息交易表)；TEL_NUM(来电手机号)；TMP1_DWS_CUST_CHNL_USE(客户渠道使用表_临时表非动账口径)；TMP_DWS_CUST_CHNL_USE(客户渠道使用表_临时表动账口径)；ZHTT_T_BUSI_FLOW_RECORD(待确认：来源表中文名缺失)
  -- 目标表：DWS_CUST_CHNL_USE；TMP1_DWS_CUST_CHNL_USE；TMP_DWS_CUST_CHNL_USE
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户渠道使用表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWS_CUST_CHNL_USE';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
  V_SYSDAT_3M         VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_SYSDAT_3M        := TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'yyyymmdd'), -3), 'yyyymmdd');

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_CHNL_USE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_DWS_CUST_CHNL_USE';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_CUST_CHNL_USE';

  --***************************************
  -- 2.1 -- 第1段处理开始：客户渠道使用-动账口径
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：客户渠道使用-动账口径
  INSERT INTO TMP_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE                          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID                                      AS CUST_ID              , -- 客户编号
         '2'                                             AS STATIS_TYP           , -- 统计口径
         CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '1'
            WHEN T1.TX_CHNL IN ('3001','3302') THEN '2'
            WHEN T1.TX_CHNL IN ('3003','3041') THEN '3' 
            WHEN T1.TX_CHNL IN ('031') THEN '4'
            WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '5'
            WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '6'
            WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '7'
            ELSE T1.TX_CHNL
         END AS CHNL_CATE, -- 渠道种类
         CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '手机银行'
            WHEN T1.TX_CHNL IN ('3001','3302') THEN '网上银行'
            WHEN T1.TX_CHNL IN ('3003','3041') THEN '电话银行' 
            WHEN T1.TX_CHNL IN ('031') THEN '微信银行'
            WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '三方支付'
            WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '智能终端'
            WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '柜面'
            ELSE T1.TX_CHNL
         END AS CHNL_NAME, -- 渠道名称
         COUNT(1)                                        AS USE_CNT               -- 使用次数
    FROM DWD_TX_ASET T1 -- 资产交易信息表
   WHERE T1.DATA_DATE >= V_SYSDAT_3M --近三个月
     GROUP BY T1.CUST_ID,PERSN_LEGAL_BK_CODE,
     CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '1'
     WHEN T1.TX_CHNL IN ('3001','3302') THEN '2'
     WHEN T1.TX_CHNL IN ('3003','3041') THEN '3'
     WHEN T1.TX_CHNL IN ('031') THEN '4'
     WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '5'
     WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '6'
     WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '7'
     ELSE T1.TX_CHNL
     END,
     CASE WHEN T1.TX_CHNL IN ('3002','3008','3031') THEN '手机银行'
     WHEN T1.TX_CHNL IN ('3001','3302') THEN '网上银行'
     WHEN T1.TX_CHNL IN ('3003','3041') THEN '电话银行'
     WHEN T1.TX_CHNL IN ('031') THEN '微信银行'
     WHEN T1.TX_CHNL IN ('3012','3026','3028','3029','3030','3111','3201','3300','3301','3303','3304','3305','3306','3307','3308','3309','3310','3311','3312','3313','3314','3315','3317','3318','3320','3321','3322','3323','3324','3325','3326','3327','3328','3329','3330','3331','3332','3333','3334','3335','3336','3337','3338','3340','3341','3342','3343','3344','3345','3346','3347','3348','3349','3350','3352','3353','3354','3355','3356','3357','3359','3360','3361','3362','3363','3364','3365','3366','3367','3368','3369','3370','3371','3372','3373','3374','3375','3376','3377','3378','3379','3380','3381','3382','3383','3384','3385','3386','3387','3388','3389','3390','3391','3392','3393','3394','3395','3396','3397','3398','3399','3400','3401','3402','3404','3405','3406','3407','3408','3409','3410','3411','3412','3413','3414','3415','3416','3417','3418','3419','3420','3421','3422','3423','3425') THEN '三方支付'
     WHEN T1.TX_CHNL IN ('3015','3016','3017','3038','3050','3106','3107','3108','3113','3114','3115','3118','3202') THEN '智能终端'
     WHEN T1.TX_CHNL IN ('1001','1002','1003','1004','1005','1012','1017','1018','3013','3040','3049') THEN '柜面'
     ELSE T1.TX_CHNL
     END;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：客户渠道使用-动账口径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：客户渠道使用-非动账口径-手机银行
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：客户渠道使用-非动账口径-手机银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.ECIF_NO                                  AS CUST_ID              , -- 客户编号
         '1'                                         AS STATIS_TYP           , -- 统计口径
         '1'                                         AS CHNL_CATE            , -- 渠道种类
         '手机银行'                                      AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T1.LGN_DATE, 1, 10))  AS USE_CNT               -- 使用次数
    FROM MBK_CUST_LOG_LOGIN T1 -- 客户登录日志表
    LEFT JOIN MBK_CUST_DETAIL_INFO T2 -- 客户详细信息
      ON T1.CUST_NO = T2.CUST_NO
   WHERE T1.LGN_STATUS='1' and TO_CHAR(TO_DATE(T1.LGN_DATE,'YYYY-MM-DD'),'YYYYMMDD') > V_SYSDAT_3M
     GROUP BY T2.ECIF_NO;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：客户渠道使用-非动账口径-手机银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：客户渠道使用-非动账口径-网上银行
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：客户渠道使用-非动账口径-网上银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                          AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CIP_HOSTNO                                   AS CUST_ID              , -- 客户编号
         '1'                                             AS STATIS_TYP           , -- 统计口径
         '2'                                             AS CHNL_CATE            , -- 渠道种类
         '网上银行'                                          AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T2.PLF_LOGINDATE, 1, 10)) AS USE_CNT               -- 使用次数
    FROM SEBS_PB_CSTINF_PRO T1 -- 个人注册客户网银信息表
    LEFT JOIN SEBS_PB_LOGINLOG_FLOW T2 -- 个人网银登录信息交易表
      ON T1.CIP_CSTNO=T2.PLF_CSTNO
   WHERE T2.PLF_LOGINDATE > V_SYSDAT_3M
     GROUP BY T1.CIP_HOSTNO;

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：客户渠道使用-非动账口径-网上银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：客户渠道使用-非动账口径-电话银行
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 第4段业务逻辑：客户渠道使用-非动账口径-电话银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  WITH TEL_NUM AS (
    SELECT ANI, COUNT(DISTINCT(TO_CHAR(DATATIMESTAMP,'YYYYMMDD'))) AS TEL_NU
    FROM DHYH_T_BASELOG_AGENT_SESSION_INFO
    WHERE REGEXP_LIKE(ANI, '^1[3-9][0-9]{9}$')
      AND CHANNELTYPE = 'voice'
      AND TO_CHAR(DATATIMESTAMP,'YYYYMMDD') > V_SYSDAT_3M
    GROUP BY ANI
  )
  SELECT
         '9999'      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.CUST_ID  AS CUST_ID              , -- 客户编号
         '1'         AS STATIS_TYP           , -- 统计口径
         '3'         AS CHNL_CATE            , -- 渠道种类
         '电话银行'      AS CHNL_NAME            , -- 渠道名称
         T1.TEL_NU   AS USE_CNT               -- 使用次数
    FROM TEL_NUM T1 -- 来电手机号
    LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
      ON T1.ANI = T2.PHONE_NO
   WHERE 1=1;

  -- 提交第4段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：客户渠道使用-非动账口径-电话银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5 -- 第5段处理开始：客户渠道使用-非动账口径-微信银行
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  -- 第5段业务逻辑：客户渠道使用-非动账口径-微信银行
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T2.ECIF_NO                                  AS CUST_ID              , -- 客户编号
         '1'                                         AS STATIS_TYP           , -- 统计口径
         '4'                                         AS CHNL_CATE            , -- 渠道种类
         '微信银行'                                      AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T1.LGN_DATE, 1, 10))  AS USE_CNT               -- 使用次数
    FROM MBK_CUST_LOG_WECHAT_LOGIN T1 -- 登录日志
    LEFT JOIN MBK_CUST_DETAIL_INFO T2 -- 客户详细信息
      ON T1.CUST_NO = T1.CUST_NO
   WHERE T1.LGN_STATUS='1' and TO_CHAR(T1.LGN_DATE,'YYYYMMDD') > V_SYSDAT_3M
     GROUP BY T2.EICF_NO;

  -- 提交第5段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第5段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段业务逻辑处理完成：客户渠道使用-非动账口径-微信银行';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第5段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.6 -- 第6段处理开始：客户渠道使用-非动账口径-智慧厅堂
  --***************************************
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  -- 第6段业务逻辑：客户渠道使用-非动账口径-智慧厅堂
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_NO                  AS CUST_ID              , -- 客户编号
         '1'                         AS STATIS_TYP           , -- 统计口径
         '6'                         AS CHNL_CATE            , -- 渠道种类
         '智能终端'                      AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT TRANS_DATE)  AS USE_CNT               -- 使用次数
    FROM ZHTT_T_BUSI_FLOW_RECORD T1 -- 待确认：来源表中文名缺失
   WHERE TTRANS_AMT_FLAGE = '0' AND CUST_NO IS NOT NULL AND RANS_DATE >= V_SYSDAT_3M --动账类交易标志0-否,1-是
     GROUP BY CUST_NO;

  -- 提交第6段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第6段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6段业务逻辑处理完成：客户渠道使用-非动账口径-智慧厅堂';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第6段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.7 -- 第7段处理开始：客户渠道使用-非动账口径-柜面
  --***************************************
  V_NO_ID := '7';
  V_BGN_DATE := SYSDATE;

  -- 第7段业务逻辑：客户渠道使用-非动账口径-柜面
  INSERT INTO TMP1_DWS_CUST_CHNL_USE (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         '9999'                                      AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.KEHUHAOO                                 AS CUST_ID              , -- 客户编号
         '1'                                         AS STATIS_TYP           , -- 统计口径
         '7'                                         AS CHNL_CATE            , -- 渠道种类
         '柜面'                                        AS CHNL_NAME            , -- 渠道名称
         COUNT(DISTINCT SUBSTR(T2.XIUGRIQI, 1, 10))  AS USE_CNT               -- 使用次数
    FROM CBS_KDPA_ZHXINX T1 -- 负债账户信息表
    LEFT JOIN CBS_KDPA_XIUGMX T2 -- 账户修改明细登记簿
      ON T1.ZHANGHAO = T2.ZHANGHAO AND T1.KEHUZHAO = T2.KEHUZHAO
   WHERE T2.XIUGRIQI >'20260420'
     GROUP BY T1.KEHUHAOO;

  -- 提交第7段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第7段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第7段业务逻辑处理完成：客户渠道使用-非动账口径-柜面';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第7段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.8 -- 第8段处理开始：客户渠道使用-动账口径
  --***************************************
  V_NO_ID := '8';
  V_BGN_DATE := SYSDATE;

  -- 第8段业务逻辑：客户渠道使用-动账口径
  INSERT INTO DWS_CUST_CHNL_USE (
      PK_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         SEQ_DWS_CUST_CHNL_USE.NEXTVAL  AS PK_ID                , -- 主键
         T2.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID                     AS CUST_ID              , -- 客户编号
         T1.STATIS_TYP                  AS STATIS_TYP           , -- 统计口径
         T1.CHNL_CATE                   AS CHNL_CATE            , -- 渠道种类
         T1.CHNL_NAME                   AS CHNL_NAME            , -- 渠道名称
         T1.USE_CNT                     AS USE_CNT               -- 使用次数
    FROM TMP_DWS_CUST_CHNL_USE T1 -- 客户渠道使用表_临时表动账口径
    LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
      ON T1.CUST_NO = T2.CUST_NO
   WHERE 1=1;

  -- 提交第8段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第8段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第8段业务逻辑处理完成：客户渠道使用-动账口径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第8段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.9 -- 第9段处理开始：客户渠道使用-动账口径、客户渠道使用-非动账口径 合并为客户渠道使用-全口径
  --***************************************
  V_NO_ID := '9';
  V_BGN_DATE := SYSDATE;

  -- 第9段业务逻辑：客户渠道使用-动账口径、客户渠道使用-非动账口径 合并为客户渠道使用-全口径
  INSERT INTO DWS_CUST_CHNL_USE (
      PK_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      STATIS_TYP,
      CHNL_CATE,
      CHNL_NAME,
      USE_CNT
  )
  SELECT
         NULL                    AS PK_ID                 , -- 主键
         T.PERSN_LEGAL_BK_CODE   AS PERSN_LEGAL_BK_CODE   , -- 法人行号
         T.CUST_ID               AS CUST_ID               , -- 客户编号
         T.STATIS_TYP            AS STATIS_TYP            , -- 统计口径
         T.CHNL_CATE             AS CHNL_CATE             , -- 渠道种类
         T.CHNL_NAME             AS CHNL_NAME             , -- 渠道名称
         SUM(T.USE_CNT)          AS USE_CNT                -- 使用次数
    FROM (
          -- 客户渠道使用-动账口径
          SELECT
                 SEQ_DWS_CUST_CHNL_USE.NEXTVAL  AS PK_ID                , -- 主键
                 T1.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID                     AS CUST_ID              , -- 客户编号
                 '1'                            AS STATIS_TYP           , -- 统计口径
                 T1.CHNL_CATE                   AS CHNL_CATE            , -- 渠道种类
                 T1.CHNL_NAME                   AS CHNL_NAME            , -- 渠道名称
                 T1.USE_CNT                     AS USE_CNT               -- 使用次数
            FROM TMP_DWS_CUST_CHNL_USE T1 -- 客户渠道使用表_临时表动账口径
           WHERE 1=1
          UNION
          -- 客户渠道使用-非动账口径
          SELECT
                 SEQ_DWS_CUST_CHNL_USE.NEXTVAL  AS PK_ID                , -- 主键
                 T1.PERSN_LEGAL_BK_CODE         AS PERSN_LEGAL_BK_CODE  , -- 法人行号
                 T1.CUST_ID                     AS CUST_ID              , -- 客户编号
                 '1'                            AS STATIS_TYP           , -- 统计口径
                 T1.CHNL_CATE                   AS CHNL_CATE            , -- 渠道种类
                 T1.CHNL_NAME                   AS CHNL_NAME            , -- 渠道名称
                 T1.USE_CNT                     AS USE_CNT               -- 使用次数
            FROM TMP1_DWS_CUST_CHNL_USE T1 -- 客户渠道使用表_临时表非动账口径
           WHERE 1=1
         ) T
   GROUP BY T.PERSN_LEGAL_BK_CODE, T.CUST_ID, T.STATIS_TYP, T.CHNL_CATE, T.CHNL_NAME;

  -- 提交第9段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第9段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第9段业务逻辑处理完成：客户渠道使用-动账口径、客户渠道使用-非动账口径 合并为客户渠道使用-全口径';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第9段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_dormant_accout(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_dormant_accout(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 睡眠户
  -- 作业编号: PRC_DWS_CUST_DORMANT_ACCOUT
  -- 处理周期: 每日
  -- 来源表: CBS_KDPA_ZHXINX DWS_CUST_ASSE_LIAB
  -- 目标表: DWD_CUST_DORMANT_ACCOUT
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '睡眠户信息加工';
  V_PRC_NAME    VARCHAR(32)  := 'PRC_DWS_CUST_DORMANT_ACCOUT';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LASTYEAR	VARCHAR(8);
BEGIN
   
  ------------------------------------------------------------------
  -- 1. 睡眠户客户统计
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  V_LASTYEAR := TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -12),'YYYYMMDD');
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_CUST_DORMANT_ACCOUT';

  INSERT INTO DWS_CUST_DORMANT_ACCOUT (
  	  PERSN_LEGAL_BK_CODE, -- 法人行号
      DATA_DATE, -- 数据日期
      CUST_ID  -- 客户编号
  )
  SELECT B.PERSN_LEGAL_BK_CODE, --法人行号
  	  V_SYSDAT DATA_DATE, -- 数据日期
  	  B.CUST_ID -- 客户编号
      FROM (SELECT KEHUHAOO AS CUST_ID,MIN(YEGXRIQI) AS YEGXRIQI,sum(ZHHUYUEE) ZHHUYUEE 
      			FROM  CBS_KDPA_ZHXINX WHERE KEHUHAOO LIKE '1%' GROUP BY KEHUHAOO) A,DWS_CUST_ASSE_LIAB B 
     WHERE A.CUST_ID=B.CUST_ID AND A.YEGXRIQI <= V_LASTYEAR AND B.BAL_TYPE='1'
       AND B.AUM_BAL <=100 AND B.LOAN_BAL<=0;
  COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步睡眠户信息装载完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_indv_poten(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_indv_poten(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 零售潜在客户信息表
  -- 存储过程编号：PRC_DWS_CUST_INDV_POTEN
  -- 处理周期：日
  -- 过程描述：根据 DWS 数据模型映射生成
  -- 来源表：DWD_ACCT_DEPO(存款账户信息表)；DWD_ACCT_FIN(理财账户信息表)；DWD_ACCT_INSUR(保险账户信息表)；DWD_CUST_INDIV_MNER(家庭成员信息表)；DWD_CUST_INDV_INFO(客户基本信息表)；DWS_CUST_INDV_POTEN(零售潜在客户信息表)；TMP1_DWS_CUST_INDV_POTEN(零售潜在客户信息表_临时表1)；TMP_DWS_CUST_INDV_POTEN(零售潜在客户信息表_临时表)
  -- 目标表：DWS_CUST_INDV_POTEN；TMP1_DWS_CUST_INDV_POTEN；TMP_DWS_CUST_INDV_POTEN
  -- author :
  -- date   ： 2026-07-31
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '零售潜在客户信息表';
  V_PRC_NAME             VARCHAR(32)  := 'PRC_DWS_CUST_INDV_POTEN';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  --OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 将输入的批处理日期转换为标准格式,便于后续日志和区间处理
  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  -- 预留时间区间参数,方便后续扩展按天/按月增量处理
  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 每次跑批前按模块处理要求清理目标数据,保证重复跑批结果一致
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP1_DWS_CUST_INDV_POTEN';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_INDV_POTEN';

  --***************************************
  -- 2.1 -- 第1段处理开始：潜客转化存款客户
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  -- 第1段业务逻辑：潜客转化存款客户
  INSERT INTO TMP1_DWS_CUST_INDV_POTEN (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CERT_ID,
      PHONE_NO,
      POT_CNVRT_PRDKT,
      POT_CNVRT_ORG,
      INF_KLKT_DATE
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS CUST_ID              , -- 客户编号
         T2.CUST_NAME            AS CUST_NAME            , -- 客户名称
         T2.CERT_ID              AS CERT_ID              , -- 证件号码
         T2.PHONE_NO             AS PHONE_NO             , -- 手机号码
         T1.PRDKT_ID             AS POT_CNVRT_PRDKT      , -- 潜客转化产品
         T1.OPEN_ACCT_ORG        AS POT_CNVRT_ORG        , -- 潜客转化机构
         T1.OPEN_DATE            AS INF_KLKT_DATE         -- 潜客转化日期
    FROM DWD_ACCT_DEPO T1 -- 存款账户信息表
    LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
      ON T1.CUST_ID = T2.CUST_ID
   WHERE T1.OPEN_DATE = V_SYSDAT AND T2.OPEN_DATE = V_SYSDAT AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE;

  -- 提交第1段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：潜客转化存款客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：潜客转化理财客户
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  -- 第2段业务逻辑：潜客转化理财客户
  INSERT INTO TMP1_DWS_CUST_INDV_POTEN (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CERT_ID,
      PHONE_NO,
      POT_CNVRT_PRDKT,
      POT_CNVRT_ORG,
      INF_KLKT_DATE
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS CUST_ID              , -- 客户编号
         T2.CUST_NAME            AS CUST_NAME            , -- 客户名称
         T2.CERT_ID              AS CERT_ID              , -- 证件号码
         T2.PHONE_NO             AS PHONE_NO             , -- 手机号码
         T1.PRDKT_ID             AS POT_CNVRT_PRDKT      , -- 潜客转化产品
         T1.OPRT_ORG             AS POT_CNVRT_ORG        , -- 潜客转化机构
         T1.ISSU_DATE            AS INF_KLKT_DATE         -- 潜客转化日期
    FROM DWD_ACCT_FIN T1 -- 理财账户信息表
    LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
      ON T1.CUST_ID = T2.CUST_ID
   WHERE T1.ISSU_DATE = V_SYSDAT AND T2.OPEN_DATE = V_SYSDAT AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE;

  -- 提交第2段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第2段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：潜客转化理财客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第2段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：潜客转化保险客户
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  -- 第3段业务逻辑：潜客转化保险客户
  INSERT INTO TMP1_DWS_CUST_INDV_POTEN (
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      CERT_ID,
      PHONE_NO,
      POT_CNVRT_PRDKT,
      POT_CNVRT_ORG,
      INF_KLKT_DATE
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.CUST_ID              AS CUST_ID              , -- 客户编号
         T2.CUST_NAME            AS CUST_NAME            , -- 客户名称
         T2.CERT_ID              AS CERT_ID              , -- 证件号码
         T2.PHONE_NO             AS PHONE_NO             , -- 手机号码
         T1.PRDKT_ID            AS POT_CNVRT_PRDKT      , -- 潜客转化产品
         T1.TX_ORG               AS POT_CNVRT_ORG        , -- 潜客转化机构
         T1.TX_DATE              AS INF_KLKT_DATE         -- 潜客转化日期
    FROM DWD_ACCT_INSUR T1 -- 保险账户信息表
    LEFT JOIN DWD_CUST_INDV_INFO T2 -- 客户基本信息表
      ON T1.CUST_ID = T2.CUST_ID
   WHERE T1.TX_DATE = V_SYSDAT AND T2.OPEN_DATE = V_SYSDAT AND T1.PERSN_LEGAL_BK_CODE = T2.PERSN_LEGAL_BK_CODE;

  -- 提交第3段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第3段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：潜客转化保险客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第3段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：处理系统每日新增潜客数据
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  -- 第4段业务逻辑：处理系统每日新增潜客数据
  INSERT INTO TMP_DWS_CUST_INDV_POTEN (
      PERSN_LEGAL_BK_CODE,
      POTEN_CUST_ID,
      POTEN_CUST_NAME,
      POTEN_TYP,
      GENDER,
      CERT_TYP,
      CERT_ID,
      TEL_NO,
      INTENT_DSC,
      DTL_ADDRS,
      CREATR,
      CREAT_TIME,
      POTEN_CUST_STATE,
      SRC_TYP,
      MKT_PERSN,
      MKT_ORG,
      SERV_ENTER,
      POST,
      MTH_INCOM,
      YR_INCOM,
      RMARK,
      INF_KLKT_DATE,
      UNIT_ADDRS,
      INTN_PRDKT,
      NO_BAT,
      CUST_ID,
      POT_CNVRT_PRDKT,
      POT_CNVRT_ORG,
      ALLO_DATE,
      REC_DATE,
      AGE
  )
  SELECT
         '9999'        AS PERSN_LEGAL_BK_CODE  , -- 法人行号
          SEQ_DWS_CUST_INDV_POTEN.NEXTVAL   AS POTEN_CUST_ID        , -- 潜在客户号(自增键)
         T1.MBER_NAME  AS POTEN_CUST_NAME      , -- 潜在客户名称
         '0'           AS POTEN_TYP            , -- 潜客类型
         T1.GEND       AS GENDER               , -- 性别
         T1.CERT_TYP   AS CERT_TYP             , -- 证件类型
         T1.CERT_ID    AS CERT_ID              , -- 证件号码
         T1.TEL_NO     AS TEL_NO               , -- 联系电话
         T1.REMARK     AS INTENT_DSC           , -- 备注说明
         ''            AS DTL_ADDRS            , -- 居住地址
         'admin'       AS CREATR               , -- 创建人
         V_SYSDAT      AS CREAT_TIME           , -- 创建时间
         '0'           AS POTEN_CUST_STATE     , -- 潜在客户状态
         '01'          AS SRC_TYP              , -- 来源类型
         ''            AS MKT_PERSN            , -- 客户经理
         '000000'      AS MKT_ORG              , -- 归属机构
         ''            AS SERV_ENTER           , -- 工作单位
         ''            AS POST                 , -- 职位
         ''            AS MTH_INCOM            , -- 月收入
         ''            AS YR_INCOM             , -- 年收入
         ''            AS RMARK                , -- 备注
         ''            AS INF_KLKT_DATE        , -- 潜客转化日期
         ''            AS UNIT_ADDRS           , -- 工作单位地址
         ''            AS INTN_PRDKT           , -- 意向产品
         ''            AS NO_BAT               , -- 批次号
         ''            AS CUST_ID              , -- 转化后核心客户号
         ''            AS POT_CNVRT_PRDKT      , -- 潜客转化产品
         ''            AS POT_CNVRT_ORG        , -- 潜客转化机构
         ''            AS ALLO_DATE            , -- 分配日期
         ''            AS REC_DATE             , -- 回收日期
         0             AS AGE                   -- 客户年龄
    FROM DWD_CUST_INDIV_MNER T1 -- 家庭成员信息表
   WHERE NOT EXISTS (SELECT 1 FROM DWS_CUST_INDV_POTEN T2 --零售潜在客户信息表
     WHERE T2.POTEN_CUST_NAME = T1.MBER_NAME
     AND (T1.CERT_ID = T2.CERT_ID OR T1.TEL_NO = T2.TEL_NO)
     ) AND (T1.CERT_ID IS NOT NULL OR T1.TEL_NO IS NOT NULL);

  -- 提交第4段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第4段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：处理系统每日新增潜客数据';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第4段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5 -- 第5段处理开始：每日新增潜客入结果表
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  -- 第5段业务逻辑：每日新增潜客入结果表
  INSERT INTO DWS_CUST_INDV_POTEN (
      PERSN_LEGAL_BK_CODE,
      POTEN_CUST_ID,
      POTEN_CUST_NAME,
      POTEN_TYP,
      GENDER,
      CERT_TYP,
      CERT_ID,
      TEL_NO,
      INTENT_DSC,
      DTL_ADDRS,
      CREATR,
      CREAT_TIME,
      POTEN_CUST_STATE,
      SRC_TYP,
      MKT_PERSN,
      MKT_ORG,
      SERV_ENTER,
      POST,
      MTH_INCOM,
      YR_INCOM,
      RMARK,
      INF_KLKT_DATE,
      UNIT_ADDRS,
      INTN_PRDKT,
      NO_BAT,
      CUST_ID,
      POT_CNVRT_PRDKT,
      POT_CNVRT_ORG,
      ALLO_DATE,
      REC_DATE,
      AGE
  )
  SELECT
         T1.PERSN_LEGAL_BK_CODE  AS PERSN_LEGAL_BK_CODE  , -- 法人行号
         T1.POTEN_CUST_ID        AS POTEN_CUST_ID        , -- 潜在客户号(自增键)
         T1.POTEN_CUST_NAME      AS POTEN_CUST_NAME      , -- 潜在客户名称
         T1.POTEN_TYP            AS POTEN_TYP            , -- 潜客类型
         T1.GENDER               AS GENDER               , -- 性别
         T1.CERT_TYP             AS CERT_TYP             , -- 证件类型
         T1.CERT_ID              AS CERT_ID              , -- 证件号码
         T1.TEL_NO               AS TEL_NO               , -- 联系电话
         T1.INTENT_DSC           AS INTENT_DSC           , -- 备注说明
         T1.DTL_ADDRS            AS DTL_ADDRS            , -- 居住地址
         T1.CREATR               AS CREATR               , -- 创建人
         T1.CREAT_TIME           AS CREAT_TIME           , -- 创建时间
         T1.POTEN_CUST_STATE     AS POTEN_CUST_STATE     , -- 潜在客户状态
         '01'                    AS SRC_TYP              , -- 来源类型
         T1.MKT_PERSN            AS MKT_PERSN            , -- 客户经理
         T1.MKT_ORG              AS MKT_ORG              , -- 归属机构
         T1.SERV_ENTER           AS SERV_ENTER           , -- 工作单位
         T1.POST                 AS POST                 , -- 职位
         T1.MTH_INCOM            AS MTH_INCOM            , -- 月收入
         T1.YR_INCOM             AS YR_INCOM             , -- 年收入
         T1.RMARK                AS RMARK                , -- 备注
         T1.INF_KLKT_DATE        AS INF_KLKT_DATE        , -- 潜客转化日期
         T1.UNIT_ADDRS           AS UNIT_ADDRS           , -- 工作单位地址
         T1.INTN_PRDKT           AS INTN_PRDKT           , -- 意向产品
         T1.NO_BAT               AS NO_BAT               , -- 批次号
         T1.CUST_ID              AS CUST_ID              , -- 转化后核心客户号
         T1.POT_CNVRT_PRDKT      AS POT_CNVRT_PRDKT      , -- 潜客转化产品
         T1.POT_CNVRT_ORG        AS POT_CNVRT_ORG        , -- 潜客转化机构
         T1.ALLO_DATE            AS ALLO_DATE            , -- 分配日期
         T1.ALLO_DATE            AS REC_DATE             , -- 回收日期
         T1.AGE                  AS AGE                   -- 客户年龄
    FROM TMP_DWS_CUST_INDV_POTEN T1 -- 零售潜在客户信息表_临时表
   WHERE NOT EXISTS (SELECT 1 FROM DWS_CUST_INDV_POTEN T2 --零售潜在客户信息表
     WHERE T2.POTEN_CUST_NAME = T1.POTEN_CUST_NAME
     AND (T1.CERT_ID = T2.CERT_ID OR T1.TEL_NO = T2.TEL_NO)
     );

  -- 提交第5段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第5段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段业务逻辑处理完成：每日新增潜客入结果表';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第5段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.6 -- 第6段处理开始：处理已转化客户
  --***************************************
  V_NO_ID := '6';
  V_BGN_DATE := SYSDATE;

  -- 第6段业务逻辑：处理已转化客户
  UPDATE DWS_CUST_INDV_POTEN T1
     SET (
         T1.POTEN_CUST_STATE        , -- 潜在客户状态
         T1.INF_KLKT_DATE           , -- 潜客转化日期
         T1.CUST_ID                 , -- 转化后核心客户号
         T1.POT_CNVRT_PRDKT         , -- 潜客转化产品
         T1.POT_CNVRT_ORG            -- 潜客转化机构
     ) = (
         SELECT
                '1'                         , -- 潜在客户状态
                T2.INF_KLKT_DATE            , -- 潜客转化日期
                T2.CUST_ID                  , -- 转化后核心客户号
                T2.POT_CNVRT_PRDKT          , -- 潜客转化产品
                T2.POT_CNVRT_ORG             -- 潜客转化机构
           FROM TMP1_DWS_CUST_INDV_POTEN T2
          WHERE T1.POTEN_CUST_NAME = T2.CUST_NAME AND (T1.CERT_ID = T2.CERT_ID OR T1.TEL_NO = T2.PHONE_NO) AND T1.POTEN_CUST_STATE = '0'
     )
   WHERE EXISTS (
         SELECT 1
           FROM TMP1_DWS_CUST_INDV_POTEN T2
          WHERE T1.POTEN_CUST_NAME = T2.CUST_NAME AND (T1.CERT_ID = T2.CERT_ID OR T1.TEL_NO = T2.PHONE_NO) AND T1.POTEN_CUST_STATE = '0'
     );

  -- 提交第6段结果,确保已完成数据不被后续异常影响
  COMMIT;

  -- 记录第6段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第6段业务逻辑处理完成：处理已转化客户';
  V_LOG_FLG := OUTCDE;

  -- 调用日志过程,记录第6段正常结束信息
  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_indx_data_aum(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_indx_data_aum(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户AUM指标数据处理
  -- 作业编号: PRC_DWS_CUST_INDX_DATA_AUM
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_ASSE_LIAB
  -- 目标表: DWS_CUST_INDX_DATA
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户AUM指标数据处理';
  V_PRC_NAME    VARCHAR(32)  := 'PRC_DWS_CUST_INDX_DATA_AUM';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YR 	VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YR := sys_fun_deal_date(V_SYSDAT,4);
  ------------------------------------------------------------------
  -- 1. 装载客户AUM指标信息
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

   EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_INDX_DATA_AUM';
   DELETE FROM DWS_CUST_INDX_DATA WHERE DATA_DATE=V_SYSDAT AND INDX_TYP='AUM';
   COMMIT;
   
   -- 客户AUM余额
	INSERT INTO TMP_DWS_CUST_INDX_DATA_AUM (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  ORG_ID, -- 客户所属机构
	  INDX_TYP, -- 指标类型
	  INDX_VALUE, -- 指标值
	  INDX_LAST_VAL, -- 指标上日值
	  INDX_MTH_VAL, --  指标上月值
	  INDX_QRT_VAL, -- 指标上季值
	  INDX_YR_VAL  --  指标上年值
  )
   SELECT a.PERSN_LEGAL_BK_CODE,-- 法人行号
   		V_SYSDAT, -- 数据日期
   		A.CUST_ID , -- 客户编号
   		A.ORG_ID , -- 归属机构
   		'AUM' , -- 指标类型
   		A.AUM_BAL , -- 指标值
   		NVL(B.INDX_VALUE,0) INDX_LAST_VAL, -- 指标上日值
	    NVL(C.INDX_VALUE,0) INDX_MTH_VAL, --  指标上月值
	    NVL(D.INDX_VALUE,0) INDX_QRT_VAL, -- 指标上季值
	    NVL(E.INDX_VALUE,0) INDX_YR_VAL  --  指标上年值
   FROM DWS_CUST_ASSE_LIAB a 
   LEFT JOIN DWS_CUST_INDX_DATA_HIS b 
   	ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE AND B.DATA_DATE=V_LAST_DAY AND B.INDX_TYP='AUM'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS c 
   	ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE AND C.DATA_DATE=V_LAST_MTH AND C.INDX_TYP='AUM'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS d 
   	ON A.CUST_ID=D.CUST_ID AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE AND D.DATA_DATE=V_LAST_QRT AND D.INDX_TYP='AUM'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS e 
   	ON A.CUST_ID=E.CUST_ID AND A.PERSN_LEGAL_BK_CODE=E.PERSN_LEGAL_BK_CODE AND E.DATA_DATE=V_LAST_YR AND E.INDX_TYP='AUM'
    WHERE A.DATA_DATE = V_SYSDAT AND A.BAL_TYPE ='1';
  COMMIT;
  
  -- 客户AUM余额
	INSERT INTO DWS_CUST_INDX_DATA (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  ORG_ID, -- 客户所属机构
	  INDX_TYP, -- 指标类型
	  INDX_VALUE, -- 指标值
	  INDX_LAST_VAL, -- 指标上日值
	  INDX_MTH_VAL, --  指标上月值
	  INDX_QRT_VAL, -- 指标上季值
	  INDX_YR_VAL  --  指标上年值
  )
   SELECT a.PERSN_LEGAL_BK_CODE,-- 法人行号
   		V_SYSDAT, -- 数据日期
   		A.CUST_ID , -- 客户编号
   		A.ORG_ID , -- 归属机构
   		A.INDX_TYP, -- 指标类型
   		A.INDX_VALUE , -- 指标值
   		A.INDX_LAST_VAL, -- 指标上日值
	    A.INDX_MTH_VAL, --  指标上月值
	    A.INDX_QRT_VAL, -- 指标上季值
	    A.INDX_YR_VAL  --  指标上年值
   FROM TMP_DWS_CUST_INDX_DATA_AUM a ;
   COMMIT;
   
   
   	-- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;
  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);    
  ------------------------------------------------------------------
  -- 2. 装载客户AUM月日均信息
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

   EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_INDX_DATA_AUM';
   DELETE FROM DWS_CUST_INDX_DATA WHERE DATA_DATE=V_SYSDAT AND INDX_TYP='AUM_MTH_AVG';
   COMMIT;
   
   -- 客户AUM月日均
	INSERT INTO TMP_DWS_CUST_INDX_DATA_AUM (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  ORG_ID, -- 客户所属机构
	  INDX_TYP, -- 指标类型
	  INDX_VALUE, -- 指标值
	  INDX_LAST_VAL, -- 指标上日值
	  INDX_MTH_VAL, --  指标上月值
	  INDX_QRT_VAL, -- 指标上季值
	  INDX_YR_VAL  --  指标上年值
  )
   SELECT a.PERSN_LEGAL_BK_CODE,-- 法人行号
   		V_SYSDAT, -- 数据日期
   		A.CUST_ID , -- 客户编号
   		A.ORG_ID , -- 归属机构
   		'AUM_MTH_AVG' INDX_TYP, -- 指标类型
   		A.AUM_BAL , -- 指标值
   		NVL(B.INDX_VALUE,0) INDX_LAST_VAL, -- 指标上日值
	    NVL(C.INDX_VALUE,0) INDX_MTH_VAL, --  指标上月值
	    NVL(D.INDX_VALUE,0) INDX_QRT_VAL, -- 指标上季值
	    NVL(E.INDX_VALUE,0) INDX_YR_VAL  --  指标上年值
   FROM DWS_CUST_ASSE_LIAB a 
   LEFT JOIN DWS_CUST_INDX_DATA_HIS b 
   	ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE AND B.DATA_DATE=V_LAST_DAY AND B.INDX_TYP='AUM_MTH_AVG'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS c 
   	ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE AND C.DATA_DATE=V_LAST_MTH AND C.INDX_TYP='AUM_MTH_AVG'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS d 
   	ON A.CUST_ID=D.CUST_ID AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE AND D.DATA_DATE=V_LAST_QRT AND D.INDX_TYP='AUM_MTH_AVG'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS e 
   	ON A.CUST_ID=E.CUST_ID AND A.PERSN_LEGAL_BK_CODE=E.PERSN_LEGAL_BK_CODE AND E.DATA_DATE=V_LAST_YR AND E.INDX_TYP='AUM_MTH_AVG'
    WHERE A.DATA_DATE = V_SYSDAT AND A.BAL_TYPE ='2';
  COMMIT;
  
  -- 客户AUM余额
	INSERT INTO DWS_CUST_INDX_DATA (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  ORG_ID, -- 客户所属机构
	  INDX_TYP, -- 指标类型
	  INDX_VALUE, -- 指标值
	  INDX_LAST_VAL, -- 指标上日值
	  INDX_MTH_VAL, --  指标上月值
	  INDX_QRT_VAL, -- 指标上季值
	  INDX_YR_VAL  --  指标上年值
  )
   SELECT a.PERSN_LEGAL_BK_CODE,-- 法人行号
   		V_SYSDAT, -- 数据日期
   		A.CUST_ID , -- 客户编号
   		A.ORG_ID , -- 归属机构
   		A.INDX_TYP, -- 指标类型
   		A.INDX_VALUE , -- 指标值
   		A.INDX_LAST_VAL, -- 指标上日值
