CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_indx_data_hold_prdkt(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户持有产品数据处理
  -- 作业编号: PRC_DWS_CUST_INDX_DATA_HOLD_PRDKT
  -- 处理周期: 每日
  -- 来源表: DWS_CUST_PRDKT_HOLD
  -- 目标表: DWS_CUST_INDX_DATA
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户持有产品数据处理';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_DWS_CUST_INDX_DATA_HOLD_PRDKT';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YR 	VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YR := sys_fun_deal_date(V_SYSDAT,4);
  ------------------------------------------------------------------
  -- 1. 持有产品处理 1-存款 2-理财 3-保险 4-贷款 5-借记卡 6-社保卡  7-手机银行 8-网银 9-电话银行
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

   EXECUTE IMMEDIATE 'TRUNCATE TABLE TMP_DWS_CUST_INDX_DATA_HOLD_PRDKT';
   DELETE FROM DWS_CUST_INDX_DATA WHERE DATA_DATE=V_SYSDAT AND INDX_TYP='PRDKT_HOLD';
   COMMIT;
   
	INSERT INTO TMP_DWS_CUST_INDX_DATA_HOLD_PRDKT (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  ORG_ID, -- 客户所属机构
	  INDX_TYP, -- 指标类型
	  INDX_VALUE, -- 指标值
	  INDX_LAST_VAL, -- 指标上日值
	  INDX_MTH_VAL, --  指标上月值
	  INDX_QRT_VAL, -- 指标上季值
	  INDX_YR_VAL  --  指标上年值
  )
   SELECT a.PERSN_LEGAL_BK_CODE,-- 法人行号
   		V_SYSDAT, -- 数据日期
   		A.CUST_ID , -- 客户编号
   		A.ORG_ID , -- 归属机构
   		'PRDKT_HOLD' , -- 指标类型
   		count(1) , -- 指标值
   		0 INDX_LAST_VAL, -- 指标上日值
	    0 INDX_MTH_VAL, --  指标上月值
	    0 INDX_QRT_VAL, -- 指标上季值
	    0 INDX_YR_VAL  --  指标上年值
	 FROM DWS_CUST_PRDKT_HOLD A 
	 GROUP BY A.PERSN_LEGAL_BK_CODE,A.CUST_ID,A.ORG_ID
   /*FROM (SELECT CUST_ID,ORG_ID,PERSN_LEGAL_BK_CODE,COUNT(1) NUM FROM  DWS_CUST_PRDKT_HOLD GROUP BY CUST_ID,ORG_ID,PERSN_LEGAL_BK_CODE ) a 
   LEFT JOIN DWS_CUST_INDX_DATA_HIS b 
   	ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE AND B.DATA_DATE=V_LAST_DAY AND B.INDX_TYP='CUST_LVL'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS c 
   	ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE AND C.DATA_DATE=V_LAST_MTH AND C.INDX_TYP='CUST_LVL'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS d 
   	ON A.CUST_ID=D.CUST_ID AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE AND D.DATA_DATE=V_LAST_QRT AND D.INDX_TYP='CUST_LVL'
   LEFT JOIN DWS_CUST_INDX_DATA_HIS e 
   	ON A.CUST_ID=E.CUST_ID AND A.PERSN_LEGAL_BK_CODE=E.PERSN_LEGAL_BK_CODE AND E.DATA_DATE=V_LAST_YR AND E.INDX_TYP='CUST_LVL'*/
    ;
  COMMIT;
  
  -- 客户等级
	INSERT INTO DWS_CUST_INDX_DATA (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  ORG_ID, -- 客户所属机构
	  INDX_TYP, -- 指标类型
	  INDX_VALUE, -- 指标值
