	  INDX_MTH_VAL, --  指标上月值
	  INDX_QRT_VAL, -- 指标上季值
	  INDX_YR_VAL  --  指标上年值
  )
   SELECT a.PERSN_LEGAL_BK_CODE,-- 法人行号
   		V_SYSDAT, -- 数据日期
   		A.CUST_ID , -- 客户编号
   		A.ORG_ID , -- 归属机构
   		A.INDX_TYP, -- 指标类型
   		A.INDX_VALUE , -- 指标值
   		A.INDX_LAST_VAL, -- 指标上日值
	    A.INDX_MTH_VAL, --  指标上月值
	    A.INDX_QRT_VAL, -- 指标上季值
	    A.INDX_YR_VAL  --  指标上年值
   FROM TMP_DWS_CUST_INDX_DATA_HOLD_PRDKT a ;
   COMMIT;
   
   
   	-- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;
  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);    
   
  
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
