    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_life_cycle_stage(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_life_cycle_stage(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 存储过程名称: 客户生命周期阶段计算
  -- 存储过程编号：PRC_DWS_CUST_LIFE_CYCLE_STAGE
  -- 处理周期：日
  -- 过程描述：根据客户开户日期及近三期月末客户等级,计算客户生命周期阶段
  -- 规则优先级：新客 > 流失 > 衰退 > 成熟 > 潜力
  -- 来源表：CUST_LVL_INFO 客户等级信息表
  -- 来源表：DWD_CUST_INDV_INFO 客户基本信息表
  -- 目标表：DWS_CUST_LIFE_CYCLE_STAGE 客户生命周期阶段结果表
  -- author :
  -- date   ： 2026-07-28
  -- 适配数据库：人大金仓 Oracle 兼容模式
  ------------------------------------------------------------------
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_PRC_DESC             VARCHAR(100) := '客户生命周期阶段计算';
  V_PRC_NAME             VARCHAR(64)  := 'PRC_DWS_CUST_LIFE_CYCLE_STAGE';
  V_SYSDAT2              VARCHAR(10);
  V_SQL                  VARCHAR(4000);
  V_LOG_MSG              VARCHAR(4000);
  V_START_DT             DATE;
  V_LOG_FLG              INTEGER;
  V_LOG_BUTTON           INTEGER := 1;
  V_NO_ID                VARCHAR(10);
  V_BGN_DATE             DATE;
  V_END_DATE             DATE;
  V_DURA_DATE            INTEGER;
  P_INTERVAL_START_DATE  VARCHAR(8);
  P_INTERVAL_END_DATE    VARCHAR(8);

  V_DATA_DT              DATE;       -- 跑批日期
  V_DATA_DT_STR          VARCHAR(8); -- 跑批日期YYYYMMDD
  V_LVL_M0_DT            DATE;       -- 本期等级月末日期
  V_LVL_M1_DT            DATE;       -- 上期等级月末日期
  V_LVL_M2_DT            DATE;       -- 上上期等级月末日期
  V_LVL_M0_DT_STR        VARCHAR(8); -- 本期等级日期YYYYMMDD
  V_LVL_M1_DT_STR        VARCHAR(8); -- 上期等级日期YYYYMMDD
  V_LVL_M2_DT_STR        VARCHAR(8); -- 上上期等级日期YYYYMMDD
BEGIN
  --***************************************
  -- 2. 业务逻辑区
  --***************************************
  -- 默认返回成功,异常时统一改为 -1
  OUTCDE := 0;

  -- 记录跑批开始时间,用于统计整个过程耗时
  V_START_DT := SYSDATE;

  -- 初始化跑批日期和等级月末日期
  V_DATA_DT     := TO_DATE(V_SYSDAT, 'yyyymmdd');
  V_DATA_DT_STR := TO_CHAR(V_DATA_DT, 'yyyymmdd');
  V_SYSDAT2     := TO_CHAR(V_DATA_DT, 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(V_DATA_DT - 30, 'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  -- 等级表月末跑：跑批日为月末取当月月末,否则取上月月末
  IF V_DATA_DT = LAST_DAY(V_DATA_DT) THEN
      V_LVL_M0_DT := V_DATA_DT;
  ELSE
      V_LVL_M0_DT := LAST_DAY(ADD_MONTHS(V_DATA_DT, -1));
  END IF;

  V_LVL_M1_DT     := LAST_DAY(ADD_MONTHS(V_LVL_M0_DT, -1));
  V_LVL_M2_DT     := LAST_DAY(ADD_MONTHS(V_LVL_M0_DT, -2));
  V_LVL_M0_DT_STR := TO_CHAR(V_LVL_M0_DT, 'yyyymmdd');
  V_LVL_M1_DT_STR := TO_CHAR(V_LVL_M1_DT, 'yyyymmdd');
  V_LVL_M2_DT_STR := TO_CHAR(V_LVL_M2_DT, 'yyyymmdd');

  -- 清空临时表,保证本次会话内结果不受上次执行影响
  DELETE FROM TMP_DWS_CUST_LIFE_CYCLE_STAGE;
  DELETE FROM TMP1_DWS_CUST_LIFE_CYCLE_STAGE;
  DELETE FROM TMP2_DWS_CUST_LIFE_CYCLE_STAGE;
  DELETE FROM TMP3_DWS_CUST_LIFE_CYCLE_STAGE;

  --***************************************
  -- 2.1 -- 第1段处理开始：加载客户基础信息
  --***************************************
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP_DWS_CUST_LIFE_CYCLE_STAGE (
      CUST_ID,
      PERSN_LEGAL_BK_CODE,
      CUST_NAME,
      OPEN_DATE,
      OPEN_DT
  )
  SELECT C.CUST_ID             AS CUST_ID,             -- 客户编号
         C.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         C.CUST_NAME           AS CUST_NAME,           -- 客户名称
         C.OPEN_DATE           AS OPEN_DATE,           -- 开户日期
         TO_DATE(C.OPEN_DATE, 'yyyymmdd')
                               AS OPEN_DT              -- 开户日期DATE格式
    FROM DWD_CUST_INDV_INFO C;                         -- 客户基本信息表

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成：加载客户基础信息';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.2 -- 第2段处理开始：加载近三期月末客户等级
  --***************************************
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP1_DWS_CUST_LIFE_CYCLE_STAGE (
      CUST_ID,
      PERSN_LEGAL_BK_CODE,
      DATA_DT,
      CUST_LVL
  )
  SELECT L.CUST_ID             AS CUST_ID,             -- 客户编号
         L.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         L.DATA_DATE             AS DATA_DT,             -- 数据日期
         TO_NUMBER(L.CUST_LVL) AS CUST_LVL             -- 客户等级
    FROM DWS_CUST_LVL_INFO L                           -- 客户等级信息表
   WHERE L.DATA_DATE IN (V_LVL_M0_DT_STR, V_LVL_M1_DT_STR, V_LVL_M2_DT_STR);

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2段业务逻辑处理完成：加载近三期月末客户等级';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.3 -- 第3段处理开始：透视近三期客户等级
  --***************************************
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP2_DWS_CUST_LIFE_CYCLE_STAGE (
      CUST_ID,
      PERSN_LEGAL_BK_CODE,
      LVL_M0,
      LVL_M1,
      LVL_M2
  )
  SELECT L.CUST_ID             AS CUST_ID,             -- 客户编号
         L.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE, -- 法人行号
         MAX(CASE WHEN L.DATA_DT = V_LVL_M0_DT_STR THEN L.CUST_LVL END)
                               AS LVL_M0,              -- 本期等级
         MAX(CASE WHEN L.DATA_DT = V_LVL_M1_DT_STR THEN L.CUST_LVL END)
                               AS LVL_M1,              -- 上期等级
         MAX(CASE WHEN L.DATA_DT = V_LVL_M2_DT_STR THEN L.CUST_LVL END)
                               AS LVL_M2               -- 上上期等级
    FROM TMP1_DWS_CUST_LIFE_CYCLE_STAGE L                              -- 近三期客户等级临时表
   GROUP BY L.CUST_ID, L.PERSN_LEGAL_BK_CODE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第3段业务逻辑处理完成：透视近三期客户等级';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.4 -- 第4段处理开始：计算生命周期阶段
  --***************************************
  V_NO_ID := '4';
  V_BGN_DATE := SYSDATE;

  INSERT INTO TMP3_DWS_CUST_LIFE_CYCLE_STAGE (
      DATA_DT,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      OPEN_DATE,
      CURR_CUST_LVL,
      LAST_MTH_CUST_LVL,
      LAST_2MTH_CUST_LVL,
      LIFE_CYCLE_STAGE,
      LIFE_CYCLE_STAGE_NAME,
      RULE_DESC
  )
  SELECT V_DATA_DT_STR         AS DATA_DT,               -- 数据日期
         C.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE,   -- 法人行号
         C.CUST_ID             AS CUST_ID,               -- 客户编号
         C.CUST_NAME           AS CUST_NAME,             -- 客户名称
         C.OPEN_DATE           AS OPEN_DATE,             -- 开户日期
         L.LVL_M0              AS CURR_CUST_LVL,         -- 本期客户等级
         L.LVL_M1              AS LAST_MTH_CUST_LVL,     -- 上期客户等级
         L.LVL_M2              AS LAST_2MTH_CUST_LVL,    -- 上上期客户等级
         CASE
           WHEN V_DATA_DT - C.OPEN_DT <= 180
             THEN '01'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND L.LVL_M0 = 0
            AND L.LVL_M1 = 0
            AND L.LVL_M2 = 0
             THEN '05'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND (L.LVL_M1 - L.LVL_M0 >= 2
              OR (L.LVL_M2 > L.LVL_M1 AND L.LVL_M1 > L.LVL_M0)
              OR (V_DATA_DT - C.OPEN_DT > 365 AND L.LVL_M0 = 0))
             THEN '04'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND L.LVL_M0 >= 4
             THEN '03'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND (L.LVL_M0 BETWEEN 1 AND 3
              OR (L.LVL_M2 < L.LVL_M1 AND L.LVL_M1 < L.LVL_M0))
             THEN '02'
           ELSE '00'
         END                   AS LIFE_CYCLE_STAGE,      -- 生命周期阶段代码
         CASE
           WHEN V_DATA_DT - C.OPEN_DT <= 180
             THEN '新客'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND L.LVL_M0 = 0
            AND L.LVL_M1 = 0
            AND L.LVL_M2 = 0
             THEN '流失'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND (L.LVL_M1 - L.LVL_M0 >= 2
              OR (L.LVL_M2 > L.LVL_M1 AND L.LVL_M1 > L.LVL_M0)
              OR (V_DATA_DT - C.OPEN_DT > 365 AND L.LVL_M0 = 0))
             THEN '衰退'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND L.LVL_M0 >= 4
             THEN '成熟'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND (L.LVL_M0 BETWEEN 1 AND 3
              OR (L.LVL_M2 < L.LVL_M1 AND L.LVL_M1 < L.LVL_M0))
             THEN '潜力'
           ELSE '未分类'
         END                   AS LIFE_CYCLE_STAGE_NAME, -- 生命周期阶段名称
         CASE
           WHEN V_DATA_DT - C.OPEN_DT <= 180
             THEN '开户天数小于等于180天'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND L.LVL_M0 = 0
            AND L.LVL_M1 = 0
            AND L.LVL_M2 = 0
             THEN '开户天数大于180天且连续3个月客户等级为0级'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND (L.LVL_M1 - L.LVL_M0 >= 2
              OR (L.LVL_M2 > L.LVL_M1 AND L.LVL_M1 > L.LVL_M0)
              OR (V_DATA_DT - C.OPEN_DT > 365 AND L.LVL_M0 = 0))
             THEN '单月等级下降大于等于2级，或连续2个月等级下降，或开户超过365天且本期等级为0级'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND L.LVL_M0 >= 4
             THEN '本期等级大于等于4级，且未命中流失/衰退'
           WHEN V_DATA_DT - C.OPEN_DT > 180
            AND (L.LVL_M0 BETWEEN 1 AND 3
              OR (L.LVL_M2 < L.LVL_M1 AND L.LVL_M1 < L.LVL_M0))
             THEN '本期等级为1-3级或连续2个月等级上升，且未命中更高优先级规则'
           ELSE '未命中生命周期阶段规则'
         END                   AS RULE_DESC              -- 命中规则说明
    FROM TMP_DWS_CUST_LIFE_CYCLE_STAGE C                                -- 客户基础信息临时表
    LEFT JOIN TMP2_DWS_CUST_LIFE_CYCLE_STAGE L                      -- 客户等级透视临时表
      ON C.CUST_ID = L.CUST_ID
     AND C.PERSN_LEGAL_BK_CODE = L.PERSN_LEGAL_BK_CODE;

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4段业务逻辑处理完成：计算生命周期阶段';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  --***************************************
  -- 2.5 -- 第5段处理开始：写入目标表
  --***************************************
  V_NO_ID := '5';
  V_BGN_DATE := SYSDATE;

  DELETE FROM DWS_CUST_LIFE_CYCLE_STAGE
   WHERE DATA_DT = V_DATA_DT_STR;

  INSERT INTO DWS_CUST_LIFE_CYCLE_STAGE (
      DATA_DT,
      PERSN_LEGAL_BK_CODE,
      CUST_ID,
      CUST_NAME,
      OPEN_DATE,
      CURR_CUST_LVL,
      LAST_MTH_CUST_LVL,
      LAST_2MTH_CUST_LVL,
      LIFE_CYCLE_STAGE,
      LIFE_CYCLE_STAGE_NAME,
      RULE_DESC,
      ETL_TIME
  )
  SELECT T.DATA_DT               AS DATA_DT,               -- 数据日期
         T.PERSN_LEGAL_BK_CODE   AS PERSN_LEGAL_BK_CODE,   -- 法人行号
         T.CUST_ID               AS CUST_ID,               -- 客户编号
         T.CUST_NAME             AS CUST_NAME,             -- 客户名称
         T.OPEN_DATE             AS OPEN_DATE,             -- 开户日期
         T.CURR_CUST_LVL         AS CURR_CUST_LVL,         -- 本期客户等级
         T.LAST_MTH_CUST_LVL     AS LAST_MTH_CUST_LVL,     -- 上期客户等级
         T.LAST_2MTH_CUST_LVL    AS LAST_2MTH_CUST_LVL,    -- 上上期客户等级
         T.LIFE_CYCLE_STAGE      AS LIFE_CYCLE_STAGE,      -- 生命周期阶段代码
         T.LIFE_CYCLE_STAGE_NAME AS LIFE_CYCLE_STAGE_NAME, -- 生命周期阶段名称
         T.RULE_DESC             AS RULE_DESC,             -- 命中规则说明
         SYSDATE                 AS ETL_TIME               -- 加工时间
    FROM TMP3_DWS_CUST_LIFE_CYCLE_STAGE T;                            -- 客户生命周期阶段规则结果临时表

  COMMIT;

  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第5段业务逻辑处理完成：写入客户生命周期阶段目标表';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS(
      V_SYSDAT,
      V_PRC_NAME,
      V_PRC_DESC,
      V_NO_ID,
      V_BGN_DATE,
      V_END_DATE,
      V_DURA_DATE,
      V_LOG_MSG,
      V_LOG_FLG,
      V_LOG_BUTTON
  );

  -- ***************************************
  -- 3. 异常处理区(捕获错误码并记录详细日志)
  -- ***************************************
EXCEPTION
  WHEN OTHERS THEN
    -- 异常时先回滚当前未提交数据,避免留下半成品
    OUTCDE := -1;
    ROLLBACK;

    -- 记录异常发生后的结束时间和耗时
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;

    -- 用 Oracle 标准错误信息写入日志,保留前 1000 个字符
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    -- 异常信息也走同一个日志过程,保证审计链路一致
    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );

    -- 继续抛出异常,交给上层调度器感知失败
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_lvl_info(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_lvl_info(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户等级信息处理
  -- 作业编号: PRC_DWD_CUST_LVL_INFO
  -- 处理周期: 每日
  -- 来源表: DWD_CUST_ASSE_LIAB
  -- 目标表: DWD_CUST_LVL_INFO
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户等级信息加工';
  V_PRC_NAME    VARCHAR(32)  := 'PRC_DWS_CUST_LVL_INFO';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_MBGIN_DATE	VARCHAR(8);
  V_MEND_DATE	VARCHAR(8);
  V_LMTH_DATE	VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_MBGIN_DATE := crmdm.sys_fun_deal_date(V_SYSDAT,'9');
  V_MEND_DATE := crmdm.sys_fun_deal_date(V_SYSDAT,'10');
  V_LMTH_DATE := crmdm.sys_fun_deal_date(V_SYSDAT,'2');
  
	
  ------------------------------------------------------------------
  -- 1. 装载客户等级信息
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

   EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_CUST_LVL_INFO';
   
   -- 本月开户的客户等级为11-未评级
   INSERT INTO DWS_CUST_LVL_INFO (
  	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      CUST_LVL,   --客户等级
      ORG_ID,	-- 归属机构
      CUST_HRAKY, -- 客户权益等级
      CUST_NAME -- 客户名称
   )
  SELECT A.PERSN_LEGAL_BK_CODE,--法人行号
  		 V_SYSDAT, --数据日期
  		 A."CUST_ID" , --客户号
  		 '11' AS CUST_LVL,  --客户等级
  		 CASE WHEN C.ORG_ID IS NULL THEN A.OPEN_ORG ELSE C.ORG_ID END AS ORG_ID, -- 归属机构
  		 '8',
  		 A.CUST_NAME -- 客户名称
  FROM DWD_CUST_INDV_INFO A
  LEFT JOIN DWS_CUST_ASSE_LIAB C ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE AND C.DATA_DATE = V_SYSDAT AND C.BAL_TYPE = '2'
  WHERE A.OPEN_DATE >= V_MBGIN_DATE AND A.OPEN_DATE < V_MEND_DATE
  ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步当月新开户客户等级信息装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   -- 睡眠户客户等级为00
	INSERT INTO DWS_CUST_LVL_INFO (
  	  PERSN_LEGAL_BK_CODE, --法人行号
      DATA_DATE, --数据日期
      CUST_ID,   --客户号
      CUST_LVL,   --客户等级
      ORG_ID,	-- 归属机构
      CUST_HRAKY, -- 客户权益等级
      CUST_NAME
   )
  SELECT A.PERSN_LEGAL_BK_CODE,--法人行号
  		 V_SYSDAT, --数据日期
  		 A."CUST_ID" , --客户号
  		 '00' AS CUST_LVL,  --客户等级
  		 CASE WHEN C.ORG_ID IS NULL THEN B.OPEN_ORG ELSE C.ORG_ID END AS ORG_ID, -- 归属机构
  		 '0' AS CUST_HRAKY, -- 客户权益等级
  		 B.CUST_NAME      -- 客户名称
  FROM DWS_CUST_DORMANT_ACCOUT A
  LEFT JOIN DWD_CUST_INDV_INFO B ON A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE
  LEFT JOIN DWS_CUST_ASSE_LIAB C ON A.CUST_ID=C.CUST_ID AND A.PERSN_LEGAL_BK_CODE=C.PERSN_LEGAL_BK_CODE AND C.DATA_DATE = V_SYSDAT AND C.BAL_TYPE = '2'
  WHERE NOT EXISTS (SELECT 1 FROM DWS_CUST_LVL_INFO D WHERE A.CUST_ID=D.CUST_ID AND A.PERSN_LEGAL_BK_CODE=D.PERSN_LEGAL_BK_CODE)
  ;
   COMMIT;
   OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步睡眠户客户等级信息装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
  V_NO_ID := '3';
  V_BGN_DATE := SYSDATE;
   -- 非月末取上月末客户等级
   IF V_CURR_DATE <> LAST_DAY(V_CURR_DATE) THEN
      INSERT INTO DWS_CUST_LVL_INFO (
	  	  PERSN_LEGAL_BK_CODE, -- 法人行号
	      DATA_DATE,  -- 数据日期
	      CUST_ID,  -- 客户编号
	      CUST_LVL,  --客户等级
	      ORG_ID,  --归属机构
	      CUST_HRAKY, -- 客户权益等级
	      CUST_NAME  -- 客户名称
	  )
	  SELECT 
	  	  PERSN_LEGAL_BK_CODE, -- 法人行号
	      DATA_DATE,  -- 数据日期
	      CUST_ID,  -- 客户编号
	      CUST_LVL,  --客户等级
	      ORG_ID,  --归属机构
	      CUST_HRAKY, -- 客户权益等级
	      CUST_NAME -- 客户名称
	  FROM DWS_CUST_LVL_INFO_HIS A
	  WHERE A.DATA_DATE = V_LMTH_DATE
	  	AND NOT EXISTS (SELECT 1 FROM DWS_CUST_LVL_INFO B WHERE A.CUST_ID=B.CUST_ID AND A.PERSN_LEGAL_BK_CODE=B.PERSN_LEGAL_BK_CODE)
	  ;
	  COMMIT;
	  
   ELSE
	  INSERT INTO DWS_CUST_LVL_INFO (
	  	  PERSN_LEGAL_BK_CODE, -- 法人行号
	      DATA_DATE,  -- 数据日期
	      CUST_ID,  -- 客户编号
	      CUST_LVL,  --客户等级
	      ORG_ID,  --归属机构
	      CUST_HRAKY, -- 客户权益等级
	      CUST_NAME -- 客户名称
	  )
	  SELECT
	      A.PERSN_LEGAL_BK_CODE,
	      V_SYSDAT AS DATA_DT,
	      A.CUST_ID,
	      m.CUST_LVL,
	      CASE WHEN T.ORG_ID IS NULL THEN trim(A.OPEN_ORG) ELSE T.ORG_ID END ORG_ID,
	      m.CUST_HRAKY,
	      A.CUST_NAME 
	  FROM DWD_CUST_INDV_INFO A 
	  LEFT JOIN DWS_CUST_ASSE_LIAB t ON A.CUST_ID=T.CUST_ID AND A.PERSN_LEGAL_BK_CODE=T.PERSN_LEGAL_BK_CODE
	  	AND t.DATA_DATE = V_SYSDAT
	    AND t.BAL_TYPE = '2'
	   INNER JOIN DWD_CUST_LVL_MAPPING m
		    ON m.PERSN_LEGAL_BK_CODE = '9999'
		   AND NVL(t.AUM_BAL, 0) >= NVL(m.MIN_BAL, 0)
		   AND NVL(t.AUM_BAL, 0) < NVL(m.MAX_BAL, 999999999999)
	    WHERE  NOT EXISTS (SELECT 1 FROM DWS_CUST_LVL_INFO T1 WHERE A.CUST_ID=T1.CUST_ID AND A.PERSN_LEGAL_BK_CODE=T1.PERSN_LEGAL_BK_CODE);
	
	  COMMIT;
	  OUTCDE := 0;
	  V_END_DATE := SYSDATE;
	  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
	  V_LOG_MSG := '第3步客户等级信息装载完成';
	  V_LOG_FLG := OUTCDE;
	  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	  COMMIT;
	  
	  -- 保存月末数据到历史表中
	  V_NO_ID := '4';
  	  V_BGN_DATE := SYSDATE;
	  DELETE FROM DWS_CUST_LVL_INFO_HIS WHERE DATA_DATE = V_SYSDAT;
	  INSERT INTO DWS_CUST_LVL_INFO_HIS (
	  	  PERSN_LEGAL_BK_CODE, -- 法人行号
	      DATA_DATE,  -- 数据日期
	      CUST_ID,  -- 客户编号
	      CUST_LVL,  --客户等级
	      ORG_ID , --归属机构
	      CUST_HRAKY, -- 客户权益等级
	      CUST_NAME -- 客户名称
	  )
	  SELECT 
	  	  PERSN_LEGAL_BK_CODE, -- 法人行号
	      DATA_DATE,  -- 数据日期
	      CUST_ID,  -- 客户编号
	      CUST_LVL,  --客户等级
	      ORG_ID , --归属机构
	      CUST_HRAKY, -- 客户权益等级
	      CUST_NAME -- 客户名称
	  FROM DWS_CUST_LVL_INFO;
	  
   END IF;
   
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第4步客户等级信息装载完成';
  V_LOG_FLG := OUTCDE;

  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
	COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_cust_prdkt_hold(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_cust_prdkt_hold(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  -- 作业名称: 客户持有产品数据处理
  -- 作业编号: PRC_DWS_CUST_PRDKT_HOLD
  -- 处理周期: 每日
  -- 来源表: DWS_CUST_LVL_INFO
  -- 目标表: DWS_CUST_PRDKT_HOLD
  -- 适配数据库: Kingbase/Oracle兼容模式
  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '客户持有产品数据处理';
  V_PRC_NAME    VARCHAR(32)  := 'PRC_DWS_CUST_PRDKT_HOLD';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_LAST_DAY	VARCHAR(8);
  V_LAST_MTH	VARCHAR(8);
  V_LAST_QRT	VARCHAR(8);
  V_LAST_YR 	VARCHAR(8);
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_LAST_DAY := sys_fun_deal_date(V_SYSDAT,1);
  V_LAST_MTH := sys_fun_deal_date(V_SYSDAT,2);
  V_LAST_QRT := sys_fun_deal_date(V_SYSDAT,3);
  V_LAST_YR := sys_fun_deal_date(V_SYSDAT,4);
  ------------------------------------------------------------------
  -- 1. 持有产品处理 1-存款 2-理财 3-保险 4-贷款 5-借记卡 6-社保卡  7-手机银行 8-网银 9-电话银行
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;

   EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_CUST_PRDKT_HOLD';
   
	INSERT INTO DWS_CUST_PRDKT_HOLD (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   select
   	A.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'1' PRDKT_BIG_CLS, -- 存款
   	A.ORG_ID  -- 归属机构
   FROM DWS_CUST_ASSE_LIAB a  
    WHERE A.BAL_TYPE='1' and A.DATA_DATE = V_SYSDAT and DEPO_BAL>0;
  COMMIT;
  
  INSERT INTO DWS_CUST_PRDKT_HOLD (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   select
   	A.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'2' PRDKT_BIG_CLS,  -- 理财
   	A.ORG_ID  -- 归属机构
   FROM DWS_CUST_ASSE_LIAB a  
    WHERE A.BAL_TYPE='1' and A.DATA_DATE = V_SYSDAT and FIN_BAL>0;
  COMMIT;
  
  INSERT INTO DWS_CUST_PRDKT_HOLD (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   select
   	A.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'3' PRDKT_BIG_CLS,  -- 保险
   	A.ORG_ID  -- 归属机构
   FROM DWS_CUST_ASSE_LIAB a  
    WHERE A.BAL_TYPE='1' and A.DATA_DATE = V_SYSDAT and INSUR_BAL>0;
  COMMIT;
  
  INSERT INTO DWS_CUST_PRDKT_HOLD (
  	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   select
   	A.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'4' PRDKT_BIG_CLS,  -- 贷款
   	A.ORG_ID  -- 归属机构
   FROM DWS_CUST_ASSE_LIAB a  
    WHERE A.BAL_TYPE='1' and A.DATA_DATE = V_SYSDAT and LOAN_BAL>0;
  COMMIT;
  
  INSERT INTO DWS_CUST_PRDKT_HOLD (
  	PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   SELECT distinct
   	A.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'5' PRDKT_BIG_CLS,  -- 贷款
   	A.ORG_ID  -- 归属机构
   FROM DWS_CUST_LVL_INFO a  , CBS_KCDA_PZJCXX b 
    WHERE A.CUST_ID=B.KEHUHAOO and A.PERSN_LEGAL_BK_CODE=(CASE WHEN B.FAKAJIGO LIKE '12%' THEN '1200' 
    	WHEN B.FAKAJIGO LIKE '15%' THEN '1500'
    	WHEN B.FAKAJIGO LIKE '18%' THEN '1800'
    	else '9999' END )
    	and B.KAXINGZH='0' and B.PZSYZTAI IN ('0','1','3','4','5','6','D','E','F','K','N','M','j') AND B.SBKBIAOZ != '1';
  COMMIT;
   
   INSERT INTO DWS_CUST_PRDKT_HOLD (
  	PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   SELECT distinct
   	A.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'6' PRDKT_BIG_CLS,  -- 社保卡
   	A.ORG_ID  -- 归属机构
   FROM DWS_CUST_LVL_INFO a  , CBS_KCDA_PZJCXX b 
    WHERE A.CUST_ID=B.KEHUHAOO and A.PERSN_LEGAL_BK_CODE=(CASE WHEN B.FAKAJIGO LIKE '12%' THEN '1200' 
    	WHEN B.FAKAJIGO LIKE '15%' THEN '1500'
    	WHEN B.FAKAJIGO LIKE '18%' THEN '1800'
    	else '9999' END )
    	and B.SBKBIAOZ = '1' AND B.KAXINGZH='0' and B.PZSYZTAI IN ('0','1','3','4','5','6','D','E','F','K','N','M','j');
  COMMIT;
   
   INSERT INTO DWS_CUST_PRDKT_HOLD (
  	PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   select
   	B.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'7' PRDKT_BIG_CLS,  -- 手机银行
   	B.ORG_ID  -- 归属机构
   FROM DWD_CUST_SIGN_CTRAKT a  ,DWS_CUST_LVL_INFO b
   WHERE a.CUST_ID=b.CUST_ID AND a.PERSN_LEGAL_BK_CODE=b.PERSN_LEGAL_BK_CODE AND a.ctrakt_typ='01';
  COMMIT;
  
  INSERT INTO DWS_CUST_PRDKT_HOLD (
  	PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   select
   	B.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'8' PRDKT_BIG_CLS,  --  网银 
   	B.ORG_ID  -- 归属机构
   FROM DWD_CUST_SIGN_CTRAKT a   ,DWS_CUST_LVL_INFO b
   where a.CUST_ID=b.CUST_ID AND a.PERSN_LEGAL_BK_CODE=b.PERSN_LEGAL_BK_CODE AND a.ctrakt_typ='02';
  COMMIT;
  
  INSERT INTO DWS_CUST_PRDKT_HOLD (
  	PERSN_LEGAL_BK_CODE , -- 法人行号
	  DATA_DATE , -- 数据日期
	  CUST_ID , -- 客户编号
	  PRDKT_BIG_CLS, -- 持有产品
	  ORG_ID -- 归属机构
  )
   select
   	B.PERSN_LEGAL_BK_CODE, -- 法人行号
   	V_SYSDAT DATA_DATE, -- 数据日期
   	A.CUST_ID, -- 客户编号
   	'9' PRDKT_BIG_CLS,  --  电话银行
   	B.ORG_ID  -- 归属机构
   FROM DWD_CUST_SIGN_CTRAKT a  ,DWS_CUST_LVL_INFO b 
   where a.CUST_ID=b.CUST_ID AND a.PERSN_LEGAL_BK_CODE=b.PERSN_LEGAL_BK_CODE AND a.ctrakt_typ='04';
  COMMIT;
   
   	-- 记录第1段结束时间和耗时
  OUTCDE      := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1段业务逻辑处理完成';
  V_LOG_FLG := OUTCDE;
  -- 调用日志过程,记录第1段正常结束信息
  SYS_PRC_STEP_LOGS(V_SYSDAT,V_PRC_NAME,V_PRC_DESC,V_NO_ID,V_BGN_DATE,V_END_DATE,V_DURA_DATE,V_LOG_MSG,V_LOG_FLG,V_LOG_BUTTON);    
   
  
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.prc_dws_rec_cnt(in varchar, out int4);

CREATE OR REPLACE PROCEDURE crmdm.prc_dws_rec_cnt(v_sysdat varchar, outcde OUT integer)
AS 
  ------------------------------------------------------------------
  /*-- 作业名称: 营销活动汇总
  -- 作业编号: PRC_DWS_REC_CNT
  -- 处理周期: 每日
  -- 来源表: CRM.MKT_REC_INFO
  -- 目标表: DWS_REC_CNT
  -- 适配数据库: Kingbase/Oracle兼容模式
  */

  ------------------------------------------------------------------
  V_PRC_DESC    VARCHAR(100) := '营销活动汇总';
  V_PRC_NAME    VARCHAR(64)  := 'PRC_DWS_REC_CNT';
  V_LOG_MSG     VARCHAR(4000);
  V_LOG_FLG     INTEGER;
  V_LOG_BUTTON  INTEGER := 1;
  V_NO_ID       VARCHAR(10);
  V_BGN_DATE    DATE;
  V_END_DATE    DATE;
  V_DURA_DATE   INTEGER;
  V_CURR_DATE   DATE;
  V_MTH_BEG		VARCHAR(20);
  V_QRT_BEG		VARCHAR(20);
  V_YEAR_BEG	VARCHAR(20);
  V_INDATE		VARCHAR(20);
  
BEGIN
  V_CURR_DATE := TO_DATE(V_SYSDAT, 'YYYYMMDD');
  V_MTH_BEG	  := sys_fun_deal_date(V_SYSDAT,9)||'00:00:00';
  V_QRT_BEG	  := sys_fun_deal_date(V_SYSDAT,11)||'00:00:00';
  V_YEAR_BEG  := sys_fun_deal_date(V_SYSDAT,13)||'00:00:00';
  V_INDATE	  := v_sysdat||'23:59:59';
  
  ------------------------------------------------------------------
  -- 1. 清空目标表数据
  ------------------------------------------------------------------
  V_NO_ID := '1';
  V_BGN_DATE := SYSDATE;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE DWS_REC_CNT';
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第1步清空目标表数据';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
  ------------------------------------------------------------------
  -- 2. 汇总营销活动量 
  ------------------------------------------------------------------
  V_NO_ID := '2';
  V_BGN_DATE := SYSDATE;
   INSERT INTO DWS_REC_CNT(
   	  CUST_ID , -- 客户编号
	  PERSN_LEGAL_BK_CODE , -- 法人行号
	  VISIT_CNT_M  , -- 面访月活动量
      VISIT_CNT_Q , -- 面访季活动量
	  VISIT_CNT_Y , -- 面访年活动量
	  CALL_CNT_M , -- 电访月活动量
	  CALL_CNT_Q , -- 电访季活动量
	  CALL_CNT_Y , -- 电访年活动量
	  QYWX_CNT_M , -- 企业微信月活动量
	  QYWX_CNT_Q ,-- 企业微信季活动量
	  QYWX_CNT_Y ,--企业微信年活动量
	  SMS_CNT_M ,--短信月活动量
	  SMS_CNT_Q ,--短信季活动量
	  SMS_CNT_Y --短信年活动量
   )
   SELECT 
   	  T.CUST_ID AS CUST_ID , -- 客户编号
	  T.PERSN_LEGAL_BK_CODE AS PERSN_LEGAL_BK_CODE , -- 法人行号
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_MTH_BEG AND V_INDATE AND T.MKT_TYP = '1' THEN T.CUST_ID ELSE '' END) AS VISIT_CNT_M  , -- 面访月活动量
      COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_QRT_BEG AND V_INDATE AND T.MKT_TYP = '1' THEN T.CUST_ID ELSE '' END) AS VISIT_CNT_Q , -- 面访季活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_YEAR_BEG AND V_INDATE AND T.MKT_TYP = '1' THEN T.CUST_ID ELSE '' END) AS VISIT_CNT_Y , -- 面访年活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_MTH_BEG AND V_INDATE AND T.MKT_TYP = '2' THEN T.CUST_ID ELSE '' END) AS CALL_CNT_M , -- 电访月活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_QRT_BEG AND V_INDATE AND T.MKT_TYP = '2' THEN T.CUST_ID ELSE '' END) AS CALL_CNT_Q , -- 电访季活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_YEAR_BEG AND V_INDATE AND T.MKT_TYP = '2' THEN T.CUST_ID ELSE '' END) AS CALL_CNT_Y , -- 电访年活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_MTH_BEG AND V_INDATE AND T.MKT_TYP = '3' THEN T.CUST_ID ELSE '' END) AS QYWX_CNT_M , -- 企业微信月活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_QRT_BEG AND V_INDATE AND T.MKT_TYP = '3' THEN T.CUST_ID ELSE '' END) AS QYWX_CNT_Q ,-- 企业微信季活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_YEAR_BEG AND V_INDATE AND T.MKT_TYP = '3' THEN T.CUST_ID ELSE '' END) AS QYWX_CNT_Y ,--企业微信年活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_MTH_BEG AND V_INDATE AND T.MKT_TYP = '4' THEN T.CUST_ID ELSE '' END) AS SMS_CNT_M ,--短信月活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_QRT_BEG AND V_INDATE AND T.MKT_TYP = '4' THEN T.CUST_ID ELSE '' END) AS SMS_CNT_Q ,--短信季活动量
	  COUNT(DISTINCT CASE WHEN T.MKT_TIME BETWEEN V_YEAR_BEG AND V_INDATE AND T.MKT_TYP = '4' THEN T.CUST_ID ELSE '' END) AS SMS_CNT_Y --短信年活动量
   FROM CRM.MKT_REC_INFO T 
  WHERE T.MKT_TIME BETWEEN V_YEAR_BEG AND V_INDATE
  GROUP BY T.CUST_ID,T.PERSN_LEGAL_BK_CODE
   ;
   COMMIT;
  OUTCDE := 0;
  V_END_DATE := SYSDATE;
  V_DURA_DATE := TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60);
  V_LOG_MSG := '第2步汇总营销活动量数据装载完成';
  V_LOG_FLG := OUTCDE;
  SYS_PRC_STEP_LOGS( V_SYSDAT, V_PRC_NAME, V_PRC_DESC, V_NO_ID, V_BGN_DATE, V_END_DATE, V_DURA_DATE, V_LOG_MSG, V_LOG_FLG,V_LOG_BUTTON);
  COMMIT;  
   
EXCEPTION
  WHEN OTHERS THEN
    OUTCDE := -1;
    ROLLBACK;
    V_END_DATE := SYSDATE;
    V_DURA_DATE := CASE
                     WHEN V_BGN_DATE IS NULL OR V_END_DATE IS NULL THEN NULL
                     ELSE TRUNC((V_END_DATE - V_BGN_DATE) * 24 * 60 * 60)
                   END;
    V_LOG_MSG := SUBSTR(SQLERRM, 1, 1000);
    V_LOG_FLG := OUTCDE;

    SYS_PRC_STEP_LOGS(
        V_SYSDAT,
        V_PRC_NAME,
        V_PRC_DESC,
        V_NO_ID,
        V_BGN_DATE,
        V_END_DATE,
        V_DURA_DATE,
        V_LOG_MSG,
        V_LOG_FLG,
        V_LOG_BUTTON
    );
    RAISE;
END
;

-- DROP PROCEDURE crmdm.sys_prc_step_logs(varchar, varchar, varchar, varchar, sys."date", sys."date", int4, varchar, int4, int4);

CREATE OR REPLACE PROCEDURE crmdm.sys_prc_step_logs(logdate varchar, prc_name varchar, prc_desc varchar, no_id varchar, bgn_date date, end_date date, dura_date integer, log_msg varchar, log_flg integer, log_button integer)
AS 
  V_LOGDATE  VARCHAR(8);
  V_PRC_NAME VARCHAR(80);
  V_PRC_DESC VARCHAR(300);
  V_NO_ID    VARCHAR(10);
  V_BGN_DATE DATE;
  V_END_DATE DATE;
  V_DURA_DATE INTEGER;
  V_LOG_MSG  VARCHAR(1000);
  V_LOG_FLG  INTEGER;
BEGIN
  -- 调试开关关闭时直接退出,不写日志
  IF NVL(log_button, 0) = 1 THEN
    -- 先规范日志日期格式,确保日志表中的日期字段统一
    IF logdate IS NOT NULL AND TRANSLATE(logdate, '1234567890', '0000000000') = '00000000' THEN
      V_LOGDATE := SUBSTR(logdate, 1, 8);
    ELSE
      -- 如果传入日期不合法,则回退到当前系统日期,避免日志过程自身报错
      V_LOGDATE := SUBSTR(TO_CHAR(SYSDATE, 'YYYYMMDD'), 1, 8);
    END IF;

    -- 截断长度,防止字符超长写入失败
    V_PRC_NAME := SUBSTR(prc_name, 1, 80);
    V_PRC_DESC := SUBSTR(prc_desc, 1, 300);
    V_NO_ID := SUBSTR(no_id, 1, 10);
    V_BGN_DATE := bgn_date;
    V_END_DATE := end_date;
    V_DURA_DATE := dura_date;
    V_LOG_MSG := SUBSTR(log_msg, 1, 1000);
    V_LOG_FLG := log_flg;

    -- 将步骤运行信息写入日志表
    INSERT INTO crmdm.prc_logs
      (logid, prc_name, prc_desc, logdate, no_id, bgn_date, end_date, dura_date, logmsg, log_flg)
    VALUES
      (crmdm.seq_crm_prc_log.nextval,
       V_PRC_NAME,
       V_PRC_DESC,
       V_LOGDATE,
       V_NO_ID,
       V_BGN_DATE,
       V_END_DATE,
       V_DURA_DATE,
       V_LOG_MSG,
       V_LOG_FLG);

    -- 日志独立提交,避免被主过程回滚影响
    COMMIT;
  END IF;
END
 


;